Object.assign(window.__LB,{"5000": ["病机", "脉数多遗，脊酸腰坠，乃督任失固之象。数脉主热，然此非实热，乃精亏不固、虚热内扰，故见遗泄；脊酸腰坠为督任不摄、肾精不充之征。原文谓“非通不能入脉，非涩无以填精”，说明需通涩兼施以固精填髓。色苍形瘦，阴血不足，不宜温补，恐助虚热。", ["数"]], "5001": ["病机", "脉数小，不饥，痰多，为阴虚伏热之候。数主热，小主虚，脉数小而小，乃阴液不足、虚热内伏，故不饥；虚热灼津为痰，故痰多。此非实火，乃阴虚为本、伏热为标，治当养阴清伏热，不可妄投温燥。", ["数", "小"]], "5002": ["病机", "阴液枯槁，阳气独升，故心热惊惕、倏热汗泄。阴亏不能涵阳，阳气升浮无制，虚热扰心则惊惕，阳升汗泄则倏热。议用复脉汤甘以缓热、充养五液，是甘润养阴以配阳，使阴阳相济，非苦寒直折。", []], "5003": ["预后", "脉大不敛，神迷呓语，为阴阳不相交合、欲脱之象。大脉本主实，然不敛则正气外散，阴不恋阳，阳不守阴，神失所依故神迷呓语。此非实热，乃阴阳离决之危候，故曰“欲脱”。救阴无速功，急宜镇固阴阳，冀其苏息。", ["大"]], "5004": ["病机", "男子脉大为劳，大而无力为内损少固之征。暑月阳不伏藏，初夏阳升血溢，皆因精气不固、阳失潜藏。脉大非实，乃虚劳精气外浮。治当填精固气，静摄绝欲，经年可复，说明劳损需缓图，非旦夕可效。", ["大"]], "5005": ["病机", "脉小濡而缓，主肾纳失司、肝风震突。小濡为虚，缓为湿为弱，脉不主流动，乃肾虚不纳、肝风内动，故见右痪、舌喑、足痱、头岑、面戴阳、呵欠微呃。病起耳后暴肿，兼温热客气；舌强难言，因肾脉萦舌本，筋脉不主流动。仿地黄饮子浊药清投。", ["小", "濡", "缓"]], "5006": ["病机", "脉象左部稍振，水亏木中风动，左牙痛。风从内旋，乃阳化风，春深地气上升，多升少降，下元不司收纳，虚证无疑。因目恙频用韭子烟熏，辛辣升腾助阳，反伤其阴。痱中八日声音渐振，为精气略宁、里窍有灵之顺境；若再辛以泄气，必致虚症蜂起。", []], "5007": ["病机", "平时六脉微弱，病时左手三部弦大而坚，知为肾脏阴伤、壮火食气之候。弦大而坚非实，乃阴亏阳亢、虚火内炽；人迎斜内向寸，三阳经满溢入阳维，有颠仆不仁之虞。右手浮缓、气口微滑，为痰沫壅膈，侵渍心主，故神识不清、语言错误。此肾气不能上通于心，心脏虚热生风，非燥药所宜。", ["微", "弱", "弦", "大"]], "5008": ["病机", "脉左大右濡，左大乃肝风震动之象，右濡为阳明脉空，气血不充。舌强肢软，属风中经络，病机为肝风内动、阳明络脉空虚，故治以缓肝熄风。", ["大", "濡", "空"]], "5009": ["病机", "阳脉大，阴脉涩，大则阳亢于上，涩则阴衰于下，此上盛下虚之候。浊阴上干清阳之位，阴阳否塞，故头痛累月。法用六味地黄汤加青铅，滋阴镇逆。", ["大", "涩"]], "5010": ["主病", "两脉俱沉且滑，沉主里，滑主痰，结合头痛经年、神气昏愦，此太阴阳明痰厥头痛。痰浊内阻，清阳不升，故用礞石滚痰丸、导痰汤荡涤痰浊。", ["沉", "滑"]], "5011": ["病机", "两脉浮虚，浮虽风象，内虚者脉亦浮而无力。症见周身掣痛、头不可转、手足不用，乃劳倦伤中，阳明不治，气血不荣，卫中空虚，营行不利，相搏而痛，非风寒湿痹。", ["浮", "虚"]], "5012": ["病机", "脉浮大而数，浮为风，大为热，数为火。发热口干，风性善行，火热得之愈增其势，伤于筋脉则纵缓不收，逆于肉理则攻肿为楚，此阴虚生内热、热胜则风生之候。", ["浮", "大", "数"]], "5013": ["病机", "左脉如刃，肝阴亏而风动；右脉缓涩，暑热湿蒸，阳明气衰。水谷气蒸，湿流肢末，遂成挛痹，兼泄泻食减，阳明脉中气衰极，故宜缓治。", ["弦", "缓", "涩"]], "5014": ["病机", "湿痹络脉不通，渗湿苦温小效，但汗出形寒、泄泻食减，阳气大衰，非湿甚生热可例治。当通阳宣行，以冀脉络流通，不可再投苦温渗湿。", []], "5015": ["预后", "高年液涸风动，酒湿气蒸，痿躄已成，脉数动疾，乃阳气不潜、阴液枯槁之象。温燥之补无益反害，仿虎潜丸滋阴潜阳，冀津液少存，非攻病也。", ["数", "动", "疾"]], "5016": ["病机", "原文言长夏湿痹，经脉流行气钝，兼下元脉络已虚，故痿弱不能步趋、脊膂酸楚、大便或结或溏。脉络已虚非具体脉象，乃言下元奇经空虚，湿阻气钝，肝肾失养。病机属湿痹兼下元虚损，主痿弱、腰脊酸楚、二便不调，治当宣通脉络，不可呆补。", []], "5017": ["主病", "脉左大而舌干白苔，肿痛流走四肢，此为行痹。左脉大主邪气盛于经络，风邪流走故肿痛无定处；喘急不食二十日，示邪势渐深，肺胃受累。脉大而症见流走肿痛，说明风邪痹阻脉络，主行痹，兼喘急不食之候。", ["大"]], "5018": ["病机", "脉微为阳气虚，涩为阴血伤，故下肢独冷、步趋无力、肉腠麻痹若虫行。高年真阳失蛰，胃阳失护，入夏身动加喘，生生意少。微涩并见，示阴阳气血俱损，主真阳不藏、胃阳失护之虚损，非攻病所宜，当大封大固以防暴脱。", ["微", "涩"]], "5019": ["病机", "脉形大虚无力，合神伤思虑则内脱、意伤忧愁则肢废，皆痿症也。大而无力为阳气虚浮不敛，思虑操持萦思耗伤神意，故病必迁延。此脉主虚劳痿症，说明阳气虽饵补而操劳未已，神意内伤，病机在虚而难复。", ["大", "虚"]], "5020": ["病机", "右脉涩、左脉微，饮食不能健运，嗳呕间或溏泄。右脉涩主脾运不健、阳气不布，左脉微主中阳衰微。中宫阳气欲寂，故纳运失职、嗳呕溏泄并见。此脉示脾胃阳衰、运化无权，主中焦虚寒之证，当用辛温以补之。", ["涩", "微"]], "5021": ["病机", "左脉弦大空虚，右脉虚软涩滞，能食不能运，便溏跗肿。弦大而空虚为劳伤阳气、肝脾失和；右虚软涩滞示脾运不健、湿滞内停。积劳伤阳，壮岁经年不复，当作虚症。此脉主脾肾阳虚、运化失职，故能食不运、便溏跗肿。", ["弦", "大", "虚", "涩"]], "5022": ["预后", "左脉大空虚，右脉细小虚涩，翻胃三月粒米不存，纳食少停即涌出，面白神瘁，便燥。大虚为阴血枯槁，细涩为阳气郁结、津血不充。脉症合参已成膈症，胃气将败，故曰勉拟补中纳下，示预后不良。此段重在判断膈症难治。", ["大", "虚", "细", "涩"]], "5023": ["病机", "肝脉弦急，肺脉独大，症见发热痰喘、胸满身痛、睪丸逆上痛不可忍。弦急为肝木化风生火，独大为肺受邪乘。风火旺于本位则为热为痛，乘于肺金则为痰为喘。此脉示肺肝受邪、风火合邪，主热痛痰喘之候，法宜滋达肺金兼疏肝木。", ["弦", "急", "大"]], "5024": ["病机", "脉浮虚而涩，浮为气虚，涩乃精伤，故断为阴阳两虚。原文谓“得之忧思劳郁，而伤中也”，又引“阳明为气血之海，主润宗筋”，因气血两伤，宗筋失润，故阴茎作痛。此脉主气精两亏、宗筋失养之病机，与痛甚而愦、形色不足相应。", ["浮", "虚", "涩"]], "5025": ["病机", "右脉虚涩无神，左关独弦，据脉论症乃肝脾积热。肝热则阴火不宁而阴血自动，故溺血茎中痛；脾热则湿气内壅而生气不伸，故嗳气、形色憔悴。虚涩示脾虚湿滞，独弦示肝热风动，此脉主肝脾积热、阴血妄行之病机。", ["虚", "涩", "弦"]], "5026": ["病机", "两脉虚涩，虚为气虚，涩为阴伤。原文谓“阴血暴亡，虚阳无偶，势必外越”，阴阳相离，气血两亏，故见下血不已、汗出躁烦、心悸恍惚。此脉主阴血暴亡、虚阳外越之病机，与气血两亏、神不内守诸症相应。", ["虚", "涩"]], "5027": ["病机", "脉弦数兼涩，弦则为风，数则为热，涩则气结。原文谓“肝脾之气，悒郁不宣，胸中阳和，抑而成火”，肝风自逆故左胁攻楚有块，风淫热胜故寒热如疟、便血不已。此脉主肝郁化火、风热伤血之病机。", ["弦", "数", "涩"]], "5028": ["病机", "左脉弦数，右脉空大，为厥阴肝木、太阴脾土二脏交伤之候。肝郁则风发，风挟势以贼脾，脾土受克则湿胜，湿停热瘀而发黄。弦数示肝风热亢，空大示脾土中虚，此脉主木亢土困、湿热瘀滞之病机，与面目悉黄、烦渴腹满相应。", ["弦", "数", "空", "大"]], "5029": ["预后", "脉交虚，八脉交虚，形寒内热，骨痛耳鸣，血液日耗，生气不充。原文谓“冬季不得复元，春深发泄司令，延为劳瘵矣”，此脉示产后下损、八脉空虚，阴阳气血俱亏，不能随冬藏春发之令恢复，故主预后不良，将成劳瘵。", ["虚"]], "5030": ["病机", "脉空隙，八脉空隙，产后阴伤，寒热疟几两月，白带淋漓，腹有动瘕。此脉示下元虚惫已极，奇经八脉空虚不固，冲任带脉失约，故带下淋漓、动瘕上逆。主病机为产后阴损、八脉空虚、下元不固，与寒热、带下、动瘕诸症相应。", ["空", "隙"]], "5031": ["病机", "脉数疾，上涌下垂，此血去阴伤，孤阳上冒，内风燔燎，肝魂不宁。数疾为阳亢热盛之象，上涌下垂示气血逆乱。面赤头痛、昼轻夜重，阴弱阳亢，上实下虚。此脉主产后阴伤阳亢、内风动越之病机，若不按法施治，必增瘛痉厥逆。", ["数", "疾"]], "5032": ["病机", "产后脉虚，舌白背寒凛、身痛干咳不饥，是血气两损、不肯复元之象。脉虚为正亏无力，血虚则脉道不充，气虚则鼓动乏力，故主蓐劳之虑。原文强调'莫以肺经咳嗽治，再伐胃气'，说明干咳由血损及肺、胃气亦弱所致，非外邪犯肺，当培养足三阴脏。", ["虚"]], "5033": ["病机", "产蓐百脉皆动，是血痹之症脉络未复而妄动。春寒客气乘隙袭入经络，始热继寒，邪渐陷阴络，夜分偏剧、汗多神昏谵语，由邪逼神明。脉动主阴阳相搏、邪正纷争，故非小病，与仲景劫汗亡阳惊谵同例，议救逆汤减芍药以救逆。", ["动"]], "5034": ["治法", "产后络脉伤，腹痛频发，嗔怒及食物不宜则甚，是脉络不和、气血壅滞所致。原文未出具体脉象，只言'当调和脉络，庶不延成痼疾'，故以葱白丸通阳和络为治。腹痛因络伤而作，嗔怒动肝、食滞伤中皆能加剧，治在调和而非攻伐。", []], "5035": ["病机", "脉右涩左微，色悴不华，食减不能健运，嗳呕溏泄，此中宫阳气欲寂。右涩主脾阳痹阻、运化无力，左微主阳气衰少，故食减、嗳呕、溏泄并见。原文断为'中宫阳气欲寂'，法宜辛温通补，失治则酿成中满难调，是阳气不振、湿浊内聚之机。", ["涩", "微"]], "5036": ["病机", "脉沉右小、左虚大，脐上有动气，䐜胀不嗜食，艰于大便，此中气大虚、肝气内变。右小为脾胃气虚，左虚大为肝气乘虚内动，动气在脐上正是肝气上逆之征。中虚不运则胀而不嗜食，肝气内变则大便艰，故忌攻伐消导，宜泄肝和胃。", ["沉", "小", "虚", "大"]], "5037": ["病机", "脉沉属水，初因食物之滞，继为下夺太速，脾阳顿伤，气窒湿聚而为肿胀。沉脉主里主水，脾阳伤则运化失职，气机窒塞、湿浊凝聚，水湿泛滥故成肿胀。原文点明'下夺太速'伤脾阳是致肿之由，脉沉正应水湿内停、阳气不振之病机。", ["沉"]], "5038": ["病机", "脉左大坚弦，肝风震动，脾胃络脉不和，不知饥、不安寐、口流涎、右肢肿。左脉大坚弦为肝阳亢盛、风动于内之象，肝风扰及脾胃络脉则运化失司，故不知饥、流涎、肢肿；风阳上扰则不安寐。当兼理中焦之络，用茯苓饮法。", ["大", "坚", "弦"]], "5039": ["预后", "脉微而涩，阳气已惫，浊阴日聚，腹胀仍空、鼻冷涕泪、形色衰夺，为胀满不食，危期至速。微为阳衰，涩为血少气滞，阳惫则阴浊凝聚，故腹胀而空、鼻冷。原文断'危期至速'，勉议通阳方法，是阳气将竭、浊阴日盛之危候。", ["微", "涩"]], "5040": ["病机", "脉沉迟，沉主里，迟主寒，为里寒阳虚之象。原文述肿胀腹满、茎缩溺不利，起于冬底痰饮咳嗽气逆，误认肾虚水泛而致增剧，显系寒饮内停、肾阳不足、水气不化。久泻伤肾，下午黄昏为甚，更证肾阳虚衰。故脉沉迟主肾阳虚寒、水湿内停之病机，治宜温肾通阳。", ["沉", "迟"]], "5041": ["病机", "原文谓“两脉逆乱”，非具体脉象，指脉气逆乱失常。客寒闭其流行，脉络中病，故肋稍隐痛、咳甚冷汗、背微寒、足冷、转侧不利。寒邪闭阻，气血流行失序，脉气逆乱上犯，病在血分络脉。治在通络补虚，散寒行血，使脉气复常。", []], "5042": ["病机", "脉数重按无力，数主热，无力为虚，示正虚而湿热内蕴。左腰胁痛不能转侧，舌苔白边红，心中热闷不欲饮，是湿邪滞著、经络阻痹，湿遏热伏。脉数无力说明热不盛而正已伤，故宜气分轻清之药，化湿通络而不伤正气。", ["数", "虚"]], "5043": ["兼症", "脉数，左腰胁疼未止，舌苔黄，为湿热未清之象。昨进芳香轻剂略安，说明药已中病，但脉仍数、苔转黄，示余热未尽，湿滞经络未解。仍不宜重药，继以轻清芳化，清透余邪，免伤正气。", ["数"]], "5044": ["病机", "脉数无力，数主余热，无力为虚，示邪稍缓而阴气已不振。左腰胁疼未止，舌色转红，为余热未清、阴液不足。病邪虽减，正虚渐显，故进清余热略兼养阴方，清补兼施，以复阴气。", ["数", "虚"]], "5045": ["病机", "脉数无力，左腰胁疼未止，舌苔已退，示邪气渐衰而阴气仍然不振。数而无力为虚热内扰，阴不敛阳。虽病邪稍缓，但正虚未复，故议清余热略兼养阴方，以清透余邪、滋养阴液为治。", ["数", "虚"]], "5046": ["治法", "老人久嗽，身小质薄，络脉单弱，脉弱示气血不足、络脉空虚。古人温养脾肾，但桂附雄猛，液枯必犯肺疡，故不可峻温。宜温剂通纳，柔润通补，使肾气收纳、络脉得养，而无伤液之弊。", ["弱"]], "5047": ["病机", "脉细有遗症，细主阴血不足，是阴虚不主收纳。冲气上激为咳嗽，肺药无益，病本在肾。今胃纳颇好，急宜填下绝欲，安养可图愈。脉细说明阴精亏虚、冲脉不摄，故治当补肾填精、纳气归元。", ["细"]], "5048": ["病机", "原文未提脉象，但述“肝肾两虚，阳明脉络失用，筋缩牵强，足痛不堪动作”，病机为肝肾精血亏虚，阳明脉络失养，筋脉拘急。治当温散下焦，莫进疏解，提示虚寒为本，非外邪可疏解。", []], "5049": ["病机", "脉来六至为数脉，主热。原文“行痹日久，时愈时发，脉来六至，湿热居多”，说明湿热内蕴，流注关节，故关节肿痛游走不定；又夹风火，故脉数。病机为湿热夹风火，兼脏液耗虚、腑阳窒塞。", ["数"]], "5050": ["主病", "脉小主虚。久嗽失音，痰冷冲气，入暮为重，乃肺虚气馁，宣降无力，故脉小；酒家有饮邪，更伤肺气。此肺虚为本，饮邪为标，故不易骤愈。", ["小"]], "5051": ["病机", "原文未提脉象，述胁膈懊𢙐、呕逆带血，因中年操持耗血，血不和气，气攻入络，络中聚血，病状难明。病机为血虚气滞，络脉瘀阻，治宜宣通血分以和络，防噎膈反胃。", []], "5052": ["病机", "原文未提脉象，述少腹痛坚、攻脐、午后气胀、经事愆期仅黄水，阴寒入血络，起于产蓐，累及奇经八脉，身伛不直。病机为阴寒凝滞血络，肝肾奇经受损。", []], "5053": ["病机", "原文未提脉象，述肝病属木主筋，情志不适，热自内起，烁筋袭脉，肢体牵强。病机为肝郁化火，风火内动，耗伤筋脉，故药难除根，怡悦静养可渐愈。", []], "5054": ["病机", "原文“色脉是阴虚”，脉虚主阴精亏乏。阴乏上承，热气从左上升，内应肝肾阴火，故喉妨食纳；前用复脉滋阴，大便滑泄，知胃气久为药伤，不受滋阴。病机为肝肾阴虚，阴火上炎，胃气受损。", ["虚"]], "5055": ["预后", "原文未提脉象，述劳怯为肾精内损，真阴枯槁，龙雷之火无制，肾脉循喉受灼而糜腐痛；冬无藏精，春无生发，胃气已索，草木难挽回。病机为肾精枯竭，阴火燔灼，胃气衰败，预后不良。", []], "5056": ["病机", "脉尺中动而左数，动主阳升，数主热。尺候肝肾，动数见于尺中，是肝肾内虚，阴不敛阳，虚阳升动，失其收肃之令。阳升则痰血上溢，夜热非外感，正合过劳熬夜、阳升痰血之症。", ["动", "数"]], "5057": ["治法", "原文未及脉象，径言经水不来是络脉无血，古云气旺血自生，大忌通经。此以血虚络脉无血为病机，主张补气生血，反对通经攻伐，属治法之论。", []], "5058": ["病机", "形色脉象确是阳虚，酒食聚湿，湿为阴浊，先伤脾阳，阳微气衰，故麻木起于夜半气血交代之时。湿注入肠，肠痔下血，中年痱中可虞，皆阳虚湿浊内伤之病机。", []], "5059": ["病机", "脉右弦空左濡，弦为络血不宁，空为形神两伤，濡为气血耗损。经营耗气血，络血不得宁静，故吐血频发，不比方壮，是形神两伤之病机。", ["弦", "空", "濡"]], "5060": ["病机", "色夺脉促，促为阳郁而数中一止，主卫阳疏、气易泄。风冷形肌凛凛，寒露霜降嗽甚，是卫阳不固，气易外泄，故脉促色夺，病机在阳虚卫疏。", ["促"]], "5061": ["病机", "原文未出脉名，而言少阴脉中阴火内烁，上燔阴液，蒸变涎沫，内损精血。咳痰不出、呕食、喉痛失音，皆阴火灼液、精血内损之病机，非清金润肺所能治。", []], "5062": ["病机", "原文未及脉象，述产蓐无乳、经水不来、少腹瘕气、背脊常冷、心腹中热、面黄色夺、食少。督脉阳虚背寒，任脉虚攻入络为瘕，是产损蓐劳、下元无力之病机。", []], "5063": ["病机", "原文未出脉象，言环跳筋骨酸痛，少年精伤，阳维脉少护卫。环跳属阳维所过，精伤则阳维失护，筋骨酸痛，是少年精伤、阳维不护之病机。", []], "5064": ["病机", "原文述漏经继下如卵，形已见，断为血损气结，又引任脉为病、女子带下瘕聚、少腹形象。血伤则忌气燥温热，血药又不可沉滞，故取血中宣气。此段虽未出脉名，病机在血损气结、任脉失养，主漏经瘕聚，症见少腹有形。", []], "5065": ["病机", "原文言精未生成、强泄最难充旺，至今无生育，视形瘦、问食少、精薄易泄。形脉不受刚猛阳药，故藉血肉有情温养气血。此段未识脉名，病机为精亏气血不足，主不育，症见形瘦食少精薄，治当温养而非刚猛。", []], "5066": ["病机", "脉小数而形瘦，经水或前或后，鼻塞火升、上热下冷，原文断为阴弱不旺、肝阳左升太速、右降不及。夏令阴伏于里、阳泄上浮，故宿病俄发。小数示阴弱阳浮，主阴虚肝阳上逆，症见喉病、鼻塞火升、经水不调。", ["数", "小"]], "5067": ["病机", "十四岁室女色夺脉弱，下焦未寒先冷，经事淋漓，原文断为冲任虚冷、二气不交。脉弱主虚，色夺示血不足，故无温热药之例，冬宜藏阳、用温摄升阳。此脉弱主冲任虚冷，症见经漏、下焦先冷。", ["弱"]], "5068": ["病机", "立冬未冷，温热之气外入引动宿饮，先如伤风稀痰，继痰浓咽干，原文谓少阴脉中乏津上承、五液尽化痰涎，因下虚易受冷热而饮邪上泛。老年咳嗽宜调脾肾，忌发散泄肺，暂用越婢法。病机属下虚饮泛、津不上承。", []], "5069": ["病机", "寡居无欢，肝胆气火郁勃，直上直下莫能制伏，失疏泄之用而小溲成淋。原文谓肝脉环绕阴窍，用龙胆泻肝法。此段未出脉名，病机为肝胆气火郁逆、疏泄失职，主淋证，症见小便淋涩，治以泻肝。", []], "5070": ["病机", "疟母瘕聚有形，治有宣通气血，然所述病状已是产虚，八脉交损，故不敢攻瘕。此段未识脉名，病机为产后虚损、八脉交伤而兼瘕聚，主虚中夹积，症见疟母有形，治当顾虚而慎攻。", []], "5071": ["预后", "积劳伤阳，腹膨仍软，脉弦无胃气，形肉衰削。弦为肝脉，无胃气则真脏脉见，中宫阳气不转，虽理中宫望其进食，原文叹无能却病。此脉弦无胃气主胃气衰败、真脏显露，预后不良，症见腹膨、形肉削。", ["弦"]], "5072": ["治法", "原文仅言「复脉法去麻仁」，属治法调整，非脉象描述。复脉法本为炙甘草汤加减，麻仁润燥滑肠，去之或因便溏、或防滋腻碍脾。此处无脉象可辨，故脉素为空，主旨为治法变化，不可强解为某脉主某病。", []], "5073": ["病机", "原文未载脉象，以「经水仍至」与「产后十六年不育」推断病机。任脉为病，男子内结七疝，女子带下瘕聚，此引《素问·骨空论》点明冲任受病。经水仍至而知气攻入络、渐次有形，说明病在气分渐及血络，冲任损伤显然，故主病机而非主脉。", []], "5074": ["病机", "脉左动数，尺不附骨，左脉候肝肾，动数为阳扰，尺不附骨乃肾精不藏。原文谓「肾精肝血内夺，弱阴无能交恋其阳，冲阳上逆」，故咳呕嗳浊、日晡寒热、夜深汗泄。此非有余瘀血，乃内损不足，误用逐瘀则损者更损，脉症合参主阴虚阳逆之病机。", ["动", "数"]], "5075": ["病机", "原文未出脉象，述遗精频致哮喘，病发必甚，断为「肾虚失纳，真气散越」。少年形瘦难用温药，故治当导入任脉阴海以固之。此段以症测机，肾不纳气则喘，精关不固则遗，真气散越为其枢，主病机而非凭脉。", []], "5076": ["病机", "原文无脉象，以经漏胎走推「下元真阴先损，任脉阴海少液，督脉阳海气升」，阴虚生热，故五心脊椎骨热、天明微汗热缓。医投芪术呆守中上，不究阴阳气血，反伤阴分。此段由症候溯病机，主肝肾精血损伤、督任失养。", []], "5077": ["病机", "脉形小濡，小为阳微，濡为气虚湿滞。形躯充伟而脉反小濡，是外强中馁、中年阳微不运之象。食入脘闷、嗳气呕吐觉爽、少焉仍然痞闷，皆中阳不运、气机壅滞。原文斥泄降攻痰为有余治法，非脉症所宜，故主阳微不足之病机。", ["小", "濡"]], "5078": ["其他", "此段为医案源流考述，论《名医类案》《续名医类案》《寓意草》《临证指南》《温病条辨》等书之得失，非论脉诊病。原文无脉象，亦无病机症候可析，主旨属医史文献评述，故归其他，脉素从空。", []], "5079": ["误治", "风温初起，脉浮数，浮主邪在表，数主热，故曰「邪在上焦」。胸痞微痛乃秽浊上干清阳，医误作痰饮阴邪用薤白汤，又误作少阳胁痛用小柴胡，遂致谵语烦躁而痞不解。原文议辛凉退热、芳香逐秽，此段以脉浮数定温邪在卫，纠误治之偏。", ["浮", "数"]], "5080": ["病机", "风温误汗后脉沉数，沉为邪入于里，数为热盛，乃热邪由表上行极而反下陷，气血两燔之象。渴甚示热灼津伤，故议玉女煎合银翘散加黄连清气血之燔，夜间谵语则热扰神明，仍服牛黄丸。脉沉数正合邪热内陷、上行极而下之病机。", ["沉", "数"]], "5081": ["病机", "大势已解而余焰尚存，今日脉浮，是邪气由里还表、下行极而上之征。浮脉主邪在表，与余热未尽、外达肌表相应，故知病势向表而非内陷，仍当随其所在而逐之，清透余邪。", ["浮"]], "5082": ["病机", "脉沉数有力，沉主里、数主热、有力为实，示邪气入里化热。舌老黄微黑为热结之征，故可下；然非正阳明大满大痞之实证，故不用峻下，仅以增液润下，脉沉数有力正说明里热已成而燥结未甚。", ["沉", "数"]], "5083": ["病机", "昨服增液黑粪已下，舌中黑边黄、口渴面赤，脉浮乃下行极而上，热邪复从里达表之象。浮脉主邪出于表，与阳明余热上炎相应；自觉饥甚为阳明热盛，故仍用玉女煎加知母，随其所在而逐之。", ["浮"]], "5084": ["治法", "原文未出脉名，仅言邪少虚多，用复脉法、二甲复脉汤。邪少虚多示正虚邪恋，故以复脉汤滋阴复脉、二甲潜阳，属扶正以祛余邪之治法，非据脉象断病，故脉象要素为空。", []], "5085": ["病机", "风温误认伤寒发表，致神呆谵语、阳有汗阴无汗、大便稀水不爽，现脉浮，乃下行极而上、邪从里还表之象。先渴今不渴为邪归血分，浮脉示邪热外达，与神呆谵语之热扰神明相应，故当清透血分。", ["浮"]], "5086": ["病机", "原文未出脉名，仅言脉无阴，即阴脉不显、阴液亏乏之象。神识稍清而小便短、大便稀水，示邪热伤阴、阴气不足，故议甘苦合化阴气法，仍服牛黄丸清余热，属邪少虚多、阴伤之病机。", []], "5087": ["治法", "原文未出脉名，言温病已解、邪少虚多，用复脉法。邪解而正虚，故以复脉汤滋阴养血、复其脉气，属病后扶正之治法，非据脉断证，故脉象要素为空。", []], "5088": ["病机", "原文言风温发疹初起肢厥而“脉不甚数”，说明邪热初郁、尚未炽盛，故脉数不显。肢厥为热郁气机、阳不外达之象，非虚寒可比。脉不甚数而见发疹肢厥，提示病势虽非浅鲜，然热未大盛，当从风温透疹论治，不可因肢厥误作寒证。", ["数"]], "5089": ["误治", "风温咳嗽黏痰，脉弦数，弦主风、数主热，本属风温热邪。前医误以辛温治风寒，致曾吐血丝血沫，辛温助热伤络之弊已显。脉弦数正合风温热郁之机，故原文断为“风温而误以治风寒之辛温法治之”，当改用辛凉甘润以清透。", ["弦", "数"]], "5090": ["预后", "温病日久不解而“六脉全无”，目闭不言、四肢不动，宛如死去，原文引吴又可“体厥脉厥之证”。脉全无乃邪闭气机、脉道不通之厥，非真元已绝，故用紫雪丹续灌而醒、复脉汤收功，说明此脉厥属可救之闭证，预后尚可挽回。", []], "5091": ["病机", "原文自释“弦则为风，浮为在表，数则为热”，六脉浮弦而数，正合风温热邪在表之机。虽头痛身痛恶寒甚，然脉不紧而弦数，非伤寒表寒，故“不得误用辛温”，宜辛凉芳香清上，上焦主表，表即上焦，脉浮弦数即其据。", ["浮", "弦", "数"]], "5092": ["主病", "脉浮主风温在表，症见咽痛、项强、颈微肿、舌伸不长，为风热壅遏上焦、肺气不宣之象。浮脉应表，说明邪尚在上焦气分，故治法“开提肺气为主”，以宣透上焦风热，脉浮正是邪在表之凭据。", ["浮"]], "5093": ["病机", "年老体虚，本有肝郁，又受时令浊气，见舌黑苔、口苦、胸痛头痛而“脉不甚数”、不渴。脉不甚数、不渴，说明邪气因体虚不能及时传化，热势未炽，非纯实热。故法宜辛凉芳香，透化浊邪而不峻攻，脉象反映正虚邪滞之机。", ["数"]], "5094": ["病机", "昨用辛凉芳香后舌苔少化、身有微汗，“右脉始大”为邪气甫出之象；然“六脉沉取极弱”，沉取候里，弱为不足，说明下虚阴亏。脉大示邪外达，沉弱示正内虚，故议辛凉药中加护阴法，脉象揭示邪退而阴伤之病机。", ["大", "沉", "弱"]], "5095": ["病机", "老年阴亏，邪退十分之七即与填阴，然耳聋脉芤。芤脉中空，主阴血亏耗，原文谓“可知其阴之所存无几”，耳聋亦阴亏失养之征。脉芤与耳聋相应，说明邪虽退而阴液大伤，故与复脉法以填阴复脉。", ["芤"]], "5096": ["病机", "热退大半而脉仍大，说明余邪未尽、正气未复。脉大为病进之象，热病后期脉不随症减，提示余邪深伏未清，故加鳖甲搜剔余邪。脉大在此非实热壅盛，而是邪留阴分、正虚邪恋之征，与热退但脉不静相应。", ["大"]], "5097": ["病机", "脉静便溏，为邪退正复之象。脉由大转静，说明余邪渐清；便溏则示脾土受困、中气不足。故加牡蛎收阴、甘草守中，既固护阴液又培补中焦。脉静与便溏并见，反映热病后期邪去而脾胃未复、阴精待敛之病机。", []], "5098": ["病机", "脉弦数而不洪，弦主邪郁血分，数主热，不洪则热不在气分而深居血分。原文谓「邪毒深居血分」，秽热尚多，清窍火疮、咽痛胸痛、肢厥，皆邪毒内郁、阴精受灼之候。脉不洪而弦数，正说明热毒郁遏血分、不得外达，故恐高年阴精不足当此燎原之势。", ["弦", "数"]], "5099": ["病机", "脉厥六部全无，原文归咎于「大用表药，误伤心阳」，致厥阴包络受伤。脉厥与肢厥冷过肘膝并见，为心阳衰败、邪闭内窍之危候。舌苔板者已化、微有渴意，是邪有外达之机；若得大渴、脉出身热，方为转机。此段论误治致厥、脉闭不出之病机。", []], "5100": ["病机", "肢厥脉厥俱有渐回之象，说明心阳渐复、闭阻之邪渐开。前段脉厥六部全无，此段渐回，是香开内窍、清透邪热后阳气来复之征。仍服前方并紫雪、牛黄丸，以续清内闭之热毒。脉厥渐回反映厥阴包络受伤后阳气渐通、邪有外解之势。", []], "5101": ["病机", "酒客脉象模糊，苔如积粉，胸中郁闷，大便昼夜十数下，原文断为「不惟温热，且兼浊湿」。脉模糊为湿浊蒙蔽、气血运行不畅之象，非单纯温热可解释。苔如积粉、胸郁闷、便频，皆浊湿内蕴、秽浊壅滞之候，故谓非伤寒六经药可治，主湿热秽浊深重之病机。", []], "5102": ["病机", "旧苔退而新苔出，说明邪之所藏尚多；脉象模糊较前稍觉光明，是湿浊渐化、气血渐通之兆。脉由模糊转光明，反映秽浊蒙蔽稍减而余邪未清。此段以脉象变化判断邪正消长，脉渐光明与苔退复出并见，示湿浊未净、正气渐复之病机。", []], "5103": ["病机", "脉洪而舌滑、中心灰黑、余皆刮白，原文断为「湿中秽浊」。脉洪为热象，然舌滑苔白灰黑，是湿浊内蕴、热为湿遏之候。洪脉在此非单纯气分热盛，而是湿热秽浊交蒸、邪势鸱张之征，故须重用芳香以化浊透邪，主湿热秽浊壅盛之病机。", ["洪"]], "5104": ["病机", "脉尚数，说明温病虽已得凉汗，但热邪未净，里热仍盛，故协热下利不止。数脉主热，热迫大肠则下利，热未清则脉数不退。此脉象提示热邪内陷，与下利并见，故议白头翁汤清热止利。", ["数"]], "5105": ["病机", "脉仍未静，说明热邪虽退而余热未清，脉象未复平和。大泄大汗后津液丧亡已多，脉不静反映余热未净，非阳衰。胃脘痛因痰黏，乃液伤热灼所致，不可作阳衰论。脉未静与痰黏、津伤并见，故用甘苦合化阴气法。", []], "5106": ["病机", "肺脉独大，说明肺经热邪壅盛。大脉主热盛，肺热炽盛则仍渴思凉。肺脉独大提示热邪偏聚于肺，与渴思凉相应，为肺热未清之象。", ["大"]], "5107": ["病机", "脉象模糊，说明温毒邪气弥漫，脉道不清。舌黄喉痹、胸闷渴甚，皆温毒炽盛、邪聚上焦之象。脉模糊反映邪热壅遏，气血运行不畅，故议时时轻扬，使邪不聚。", []], "5108": ["病机", "脉沉壮热，说明热邪内结阳明，里实已成。沉脉主里，壮热主实热，舌苔老黄、舌肉甚绛、夜间谵语、烦躁面赤、口干唇燥、喜凉饮，皆阳明腑实、热盛伤津之候。脉沉与壮热并见，故议急下存津，用大承气加减。", ["沉"]], "5109": ["病机", "脉浮，说明邪气还表，由里出外，下行极而上也。浮脉主表，邪气从内向外，故脉浮。此脉象提示病势向外，邪有外达之机，故于前方内加药，因势利导。", ["浮"]], "5110": ["病机", "脉仍数，说明余焰未息，热邪未尽。数脉主热，热未清则脉数不退，口仍微渴亦为余热伤津之象。脉数与微渴并见，提示气血伏热未解，故少用玉女煎法，两解气血伏热。", ["数"]], "5111": ["病机", "脉沉微数，说明热结在里而正气已伤。沉主里，微主正虚，数主热，舌上老黄苔、二日不大便，为阳明腑实；心中躁、腹中不爽，为热扰气滞。脉沉微数反映里实热结兼正虚，故议小承气汤微和之。", ["沉", "微", "数"]], "5112": ["病机", "六脉沉数而实，沉主里、数主热、实主邪结，说明热邪内结阳明，里气不通，故四日不大便、汗不得除、舌苔微黄。然患者老年下虚，脉实虽示可下，却不可轻下，恐伤正气，故议增液汤增水行舟，以润代攻，体现脉实而正虚、攻邪须顾护津液之病机。", ["沉", "数", "实"]], "5113": ["病机", "脉已滑，滑主痰热内盛、邪有外达之势，故渴稍加、汗甚多，为邪欲出之象；但仍未大便，说明里结未通、津液受灼。老年津液有限，不可放心攻劫，故仍守增液法，少入玉女煎，既润肠通便，又保护津液，体现脉滑而正虚、邪欲出而里未通之病机。", ["滑"]], "5114": ["病机", "大便已见而舌苔未净、脉尚带数，数主热，说明余热未尽、血分仍有伏热，故不甚渴而仍以清血分为主。脉数未静，示邪热未全清，须复领邪外出，防其复聚。此段以脉数判断余热稽留血分，主清血分、领邪外解之治法方向。", ["数"]], "5115": ["病机", "血分太热故脉极数，数之极为热盛之征，与痉厥神昏相应，说明邪热深入血分、气血两燔。尚能渴思凉饮，示热未全闭，故以清宫为主，地黄汤犀角为佐，加石膏合冬地为玉女煎法，清气血两燔之伏热。脉极数在此标示血分热盛之病机核心。", ["数"]], "5116": ["预后", "诸证俱减而未尽除，脉之至数亦减，说明邪热渐退、病势向缓，数脉减轻为热减之兆。但老年下虚，咳声不满喉咙，为正虚气弱之危象，可畏之至。故议搜邪之中寓补阴和阳，既清余邪又扶正气。脉数减而证未尽，示病机由邪盛转向正虚邪恋。", ["数"]], "5117": ["预后", "原文仅言脉证虽减，未识具体脉名，故脉象要素从缺。脉证虽减说明邪势稍退，然犹在险途，示正气未复、余邪未尽，病情仍有反复之虞。此段以脉证俱减而仍属险境，提示预后须谨慎，不可因一时缓解而松懈，体现老年热病正虚邪恋、进退未定之病机。", []], "5118": ["病机", "脉洪数有力，洪主热盛气分、数主热、有力主邪实，说明阳明热炽、气血两燔，故周身尽赤若斑、大便大频。神识略清而脉仍洪数有力，示热毒未清、有内陷之虞，故用玉女煎加苦以坚阴，并备紫雪丹清心开窍。脉洪数有力在此标示热毒炽盛、邪实为主之病机。", ["洪", "数", "实", "有"]], "5119": ["预后", "原文未识具体脉名，仅言脉静身凉，脉静指脉象由数急转为和缓，为邪退正安之象。配合神识清、大便通、舌苔退，说明热邪已解、气机通畅，故后以二甲复脉汤养阴复脉善后。此段以脉静身凉示病机由邪盛转为邪退正复，属向愈之预后。", []], "5120": ["病机", "脉数主热，温热月余不解，误用横补中焦致邪无出路，继用刚燥致津液大亏，湿热之邪未能化。干呕、大小便闭、烦躁不安，皆热邪内蕴、阴液耗伤之象。脉数说明热邪仍盛，阴伤未复，故议甘寒苦寒合化阴气，令小便自通，不可强责小便以免泉源告竭。", ["数"]], "5121": ["病机", "脉仍沉数有力，沉主里，数主热，有力为实。虽汗便表里俱通，但脉象未变，说明仍有宿粪与久羁之结邪相搏于里。热邪深结，故需增水行舟，复入阴搜邪法，以荡涤里实。", ["沉", "数"]], "5122": ["病机", "温病汗后脉虽为汗衰，究有五至且不能弱，又对医者说病刺刺不休，此非虚脱之象，乃伏邪藏深日久，方有出路。大便溏泄频频，不可收摄肾胃两关，恐闭门留寇。脉数不弱说明邪热内蕴，正气未溃，故畏其实，治以甘苦咸寒，寓坚阴收纳于中。", []], "5123": ["主病", "脉数急，身热头痛，思凉饮，乃暑伤手太阴之候。数急为热盛之脉，暑热内迫，故身热思凉；热邪上攻则头痛。切忌误认伤寒而用羌防柴葛等辛温发汗，以免助热伤津。", ["数", "急"]], "5124": ["病机", "六脉洪大而数，洪大主热盛，数主热急。渴思凉饮，纯阳之症，气血两燔，热邪充斥内外，故脉象洪大而数。用玉女煎清气血之热，兼滋阴液。", ["洪", "大", "数"]], "5125": ["治法", "温热自汗，脉浮，舌满白，为邪在肺卫之表。脉浮主表，自汗为热迫津泄。最忌足三阳表药发汗，恐辛温助热伤津。故用辛凉法，以疏表泄热，透邪外出。", ["浮"]], "5126": ["主病", "温病脉浮自汗，喘喝，舌苔白厚，思凉饮，为热邪壅肺、表气不和之候。脉浮主邪在表，自汗为热蒸津泄，喘喝为肺热上逆。舌苔白厚、思凉饮说明热邪内蕴。用辛凉重剂以清透肺热。", ["浮"]], "5127": ["治法", "大渴思凉饮，大汗如注，脉数急，为热邪炽盛、迫津外泄之象。数急主热盛，大汗大渴为阳明热炽。非辛凉重剂不足以解之，以清泄里热，保津护液。", ["数", "急"]], "5128": ["病机", "大热已解而脉见小数，是邪热虽退，余邪未清，阴液已伤。数主热，小主虚，脉小数说明热邪虽减而阴分不足，故以养阴清解余邪立法，既清余热又复阴液，防其死灰复燃。", ["小", "数"]], "5129": ["主病", "温热七日不退，脉仍洪浮而长，洪为热盛，浮为邪在表，长为气分热炽。此邪热尚盛于气分，故急宜辛凉退热，加芳香化浊。最忌羌防柴葛发表，以温病忌汗，汗之则伤阴助热。腹痛为秽浊内阻，勿误作寒而用温药。", ["洪", "浮", "长"]], "5130": ["病机", "热稍减而脉势亦减过半，是气分邪热渐退，然气分尚未解透，血分亦有邪。脉势减说明正气渐复，邪势已挫，但余邪未尽，深入血分，故用玉女煎加芳香法，既清气分余热，又凉血养阴，兼化秽浊。", []], "5131": ["治法", "前方芳香开膻中，是治邪之法。然老年阴气告竭，自汗而脱，恐正不胜邪，故再用复脉法护阴，是固正之法。脉象虽未明言，然从自汗而脱可知阴液欲竭，故以复脉汤固护真阴，防其虚脱。", []], "5132": ["病机", "脉仍有力，舌黄黑，仍有宿粪未净，说明邪热与燥屎内结，腑气不通。脉有力为邪实正未虚，舌黄黑为热极津伤，宿粪未净则邪有出路，故再服增液一帖，增水行舟，润肠通便，使邪从下解。", []], "5133": ["治法", "大便后仍用二甲复脉法，以复其丧失之真阴。前已通下，邪有出路，然下后阴液更伤，故用二甲复脉法，咸寒滋肾，甘润养阴，以复其丧失之真阴，防其阴竭阳脱。脉象虽未言，然从治法可知阴伤之甚。", []], "5134": ["预后", "脉浮而鼻息太粗，粗甚则为喘，温病大忌喘促，恐化源绝也。手指与臂时时掣动，瘛疭之象也。脉浮为邪气还表，然喘促瘛疭并见，是邪热内陷，肺肾化源将绝，肝风内动，故勉与玉女煎法，清胃热而滋肾阴，以图万一。", ["浮"]], "5135": ["病机", "脉浮为邪气还表，是邪热从里达外，有外解之势。渴甚加石膏，以清阳明气分大热。脉浮说明邪在表分，然渴甚则里热亦盛，故加石膏清里热，使表里双解，邪从外透。", ["浮"]], "5136": ["预后", "原文述“渴止脉静身凉”，为温病后期邪退正复之象。脉静指脉象由数急转为和缓，身凉、渴止示热邪已解，津液渐复。此时用复脉法，旨在滋养阴液、恢复脉气，故本段主旨为预后转归，说明病势向愈。", []], "5137": ["主病", "温病自汗，脉浮芤。浮为热邪在表，芤为阴血津液亏耗，脉道不充。神昏谵语乃热陷心包、扰及神明。浮芤并见，示热盛而津伤，故先服牛黄丸清心开窍，继以人参白虎汤清热生津。", ["浮", "芤"]], "5138": ["病机", "大用白虎后“脉为敛戢”，指脉势由洪大转为收敛，热未全退，咳而腹痛。脉敛示热势渐减，但余热未清，肺气不降则咳，腹气不和则痛。议甘苦合化阴气法，以甘寒养阴、苦寒清热，针对热退津伤之病机。", []], "5139": ["病机", "“脉少敛”示热势稍减，但手心热甚于手背，为热邪内郁、津液已亏之征。温热未净而阴伤，故用存阴退热法，兼润肺燥。脉少敛反映邪热未完全消退，正虚邪恋，治当兼顾养阴与清热。", []], "5140": ["病机", "“脉复大而芤”，大脉主热盛，芤主津血亏虚。温病过程中脉由敛转大而芤，示热邪复炽而阴液更伤，脉道空虚。此脉象反映邪热未清、津气两伤之病机，为后续治疗提供依据。", ["大", "芤"]], "5141": ["病机", "“脉势火敛”指脉势收敛，火热之势渐减，但手心热甚，示热邪内郁于里。原文“热淫于内，治以甘苦，佐以咸寒”，说明脉势虽敛而里热未清，故治当清里热、养阴液，以甘苦咸寒之品泻热存阴。", []], "5142": ["病机", "“脉复浮大而芤”，浮主邪在表，大主热盛，芤主津血亏虚。温病过程中脉复现浮大而芤，示热邪复张、津液耗伤，脉道不充。前方去二甲黄芩，加石膏、洋参，意在清热生津，针对热盛津伤之病机。", ["浮", "大", "芤"]], "5143": ["病机", "“脉少敛”示热势稍减，但“左脉仍空大”，空大之脉主阴血亏虚、脉道不充，左脉候血，示阴血未复。热未净而阴血亏，故用存阴退热法，以养阴清热，针对津血亏虚、余热未清之病机。", ["空", "大"]], "5144": ["病机", "原文未出脉名，仅言「左大为下焦血分，非右大可比」，以左脉大判邪入下焦血分、阴伤邪少虚多。议复脉法复胃中之阴，是凭左大之脉定病位在血分、病机为阴虚邪恋，故以复阴驱邪为治，非泛言虚证。", []], "5145": ["主病", "右脉大于左，滑而且数，合舌苔老黄、渴欲凉饮，正合《诊尺篇》尺肤热为温病之说。滑数主热盛，右大主邪在中上焦气分，故断为温病，法宜辛凉解肌合芳香化浊，切忌辛温发表、甘热温里，脉症相参以定治法。", ["大", "滑", "数"]], "5146": ["兼症", "素有痰饮，客气加临而身热苔黄脉数思凉，脉数主温邪内盛。昨用辛凉芳香，便后病势未除，仍须辛凉解散，然须回护痰饮，即《金匮》先治新病、旧病后治之意。脉数在此示温病未解，兼症为痰饮宿疾。", ["数"]], "5147": ["病机", "病势较前稍减，脉体亦小，黄苔亦彻，是邪势渐退而脉随病减。但寒从左升、热从入分，寒少热多颇似温疟，故议白虎桂枝法加青蒿，使陷下之邪涌出。脉小在此示邪减而未净，非虚损之小。", ["小"]], "5148": ["预后", "原文未出脉名，仅言「脉静身凉，舌苔悉退，温热已尽」，以脉静身凉判温热之邪已解，预后良好。惟余痰饮胁痛，故一以宣通悬饮为法。脉静为邪退正安之象，与身凉苔退共成温热向愈之凭据。", []], "5149": ["病机", "大便后面微赤、脉微大、舌微苔、胸中热思凉饮，脉微大示余邪未尽而稍上泛，非正虚之微。故议芳香之中仍稍加辛凉，以清透上泛之余邪。脉微大与面赤、思凉饮相合，说明邪热未清而非纯虚。", ["微", "大"]], "5150": ["预后", "原文未出脉名，仅言「脉静身凉，惟头微热，余邪已去八九」，以脉静身凉判邪退，预后向安。余邪仅存头微热，故一以宣肺透饮为主，须能入胁者宜之。脉静为温热已解、正气渐复之象，与头微热共示病势将愈。", []], "5151": ["病机", "食复后脉弦细而滑，胁痛胀、舌苔重浊、不思食。弦主肝、细主阴伤、滑主痰饮，合其人本有痰饮，知肝胃不和、痰饮内阻，食复更伤中焦。故与两和肝胃法，脉弦细滑正示肝胃失调兼痰饮之病机。", ["弦", "细", "滑"]], "5152": ["兼症", "原文仅言脉安静，未及具体脉形，故脉象要素为空。脉静而苔尚未化，说明邪热虽减而湿浊未净，胃气未复，故不可恣意饮食；胁下刺痛为络脉不和，故治法开胃兼和络。脉静在此非平脉，而是邪退正未复之象，与苔未化、胁痛并见，提示余邪留连、络气痹阻。", []], "5153": ["主病", "脉芤数，芤主阴血不足、津液耗伤，数主热盛。温病头痛身热、口渴自汗、喉痛、舌苔重浊尖赤，皆热邪炽盛、津液受灼之象。脉芤数正合热盛伤津、血络不充之机，故断为温病势重，法宜辛凉透解，最忌发汗再伤津液。", ["芤", "数"]], "5154": ["预后", "原文只言脉渐静，未出具体脉形，故脉象要素为空。十三日大便通、咽痛减，邪有出路，脉渐静为邪热渐退、正气渐复之兆；然仍嘱不可躁，说明余邪未清、正气未全，脉静仅是向愈之势，尚需静养，不可因脉静而妄动。", []], "5155": ["预后", "脉静而痛止大半，为邪热渐退之象；但小便未畅、余焰尚存，说明热邪未尽、气化未复。脉静在此反映邪势已减，而非完全平复，故仍不可食谷，恐食复助邪。原文以脉静与余焰尚存并见，提示预后向好而须慎养。", []], "5156": ["治法", "脉静身凉，为邪热已退、正气渐复之象，故用一甲复脉汤。复脉汤类方本为滋养阴液、复其脉气而设，脉静身凉说明热病后期阴伤未复，治当育阴潜阳、复其脉道。原文未出具体脉形，脉静是疗效判断依据，也是用复脉汤的指征。", []], "5157": ["死脉", "热病脉七至，即数疾之脉，主热盛阴竭。烦躁无宁晷、谵语神昏、汗出辄复热而脉不为汗衰，说明邪热深入心包、阴液耗竭，汗出而热不退、脉不因汗减，正合《内经》见三死不见一生之说。脉数疾不去为邪盛正衰之死候，故虽勉与玉女煎护阴清热，仍难言必生。", ["数"]], "5158": ["病机", "脉洪大而芤，洪大为热盛，芤为阴血津液耗伤。热病瘛疭、痉厥神昏，为热邪深入、肝风内动、阴液亏耗之象；洪大而芤正说明热盛于外而阴伤于内，故用育阴潜阳、咸以止厥法，兼以代赈普济散、紫雪丹清透喉舌之肿与心包之邪。", ["洪", "大", "芤"]], "5159": ["病机", "左脉洪而有力，右脉甚软，左候血分、右候气分。左洪有力为热邪深入下焦血分，右软为气分不足。原文断为温邪日久陷入下焦血分无疑，故借芳香搜逐之用，仍用紫雪丹清透血分热邪，热退神清能言即止，说明脉象是判断邪入血分与停药时机的依据。", ["洪", "软"]], "5160": ["预后", "原文未出脉名，仅言「脉未静」，指脉象仍躁动不宁，与汗出、宿粪已解而肿未消、神未清并见，说明余邪未尽、正气未复，病势尚未全平。故仍用代赈普济散、紫雪丹搜逐余邪，汤药重收阴气，以脉未静为邪恋阴伤之征，属预后观察。", []], "5161": ["病机", "汗出脉静身凉后七八日忽又身热，脉洪数有力，便涩口渴思凉，洪数为热盛，有力为邪实，说明余邪续出、热淫于内，非食复劳复。久病反复恐气血不支，故用玉女煎清胃滋阴，紫雪丹仅于神昏瘛疭时服，紧扣「余邪续出」之机。", ["洪", "数", "实"]], "5162": ["病机", "原文仅言「脉浮大」，并释为「下行极而上也」，浮主邪气向上向外，大主热盛，说明伏邪自下焦转而向上、热势复张，是邪气由深出浅、由下趋上之象，故脉见浮大，提示病机转折而非单纯表证。", ["浮", "大"]], "5163": ["病机", "右脉已小、左脉仍壮，右脉候气分，小则气分邪减；左脉候血分，仍壮说明邪气又归下焦血分。故先以紫雪丹搜逐血分伏邪，继培阴清热，宗「热淫于内，治以咸寒，佐以苦甘」之法，脉象左右对比揭示邪之所在。", ["小"]], "5164": ["病机", "右脉复浮而大，右候气分，浮大为热盛邪实之象，犹思凉饮亦为里热之征，说明余邪未尽、热势复张于气分。故暂与玉女煎清胃滋阴，芳香搜逐邪浊之法仍不能止，脉复浮大正是邪浊未净、热淫于内的反映。", ["浮", "大"]], "5165": ["预后", "右脉稍沉而小，左脉仍洪大而浮，右小示气分邪减，左洪大而浮示血分伏邪仍盛；更见神识反昏、微瘛疭、肢微厥，邪陷心包、内闭欲厥，故原文断为「非吉兆也」。舌津回、便通为阴液尚存，治以护阴搜逐深入伏邪。", ["沉", "小", "洪", "大"]], "5166": ["预后", "原文未出脉名，仅言「脉未静」，诸症渐减而脉独未静，说明邪少虚多、余邪未尽，正气尚未全复。故按邪少虚多例调治，不尽之邪付之紫雪丹搜逐，脉未静为余邪留恋之征，属预后判断。", []], "5167": ["治法", "原文仅载「复脉汤去参桂姜枣，二帖」，未出脉象，属治法记录。复脉汤本为炙甘草汤加减，去参桂姜枣者，避温补甘壅，专取滋阴复脉之意，用于阴血亏虚、脉气不复之证，体现以方测证、护阴复脉的治法。", []], "5168": ["病机", "原文谓“气血两燔，脉浮洪数极故也”。温热误汗伤津，又误苦燥化燥，邪热深入气血，浮为热越于外，洪为阳明气分热盛，数极为热毒炽盛之征。热扰胎元则胎动不安，热毒上攻则舌黄烂去半边、目睛突出，皆气血两燔、热盛动血之候。", ["浮", "洪", "数"]], "5169": ["预后", "原文“下后脉静身凉，目睛渐收”，未出具体脉名，以“脉静”与“身凉”并见，说明攻下之后邪热得泄、气血渐和，故目睛突出渐收。此为热退正复之佳兆，故续与甘寒柔润以养阴液，属预后转归之判断。", []], "5170": ["治法", "原文仅言“复脉汤去刚药”，未载脉象。复脉汤本为养阴复脉而设，去刚药者，避桂、姜等温燥之品，防其助热伤阴。此段承前热退阴伤之后，以柔润复脉为治，属治法范畴，非以脉断病。", []], "5171": ["治法", "原文“复脉加三甲”，未出脉象。三甲者，牡蛎、鳖甲、龟板之类，咸寒潜阳、育阴熄风。承前温热日久、阴液亏耗、虚风内动之势，于复脉汤中加咸寒介类，以恋阳止厥，属治法之延续，非脉象主病之文。", []], "5172": ["预后", "原文未出具体脉名，唯言“脉总不静”，与“热总不退”并见，反映邪热深伏、阴津耗伤，虽屡下屡透疹而正邪交争未已。直至“脉静身凉”方为邪退正安之转机，继以复脉汤、专翕大生膏滋养收功，全段以脉静与否判预后。", []], "5173": ["其他", "原文未载脉象，述温病狂热、大渴引饮、癫狂谵语、大汗不止，用白虎合犀角地黄、紫雪、牛黄清心等大剂清解，热退后以复脉汤收功。此段重在记录温热重证之治疗经过与方药次第，未以脉象立论，故归其他。", []], "5174": ["病机", "原文“右脉洪大数实而模糊”，右脉候气分，洪大数实为暑温邪热炽盛、阳明气分热实之象；模糊者，热邪弥漫、痰热蒙蔽心包之征。热陷心包则谵语神昏，故脉势甚危，此脉象直接揭示暑热内传心包、气分热实兼痰蒙之病机。", ["洪", "大", "数", "实"]], "5175": ["病机", "原文“脉沉弦细数，非痉厥所宜”。沉为邪郁于里，弦主肝风内动，细为阴血亏耗，数为热扰。厥热虽稍缓而脉仍沉弦细数，说明阴亏阳亢、虚风未息，热灼阴伤之本质未除，故急宜育阴恋阳、咸以止厥，脉象示病机未离险境。", ["沉", "弦", "细", "数"]], "5176": ["预后", "原文述脉之弦刚者转为大觉和缓、沉者已起，为起色，说明邪退正复之机。弦刚脉本主邪盛，今见和缓，是脉象转佳，但热病伤阴，又误用温燥，故舌燥如草，议启肾液法以救阴。", ["弦"]], "5177": ["主病", "厥已回而面赤、舌干黑苔、脉洪数有力、十余日不大便，洪数有力为实热内结之象，热盛于里故脉洪数，腑气不通故不大便，皆下证，虽虚亦可调胃承气小和之。", ["洪", "数"]], "5178": ["病机", "大下后舌苔化而干未滋润，脉仍洪数，微有潮热，说明下后实邪虽减而阴液未复，余热未尽，洪数脉主热盛，阴伤故舌干，潮热为余邪内伏，故除存阴无二法。", ["洪", "数"]], "5179": ["病机", "小便短赤、微咳、面微赤、尺脉数洪，尺脉候下焦，数洪为热邪内蕴下焦，热伤阴液故小便短赤，议甘润益下以治虚热，少复苦味以治不尽之实邪，甘苦合化利小便。", ["数", "洪"]], "5180": ["治法", "原文未识脉名，述复脉复苦法，清下焦血分之阴热，可知前证为下焦血分阴热未清，故用复脉滋养与苦寒清泄并施，以清血分伏热。", []], "5181": ["病机", "暑温初起脉洪弦而刚甚，左反大于右，不渴，洪弦刚甚为热盛阴伤、肝阳偏亢之象，左大于右提示下焦精血之热甚于上焦气分，旧有血溢故手心热甚，虽初起且清上焦，不可不知其本。", ["洪", "弦"]], "5182": ["病机", "失血后暑病，五心发热，脉双弦而细，弦细为阴血不足、真阳亦弱之象，阴不配阳故五心热，脉不洪大而反弦细，说明阴阳俱虚，议二甲复脉汤滋阴配阳，仍用桂参姜枣扶阳。", ["弦", "细"]], "5183": ["病机", "外邪虽退，平素劳伤太过，虚不肯复，六脉无神，脉无神为气血大虚、元气衰惫之象，劳伤过度致虚不复，非参不可，以人参大补元气。", []], "5184": ["病机", "脉微数，微为正气不足，数为热邪内迫。病后饮食不调，暑湿著里，腹中绞痛、痛极便溏，是湿热滞于肠腑，气血壅阻。脉数主热，微示正伤，热迫欲作滞下，故议芩芍法清肠化湿，夺其滞下之源。", ["微", "数"]], "5185": ["其他", "原文未载脉象，仅述一二帖后腹痛除，仍服复脉汤十余帖。此段重在记录药后痛除、继以复脉汤调养，属病后调理过程，无脉可析，故脉象要素为空。", []], "5186": ["病机", "脉芤主血虚，身热而胁痛，乃暑温挟痰饮怒郁，气机壅滞，血络受伤。误用足六经表药，更伤津血，致烦躁不宁、六日不解。芤脉示阴血亏耗，热郁胁络，故为至危之证。", ["芤"]], "5187": ["病机", "左关独高，余脉皆缓，缓为通体虚寒，左关高主少阳内风掀动。头痛因风热上扰胆络，有损一目之弊。通体皆寒、一隅偏热，故先清少阳一隅之热，宗《金匮》先治新病之意。", ["缓"]], "5188": ["病机", "六脉洪大之极，左手更甚，洪大为暑热炽盛、气血燔灼。暑入心包胆络，故目斜视、怒气可畏、瘛疭、舌斜不语、面赤身热。脉洪大极示邪热充斥，清心胆为要，先与紫雪丹。", ["洪", "大"]], "5189": ["病机", "脉沉主里，暑热已退七八，十余日不大便，微有谵语，是热结阳明、腑气不通。沉脉示邪入里，虽热势已减，仍可轻通阳明，与增液承气法养阴通便。", ["沉"]], "5190": ["病机", "脉缓主湿，暑温下后舌苔白滑，暑必挟湿，湿困中焦，胃气不和。缓脉示湿邪未化，故下后宜养阴兼和胃，与外台茯苓饮意健脾化湿。", ["缓"]], "5191": ["病机", "右脉洪大无伦，洪大为暑热炽盛，右脉主气分，暑伤手太阴肺经。喘渴太甚、烦躁谵语、身热，是热邪有逆传心包之势。脉洪大无伦示邪热鸱张，故议两清营卫之法。", ["洪", "大"]], "5192": ["病机", "右脉仍洪，舌黄而滑，呕未尽除，说明热邪未净，余热仍盛于气分。洪为热盛之象，滑主痰湿未化，故虽诸症俱减、热已退，而右脉仍洪，提示热邪深伏，痰湿内蕴，胃气上逆故呕未尽除。此脉主病机为余热夹痰湿未清，与舌黄滑、呕逆相应。", ["洪", "滑"]], "5193": ["小儿", "小儿脉当数，此其常也，然暑湿伤脾，暮夜不安，少腹肿痛，肝肾虚寒，面色青黄，舌苔白，手心时热，乃脾虚湿困、肝肾不足之候。脉数虽小儿常态，结合诸症，主暑湿伤脾、肝肾虚寒，防成疳疾。脉数与手心热、舌苔白并见，示虚中夹湿，非纯实热。", ["数"]], "5194": ["病机", "暑温误下，寒凉太过，洞泄完谷不化，关闸不藏，脉弦。弦为肝木乘脾之象，误下伤中，脾阳衰败，肝木克土，故洞泄完谷。脉弦主病机为土虚木贼、中阳不振，与洞泄、完谷不化相应。用桃花汤改粥法，温涩固脱，正合此机。", ["弦"]], "5195": ["病机", "脉右大左弦，身热如烙，无汗，胶痰，舌苔满黄，腹胀少腹痛，不渴，乃伏暑内发、新凉外加，阴阳并病，两太阳互争。右大主气分热盛，左弦主肝胆邪郁，脉象示上焦湿热壅遏、气化不利。胶痰、苔黄为湿热酿痰，腹胀痛为邪阻气机，故先清上焦湿热。", ["大", "弦"]], "5196": ["病机", "津液稍回，宿粪未除，潮热因邪气还表，右脉仍然浮大，未可下。浮大之脉主邪在表、气分热盛，虽潮热似里实，然脉浮大示邪气还表，未全入里，故不可下，宜保津液，护火克金之嗽。此脉主病机为邪热还表、津伤未复，与潮热、嗽相应。", ["浮", "大"]], "5197": ["病机", "原文未识脉名，然述津液消亡、舌黑干刺，用复脉法。舌黑干刺为津枯液涸、邪热深入营血之危候，复脉法旨在滋阴复脉、救液存津。虽无脉象，从症推机，主病机为热邪久羁、津液消亡、阴血亏耗，与舌黑干刺相应，属病机分析。", []], "5198": ["病机", "右脉仍数，余邪陷入肺中，咳甚痰艰，议甘润兼凉肺气。数脉主热，右脉候肺，余邪入肺，肺热津伤，故咳甚痰艰。脉数示肺中余热未清，与咳甚痰艰相应。主病机为余热恋肺、肺失清润，故用甘润凉肺之法。", ["数"]], "5199": ["病机", "舌黑苔退，脉仍数，仍咳，腹中微胀。舌苔退而脉仍数，示邪热未净，余热留恋肺胃；咳为肺气不清，腹微胀为气机未畅。数脉主热，与咳、腹胀并见，主病机为余热未清、肺胃气机不和，属病机分析。", ["数"]], "5200": ["病机", "原文未载脉名，然述“潮热退，唇舌仍绛”，绛为热灼阴伤之征。热邪久羁，必耗阴液，故曰“热之所过，其阴必伤”。用复脉法复其阴，是据阴伤之机而设，脉虽未言，当见细数或虚象，主热病后期阴液亏耗之病机。", []], "5201": ["预后", "原文谓“脉较前却稍和”，是伏邪内溃、白痧续出后，邪有外达之机，脉由躁转和，示病势向缓。然舌苔未化、不大便，余邪未净，故脉“稍和”仅属小效，非全愈之候，主伏邪渐透而未尽之预后判断。", ["和"]], "5202": ["预后", "服后得黑粪，潮热退而“脉静”，是邪热从下而解，脉由数躁转静，示病退正安之象。脉静为邪去阳潜之征，故以后“一以养阴收功”，主热病后邪退正复、阴伤待养之预后。", ["静"]], "5203": ["病机", "左脉洪大数实，右脉阳微，左右悬殊，故断为“阴阳逆乱”。洪大数实为暑热炽盛、邪壅于左；右脉阳微则气分不足。伏暑似疟，邪伏难透，脉证相悖，故曰“最难即愈”，主暑热内伏、阴阳失调之病机。", ["洪", "大", "数", "实"]], "5204": ["治法", "原文未出脉象，仅载二甲复脉汤加黄芩，谵语仍服牛黄丸。此为热伤阴液、余邪未清而设：复脉汤滋阴，黄芩清余热，牛黄丸开窍治谵语。脉虽未言，当属阴伤邪恋之细数或虚数，主滋阴清热、开窍之治法。", []], "5205": ["病机", "原文未出脉名，然言“六脉重按全无，舌仍干燥”，重按全无是阴液枯竭、脉道不充之象，舌干亦阴伤之征。热退脉减而重按无根，故引“热之所过，其阴必伤”例，用二甲复脉重加鳖甲、甘草，主热病后阴液大伤之病机。", []], "5206": ["病机", "六脉俱弦，木旺克土，故泄泻、不食、欲呕、胸痞；舌白滑为寒湿。然“脉反数”与寒湿不符，原文谓“思凉思酸，物极必反之象”，是湿郁化热之兆。弦主木旺，数主郁热，主寒湿困脾、木旺克土而兼郁热之病机。", ["弦", "数"]], "5207": ["病机", "“脉数甚，思凉”，原文明言“湿中生热之故”。数脉为热，湿郁日久化热，故脉数而思凉。此段紧承上条寒湿病，示湿邪郁久生热之转机，主湿中生热之病机，与思凉、脉数甚相应。", ["数"]], "5208": ["病机", "右脉单弦主伏饮内停，饮邪阻滞气机；脉弦又主肝郁，脘痞胸痛为肝气郁结之征。湿热内蕴则面目青黄，误服酸甘致湿热伏匿，故脉弦与庞杂症候相应，治当宣通三焦。", ["弦"]], "5209": ["病机", "六脉俱弦之泄泻，古称木泄，弦主肝木乘脾，中焦虚寒，故脉双弦者寒也。寒热往来更证邪在少阳，当以小柴胡汤提邪外出，非生熟地所宜。", ["弦"]], "5210": ["病机", "脉之弦劲者转为微细，弦劲为寒暑郁遏之象，微细则阳气衰微，阳虚不能鼓动血脉。面青、痰稀、舌淡、不渴皆阳虚之候，故用桂枝柴胡各半汤减黄芩加干姜温阳。", ["弦", "细"]], "5211": ["预后", "原文未言具体脉象，仅述「脉中阳气已有生动之机」，指药后脉象由沉滞转为生动，示阳气渐复，为向愈之兆。故仍宗前法退之，不可性急。", []], "5212": ["病机", "脉沉弦主邪气深入，沉为在里，弦为寒饮内结。寒多热少，疟疾已成，邪伏阴分，故用两分阴阳之中偏于温法，以温散深入之寒邪。", ["沉", "弦"]], "5213": ["病机", "脉弦细主阳微，弦为饮邪，细为阳虚，阳气不及四末故指尖冷。兼腹痛便溏、痰饮咳嗽，皆中阳不足、饮邪内停之候，治以和胃阳、温中逐饮。", ["弦", "细"]], "5214": ["病机", "脉缓而饮，缓主湿，饮为水湿停聚。伏暑酒毒遇寒凉而发，湿热交蒸故身热、谵语、发黄、滞下。脉缓与湿热内蕴、饮邪阻滞相应，先清湿热、开心包。", ["缓"]], "5215": ["预后", "脉之软者亦鼓指，软脉本主湿，今能鼓指说明正气渐复，湿热渐退，故黄亦少退。然舌赤、小便赤浊，余湿余热未尽，尚须清之，为向愈而未全之候。", ["软"]], "5216": ["病机", "黄疸二十日后黄退，而小便赤浊、舌赤脉洪，洪为热盛之象，说明湿热虽退而未净，热邪仍偏盛于气分。脉洪与舌赤、小便赤浊相应，皆属湿热余邪内蕴，故断为湿热未净，不可骤补。", ["洪"]], "5217": ["主病", "伏暑如疟状，寒热往来而热多于寒，脉弦数。弦主少阳枢机不利、疟邪在半表半里，数主热盛，故寒热往来而热偏多；解后有汗，是邪从表解之兆。弦数与如疟寒热相应，主伏暑少阳之邪，故用青蒿鳖甲汤透解而愈。", ["弦", "数"]], "5218": ["病机", "六脉弦细而紧，两关独大而浮，弦紧主肝郁饮停、外风相搏，细为阴伤；两关大浮是厥阴肝木克阳明胃土之象。原文斥医者以地黄柔药补阴，反助阴病，致势成噎食反胃，故脉象所示乃肝胃不和、阴阳错杂之病机。", ["弦", "细", "紧"]], "5219": ["病机", "伏暑遇新凉而发，舌苔裛白上灰黑，六脉不浮不沉而数。不浮不沉说明邪不在表亦不在里，数主热郁；误与发表则胸痞不食，是四气杂感兼肾虚、肝郁、误治、酒客中虚层层相叠，故脉数示湿热郁阻三焦、气化不利之危候。", ["数"]], "5220": ["病机", "舌灰化黄、滑而不燥，唇赤颧赤，脉由弦转为滑数。弦为湿热郁阻气机，滑数则湿热俱盛之象；脉之弦者化为滑数，说明邪从郁滞转为湿热蒸腾，故断为湿与热俱重，与唇颧赤、舌黄滑相应。", ["弦", "滑", "数"]], "5221": ["病机", "伏暑舌灰化黄，黄退而白滑未除，脉滑甚。滑主痰湿内盛，滑甚说明痰湿仍重，故当退苦药、加辛药以化痰，并重加化痰之品。脉滑甚与舌白滑相应，示暑中伏湿未化、痰湿偏盛之病机，须小心复感。", ["滑"]], "5222": ["病机", "伏暑虽退，舌白滑未化，是伏湿尚存；脉之滑大者已减，说明暑中热邪已去，然脉转太小而不甚流利，是阳气未充、不能化湿之象。滑大减而小涩，正合湿存阳弱之病机，故重与辛温助阳化湿。", ["滑", "大"]], "5223": ["病机", "原文以脉辨伏暑与劳瘵：劳之阴虚身热，脉必芤大，芤大为阴血亏虚、虚热外浮之象；伏暑之脉则弦细而弱，弦细主邪郁少阳、湿阻气机。两脉对举，说明伏暑寒热如疟、有汗而止，非劳瘵阴虚之芤大，故知为伏暑而非劳。", ["芤", "大", "弦", "细"]], "5224": ["病机", "脉弦细，弦主湿郁气滞，细主中虚。酒客中虚湿重，又感伏暑新凉，头胀便溏、舌白滑，皆寒湿内蕴之象。脉弦细正合中虚寒湿，非外感实邪之脉，故断为久病伏湿虚寒难退，客症虽易除而根本难拔。", ["弦", "细"]], "5225": ["病机", "伏暑误治，邪陷下焦血分，夜热早凉，食减汗多便结，脉大乃邪热伤及阳明阴分、虚阳外浮之象。脉大而食减，非实热壅盛，乃阴伤不能敛阳，故先救阳明之阴，以复其津液。", ["大"]], "5226": ["病机", "温毒颊肿，面目前后俱肿，头痛身痛谵语肢厥，脉伏而象模糊，是阳证得阴脉。热毒壅遏，气血不能外达，故脉伏不显，非虚寒之伏，乃邪闭阳郁之危候，故议普济消毒饮以透解热毒。", ["伏"]], "5227": ["病机", "脉促为阳盛而阴不能和，数中一止，主邪热内迫、气机不利。此段承前温毒病程，脉转促提示热势鸱张，气血壅滞，故于前方内加味以清透并调其气血。", ["促"]], "5228": ["预后", "脉出，是伏邪外达、正气渐复之象，身壮热为邪机向外。然脉出而热壮，其势必凶，恐正不胜邪，故当静以镇之，勿事慌张，稍有谵语即服前方，示人守方待变、慎防内陷。", []], "5229": ["预后", "肿消热退，脉亦静，是邪去正安、脉证相符之佳兆。脉静不躁，说明热毒已解，气血渐和，故用复脉汤七帖以复其阴液、善其后，全愈收功。", []], "5230": ["误治", "温毒发斑，误用伤寒大汗大下，耗伤阴津。右脉洪大芤甚，洪大为热盛，芤为中空阴伤，渴甚汗太甚，皆津液外泄之征。脉证合参，知误治伤阴，故急用化斑汤清热生津化斑。", ["洪", "大", "芤"]], "5231": ["主病", "温毒三日，喉痛胀、滴水不下、身热，脉洪数，洪主热盛，数主邪急，热毒壅结咽喉，气血沸涌，故脉洪数。先以普济散噙化控吐，开喉泄毒，继以玉女煎清热，复脉汤收功，步步紧扣热毒壅盛之机。", ["洪", "数"]], "5232": ["病机", "脉弦为湿毒内蕴、肝失疏泄之象，兼有外风则风与湿毒相搏，外风引动内湿，故脉弦而不静。原文“因湿毒而发天行杨梅疮，脉弦兼有外风”，说明弦脉既主湿毒郁于肝经，又主外风袭表，风毒相合发为疮疡，症见杨梅疮。", ["弦"]], "5233": ["病机", "六脉洪数而促，洪为阳明热盛，数为热炽，促为热盛急迫、脉行急促而时一止。原文“壮热大汗，鼻衄”“其脉促，有燎原之势”，正合阳明经证热邪鸱张，非白虎不能清泄，故脉促主热势燎原，与面赤、口渴、烦躁相应。", ["洪", "数", "促"]], "5234": ["预后", "原文“尽剂而脉静身凉”，脉由躁动转为安静，身热退去，是邪去正安之象。“脉静”与“身凉”并见，说明药后热退、脉复和平，属疾病向愈的预后判断，故本段主旨为预后，非论具体脉象要素。", []], "5235": ["病机", "原文“数而时一止曰促，缓而时一止曰结”，促为阳属火，故主以石膏清肺胃之阳热；结为阴，乃肺之细管中块痰堵截隧道，故主以杏仁利肺气消块痰。此段以促、结分阴阳，说明促主火盛、结主痰阻气机的病机。", ["促", "结"]], "5236": ["主病", "脉沉而肢厥，面赤舌黄大渴，十日不大便、转矢气、谵语，是热结阳明、腑实内成之候。脉沉主里，肢厥为热深厥深，原文“下证也”明言可下，故脉沉在此主里实热结，与谵语、矢气、便秘相应，用小承气汤下之。", ["沉"]], "5237": ["病机", "脉犹沉而有力，说明下后里实未净、热结仍在；身热不退而微厥、渴甚面赤，为热郁于里、阳气不达四末。原文“犹宜微和之”“议增液承气”，故沉而有力主里实热结未解，兼阴液受伤，需微和而非峻下。", ["沉"]], "5238": ["治法", "原文“今日脉浮不可下”，脉浮为邪热趋于气分、病势向外向上，非里实可下之候。渴思凉饮为气分热，口中味甘为脾热，故不可下而议玉女煎加苦药清脾瘅。脉浮在此提示病位在气分、禁下，属治法宜忌之辨。", ["浮"]], "5239": ["治法", "原文“邪少虚多，宜用复脉去桂、枣”，未明言脉象，以邪少虚多立论，主以复脉汤加减。因其人酒客，去甘草之重甘，加二甲、丹皮、黄芩，属据体质与邪正虚实调整治法，故本段主旨为治法，脉象要素无具体可录。", []], "5240": ["病机", "温热病见面赤目赤、舌苔满布，外热不盛、口不渴、肢微厥，脉反缓而弦，属阳证阴脉。缓为阳气不足，弦为邪郁不化，说明本身阳气不能充满，无力化解温邪，故外热不盛、口不渴而肢厥，治当化邪。", ["缓", "弦"]], "5241": ["病机", "温病舌苔布满而不渴，虽黄而滑，脉缓甚，热不壮，此挟湿之故。缓脉主湿邪困阻，热为湿遏故不壮盛，苔黄滑而不渴亦湿象，故从湿温例治，用苦辛寒法以化湿清热。", ["缓"]], "5242": ["病机", "六脉弦细而劲，为阴寒脉；咳嗽稀痰为阴湿咳，舌苔刮白而滑为阴舌苔，呕吐泄泻为阴湿证。弦细而劲示寒湿内盛、阳气受困，虽发热汗出而解，乃湿中兼风之湿温，非阴虚证。", ["弦", "细", "劲"]], "5243": ["病机", "痰饮兼风误治成坏证，现面赤口渴、暮夜谵语，有风化热之象，但六脉尚弦，未尽转阳。弦脉主饮主风，说明风痰之邪未化，故咳嗽则胸胁小腹微痛，有金克木之象，病机仍在饮风未解。", ["弦"]], "5244": ["病机", "脉弦数，午后潮热，苔由白变黄，呕恶口渴，似湿疟；但咳嗽便溏，又有湿温之形。弦主湿郁，数主热，示伏邪内陷、湿热交蒸，故潮热、呕恶、口渴与咳嗽便溏并见，病机复杂难清。", ["弦", "数"]], "5245": ["病机", "六脉俱弦而细，左手沉取数而有力，面淡黄、目白睛黄，午后身热，便溏不渴，小便午后赤浊。弦细主湿，沉数有力主内热，示湿中生热、郁于中焦，故用苦辛寒法以化湿清热。", ["弦", "细", "数"]], "5246": ["病机", "湿温舌苔白滑厚浊，脉象模糊，弦细而且沉濡。弦细主湿郁，沉濡主湿邪内蕴、阳气不宣，模糊示湿浊弥漫，故先寒热后微热，治以通三焦、渗湿之苦辛淡法，久服方解。", ["弦", "细", "濡"]], "5247": ["病机", "舌黄口渴，头不痛而恶寒，面赤目赤，脉洪热甚，形似伤寒，实乃冬温夹痰饮，与伏暑一类。洪脉主热盛，热邪内炽故面赤目赤、口渴苔黄，虽恶寒乃热郁于内，非真伤寒。", ["洪"]], "5248": ["主病", "温病见渴甚、热甚、面赤甚，脉洪甚，洪为阳盛之象，热邪充斥气分，故脉形盛大。渴甚面赤为热灼津伤、阳明热盛之候，脉洪与症相应，主气分热盛之温病，非虚寒可拟。", ["洪"]], "5249": ["病机", "脉洪滑，洪主热盛，滑主痰湿内蕴，为热与痰交蒸之象。承前温病渴热面赤之后，热势未清而兼痰湿，故于前方加减，脉象提示气分热盛兼痰，非单纯虚证。", ["洪", "滑"]], "5250": ["病机", "脉不浮而细数，细为阴伤，数为热，不浮则邪已入里，非表证。大渴欲饮、大汗，热盛耗津，里不足之热病也，故用玉女煎法清胃滋阴，脉细数正合里虚有热之机。", ["细", "数"]], "5251": ["兼症", "温热大渴大汗，脉数，热势尚存。服玉女煎后诸证俱减，然平素消渴，药后大便稀溏，数脉主热，兼见下利，为热伤阴而脾肠不固，故加牡蛎一面护阴、一面收下，脉数示余热未清。", ["数"]], "5252": ["病机", "冬温脉沉细之极，沉主里，细为阴血不足，舌赤面赤谵语便闭，邪机纯然在血分之里，热灼血分而阴伤，故脉沉细至极。与润下法，通腑泄热以存阴，脉象正示邪在血分深处。", ["沉", "细"]], "5253": ["病机", "诸病渐减而左肢拘挛、语言不清，脉兼结。结为脉来缓而时止，主气血痰浊阻滞络脉，此络中痰堵塞，皆误补致壅之故，非针不可。脉结与肢挛语涩相应，示痰阻络隧、气血不畅。", ["结"]], "5254": ["病机", "中风湿见口歪、臂不举、腿肿，脉洪数，口渴胃不开。洪数为热盛，热蒸湿动，风湿热交阻经络，故肢废肿渴。辛凉开水道法，清其热而利其湿，脉洪数正示湿热壅盛之机。", ["洪", "数"]], "5255": ["病机", "中风神呆不语，前能语时自云头晕、左肢麻、口大歪、不食，六脉弦数。弦为肝旺风动，数为热，肝阳化风上扰，故痱中也。与柔肝法，脉弦数示肝风内动、筋脉失柔之病机。", ["弦", "数"]], "5256": ["病机", "脉洪数而弦，洪为热盛，数为邪热内迫，弦主肝郁风动。李氏伏暑挟痰饮，暑热内蒸故脉洪数；肝郁化风、痰饮上扰，故兼弦。头痛、舌厚白苔、言蹇，皆痰热蒙蔽、风阳上扰之候，故先以辛凉清上，透暑热、熄肝风。", ["洪", "数", "弦"]], "5257": ["病机", "六脉弦细，弦为肝风未息，细为阴血不足。前服柔肝清热之剂烧退，外邪已解，而脉仍弦细、手足发凉，是肝风内动、阳郁不达四末，有厥脱之势。故治法于熄风中参入开心胞之络，防其窍闭神昏，若一二日不醒则难挽回。", ["弦", "细"]], "5258": ["病机", "左手脉紧，紧主寒主痛。诸症向安而余晨泄，晨泄属肾阳不足、命门火衰，阴寒内盛故脉紧。左手候肾，紧见于左，正合肾阳虚衰、寒凝于下之机，故宜补肾阳以温散下焦阴寒，使晨泄自止。", ["紧"]], "5259": ["病机", "上脉洪大、尺部更甚，左脉弦细，洪大为阳热亢盛，弦细为肝阴不足。上盛下虚，阳亢于上、阴虚于下，肝风内动、络热窍闭，故卒中不能言、如中风状。证势甚重，脉象示本虚标实、阴阳不相维系。", ["洪", "大", "弦", "细"]], "5260": ["病机", "脉弦数，弦属肝木，数主热。真水不配相火，水不生木，木失滋涵而直强上行，化风上扰，故头晕甚即颠厥。此非痰之为患，乃肝肾阴虚、相火妄动、肝风内动之机，久不治则成痱中，故先清少阳胆络，继填真阴。", ["弦", "数"]], "5261": ["病机", "脉沉而弦细，沉主里、弦主肝、细主阴血不足。肝阳上窜因怒而发十余年，久病入络，沉弦细示寒凝络脉、阴血亏虚，故断其为寒厥。胁下有块有声、经色紫黑，皆寒瘀阻络之征，幸为腑厥非脏厥，故用温通络脉法。", ["沉", "弦", "细"]], "5262": ["病机", "脉弦细数、按之无力，弦为肝风，细为阴亏，数为虚热，无力为正气大伤。久服桂附刚热，劫烁少阳津液，厥阴头痛、畏明、厥去四五次，皆阴亏阳亢、肝风内动之候。脉证合参，危急已极，故用定风珠潜阳育阴以熄肝风。", ["弦", "细", "数"]], "5263": ["病机", "六脉弦紧而长，弦主肝郁，紧主寒痛，长为气机郁滞、邪实有余。肝郁胁痛继而肝厥犯胃，十年不食、闻声痉厥、终夜抽搐，是木克脾土、阳明空虚、外犯太阳。弦紧长示肝郁寒凝、本脏致病，故仍从肝络论治。", ["弦", "紧", "长"]], "5264": ["预后", "脉稍和平，虽弦而有胃气，是肝木之弦得脾胃中和之气相济，为病情向愈之象；故能食干饭一碗有半、月经复通。然夜间燥症烦躁欲起坐不得，乃阴血未充、虚风内扰之兼症，脉虽和而症未全平，故仍间服前二方以巩固。", ["弦", "和平"]], "5265": ["预后", "六脉又和一等，较前日脉稍和平更进一层，脉象趋于冲和，反映胃气渐复、气血渐调；故能食干饭两小碗，食量增加为脾胃气旺之征。仍间服前二方者，示病虽向愈而余邪未净，须缓调以竟全功，属脉症相应之佳兆。", ["和"]], "5266": ["病机", "六脉洪大无伦，为肝风鸱张、疏泄失职、气火升腾无降之象；风药助风、大黄麻仁再通，两犯逆而气机愈壅，故不食不饥、不便不寐、身热坐不得卧、时时欲呕、烦躁欲怒。洪大无伦正是邪盛正困、升降俱废之危候，故引《金匮》再逆促命期以警。", ["洪", "大"]], "5267": ["兼症", "原文未载脉名，仅言昨用苦辛法后脉减便通，可知前此脉必因络阻气滞而偏实偏数，药后脉势得减、大便得通，是苦辛宣降见效之征。今日腹中觉痛、将近经期，痛因冲任气血将行而络脉不畅，故一以宣络为主，兼顾经行。", []], "5268": ["治法", "本段未出脉象，重在述治法次第。昨日通络已得便通痛止，惟不成寐，是胃不和则卧不安，故用半夏汤和胃以安卧，仍兼宣络。引仲景冲脉累及阳明之说，明冲脉气逆上干阳明致卧不安，故先治冲脉后治阳明，示先后缓急之序。", []], "5269": ["病机", "脉沉数，沉主里、数主热，为热郁于里之征；溲赤短正是小肠火府热结、肝热下移之症。前用半夏汤已得寐，胃气稍和，而脉仍沉数、溲赤短未除，说明肝经郁热未清，故议加苦药泄肝热而通小肠火府，脉症合参以定清利之法。", ["沉", "数"]], "5270": ["兼症", "本段未载脉象，以症测机。得寐、溲色稍淡、口知味，是阳明渐和之机；惟胸中微痛、背掣痛，按肝脉络胸、背属太阳，乃厥阴病累及少阳、少阳累及太阳之传变。仍用前法加通太阳络，示病机由肝及胆及膀胱经层层相引。", []], "5271": ["病机", "本段未出脉象，以症言机。绕脐痛者瘕也，瘕属气聚血结、按之移动；脐周为冲脉所过、肝经所络，故断为冲脉肝经之病。冲脉起于胞中，肝主疏泄，二经气血郁滞则结为瘕而绕脐作痛，与前文冲脉累及阳明、肝脉络胸诸论一脉相承。", []], "5272": ["病机", "左脉已和示阴血渐复，右脉弦大乃土中木旺之象。弦为肝脉，大为邪盛，右关候脾胃，弦大见于右脉，说明肝木乘脾，土虚木贼。虽诸证悉减而未尽，此脉象揭示病机重点已由气血两燔转为肝木犯土，故治法于两疏气血之中兼泄木安土，以平木亢而安中州。", ["弦", "大"]], "5273": ["病机", "右脉弦刚，弦为肝木之象，刚则示木气劲急。右脉候肺与脾胃，弦刚见于右，乃土中木盛，肝气横逆犯脾。木盛则克土，土受戕则运化失职，故脉象弦劲不柔。此与上条‘土中有木’一脉相承，皆言肝木偏亢、脾胃受困之病机。", ["弦"]], "5274": ["病机", "脉弦数，弦主少阳，数主热。头痛时止时甚、时发时止，乃少阳络脉为病，虚风内动之征。弦为风木之象，数为虚热之应，风热扰于少阳络脉，故痛势休作有时。原文明言‘少阳络痛，虚风内动’，治以清胆络法而勿犯中焦，正合脉弦数所示胆络郁热、风动不宁之机。", ["弦", "数"]], "5275": ["病机", "原文未出脉象，然言‘八脉丽于肝肾，肝病久，未有不累及八脉者’，揭示久病肝郁必下及奇经八脉之病机。八脉隶于肝肾，肝病日久，阴血亏耗，络脉失养，奇经亦随之虚滞。故用通补阴络兼走八脉法，以通为补，兼顾奇经，非独治肝也。", []], "5276": ["治法", "原文未载脉象，述‘镇冲脉，泄胆阳，业已得效，仍宗其法’，示冲脉上逆、胆阳偏亢之病机已得控制。冲脉为病气从少腹上冲，胆阳上逆则呕苦眩冒，镇冲泄胆正对此机。血络郁痛未能卒治，乃因冲胆之逆为急，络瘀为缓，故先治其急，缓图其络。", []], "5277": ["主病", "脉弦数，左尺独大。弦主肝，数主热，左尺候肾与肝，独大示病位在下焦肝肾。瘕居右胁、发则攻心、痛跃不止，病名肝著，乃肝经气血郁滞、络脉瘀阻所致。弦数为郁热之征，左尺独大说明病根深伏下焦，故先宜宣络以通瘀滞，后补八脉以固其本。", ["弦", "数", "大"]], "5278": ["病机", "左脉沉弦，右脉浮弦，两畔不同。原文谓‘凡两畔不同者，皆肝病也’。沉弦主肝郁于下，浮弦主风阳上浮，气至丑寅则上升、暮卒复，升降失司，痰饮斯聚。肝主疏泄，升降失常则水液不化，聚为痰饮。脉之左右浮沉不一，正示肝病及脾、气机升降乖违之机。", ["沉", "弦", "浮"]], "5279": ["病机", "左脉浮取弦，沉取洪大而数，重按即芤。弦为肝郁络瘀，洪数为郁热内盛，芤主血虚失血。痰挟瘀滞黑色、咳血，乃肝经络瘀挟痰饮，血不循经而妄行。原文辨‘左脉坚搏，治在下焦血分’，此脉浮弦沉洪数而芤，正合下焦血分络瘀挟热、阴血耗伤之病机，故势已惫极。", ["弦", "浮", "洪", "数"]], "5280": ["病机", "左脉坚搏主肝络瘀滞，血不归经；洪数而芤为阴伤阳浮之象。原文谓“血家左手脉坚搏，治在下焦血分”，又言“阳虚也”“阴伤也”，说明阴阳两伤而瘀滞未净，故通补两难，脉象反映虚中夹实、络瘀阴亏之病机。", ["坚", "洪", "数", "芤"]], "5281": ["病机", "脉芤大而涩，为瘀血内壅、新血不荣之征。原文谓“瘀血致壅，久嗽成劳”，又见“骨痿不能起床”“痰有臭味”，系肝著成痈、瘀滞不化。昨日大见瘀血后今日纯然芤，正是瘀血之明征，故不可一味贪补，当兼宣络。", ["芤", "大", "涩"]], "5282": ["兼症", "脉芤自汗甚，为阴血亏虚、阳气不摄之象。原文谓“痰中臭味太甚，黑痰未净”是活络方不能除，“脉芤自汗甚”是补摄方不可缓，又言“极虚极实”，说明瘀滞未净而虚象已著，故一通一补并进，脉芤正是虚象之据。", ["芤"]], "5283": ["其他", "原文仅言“脉较前敛戢”，未识具体脉名，属脉象动态描述。敛戢指脉势较前收敛，反映前服通补方后气机渐摄、虚浮稍减，故于新绛方内加半夏以化痰饮，余法仍旧，示病情向稳。", []], "5284": ["病机", "左尺脉独大，左尺候肾，独大主肾气不固、虚阳下浮。原文于通补方中“加封固肾气法”，正因尺脉独大提示下焦封藏失职，故须加固肾摄纳之品，以敛浮越之气。", ["大"]], "5285": ["病机", "左脉空大未敛，空为血虚不充，大为脉道松弛，主阴血亏虚、气不收摄。原文谓“精神较前虽好，犹宜收摄下焦”，故去龟板、五味子等滋腻之品，专事收摄下焦，脉空大未敛正是下元不固之征。", ["空", "大"]], "5286": ["其他", "原文仅言“脉少敛”，未识脉名，属脉势动态描述。少敛指脉较前收敛，反映通补间服后气机渐摄、虚浮减轻，故仍守通补二方间服如前，四帖继进，示病情平稳向愈。", []], "5287": ["兼症", "原文言“脉象少敛”而未识脉名，属脉势描述。少敛示脉气渐收，但“午后微热不寐”乃阴亏阳浮、痰浊未净之兼症，故饮食须“不可太过不及”，示脉虽敛而虚热未清，调理宜缓。", []], "5288": ["病机", "左脉实大坚牢，为邪实内结、肝风鸱张之象。原文谓情志重伤、君相火相应，初起如狂，医者攻风劫痰、辛温刚燥、苦寒直下，反助贼为虐。实大坚牢非虚证，乃阳火有余、内风震动，故勉以紫雪泄客热、定风珠济真阴，脉象示邪盛正伤、非吉兆。", ["实", "大", "坚", "牢"]], "5289": ["预后", "左脉仍然牢固，较昨日诸证俱减，舌苔黄黑、尺肤热、阳明络现。脉牢固示邪热深结未解，虽症减而脉未和，说明本身虚热与客气加临并存，非虚语。故仍照前方，再以清宫汤、化牛黄紫雪辈清透客热，脉牢固为邪势尚盛之征。", ["牢", "固"]], "5290": ["病机", "脉仍牢固数大，瘛疭肢厥虽止而狂如故、会厌不利。原文按阳盛并于上则狂，的系阳火有余，非极苦之药直折上盛之威，其势未必得减。牢固数大示火邪壅盛、小肠火腑非苦不降，痰亦因之而降，会厌庶可得利，脉象明示实火内结。", ["牢", "固", "数", "大"]], "5291": ["预后", "脉气大减，为邪势渐退之象，然原文谓阳升阴络、机不灵，说明虽脉减而清窍未利，余热犹恋胆络会厌。脉气大减示正气渐复、邪火渐平，故拟兼清会厌胆络之热，以善其后，脉减与机窍不灵并见，示病退而未净。", []], "5292": ["病机", "脉较昨日实大，稍进糜粥觉勇力培常，舌红黑。脉实大示阳火有余未清，虽胃气稍复而邪热仍炽，舌红黑为热灼阴伤之征。原文断为犹为阳火有余，说明脉象实大与舌红黑相应，邪火未敛，不可因食进力增而遽补。", ["实", "大"]], "5293": ["预后", "诸证与脉俱减，然未以净，苦药犹不能除，颊肿系客气，拟加辛凉。脉证俱减示邪势渐衰、向愈之机，但未净说明余热尚存，苦寒未能尽除，颊肿为客气未尽之征，故转用辛凉透解，脉减而未净是预后判断之据。", []], "5294": ["病机", "脉弦数而劲，初因肝郁久升无降，阳并于上则狂。弦为肝木、数为火、劲为木火相煽之象，原文谓卯中乙木盛时、岁风木司天，木火相煽，心体虚而心用强，间日举发气伏最深，已难调治，故勉与补心体泻心用两法。", ["弦", "数", "劲"]], "5295": ["预后", "脉势亦减，经谓脉小则病退是也。前用补心体、泻心用、摄心神已见大效，脉由大而小，示心气渐敛、狂疾向愈。操持太过伤心气之狂疾，脉小为邪退正复之征，故引经以证病退，脉势减与症效相应，预后转佳。", ["小"]], "5296": ["病机", "左脉弦劲、单弦，经谓单弦饮癖，弦为饮为痰之象。患者观戏后恶梦发狂肢厥，咳嗽块痰，乃痰饮内伏、阳气偏胜并于上所致。脉弦劲不柔，说明痰浊壅盛、肝阳偏亢，故前贤谓怪症多属痰，此症当从痰治，以弦脉为痰饮内结之据。", ["弦"]], "5297": ["病机", "左脉单弦为痰，今渐有和平之象，外证亦效，然形貌怯弱、色白而嫩、脉不壮，说明痰虽渐化而阳虚神怯本质显露。原文指出痰因惊起，惊后恶梦大汗，阳虚显然，故不可因攻痰见效而忘其虚怯，当于化痰中微加益气，脉不壮正是虚象未复之征。", ["弦"]], "5298": ["病机", "脉微滑数，微为虚象，滑主痰，数主热，合观为体虚有痰、痰热内扰之候。原文谓体虚有痰之证不能纯治一边，故于前法少加逐痰，说明此脉既示痰浊未清，又示正气不足，治疗须虚实兼顾，不可一味攻逐。", ["滑", "数", "微"]], "5299": ["病机", "右脉仍滑，滑为痰湿未净之象。前日稍加逐痰，痰出如许，大势安静但多怒，右脉仍滑说明痰浊虽减而未尽，气机尚欠调畅。多怒属肝气偏旺，滑脉不去则痰源未绝，故仍当续予化痰，不可遽补。", ["滑"]], "5300": ["病机", "六脉弦长而劲，弦主肝、主痛、主痰，长为气有余，劲为邪实坚结。大狂七年，言语错乱、叫号声嘶、欲见妇人，乃肝火痰热亢盛、阳气并于上之狂证。脉弦长而劲说明邪实正未大虚，前医多补虚少攻实，故病不愈，此脉正是可攻之据。", ["弦", "长", "劲"]], "5301": ["病机", "复诊脉弦长而数，弦长为肝火痰实未除，数则热象更著。前用轻剂加补阴而病势大重，说明邪实未衰、误补助火，故叫哮妄语加数倍。脉由劲转数，示相火鸱张，仍当重用苦药折其上盛之威，不可因久病体虚而姑息。", ["弦", "长", "数"]], "5302": ["病机", "脉仍洪数，洪为阳明气分热盛，数为热象，说明虽经苦寒折威、芳香开窍而愈，然热邪未清、相火犹炽。患者不戒酒肉，午节大开酒肉，致狂不可当，正是洪数之脉所主之热复炽，少阳相火挟制君主，故病复作，脉象示热盛未除。", ["洪", "数"]], "5303": ["病机", "脉沉弦细，沉主里、弦主痛、细主虚，合为脾肾阳气伤残、阴寒内盛之象。原文谓苦寒滑润伐其生发健运之常，致腹痛晨泄不食，脉沉弦细正由脾阳肾阳受损而来。三焦俱损，先建中焦，补土生金，肾关之虚亦可仰赖胃关，此脉示虚寒内伤之本质。", ["沉", "弦", "细"]], "5304": ["预后", "左脉搏大，左脉候肝肾，大为邪盛正衰之象。下焦肝肾吐血，上焦咳嗽，中焦不食，三焦俱损，脉大而失柔和，说明正气耗散、阴不敛阳，故断为不治。勉拟先建中焦，是于败局中求中气来复，非脉大主实热，乃虚损之脉大无根。", ["大"]], "5305": ["预后", "脉弦细而失音，弦为肝木偏旺，细为阴血不足，木火刑金则金碎不鸣。暮热不食、食则呕，是阴亏于下、胃气上逆，弦细之脉示肝脾阴血俱伤而气机不畅，故谓俱损难治，非外感失音可比。", ["弦", "细"]], "5306": ["病机", "形寒而六脉弦细，弦为阳气不舒，细为营血不足，时而身热乃虚阳浮越。原文断为先天不足，诸虚不足，故脉见弦细而非洪数，说明中气亏虚、阴阳俱弱，营卫不和，治以小建中法建中气以生营卫。", ["弦", "细"]], "5307": ["病机", "六脉弦细而紧，弦细为虚损，紧为劳伤阳气不摄、寒凝血脉。劳伤吐血而见紧脉，非实寒，乃中阳不足、血失统摄，故以诸虚不足归之，主以小建中汤温建中阳，使阳气复而血自归经。", ["弦", "细", "紧"]], "5308": ["病机", "六脉弦细，阳微之象。五更胃痛欲饮、得食少安、痛则背冷如冰，是太阳之阳虚累及阳明之阳虚，弦为阳微不运，细为阳气衰少。原文明言阳微，故只宜通补而不宜守补，通补者助阳气流通，守补则呆滞不行。", ["弦", "细"]], "5309": ["病机", "六脉弦细而紧，吐血遗精、胃口不开，是阳气不摄、中阳亏虚，紧为寒凝气结。然系酒客中焦湿热壅聚，不可与甘，故舍建中甘温而用辛淡微甘和胃，脉弦细紧示阳虚为本，湿热为兼，治法须避甘助湿。", ["弦", "细", "紧"]], "5310": ["预后", "业已见效、胃开得食，而脉尚弦紧，说明中阳未复、寒凝气机仍未畅达。弦紧为阳气不舒之象，症减而脉未和，故宜多服以渐复其阳，不可因症缓而遽停药，此以脉测预后、示守方之意。", ["弦", "紧"]], "5311": ["病机", "幼孩脉双弦而细紧，弦紧为胃阳不开、寒凝气结，细为形体羸瘦、气血不足。瘰疬结核、色白食少且呕，是胃阳不振、痰凝络脉，故与通补胃阳，使阳气得通、痰核渐消，非纯补所能奏效。", ["弦", "细", "紧"]], "5312": ["预后", "原文未点明具体脉名，仅言“脉有回阳之气”，是据呕止胃开、腹微胀等症推断阳气渐复之象。前药十二帖后呕止胃开，说明中阳渐苏，脉气随之转和，故称回阳之气；腹微胀为余邪未净、气机未畅，故加厚朴、杉皮消胀，胀消后转以化瘰疬痰核，脉象在此作为阳气来复的预后指征。", []], "5313": ["病机", "六脉弦紧，弦主气机郁滞、紧主寒凝收引，合见则示寒邪与气滞搏结于里。原文“胃痛，久痛在络”，说明病延日久，由气及血，络脉瘀阻，故弦紧之脉不独主寒，亦反映络脉拘急不通。治当和络，即缓其拘急、通其瘀滞，使弦紧得解而痛止。", ["弦", "紧"]], "5314": ["病机", "六脉弦细而紧，弦为气郁，细为阳衰血少，紧为寒凝，三象合见，原文断为“脏气之沉寒”“腑阳之衰”。阳虚不能腐熟水谷，故食难用饱、稍饱则䐜胀、嗳气；寒凝气滞则间有胃痛。此属阳虚损症，劳阳者多，故主温补脏腑之阳，非六味八味滋腻所宜。", ["弦", "细", "紧"]], "5315": ["预后", "原文言“脉之紧无胃气者和”，指原先紧而无胃气之脉已转为和缓，紧象渐去，是寒凝渐散、胃气来复之征。故痛楚已止、颇能加餐、神气亦旺，皆脉和之应。既已见效，仍守前方减川椒、丁香之刚燥，防其太过，再服以巩固，可定丸方缓图。", ["紧"]], "5316": ["病机", "原文对比初诊“脉紧”与念四日“脉和肢凉”，今诊脉虽不似初诊之紧，亦未复念四日之和，且肢凉，断为“阳微不及四末”。脉紧减而未和，说明阳气虽回而未充；阳微不能温煦四肢，故肢凉。加桂枝五钱者，取其温通经脉、助阳达于四末，使脉渐和而肢温。", ["紧"]], "5317": ["病机", "诸症向安而六脉尚弦，说明症状虽减，脉象未复。弦主气机不和、木郁克土，脾胃阳气未充，气机仍欠条畅，故脉尚弦。既云向安，则弦非实邪，乃脾胃阳虚、气机未和之余象，故与通补脾胃两阳，使中阳复则弦脉自和。", ["弦"]], "5318": ["病机", "病后六脉弦细而紧，原文断为“绝少阳和之气”。弦为木郁，细为形瘦血少，紧为寒凝，合见则少阳生发之气不振、阳和不布。形体羸瘦而胃旺，说明后天尚可支撑，故可守补；用“形不足者补之以气”法，温养阳气以复少阳冲和之象。", ["弦", "细", "紧"]], "5319": ["病机", "脉虚数为阴血不足、虚热内生之象。虚为正气亏，数为热扰，故头目眩冒、暮有微热；阴血不能充养，则饮食减少、面似桃花、身如柳叶，形瘦色浮。此属虚劳阴亏、虚火上浮之候，脉虚数正示正虚与虚热并存，非实热可攻。", ["虚", "数"]], "5320": ["病机", "脉虚弦而数，虚为阴精不足，弦为肝阳偏亢，数为相火妄动。面赤舌绛乃阴虚火旺之象，闻妇声则遗是肾失封藏、相火扰动精室。此脉此症示肝肾阴虚、相火不藏之病机，故令移居深处以避情志扰动。", ["虚", "弦", "数"]], "5321": ["治法", "三甲复脉汤为治法方药，非脉象描述。此方育阴潜阳、养血复脉，适用于阴虚阳亢、脉象细数或虚弦之证。原文未出脉象，故脉素取空，主旨为治法。", []], "5322": ["病机", "虚数脉主阴血不足、虚热内生。头时晕、心悸气短不寐，乃心肾阴虚、神不守舍；身微热、食少为阴亏及脾。此脉此症示心肾阴亏、虚热内扰之病机，故与补心肾之阴。", ["虚", "数"]], "5323": ["病机", "脉弦如刃，弦为肝脉，如刃示劲急失柔，乃肝络瘀滞、肝气横逆之象。吐血后左胁微痛、喉中如有物阻，是肝络瘀阻、气机不畅。治在肝络使血不瘀，则吐可止，止后补阴，紧扣弦脉主肝、主痛、主瘀之病机。", ["弦"]], "5324": ["预后", "原文言“又如刃之脉，已渐平减，但虚数如故”，刃脉渐平示肝络瘀滞得减、病势向缓；虚数如故则阴血未复、虚热尚存。此段以脉象变化判断预后，故归预后。", ["虚", "数"]], "5325": ["病机", "左脉坚搏主下焦血分瘀滞，右脉坚搏主上焦气分壅实。坚搏为邪实内结、气血不畅之象。原文举吐血各种不同，又述冲脉受寒、经不得行、倒送而吐，示瘀浊内阻、冲脉失降之病机，故忌柔润寒凉，议温镇冲脉、行至阴瘀浊。", ["坚", "搏"]], "5326": ["病机", "右脉浮洪，浮主上焦，洪为气分热盛。咳痰吐血、唇绛，乃上焦气分热盛、迫血妄行之象。右脉候肺，浮洪示热壅上焦气分，故治在上焦气分，清泄气热以止血。", ["浮", "洪"]], "5327": ["病机", "血后咳不止、进食不香，右脉不浮而仍洪，不浮示表热已减，仍洪则阳明气分热未清。洪为阳明热盛之脉，热灼肺胃故咳不止、食不香。兼养阳明之阴，是清余热、滋胃阴以善后。", ["洪"]], "5328": ["病机", "诸证俱退而进食不旺，右脉大垂尺泽，右脉主脾胃，大而垂尺泽为胃阴不足、虚热内扰之象，胃阴亏则纳化无力，故进食不旺。脉大非实热，乃阴亏不敛，故先与甘寒养胃阴，以滋胃津、清虚热，使脉敛食增。", ["大"]], "5329": ["病机", "六脉弦数，两关独浮，左更甚，弦为肝郁，数为郁热，关浮主病在肝脾。左关甚而右胁痛、胸中痞塞，是肝郁化火、络气不通，火迫血溢而吐血。故先理肝络，疏肝解郁、清络止血，使弦数得减。", ["弦", "数", "浮"]], "5330": ["病机", "左脉弦细数锋钢如刃，坚搏有力，弦细数为阴亏火旺，锋钢如刃、坚搏乃肝火亢盛、血热妄行之象。吐血而左手脉坚搏，病在下焦血分，火灼阴络，迫血上溢。故治在下焦血分，凉血降火、滋阴止血。", ["弦", "细", "数", "坚"]], "5331": ["病机", "脉数减而弦刚甚，数减示热势稍退，弦刚甚则肝郁未解、气机仍劲。刚劲之弦主肝木偏亢，虽数减而刚不减，说明郁火渐平而肝气未柔，仍需柔肝解郁，防其复燃动血。", ["数", "弦"]], "5332": ["病机", "劳伤吐血而脉双弦，引《金匮》大则为虚、弦则为减，虚弦相搏名曰革。革脉主男子失精亡血诸不足，弦为劳伤中气，虚为阴血亏耗，故以小建中汤建中气、和阴阳，使虚弦得复。", ["弦", "虚", "革"]], "5333": ["病机", "右脉空大，左脉弦，血后咳吐浊痰腥臭。空大为真液不守、阴亏不敛，弦为阴火上冲，火克肺金，故咳吐腥臭浊痰。非纯补纯清之症，须滋阴降火、清金化痰兼顾，然脉象已示惫矣。", ["大", "空", "弦"]], "5334": ["预后", "原文仅言脉少敛、痰咳亦减，未出具体脉名，故脉象要素为空。脉少敛示亢劲之势渐退，痰咳亦减为邪渐衰、正渐复之兆，故嘱切戒用心，防劳心耗神、扰动气血而致病情反复。", []], "5335": ["预后", "脉大敛戢，即大脉渐收而转小，古谓脉小则病退，是邪退正复、病势向愈之象，故颇有起色。若舌苔化去，则胃气渐和、浊邪尽化，预后更佳。此段以脉之敛戢判断病退，属预后之论。", ["大", "小"]], "5336": ["病机", "六脉弦细不数，弦为肝脉，细为阴血不足，不数则无实热。劳伤吐血后汗多足麻，乃阴血亏虚、肝脾失养，虚劳里急之象。脉不数说明非实火迫血，故以小建中汤温建中气、调和营卫，使气血自生，吐血自止。", ["弦", "细", "数"]], "5337": ["病机", "六脉弦数，弦主肝郁，数主有热。劳伤吐血而脉弦数，是肝郁化火、火迫血溢之象。然用建中汤者，盖劳伤中气，土虚木乘，虽见数脉，非实火可比，故以建中培土抑木，使中气立而肝火自平，血不复吐。", ["弦", "数"]], "5338": ["病机", "六脉弦劲，前用建中后脉已和而左手仍劲，左关候肝，劲为肝络瘀滞之征。胸前咳甚则痛、间有紫色之血，按语明言肝脉络胸，是肝络中尚有瘀滞。脉劲不退与瘀血相应，故与宣络法，俟瘀去则脉自柔。", ["弦", "劲"]], "5339": ["兼症", "六脉弦数，肝火未清；右寸独浮大而衄血，右寸候肺，浮大为风热上扰清道之象。原文谓清气在头，受微风，风热乘肺，迫血从鼻出。弦数为本有肝火，浮大独见右寸为新感风热，故暂与清清道之风热，标本兼顾。", ["弦", "数", "浮", "大"]], "5340": ["病机", "脉洪为阳热亢盛之象，周身痒不可当、狂吐血，是阳明热盛、火邪迫血妄行，兼热淫肌肤而痒。洪脉应此实火，故与大黄黄连泻心汤苦寒直折，泻心胃之火，火降则血止痒除，以后永不发，示中病即止。", ["洪"]], "5341": ["病机", "六脉洪数，面赤，酒客大吐狂血盛盆，洪数为三阳实火炽盛之脉。酒性湿热，积久化火，火迫血溢，故狂吐。与大黄黄连泻心汤泻火止血，一帖止、二帖脉平，脉平即火退之验；后复发血如故，仍用前法，证明脉证相应。", ["洪", "数"]], "5342": ["病机", "脉弦主肝，饱食就床困脾阳，脾失统血之职而吐血，此伤食吐血。脉弦非肝火，乃土虚木乘、脾阳受困之象。灶中黄土温脾摄血，使脾复统血之权，半月而愈，戒夜食以绝其困脾之因，脉弦随之而解。", ["弦"]], "5343": ["病机", "六脉弦紧，弦主肝郁，紧主痛主瘀。怒伤肝，肝郁气滞，血行不畅而成瘀，瘀阻肝络故两胁俱痛。原文谓怒伤肝郁必有瘀血，误补则壅滞难愈，故以活肝络为主，俟瘀血去净而后补虚，脉紧随之而松。", ["弦", "紧"]], "5344": ["病机", "脉弦紧虽减而未和缓，说明寒凝气滞、肝络不和之病机尚未全解。弦紧主寒主痛，胁痛虽大减而未净除，正是寒滞肝络、气血未畅之象。去桃仁加细生地，意在减破血之力，兼养阴以和络，防温燥伤阴。", ["弦", "紧"]], "5345": ["病机", "六脉弦细而紧，弦则为减，紧则为寒，细为阴血不足。怒伤吐血后，阴血亏虚，阳气亦弱，故脉见弦细紧。小建中汤复阳生阴，以甘温建中、调和营卫，使阴阳相生，寒减脉和。", ["弦", "细", "紧"]], "5346": ["病机", "小儿脉当数而反缓，缓为湿为寒，主脾阳不足、寒湿下注。粪后便血，前用黄土汤见效，仍照前法加刚药，去白芍、全当归之柔润，增温燥之力，以助脾阳摄血，针对寒湿未净之病机。", ["缓"]], "5347": ["病机", "酒客湿中生热，久而发黄，颜色暗滞，六脉俱弦。弦主湿主饮，亦主肝郁。其来也渐，非阳黄暴发，况粪后见红，为小肠寒湿，故脉弦而不数，示湿寒内蕴、非热毒发黄之机。", ["弦"]], "5348": ["病机", "诸症皆效而大势未退，左脉紧甚，紧主寒主痛，左脉候肝，说明肝经寒凝未散、气机仍紧。加熟附子、干姜温阳散寒，降香末行气降逆，针对寒凝肝脉、阳气未复之病机。", ["紧"]], "5349": ["病机", "面色青黄滞暗，六脉弦细无阳，弦细为阴血不足、阳气衰微，无阳则脉失温煦。胃口不振，为胃阳亦弱。暂与和胃，俟便红发时再服黄土汤，示当前以胃阳不振、阴寒内盛为主。", ["弦", "细"]], "5350": ["病机", "便红已止，饮食大进，诸症渐安，惟六脉细弦，右手有胃气，左手弦紧，痰多畏寒，胁下仍有伏饮。细弦主饮主郁，弦紧主寒，左手候肝，肝经寒饮未净，故与通补胃阳兼逐痰饮。", ["细", "弦", "紧"]], "5351": ["病机", "脉弦紧，痰多畏寒，冲气上动。弦紧主寒主饮，寒饮内停，冲脉之气上逆，故见痰多畏寒、冲气上动。与桂枝茯苓甘草汤合桂枝加桂汤法，温阳化饮、平冲降逆，针对寒饮上冲之病机。", ["弦", "紧"]], "5352": ["病机", "原文谓“六脉紧退，而弦未除”，紧脉主寒主痛，紧退说明冲气已止、寒邪渐减；弦脉主肝木、主气机不畅，弦未除提示肝气未和、冲阳未全复。故仍用前方续服，以温阳降冲为治，待弦脉转和则阳复。", ["紧", "弦"]], "5353": ["病机", "“脉仍弦紧”与“背畏寒”并见，弦紧为寒邪束表、阳气不伸之象，紧主寒，弦主痛与气机郁滞。背为阳，畏寒说明冲阳未复，寒邪留恋。故用桂枝加桂汤峻补冲阳，药后吐顽痰，是阳复驱邪之征。", ["弦", "紧"]], "5354": ["病机", "“脉仍弦紧，背犹畏寒”，紧脉主寒，弦脉主气机不利，说明寒邪未散、阳气未复，故背恶寒不止。原文断为“阳未全复”，仍守原方续服，以温通阳气、解散寒邪，待脉转冲和则愈。", ["弦", "紧"]], "5355": ["病机", "“脉之弦紧，亦未冲和”，弦紧为寒与气郁之象，冲和之脉未复，说明阳气未全复、寒邪未尽。又见“冲气微有上动之象”，是下焦冲阳不足，冲气上逆。故仍取桂枝加桂汤法，温阳降冲，以立春后阳气渐升之时调治。", ["弦", "紧"]], "5356": ["病机", "“六脉俱弦，左脉更紧”，弦主肝木、主寒湿，紧主寒。左脉更紧，左属肝，肝经寒湿偏盛。原文断为“小肠寒湿”，因寒湿下注，故粪后便红。虽自觉胸中热、背心如热水浇，然“所云热非热也”，乃寒湿郁遏、虚阳上浮之假热，故仍以黄土汤温阳渗湿。", ["弦", "紧"]], "5357": ["病机", "“阳虚脉弦”，弦为肝脉，阳虚则肝木失于温煦，气机不畅而脉弦。原文又言“素有寒湿痰饮”，寒湿痰饮内停，阻遏阳气，故脉见弦。治以蠲饮丸通阳渗湿而补脾阳，使阳复湿化，则弦脉自和。", ["弦"]], "5358": ["病机", "“脉之紧者亦减”，紧脉主寒，紧减说明寒湿渐退，但原文谓“寒湿未尽”，故紧虽减而未全去。背恶寒未罢，是阳未全复。此时当退刚药，行湿之中兼调和营卫，以防温燥太过，体现随脉象变化而调整治法。", ["紧"]], "5359": ["病机", "“六脉沉弦而细”，沉主里、主水，弦主肝郁、主饮，细主阴血不足。原文断为肝经郁勃、木穿土位之蛊胀，又经误治，摄少阴之阴，使阳不得行，阴凝日甚，故脉沉弦而细。伴耳无所闻、目无所见、口中血块，是血脉凝泣、阴阳俱损之危候。", ["沉", "弦", "细"]], "5360": ["病机", "六脉沉细如丝，沉主里主水，细主阴血不足、阳气衰微。患者孀居忧郁，肝郁日久，暴怒重忧致厥阴太阴䐜胀，水不得行，肿从跗起。脉沉细如丝说明阴寒内盛、阳气式微，水湿泛滥而正气已虚，故断非轻剂所能了，需温阳利水兼顾。", ["沉", "细"]], "5361": ["病机", "服温阳利水重剂后六脉丝毫不起，肿不消，便亦不长。脉不起说明阴寒痼结、阳气不能振奋，忧郁多年暴怒伤肝必有陈菀瘀滞。加鸡矢醴熬净烟、附子后小便稍通，肿渐消，说明病机为阴寒陈菀阻络、阳气不通，非单纯温补所能及。", []], "5362": ["病机", "六脉弦无胃气，弦为肝脉，无胃气则失冲和之象。患者悲痛太过、哭泣不休、食少衣薄，情志伤肝，肝气横逆克脾，致单腹胀、气喘不能食、羸瘦。脉弦无胃气说明肝郁至极而脾胃衰败，故无情草木难治有情之病，需先开其愚蒙使情志畅遂。", ["弦"]], "5363": ["病机", "脉弦细而紧，弦主肝郁，细主正虚，紧主寒主痛。不知饥、内胀外肿、小便不利，乃肝郁乘脾、寒湿内盛、阳气不运所致。脉弦细紧说明阳欲灭绝，阴寒内结，故需重加热以通阳，并遵岁气先调天和。", ["弦", "细", "紧"]], "5364": ["病机", "服前方后肿胀稍退，惟阳脉微弱。微弱为阳气虚衰之象，说明温通之后阳气仍未恢复，故加椒炭以温中散寒；大便不通加两头尖，去陈菀以通滞。脉微弱提示病机重点在阳虚不运，需继续温阳化气。", ["微", "弱"]], "5365": ["兼症", "服肝络药后胀满、胁痛、不寐少减，惟觉胸痛，小便赤浊。原文未载脉象，从症测机：肝脉络胸，胸痛乃肝郁未畅；小便赤浊为气湿下注。说明肝郁气滞、湿浊内蕴之病机仍在，治疗需继续疏肝通络、行气化湿。", []], "5366": ["病机", "脉缓为胃气渐复、冲和之象，故曰太阳已开而小便清通，阳明已阖而得寐能食。但䐜胀不除，病起肝郁，说明虽表里气机渐通，而肝郁未解、湿滞未化，故行湿之中必兼开郁，以疏肝解郁为要。", ["缓"]], "5367": ["病机", "脉弦细，弦主肝郁，细主正虚。腹胀且痛、大便泄、小便短、身不热，此寒湿伤足太阴。脉弦细说明肝郁乘脾、寒湿内盛而正气不足，脾运失职故泄、小便短，寒湿阻滞气机故腹胀痛。", ["弦", "细"]], "5368": ["病机", "脉迟而弦，迟主寒，弦主痛，亦主积。原文谓“滞下白积，欲便先痛，便后痛减，责之积重”，且“甚痛”，显系冷积内结、气机不通。寒积非温不化，故断为“冷积也，非温下不可”，脉象与积重冷痛之病机相合。", ["迟", "弦"]], "5369": ["预后", "先泄后滞下，古称难治，然“且喜脉弱，尚有生机”。脉弱为胃气未绝、邪不盛而正尚可支之象，较之实大急数者为顺。此段以脉弱判断预后，谓虽病程缠绵，非一时可了，但生机尚存，不可妄攻。", ["弱"]], "5370": ["治法", "脉沉有力，沉主里，有力为实，滞下胀痛太甚，便后少减而片时复痛，是积滞内结、邪实壅遏。原文议“纲开一面，用温下法”，因脉沉有力示里实可下，故以温下因势利导，使积去痛缓。", ["沉", "有", "力"]], "5371": ["病机", "右脉沉细弦伏，原文谓“阳微之极，浊阴太甚克之也”。沉细弦伏为阳气衰微、浊阴内盛、络脉不通之象。积气起于左胁注痛，属肝著，久病在络，故治宜宣通肝之阴络，使浊阴有出路，不可妄冀速愈而剥削阳气。", ["沉", "细", "弦", "伏"]], "5372": ["其他", "服通络药后“脉气大为回转”，是药力已行、气机渐通之佳兆，故“已见小效”。然右胁著席则咳甚，乃胁下支饮未除，故于前方去桃仁、川楝、小茴之破血温通，随证加减，脉大为回转示病势向愈。", ["大"]], "5373": ["病机", "左脉沉细阳微，沉细为阳气不振、湿浊内阻之象。症瘕痛发，舌苔厚白，面色淡黄而暗，皆湿浊困阳、气血凝滞之征。虽业已见效而未能除根，故再与汤药行湿通阳，以脉沉细阳微为据。", ["沉", "细"]], "5374": ["病机", "六脉弦细而紧，弦主肝郁，细主血少，紧主寒痛。十年瘕气，久病入络，肝郁血滞，寒凝脉络，故脉见弦细而紧。所用吴萸、乌药、川椒、良姜、小茴皆温通肝络、散寒止痛之品，正合此脉此证。", ["弦", "细", "紧"]], "5375": ["病机", "六脉弦紧，弦为肝郁，紧为寒痛。心下伏梁，一生忧泣，肝郁气结，又值燥金克木之年，痛愈甚矣。吐血亦络中寒，故与温络法。脉弦紧示肝寒络凝、气机壅塞，非易化之症。", ["弦", "紧"]], "5376": ["病机", "六脉沉细，沉主里、细主虚，合为阳气衰微、阴寒内结之象。瘕结脐左、经来必痛，乃寒凝肝脉、气血不畅所致；阳微则推动无力，故脉沉细而不起。原文直断“阳微”，正说明此脉非单纯血瘀，而是阳虚寒凝成瘕，主里虚寒结之病机。", ["沉", "细"]], "5377": ["病机", "脉短涩而迟，短主气结、涩主血滞、迟主寒凝，合示金气燥结、肝木抑郁，邪结日久成坚。脐左坚冷如石、不大便四十九日，屡下不通，正因寒下伤中，气机愈结。原文谓“金气之所结”“愈久愈坚”，此脉反映燥金敛结、气血涩滞之病机，非热实可下。", ["短", "涩", "迟"]], "5378": ["病机", "六脉弦紧，弦主肝郁、紧主寒痛，合为肝气郁结、阴络闭阻之象。大小便俱闭，自用大黄、五苓通利无效，反伤气机，故脉见弦紧。原文断“病因肝郁而成”，以开阴络法，说明此脉主肝郁气滞、下焦络脉不通，非单纯水停。", ["弦", "紧"]], "5379": ["病机", "脉弦为肝郁之征。血淋太多，先与导赤不应，细询由怒郁而起，转方活肝络，说明病本不在心与小肠之热，而在肝气郁结、疏泄失职，致血不循经而下淋。原文以“脉弦”为转方依据，正示弦脉主肝郁气滞、络脉不和之病机。", ["弦"]], "5380": ["病机", "脉弦数，弦主肝郁，数主热，合为肝郁化火、热迫血妄行之象。小便狂血，来势急迫，非仅膀胱湿热，原文明言“病因肝郁”，说明肝火循经下迫，血随火溢。此脉主肝郁化火、热伤血络之病机，与狂血相应。", ["弦", "数"]], "5381": ["病机", "脉洪数，洪主热盛、数主热急，合为暑热内盛、膀胱气化不利之象。痘后受暑，小便不通，玉茎肿亮蜷曲，乃暑热下注、湿热壅遏膀胱所致。原文以凉利膀胱为治，正说明此脉主暑热夹湿、下焦壅滞之病机，与茎肿尿闭相应。", ["洪", "数"]], "5382": ["病机", "六脉俱弦，弦主饮邪、主气郁，合示痰饮内停、湿痹阻络之象。金实无声，痰饮兼湿痹，小便白浊，皆因饮湿上泛、气机不畅。原文先与行湿，说明此脉主痰饮湿浊壅阻、肺气不宣之病机，弦为饮脉之常，与胸满声哑、便浊相应。", ["弦"]], "5383": ["病机", "脉弦细，弦主饮停、细主阳微，合为饮邪内伏、阳气不复之象。伏饮湿痹便浊，前服淡渗通阳三十帖，停药后饮又上泛，胸满短气、腰酸淋浊未除。原文谓“阳不复”，说明此脉主饮邪未化、阳气虚弱之病机，弦细正是饮停阳微之征。", ["弦", "细"]], "5384": ["病机", "久泄而脉弦，弦为肝木之象，春令木旺，木来侮土，脾受克伐故泄。原文称“木泄，侮其所胜”，正指肝木乘脾之病机，泄久不愈而脉仍弦，说明木气未平，主病在肝脾不和。", ["弦"]], "5385": ["病机", "前曾木泄，服小柴胡而愈，今脉虽弦而不劲，兼见缓象，是肝木已不亢，脾土渐复之征。大便复溏，粪后便红，原文断为小肠寒湿，故不再用柴胡疏木，转用黄土汤温摄，脉象由劲转缓正是病机转属虚寒的反映。", ["弦", "缓"]], "5386": ["病机", "胃不开、大便溏、小便不畅而脉弦，弦主肝木，木郁则乘脾，脾运失职故便溏；木气不疏，三焦水道不利故小便不畅；木郁克土，胃气因之不醒。此脉弦示肝脾不和、气机郁滞之病机。", ["弦"]], "5387": ["病机", "六脉弦细，面色淡黄，泄则脾虚，少食则胃虚，弦为木旺，细为血少，木旺乘土而中焦不能建立，化源不足，故望行经而不可得。原文议先与强土，正以脉弦细示肝脾两虚、中焦失运之病机。", ["弦", "细"]], "5388": ["病机", "右脉宽泛而缓，缓为脾土之本象，右脉候脾，宽泛缓和说明胃气稍苏，故胃口稍开。然泄则加添、小便不通，是脾虚不能运化水湿，水湿内停之象，故加实脾利水，脉缓在此示脾虚湿滞之病机。", ["缓"]], "5389": ["病机", "泄止胃稍醒，而脘中闷、舌苔滑、周身痹痛，六脉弦细而沉，弦细主肝脾不足，沉则病在里，苔滑为湿，湿阻气机故脘闷痹痛。原文先与和中、治痹在后，说明脉象示里虚夹湿、气机不畅之病机。", ["弦", "细", "沉"]], "5390": ["病机", "三岁痘点繁重，表虚而脉滑，滑主痰热内盛，心热恣甚，热毒壅盛于里，表气又虚，故原文谨防八九朝塌痒，与辛凉解肌透毒。脉滑在此示热毒内蕴、正气不足之病机，主痘毒炽盛而表虚。", ["滑"]], "5391": ["病机", "十天浆足色苍、形势圆绽，皮肤扪之平和，脉洪数有力，洪数为气血充盈、热象正盛之脉，痘多浆多乃炼气血而成，痛亦情理之正。原文断非陷症，脉洪数有力正合情理之正，示气血充盛、毒化成浆之病机。", ["洪", "数"]], "5392": ["病机", "左尺独大，原文断为“肾液不充，肾阳不安其位”，故“尺脉以大为虚”，属阴衰于下；右手三部俱弦、食入则痛，为阳结于上。形体长大、木火通明，阴素虚而火旺，故以阴虚为本、阳结为标，戒妄投大黄数下亡阴。", ["大", "弦"]], "5393": ["病机", "脉沉数有力而渴，沉主里、数主热、有力为实，合面色苍兼红、甫过五旬须发皆白，知平日用心太过、重伤其阴，阴衰于下而阳结于上，成噎膈之证。数而有力非虚火，乃阳结之征，故治法须辨阴衰阳结孰先孰后。", ["沉", "数"]], "5394": ["治法", "原文仅言“阳脉已起”，未出具体脉名，故脉象要素从缺。阳脉已起示阳气渐复，但恐过用阳药涸竭其液，故议进阴药、退阳药，属据脉转归调整治法，体现阴阳进退之间的权衡。", []], "5395": ["治法", "前日脉数，退阳进阴后今日转为脉缓而痰多。数去而缓来，知阳热已退；痰多则示中焦运化未复，故仍须进阳，俾中焦得运以复健顺之体。此段以脉数、脉缓之变定用药进退，属凭脉转归施治。", ["数", "缓"]], "5396": ["主病", "脉沉洪有力，沉主里、洪为阳热亢盛、有力为实，合胃中痛处高起如桃、按之更痛、面赤如赭、骨瘦如柴，断为食膈，实邪结于胃脘。洪而有力非虚象，故敢用大承气加牵牛下之，以通其结滞。", ["沉", "洪"]], "5397": ["病机", "六脉弦数，弦属肝郁，数主热，合先有痰饮咳嗽、误补误下伤津，又因肝郁性急致成噎食、不食而大便燥。原文断“治在阴衰”，知弦数为阴液亏而肝火郁，非实热可攻，故以养阴为要。", ["弦", "数"]], "5398": ["治法", "前方已见效而脉转迟紧，迟主阳微、紧主寒凝，知胃阳未复、寒滞内结，故与通养胃阳之法。此段以脉迟紧为据，说明虽效而阳气尚弱，治当温通并养，不可因见效而骤进阴柔。", ["迟", "紧"]], "5399": ["病机", "脉弦如丝而劲，弦主肝、细为阴血不足、劲示气逆不和，合大惊后肝气厥逆、呕吐频仍、误补大呕、米粒不下、四肢如冰，知肝阳上逆而胃阴耗竭、阳气不达四末，故用乌梅丸法柔肝降逆、温脏安胃。", ["弦", "细", "紧"]], "5400": ["病机", "六脉俱濡为湿邪弥漫之象，右寸独大则湿淫于中而肺气贲郁，肺失宣降，气逆作哕。原文明言「湿淫于中，肺气贲郁，因而作哕」，与伤寒阳明足太阴寒哕不同，故以宣肺气之痹为主，脉象揭示湿阻肺郁之病机。", ["濡", "大"]], "5401": ["病机", "「脉之濡者已解，寸之大者已平」，说明湿邪渐化、肺郁渐开，但胃中仍有饮邪隔拒上焦之气，不得下通，故于旺时哕甚。脉象由濡大转平，提示病机从湿郁肺痹转为饮阻胃气，故从阳明主治。", ["濡", "大"]], "5402": ["病机", "哕虽止而六脉俱数、右手更大，兼泄泻色黑、舌黄，数脉主热，右脉大主邪盛于阳明，黑泻舌黄为气分湿热下迫之征。原文断「气分湿热可知」，脉数大与湿热壅盛之病机相应。", ["数", "大"]], "5403": ["病机", "右脉洪数有力，洪为热盛，数为热急，有力为实，右脉候肺，肺金实热壅塞致「金实无声」，即肺热失音。原文以麻杏石甘汤证立论，脉象正合肺经实热壅遏、金实不鸣之病机。", ["洪", "数", "实"]], "5404": ["病机", "右脉洪数已减其半，音亦渐开，说明肺经实热渐退，金实渐开。脉象由洪数有力转为减半，与音声渐复相应，仍守麻杏石甘加半夏，清肺化痰以竟全功，脉症相符。", ["洪", "数"]], "5405": ["病机", "六脉弦细若丝，弦为虚劳脉象，细若丝示阳微极矣。咳嗽便溏、纳食不旺，由上焦损及中焦，初因遗精、继因秋湿冬咳，外邪未清而骤补致邪无出路。原文引「三虚一实先治其实」，脉象反映阴阳俱损兼外邪未净之虚实夹杂病机。", ["弦", "细"]], "5406": ["病机", "六脉弦细之极，较前更甚，原文断「阴阳俱损，急需用补」，然外感未净、喉音未清，故暂与理肺二帖后再诊。弦细至极示正气大伤，阴阳两虚，脉象与虚损病机相应，治当兼顾虚实。", ["弦", "细"]], "5407": ["病机", "服五帖音大出，说明肺气渐宣、金实已开，但脉滑耳。滑脉主痰湿内蕴，提示虽音出而痰浊未净，故仍与清音汤清化痰热以善其后，脉滑与痰湿留恋之病机相应。", ["滑"]], "5408": ["病机", "脉滑主痰饮内盛，原文谓“脉滑痰饮不尽”，说明服五帖后音虽清而痰饮未净，滑脉为痰湿留滞之象，故续用外台茯苓饮法健脾化饮，减辛药以防过燥。", ["滑"]], "5409": ["病机", "脉数主热，水气由面肿至足心，为风水兼热之证。经谓“病始于上而盛于下者，先治其上”，故议腰以上肿当发汗，用越婢加术汤法，数脉示热郁水停。", ["数"]], "5410": ["病机", "脉之沉部洪较有力，沉主里、洪主热，症本湿中生热，又有酒毒，虽饮咳见效而小便未畅，湿浊未化，热蕴下焦，故仍用凉利小便之苦辛淡法。", ["沉", "洪"]], "5411": ["病机", "浮脉主表，数脉主热，风水已愈其半而复感风寒，身半以上覆肿、口渴，浮数脉示表邪未解、热郁肌腠，故仍与越婢加术法发汗清热。", ["浮", "数"]], "5412": ["病机", "脉洪数主热盛，风水汗后肿水全消而渴而停水，洪数示热邪未清、水热互结膀胱，故尤宜凉开膀胱，清利水热。", ["洪", "数"]], "5413": ["病机", "右脉滑数，滑主痰湿、数主热，小便不甚长，胃中得热物微噎，示痰热内阻中焦，肺胃热壅，水道不利，故脉见滑数。", ["滑", "数"]], "5414": ["病机", "右脉数大未退，数主热、大主邪盛，小便仍未通畅，示肺热壅盛、水道不利，热邪未减，故仍宜凉肺以开膀胱，清上通下。", ["数", "大"]], "5415": ["病机", "右脉洪数，洪主热盛、数主热，肿未全消又发痰饮咳嗽，表通则小便长，示饮热互结、溢饮兼热，故照溢饮例与大青龙汤，外解表邪、内化饮热。", ["洪", "数"]], "5416": ["兼症", "肿减而咳增、衄未止，脉见洪数，说明热邪仍盛于气分，未能清解。洪为热盛气分、脉道充盈，数为热迫血行，故衄血不止；热壅肺气则咳增。肿减是水湿稍退，但洪数不去，示热势未衰，仍当清热凉血，不可因肿减而松懈。", ["洪", "数"]], "5417": ["病机", "咳虽减而脉仍滑数，滑主痰湿内蕴，数主热邪未清，说明痰热仍恋于肺，气机未复。肿未全消，是水湿与痰热互结，尚未尽化。脉症合参，病机为痰热壅肺、水湿未净，故咳减而脉象未转，仍需清化痰热、利湿消肿，不可早投温补。", ["滑", "数"]], "5418": ["主病", "因饮冰冻黄酒、冰果，内湿不行，又受外风，从头面肿起、头大如斗、不能卧，六脉洪大。洪大为水气太过、风热壅盛之象，风水相搏，泛溢肌肤，故先以越婢汤发汗，肿渐消。后便血如注，乃湿伤脾阳、统摄失职，用黄土汤温脾摄血而止，终以温补脾阳收功。", ["洪", "大"]], "5419": ["预后", "原文仅言\"共服十三帖而后脉转\"，未明指脉象，故脉象要素为空。\"脉转\"是服药后脉象由病脉转向和缓，为邪退正复之兆，属预后转归之辞。说明前方切中病机，药后气血渐和，脉随证转，可继续守方调理，不必更张。", []], "5420": ["病机", "跗肿、痰多咳嗽、口渴、茎中痛，右脉洪数。洪数为热盛于气分，右脉候肺与脾胃，热壅肺胃则痰多咳嗽、口渴；湿热下注膀胱则茎中痛、跗肿。故用凉利小便法，清泄湿热，使热从小便而去，脉洪数可随之而减。", ["洪", "数"]], "5421": ["治法", "\"脉之洪数者减\"，是服药后热势渐退之征，洪数减轻说明气分热邪已挫。故去石膏二钱，减其清热之力，防寒凉过剂伤中，并加他药随证调理。此段体现据脉调整治法，脉减则药减，以脉象进退为用药依据。", ["洪", "数"]], "5422": ["兼症", "脉洪数而小便反黄，洪数为热盛，小便黄为湿热下注之征，故加黄柏、滑石清利下焦湿热。茎痛止是湿热稍解，去甘草者，恐其甘缓助湿。脉洪数未减，说明上中焦热势仍在，湿热未清，故仍守清热利湿之法。", ["洪", "数"]], "5423": ["病机", "小便已长是水湿下行有路，肿未全消则湿邪未尽；脉弦滑，弦主饮、主气机不畅，滑主痰湿内盛，故咳嗽多痰。脉症相合，病机为痰饮内停、水湿未化，气机被阻。虽小便已长，仍须化痰蠲饮、健脾利湿，使痰湿尽化而肿消咳止。", ["弦", "滑"]], "5424": ["主病", "六脉弦细，弦主痛、主寒湿痹阻，细主湿邪困遏、气血不畅。身热头痛、腰痛肢痛、无汗，为寒湿闭表、经络痹阻之象；两目不明、食少，乃湿浊上蒙、脾胃受困。脉弦细与寒湿痹证相应，非单纯外感发热，故断为寒湿痹。", ["弦", "细"]], "5425": ["病机", "痹症已愈、便溏止、目复明、胃口增，说明寒湿渐化。此时脉稍数，数为热象，故断为寒湿有化热之象。原文以脉数作为化热之凭据，提示余邪未尽而偏热，治当平药逐化热之余邪，不可再温燥。", ["数"]], "5426": ["兼症", "又感暑湿而泄泻、腹胀，脉弦。弦主湿阻气机、木郁克土，暑湿困脾，气机壅滞，故腹胀泄泻并见。脉弦与暑湿内阻、脾胃升降失司相应，故用五苓法分利湿邪，使湿去则弦脉可缓。", ["弦"]], "5427": ["主病", "太阳寒痹，脉弦，背心板著而痛。弦脉主寒、主痛、主经脉拘急，寒邪痹阻太阳经脉，气血不通，故背心板滞而痛。脉弦与寒痹疼痛相应，说明病机为寒凝太阳、经气不利，属痹证主病之脉。", ["弦"]], "5428": ["预后", "原文仅言脉已回阳，未识具体脉名，故脉象要素为空。脉已回阳说明阳气渐复，是向愈之兆；但痛未止，说明余邪未净、经络未通。此段以脉回阳判断预后转佳，仍须继续服药以除痹痛。", []], "5429": ["预后", "脉仍小，阳未回，背仍痛。小脉主阳气不足、鼓动无力，与阳未回相应；背痛不止，说明寒痹未解。脉仍小而阳未复，提示病情尚未转机，故再服三帖分六帖缓图，以温阳通痹为要。", ["小"]], "5430": ["病机", "痹症夹伏湿胀痛，且有肥气，湿已化热，故六脉洪滑。洪为热盛，滑主湿痰壅盛，湿郁化热，脉道充盈，故见洪滑。原文明言本寒标热，先治其标，说明洪滑反映湿热标急之病机，与胀痛、肥气相应。", ["洪", "滑"]], "5431": ["病机", "尺脉洪数更甚，洪为热盛，数为热急，尺部候下焦，说明下焦湿热增剧。承前湿已化热之机，热邪深入下焦，故尺脉洪数更甚。此脉象提示标热未减而反进，当继续清化下焦湿热，不可因本寒而迟疑。", ["洪", "数"]], "5432": ["病机", "尺脉仍洪，洪为热盛之象，尺部候下焦，示下焦热邪未清。热灼肠道，故腹痛欲便；便后肛门热痛，乃热毒下迫肛门所致。此脉主里热实证，与腹痛、便后肛门热痛相应，故原方再服以清下焦之热。", ["洪"]], "5433": ["病机", "右脉大而数，大为邪盛，数为热象，右脉候气分，示气分热盛。热邪内蕴，故加黄芩以清热，去川朴之温燥。此脉主气分实热，与热证相应，故以清热为治。", ["大", "数"]], "5434": ["预后", "诸症向安，脉亦调适，胃口亦开，示邪退正复，脾胃功能渐复。脉调适为平和之象，无病脉可辨，故以调理脾胃立法，巩固疗效。此段主在预后，说明病势向愈。", []], "5435": ["主病", "脉弦短涩而紧，弦主痛、主寒，紧主寒主痛，涩主气血涩滞，短主气病。寒邪凝滞，气血不畅，故寒痹疼痛由腿连少腹，痛不可忍，甚至欲厥；兼痰饮胃痛，亦因寒凝气滞所致。此脉主寒痹疼痛之病机。", ["弦", "短", "涩", "紧"]], "5436": ["病机", "左脉稍长，长主气机不畅或邪气有余；仍然紧甚，紧主寒主痛，示寒邪未解，疼痛仍在。左脉候血分，紧甚说明寒凝血脉，气血不通。此脉主寒凝疼痛之病机未除，故再服前方。", ["长", "紧"]], "5437": ["病机", "左脉浮取弦，沉取宽泛；右脉浮取弦，沉取洪。弦主痛、主痰饮，洪主热盛。浮取弦示邪在表分，沉取宽泛示血瘀，沉取洪示湿热内盛。此脉示湿热与瘀血互结，故经行紫黑、腰腿少腹痛，经不调。治湿热用汤药，治瘀血用丸药。", ["弦", "洪"]], "5438": ["主病", "脉弦，弦主痛、主寒、主痰饮。寒湿为痹，湿阻经络，气血不通，故背痛不能转侧，两腿拘挛，手不能握，口眼歪斜；畏风自汗，舌苔白滑，面色昏暗且黄，睛黄，大便闭，皆寒湿内蕴之象。此脉主寒湿痹痛之病机。", ["弦"]], "5439": ["误治", "脉洪数，洪为热盛，数为热象，示热邪炽盛。误服桂、附、人参、熟地等补阳之品，助热伤阴，湿热不攘，故面赤、小便闭、身重不能转侧、手足拘挛。此脉主湿热壅盛之病机，与误治后热象相应，故以极苦通小肠、淡渗利膀胱为治。", ["洪", "数"]], "5440": ["病机", "六脉弦细而紧，弦主痛、紧主寒，细为湿滞血少。两腿紫绛肿、细疮如痱、酸痛不能立，乃寒湿著于下肢经络，气血痹阻不通，故脉见弦细紧。窦氏称苏木腿，正言寒湿著痹之候，脉与腿肿疮痛相合。", ["弦", "细", "紧"]], "5441": ["病机", "六脉洪大而滑，洪大为热盛，滑主湿痰。腰酸腿软不能跪拜、间有腰痛，前医补阴日重，说明非虚乃湿热下注、痿躄之候。湿热壅于阳明，脉道充盈故洪大而滑，与诸痿独取阳明法相应。", ["洪", "大", "滑"]], "5442": ["病机", "六脉反沉洪，沉为水气内伏，洪为假热外现。肝郁挟痰饮、肾水上凌，心悸短气、腹胀胸痹，皆水寒射肺凌心之症。原文谓水极而似火，正言水饮内盛反见洪象，非真火也，故以蠲痰饮伐邪降肝逆为治。", ["沉", "洪"]], "5443": ["病机", "脉洪大，痰饮夹痹、肾水上凌，心惊悸短气、腰脊痹痛、小便短腹胀脐突，内外经络脏腑皆痹。洪大为邪盛气壅、水饮化热之象，开太阳之痹、行痰逐饮，故与大青龙合木防己汤法，脉症相参以决治法。", ["洪", "大"]], "5444": ["病机", "脉洪数，洪为热壅，数为热急。行痰开痹不应，少腹胀、小便短浊而臭，是湿热内结下焦、邪无出路。洪数示湿热化火之势，故先开支河利小便，使湿热有出路，再商后法，脉象为湿热壅盛之据。", ["洪", "数"]], "5445": ["病机", "六脉洪大，湿已化热，屡利小便不应，是热壅肺气、痹阻太阴。洪大为热盛气分，非重用石膏宣肺热不可。诸痹独取太阴，正因脉洪大示热在气分肺经，故以清宣肺热为治，脉象定治法方向。", ["洪", "大"]], "5446": ["预后", "脉象方小其半，是石膏用至二斤余后脉势渐减之象，然少腹胀甚、小便不畅、腰痛胸痛，邪无出路。脉小半示药力已挫其势，但痹结十年误补固结，必得小便畅行方有转机，此段以脉象变化判预后与转机。", []], "5447": ["治法", "脉大而小便不利，大示邪热壅盛，小便不利为湿热无出路。用此方小便利则去滑石，是据脉大与小便通利与否调整治法，脉大为邪盛之征，小便利则滑石渗利可去，体现脉症合参、随证加减之法。", ["大"]], "5448": ["预后", "原文以“六脉已小”为据，引经“脉小则病退”，说明大用石膏后邪热渐衰、脉随病减，故脉小为病退之兆。又申“脉病人不病者死，人病脉不病者生”，强调脉与病相应则生。现病归下焦血分，兼本有肝郁，脉退仅示暂退，不可恃脉小即谓病愈。", ["小"]], "5449": ["病机", "初六日“脉复洪大”，承前日“六脉已小”而言，脉小后复见洪大，说明邪热再度鸱张、病势反复。洪大为阳热亢盛之象，与前方大用石膏清泄之后脉复洪大相应，提示热邪未尽或复燃，故须继续随脉辨治，不可因一时脉小而松懈。", ["洪", "大"]], "5450": ["预后", "痹症夹痰饮疝瘕而“六脉洪大”，用诸痹独取太阴法后“脉洪大者小”，引《难经》“人病脉不病者生”，说明脉平为佳兆。但“脉虽平而瘕胀痹痛未除”，知脉平不等于病除，久病在络，故以乌药散、丸药缓通；并嘱“脉若复大，仍服前方”，见小即止，示以脉测进退。", ["洪", "大"]], "5451": ["病机", "原文“脉本洪数”，洪数为阳热之象，主痹症夹痰饮之热邪偏盛。前用辛凉脉减，通络散、瘕丸散亦效，说明药中病机。现“六脉中部仍洪，但不数”，中部候脾胃，洪而不数示热势已挫而未尽，故议暂用辛凉宣肺，继续清透余热。", ["洪", "数"]], "5452": ["病机", "“右脉更大，小便反短”，右脉候肺，右脉大而小便短，说明肺气不降、通调失职，水热壅于上焦，气化不行。故用苦辛淡法，于前方内加味，以苦降辛开、淡渗利水，使肺气降而小便通，脉大随之可减，体现凭脉辨肺气壅滞之病机。", ["大"]], "5453": ["病机", "原文追溯“以右脉洪大之故，痹症甚重，治在肺经”，右脉洪大主肺经热壅，故取诸痹独取太阴之法。今“右脉平而左脉大”，右平示肺热已减，左大则病转厥阴肝络，故“不得著于前议”，暂与泄厥阴之络。脉之左右更移，反映病机由肺及肝、久病入络。", ["洪", "大"]], "5454": ["兼症", "本段未识脉名，纯述症候：“左胁痛胀，卧不著席，胸亦闷胀，气短”，并明言“肝脉络胸之故”。左胁为肝之分野，肝络布胸，肝郁气滞则胁胀胸闷、气短不得卧。虽无脉象可凭，然症属肝络壅滞，与前后文肝郁、久病在络之病机一脉相承。", []], "5455": ["病机", "“痰饮肝郁，脉弦细，气上冲胸”，弦主肝郁、饮邪内停，细主正气不足、饮阻脉道。弦细并见，说明肝郁夹痰饮、本虚标实，饮随肝气上逆故气上冲胸。脉弦细与痰饮肝郁、气逆之症相应，为辨证之据。", ["弦", "细"]], "5456": ["预后", "此段仅记“十五日脉缓”，承前案服药后脉象转缓。缓为胃气渐和、病势向安之象，非病脉之缓，故属预后转归。原文未言其他症候，只以脉缓示正气渐复、邪势渐退，故续服前方。", ["缓"]], "5457": ["预后", "“十六日脉缓甚”，较前日之缓更为明显。缓甚在此非湿盛之缓，而是胃气冲和、邪退正安之象，故仍服前方。原文只载脉象与服药，未列兼症，可见以脉缓甚判断病势向愈，属预后观察。", ["缓"]], "5458": ["兼症", "“脉浮”而见筋骨酸痛、气短、五心烦热，原文明言“新感暑湿之气”。浮脉主表，暑湿外袭肌表，故脉浮；湿阻经络则筋骨酸痛，暑热内扰则五心烦热，气短为湿阻气机。治以辛凉与三焦，是浮脉主新感之兼症。", ["浮"]], "5459": ["病机", "“脉小于前”，背痛腹胀不减、二便不爽、非嗳则哕，为湿郁气滞、痹阻不通之候。脉小于前，示邪郁日深、气血受阻，脉道不畅而变小，非正气虚少。故与宣痹开郁、兼去陈莝，以脉小参合胀满哕逆，断为郁痹之病机。", ["小"]], "5460": ["病机", "“寒湿发痹，脉缓甚，中有痰饮”。缓甚在此主湿，寒湿内蕴、痰饮停聚，湿性濡滞故脉缓甚；湿阻经络则为痹。原文以脉缓甚合寒湿痹症与痰饮，说明湿邪偏盛、痰饮内停之病机，非胃气之和缓。", ["缓"]], "5461": ["病机", "“脉弦紧”，主痰饮痹症症瘕，因燥气而发。弦为饮邪、为痛、为症瘕，紧主寒主痛；痰饮内结、燥气外引，脏腑经络俱痹，阳气不通故肢冷畏寒。脉弦紧正合饮结寒凝之病机，故峻与通阳以破阴结。", ["弦", "紧"]], "5462": ["病机", "“痹痛，饮咳，脉弦细”。弦主饮、主痛，细主饮邪内结、气血不畅；痰饮内停则咳，痹阻经络则痛。脉弦细合饮咳痹痛，示饮邪内郁、络脉不利之病机，非单纯虚象，故以饮痹并治。", ["弦", "细"]], "5463": ["病机", "“冲气上动畏寒，脉沉细”。沉主里、主气逆于内，细主阳衰气弱；冲气上逆而畏寒，是下焦阳虚、冲脉失摄，气逆于上。脉沉细正合阳虚冲逆之病机，故用桂枝加桂汤法直伐冲气，温阳降逆。", ["沉", "细"]], "5464": ["病机", "大寒节冲气未止而脉反弦紧，弦主气逆、紧主寒凝，冲气上逆本应缓和，今反见弦紧，说明寒邪束表、冲气内郁，气机不得下降。原文以「脉反弦紧」提示病势未减，故于原方内加药，属据脉辨病机未平、需继续调治。", ["弦", "紧"]], "5465": ["预后", "原文「脉中阳气生动」为纯描述，指服药二帖后脉象由沉弱转为有神，是阳气来复之象。冲气平、畏寒止与脉中阳气生动相应，说明药力已振中阳、冲逆得降，故仍守化症回生丹与奇经丸缓图，属预后转佳之判断。", []], "5466": ["主病", "风淫末疾，两手发软不能持物、脚亦时软，脉弦数。弦主风动、数主热，风热淫于四肢末梢，筋脉失养而弛软。原文点明「风淫末疾」与「治以辛凉」，脉弦数正合风热之邪，故主风热伤筋之痿软证。", ["弦", "数"]], "5467": ["病机", "「脉稍平」为纯描述，示病势略缓。原文辨渴止非因热解，而是饮居心下、格拒心火，水饮内停为本；微恶寒则营卫不和。脉稍平说明饮邪未再鸱张，故仍以蠲饮为主，兼和营卫，属据脉测饮邪病机尚存。", []], "5468": ["妇人", "痰饮哮喘、咳嗽声重有汗，六脉弦细，且有七月之孕。弦主饮邪内结、细主正虚，饮停肺胃而脉道不充，故见弦细。妊娠七月而病痰饮，须顾胎气，故用小青龙去麻辛，避发散太过，属妇人妊娠兼痰饮之辨。", ["弦", "细"]], "5469": ["病机", "寒饮误服苦寒坚阴，改用辛温后右脉始大、左脉仍弦细。右脉大是阳气渐复、寒凝稍开；左脉弦细示饮邪未化、阴分仍滞。咳嗽反重乃温药启其封固、痰欲外出之象，故再以温药兼滑痰，属据脉辨药后病机转归。", ["大", "弦", "细"]], "5470": ["兼症", "原文未识脉名，「右脉已退」为描述，示病势少减。然寒热汗多、胸痹，恐成漏汗而阳愈虚，饮更难愈。故议桂枝加附子护表阳，去甘草因肋胀，合栝蒌薤白通中上清阳，属据症防变、兼顾兼症之治。", []], "5471": ["主病", "脉双弦而紧，弦主饮、紧主寒，双弦更示寒饮内盛。原文历举不欲饮水、痰清不黏、咳而呕、背恶寒欲近火、面淡黄唇淡白，皆寒饮乘胃、卫阳不足之征。故法当温中阳护表阳，用小青龙去麻杏加味，主寒饮胃咳之病。", ["弦", "紧"]], "5472": ["病机", "酒客脉弦细而沉，弦主饮邪内停，细为湿滞脉道，沉则病在里。原文喘满短气、倚息不得卧，是水饮上射于肺；胁连腰痛、恶风寒有汗，乃内水招外风，表里同病。舌白滑而厚亦水湿之征，故断为内水招外风，主小青龙去麻辛证。", ["弦", "细", "沉"]], "5473": ["治法", "痰饮喘咳服小青龙已见效，然脉迟缓，迟缓属脾阳不振、水湿不化之象，说明饮邪虽减而脾运未复。原文谓小青龙非常服之品，故议外治脾法，从脉迟缓看出病本在脾，当以温运脾阳、化湿蠲饮为治，不再专恃发表逐饮。", ["迟", "缓"]], "5474": ["病机", "左脉浮弦沉紧，浮弦为风饮上泛之象，沉紧则水寒内结。原文痰饮喘咳、自汗而势甚凶危，正合外寒引动内饮、饮邪迫肺之机。紧脉主寒主痛，沉紧示饮结于里，故议小青龙加杏仁厚朴，去麻辛以避过散，专于降气化饮。", ["浮", "弦", "沉", "紧"]], "5475": ["预后", "脉现单弦，弦为饮脉，喘止咳喊、眩冒未宁，是饮邪未尽、清阳被蒙。原文言太阴属土既重且缓，万不能一时速愈，又谓痰饮五年岂三五日可了，明示此属久病缓图，脉单弦示饮邪尚存而正气未复，预后需假以时日。", ["弦"]], "5476": ["病机", "脉弦细而沉，弦主饮，细主湿滞，沉主里。咳嗽倚息不得卧、胸满口渴，是饮邪停胸、肺气不降，水停而津不上承故渴。此与酒客条脉同证近，皆属内饮为患，故仍用小青龙去麻辛法，专于温化里饮。", ["弦", "细", "沉"]], "5477": ["病机", "服小青龙已效，喉哑知渴，脉见微数。微为邪衰，数为饮郁化热之象，原文断为痰饮欲去，是饮邪渐退而余热未清，故转用辛凉开提肺气法，从脉微数看出病机由寒饮转热，治法随之而变。", ["微", "数"]], "5478": ["病机", "脉弦缓，弦主饮邪，缓主湿滞脾弱。嗽不欲饮、倚息不得卧、胁痛自汗不寐，是饮停胸胁、肺胃不和。弦缓并见，示饮邪未盛而脾运不健，故议小青龙去麻辛，加杏仁苡仁降气渗湿，重加半夏以蠲饮和胃。", ["弦", "缓"]], "5479": ["病机", "饮家眩冒，脉洪滑而沉。洪滑为饮邪壅盛、水气太过之象，沉则病位在里。眩冒乃饮停心下、清阳不升所致，脉洪滑沉正合水饮内盛之机，故用白术泽泻汤法，健脾利水以除饮，使水去则眩冒自止。", ["洪", "滑", "沉"]], "5480": ["病机", "脉沉微数，沉主里、微主阳虚、数主虚热或邪扰。此段仅录脉象，未出症候，然沉微并见，示阳气衰微于内，数则虚阳躁动或邪热内郁。脉沉微数为里虚阳弱兼有虚热之象，主病在里、阳气不足，与虚损、劳倦、内伤发热等症候相应。", ["沉", "微", "数"]], "5481": ["主病", "脉洪数，洪为阳盛气浮，数为热盛。痰饮本属阴邪，今脉洪数，是饮郁化热、痰热内壅之象。原文见咳嗽、倚息不得卧、有汗、胸痹，皆痰热上壅、肺气不降、胸阳痹阻所致。洪数之脉正应痰饮化热、邪实于上之病机，主痰热咳喘胸痹。", ["洪", "数"]], "5482": ["病机", "脉沉细而不调，沉主里、细主虚，不调为阳气衰微、气血运行失序。原文谓中焦痰饮、下焦浊饮为患，阴邪上僭，喘满短气、心悸气上阻胸、倚息不得卧，皆阴浊上逆、阳虚不能制阴之候。年高阳气本衰，阴邪僭上，故脉沉细不调，主阳虚阴盛、痰浊上逆之病机。", ["沉", "细"]], "5483": ["病机", "六脉俱结，结为脉来缓而时一止，主气血痰食阻滞、脉道不利。原文谓疟邪伤胃、土虚邪实，且有块痰寒滞经脉隧道，故脉气结而不畅。结脉在此示痰寒壅阻、经脉隧道不通之病机，与块痰、寒滞相应，属邪实阻滞之候，故先治其实。", ["结"]], "5484": ["误治", "脉洪，洪为邪盛气浮。原文述脊痛痹、右腿偏软痿、咳嗽而喘支饮射肺，日久不愈，皆误补用熟地等壅塞隧道所致。误补壅塞，邪不得泄，郁而化热，故脉洪。此洪脉示误补致邪壅化热之病机，与痹、痿、支饮诸症相应，属误治变证。", ["洪"]], "5485": ["预后", "脉之洪者减，谓前之洪脉已见减退。原文痹夹痰饮，与开痹蠲饮法后痹解而饮未除，洪脉随病减而减，示邪势渐退、药已中病。脉洪减为病减之征，故曰病减者减其治。此段以脉象变化判断病情向愈，主预后转佳，与痹解饮未除之候相应。", ["洪"]], "5486": ["主病", "脉弦细，弦主饮、主痛、主气机郁滞，细主湿阻脉道、气血不足。原文暑湿行令，胃不开、渴而小便短，暑湿困阻中焦，气化不利，故脉弦细。弦细示暑湿内蕴、脾胃气机不畅之病机，与胃不开、渴、小便短相应，主暑湿中阻之病。", ["弦", "细"]], "5487": ["主病", "六脉俱弦，弦主饮、主气郁。原文痰饮之质，冒暑欲呕，虽渴甚难用寒凉，是痰饮内伏、暑邪外触，饮邪阻遏气机，故六脉俱弦。弦脉示痰饮内盛、气机郁滞之病机，与痰饮、冒暑欲呕相应，故用局方消暑丸法，主痰饮夹暑之病。", ["弦"]], "5488": ["病机", "脉沉细为湿困中焦、胃气不醒之象。沉主里，细主虚，湿浊内阻则胃不开，故减食。方中猪苓、泽泻、滑石分利湿浊，加藿香梗、广皮、益智仁芳化醒胃，正合脉证。", ["沉", "细"]], "5489": ["病机", "脉缓气歉，缓为湿滞，气歉乃暑湿伤气。头胀胸闷，暑必夹湿，湿阻气机则清阳不升、胸阳不展。脉缓不数，说明湿重于热，气分受困，故以暑湿合邪论治。", ["缓"]], "5490": ["病机", "六脉阳微，乃暑湿之余，阳气未复。小便白浊，为湿浊下注，气化不利。阳微则分利需顾护阳气，故与分利法，使湿浊从小便去而阳不伤。", ["微"]], "5491": ["主病", "脉双弦为痰饮内停、饮邪偏盛之象。弦主饮、主痛，双弦则饮邪结聚。痰饮喘咳，饮犯肺胃，气逆不降，故与小青龙法温化寒饮。", ["弦"]], "5492": ["病机", "脉弦数，弦主饮、主肝，数主热。悬饮者水在肝也，饮结胁下则胁动而喘渴；外风未净，风与饮搏，故脉弦数。此水饮与风热相兼之候。", ["弦", "数"]], "5493": ["主病", "脉弦数，弦为饮邪结聚，数为饮郁化热。悬饮水在肝，胁痛而喘咳，饮停胁下，肝络不和，肺气上逆。脉证合参，主悬饮病。", ["弦", "数"]], "5494": ["其他", "脉如故，说明病机未变，仍守前法。口水减、牙痛，为兼症变化，而脉象无进退，故再服四帖，以观后效。此段重在凭脉守方。", []], "5495": ["病机", "六脉洪数，右寸独大，洪数为肺胃热盛，右寸独大则热壅肺金。酒客痰多，酒湿化热，痰热交阻，肺热之至，故脉象洪数而右寸独显。", ["洪", "数", "大"]], "5496": ["主病", "脉洪数，右大于左，洪为气分热盛，数为热象，右脉大主肺胃热壅。喉哑痰多乃热灼肺津、痰热阻喉所致。戒油腻者，防助湿生痰、增热碍运。此脉此症，主痰热壅肺之病机，与喉哑、痰多相应。", ["洪", "数"]], "5497": ["病机", "右寸脉独大，右寸候肺，独大主肺金实热，故称“金实无声”，即肺热壅盛致喉哑失音。已效未全愈，仍守前方清肺泄热，石膏用至三百数十两，可见热势之重。此脉主肺实热壅之病机，与无声、痰热内盛相应。", ["大"]], "5498": ["预后", "六脉弦细短涩，弦主饮、细主虚、短涩主血少气滞。吐血三年不愈，兼痰饮咳嗽、五更出汗，乃阳络伤而血上溢，久病阳欲亡。原文斥“见血投凉、见血补阴”之弊，谓此症阳欲亡矣，已难数治，脉症相合，预后不良。", ["弦", "细", "短", "涩"]], "5499": ["病机", "脉和缓、稍和缓，为胃气渐复之象。饮食已增，得谷者昌，故方无可转；午后五心烦热如故，仍用甘温除大热法。因脉稍和缓，去干姜炭之温燥。此脉示中气渐复而虚热未清，与食增、烦热并见相应。", ["缓"]], "5500": ["病机", "脉仍紧、弦紧如故，弦紧主饮邪内伏、气机不畅。汗敛食增、血不吐，诸症向安，而脉象未变，说明痰饮痼疾未除；咳甚欲呕，亦饮邪上逆之征。故去五味、减甘草，防酸收甘缓碍饮，仍守温化。", ["紧", "弦"]], "5501": ["病机", "脉弦细如故，弦主饮、细主虚，饮邪未化而正气已伤。咳嗽日减而夜甚，夜属阴，阳微阴盛可知；午后身热已减，惟食后嘈杂、胸中有水状，少时即平，乃饮停中焦、胃气不和之象。脉症合参，主饮邪内停、阳微阴盛。", ["弦", "细"]], "5502": ["病机", "脉弦数，弦主饮、数主热。汗停嗽减、五心烦热亦减，而脉仍弦数，夜间咳甚，服热药反不渴，饮尚重也。说明饮邪内伏、郁而化热，热药未能化饮，反见不渴。原文谓“病痰饮者，冬夏难治”，示饮病缠绵。", ["弦", "数"]], "5503": ["病机", "脉弦紧不数，弦紧主饮邪内盛、气机凝滞，不数则热象不显。仍不知渴，正是饮停不化、津不上承之征。前方已服四帖而脉症如此，故仍守原方加味，以温化饮邪。此脉主饮邪内停之病机，与不渴相应。", ["弦", "紧"]], "5504": ["病机", "脉弦紧如故，说明痰饮内伏、寒邪未解之病机仍在。弦主饮、紧主寒，呛咳、舌苔白滑皆为寒饮上逆之象。脉症相符，故仍守温化之法，加桂枝、干姜以增强温阳化饮之力，使寒饮得温而散。", ["弦", "紧"]], "5505": ["病机", "短涩渐退而弦细如故，说明气滞血涩稍减，但痰饮之本未除。弦主饮、细主虚，脉象由短涩转弦细，反映饮邪仍重而正气渐伤。故仍以桂枝、干姜、茯苓温阳化饮，针对痰饮内停之病机继续施治。", ["短", "涩", "弦", "细"]], "5506": ["病机", "左脉沉细、右脉弦紧，左候阳气不足，右候饮邪未净。咳减而脉仍弦紧，说明饮未尽除；遍身骨痛为久病劳损之征。故以甘温调营卫、复胃气为治，气旺则饮化，体现劳者温之、病减者减其治的思路。", ["沉", "细", "弦", "紧"]], "5507": ["病机", "六脉俱弦细，弦主饮、细主虚，说明伏饮内停而正气不足。眩冒昏迷、胸中如伤油腻、饮水多则胃不快，皆伏饮上泛之象。脉弦细而非虚大，故不可恣用熟地、六味滋腻之品，当先逐饮，再缓图湿热阳痿。", ["弦", "细"]], "5508": ["病机", "六脉纯阴、左脉弦甚，经谓单弦为饮澼。弦主饮，阴脉无阳说明饮为阴邪、腻补药闭阻阳气。面色光亮为水气外现。故用半夏汤、小青龙去表药加广皮、枳实以和饮，针对饮邪内停、阳气被闭之病机。", ["弦"]], "5509": ["病机", "原文仅言脉象较前生动，未列具体脉形，故脉象要素为空。胃不和因土恶湿而阳困，昨用纯刚大燥复胃阳后脉转生动，说明胃阳已有来复之机；但小便白浊，湿气尚未畅行，胃终不得和，故以开太阳阖阳明法通利湿浊。", []], "5510": ["病机", "脉弦主饮，痰饮喘咳为饮邪上逆犯肺之象。弦脉应饮，饮停则肺气不利而喘咳。故用小青龙去麻辛，加广皮、枳实以理气化饮，针对痰饮内停、肺失宣降之病机施治。", ["弦"]], "5511": ["病机", "脉沉细弦弱，沉细弱主虚、弦主饮，合为阴脉，说明饮为阴邪、阳气不足。咳嗽夜甚、久而不愈，为饮邪内伏之征。饮为阴邪故脉见阴象，最忌补阴，补阴则助阴碍阳，故曰补阴必死，当以温化饮邪为治。", ["沉", "细", "弦", "弱"]], "5512": ["病机", "寒热已止而脉转微弱，说明邪气已退而正气未复，阳气偏虚。微弱之脉主气血不足、阳气衰微，故去蔻仁、青蒿等清透之品，加桂枝、干姜温阳散寒以治咳，是据脉辨为正虚寒咳，以温药扶阳复脉。", ["微", "弱"]], "5513": ["病机", "咳减寒热止、胃开而脉尚细小，细小主气血未充、余邪未尽。脉症相参，知大邪已去而正气尚弱，故效不更方，守前法缓服至不咳为度，是据细小之脉判断正虚未复、余嗽未清，宜守方缓图。", ["细", "小"]], "5514": ["病机", "六脉弦紧主寒饮内伏、卫阳被遏，右脉沉取洪大则饮郁化热之象。舌白滑、喘咳无汗、浮肿，正合溢饮寒束饮溢之机，故从腰以上肿例，用大青龙汤去甘药，取其重而滞，以发汗散饮。", ["弦", "紧", "洪", "大"]], "5515": ["病机", "溢饮脉紧、无汗喘咳浮肿，紧主寒邪束表、饮邪内停。昨用大青龙得汗，肿消喘咳减，紧脉示表寒未尽、水饮未净，故续与开太阳阖阳明法，外解表寒、内调中焦，以竟其功。", ["紧"]], "5516": ["病机", "悬饮脉弦、左胁不快，弦主饮邪停聚、肝气不舒，水在肝经胁下，故法当用十枣汤攻逐。然年近八旬，难任峻药，改与两和肝胃，是据弦脉辨饮停肝络，而兼顾正气，缓图调治。", ["弦"]], "5517": ["病机", "脉结加，结主气机阻滞、痰饮内停，脉道不利而时有歇止。原文仅载脉结加及杏泥一味，示痰浊壅阻、肺气不宣之机，故加杏泥宣肺化痰，以通脉道、畅气机。", ["结"]], "5518": ["病机", "酒客痰饮哮喘，脉弦紧数，弦紧主饮邪内结、寒束气机，数则饮郁化热。初与小青龙不应，右胁痛甚，知饮结胁下为悬饮，非支饮可比，故改用十枣汤，因峻而用控涎丹缓攻逐饮。", ["弦", "紧", "数"]], "5519": ["病机", "伏暑夹痰饮，屡效而热不退、痰不除，右脉微结，结主痰块堵塞隧道、气血运行不畅，微则正气略伤。针中泉出紫血、咳出老痰后用药见效，证实结脉所主为痰阻脉络，痰去则脉通病愈。", ["微", "结"]], "5520": ["病机", "脉弦急七八至之多，弦主饮邪内结，急数主邪盛正急。患者胃中积水胀痛，误补近一年，致胸高不能俯、夜坐不能卧，水饮上迫肺胃，气机壅塞。脉象与症相符，故断势急，非缓药可救，用巴霜峻下黑水而势平。", ["弦", "急", "数"]], "5521": ["病机", "六脉洪大已极，洪大为阳明热盛、湿热壅遏之象。太阳痹腰脊痛，中焦流饮上泛则喘，湿热痹阻经脉。脉洪大极，说明热势深重，非重用石膏清解不能挫其势，故曰石膏用少万不见效。", ["洪", "大"]], "5522": ["预后", "右脉洪大已减，说明前用石膏清阳明湿热已见成效，热势渐退。右脉候气口，洪大减则壅盛之势挫，故石膏减量至一两，示热减药亦减，防过寒伤中。", ["洪", "大"]], "5523": ["病机", "洪大之脉较前减七八，然较平脉仍大而有力，说明阳明太阳二经湿热未净，太阴化气未复。小便赤浊、阴痿、牙缝臭味复出，皆湿热下注、上蒸之征。痹痛虽止，脉未复常，故知余邪未尽。", ["洪", "大"]], "5524": ["预后", "原文仅言脉渐退，未及具体脉象，故脉象要素为空。脉渐退示邪热渐衰，故减石膏至二两，随脉症调整方药，体现脉象进退为预后转归之凭据。", []], "5525": ["病机", "风寒解而饮未除，脉复洪大，洪大主饮热壅盛。前用小青龙解表化饮，表邪虽去，饮邪未消，郁而化热，脉复洪大，故仍用大青龙合木防己汤，兼治饮与痹，清泄饮热。", ["洪", "大"]], "5526": ["病机", "右脉洪数，洪主热盛，数主邪急，右脉候脾胃。食后恶心、二便不爽，乃暑湿干于六腑，三焦气机不利。洪数之脉与暑湿内蕴、腑气不通相应，故议通宣三焦，清利暑湿。", ["洪", "数"]], "5527": ["病机", "停饮兼痹，脉洪，用石膏有效。食后倒饱脉不大，转温脾阳不应，水蓄跗肿如故，右脉复洪大有力，小便短。洪大主肺胃热壅，肺热则溺短，饮热复聚，故仍用石膏凉肺胃，清肃水之上源。", ["洪", "大"]], "5528": ["病机", "脉洪大不减，说明阳明热邪仍盛，气分热炽未清。洪大为阳明热盛之象，热邪亢盛则脉道充盈，故脉形洪大而持续不减。此段以脉象判断热势未退，为后续加药提供依据，属病机分析。", ["洪", "大"]], "5529": ["病机", "服石膏五十斤而脉犹浮洪，说明热邪深重且误治夹杂。浮为邪在表分未解，洪大为阳明热盛之象。原文指出误下伤正、误补留邪，致热邪留恋不去。阳明之脉大，故脉大主阳明热盛，浮洪示热势仍炽，属病机分析。", ["浮", "洪", "大"]], "5530": ["兼症", "脉洪滑，洪为热盛，滑主痰饮。原文明言痰饮未除，晨起微喘、足跗肿未消，皆痰饮内停、水气不化之症。洪滑并见，示热与痰饮相合，故脉洪滑而兼痰饮诸症，属兼症分析。", ["洪", "滑"]], "5531": ["病机", "右脉仍浮洪，说明热邪未清。气已不急而去葶苈，但右脉浮洪提示阳明热势仍在，故加石膏一倍以清之。浮洪为热盛之脉，右脉候气分，右脉浮洪主气分热邪未解，属病机分析。", ["浮", "洪"]], "5532": ["病机", "右脉洪大得石膏而大减，示热势渐退；但仍滑数，滑主痰饮，数主热。原文言病减者减其制，仍滑数故加行痰饮之品。洪大减而滑数存，说明热减而痰饮未净，属病机分析。", ["洪", "大", "滑", "数"]], "5533": ["预后", "脉渐小，说明邪热渐退，脉象由洪大转为渐小，为病势向愈之兆。原文仅言脉渐小、减药，未及其他症候，以脉象变化判断病情好转，属预后分析。", ["小"]], "5534": ["病机", "脉洪数，洪为热盛，数主热炽。原文加石膏八两，说明热邪复盛，脉洪数示阳明热炽、气分热盛。洪数并见，主热邪亢盛，故加重石膏以清之，属病机分析。", ["洪", "数"]], "5535": ["预后", "原文仅言脉减、减石膏六两，未识别出具体脉名。脉减示邪热渐退，病情好转，故减石膏用量。以脉象减轻判断病势向愈，属预后分析。", []], "5536": ["治法", "脉洪大者，热盛于阳明气分，故用石膏一斤清泄里热，热减则脉减，病减者减其制。若脉复洪大有力，说明余热未清、邪势复张，当再酌加石膏之制以清之。此以脉之洪大进退定石膏用量，脉象为热盛之征，有力则实热未衰，故主病机为阳明热盛、邪实未解。", ["洪", "大"]], "5537": ["病机", "原文引《金匮》\"咳家之脉弦为有水\"，又谓\"偏弦饮澥\"，弦脉主饮、主痛。左胁漉漉有声、不时呕咳，水在肝也，肝脉弦，饮邪偏聚于肝，故脉弦为有水之明证。水饮内停，当以十枣汤峻下，因南人胆怯改用妙应丸缓下。此段以弦脉定水饮在肝之病机，脉弦与胁下水声、呕咳相应。", ["弦"]], "5538": ["预后", "十二日脉仍洪大有力，说明前服石膏后热邪未得尽解，脉象未转缓和，洪大有力仍为阳明热盛、邪实之象。此段仅记脉象以判病势进退，脉仍洪大有力提示热势尚炽、病根未拔，预后当继续清泄，不可遽停。脉象与热盛症候相应，为观察疗效与转归之依据。", ["洪", "大"]], "5539": ["病机", "右脉洪数，右主肺胃，洪为热盛，数为热急，本有饮聚而热与饮搏，气化不利，故小便不长。洪数之脉说明饮聚化热、热郁气分，水液不得下输膀胱。此段以右脉洪数定饮聚化热之病机，与小便短少相应，为清热化饮、通利小便之凭据。", ["洪", "数"]], "5540": ["病机", "痰饮喘咳，右脉洪为肺胃热盛、饮邪化热，左关独浮为肝木偏旺、木火上浮。右洪左关浮并见，说明金不制木、木反侮金，故喘咳由痰饮与肝木上逆相合而发。用建金制木法，即清肺胃之热兼平肝木。此段以右洪、左关浮定痰饮喘咳之病机，脉与喘咳症候相应。", ["洪", "浮"]], "5541": ["病机", "洪大之脉已退，说明阳明大热已减；惟两关独浮、右大于左而兼实，关候肝胃，浮而兼实为木郁陷土、肝胃不和之象。原文谓\"木陷入土\"，即肝木之气郁陷于脾胃，气机壅实。小便短而水易停，亦由气化不利。此段以两关浮实定肝胃不和、木陷于土之病机，与小便短、水停相应。", ["浮", "实"]], "5542": ["病机", "数日不服石膏，右脉复洪数，说明肺胃热邪复炽；左关之独浮者未十分清净，肝木仍偏浮未平。右洪数与左关浮并见，仍属金木同病、热盛而肝木不降。故与金木同治法，清肺胃之热兼平肝木。此段以右脉复洪数、左关浮定热复木浮之病机，脉象与停石膏后热复相应。", ["洪", "数", "浮"]], "5543": ["治法", "右脉大者，右主肺胃，大为热盛邪实之象。原文以右脉大作为服小方之指征，服后脉小即停止，说明脉大为邪热未清、当清之候，脉小则热退邪衰、可停攻伐。此段以右脉大之进退定用药与停药，脉大为实热之征，与肺胃热盛病机相应，属据脉施治之法。", ["大"]], "5544": ["预后", "原文仅言“脉不肯小故也”，未直接描述脉象形态，属以脉势变化判断病势进退。前服桂枝、广皮辛温走散，脉不肯小提示邪未尽解、气机未敛，故去桂枝、广皮，服至十五日止，是据脉象未敛而调整方药并判断疗程，非主病之脉。", []], "5545": ["病机", "原文以“脉洪大”与“脉小”交替判断水饮病势。洪大甚则喘发，说明水饮上逆、肺气壅实，故宜石膏、杏仁清降；脉小时用开水下丸，脉大时暂用石膏汤送下，脉复小则不用石膏。此以脉之大小定饮停与气逆之轻重，属病机与治法相应之论。", ["洪", "大"]], "5546": ["病机", "“六脉俱结”主气血痰浊壅滞、脉道不利。原文谓疟邪伤胃，土虚水泛，喘而肢软，正虚邪实，且有块痰塞滞经脉隧道，故脉结。结脉在此反映痰阻脉道、邪实壅塞，与“三虚一实”之论相应，先治其实即针对痰滞脉道。", ["结"]], "5547": ["病机", "“脉洪”主热盛气壅。原文述脊痹、右腿偏软痿弱、咳嗽而喘，为支饮射肺，日久不愈因误用熟地等补塞隧道，致邪壅化热，故脉洪。洪脉说明补塞致壅、饮热内盛，与痹、痿、支饮诸症相应，非单纯虚象。", ["洪"]], "5548": ["预后", "原文“脉之洪大者减”是据脉判断病减。前用开痹蠲饮法后痹解而饮未除，洪大脉减说明饮邪渐退、气壅减轻，故“病减者减其制”，减其药力。此以脉势衰减印证疗效，属预后判断，非主病之脉。", ["洪", "大"]], "5549": ["病机", "“脉弦细”主暑湿内阻、气机不畅而阴液不足。原文暑湿行令，胃不开，渴而小便短，弦为湿阻气滞，细为津伤，故用猪苓汤法分利湿热兼养阴。弦细与胃不开、渴、溺短相应，说明暑湿困阻、气化不利之病机。", ["弦", "细"]], "5550": ["病机", "“六脉俱弦”主痰饮内停、气机郁滞。原文痰饮之质，冒暑欲呕，虽渴甚难用寒凉，因弦脉示饮邪内踞、阳气不布，寒凉更伤中阳，故用局方消暑丸法。弦脉与痰饮、呕、渴相应，说明饮阻气机、暑邪夹饮之病机。", ["弦"]], "5551": ["病机", "“脉沉细”主湿阻中焦、阳气不运。原文胃不开，减前方加藿梗、广皮、益智仁，沉为湿着于里，细为气化不利，故以芳香化湿、温运醒胃为治。沉细与胃不开相应，说明湿困脾胃、气机不宣之病机。", ["沉", "细"]], "5552": ["病机", "脉缓为湿邪困阻、气机不畅之象，原文言「脉缓气歉」，气歉即正气不足，缓而无力，正合暑必夹湿、湿伤气分之机。暑湿内蕴，清阳不升则头胀，湿阻气滞则胸闷，脉缓正是湿性黏滞、阳气不伸之应，故主暑湿夹湿之候。", ["缓"]], "5553": ["病机", "「六脉阳微」指六部脉皆微弱无力，阳气衰微之象。暑湿之余，湿伤阳气，气化失司，清浊不分，故小便白浊。阳微不能蒸腾气化，湿浊下注，脉微正示阳气不足、湿浊内停，故以分利法通阳化湿，主暑湿伤阳、清浊相干之病机。", ["微"]], "5554": ["主病", "脉弦主饮、主痛，亦主肝。痰饮内停，水气凌肺，肺失宣降则喘咳；饮邪阻滞气机，脉道拘急故弦。原文「痰饮喘咳脉弦」，弦为饮邪内结之应，与小青龙法温化水饮相合，主痰饮内停、肺气上逆之病。", ["弦"]], "5555": ["病机", "脉弦主饮、主肝，数主热。悬饮者水在肝，饮邪结于胁下，肝络不和则胁痛，饮邪迫肺则喘咳。弦为饮结肝经之象，数为饮郁化热或外风未净、身热之应。原文明言「身热者，外风未净也」，故弦数并见，主饮结肝络兼外风之病机。", ["弦", "数"]], "5556": ["病机", "此段与上段同论悬饮，脉弦数。弦主饮邪结聚、肝气不舒，水在肝则胁痛；数主饮郁有热。饮邪迫肺则喘咳。脉弦数正合悬饮水结肝经、饮郁化热之机，主水饮内结、肝肺同病之候，故以悬饮名之。", ["弦", "数"]], "5557": ["病机", "脉沉主里、主水，弦主饮。痰饮内停，水气结于里，故脉沉弦；饮邪上迫于肺，有微喘之意。沉弦并见，示饮邪深结在里、非表邪所致，故用小青龙去麻辛，减其发散，专于温化里饮，主里饮内停、肺气上逆之病机。", ["沉", "弦"]], "5558": ["病机", "脉弦主饮、主风，缓主湿、主胃气和。内饮招外风，风邪犯肺则喘咳，风袭肌表则头痛恶寒；能大食示胃气尚和，故言「只有风而无寒」。弦缓并见，主外风引动内饮、风邪偏胜之机，故用小青龙去麻黄，兼桂枝汤啜粥微汗以解风邪。", ["弦", "缓"]], "5559": ["病机", "原文「脉不浮」示外感已解，邪不在表；「但弦细」则弦为饮邪未净，细为阳气不足、脉道不充。畏冷乃中阳虚弱、失于温煦之征。脉不浮而弦细，正合外解里虚、中阳不振之病机，故去细辛之辛散，专顾中阳，主饮邪未尽而阳气已伤之候。", ["细"]], "5560": ["主病", "脉双弦者，两手皆弦，弦为肝木之象，木旺则克土，胃土受制，气逆而上，故咳而呕。原文直言\"胃咳也\"，以弦脉应肝，肝病传胃，胃气上逆则呕，肺失肃降则咳，双弦示木气偏盛、胃土受困之病机，主胃咳之证。", ["弦"]], "5561": ["病机", "脉沉弦而缓，沉主里，弦主饮癖，缓为湿滞。饮邪停居右胁，故呕痰由肋痛外至脊背恶寒。原文谓\"厥阴内犯阳明，外犯太阳\"，弦应厥阴肝木，缓应太阴湿土，沉则饮伏于里，故以逐胁下之饮为法，脉象正示饮停胁下、肝胃太阳同病之机。", ["沉", "弦", "缓"]], "5562": ["预后", "脉短而数，短为肺气不足、津液耗伤，数为热盛。喉痹误用快利，肺气受伤，热毒蕴结成痈，胸痛口燥、痰气腥臭，已成脓象。数脉主热，短脉示正虚，热移大肠而泄泻，正虚邪盛，故原文断为\"难愈之证\"，脉象反映肺痈脓成、气阴两伤之病机。", ["短", "数"]], "5563": ["病机", "脉洪数，洪为阳明热盛，数为热象；继而脉又大，大则热邪更炽、气分燔灼。风温化热，口渴思凉，汗多身热，皆热盛津伤之征。辛凉不解，辛寒重剂石膏一帖而脉静，说明洪数大脉主阳明气分实热。后重亡津液而成肺痈，脉象演变正示热盛伤津、酿痈之病机。", ["洪", "数", "大"]], "5564": ["病机", "脉弦而长，弦为肝木之脉，长为气机有余、木气偏旺之象。原文谓\"木气太旺，与君火结而成喉痹\"，肝木亢盛，化火与心火相结，上攻咽喉，故成喉痹。弦长并见，示木火同盛、气火上炎之病机，主喉痹之证。", ["弦", "长"]], "5565": ["病机", "酒客脉弦数，弦主肝木、主饮，数主热。酒客素蕴湿热，湿阻气机则脉弦，湿热内蒸则脉数。原文以苦药清酒中之湿，正因弦数示湿热内蕴、肝胃同病之机，故治以苦寒清化酒湿，脉象反映湿热蕴结之病机。", ["弦", "数"]], "5566": ["主病", "脉数主热，疠气所干，热毒上攻则喉肿而痛，外蒸则身热，上扰则头晕，舌苔边白中浊示湿浊内蕴。数脉应疠气化热、邪正交争之象，故急开关窍、用时时轻扬法以透邪外出，脉数正示疠气热毒壅盛之病机，主喉肿身热之证。", ["数"]], "5567": ["病机", "脉仍微数，微为正气不足、湿邪留恋，数为余热未清。喉痛虽止而舌浊未除，脉仍微数，原文断\"其中之湿可知\"，说明湿浊未化、余热未尽。以宣通肺气为主，气化则湿化，脉微数正示湿郁化热、肺气不宣之病机。", ["微", "数"]], "5568": ["病机", "六脉沉弦而细，沉主里、弦主痛主饮、细主阴血不足，合为纯阴之象，阳微阴盛，寒湿内凝。喉痛非实火，乃阴寒上逆；足痹为寒湿下注、经脉不通。故断为纯阴，治宜温通回阳，不可寒凉。", ["沉", "弦", "细"]], "5569": ["病机", "脉再至而弦紧，至数迟少为阳衰，弦紧为寒凝气结、肝木郁滞。食减、经不行、腹中结块、肝厥频发、久喉痛，皆寒凝厥阴、真阳式微之候。前服寒凉地芍更伤阳，故病势日重、十二年不孕，治以苦辛热急回真阳。", ["弦", "紧"]], "5570": ["预后", "原文未明脉名，仅言前方服七帖后六脉将进至四至。由前案再至之迟脉渐复四至，是阳气渐回、脉率向平之象，故续服通补奇经丸，半年后受孕。此段以脉至数改善示预后转佳，非论病机。", []], "5571": ["病机", "但寒不热似牝疟，然渴甚脉数、皮肤扪之亦热，数脉主热，热在里而郁。乃伏暑内发、新凉外加，热邪为外寒所遏，未透出阳分，故外但寒而内实热。治用苦辛寒加升提，使伏热透达。", ["数"]], "5572": ["病机", "昨用升提后渴甚、脉洪数甚、热反多，洪为热盛、数为热急，是伏暑热邪已出阳分、深伏之热外透之征。故前云非真牝疟、热邪深伏未曾透出者得验，治以苦辛寒重剂清泄里热。", ["洪", "数"]], "5573": ["病机", "少阴三疟二年不愈、寒多热少，脉弦细，弦为邪郁少阳、细为阳微血少，阳微损及八脉，奇经失养，故久疟不愈。治以通补奇经丸温养八脉，服完全愈，示弦细在此主阳微而非实热。", ["弦", "细"]], "5574": ["病机", "少阴三疟久不愈，六脉弦紧，紧主寒、弦主痛主饮，形寒嗜卧、发时口不知味、不渴，皆阳虚寒盛之候；肾气上泛、面目黧黑为肾阳衰败、水寒上逆。故用扶阳汤法温肾回阳，散寒截疟。", ["弦", "紧"]], "5575": ["病机", "脉双弦，弦主饮主疟、主少阳枢机不利。伏暑成疟间二日一至、十月不止，舌苔白滑、热多寒少，是暑湿痰浊深伏三焦、邪入已深，故难速出。治宜通宣三焦使邪有出路，勿得骤补，以免闭门留寇。", ["弦"]], "5576": ["兼症", "脉紧主寒邪束表、卫阳被遏，汗多则腠理不固、营阴外泄。紧脉与汗多并见，说明表寒未解而汗出伤津，寒邪仍在，正虚渐显。原文以「脉紧汗多」并提，提示当前证候为寒邪留恋、表虚汗泄，故于方中加药以兼顾解表固汗，属随症加减之记录。", ["紧"]], "5577": ["预后", "原文「脉已活动」为脉象由紧滞转为和缓流利之象，非具体脉名，故脉素取空。脉活动、色已毕、寒大减、热少减，共计减半，汗至足底，说明邪退正复、阳气渐通。舌苔虽减仍白，示湿浊未尽，故去青蒿加黄芩，清余热而化湿，属病情向愈之预后判断。", []], "5578": ["病机", "右脉稍大，右主气分，脉大示邪热偏盛于气分。热多汗多，舌苔白滑虽薄而未尽化，说明湿浊内蕴、湿中生热，湿热交蒸而未能骤补。脉大与热多汗多相应，正合「湿中生热」之机，故治以两清湿热，不可早投补益，属病机分析。", ["大"]], "5579": ["病机", "脉大而尚紧，大示邪势未敛或正气抗邪，紧主寒与痛、邪气结聚未散。病虽又减，而脉仍大紧，说明余邪未尽、寒湿未化，故去黄连之苦寒，加益智仁温运脾肾，以脉象为据调整方药，体现凭脉辨证、寒湿未清之病机。", ["大", "紧"]], "5580": ["病机", "原文「弦中兼缓，气来至缓」，弦主疟邪留于少阳、气机不畅，缓而无力则示阳气未充、正气来复不足。三疟十退其九而白苔未尽，脉弦中兼缓，说明邪衰而阳未振，故于前方退苦寒、进辛温，以温阳化湿，属阳气未充之病机判断。", ["弦", "缓"]], "5581": ["病机", "左脉弦紧，弦主少阳疟邪、紧主寒湿内结；右大而缓，大示气分邪恋，缓为湿滞。舌白未化，疟虽止而余湿未消，脉象弦紧与大缓并见，说明寒湿余邪仍阻三焦，故方仍照服，去其不宜之品，属余湿未清之病机。", ["弦", "紧", "大", "缓"]], "5582": ["预后", "原文「脉已回阳」为脉由沉弱转为和缓有神之概称，未出具体脉名，故脉素取空。四疟已止、胃已开、脉已回阳，说明邪退正复、阳气来复、脾胃功能渐振，故与平补中焦以善后，属疾病向愈、正气恢复之预后判断。", []], "5583": ["病机", "六脉俱弦微数，弦主疟邪未净、肝脾不和，微数示余热未清、阴分稍伤。疟后而六脉皆弦微数，说明邪虽衰而未尽、脾肾两虚兼有余热，故用脾肾双补法，于补中兼清，属疟后正虚邪恋、脾肾不足之病机。", ["弦", "数"]], "5584": ["病机", "脉弦为暑邪深入之象。暑邪本多兼湿，深入少阳厥阴，气机郁滞，脉道紧张故弦。间三疟者，邪伏半表半里，与正气相争，故脉弦主暑湿深陷、枢机不利，症见寒热交替发作。", ["弦"]], "5585": ["病机", "脉数主热，此热为暑邪内盛或湿郁化热所致。数而兼热，说明邪热亢盛，正气抗邪，故脉行急迫。结合前案暑邪深入，此脉数热提示病机由暑湿向里热转化，热势渐张。", ["数"]], "5586": ["病机", "脉沉弦而紧，沉主里，弦主饮主痛，紧主寒。此太阴湿疟，寒湿偏重于里，阳气被遏，故脉沉紧；湿阻气机，脉道拘急故弦。舌苔白滑厚转灰黑滑，皆寒湿内盛之征，与牝疟表寒重者不同，此偏里寒湿重。", ["沉", "弦", "紧"]], "5587": ["病机", "左脉沉紧，沉为在里，紧为寒为痛。左脉候血候肝，沉紧提示寒邪内侵厥阴，气血凝滞，阳郁不达。结合前案太阴湿疟，此左脉沉紧说明寒湿深入下焦血分，故于前方加温通之品。", ["沉", "紧"]], "5588": ["病机", "脉洪大而数，洪大为热盛气分，数主热。经络痛虽解而未尽除，痹也；小便白而浊，湿也。此寒湿化热，热蕴气分，故脉洪大而数，主湿热痹阻经络，余邪未清，湿浊下注。", ["洪", "大", "数"]], "5589": ["病机", "右脉仍见数大，数主热，大主邪盛。右脉候气候肺，数大提示肺与大肠热邪未清，湿滞虽下而热未全退。大便与瘼中微有血迹，证从寒湿化热而来，故脉数大，可加苦药清泄腑热。", ["数", "大"]], "5590": ["病机", "左脉沉缓，沉主里，缓主湿；右脉滑，滑主痰饮。中风漏汗后表虽清，而浊阴未退，肾水上凌，故脉沉缓滑。沉缓为阳虚湿滞，滑为阴浊内盛，主下焦里证未除，心悸腹痛由水气上冲所致。", ["沉", "缓", "滑"]], "5591": ["病机", "脉缓浊阴久居，缓主湿主脾虚。浊阴久居，兼有滞物续下，说明阳明通降失职，湿浊内聚。脉缓非平和之缓，乃湿滞气机之缓，故用苦辛通法，通补阳明之阳以驱浊阴，因势利导。", ["缓"]], "5592": ["病机", "原文未出脉名，然述“痛胀滞下”久病十余年，半产后得之，误用壅补成之，且“偏左下至少腹板著”，显系瘀滞阻络、气血壅塞之病机。久病入络，汤药荡涤肠胃虽通百脉，难达细络，故须化症回生丹缓通。阳剂过重恐症散为蛊，示瘀滞深伏、正虚邪结之机。", []], "5593": ["主病", "脉缓有汗，头项强痛而恶寒，为太阳中风表虚证。风邪袭表，营卫不和，卫强营弱，故汗出而脉缓。缓为营弱卫强之象，非迟缓和缓之平脉，与恶寒、汗出、头项强痛相应，主以桂枝汤解肌祛风、调和营卫。", ["缓"]], "5594": ["主病", "服前方后脉静身凉，因不肯避风而复中，脉紧无汗，为太阳伤寒表实证。寒邪束表，卫阳被遏，营阴郁滞，故脉紧无汗。紧主寒主痛，与恶寒、无汗、身痛相应，用麻黄汤法发汗解表、宣肺散寒。", ["紧"]], "5595": ["主病", "头痛恶寒脉紧，言蹇肢冷舌淡，虽季春阴晦雨寒，寒邪外袭太阳，卫阳郁遏，故脉紧。紧为寒束之象，言蹇肢冷示寒邪伤阳、经脉不利。以桂枝二麻黄一法，微发其汗，调和营卫，兼顾阳气。", ["紧"]], "5596": ["病机", "中风表解后言蹇减食、汗出头行痛、舌白滑、脉微紧，为表邪未尽、阳气已伤。微为阳虚，紧为寒留，卫外不固则汗出，寒凝经脉则头痛。宜桂枝加附子汤，除风实表护阳，温经固表以复阳气。", ["微", "紧"]], "5597": ["病机", "表解后复中，恶寒胸结、舌苔厚白、脉迟紧里急，为寒邪内陷、阳气不振。迟主阳虚寒凝，紧主寒实内结，胸结里急示寒饮停聚、气机壅塞。脉证合参，属表虚里寒、寒饮内结之机，当温阳散寒、化饮解结。", ["迟", "紧"]], "5598": ["预后", "太阳中风误下成胸痞，壮热泄泻，脉动数。原文谓“脉不动数者为不传经”，今动数太甚，断无不传之理，可畏在此。数脉主热，动数示邪热内传、病势未已，故预后当防传经入里，非静止之候。", ["数"]], "5599": ["病机", "太阳中风误下后胸痞解，惟自利不渴、舌灰白、脉沉数。沉主里，数主热，然自利不渴属太阴，舌灰白示脾阳不足、寒湿内停。脉沉数而症见虚寒，为脾阳不振、寒湿下利之机，故议理中法而不用其方，避甘壅碍湿。", ["沉", "数"]], "5600": ["病机", "脉由大顿小其半，是邪退之象，故云脉小则病退；但仍沉数，沉主里、数主热，说明陷下之余邪未净，阳邪尚盛而真阴已虚，故身热、气粗、不寐。脉小示病退，沉数示里热未清，二者并见，正是虚实夹杂、余邪陷里之机。", ["沉", "数", "小"]], "5601": ["病机", "脉沉数，沉为在里，数为有热，故曰阴经热阳经不热，是陷下之余邪在里。邪郁于里，气机不伸而致哕，哕为伤寒大忌，皆误下后邪陷、胃气受伤所致。脉沉数正说明里热未彻、气逆不降之病机。", ["沉", "数"]], "5602": ["病机", "原文未识脉名，仅言左脉加进，即左脉较前增进。误下后胸痞自利虽止，而陷下之邪与受伤胃气搏结而成哕，哕不止且左脉加进，示邪势未衰、胃气虚馁，故用橘皮竹茹汤降逆补中，因病人气虚日甚，力量较前方大减。", []], "5603": ["预后", "脉亦渐平，是邪溃之后脉象趋于和平之象，与诸恶候如失相应，说明陷下之邪已解、气机渐复。然中气受伤不浅，故脉虽平而人未全复，议小建中汤小小建立中气、调和营卫，兼宣胃阳以进食安眠，属邪退正虚之预后调治。", ["平"]], "5604": ["病机", "脉乍数，乍者忽然而见，非持续之数。胃阳已复故安眠进食，而舌起白滑苔、小便短、大便不解，是脾阳未醒、湿滞不化；脉乍数乃脾阳不振、湿郁上蒸于肺所致，非实热之数。故议宣利三焦以醒脾阳，脉乍数正是脾阳未醒之征。", ["数"]], "5605": ["病机", "大小便已利而脉仍洪数，洪为热盛、数为热急，说明湿热未尽、郁蒸于内；舌白滑苔未除，是湿浊尚滞。脉洪数与白滑苔并见，示湿热交蒸、脾阳不运，故仍宜苦辛淡法转运脾阳、宣行湿热，不可因二便通利而遽补。", ["洪", "数"]], "5606": ["病机", "脉仍沉数，沉主里、数主热，示伏邪郁于里而未解；舌苔反白滑，是湿浊内盛之象。湿最伤气，湿不去则气不健，故脉沉数而苔白滑，说明湿热伏邪未除、气机被湿所困，宜建中行湿、急劫其湿以除伏邪。", ["沉", "数"]], "5607": ["主病", "脉浮主表，与内热外寒、头痛恶寒相应，是外邪束表、卫阳被遏之象；兼发痰饮、喉哑咳嗽痰多，则属外寒引动内饮、肺气不宣。脉浮说明病位在表，故用麻杏石甘汤外解表邪、内清肺热，兼化痰饮。", ["浮"]], "5608": ["病机", "原文“十四日肺脉独浮”，独取肺部见浮，提示邪仍在肺卫、肺气失于宣降。浮为邪在表、在阳之象，肺主皮毛，故肺脉独浮说明表邪未解而肺气上逆，与咳嗽、喉哑等肺系症候相应，属病机层面之表邪恋肺。", ["浮"]], "5609": ["兼症", "“十七日脉浮，喉哑，咳嗽，痰多”，浮脉主表、主邪在肺卫，肺气不宣则咳嗽痰多；喉为肺系，邪郁肺金、声道不利故喉哑。脉浮与咳、痰、哑并见，说明表邪未解、肺失宣肃，属外邪犯肺之兼症表现。", ["浮"]], "5610": ["病机", "原文明言“内饮招外风为病”，脉浮为外风在表之征，风邪引动内饮，饮邪上逆则咳嗽痰多、喉哑。浮脉在此标示外风未解，与内饮相合，故用大青龙法外解风邪、内化水饮，脉浮正是表邪仍在之病机依据。", ["浮"]], "5611": ["病机", "“喉复哑，脉洪数，小便已长”，洪为热盛气分、数主热，洪数相合说明邪热亢盛于里；喉哑为热灼肺津、声道不利。小便已长提示前之湿热或水停已减，而热势仍盛，故去木通之渗利，脉洪数正是里热未清之病机所在。", ["洪", "数"]], "5612": ["病机", "“头痛，脉浮，弦不甚紧，无汗”，浮主表邪，弦主风、主气机郁滞，不甚紧说明寒邪不重。浮弦并见提示外风袭表、经气不利，故头痛无汗；与杏苏法疏风宣肺相合，脉浮弦正是外风在表、肺气失宣之病机。", ["浮", "弦"]], "5613": ["病机", "原文“阴未化，阳自不复，且心下坚大如盘，脉如故”，脉象未明言，仅称“如故”，故不取脉素。心下坚大如盘为水饮结聚、阴寒未化之征；阴未化则阳难复，阳气不振而饮邪盘踞，前方再服意在温阳化饮，此段主旨在水饮阴凝之病机。", []], "5614": ["病机", "“六脉弦紧，岂不知脉双弦者寒乎”，弦紧主寒、主痛，双弦尤示寒邪内盛。原文批评久服熟地补阴致阳气困顿，不能食而呕，正因寒伤阳气、胃气上逆。弦紧之脉说明所伤在阳气、病性属寒，非阴虚可补，故以脉证相参揭示寒困阳微之病机。", ["弦", "紧"]], "5615": ["病机", "“六脉弦细如丝，阳微之极”，弦细如丝为脉道细弱、阳气衰微之象，弦在此非实邪，乃阳微脉失柔和而拘急。复感燥气后呕而欲泻，更伤阳气，故脉细如丝示阳微之极，去甘药防壅滞，此段主旨即在阳微欲绝之病机。", ["弦", "细"]], "5616": ["预后", "原文称「脉稍有神」，是诸症皆效后脉象由无神转有神，示胃气渐复、正气来复之佳兆。故去吴萸、丁香之刚燥，防其耗气伤阴；加苡仁平淡，从阳明中治，以谷气养胃。脉神之有无，直接关系预后顺逆，此段以脉测症，属预后判断。", []], "5617": ["病机", "「六脉弦紧」主痛主寒，弦为木旺、紧为寒束。原文析为起初感燥金之气，金来克木，木受病则克土，由外感延及内伤，故见胃痛胁痛、呕酸水多年不愈。弦紧应肝木受克、土受木乘之病机，治以变胃受胃、用火克金，久病在络。", ["弦", "紧"]], "5618": ["病机", "胃痛胁痛吐酸之证虽不发，而「六脉弦紧不变」，说明症状暂缓而病本未除，胸中绝少太和之气，肝木寒郁之机仍在。弦紧为木郁寒凝之象，故议转方温平，不可久任刚燥，以免燥伤胃阴，示脉象为病机未变之凭据。", ["弦", "紧"]], "5619": ["治法", "原文「诊脉已回阳」，指前此阳衰之脉已转复，故去干姜之温燥，减桂枝之半，防温散太过。此段以脉象转归决定方药进退，脉回阳则减辛温，属据脉施治、中病即止之法，体现脉诊对治法调整的指导作用。", []], "5620": ["病机", "复诊「脉仍紧」，紧主寒主痛，示寒邪郁结未解、阳气未得宣通，前治虽行而病本尚在，故于原方再加药味以助温散。脉紧不去，即病机未转之征，此段以脉象紧否判断寒凝之进退，为继续温通治法提供依据。", ["紧"]], "5621": ["病机", "「脉双弦」主肝木偏旺、饮邪内停，弦为肝脉，双弦则木气横逆。原文谓午后更甚者，阳邪自旺于阴分，故胃痛胁痛定时而作。弦脉应肝木乘土、阴阳分争之机，与胃痛胁痛症候相应，示病在肝胆而累及胃。", ["弦"]], "5622": ["病机", "病虽稍减而「脉仍紧」，紧为寒凝未散之象，说明症状减轻而寒郁之根尚存，不可因症减而遽停温散。此段以脉紧不去提示病机未彻，故仍守原法加减，体现脉象较症状更能反映病本之深浅进退。", ["紧"]], "5623": ["预后", "「脉之紧者稍和」，紧象渐缓，示寒凝渐解、阳气渐通，故腹痛已止；惟头晕不寐，乃胃不和则卧不安之余症。脉紧转和是病退之兆，故转以和胃令寐为治，再商后法。此段以脉象缓和判断病势向愈，属预后转归之论。", ["紧"]], "5624": ["病机", "感受金凉，寒邪外束，胸阳不展则胸痹头痛。脉弦主痛、主气机郁滞，细为阴血不足或寒凝脉道收引，紧主寒主痛。弦细而紧并见，说明寒凉外袭、经脉拘急、阳气被遏，故见胸痹头痛，属寒凝气滞之病机。", ["弦", "细", "紧"]], "5625": ["病机", "燥气虽化而六脉俱弦，舌苔白滑，说明燥邪去而湿痰寒饮未净，弦脉主饮主痛、主气机不和。阳明从中治法即从太阴湿化论治，用苦辛淡法以运脾化湿，最忌酸甘壅滞助湿。脉弦与白滑苔相应，示湿浊内蕴、气机不畅之病机。", ["弦"]], "5626": ["病机", "脉仍弦紧，说明寒邪与气滞未解，弦主痛主饮，紧主寒主痛，故热药难退而右胁微痛。咳嗽减是痰气稍顺，但脉象未变，说明病本在寒凝气滞，效不更方，仍守温通化饮之法，加药以针对胁痛，脉症相参示寒凝未散。", ["弦", "紧"]], "5627": ["病机", "右胁微痛而脉弦紧如故，说明寒凝气滞之病机未变。弦为气郁饮停，紧为寒邪收引，胁为肝胆之分，寒滞络脉则痛。脉象如故提示前药虽中病而寒未透解，故仍守方加药，以温通散寒、行气止痛，脉症相应示寒凝胁络未解。", ["弦", "紧"]], "5628": ["病机", "胁痛咳嗽皆止而痰尚多，脉弦未和，说明寒饮渐化而气机未复。弦脉主饮、主气机郁滞，痰多而脉弦，示脾运未健、饮邪尚留，故去香附苏子霜降香旋覆花等行气降逆之品，专事化痰和脉，脉弦未和即气机未畅之征。", ["弦"]], "5629": ["治法", "桂枝、干姜以充其阳气、行痰饮，使阳复饮化而脉和。此处和弦脉指以温阳化饮之法调复弦脉，弦主饮主寒，阳气得充则痰饮得行，脉象自和。属治法范畴，说明用药意在温通阳气以纠正弦脉所反映的寒饮内停病机。", ["弦"]], "5630": ["主病", "原文未识脉名，仅言甚则六脉全无，示阴寒极盛、阳气欲绝之危候。主治中燥吐泻腹痛、四肢厥逆转筋、烦躁不宁等，皆寒凝痼冷、阴毒内结之症。六脉全无说明寒邪闭阻、阳气不能外达，属凝寒痼冷积聚之主病，故以温散寒邪为治，非纯受阴邪者不可服。", []], "5631": ["病机", "燥气腹痛虽止而当脐仍坚、按之微痛，舌苔微黄而滑，周身筋骨痛，脉缓。缓脉主湿主脾，说明湿浊留滞中焦、气机未畅，故脐腹按痛、苔滑。阳明从中治例即从太阴湿化论治，脉缓与苔滑、脐坚相应，示湿滞脾运、筋脉不利之病机。", ["缓"]], "5632": ["预后", "原文述“脉小于前，身痛已止，六脉未和，舌黄滑苔”，脉象由大转小，示邪势渐退而身痛止，然“六脉未和”说明余邪未净、正气未复，舌黄滑苔为湿热内蕴之征。脉小为邪衰正复之象，但未和提示病未全解，故属预后判断，非主病脉。", ["小"]], "5633": ["病机", "“六脉俱弦”而见胃口不开、腹胀肢倦，弦为气机郁滞、木旺克土之象。脾胃受困，纳运失职则胃口不开、腹胀；气机不畅、阳气不达四肢则肢倦。原文提出“宜通六腑，即劳者温之之法”，正是针对弦脉所主的气滞中焦、脾运不健之病机。", ["弦"]], "5634": ["病机", "原文“六脉全无，僵卧如死，四肢逆冷，已过肘膝，骽痛转筋”，为燥金寒邪直中入里、阳气暴脱之危候。脉全无、厥逆过肘膝，乃阴寒内盛、阳气不能外达所致。用通脉四逆汤加椒、萸、丁香温阳回厥，厥回脉出，证明脉无因于寒厥而非真死。", []], "5635": ["病机", "“直中燥气，呕少泻多，四肢厥逆，无脉，目开，无语，睛不转”，无脉与厥逆并见，为燥寒直中、阳气衰微、阴寒内盛之候。呕少泻多伤中阳，阳衰不能运达四末则厥逆无脉；目开无语睛不转，神气亦衰。与通脉四逆汤回阳救逆，正针对此寒厥无脉之病机。", []], "5636": ["预后", "原文“一帖而效，三帖脉渐复，重与补阳而愈”，从无脉到脉渐复，示阳气来复、生机渐回。脉渐复为厥回阳返之征，故三帖后重与补阳收功。此段以脉之渐复判断病势向愈，属预后转归之论，非专主某病脉象。", []], "5637": ["病机", "“脉弦细而紧”主胁痛、心烦懊𢙐、拘急肢冷，弦为肝郁，细为阴血不足，紧为寒凝收引，故胁痛拘急、肢冷。继而“一刻较一刻脉渐小，立刻要脱”，脉小为正气骤衰、阳气欲脱之危象。用霹雳散不住灌之，正是针对寒凝气滞、阳衰欲脱之病机。", ["弦", "细", "紧", "小"]], "5638": ["病机", "“脉弦数”见于太阳中风汗出复感、身微热恶寒、腹中胀痛，弦主少阳枢机不利，数主邪郁化热。外证面赤汗多似温病，而当脐痛未休、舌白不燥，说明里无燥热，热象由郁而致。故用桂枝柴胡各半汤和解，后佐黄连清热，脉弦数所主为少阳郁热、表里不和之病机。", ["弦", "数"]], "5639": ["病机", "“六脉洪数而紧”而面赤身热、舌黄燥渴、便闭溺短，通体似火证，洪数为热盛，紧主邪实壅结。然只有当脐痛拒按，原文断为“阳中之阴，乃为真阴”，说明热象虽盛而里有实结，非纯热无滞。苦热芳香一剂热退，正针对洪数紧所主之燥淫表里俱病、热结壅实之病机。", ["洪", "数", "紧"]], "5640": ["病机", "原文以“脉不数”排除外感风火，痉已二十余日而脉不数，说明非热邪鼓动，乃杂药乱投伤及脾胃，乳食不化，土虚而肝风内动，恐成柔痉、慢脾风。脉不数正是虚寒无火之征，故议护中焦、实土制风，以甘缓肝急，紧扣“并无外感可知”一句。", []], "5641": ["病机", "“脉迟凉汗”而刮白兼青、舌苔白滑厚、食物不化、洞泄，迟为阳虚寒盛，凉汗为卫阳不固，全无风火之象，纯然虚寒。乳中湿不化则土愈虚，土虚则肝中内风愈动，故痉因于湿，属柔痉。脉迟正是中寒湿滞、脾阳不振之据，故议从中治、崇土以制风。", ["迟"]], "5642": ["预后", "“脉仍不数”承前虚寒之象，大便犹溏、舌苔微黄、神气渐复，说明虚寒太甚之势已退而未尽，脉不数示无热象复起。故宜退刚药、少进柔药，取“上守神，粗守形”“见可而进，知难而退”之义，脉象未变正是判断进退、调整刚柔之依据。", []], "5643": ["病机", "“脉沉细而弱”合舌苔白滑，沉主里、细弱主虚，幼童体厚而脉反沉细弱，是湿邪内困、阳气不伸之象。纯然湿邪致痉一年有余，湿性黏滞故久延不愈，脉沉细弱正说明病在里属虚湿，非风火实邪，与舌白滑相应。", ["沉", "细", "弱"]], "5644": ["病机", "“脉至沉至细至缓”而舌白滑甚，沉细主里虚，缓主湿滞，三至叠见说明湿气太重，阳气为湿所困，故效而不愈。于前方加草果劫湿、桂枝白芍甘草调和营卫，正是针对脉沉细缓所反映的湿重脾阳不通之机，脉象未转即湿未尽之证。", ["沉", "细", "缓"]], "5645": ["病机", "痉症而“脉沉细”、舌白滑，沉细为里虚湿困，湿浊内蕴故痉发渐稀而未得除根。脉仍沉细说明湿邪未化、脾阳未复，故于前方去刚燥、加化痰，以湿淡法缓图，紧扣舌白滑与脉沉细相应之湿浊病机。", ["沉", "细"]], "5646": ["病机", "“六脉阳微”而舌苔仍然白滑，阳微即阳气虚衰、鼓动无力，白滑为湿浊未化，说明前药虽效而脾阳尚弱、湿邪留恋。脉阳微与舌白滑相合，正是虚寒湿困之本象，故照前方再服，以温阳化湿巩固，脉象未复即病根未除。", ["微"]], "5647": ["病机", "痉发一次甚轻、已不呕吐而痰尚多，“脉甚小”示正气未充、阳气尚弱，小为虚象，与痰多相合说明脾虚运化无力、痰湿未尽。症减而脉小，是邪退正亦未复，故照前方再服，以缓培中气、化痰湿，脉小正是虚而未复之据。", ["小"]], "5648": ["病机", "久病阴伤已极，骨瘦如柴，又卒中暑热，舌绛芒刺、痉厥神昏，阴液涸竭而阳热鸱张。脉浮弦为热邪未敛、肝风内动之象，芤则示阴血大亏、脉道失充。浮弦而芤并见，说明正虚邪恋、阴亏风动，故勉以大队填阴兼咸止厥，先服紫雪丹凉解内闭之热。", ["浮", "弦", "芤"]], "5649": ["病机", "原文未出脉名，以「邪少虚多」立论。前用复脉已当，说明虚多之体得复脉滋养而邪势已衰；但舌上黑苔未化、宿粪未见，是阴亏肠燥、燥屎内结未下之征。故于复脉中兼加润法，寓增液行舟之意，使燥结得润而阴不复伤，属邪退正虚、虚中夹滞之病机。", []], "5650": ["病机", "本段未载脉象，承前「邪少虚多」之机。服前药五帖后宿粪碗许、黑苔已化，是润下得效、燥结渐去；但神识尚未十分清楚，说明阴液未复、余热未清、心神失养。故用三加复脉加犀角，即三甲复脉汤内加犀角，育阴潜阳兼清余热，以善其后。", []], "5651": ["病机", "三岁小儿，燥气化火，壮热舌黄、瘛疭而厥，脉数正应火热内盛、邪正交争之象。数脉主热，热盛则风动，故见抽搐昏厥。燥火伤津，法宜清凉解肌以透热外出，切忌发表，恐辛温升散更助燥火、耗其津液，此即「燥气化火」不可误汗之戒。", ["数"]], "5652": ["病机", "未及岁婴儿，瘟毒头肿、瘛疭而厥、壮热气促，脉数大乃阳邪炽盛、毒热内壅之征。数主热盛，大示邪实，故恐真阴不胜阳邪。治以普济消毒饮宣毒外出，必去升麻、柴胡之直升少阳阳明者，加犀角、羚羊泻心胆之热，防升散助毒、内陷生变。", ["数", "大"]], "5653": ["病机", "跌扑惊后瘛疭，醒后身大热、口渴、脉数、舌无苔，是惊则气乱、热灼阴伤之象。数脉主热，舌无苔示阴液已亏，热盛风动故瘛疭。用复脉汤滋养阴液以复其脉，热退脉静则阴复热清，又服二帖而安，说明此数脉为虚热扰动而非实邪壅盛。", ["数"]], "5654": ["预后", "十三日热退脉平，是邪热已解、脉气复常之佳兆。前段脉数，今转为平和，说明阴液渐复、正气得安，故预后良好。此时余邪已微，不宜再施苦寒攻伐，以调理脾胃为主，使中焦健运、气血生化有源，则病可全愈，属热病后期向愈之转归。", ["平"]], "5655": ["病机", "脉大浮取弦数，大示邪实，浮弦为肝脾不和、气机郁滞，数则食积化热之象。脾虚食滞，大便频仍、面肿腹大，疳疾将成，正合脉大弦数所主。治以温宣中焦，运脾化滞，使中焦气机通畅，则食积得消、疳疾可防，此脉症相参以定病机之要。", ["大", "浮", "弦", "数"]], "5656": ["病机", "原文言「肝肾与冲脉伏寒」，脉伏为寒邪深伏、阳气不能外达之象。脾虚火衰则食物不化，伏寒内结于肝肾冲脉，怒则气逆触发疝痛。脉伏在此提示寒凝气滞、阳衰不运，主虚寒内结、疝痛之证，与食不化、怒甚疝痛相应。", ["伏"]], "5657": ["预后", "暑邪深入下焦致暑厥，头热如火、手冷如冰，脉迟紧。迟为阳衰、紧主寒痛，暑邪内陷而阳气被遏，脉反迟紧，与热深厥深之象相悖，故原文断「未必得愈」，属正虚邪陷、预后不良之候，姑以紫雪丹救之。", ["迟", "紧"]], "5658": ["兼症", "伏暑泄泻兼停食，欲泻腹痛、泻后痛减，脉细弦而缓。细为湿滞阴伤，弦主痛、主木克土，缓则示湿邪偏盛而胃气尚存。脉象反映暑湿内蕴、食滞气阻，故防成滞下，与腹痛欲泻、泻后痛减之症相应。", ["细", "弦", "缓"]], "5659": ["病机", "六脉弦细，五更丑寅卯时单声咳嗽甚，原文谓「木扣金鸣，风本生于木」。弦为肝木之脉，细为阴血不足，木旺无制则上刑肺金，故咳发于木气当令之时。脉弦细正示肝风内动、木扣金鸣之病机，议辛甘化风、甘凉柔木。", ["弦", "细"]], "5660": ["病机", "咳嗽减、食加而脉犹洪数，左大于右。洪数为气分热盛未清之象，左大于右示肝木火旺偏甚。症减而脉未平，说明余热仍蕴气分、肝火未戢，故原文主「效不更方」，续服以清余热，脉象反映邪热未尽之病机。", ["洪", "数"]], "5661": ["病机", "柔肝清肺已效，左脉洪数已减，原文于前方去气分辛药、加甘润。左脉洪数减说明肝火渐平、气分热势得挫，故去辛散以防耗阴，加甘润以养阴柔木。脉象变化反映木扣金鸣之病机渐解，属效验之征。", ["洪", "数"]], "5662": ["病机", "六脉弦劲，原文断为「有阴无阳」，但嗽无痰。弦劲为肝木刚强、阴凝无阳之脉，阳气不能温运，故痰无所化而但嗽。脉弦劲示阴寒内盛、肝气刚劲无制，主阳虚阴凝之病机，故议清上焦气分以调之。", ["弦", "劲"]], "5663": ["病机", "咳呕而六脉弦细而数，原文断为「阴阳两虚」。弦为肝旺，细为阴亏，数为虚热，误补封固、引邪入肾致邪难再出，足心热不解为确证。脉象示久病络伤、阴阳俱损，兼季胁痛属肝络瘀滞，故勉照胃咳方法建立中焦。", ["弦", "细", "数"]], "5664": ["病机", "六脉弦细而软，弦为饮邪内动，细软为体质本弱、阳虚不充。五更咳嗽乃阳气初升之时，阳虚无力鼓动，饮邪上逆；时而吐血，是阳虚夹饮、血不归经。故以弦细软定其阳虚夹饮之机，劳者温之，取小建中汤加茯苓、半夏温中化饮。", ["弦", "细", "软"]], "5665": ["病机", "六脉弦而迟，沉部有浮部无，迟为阳虚，弦主风动，沉取有根而浮取不应，正是阳虚于内、虚风上旋之象。巅顶痛甚下连太阳，乃阳虚内风眩动，循经上扰。脉沉部有浮部无，说明病本在里，非外感表邪，故断为阳虚内风。", ["弦", "迟"]], "5666": ["病机", "左脉浮弦而数，大于右脉一倍。浮为风袭于外，弦数为少阳风动化热，左脉大于右属肝胆之部，风热循胆络上攻，故头偏左痛。脉偏旺于左且数甚，风火炽盛有损目之虞，故议急清胆络之热，用辛甘化风法。", ["浮", "弦", "数"]], "5667": ["其他", "复诊症小效而脉尚仍旧，说明前清少阳胆络之方虽中病机，然脉象未变，邪热未净。脉仍如前，故守方再服二三帖，俟大效后再议，体现凭脉验证、以脉定进退之意，非另立新病机。", []], "5668": ["病机", "六脉沉洪而数，沉主病在里，洪数为风火相扇、热势鸱张。前误用峻补阳气，致少阳络热壅盛，头目左半麻木发痒、耳后痈肿发为马刀，皆风火循络上攻。脉沉洪数正合里热炽盛之机，故加煎方暂清脑户风热，散方仍用勿停。", ["沉", "洪", "数"]], "5669": ["病机", "六脉沉数有力，沉为热在里，数而有力为实热壅盛。医误认虚而用鹿茸峻补，致少阳之热移于阳明，项肿牙痛、半边头脸肿痛、目白睛血赤、舌苔红黄，皆阳明热毒之征。脉沉数有力证实热非虚，故急急两清少阳阳明之热毒。", ["沉", "数"]], "5670": ["病机", "舌黄更甚、脉犹数，数脉示热邪未清，肿未全消而目白睛赤缕自下而上，名曰倒垂帘。赤缕自下而上者，热在阳明，与自上而下治在太阳者不同。脉数不退，说明阳明热毒尚炽，故治在阳明，清泄其热。", ["数"]], "5671": ["病机", "经谓脉有独大独小、独浮独沉，斯病之所在。今左关独大独浮，左关属胆，大浮为胆阳太旺。清胆络之药服数十帖而胆脉尚旺，说明络药清轻上浮，不能下达，胆无出路。故借小肠火腑为出路，暂与极苦下夺，然可暂不可久，恐化燥。", ["大", "浮"]], "5672": ["预后", "原文述“左关独大独浮之脉已平”，左关候肝，独大独浮为肝经热毒壅盛、气火上炎之象，今已平复，说明肝火渐降、药已中病。然“耳后之马刀，坚硬未消”，脉平而核未消，是热毒虽减而痰瘀凝结未散，故仍续服代赈普济散解毒散结，脉象改善为向愈之兆。", ["浮", "大"]], "5673": ["病机", "脉沉数，沉主里、数主热，为热毒深陷少阳阳明经脉之征。原文“马刀之坚结未消，少阳阳明经脉受毒之处，犹然牵拉板滞”，正合沉数之脉：毒结于里故沉，热毒炽盛故数。脉症相应，说明病位在里、病性属热，故外敷水仙膏、内服羚羊角散与代赈普济散清解透毒。", ["沉", "数"]], "5674": ["预后", "“脉渐小仍数”，小为邪退正复之象，数为余热未清。原文谓“里症日轻，是大佳处”，脉由大转小示热势渐衰；然仍数、舌苔黄浊去其大半而未净，说明毒热未全化透。文中归因“前此误用峻补之累”，故见功迟缓，宜宽限缓图，不可过急，恐“过刚则折”。", ["小", "数"]], "5675": ["病机", "“左脉关部复浮”，左关候肝胆，浮为邪气外浮、气火复动之象。前脉已平而今复浮，说明肝经郁热再起；原文“疮口痛甚”，热毒壅滞、气血不通则痛，故用极苦泻小肠、芳香活络定痛。脉浮与疮痛并见，示热毒未净而肝火复扰。", ["浮"]], "5676": ["病机", "“两手关脉独浮”，两关候肝脾，独浮为气火偏旺于中焦。原文“少阳阳明之热毒未除”“气大旺”，马刀虽溃而热毒未尽，肝郁化火、气机上浮，故关脉独浮。治于清少阳阳明络热中兼疏肝郁、软坚化核，正合脉浮气旺、热毒结聚之机。", ["浮"]], "5677": ["病机", "“脉之数者已平，惟左关独浮”，数平示热势已退，左关独浮则肝郁未降。原文“其性甚急，肝郁总未能降”，木旺克土故“胃不甚开，胸中饭后觉痞，舌白滑微黄”。脉浮而不数，是郁而未化火，故停败毒清热凉剂，改两和肝胃，从脉象转变定治法。", ["数", "浮"]], "5678": ["病机", "“脉少大而数”，大为邪盛气浮，数为热象未清。原文仅载“加”字，示于前方中随脉加药。脉由前之渐小复见少大而数，说明余热未净、正气尚与邪争，热势略有反复，故仍须清解，不可遽补，与前后脉案热毒未化透之旨相承。", ["大", "数"]], "5679": ["病机", "“脉仍数”，数主热，示热邪留恋未解。原文“肝胆俱病，不能纯治一边”，说明数脉所主之热涉及肝胆两经，木火同病，单治一脏难以取效，故须肝胆并治、清疏兼顾。脉仍数与前案“脉少大而数”相续，可见热毒未清、病机未转。", ["数"]], "5680": ["病机", "脉弦数，弦主肝风，数主热，风热蟠聚脑户，故鼻塞而衄或鼽；大便黑为热伤血络。误补则邪不得出，变衄为鼽，皆风热上攻之象。", ["弦", "数"]], "5681": ["病机", "右脉洪大而数，洪大主阳明热盛，数主热，故渴欲饮水、牙床肿甚，显系阳明经热上攻。加石膏、银花、桑叶清阳明热，热不退则加重石膏。", ["洪", "大", "数"]], "5682": ["主病", "脉弦细微数，弦主厥阴，细微为阴血不足，数主虚热。巅顶一点痛、畏光如虎，乃厥阴头痛，肝血虚而风阳上扰，故用定风珠养阴熄风。", ["弦", "细", "微", "数"]], "5683": ["主病", "脉弦紧甚，弦主痛、紧主寒，阳虚头痛、背恶寒，乃阳虚寒凝，经脉拘急。服黄耆建中加附子温阳散寒，痛减脉稍和，证明寒去阳复。", ["弦", "紧"]], "5684": ["病机", "脉弦急，弦主肝郁，急主痛，怒郁伤肝，肝气横逆，暴注血海则经水暴至，肝厥犯胃则胁胀攻心、痛极欲呕、不欲食、少腹坠胀。治以厥阴为主，胞宫阳明同救。", ["弦", "急"]], "5685": ["病机", "脉双弦而细，双弦主肝郁，细为血少，肝厥犯胃，气郁血虚。故以开朗心地为要，使肝气条达，免久而成患。", ["弦", "细"]], "5686": ["病机", "脉沉弦而紧，沉主里，弦紧主寒主痛，浊阴上攻厥阴，克伐阳明，胃气上逆则呕，阳不达肢则肢逆且麻，呕而不渴为寒饮内停，急宜温之。", ["沉", "弦", "紧"]], "5687": ["病机", "脉弦而紧，弦则木旺，紧则为寒，木旺土衰，中寒阳不运，故吞酸嗳气、不寐不食、不饥不便、九窍不和，浊阴蟠踞中焦，格拒心火，心热如火，议苦辛通法。", ["弦", "紧"]], "5688": ["病机", "六脉阳微，阳气衰微，浊阴蟠踞中焦，故不食不饥不便；继则腹大痛归下焦，十余日不大便，乃肝失疏泄、浊阴内结。阳微为浊阴上逆之本，脉证相合，故用和阳明兼驱浊阴、通阴络诸法。", ["微"]], "5689": ["病机", "脉沉紧为里寒，沉主里、紧主寒主痛。木旺土衰，浊阴上攻，故腹拘急时痛、胁胀、腰痛。紧脉示寒凝气结，沉示病在里，与腹拘急、胁胀相应，故用苦辛通法兼醒脾阳。", ["沉", "紧"]], "5690": ["病机", "脉弦细而紧，弦主肝郁气滞，细主阴血不足，紧主寒凝。浊阴上攻，胸阳被阻，故胸痛。弦紧相合示气机郁滞而寒，细示正气不足，故用辛香流气法以疏畅气机。", ["弦", "细", "紧"]], "5691": ["病机", "六脉俱弦，不浮不沉不数，弦为肝气偏旺。舌苔白滑、不食不饥不便不寐、九窍不和，皆胃病；卧时气上阻咽、卧不着席，为肝气上逆。脉弦与肝气逆、胃不和相应，故两和肝胃。", ["弦"]], "5692": ["误治", "屡用大黄、蒌仁寒下，屡下屡伤，神气若昏、目闭不开，脉弦缓而九窍愈不通。弦为肝郁，缓为胃气受伤，屡下伤阳致六腑不通、九窍不和，已成坏症，故勉与通阳，示误下之害。", ["弦", "缓"]], "5693": ["病机", "面赤脉洪，洪为胃热亢盛、阴液受伤。不食十余日，胃阴亏而热盛，故脉洪面赤。与五汁饮降胃清阴，兼服牛乳，三日大食，说明洪脉主胃热阴伤，清降则胃气复。", ["洪"]], "5694": ["病机", "温热愈后午后微热不除，脉弦数，面赤。弦主肝郁余热，数主热盛，午后微热示余热未尽、阴分受伤。脉弦数与面赤、午后热相应，故用五汁饮清降，三日热退进食而愈。", ["弦", "数"]], "5695": ["病机", "咯血胁痛、项下有核、咽痛便溏，脉数恶热，为肝火乘脾之证。数主火盛，恶热示热象明显；肝火犯肺则咯血胁痛，乘脾则便溏。能食者脾求助而难胜则痞，故治在制肝益脾。", ["数"]], "5696": ["治法", "原文指出“若脉非弦大，惟羚羊去之”，说明羚羊角适用于脉弦大之证，脉非弦大则非其治。脉弦大常主肝阳上亢、热盛动风，故用羚羊角清热平肝熄风；脉不弦大，则病机非肝热动风，故去之。此从脉象指导方药加减，属治法范畴。", []], "5697": ["预后", "脉弱而数，弱为气血不足，数为虚热内扰。症见形瘦色槁、上热下寒，乃肝脾肺失调，病从内生。根本已漓，即肾元亏虚，故预后难全愈。脉弱数反映正虚邪恋，阴阳不相维系，与形瘦色槁、上热下寒相应，属内伤杂病之危候。", ["弱", "数"]], "5698": ["病机", "原文“形盛脉充，两尺独虚”，虽未明言脉名，但两尺候肾，独虚提示肾元不足。下体麻痹、火浮气急，为肾虚不能摄纳，虚阳上浮。形盛脉充乃枝叶虽盛，两尺虚则根本不固，故曰未足恃。此脉症反映下虚上实、本虚标实之病机。", []], "5699": ["治法", "诒按“如此脉证，似可参用肾气法以温摄之”，虽未列具体脉象，但结合前文两尺独虚、下体麻痹、火浮气急，脉证合参当属肾阳虚衰、虚阳上浮。肾气丸温补肾阳、摄纳浮阳，故可参用。此属治法范畴，体现凭脉辨证以立法。", []], "5700": ["病机", "原文“阳脉则缓，阴脉则急”，阳脉指手足阳明经，阴脉指厥阴肝经。阳脉缓则气血尚充，阴脉急则肝经拘急，故指节能屈不能伸。肝苦急，宜食甘以缓之，于方中增阴药甘润以缓肝急。此脉象说明肝阴不足、筋脉失养之病机，与类中偏左、指节屈伸不利相应。", ["缓", "急"]], "5701": ["病机", "原文重申“指节屈不能伸，病在厥阴肝经，是阴脉则急之义”，阴脉急主肝经筋脉拘挛。若治痿取阳明，即阳脉则缓者，阳明主润宗筋，阳脉缓则宗筋得养。此以脉之缓急辨病在厥阴或阳明，说明肝急筋挛与阳明缓筋之不同病机。", ["急", "缓"]], "5702": ["病机", "脉虚而涩，虚为气血不足，涩为血行不畅。左半手足麻痹、食不知味，乃气血不能运行周体，肢体失养，脾胃失运。此脉象反映气血两虚、脉络瘀滞之病机，为类中之渐，即中风先兆。虚涩脉与半身麻痹、食不知味相应，提示补气养血、通络为治。", ["虚", "涩"]], "5703": ["病机", "脉浮数动，浮为阳浮，数为热，动为阳动。症见齿疼舌赤、精浊、右偏肢痿舌强、口喁语蹇，乃肝肾两虚，水不涵木，肝风暴动，虚阳上浮。脉浮数动反映肝阳化风、相火内动之病机，与河间“肝肾气厥”舌瘩不语、足痱无力之证相应。治宜温肾凉肝复方。", ["浮", "数", "动"]], "5704": ["其他", "原文为诒按，强调“参详脉证，斟酌尽善”，未出具体脉象，故无脉可析。其意在于临证须脉证合参，不可偏执，属方法论之语，非主病、病机之论。", []], "5705": ["病机", "邓评言“必有痰火窜闭络脉”，未载脉象，以症测机。痰火内扰，走窜络脉，故加钩钩、姜汁、竹沥以化痰火、通络开闭，属病机推断之评。", []], "5706": ["病机", "脉濡按之则弦，濡主脾湿，弦主肝风，故曰“脾饮肝风，相合为病”。湿饮内蕴，肝风挟痰走窜，故右肩手指麻木、两腿酸痒，乃类中之渐，不可不慎。", ["濡", "弦"]], "5707": ["病机", "邓评“脉濡属湿，弦则为风”，风与湿合，故麻木酸痒。饮由湿化，湿为饮之渐，风挟湿走窜经络，故见麻木酸痒，治当祛风除湿，羚羊与桂枝并用。", ["濡", "弦"]], "5708": ["病机", "脉虚而数，虚为阴气不足，数为湿热内蒸。两膝先软后肿、不能屈伸，乃湿热乘阴气之虚而下注，久则成鹤膝风，虚实夹杂之候。", ["虚", "数"]], "5709": ["其他", "邓评推测“想必舌绛脉盛”，未出具体脉象，以舌绛脉盛测其热盛，故直任羚羊。又虑其虚，参生脉兼治。属评注推测之语，非脉学正论。", []], "5710": ["病机", "原文“脉不弱数”，谓脉不弱而数，数主痰火内扰。惊悸易泄、腰疼足软似虚，然脉不弱、形不枯瘁，故知实因痰火，未可遽补，当先清化痰火。", ["数"]], "5711": ["其他", "邓评言“总须以舌苔脉象为凭”，未载具体脉象，强调临证取舍当以舌脉为据，属评注方法之论，非主病、病机之析。", []], "5712": ["病机", "脉弱色悴，是肝风痰饮久搏、内壅脏腑外闭窍隧而正气已虚之象。邪实正虚，攻则益虚，不攻则病不除，故脉弱非纯虚，乃邪滞耗正、气血不荣之色脉相应，主不寐不饥、肢体麻痹之痼疾，最为棘手。", ["弱"]], "5713": ["病机", "久嗽而脉不数、口不干，说明热象不显，非阴亏火旺之损证。原文断为肺饮郁伏不达，饮邪内停、肺气不宣，故咳久而不化热，脉亦不数。此以脉不数辨非损证，主肺饮内伏之咳。", []], "5714": ["病机", "脉泫而细，细为阴血不足、脉道不充，泫示濡滞不畅，合体虚邪滞、肺络不清之候。幸不数，说明尚无内热伤阴之象，邪滞尚轻。此脉主正虚夹邪、肺络失清之咳，与体虚邪滞相应。", ["细"]], "5715": ["预后", "原文未识脉名，仅言脉象与前无异，重点在肺病以中气健旺、能食便坚为佳。今喘咳已久而便溏、能食难运，是脾运不健、中气不足，非所宜。脉象不变而节饮食慎寒暖犹可无虞，属凭症辨预后之论。", []], "5716": ["病机", "久嗽便溏而脉虚数，虚为中气不足，数为虚热浮动。脾主运化、肺主气，脾肺俱病则便溏、久嗽并见。脉虚数示正虚而兼浮热，故以培补中气为要；恐后泄不食、瘦削日增，是脾败之虑。", ["虚", "数"]], "5717": ["病机", "脉细数促，细为精血内耗，数为虚热，促为气逆不续。原文断为肝肾精血内耗、冲脉气逆自下及上、气不收纳，故咳吐清涎浊沫、喘而汗出，根本先拨。见血治肺是速其凶，此脉主内损危候。", ["细", "数", "促"]], "5718": ["病机", "脉虚数，虚为精血亏耗，数为阳浮不敛。合颧红声低、咳甚吐食、晡热烦躁，是肝肾阴亏、阳浮于上、精液化痰沫之内损。病已三年，非消痰治嗽可愈，须固摄下焦、绝欲，脉症相应示久损可图。", ["虚", "数"]], "5719": ["病机", "脉微小，是阳气衰微、气血不足之象。形寒为阳不温煦，久嗽失音为气馁阳损、肺金失养。原文断为气馁阳损，议固胃阳取甘温之属，说明此脉主阳虚气弱、肺胃虚寒之咳，非实邪为患。", ["微", "小"]], "5720": ["治法", "原文未出脉名，仅述呛止音出后胃弱便溏，复脉甘润不宜再用。此示肺金虽得濡润而脾土转弱，病机由肺阴不足转为脾阴亦亏，故仿麦门冬汤养土之阴以生肺金，属治法调整而非凭脉断病。", []], "5721": ["其他", "此条为孙评，说明叶氏用复脉汤每去麻仁，因麻仁滑润碍脾。原文无脉象，主旨在于方药加减之理，属对前案治法之补充说明，非脉诊主病之文，故列其他。", []], "5722": ["预后", "久咳便溏腹满，脾肺同病已属难治；更见脉数口干潮热，数脉主热，阴不制阳，虚热外浮，提示肝肾之阴亦不足。脾肺既病而肝肾阴亏，故原文叹为难治，脉数为阴虚内热之征。", ["数"]], "5723": ["病机", "寸关大而尺小，寸关主上焦中焦，尺主下焦肾。尺小为下元不足，寸关大为阳气浮越于上，故口干、上气不下；阳不达下则足冷不温。原文断为阳气不潜，当用阴中阳药引阳归宅。", ["大", "小"]], "5724": ["病机", "邓评承前案阳气失潜，主张参介类潜阳。须脉大而豁然者，方合桂、味之用。脉大而豁然示阳浮于外而中空不敛，非实热壅盛，故宜温纳潜降，若脉不豁然则桂味不合，强调凭脉定药。", ["大"]], "5725": ["病机", "脉数减、咳亦缓，是虚热渐退之象；但浮气不得全归根本，说明下焦摄纳无力，气仍上浮。数脉减而未静，示阴未全复，故宜补益下焦以为吸受之地，使浮阳归元，属病机转归与治法。", ["数"]], "5726": ["病机", "喘、足冷至膝、唇干、鼻塞而脉虚小，虚小为根本不足、下元虚衰之象。下气上逆由肾不纳气所致，故病在根本。原文戒勿因结痰在项而漫用清克，正恐虚其虚，脉虚小为辨证关键。", ["虚", "小"]], "5727": ["病机", "邓评指出口干鼻塞似兼外感，然用肾气丸直任无疑者，全凭脉之虚小。虚小示正气内亏、根本不足，急则先治其本，故不因外症而改弦，强调脉虚小在此案中决定从本论治。", ["虚", "小"]], "5728": ["其他", "原文为邓评，强调“病象毕露于脉”，认为脉象能充分反映病情，故“谁谓脉不足凭乎”。此段未出具体脉名，旨在说明脉诊可凭，病象与脉相应，非主某病机，亦非预后死脉，属脉诊价值之论。", []], "5729": ["病机", "吐血因劳与怒即发，脉小数微呛。数主热，小主虚，劳心思虑耗阴，肝心火动，热迫血溢，故脉数；阴血不足则脉小。微呛为肺气上逆之兆。病在肝心，宜早图，勿延及肺，示热势有传肺之虞。", ["小", "数"]], "5730": ["病机", "失血咳逆、痞满、暮厥、血色黯、大便黑，肝脉独大。大脉主邪盛，肝脉独大示瘀血积留肝经，气血壅滞，故脉形大而有力。瘀阻则血不归经，发为失血；气机不利则咳逆痞满。治宜和血，勿治其气。", ["大"]], "5731": ["兼症", "邓评推测当有舌绛脉数、心胸烦热之证，故方中用犀角。数脉主热，舌绛为营血热盛之征，心胸烦热乃热扰心神。脉数与舌绛、烦热并见，说明热入营血，故以犀角清营凉血。此段以脉数佐证热证兼症。", ["数"]], "5732": ["病机", "脉寸静尺动，屡经失血，气从下焦上冲则呛，劳动则气促。寸静尺动示病在下焦肾，肾阴亏虚，虚阳不潜，冲气上逆，故尺脉动。病不在肺而在肾，治嗽无益，宜滋肾阴，以潜降冲逆。", ["动"]], "5733": ["病机", "心脉独大，口干易汗，善怒血逆。大脉主邪实阳亢，心脉独大示心阳独亢，心阴不足，阳热迫津则口干易汗，阳升血逆则善怒失血。治宜犀角地黄汤凉血清心，泻其亢阳，滋其不足。", ["大"]], "5734": ["病机", "邓评言“肝阳未尝不亢”，肝阳过升则脉气上溢，溢则并火于心脉。此段未出具体脉名，但述脉上溢之机，说明肝阳亢盛，气血随之上逆，影响心脉。茅根宜易丹皮，意在凉血平肝。", []], "5735": ["预后", "劳伤失血，心下痛闷，不当作阴虚证治。但脉数咳嗽潮热，数脉主热，咳热并见，恐其渐入阴损一途。此段以脉数伴潮热咳嗽为据，提示热耗阴伤，预后有转虚损之虞，故当警惕。", ["数"]], "5736": ["病机", "原文谓“阴不足而阳有余，肝善逆而肺多郁”，脉数示阳热有余、阴不制阳，气火上逆犯肺则气喘咳逆，灼伤血络则见血，肝气郁逆则胁痛。数脉在此主阳盛火动、气逆血溢之机，故治宜滋降以制阳、静养以敛逆，否则血逆难止。", ["数"]], "5737": ["兼症", "再诊热势虽渐减，而“脉数不退”，说明余热未清、阳热仍扰于内；头中时痛为热上攻，喉中痰滞不清为热灼津液成痰。数脉在此反映邪热未尽、痰热交阻之兼症，热减而脉数不减，提示不可仅凭体热进退判断病势。", ["数"]], "5738": ["病机", "三诊“体虽不热，脉仍细数”，细为阴血不足、脉道不充，数为阴虚内热、虚火未靖。外热虽退而脉象未复，说明阴液亏耗、虚热内生仍是病机关键，故原文断“宜养阴气”，以细数脉为阴虚未复之据，而非实热未清。", ["细", "数"]], "5739": ["病机", "面黧形瘦、腰膝无力为先天肾虚，咳嗽气促、大便时溏为后天脾肺俱弱，脉虚而数正合“先后天俱虚”：虚为气阴不足，数为虚热浮动。原文虑其延成虚损，并戒清润治肺之品“能戕中气”，说明此数脉属虚数，不可作实热清降。", ["虚", "数"]], "5740": ["病机", "原文未出具体脉名，以“络脉空隙”言病机：络虚不固，气无所附则游行作痛；阴虚于下，至春末夏初阳气上升之时，血随气溢，故虑其出血。此为阴虚络空、气不摄血之机，治当填精益髓，若以清凉治咳，反伤胃气而成虚损。", []], "5741": ["病机", "原文“脉来不柔，时自歇止”，不柔即脉失柔和、偏于弦劲，歇止为脉气不续。结合汗出偏沮，知肝阳有余、胃阴不足，稠痰浊火扰动于中、壅滞于外。脉不柔而歇止，反映阳亢阴亏、痰火壅滞、脉道不利，故虽目前安和，仍须见微知著、加意调摄。", ["数"]], "5742": ["预后", "四诊“大便通，脉和”，脉和指脉象平和、无偏亢搏击之象，说明邪去正复、气机通畅，故大便得通。此为病情向愈之预后，原文惟宜滋养，即以平脉为据，示攻邪已止、转以养正善后，不可再施克伐。", ["和"]], "5743": ["治法", "下既不通，浊气上逆而为呕，本应疗下；但“脉小目陷”，小为脉道细弱、气血不足，目陷为津气耗伤，合示中气大伤。若径攻下则更伤正气，故原文主张先安中止呕，待呕定再商。此脉小在此主中气大伤，决定先扶正后祛邪的治法次序。", ["小"]], "5744": ["病机", "痛呕后脉本当和缓，今反搏大，是胃土受伤而肝木偏亢，即原文所谓“土啧木张”。搏大之脉主邪盛气逆，故见头运欲呕、胸满不食、神倦欲卧，为肝胃不和、气逆上扰之候，久则渐致痉厥，故法当安胃清肝以先事预防。", ["搏", "大"]], "5745": ["病机", "邓评指出立方只言安胃清肝而不补中，正因“脉反搏大”。搏大为邪气亢盛、肝木偏旺之象，非中虚可补之脉，故以安胃清肝平其亢逆为主，片语见斟酌，说明脉象决定治法取舍，此段主旨仍在阐发脉与病机治法的关系。", ["搏", "大"]], "5746": ["预后", "气郁痰凝阻隔胃脘，食入则噎，脉见涩。涩主气滞血少、痰瘀阻结，脉道不利，正虚与邪阻并存，故原文断为“难治”。此段以脉涩判断噎膈病情深重、预后不良，涩脉反映气血痹阻而胃气难复。", ["涩"]], "5747": ["病机", "诒按论旋覆代赭为噎膈正方，食入则噎因肺气先郁，故加郁金、贝母、枇杷叶。惟脉涩者主正虚，涩为血少气滞之象，故可加人参扶正。此段以脉涩说明正虚一面，与痰气郁阻并见，提示攻邪之中须顾护正气。", ["涩"]], "5748": ["病机", "邓评谓病较前案稍深，用药亦较进步。脉涩不独为正虚，抑且为血痹。涩脉既主气血虚少，又主血脉痹阻，噎膈日久痰瘀互结、血行不畅，故涩脉兼见虚与痹两义，此段补出涩脉主血痹之病机。", ["涩"]], "5749": ["病机", "脉疾徐不常，即脉来快慢不均、节律紊乱，主中气大衰、升降失度。中焦脾胃气虚，清浊升降失常，故食格不下。脉之疾徐无常正是中气衰败、气机逆乱之反映，此段以脉象说明食格不下之病机在于中气大衰。", ["疾", "徐"]], "5750": ["病机", "邓评重申脉疾徐不常系中气大衰所致，并赞制剂精幻可法。脉来快慢不匀，反映脾胃中气亏虚、升降之枢失职，气机时疾时徐而无常度，故食格不下。此段与上条相承，强调脉象变化直接指示中气衰败这一病机核心。", ["疾", "徐"]], "5751": ["病机", "中气迭伤不能健运，故朝食暮吐、完谷不腐。诊得脉虚，为正气亏虚之象；色黑、腰脚少力，则知不独胃病，肾亦病矣。脉虚主中气与肾气俱衰，脾肾阳虚不能腐熟运化，此段由脉虚色黑推断病涉脾肾，非仅胃病。", ["虚"]], "5752": ["病机", "原文未出脉名，然述肝阴素亏、温邪扰之，发为痉病，神昏骱齿，瘛疯不定。此属肝阴亏虚，筋脉失荣，温邪内陷，痰热蒙蔽神明。脉象虽未明言，按证当见弦细数等，主病机为阴虚邪扰、痰热动风。", []], "5753": ["预后", "热伤津液，脉细口干，难治。脉细为阴液亏耗、脉道不充之象，口干乃津不上承。热邪炽盛而津液已伤，正虚邪实，故预后不良。此以脉细口干判断热病伤津之难治。", ["细"]], "5754": ["病机", "诒按此存阴泄热之正法，所云难治，想因脉细之故。脉细主阴液不足，元气亦弱，虽用存阴泄热正治，然脉细示正虚难以胜邪，故难治。此条以脉细释难治之由，属病机分析。", ["细"]], "5755": ["病机", "邓评口干仅为津液受伤，脉细则其元气亦弱，故云难治。脉细不仅示津亏，更反映元气虚弱，正不胜邪，故虽见口干津伤，而脉细揭示根本已虚，治疗棘手。此以脉细阐发难治之病机。", ["细"]], "5756": ["病机", "舌干脉数，汗为热隔，虽发之亦不得，惟宜甘寒养液。脉数主热，舌干示津伤，热邪郁遏，汗不得出。治当甘寒养液，待足温而后热退乃吉。此以脉数舌干阐明热隔汗不出之病机及治法。", ["数"]], "5757": ["主病", "风温郁于肺胃，咳而胸满，痰多胁下痛，脉数口干。脉数主热，风温之邪郁于肺胃，肺失宣降则咳而胸满，痰多胁痛；热灼津伤则口干。脉数口干为风温郁肺胃之主病脉症。", ["数"]], "5758": ["病机", "脉右大，舌黄不渴，呕吐黏痰，神躁语言不清，身热不解。右大主肺胃热盛，舌黄为热，不渴知兼痰湿，痰热蒙蔽则神躁语言不清。此劳倦内伤更感湿温，正虚邪实，须防变端。脉右大揭示肺胃受热之病机。", ["大"]], "5759": ["病机", "邓评脉右大舌黄，知肺胃受热；不渴，知复多痰湿。脉右大主肺胃热盛，舌黄亦为热象，不渴则示痰湿内蕴。此以脉右大舌黄阐明肺胃受热兼痰湿之病机，用药轻清而识见高。", ["大"]], "5760": ["病机", "脉素大者，少阴肾经湿热内蕴之象。大脉主邪盛，湿热蕴于肾间，气机壅滞，故脉形宽大。脐中湿液腥臭，乃湿热下注外泄之征。原文明言「此少阴有湿热也」，脉大与湿浊内盛相应，故以六味加减清利肾间湿热，脉大为实邪之应。", ["大"]], "5761": ["预后", "精滑之症，脉以缓小为顺，缓小者正气尚能约束，虚而不甚。即见数象亦必无力，数而无力乃虚热扰动精室，非实火之数。原文以「脉必缓小者为宜」定吉凶，数而无力仍属虚损，若数而有力则恐火盛迫精，预后转恶，故缓小为可治之脉。", ["缓", "小", "数"]], "5762": ["病机", "脉数而微，数主邪热内扰，微主阳气衰微。面黑目黄、足寒至膝、皮肤爪甲不仁，皆少阴阳衰、湿浊瘀阻之候。原文谓「病深入少阴」，邪由白酒湿及女劳所伤，正虚邪陷，数而微示虚阳浮越而根本已衰，故见寒厥不仁之重症。", ["数", "微"]], "5763": ["治法", "脉实者，邪气壅盛而正气未衰，形证俱实，故可峻用开导攻下之法。原文「体实脉实者，故可峻用开导」，强调脉实为可攻之凭据，实脉应指有力，示邪结可下。若脉不实而妄攻，则伤正，故识脉实方能放胆用峻药，此脉实主可攻之机。", ["实"]], "5764": ["病机", "原文未出脉名，以「寒袭于肾，而气上逆」立论。寒邪客肾，肾阳受困，气不归元而上逆，故用温养。胀及腰背者，督阳不用，鹿茸温通督脉、麝香开泄浊阴，皆针对寒凝浊阴、督阳不振之机，非凭脉象断病，故脉象要素从缺。", []], "5765": ["病机", "脉弦主肝，小腹痛、食后胃脘痛上至咽嗌，乃肝火循经乘胃。弦为肝木亢盛之象，木旺克土，气火上逆，故痛自少腹上攻脘咽。原文断为「肝火乘胃」，治宜泄厥阴、和阳明，弦脉正是肝火内郁、横逆犯胃之应。", ["弦"]], "5766": ["主病", "心腹痛而脉弦、色青，弦为肝脉，青为肝色，故原文直断「是肝病也」。肝气失疏，气机郁滞，不通则痛，痛引心胸腹部。脉弦与色青并见，为肝病形之于外之征，弦脉在此主肝郁气滞作痛之病。", ["弦"]], "5767": ["病机", "脉虚数，虚为营血不足，数为虚热内扰。色白不泽、左胁块大，乃肝家营血不和、虚中夹实之候。大便小便自利示病不在二便而在肝血。原文谓「虚中有实，补必兼通」，虚数之脉正应营虚有热、瘀块内结，故补通兼施。", ["虚", "数"]], "5768": ["主病", "大腹右有形为聚，脉大，食入即作胀，此聚在六腑。脉大为阳盛有余之象，与有形积滞相合，说明腑气壅实、传化失司，故食入即胀。治在六腑，即从通降腑气立法，脉大在此提示实滞而非虚胀。", ["大"]], "5769": ["其他", "此段为邓评，承前条脉大而言。既云脉大，说明阳热实滞之象明显，故评者疑单用温运不足，主张加川连、枳实以清泄通降。脉大在此仍主实热壅滞，评语从方药角度反证脉大当兼实热内结之机。", ["大"]], "5770": ["病机", "脉迟胃冷，腹胀气攻胸胁，恶心少食泄泻，皆因脾胃阳虚、寒凝气滞。迟脉主寒主阳虚，胃冷则腐熟无权，气机不运故胀满攻冲；浊阴不降则恶心少食，水湿下趋则泄泻。治宜振脾胃之阳，脉迟正是阳虚内寒之据。", ["迟"]], "5771": ["病机", "脉微迟，左胁宿痞，腹渐胀大，便溏溺少，此为浊阴上攻。微为阳微，迟为阴寒，阳气式微则阴浊不化，痞积日久渐成胀满；便溏溺少乃气化不行、水湿内停。脉微迟揭示阳衰阴盛，故当通阳以化浊阴。", ["微", "迟"]], "5772": ["病机", "脉弦中满，病在肝脾。弦为肝脉，主气机郁滞；中满为脾运失职、气壅腹中。肝失疏泄则脾土受克，木郁土壅故见中满。脉弦在此说明病机重心在肝脾不和、气滞中焦，非单纯虚满可比。", ["弦"]], "5773": ["其他", "此段为邓评，承脉弦之证而言。脉弦主肝郁气滞，评者认为弦脉之证用人参不如白术妥善，因白术健脾运湿而不助壅滞。脉弦提示气机郁结、脾运不健，故补气须兼运脾，评语从用药角度印证弦脉所主肝脾郁滞之机。", ["弦"]], "5774": ["病机", "原文未出具体脉名，以脉证合参立论。气结在上，津不运行，蒸变浊痰，由无形渐成有形，说明病机为气滞津凝、痰浊渐聚。徐之才谓轻可去实，非胶固阴药所宜，强调痰气结聚当以轻宣流动之品开泄，不可峻补滋腻。", []], "5775": ["病机", "头痛偏左，耳重听，目不明，脉寸大尺小。寸大主风火上壅于上，尺小示下元不足，风火在上而根虚于下。偏左头痛、耳聋目昏皆风火扰及清窍之象，故姑为清解，脉寸大尺小正是上实下虚、风火浮越之据。", ["大", "小"]], "5776": ["病机", "原文未出脉名，仅言「少阳之脉，循耳外，走耳中」，指出耳部与少阳经脉相连。风火之邪客于少阳，循经上扰耳窍，故耳脓而鸣。此段以经脉循行阐释病机，非以脉象言病，故脉象要素为空。", []], "5777": ["其他", "邓评指出「小便浑浊，绝不犯分利治法，惟凭之于脉耳」，强调辨证不凭分利套法，而全赖脉象决断。原文未出具体脉名，故脉象要素为空。此段属评注性质，讨论凭脉辨证之要，非直接论脉主病。", []], "5778": ["病机", "形伟体丰而「脉得小缓」，小为阳气不足，缓为湿滞不运。外似有余，内实不足，水谷不得阳运，酿湿下注为浊病。脉小缓正合阳气发泄、内虚湿注之机，故治宜升阳，非少壮阴火自灼之比。", ["小", "缓"]], "5779": ["病机", "恼怒伤中，湿热乘之，脾气不运，水谷并趋大肠而为泄，腹中微疼。「脉窒不和」即涩滞之意，示气机壅塞、湿阻中焦。脉涩与泄泻、腹痛相应，故治在中焦，以运脾化湿为法。", ["涩"]], "5780": ["其他", "此段为按语，指出前案中「脉窒」一句不甚明了，属对原文脉象描述的质疑与讨论，未出具体脉名，故脉象要素为空。主旨在于辨析脉象表述之清晰度，非论脉主病。", []], "5781": ["其他", "此段解释「脉窒即是涩滞之意」，并主张直称「脉涩」更为直捷了当。属对脉象术语的辨析，指出窒与涩同义，非直接论某病之主脉，故归其他。脉象要素取涩。", ["涩"]], "5782": ["病机", "气郁不行，津枯不泽，故饮食少、大便难、形瘦而「脉涩」。涩为津血亏少、气机郁滞之象，非实积可下之证，故「未可概与通下」，宜养液顺气。脉涩与津枯气郁之症相应。", ["涩"]], "5783": ["治法", "邓评引仲景「脉涩可下之例」，然认为涩不宜下者罕见，此方宗通凿汤而交通之，胜于原方，以其流利不滞。段中讨论脉涩可下之例及治法加减，主旨在治法，故归治法。脉象要素取涩。", ["涩"]], "5784": ["病机", "下血后大便燥闭不爽，继而自利白滑胶黏、日数十行，形衰脉沉。沉脉主里，此因久伏水谷之湿，湿滞肠道，府病宜通，故以温下法祛其伏湿。脉沉与形衰并见，说明病在里而正气已弱，湿浊内结，非单纯虚证。", ["沉"]], "5785": ["主病", "鼻痒心辣、大便下血、形瘦，脉小而数，已经数年。脉小为阴血不足，数为有热，热迫大肠则下血，形瘦脉小数示久病阴亏内热。鼻痒心辣亦为热象，此脉主阴虚内热、肠络受损之下血证。", ["小", "数"]], "5786": ["病机", "脉虚细数，原文明言“阴不足也”。虚细为阴血亏虚，数为阴虚生内热。鼠漏未愈，热在大肠，故脉见虚细数。此脉象说明阴液不足、虚热内扰，病位在大肠，与鼠漏日久耗伤阴分相应。", ["虚", "细", "数"]], "5787": ["其他", "诒按指出此肛门漏即鼠漏，脉证已属损象，故以滋补肝肾为主。原文未识出具体脉名，但明言“脉证已属损象”，说明脉象整体反映虚损，与肛门漏日久、肝肾亏虚的病机相应，故治法以滋补肝肾为主。", []], "5788": ["病机", "胎前子肿，产后大泄、厥逆，现形瘦、脉虚、食少、少腹满、足肿、小便不利。脉虚主正气不足，脾病传心、心传肝、肝传脾，五脏相贼，脾失运化则食少便溏，肝气犯脾则少腹满痛。此脉虚说明脏气亏虚、肝脾失调，故攻补递进无效，宜泄肝和脾。", ["虚"]], "5789": ["预后", "心营肾水交亏，肝气挟肝阳上逆，见胸中气塞、口常干、手震舌掉、心烦不寐，甚至便溏纳少，脉形细小无神而有歇止。细小无神为气血大亏、精神失守之象，歇止示脏气衰微。此脉说明心肝肾俱损、神魂不宁，预后堪忧，故拟真珠母丸法安神定志。", ["细", "小"]], "5790": ["病机", "邓评指出心烦不寐为心火亢，却见脉小、便溏，因火被湿痰所遏。脉小非纯虚，乃湿痰阻滞、气血不畅之象；便溏为湿痰困脾。此脉症说明痰湿内遏、火郁不伸，故于清心安神中参辛燥开痰，使湿化痰豁，木达风清。", ["小"]], "5791": ["预后", "孙评认为所述病情均因痰火上蒙致病，即便溏、脉歇，亦为痰滞于中、脾营胃卫不调和之症。若损证而见此脉歇，则正气垂绝，决无生理。原文未识出具体脉名，但“脉歇”与便溏并见，在损证中提示胃气衰败、生机将绝，故预后不良。", []], "5792": ["预后", "原文“脉之歇止向和”指歇止脉象趋于和缓，说明正气渐复、邪气渐退，故便溏不作、气塞稍平、手震亦定，为病情向愈之兆；但寤多寐少、胸痞脘闷，提示魂魄未安、浊痰未降，余邪尚存，故需通阳镇逆以竟全功。", ["歇止"]], "5793": ["病机", "邓评“脉之歇止，是亦疫之咎欤”以设问语气指出脉见歇止与疫毒有关。歇止脉主正气不足、脉气不续，疫邪耗伤正气，致脉行断续，故歇止为疫病之咎，反映邪盛正虚、气血运行不畅之病机。", []], "5794": ["病机", "原文“脉仍细小”“脉虚证虚，是谓重虚”，细小脉主气血两虚，重虚指正虚不复，兼湿痰为患。心易烦动、神疲气短、胸痞足不安，皆虚象；痰为有形之火，火为无形之痰，故法当固本为主、消痰佐之。", ["细", "小"]], "5795": ["病机", "“脉息细小带弦”中细小主气血两亏，弦主肝经风火痰留滞。虽无止歇之形，尚有不静之意，说明邪未全平、正未全复，故筋惕肉瞤、气短等症难免风波，未可以能食为足恃。", ["细", "小", "弦"]], "5796": ["病机", "原文未明言脉象，但述“脉亦随之变异”，指气逆时面赤心悸、肉瞤筋惕、烦热不安而脉随症变。此由肝胆余邪与痰火阻气，心火一动则相火随之，故脉象变动不居，反映火动痰扰、气逆不降之病机。", []], "5797": ["病机", "原文未直接描述脉象，而言“阳𫏋脉满，满则不入于阴，阴分之虚明矣”。阳𫏋脉满指卫气独行于阳、不得入阴，故寐寤失时；阴分虚指阴血不足，不能恋阳，故心阳太旺、神气外驰，治当滋阴以配阳。", []], "5798": ["其他", "诒按针对前案不寐提出异议，认为病由肝胆痰火所致，批评案中引“阳𫏋脉满”为强为牵合，且误将经文“阴虚”指为阴血之虚。此段未涉脉象，旨在辨析病机与经文本文，属学术评按。", []], "5799": ["病机", "原文未直接言脉，而述“阳𫏋脉满，营血不能充足，肌肉不能润泽”，指出卫气不得入阴、营血亏虚不能恋阳，故寐寤不安；兼痰火易烦、虚风内动、筋惕肉瞤、大便难通，为正虚邪恋、阴阳不交之候，调理极难。", []], "5800": ["病机", "原文未出脉名，仅言「不爽不安，无非痰火为患」，是据症推机而非据脉。邓评指出所引阳𫏋脉满经文「自是勉强」，即认为以脉满释痰火证据不足。故此段主旨为痰火内扰致不爽不安，属病机推断，脉象无从取字。", []], "5801": ["病机", "原文「脉形细小而兼滑数」，数为有火、滑为有痰、细属阴虚、小属气弱，四字合参，断为「虚弱之中，兼有痰火」。故见有时面红、咳嗽、气痞而短、烦热不安，及便燥溺短、筋惕肉𥅆、肢体动摇、神倦语言无力，皆阴虚气弱兼痰火之候，脉症相应。", ["细", "小", "滑", "数"]], "5802": ["其他", "此段为孙氏评语，称「论脉确合病机，得其要领」，乃评前文脉论切中病机，本身未出具体脉象，亦未直接言某病某症，故无可取脉字，主旨属评述性文字，归入其他。", []], "5803": ["预后", "阳络重伤，咳无虚日而五更为甚，口干盗汗、溺赤便溏，脉数而身热，数主热盛，热灼阴伤，故断「欲成损证也」。又咽中已痈，虑其加喘生变，权以清热存阴。脉数与身热并见，示虚热内炽、阴液日耗，为损证将成之兆。", ["数"]], "5804": ["病机", "溏泄已止而咳嗽未除，咽痛盗汗，脉数。数脉主热，前诊热邪未清，今泄止而咳、咽痛、盗汗仍在，脉仍数，说明「肺经尚有热邪」，热恋肺金，故咳与咽痛不除，盗汗亦由热迫阴泄所致，脉症合参定为肺热未尽。", ["数"]], "5805": ["病机", "便泄稀、身热轻、咽痛渐愈，而咳嗽腹鸣、神疲纳少，脉小带数。小为气阴不足，数为余热未净，故断「风热递减，气阴两亏」，而脾中之湿又从而和之为患。脉小带数正合热减正伤、湿浊内困之机，故治法补三阴、通三阳外佐崇土化湿。", ["小", "数"]], "5806": ["病机", "脾虚便溏、肺虚咳嗽、肾虚虚火上炎而咽干痛，脉弱无力，弱主气血虚衰，故断「元气伤矣」。三脏俱虚而脉弱无力，是元气大伤、气不充脉之象，与便溏、咳、咽痛诸症相应，故急宜补气育阴，脉症合参确合病机。", ["弱"]], "5807": ["病机", "此段论素禀湿热兼挟阴虚，湿热与元气混为一家，又因膏粱嗜欲使湿热外增、阴精内耗，致风火相煽而耳苦鸣，陡然头晕面赤，为肝经之火、督脉之阳上冒。全段以病理论述为主，未出具体脉象，故脉字从缺，主旨归病机。", []], "5808": ["病机", "脉濡主脾阳不足、湿困中焦。原文身热、手心热、少力神倦、游利，皆脾阳下陷、阴火上乘之象。濡为软而浮，示阳气不运、湿浊内滞，故以甘温除热立法，正合脾虚阴火之机。", ["濡"]], "5809": ["病机", "右脉濡小主脾虚湿困，左脉浮弦主风邪外袭、肝木偏亢。劳倦伤脾，风湿乘虚而入，故见舌苔薄白、溺赤便溏、肢体疫楚、神倦嗜卧、少纳口干，皆脾弱湿滞、风扰之候，脉症相合。", ["濡", "小", "浮", "弦"]], "5810": ["病机", "脉形软弱为脾之营卫虚衰之征。原文谓肌肉暗消、脘痞纳少、力乏嗜卧，皆脾虚不运、营卫不调所致。八八已过之年阳气必衰，故治法以健脾为主兼壮元阳，使火土合德，正合软弱脉所主之脾虚阳弱病机。", ["软", "弱"]], "5811": ["病机", "心脉宜大反小、肾脉宜沉反浮，浮为伤、小为虚，示心肾不交、封藏失职。读书攻苦耗伤心肾，故脉失其常。原文以婴儿姹女喻心肾，须黄婆（脾土）媒合，舍补中宫无他法，脉象正是心肾虚而不交之据。", ["小", "浮"]], "5812": ["治法", "此段承前文而申治法：肾脉浮者宜补真阴。肾主封藏，脉当沉而反浮，是阴不敛阳、封藏失职。故以补真阴为要，并参疏补中宫为黄婆媒合之义，使心肾相交。脉浮在此非表邪，乃肾阴虚浮之象，故主补真阴。", ["浮"]], "5813": ["病机", "脉从内变而为细弦，细主阴虚，弦主饮邪内结。原文日间恶寒、夜间发热，是阳虚恶寒于日、阴虚发热于夜，阴阳正气俱虚，疟后余邪为患，致浮肿腹满溺短、脾不运化、肺咳生痰。形瘦色黄舌白，阳分更亏，极易致喘。", ["细", "弦"]], "5814": ["病机", "尺脉无力，主肾虚阴阳并弱。类中之余足不任身、手难举物，乃下元虚衰、筋骨失养所致。尺候肾，无力则肾中阴阳俱亏，故拟河间地黄饮子法，补肾填精、阴阳并补，正合尺脉无力所主之肾虚病机。", []], "5815": ["病机", "此段申明尺脉无力为阴阳并弱，是地黄饮子对题之旨。然类中本虚之中必有风痰湿热错杂，观膏方加萆薢、三诊加蝎尾可知。故病机非单纯虚损，乃本虚标实、虚实夹杂，尺脉无力仅示其本虚一面。", []], "5816": ["病机", "脉息迟弦，迟为阳虚失运，弦为痰气内郁。原文谓痰气为标、阳虚为本，故脉迟主本虚，弦主气逆痰动。陡然语言蹇涩、口角流涎，是痰随气上蒙窍；小水甚多、肢麻无力，正合阳虚不化、痰湿阻络。脉症相参，病机为阳虚痰气上逆，法当扶阳运中化痰。", ["迟", "弦"]], "5817": ["病机", "脉形弦迟，迟主中虚阳弱，弦主风痰内动。原文称中虚湿胜之体易生痰动风，内风既动招外风，故见左肢痿而不用、口歪流涎、舌苔起腻、便溏溺少。弦为风动之象，迟为湿胜阳微之征，脉症合参，病机属中虚湿胜、痰动风生。", ["弦", "迟"]], "5818": ["病机", "脉迟主阳虚寒湿，便溏为脾运不健、湿痰内停之证。原文因便溏脉迟而立温化湿痰之法，兼疏外风，说明迟脉在此反映中阳不足、湿痰内盛，非热非实。脉迟与便溏相应，共示阳虚湿痰之病机，故治法以温化为主。", ["迟"]], "5819": ["病机", "脉形细小，为日久正虚、气血不足之象；左关独见弦数，弦主风寒湿痹阻，数示三气渐见化热。原文谓鹤膝风乃风寒湿三气合病，又挟肺金之痰痹肘，肌肉暗削、行步无力皆正虚之征。细小与弦数并见，正是正虚而痹邪化热之病机。", ["细", "小", "弦", "数"]], "5820": ["病机", "脉形小滑，小为正气不足，滑主痰涎内盛。原文谓痰热内郁心包、无路可出而作心风，故见神识不清、自言自语、起坐无常、寤寐失度，舌苔白腻亦痰湿之征。滑脉应痰，小脉应郁，脉症相合，病机为痰热郁闭心包，久则归入癫痫。", ["小", "滑"]], "5821": ["病机", "脉弦滑数，弦为肝火冲激，滑主痰涎，数主积热。原文谓胃有积热、动血生痰，又被肝火所冲激，故唇起红筋、发则牵动而厥、厥醒吐沫、咳血鼻衄、二便失调。弦滑数三象并见，正合热盛痰动、肝胃火冲之病机，为痫证之根。", ["弦", "滑", "数"]], "5822": ["病机", "脉芤带滑，芤主心血本虚、脉道不充，滑主痰涎袭入。原文谓心悸从惊恐得之、经年不愈，手振舌糙、不耐烦劳，皆心血亏虚之征；痰涎乘虚袭入，故脉兼滑。芤滑并见，说明虚中夹痰，病机为心血本虚而痰涎内扰。", ["芤", "滑"]], "5823": ["病机", "左寸脉息上浮，关部独带弦数，右寸与关小而带弦。浮为神蒙善忘、病涉心包之象，弦数为肝火冲激，小为脾虚。原文谓脾经湿痰被肝火冲激、累及心包，故白苔满布、大便久溏、肢体无力、倦怠嗜卧。脉症相参，病机为脾湿痰盛、肝火冲激累及心包。", ["浮", "弦", "数", "小"]], "5824": ["病机", "脉滑主痰，数主热。曾失血则阴亏，阴虚生内热，灼津为痰，故内热吐痰、夜来大魇。滑数脉象反映阴虚挟痰之病机，痰热内扰，心神不宁，故见夜寐不安。", ["滑", "数"]], "5825": ["病机", "脉滑数，滑主痰，数主火，故断为痰火内盛。痰火内蕴，当忌滋腻温补，参、地、五味恐助痰火。此评从脉象推断病机，强调痰火为患，用药须避碍邪之品。", ["滑", "数"]], "5826": ["病机", "脉细弦，细主虚，弦主饮主痛。症见鼻血遗精、寒热盗汗，肺肾俱病、营卫并伤，然舌苔满布、二便失调、饮食不舒，显系脾湿痰阻。脉细弦应脾虚湿痰，故先宜化湿健脾，再商补剂。", ["细", "弦"]], "5827": ["病机", "脉中部太弦，弦主饮主痛。脘中拒按、隐隐作疼、筑筑而跳，乃湿热痰浊交阻于胃，失下行为顺之常。虽动则气喘言则亦然属下虚，然中部弦象独显，故未便独以虚治，当先祛痰湿。", ["弦"]], "5828": ["病机", "脉中部太弦，弦为木象，主肝胆气旺。下虚上实之证，中部弦必挟木火为患，木火刑金则喘，犯胃则脘痛。故用药须两不相碍，加蒌、连、桑皮以清木火，平妥中兼泻实。", ["弦"]], "5829": ["病机", "年逾古稀，肾气下虚，生痰犯肺，咳喘而脉微。微为阳衰气弱之象，肾虚不能纳气，痰饮上泛，本虚标实。脉微提示正气大虚，故当与峻补，补火生土以绝痰源。", ["微"]], "5830": ["治法", "此段为方药组成，金水六君煎合生脉散加核桃肉。虽未明言脉象，然从用药推之，乃针对肾虚痰喘、肺肾两虚之证，补命门、养肺金、化痰湿，属治法范畴，非单纯脉象描述。", []], "5831": ["病机", "原注阐述补命门火以生土、清生痰之原，使肺咳喘自宁。金水六君煎治脾肾，生脉养肺，桃肉补命门，丸药常服奠安下焦。此段论脾肾虚致痰之病机与治法思路，未涉具体脉象。", []], "5832": ["病机", "右脉濡数主湿热内蕴，左脉浮弦主风邪上扰。原文谓风邪湿热由上及下、由下及中，久咳不已则三焦受之，咳而腹满。跗肿、腹满、口燥舌剥、火升气逆，皆湿热弥漫三焦、气机升降失司之象，故脉濡数浮弦并见，示病机由肺及中下，非独一脏之咳。", ["濡", "数", "浮", "弦"]], "5833": ["病机", "脉数主热，配合舌红、口渴、痰浓、头疼，显系冬温之邪郁于肺分，从燥化热。寒热后咳嗽痰浓，是邪热灼津成痰；大便溏泄则热邪下迫。原文断为冬温郁肺从燥化，故脉数应热，治当泄之清之，脉数正是邪热内盛之征。", ["数"]], "5834": ["病机", "脉紧主寒，数主化热，寒伤营而化热，故见紧而数。咳嗽不止、呕吐紫血、咽干痛、苔白边青，为寒郁化热、肺胃失清降，热伤血络则紫血上溢。原文谓郁咳成劳最为可怕，紧数并见示寒热错杂、病势深入，非单纯表寒或里热可比。", ["紧", "数"]], "5835": ["预后", "舌青脉紧，孙评直断病情甚恶。脉紧主寒主痛，舌青为血行瘀滞、阳气不运之候，二者并见示寒凝血脉、病深难解。原文又批评用药平淡大不可法，说明紧脉在此非轻浅表寒，而是预后险恶之征，故归入预后判断，提醒不可等闲视之。", ["紧"]], "5836": ["病机", "左关独见浮弦且数，左关候肝胆，浮弦为风邪未解，数为郁热。伤风不醒、咳嗽呕恶、痰带血色、小有寒热，皆风邪郁于肝胆、木火刑金之象。原文称此损征之根，说明浮弦数脉示风热内扰、正气渐伤，非单纯外感，故为虚损之萌芽。", ["浮", "弦", "数"]], "5837": ["病机", "脉形弦细数，弦主风邪未尽，细主中下两虚，数主余热未清。咳嗽大减而痰仍青黄、身热虽轻、咽中苦痛，正是风邪留恋、阴液已伤之候。原文谓风邪未尽、中下两虚，故脉弦细数并见，示邪少虚多、虚实夹杂，治参猪肤法以兼顾身热咽痛。", ["弦", "细", "数"]], "5838": ["病机", "左关脉息弦硬不和，左关属肝胆，弦硬示肝胆留邪、气机刚劲失和。咳嗽大减、红痰已无，但痰色尚带青黄，说明邪未尽退。原文谓肝胆留邪容易犯肺胃俞，弦硬不和正是木气偏亢、易乘肺胃之象，故虽症减仍须警惕，不可疏忽。", ["弦", "硬"]], "5839": ["病机", "右脉弦滑而数，原文自解：滑为痰，弦为风，风郁为热，热郁为痰。风热痰浊阻于肺，清肃不行，故咳嗽自作。弦滑数三脉并见，正合风、热、痰交阻之机，右脉候肺，脉象与咳嗽症候相应，示病位在肺而病性属风热痰郁。", ["弦", "滑", "数"]], "5840": ["病机", "脉息细弦而紧，细为脾虚湿蕴，弦主痰饮，紧则为寒。原文谓“紧则为寒，寒风新感”，说明久咳脾虚积湿生痰，又新感寒邪，故身热口干苔白。脉紧提示新邪为急，当先疏化，补中寓化需缓图。", ["细", "弦", "紧"]], "5841": ["预后", "原文未识脉名，仅言“脉未促，气未喘”，强调不可因脉未促、气未喘而轻视。久咳喉痒，火逆上气，咽喉不利，最易成劳。脉未促虽暂未至危候，但病机已示肺阴耗伤、虚火内灼，预后须防劳损。", []], "5842": ["病机", "右寸脉息浮弦，弦者痰饮也。肺气虚不能通调水道，聚液为痰，积湿为饮，故咳而喘息有音。浮弦见于右寸，主肺中痰饮内停，兼有虚象。补肺健脾以绝生痰之源，清贮痰之器，正合病机。", ["浮", "弦"]], "5843": ["病机", "左脉浮弦为感风之脉，浮主表，弦主风；脉紧为感寒之脉，紧主寒。原文以脉辨外感风寒：风邪伤卫则鼻塞恶风，寒邪束表则恶寒体痛发热。脉象与症候相应，示六淫外袭，营卫失和。", ["浮", "弦", "紧"]], "5844": ["病机", "未识脉名，从症析机。咳血、梦遗、畏火更甚，因天符之火行于夏时，外火引动痰火，肺金久伤，清肃下降失职，不能生肾水，相火上炎。畏火乃肝火乘胃。法宜泻肝清火，使火降金清，诸证可平。", []], "5845": ["病机", "脉形滑数，独见肺胃两部。滑主痰湿，数主热，示阳明湿热之邪归于中土，逆克于肺。故睡醒吐青黄绿痰或带血点，右胁隐痛。肺胃同病，湿热痰火交蒸，宜清化肺胃立方。", ["滑", "数"]], "5846": ["病机", "未识脉名，邓评指出病由相火内亢，更多痰湿夹杂。用生地助痰，火反受遏，窜于络脉故胁痛。此论药误致变，相火与痰湿相合，络脉不通，胁痛由生，示痰火窜络之病机。", []], "5847": ["病机", "左寸脉数而小，合“脉数虚者为肺痿”之训，主肺虚有热；右关数疾且独大独弦独滑，主阳明胃经湿生痰、痰生热，薰蒸于肺。肺虚胃实，母病及子，故咳臭痰络血、便结苔白，治当兼顾虚实。", ["数", "小", "大", "弦"]], "5848": ["病机", "右关候脾胃，弦滑并见，是痰湿浊邪壅聚于胃之象。湿浊内聚则脉滑，热被湿遏、湿为热蒸则脉弦。原文谓“必多痰湿浊邪壅聚于胃，热被湿遏，湿为热蒸”，说明咳嗽之因不在肺而在胃中湿热痰浊上蒸，故见右关弦滑，主痰湿壅胃、湿热内蒸之病机。", ["弦", "滑"]], "5849": ["病机", "右关候胃，脉大弦数，大主热盛，弦主气机郁滞，数主热。原文谓“热遏于中，不得肃化”，是胃中热邪被遏，失于肃降宣化，故脉见大弦数。热遏于中则津不布化，反致痰热胶结，故评者主张去阿胶、生地之滋腻，恐“热得补而愈壅”，主胃热壅遏、肃化失职之病机。", ["大", "弦", "数"]], "5850": ["预后", "右脉候脾胃，前诊右关弦滑数，今“右脉亦缓”，缓为胃气和调之象，说明药后湿热渐化、胃气来复。原文“诸恙向安，右脉亦缓。药能应手，何其速也”，是以脉转缓和判断病情向愈、药证相合，属预后良好之征，故再守原法观察动静。", ["缓"]], "5851": ["病机", "右关大脉已除，是胃中实热渐减；然弦滑未化、数脉与寸相同，说明湿热痰三者仍存。原文谓“湿热痰三者，尚有薰蒸之意，肺必难于自振”，弦滑主痰湿，数主热，湿热痰浊上蒸于肺，肺气受困难以振肃，故主湿热痰残留、肺失清肃之病机。", ["大", "弦", "滑", "数"]], "5852": ["病机", "右寸候肺，脉数而空大，数为有热，空大为阴气不足、脉道不充。原文谓“肺虚则易招风”“阴气必虚”，是肺阴亏虚、虚热内扰，故脉数而空大；又兼阳明胃经湿热薰蒸之气未清，故虽以养阴为主，仍须兼理胃中湿热，主肺阴不足兼胃中湿热之病机。", ["数", "空", "大"]], "5853": ["病机", "右脉小中带数，小为阴血不足、脉道不充，数为有热。原文谓“肺阴不足，肺热有余；其所以致此者，仍由胃中之湿热薰蒸也”，说明肺阴亏而肺热有余，脉见小中带数；其根源仍在胃中湿热上蒸于肺，故主肺阴不足、肺热有余、胃湿薰蒸之病机。", ["小", "数"]], "5854": ["病机", "脉来芤数，芤主失血伤阴、血去脉空，数主火热。原文述吐血盈盆成块、火升颧红、咳逆时作、大便不爽而黑，断为“阳明胃腑必有伏热”。胃中伏热上冲，灼伤阳络则吐血，血去阴伤则脉芤，热盛则数，故主胃腑伏热、阳络损伤、防再冒再厥之病机。", ["芤", "数"]], "5855": ["病机", "脉数左弦，数主火盛，左弦主肝木偏亢。原文谓“久嗽失血，鲜而且多”“金受火刑，木寡于畏，以致阳络被伤”，是肺金受火刑伤，肝木失其所畏而亢逆，木火刑金，灼伤阳络则咳血。数脉示火盛，左弦示肝亢，故主木火刑金、阳络被伤之病机，防其冒厥。", ["数", "弦"]], "5856": ["病机", "脉形弦数，弦主郁、数主热，合瘀血内阻、郁而化热之机。瘀阻胸前则窒塞，热伤肺胃则咳逆不爽、舌红苔黄。脉象与症候相应，提示瘀热互结、肺胃受伤，久则易成损证，故原文诫“慎之”。", ["弦", "数"]], "5857": ["病机", "脉弦数而苔黄，弦为风郁、数为热盛，苔黄为热蒸之象。邓评据此指出“风热郁恋”，即外风与内热相搏，郁于气分而未解。脉症合参，风热留恋为当前主要病机，故所用方药“亦非背谬”。", ["弦", "数"]], "5858": ["病机", "痧后久咳四月，纳少形瘦、肤热脉细。细脉主阴血不足，此因余邪内恋、久咳伤阴，阴分大虚而脉道不充。颈旁鬁串、咳甚则呕，皆阴亏邪恋、肺胃失和之征，故断为“欲成损证”。", ["细"]], "5859": ["病机", "孙评以“咳而肤热脉细”为据，细脉示阴分已伤，肤热示余热未清。痧后久咳，余热留恋入肺，灼伤肺阴，故脉细而热不退。此非血虚可温，故言“芎、归不宜”，强调病机在余热伤阴而非单纯血亏。", ["细"]], "5860": ["病机", "温邪发痧后咳血，血止而咳不减，痰黄白稠稀不一，舌深红苔满白，喉痒嗌干，脉弦带数。弦主郁热未清，数主热盛，热郁肺络则咳血，热灼阴津则嗌干，渐成“痧劳”之象，病机为余热恋肺、阴分受损。", ["弦", "数"]], "5861": ["病机", "原文未识出具体脉名，仅言“据此苔脉，邪郁尚重”。邓评从苔脉合参判断邪气郁结仍深，未至解散，故主张“还当著意疏邪”。本条主旨在于凭苔脉定邪郁轻重，提示当前病机重心仍在邪郁，不可早补。", []], "5862": ["病机", "子后咳嗽、天明而缓，脉形弦数，声音不扬。子后属肝胆主时，弦为肝脉、数为火象，弦数并见，说明肝胆之火未清，木火刑金则咳，金受其刑则声不扬，火灼日久必暗耗肾水，故曰“水必暗亏”。", ["弦", "数"]], "5863": ["病机", "原文未识出脉名，邓评专就“子后咳嗽”立论，认为子后乃肝胆主时，此时咳作正是肝胆之火上逆之征，并称此为“诊脉之关键处”。虽未列脉象，其病机分析仍紧扣时辰与脏腑关系，指明火在肝胆。", []], "5864": ["病机", "脉浮促而数，浮为燥气外袭，促数主热，肺阴久伤又兼燥气加临，故咳嗽失血、音烁咽干；小有寒热头痛喉疼为燥热上扰。脉浮促数反映燥热伤肺、阴亏失润之病机，治当补肺中参辛散。", ["浮", "促", "数"]], "5865": ["病机", "脉芤数，芤主阳络频伤失血，数主内热；左关独弦为肝火偏旺。肝火刑金，金气不清，故咳嗽痰浓、嗌干。脉芤数弦并见，示失血后阴亏火旺、肝火犯肺之机，容易成损。", ["芤", "数", "弦"]], "5866": ["病机", "脉数左关弦急，数主火，弦急为肝火亢盛之象。失血后咳嗽梦遗，乃肝火在里，上犯肺金则咳，下泄肾气则遗。脉数弦急正是肝火内炽、上下交攻之病机，久延势必成劳。", ["数", "弦", "急"]], "5867": ["病机", "脉数左弦，数主阴亏火旺，左弦为肝木失养。失血久咳阴分必虚，水不涵木，阴火上冲，故咽痛、唇干、溺黄；苔白色滞为胃气不清。脉数左弦示阴虚火炎、肝胃不和之机，势欲成劳，脉不加促庶几可图。", ["数", "弦"]], "5868": ["病机", "此段强调脉数左弦为辨证着眼处。苔白色滞本似湿浊，然脉数左弦则知非单纯胃滞，乃阴虚火旺之征。数主火，左弦主肝阴不足，故断为阴虚。脉数左弦是识别阴虚火旺病机的关键。", ["数", "弦"]], "5869": ["预后", "再诊浊痰虽少而咳逆仍然，阴火上冲于肺，金受火刑，水之生源将绝。脉促为火热内盛、真阴耗竭之兆，故虑其脉促气喘。脉促在此提示病势危重，预后不良，当静养以延。", ["促"]], "5870": ["病机", "脉数左弦，数主火，左弦主肝阴亏虚。水不涵木，阴火上冲，故咽痛；苔白为胃气不清之证。脉数左弦反映阴虚火旺、肝胃同病之复杂病机，头绪虽繁，方药须一一对应。", ["数", "弦"]], "5871": ["预后", "脉形细数，细属阴亏，数为有火。火上刑金，水绝生源，故咳嗽虽小恙不可轻视。幸气息未喘、脉象未促，示火势尚未鸱张，静养可望保全。脉细数主阴虚火旺，脉未促为预后尚可之征。", ["细", "数"]], "5872": ["预后", "原文言“苟至气喘脉促，更且临危矣”，脉促为阳盛气急、心气衰败之象，气喘而促，提示正气将脱，故属临危之兆。未见潮热失血，尚属幸事，然脉促已露危候，预后不良。", ["促"]], "5873": ["病机", "脉小色白、小便清利，为虚寒之征，阳气不足，故可进温热重剂。脉小主虚，与色白溲清相应，说明病机属阳虚寒盛，非实热之候，故用启峻汤温补。", ["小"]], "5874": ["病机", "右脉弦滑主痰饮内结，左关坚急为肝气郁滞，寸部独小示心气下郁。食则右胁下痛、痰升得吐而安，乃脾弱生痰、心气郁于肝经，痰气交阻为膈，故脉见弦滑坚急。", ["弦", "滑", "坚", "急"]], "5875": ["病机", "脉象弦滑主痰浊内阻，食则噎痛、吐浊痰而止，胸前常闷，舌苔满白，皆痰浊交阻上焦之象。阴血本亏，阳气又结，阴液与痰浊互结，胃脘狭窄，久则防膈。", ["弦", "滑"]], "5876": ["病机", "脉形细涩，细主阴血不足，涩主瘀血内阻。得食则噎、胸前隐痛，乃瘀血阻于胃络，胃气不通，此膈证之根。脉证相合，瘀血内结为其病机关键。", ["细", "涩"]], "5877": ["其他", "原文未出脉象，仅言“脉证均合”，诒按此属瘀血膈，用药专注瘀血。脉证相合，说明前段细涩之脉与瘀血内阻之证相符，故为瘀血膈之诊断。", []], "5878": ["病机", "右脉涩数主痰瘀内阻，涩为血瘀，数为有热；左关独大且弦，为肝经气火亢盛。食则作痛、痛则呕吐，乃痰瘀阻于胸膈，更兼肝气火冲，故为膈证重候。", ["涩", "数", "大", "弦"]], "5879": ["病机", "脉弦主肝气冲逆，苔白、便溏溺清为湿痰内胜之征。食已即吐，乃湿痰内蕴，被肝经淫气上冲所致，故脉弦而苔白溲清，病机在肝气犯胃、痰湿上逆。", ["弦"]], "5880": ["病机", "脉迟为脾阳不足、湿浊内困之象。原文“少纳多胀，舌白脉迟”，纳少胀满由脾运失健、湿浊有余所致；舌白主寒湿，脉迟主阳气不振，故以茅术理中汤温中燥湿合四七汤理气，紧扣“脾阳不足，湿浊有余”之病机。", ["迟"]], "5881": ["病机", "胸痹由胸阳不旷、痰浊瘀血交阻膈间，故得食梗痛、便坚且黑。脉形细涩，细为阳微血少，涩为瘀血内阻、脉道不利，与“瘀血交阻膈间”相应；紫血上吐非顺，脉涩亦示血行不畅，故须下行为妥。", ["细", "涩"]], "5882": ["病机", "邓评指出“得食梗痛，便坚脉涩”，脉涩主瘀血内结、气机壅滞，食入梗痛因瘀阻膈间，便坚由瘀滞肠腑传导不利。涩脉与膈门病机相合，故谓可归入膈门，强调脉涩为瘀阻之征。", ["涩"]], "5883": ["预后", "胸痹久而不化，又值燥气加临，更增咳嗽咽干、痰中带红，脉形细小。细小为阴血亏少、脉道不充，久病正虚而燥邪伤肺，痰红咽干并见，正虚邪恋，故原文叹“治之不易”，示预后难期。", ["细", "小"]], "5884": ["病机", "痛厥两病兼见，右脉不畅、左脉太弦。弦为肝木亢盛，木乘土位则中脘痛、痞闷便闭；龙雷之火挟痰涎上冲，则溺余陡发痫厥、手足牵动。原文“弦则木乘土位而痛，又挟阴火上冲而厥”，故治当平木为主。", ["弦"]], "5885": ["病机", "邓评虽未出脉名，然阐发肝气久郁、阳亢化火生风之机：风阳升动则厥且痫，横乘于中则痛，直升于上则厥。溺余发作因肝脉络阴器，溺则肝阴虚而风阳陡动。治以酸苦辛制肝旺、疏肝郁，清火化痰并施。", []], "5886": ["病机", "厥平痛未止，便黑溺黄，右脉反弦。右脉候脾胃，弦为肝木乘土、诸邪合胃之象；便黑为瘀，溺黄为热，邪聚于胃，胃腑以通为补，故悬拟通降之方，从右脉弦看出病机关键。", ["弦"]], "5887": ["病机", "诒按点明“诸邪都合于胃，从右脉之弦看出”，右脉主脾胃，弦脉主肝木偏旺、邪气内结。弦见于右，知肝邪乘胃、诸邪聚于胃腑，故为病机紧要处，与上条便黑溺黄、痛犹未止相呼应。", ["弦"]], "5888": ["病机", "右脉反弦，是进酸敛后肝旺之气已减，胃脉得畅之象。原文谓“肝之旺气已减，故胃脉得较畅也，当属佳象”，说明弦脉本主肝旺，此时右脉见弦，非病进，乃肝气退而胃气渐舒，故为佳兆。", ["弦"]], "5889": ["病机", "脉形细数，主肝肾阴虚，气滞火升。原文谓“想肝肾阴虚，气滞火升，肺俞络脉因之俱受其伤也”，细为阴亏，数为火升，故见痛厥虽平而背腰隐疼、气逆咳呛，皆阴虚火升、络脉受伤之候。", ["细", "数"]], "5890": ["病机", "本段未识脉名，邓评谓“见证是肝家之气火留窜于络脉”，主张加山栀、钩钩、丝瓜络清经络郁火，姜汁反佐。可知病机为肝气化火，留窜络脉，虽无脉象可凭，而证候已显气火郁络之象。", []], "5891": ["病机", "脉形弦细，主阴虚挟湿热。原文谓“是阴虚而挟湿热也”，弦为肝旺，细为阴亏，湿热内蕴则苔白底红，腰脊疼、咳嗽不止，皆阴虚湿热交蒸、络脉不利之候。", ["弦", "细"]], "5892": ["病机", "脉小左弦，主脾气素虚、湿郁难化，肝木郁于内而不能伸。原文谓“脾气素虚，湿郁难化，而木之郁于内者，更不能伸”，故酸水酸味、灰白苔终无化日，脘胁胀痛，此臌胀之根。小为脾虚，弦为肝郁。", ["小", "弦"]], "5893": ["病机", "脉既左弦，主肝郁。邓评谓“附子终怕碍肝，参用柴、芍自合，金铃子散亦所需要”，说明左弦为肝气郁滞之脉，故用柴胡、白芍疏柔肝木，金铃子散行气活血，附子辛热恐助肝郁，故须慎用。", ["弦"]], "5894": ["病机", "脉形弦细而数，主血病。原文谓“更属血病见证”，痛起受饥得食则缓，午后剧、黄昏甚，但头汗出、便下紫色，皆瘀血内阻之候。弦为肝旺，细为血少，数为瘀热，故宜消补兼施。", ["弦", "细", "数"]], "5895": ["病机", "脉弦数，主肝家血瘀于胃脘。原注谓“便紫脉弦数，肝家之血必有瘀于胃脘者”，弦为肝病，数为热，便紫为瘀血下出，故须去有形瘀滞，兼补脾虚，双管齐下，痛根乃拔。", ["弦", "数"]], "5896": ["病机", "脉弦为肝木乘土之象，数主热，弦数并见说明寒热错杂之邪郁于中焦，肝木乘脾，积饮冲逆。原文“胃脘当心而痛，少腹气升，呕吐酸苦痰涎”正是木乘土位、饮邪上逆之症，故脉形弦数主此病机。", ["弦", "数"]], "5897": ["病机", "脉弦数主肝胆郁火，弦为肝脉，数为火象。原文“呕吐酸苦，脉形弦数”明示肝胆郁火必盛，虽属寒热错杂，但郁火内炽，故附子恐有碍。此脉象揭示郁火为病机关键，与呕吐酸苦相应。", ["弦", "数"]], "5898": ["病机", "脉弦数、舌绛苔黄、口干苦、小便赤，一派火热之象。弦为肝脉，数主热，说明肝火挟相火从少腹上冲于心。原文“气从少腹上冲于心”正是肝升之气挟火冲逆，脉弦数主此火热病机。", ["弦", "数"]], "5899": ["病机", "脉弦而数，弦主肝郁，数主火，说明郁气化火。原文“脘痛下及于脐，旁及于胁，口干心悸，便栗溺黄”皆肝火郁结之症，脉数、溺黄为实火确证，故脉弦数主肝郁化火病机。", ["弦", "数"]], "5900": ["病机", "原文“为木郁而佐以逍遥散者，其脉必兼弦象可知”，弦为肝脉，主木郁。逍遥散证本属肝郁脾虚，脉弦象反映肝气郁结病机，与木郁相应，故脉弦主肝郁。", ["弦"]], "5901": ["病机", "脉形细小而数，细小主虚，数主热，说明中虚伏热。原文“当脐胀痛，按之则轻，得食则减”为虚象，“舌苔左黄右剥，质深红”为伏热之征，脉细小而数正合中虚伏热病机。", ["细", "小", "数"]], "5902": ["病机", "脉象弦急，弦主肝，急主痛，说明寒湿与痰内壅肝经、外攻经络。原文“少腹久痛，手足挛急而疼，舌苔灰浊”皆寒湿痰浊阻滞肝经之症，脉弦急主此病机，故宜当归四逆汤加减。", ["弦", "急"]], "5903": ["病机", "脉右弦左紧俱兼数，弦紧主痛、主寒湿痰浊，数主热，说明湿热之邪内犯肝经，挟痰浊上升。原文“少腹作痛，呕吐，舌苔浊腻，口中干苦，头胀溺赤”皆湿热痰浊之症，脉弦紧数主此病机。", ["弦", "紧", "数"]], "5904": ["病机", "呕吐减而腹痛下痢、口干苦、小水短赤不平，脉紧数示寒热错杂之邪未解。紧主寒、主痛，数主热，紧数并见正是肝经寒热错杂、挟食滞痰浊为患之象，故诸症缠绵不肯平，仍须小心调治。", ["紧", "数"]], "5905": ["病机", "原文未出脉名，以肝脉布两胁抵少腹、同时作痛断为肝病。肝旺必乘脾土，土中痰浊湿热相和为患，说明胁腹同痛之病机在肝木犯脾、痰湿热互结，非单纯气滞，故势所必然。", []], "5906": ["病机", "气结于左，自下盘上，胀疼有形而解则无迹，甚则脉形弦数、口舌干燥。弦主气结、主肝，数主火，正是气有余便是火之见证，故急须化肝以解气火郁结。", ["弦", "数"]], "5907": ["病机", "左脉细涩、右部小弱，细涩示血少而脉道不利，小弱示气虚，合为气血久虚、营卫失于流行之象。病势不增不减，正因虚而无力逐邪，故非大建其中不可。", ["细", "涩", "小", "弱"]], "5908": ["病机", "寒入厥阴，脉当见迟细弦。迟主寒，细主阳虚血少，弦为厥阴肝脉之常，寒邪客于厥阴则脉道收引而见弦，三者合参正合寒入厥阴之候。", ["迟", "细", "弦"]], "5909": ["病机", "狐疝属肝经之湿随气下陷，脾阳必衰；夏食冷物更遏阳气，故苔白不干、指冷脉小。脉小示阳气被遏、气血不充，右睾丸胀大乃湿气下坠，当以温散振阳化湿。", ["小"]], "5910": ["病机", "寒气客于肠外，与血沫相搏，脐下结瘕胀坠作痛，痛则气升自汗，脉形弦涩。弦主寒痛、主气结，涩主血滞，寒凝血沫阻结故脉弦涩，此为臌胀之根，不可忽视。", ["弦", "涩"]], "5911": ["病机", "脉来细而附骨者主积。细示气血内敛，附骨沉伏示积结深痼；偏于胁下牢不可破，是寒食挟痰阻结气分，气行则作响而积块不移，故为胀病之根。", ["细", "牢"]], "5912": ["病机", "脉弦数，弦主郁滞，数主热，结合二便黄热、干咳不爽、面黄苔白，说明湿热痰食互相阻滞，积久化热，食入而痛，为积滞内停、湿热蕴结之病机。", ["弦", "数"]], "5913": ["病机", "原文未识脉名，据症脉为火被寒郁，郁火腹痛，食入而痛，或蛔动于中，因无食积见端，故拟椒、萸、梅、连，属寒热错杂、火郁腹痛之候。", []], "5914": ["病机", "脉形弦细，弦主郁、细主虚，寒热后脘左隐癖作疼，舌苔浊厚，为湿热痰食交相为患，留滞络脉，气血不畅所致。", ["弦", "细"]], "5915": ["病机", "脉细兼弦，细为湿滞，弦为肝郁，起于寒热后，内有留邪，癖疼偏左，是湿热痰食中挟肝气为患，故宜金铃子散平肝。", ["细", "弦"]], "5916": ["病机", "脉形弦细，弦主湿郁，细主脾虚，脘腹膨胀、二便失调、经络酸痛、四肢无力、苔白腻厚，皆湿邪内郁、脾运不健之象，当苦辛宣泄。", ["弦", "细"]], "5917": ["病机", "脉细而弦，细为脾弱，弦为木郁，苔白腻知湿胜有热蒸，湿热化解则脾健木达，诸恙向安，说明脾弱木郁、湿热内蕴之病机。", ["细", "弦"]], "5918": ["病机", "脉息弦细，弦主木郁，细主脾虚，脾虚湿郁蒸热，隐癖僭逆中宫，大腹胀满、纳少便溏、面黄溺赤、咳嗽身热，极易成臌，为脾虚湿郁、肝木犯土之病机。", ["弦", "细"]], "5919": ["病机", "脉数多渴，数主火，渴主热，为郁痰作痛、火郁中脘之候，发即寒热，治以清中蠲痛汤，说明气火湿食血五郁化火之病机。", ["数"]], "5920": ["病机", "脉弦数，弦主气郁湿阻，数主热，合之则湿热内蕴。原文大腹胀满四十余日，气促足跗浮肿，溺黄口干，皆湿热因气而阻、因食而剧之象。湿热壅滞中焦，气机不利，故脉弦；热邪内蒸，故脉数。此脉此症，示湿热为患，理之不易。", ["弦", "数"]], "5921": ["病机", "邓评以脉形弦数推求病邪，弦为气郁湿阻，数为热，合之则湿热之邪内蕴。凭证脉相参，知大腹胀满、溺黄口干系湿热因气而阻、因食而剧所致。脉症合参，病机自明，无遁情矣。", ["弦", "数"]], "5922": ["病机", "脉息沉弦，沉主里主气郁，弦主寒主痛。原文腹大脐突属脾，胀无虚日、痛问作、舌苔薄白，见于经期落后之体，显系血虚不能敛气，气郁于中，寒加于外，脾湿不消。沉弦之脉，正合气郁寒凝、血虚湿滞之机。", ["沉", "弦"]], "5923": ["病机", "邓评谓脉息沉弦，尚非血虚不能敛气之比。沉弦主气郁寒凝，较之血虚不能敛气者，病机偏实。此评旨在辨明脉象所主，非纯虚之候，当从气郁寒湿求之，不可径作血虚论治。", ["沉", "弦"]], "5924": ["治法", "脉散主气耗不敛，虚寒腹胀而见散脉，示脾肾阳衰、气不归元。原文以附桂理中汤温补脾肾，加肉果、当归、牡蛎、木瓜、茯苓，更入生脉散敛气生津。脉散为气散之征，故治法温阳固敛并施，以复气机之敛藏。", ["散"]], "5925": ["病机", "邓评虚寒腹胀责之脾肾，偏肾偏脾须观胀处甚于小腹或脘腹。参入生脉散，想其舌光苔微，示气阴不足。虽未识脉名，然凭舌症推病机，虚寒为本，气阴亦伤，故温补之中兼敛养气阴。", []], "5926": ["病机", "脉数而见便溏、舌苔冷白、干喜热饮、肤热，数非热盛，乃脾阳大虚、虚阳外浮之象。脾阳无力运化湿浊，而成臌胀。此数脉主虚寒，与冷白苔、热饮相参，知为真寒假热，理之棘手。", ["数"]], "5927": ["病机", "脉弦，妨食气短，邓评谓似乎寒饮之内更挟木气之郁。弦主木郁，亦主饮邪。寒饮内停，木气不疏，则妨食气短。弦脉在此示肝郁乘脾、饮阻气机之病机，非单纯寒饮可比。", ["弦"]], "5928": ["病机", "原文谓浮肿胀满有增无减，乃阳衰已极，脐平而脉迟，迟为阳气不振、阴寒内盛之象。温补元阳本为正治，然温补不见长，因下泄更伤肾元，脉迟正示元阳衰微、肾气不固，故非温补不可而难取效。", ["迟"]], "5929": ["治法", "邓评强调此法不可浪用，必脉形洪数始能放胆。洪数为湿热亢盛之象，脉证相符方可用峻法清化；若湿热未去而中阳已惫，误用则伤阳。故以脉形洪数为用药凭据，示湿热内盛方可径用。", ["洪", "数"]], "5930": ["病机", "中阳不足则寒湿内生，脘痞纳少、舌白便溏皆寒湿困脾之症。脉细小为阳气虚弱、气血不足之象，细主虚、小主弱，正合中阳不振、寒湿有余之机，故法当温化，使阳复湿化而脉趋于平。", ["细", "小"]], "5931": ["病机", "素有隐癖，肝脾不调，血痢痞结日久，大腹胀满、溺赤舌黄，脉弦细而数。弦主肝郁，细主脾虚，数主湿热内蕴；湿热聚而脾虚无力以消，极易成臌，故脉象示肝脾两伤、湿热内聚之病机。", ["弦", "细", "数"]], "5932": ["病机", "脉弦数大，苔厚中黄，头痛及旁，为阳明湿热挟胆经风阳上逆。弦主肝胆，数主热，大主邪盛；湿热内蕴阳明，风阳循经上扰，故脉形弦数大而症见头痛，脉症相合，示湿热风阳交炽之机。", ["弦", "数", "大"]], "5933": ["病机", "原文谓证惟风阳上升，药惟滋熄和阳，而舌绛脉数亦从可知。舌绛为热入营阴，脉数为阳热亢盛；风阳上扰、阴分受灼，故脉数而舌绛，示风阳化热、阴伤之病机，与滋熄和阳之法相应。", ["数"]], "5934": ["兼症", "左关沉小带弦为肝气郁而不升，右脉弦滑则示湿痰内阻。弦主气郁痰凝，滑主痰湿；舌苔薄白、喜饮热汤亦为湿痰之征。故本段以右脉弦滑点出湿痰内阻，当与肝气郁结兼治，属兼症之辨。", ["弦", "滑"]], "5935": ["病机", "脉沉弦滑，腿骱刺痛、腰部疫疼、背脊作响、舌苔白浊，为风湿痰三者著于肝肾之络。沉主病在里，弦主痛主肝，滑主痰湿；痰湿流注经络，肝肾络脉痹阻，故脉沉弦滑而诸节作响疼痛。", ["沉", "弦", "滑"]], "5936": ["病机", "原文未明言脉象，但强调“全于苔脉得之”，可知凭苔脉合参断为风湿痰实邪。风性上行，却陷著肝肾之络，是因内被湿痰阻遏，气机不得宣通，故邪不外达而内陷。此非单纯风邪，乃风湿痰相合为患，故不可拘一例论治。", []], "5937": ["病机", "左尺脉浮而不静，由肾气下虚，封藏失职，故精不安处，见胫酸、体倦、耳鸣等。关部独弦独大独数，舌苔黄燥，是厥阴肝经湿热助其相火，火动摇精。虚则补，实则泻，此证肾虚而肝实，故泻法最要。", ["浮", "弦", "大", "数"]], "5938": ["病机", "原文未列具体脉象，但指出“于关尺脉与舌苔上见出”，关尺脉象必显湿热助火之征。湿热助相火为本症要旨，故肾脏虽虚，不可纯补，必须参“实则泻之”之法，泻肝经湿热相火，以安肾精。", []], "5939": ["预后", "再诊大便畅行，口中干苦亦愈，左关脉大者亦小，是湿热渐退、肝火稍平之象。惟弦数仍然，尺亦未静，说明余邪未清，相火犹动，肾封藏未复。故曰“可以前方增损”，示病势向愈而未尽，仍须清泄。", ["大", "弦", "数"]], "5940": ["病机", "口苦愈是火能下降、炎上作苦之势减，但脉尚弦数未静，弦主肝，数主热，知肝经伏火未清。故虽症减，仍当苦寒泻火著意，不可因症退而遽停清泻，否则余火复炽。", ["弦", "数"]], "5941": ["误治", "三诊湿热似去，邪势初衰，若速尔进补，则余邪未尽而补之，如炉烟虽熄、灰中有火，反致脉象复见弦数。弦数再现，是肝火复动之征，故仍不能舍苦寒泻火之剂。此段明示邪衰早补之弊。", ["弦", "数"]], "5942": ["病机", "大便已和，而脉形弦数，数为有火，弦主乎肝，知肝经伏火未清。肝火既伏，不但顺乘阳明，且易摇精，故虽精四日未动，究须小心。此以脉弦数断肝火内伏，主病在肝，兼防遗精。", ["弦", "数"]], "5943": ["病机", "左脉弦数，弦主肝，数主热，热伏肝家，动而不静，势必摇精。有梦而遗为实，无梦为虚，此属肝热疏泄太过，肾封藏不固。故就左脉弦数论，病机在肝经热伏，疏泄失度，非单纯肾虚。", ["弦", "数"]], "5944": ["病机", "左关独见沉弦且数，左关候肝，沉为气郁于里，弦为肝气劲急，数为郁而化热。迭进封髓秘元而仍不主蛰，正因肝经疏泄太过，封藏不固，故脉象独显于左关。此脉主肝郁化热、疏泄失职之病机，与遗精不藏相应。", ["沉", "弦", "数"]], "5945": ["病机", "脉息芤而无神，芤主失血，无神为精血暗伤、胃气衰败之象。曾经失血、现在遗精，精血互伤，当脐动气攻筑、语言轻微、饮食减少，皆虚甚之候。脉芤无神正合精血亏虚、中气不足之病机；然舌苔腻浊，又兼中宫湿邪，故虚中夹实。", ["芤"]], "5946": ["病机", "白浊久而不痊，肾失封藏，梦遗更甚，少寐少纳，面痿脉小。脉小为气血不足、正气亏虚之象，与久浊伤肾、封藏失职相应。肾精亏耗则面痿，脾胃亦弱则少纳少寐，脉小正示虚损之机，主肾虚不固、气血两亏之病。", ["小"]], "5947": ["病机", "阴虚之体，心火下郁于小肠，传入膀胱，尿中带血，时作时止，左脉沉数，小水不利。左脉候心与小肠，沉为火郁于里，数为热象，沉数相合示郁热内蕴。心火移热于膀胱，灼伤血络则尿血，气化不利则小水不利，脉象正合此病机。", ["沉", "数"]], "5948": ["病机", "淋证所下薄少，便时不利，便后隐痛，肢膝不温，脉小弦，唇红嗌干。脉小为虚，弦为肝郁余热未清，小弦并见示热未全消而虚已渐著。肢膝不温为阳虚失煦，唇红嗌干为阴伤有热，脉象与虚实夹杂之候相应，主淋久正虚、余热未清。", ["小", "弦"]], "5949": ["病机", "淋转癃闭，少腹硬满，小便肿胀，苔白不渴，脉小而沉。脉小为正气不足，沉主病在里、气机郁闭。下焦湿热被外寒所遏，膀胱气化不行，故小便不通而少腹硬满。脉小沉正合寒遏湿滞、气化失司之病机，原文称为急证，恐其喘汗。", ["小", "沉"]], "5950": ["病机", "原文仅言苔脉属寒，故宜温通为佐，未出具体脉名。苔脉属寒，示寒邪内阻、阳气不运之病机，故治法以温通为佐。此段为评注之语，从苔脉合参推断寒凝之性，主寒证当温通，与温散通阳之法相应。", []], "5951": ["病机", "飧泄不由胃滞即系阳弱，此乃兼而有之，脉迟，嗳腐脘痛。脉迟主阳气不足、寒从中生，阳弱则运化无力而飧泄；兼有胃滞则嗳腐脘痛。脉迟正合阳虚寒凝之病机，与飧泄、嗳腐、脘痛诸症相应，示虚寒夹滞之候。", ["迟"]], "5952": ["病机", "脉迟虽常主阳弱，但邓评指出不可一概而论，阳气窒滞亦可致迟。脘痛之证多因木气内阻，中挟相火，若误认脉迟为阳虚而用附子，则助火伤阴，故极宜慎用。此段强调脉迟需结合证候辨其病机，非独阳弱一端。", ["迟"]], "5953": ["预后", "肠游便血，时重时轻，或痛或否，脉形细小，饮食少，此属虚证。脉细小为气血不足之象，纳少则化源匮乏，虚象已著。恐增浮喘者，因虚不摄纳，气浮于上，肺肾俱损，故预后堪忧。", ["细", "小"]], "5954": ["病机", "便血前先见盗汗，盗汗由于寒热，寒热虽已而盗汗便血不除，脉小而数。脉小为气阴不足，数为虚热内扰。气阴两虚，营卫不和，故盗汗；气虚不摄，故便血。此脉象揭示气阴两虚之病机。", ["小", "数"]], "5955": ["病机", "血内溢者病源虽多，但见面黄兼白、浮肿眩悸、肢酸力乏，血色淡红而非深赤，脉象虚濡而不弦实，为阳分受伤偏重。虚濡示阳气不足，不弦实说明非实热迫血。附子适用于阳伤者，否则助火灼阴。", ["虚", "濡"]], "5956": ["预后", "湿热伤营，腹臌便血久而不愈，左脉细涩，右芤、寸大尺小，加以浮肿，气分亦虚。细涩为营血亏涩，芤主失血，寸大尺小示气浮于上、下元不足。气虚无以摄血，亦不能清化湿热，防喘者，虚气上逆也。", ["细", "涩", "芤", "大"]], "5957": ["病机", "病将一载，肝气横逆不平，中气久虚不振。肝逆故胸脘阻塞攻冲，中虚故营卫不和寒热。大便溏、饮食少、右脉细、左脉弦，右细主中气虚弱，左弦主肝气横逆，脉证相合，故以四君子合逍遥加左金治之。", ["细", "弦"]], "5958": ["治法", "寒热而便溏，脉细弦者，细为脾胃虚弱，弦为肝气偏旺。邓评主张兼温理脾胃营卫，如桂枝、煨姜、大枣之类；肝逆攻冲，金铃子亦在需用。方内川连或可删去，因脉细弦非实热，苦寒易伤中气。", ["细", "弦"]], "5959": ["病机", "邓评推论病源，认为脉虽未见，而关尺想必弦大且数。关尺候肝肾，弦大为肝阳亢盛，数为热象，提示下焦肝肾火旺。此虽未诊得实际脉象，但据证推脉，可知病机属肝经火热内郁，制方精切不泛。", ["弦", "大", "数"]], "5960": ["病机", "脉细数弱，细为血少，数为虚热，弱主气虚，合之则气血两亏。原文以骨格瘦小、先天元气不足为本，夏秋寒热久延，身痛而口沃清水，显系胃阳虚惫、中气不运，故脉弱不任按。细数非实火，乃虚阳浮越之象，故治法当商温补，仿东垣补中益气之意，不可作外感实热论。", ["细", "数", "弱"]], "5961": ["治法", "此段承前案脉细数而发，邓评指出细数之脉既见，则阴营已伤，单事温补恐耗营阴，故主张兼养营阴、转方为妥。细主阴血不足，数主虚热内扰，与气血两亏、胃阳虚惫之证相参，提示温补之中须顾护营阴，不可一味升提温燥，属治法上的斟酌补正。", ["细", "数"]], "5962": ["病机", "左脉空大，空为脉中无物、按之豁然，大则外强中干，此肾水亏虚不能充盈脉道之象。原文并见倦怠无力、食少，为脾气亦弱；食少则化源不足，阴虚生内热，故断为内伤。左脉候肾，空大非实邪，乃阴亏阳浮，与补中益气、六味补肾之立法相应。", ["空", "大"]], "5963": ["治法", "诒按承前案立法而议方，谓补中益气补脾气、六味补肾阴，立法切实。惟左脉空大，空大主肾阴亏而虚阳有上浮之势，升麻、柴胡升提发散，恐助浮阳上越，故尚宜斟酌。此段从脉象出发讨论用药宜忌，属治法范畴，体现凭脉审方、勿犯虚虚之戒。", ["空", "大"]], "5964": ["病机", "邓评进一步申明左脉空大不仅肾水亏，更知肝阳旺。空大为阴不敛阳、肝阳上亢之候，若再投升麻柴胡升提，则阳升至极，恐卒致晕厥。此段由脉象推阐肝阳亢逆之机，与肾水亏于下、肝阳浮于上相应，提示升柴之禁，属病机分析。", ["空", "大"]], "5965": ["预后", "首诊两手关脉见一粒厥厥动摇之象，为土虚木胜、内风动跃，症见左半肢体麻木、头眩面麻，属偏枯虑延仆中。再诊动摇之脉大减，是内风有暗熄之机，左手屈伸稍安而左足麻木未和，故拟补肾生肝治本。脉大减反映风阳渐平，与肢体渐复相应，主病势向愈之预后。", ["大"]], "5966": ["病机", "脉细而数，细主津血亏少，数主燥火内灼。原文以肺热叶焦、津液不能灌输经脉而致痿蹙，症见卧床不能行动、形肉消削、咳嗽痰臭、舌红无苔，皆津液消耗、燥火内灼之象。脉细数正合阴伤火旺之机，故治取阳明生胃津以供肺，仿喻氏意，属病机与治法相贯。", ["细", "数"]], "5967": ["其他", "此段为邓评按语，据苔脉而言火灼阴损已极，然风寒究竟闭郁，若痰黏厚而腥臭重者，可仿萎蕤汤法出入。原文未明标脉名，仅以苔脉并称，故脉象要素从缺。所论在阴损与风寒闭郁之间权衡治法，属对前案方药的补充讨论，归入其他。", []], "5968": ["其他", "本段为医论序言，未涉脉象。原文强调士君子不遇则隐于医，以'济人利物''救死扶生'为功，并指出医道须博通《内经》本草一百七十九家、洞明阴阳。全段论医之宗旨与业医者之素养，非论脉辨证，故无脉象要素可录，主旨属医道通论而非主病。", []], "5969": ["其他", "本段叙述游苕东双林、族兄之友吴小峰兄弟病目求诊之缘起，引秦越人随俗为变之例，言'医以通变为良'。全段为医案背景交代，未及脉诊，亦无病机推断，故脉象要素为空，主旨归于其他，不属主病、病机诸类。", []], "5970": ["主病", "妊妇腹痛昏厥五日，两手脉皆洪大。洪大为邪实壅盛之象，虽在妊娠九月，脉证相参知为里实当下，故取小承气加苏梗、砂仁下之而安。原文'法当下''有故无殒'正据洪大之脉断其实，非虚寒可比，示脉洪大主实积内结、气机不通之腹痛昏厥。", ["洪", "大"]], "5971": ["病机", "大头疫脉皆浮弦而数，浮为邪在表，弦为疫毒郁结少阳，数为热盛。服柴胡剂后寒热退、弦脉减而转洪大，原文'知其传于阳明也'，洪大示邪热入于阳明气分。脉由浮弦数转洪大，正反映疫毒由表入里、由少阳传阳明之病机演变，故以病机为主。", ["浮", "弦", "数", "洪"]], "5972": ["病机", "痛风周痹脉皆弦细而数，面青肌瘦、腿肉皆削。原文谓'禀气弱，下虚多内，以伤其阴'，阴血虚则筋失养，气为寒束则百骸拘挛，营卫不行故肢节肿痛而热。弦细数为阴虚血少兼寒郁化热之象，脉细应阴血不足，弦应拘急疼痛，数应郁热，故主周痹之营卫不通病机。", ["弦", "细", "数"]], "5973": ["病机", "左寸短弱、右关略弦、余皆洪大。左寸候心，短弱示心气不足，故病心痹；右关略弦应脾胃失调；余部洪大为虚阳外浮、火象假盛。原文症见咳嗽、午后足心热上至头面、形羸气促、多梦遗，正合阴虚火动、心气亏虚之机，诸医误作瘵火，实则脉证互参知为虚损。", ["短", "弦", "洪", "大"]], "5974": ["主病", "年六十七，过啖瓜果而胸膈胀痛，寸关弦紧。弦主痛、主气机郁滞，紧主寒主痛，寸关候上中二焦，弦紧并见示寒食积滞、气机壅塞于胸膈，故胀痛。原文'症脉虽胸腹胀痛，然易瘳也'，以脉弦紧为实滞可攻之据，与神藏气固相参，断其非虚损危候，主寒积中焦之胀痛。", ["弦", "紧"]], "5975": ["病机", "便血三年，左脉沉涩，右脉漏出关外。沉主里、涩主血行不畅，左脉候血分，沉涩示瘀血积于经隧、血行瘀滞；右脉漏关则脉位失常难凭。原文'必有瘀血积于经隧'正据左脉沉涩而断，前用升提探虚实，今得病情当下去根，故脉沉涩主瘀血内结、血不循经之病机。", ["沉", "涩"]], "5976": ["预后", "原文引「下痢脉洪大者死，细微者生」，痢疾日久，正气已伤，脉宜细微而反洪大，是邪热炽盛、正气外浮之象，故为逆、主死。然本案寒热如疟、痢下红白日夜八十余行、汗多神倦，洪大亦可见于邪正交争、热毒壅盛，故作者言「其中必有故」，提示不可仅凭洪大断死，当合症细辨。", ["洪", "大"]], "5977": ["病机", "原文「左手三五不调，右手沉弦」，又述「脉急缩也」「脉弦不退」。沉弦主饮、主痛，三五不调为气血乖违；面色青、腹中漉漉有声、息微，皆阳虚饮停、气机郁滞之候。前医误作伤风表散、又以丸药攻下，更伤中阳，故腹痛愈增，脉弦急缩不退，示饮邪内结、阳气受困之病机。", ["弦", "沉"]], "5978": ["病机", "原文「右滑大，左浮弦而数」。右脉滑大主痰湿内盛，左浮弦数主风火相煽；症见头痛恶寒、胸膈懑痛、时发寒热，正是痰湿挟风火壅遏上焦之象。前医以四物汤、玄胡索、丹皮、香附养血调经之剂投七十老妇，药证相左，故不瘥。脉症合参，病机在痰火风邪，非血分虚滞。", ["滑", "大", "浮", "弦"]], "5979": ["病机", "原文「脉左弦右滑数」，作者据「滑为痰，弦为饮」断为痰火症。跌仆胁痛，前医循公言作瘀血治，服行血破血二百余帖无效。若真瘀血，脉当沉伏、芤或涩，面必带黄；今脉弦滑数而不沉伏，且不咳嗽，知痰在经络不在肺，故痛而不上出。脉象是辨痰火与瘀血之关键，不可徇言遗脉。", ["弦", "滑", "数"]], "5980": ["病机", "原文「脉左弦大，右滑大而数」。患者年近五十，产多气血惫，积忧化火，症见晕厥、小水短涩、胸膈痛、烦躁干哕、内蒸热、肌削骨立。左弦大主肝火鸱张，右滑大而数主痰火壅盛，合「诸逆吐酸皆属于火」「诸风掉眩皆属于火」之旨，病机为痰火内扰、肝风上逆，故作者断为可生。", ["弦", "大", "滑", "数"]], "5981": ["误治", "本段未识脉名，纯述病史。患者过食鳗肉卷饼，心腹胀痛，本属食积，法当吐之；市医不吐而遽用硝黄下之，大便不行，胀痛愈增，继以木香槟榔丸、小承气、大承气、白饼子、备急丸、甘遂芫花大戟牵牛等峻下逐水，愈下愈胀，小便亦无。此屡用攻下、伤败中气、食积未去而气机壅塞更甚之误治过程，故归入误治。", []], "5982": ["病机", "原文「脉沉而濡弱」。沉主里、主水，濡弱主气虚阳衰。患者多怒多欲，胸膈痞胀、食少，屡服平胃、枳术、香砂及槟榔棱莪消削，致大便溏泻、手足浮肿、面黄且黑。脉沉濡弱正是脾阳不振、气虚不运、水湿内停之征，故断为「气虚中满症」，法当温补兼升提，使清阳升、浊阴降，非水肿实邪可攻。", ["沉", "濡", "弱"]], "5983": ["病机", "原文「六部皆洪长而数」。洪长而数主热毒炽盛、充斥三焦。患者季春连看戏文、多食鱼腥虾蟹，发寒热，耳前后颊车红肿，渐及满头红大如斗，眼合无缝，昏愦谵语，粒米不进八日。脉症合参，显系大头疫毒火热壅盛、上攻头面之病机，故以贯众、石膏、柴胡、葛根等清热解毒、升散郁火，日进二帖而脉减半。", ["洪", "长", "数"]], "5984": ["病机", "脉上盛下虚，上盛为痰火壅于上，下虚为精元亏于下。患者年甫逾疆而阳萎，正合下虚精弱；痰生热、热生风，风火相煽则上盛愈甚。故断三年内恐中风，治宜清上补下、戒色慎怒，乃痰火与精亏并见之候。", ["洪", "细"]], "5985": ["病机", "两寸短弱，心气不足；两关滑、两尺洪滑，湿痰下流，故白浊精淫淫下。脉书谓洪为湿痰，滑主痰饮，湿痰壅于下焦则尺脉洪滑。治痰必先理气，升降浮沉必顺天时，故待来春之仲一剂可瘳，非秘术不售也。", ["短", "弱", "滑", "洪"]], "5986": ["妇人", "左寸洪滑、两尺滑数，左尺之外更有神气，滑非经闭之脉，故知为孕而非病。发热腹痛乃气虚血热所致，非瘀阻经闭。以安胎饮加减，人参、白术、白芍为君，佐以香附、柴胡、条芩，四帖而腹痛减、热除，至期果生子。", ["洪", "滑", "数"]], "5987": ["预后", "初诊两脉皆软弱，产后气血未复，以佛手散加减温通而减半。后因食菱栗、激怒气，探吐泻下，元气脱而脉皆散乱如解索状，神气惫而恍惚，循衣摸床。散乱解索乃胃气将绝、真元涣散之死候，故病势危急，急用人参、白术固脱。", ["弱", "软", "散", "乱"]], "5988": ["病机", "六脉皆数，脉书云数脉所主，其邪为热，其症为虚。产后误下大泻，又温胆、小柴胡杂进，致热吐四日、粒米不进，昏愦耳聋，虚浮并见。数而兼散乱无伦，是虚热浮越、元气不敛之象，故以十全大补加炮姜温补，夜半稍清爽。", ["数", "散", "乱"]], "5989": ["病机", "右寸滑、左寸短弱，两关濡、两尺皆软弱。心肾俱不足，中焦不湿之说不确，实为脾虚湿注、气血日败，故白带久变白崩。脉经云崩中日久为白带，漏下多时骨木枯。法当燥脾兼补心肾，既济丹补心肾，断下丸燥中宫之湿。", ["滑", "短", "弱", "濡"]], "5990": ["病机", "两手皆驶，驶即数急之象。经前四肢发块红紫胀痛、胃脘常痛、经水不及期，症脉相参，乃肝脾二经郁火。肝主怒、脾主思，多思多怒隐而不发，郁滞于中，临经火动血沸，故红肿发于四肢。治以柴胡、川芎、香附疏肝，黄连、山栀清火。", ["数"]], "5991": ["病机", "右寸关皆数，右寸关主中上二焦。患者酒后恣情好男色，中宫多湿多痰，积而为热，流于下部，故白浊淫淫而下，久不愈而肌瘦膝软。数脉主热，湿痰郁久化热，下注精道。与加味端本丸清热燥湿化痰，服之而瘥。", ["数"]], "5992": ["病机", "六脉皆洪大，汗出如雨，喘息不相续，乃失足坠楼后瘀血内阻，气机逆乱，阳气浮越于外之危候。洪大为气分热盛或虚阳外越，此处兼汗出如雨、喘息不相续，显系气随血脱、阳气欲散，故脉象虽洪大而按之必虚，非实热可比。邻医误作吐衄实热，几致危殆。", ["洪", "大"]], "5993": ["病机", "两寸短涩，两尺洪滑，关弦。寸短涩主上焦气机不利，肺失宣降，故连咳两声；尺洪滑主下焦相火妄动，兼有湿浊；关弦为木郁克土。妓女经行仅一日点滴，又御客时遗精冷汗，乃金木相胜、心肾不交之候，脉象怪异正合其境。", ["短", "涩", "洪", "滑"]], "5994": ["病机", "六脉洪大，兼头痛身热、口渴水泻、昏沉耳聋、舌心黑胎，此疫症邪热充斥表里三焦，非虚寒可比。洪大为阳明热盛之脉，热邪弥漫，故脉象如此。前医误用补中益气、附子理中，乃以实为虚，反助邪热，故予断为疫症，法当清解。", ["洪", "大"]], "5995": ["预后", "两寸洪滑搏指，两关微弦，两尺微弱，乃《难经》所谓溢脉，上盛下虚之象。九月深秋木凋之时，脉不宜弦大，大则阳升无制，下无真阴相济。至次年二月木旺生火，火木上升不下，有阳无阴，有升无降，出入废而神机化灭，故断其不治。", ["洪", "滑", "弦", "微"]], "5996": ["病机", "六脉大而无力，主气血亏虚、正不胜邪。患者痛风日久，手足肢节肿痛，肌肉消半，月汛两月一行且少，显系气血耗伤，脾肾俱虚，湿浊痰瘀留滞经络，形成行痹。脉大无力正是虚中夹实之征，故予断为行痹，非纯实可攻。", ["大", "无", "力"]], "5997": ["病机", "左弦数，右洪大。左弦数主少阳肝胆热盛，右洪大主阳明气分热炽。头痛骨节痛、发热口渴、胸膈膨胀、七日不食，复感寒邪，表里俱实，热壅三焦。初用藿香苍术等芳化不应，改以麻黄葛根柴胡石膏双解表里，大汗出而热痛除，脉证相符。", ["弦", "数", "洪", "大"]], "5998": ["病机", "右寸脉绝不应指，关沉滑有力，左手弦数。右寸不应指非气绝，乃邪热壅塞上焦，肺气不宣，脉道不利；关沉滑为痰热内结中焦；左弦数为少阳胆热。合而观之，阳明少阳合病，邪热壅于上焦，非膈食不治之症，故法当解散，药后右寸脉起而愈。", ["沉", "滑", "弦", "数"]], "5999": ["病机", "尺寸脉隐伏不见，惟两关沉滑。尺寸无脉非六脉将绝，乃中焦食积痰浊胶固，气机壅滞，脉道不通，故尺寸隐伏。两关沉滑正是痰积中焦之明证。前医误作脾肾虚泄，用灸补涩，反固其积。予断为食积痰泄，下其积而六脉齐见，脉证相合。", ["沉", "滑", "伏"]], "6000": ["病机", "脉弦紧，弦主痛、主饮，紧主寒主痛。左膝肿痛年半，大便泻日三次，乃脾虚运化失职，湿热凝于经络，流注下部。肿属湿，痛属火，脉弦紧反映湿热壅滞、经络不通之病机，故以苍术、黄柏、薏苡仁清利湿热，佐防风、桂枝通络，使湿热去则肿痛消、泄泻止。", ["弦", "紧"]], "6001": ["病机", "右关滑大搏指，滑主痰饮食积，大主邪盛。下痢十二日，腹痛后重脱肛，嗳气不知饥，乃积滞固结肠胃间，气机壅塞所致。前医误用补中益气，反致腹痛后重加剧，脉象证实为实积而非虚陷，故当推荡消导，以木香、槟榔、枳实等调气消积而愈。", ["滑", "大"]], "6002": ["病机", "右关滑大有力，左脉和缓，滑主痰，大主火。五更耳鸣、腹不舒畅、劳则烘热自汗、眩晕呕吐，皆痰火所致，无痰不作晕。右关候脾胃，滑大有力说明中焦食积痰饮胶固已久，卒难动摇，故先以藿香正气散去表里之邪，继以温胆汤加天麻清化痰火，后以二陈汤加味调理。", ["滑", "大"]], "6003": ["病机", "左寸洪滑，左寸候心，洪主火盛，滑主痰。后半夜不睡、面黄肌瘦、太阳眉棱骨痛、便溏、劳则体热，乃脾虚肝心二经火盛。洪滑之脉反映心肝火旺、痰热内扰，故用四君子加酒连、柴胡等健脾清火，夜服安神丸，使火降痰消而诸症悉安。", ["洪", "滑"]], "6004": ["病机", "两关俱洪滑有力，洪主火，滑主痰瘀。上吐血下泻血，胸背胀痛，从怒触及犬肉所伤而起。前医作阴虚火动，滋阴降火，反致胸背愈胀、血来更多。脉象证实为肝脾二经有余之症，怒伤肝则呕血，脾伤则不能统血，瘀血使然，故当调气健脾兼消导，非阴虚也。", ["洪", "滑"]], "6005": ["病机", "原文未识脉名，仅言“喜左脉皆有神气”，知胃气未败。妇人有痰火，过服降火药，痰积气滞于大肠，脐边硬块，痢下红白，里急后重，腹痛潮热，口渴，小水不利。此痰积气滞、湿热壅阻大肠之病机，故从刘守真行血调气之法，使便脓自愈、后重自除。", []], "6006": ["病机", "脉仅四至，两寸软弱，脉尚不数。两寸候心肺，软弱主气血不足。孀居多年，蔬素，屡因怒吐血，又里急后重、肛门疼、小便短涩、经闭、白带如注、虚浮、不寐，乃肝郁化火、脾虚气陷、湿热下注之复杂病机。脉软弱不数，说明非实热亢盛，故用药需兼顾虚实。", ["软", "弱", "数"]], "6007": ["病机", "两寸濡弱，两关滑大。濡弱主气血不足，滑大主痰积。晕厥吐痰、口渴、五更倒饱、肠鸣腹痛泄泻、小水短涩、咳嗽，乃中焦痰积所致。两寸濡弱示上焦气血亏虚，两关滑大示中焦痰湿壅盛，故先以二陈汤加苍术、山楂、麦芽健脾祛湿，佐滑石、泽泻引湿热从小便出。", ["濡", "弱", "滑", "大"]], "6008": ["病机", "六脉俱数主气虚血热，数而无力为虚热之象；肝脉甚弦，弦则木气太旺，脾土受亏，不能统血。弦为肝旺克脾之征，故见左胁胀疼不能侧卧、饮食恶心、肌肉瘦削。数脉与面色白、两足痿弱并见，说明热非实火，乃气虚血热、木旺乘土、肺金不足之危候。", ["数", "弦"]], "6009": ["病机", "右关滑主脾胃有积滞痰食，左弦数主肝郁化火。大怒后伤食，肝气横逆，脾运失职，故腹有硬块、肠鸣、小水短少、饮食俱废。前医误用寒凉，脾气大虚，热愈甚。滑为食积之征，弦数为肝火之象，故治先平胃消积，继补中气而愈。", ["滑", "弦", "数"]], "6010": ["预后", "原文引陈女科言脉沉细者生、脉洪大者死，而此妇两手皆滑大、尺部尤搏指。滑大为积滞壅盛、邪实有余之象，非虚脱之洪大。虽身热噤口、滞下频仍，尺脉搏指说明病邪在下，可引而竭之。故断症非逆，乃误治所致，法从下夺可生，与洪大无根之死脉不同。", ["滑", "大"]], "6011": ["病机", "右关滑大主脾胃饮食积滞，左手软弱主血虚不足。平素血虚咳嗽，又为饮食所伤，专科误作阴虚治而用寒凉，致胸膈愈胀。滑大为实滞在脾，软弱为虚在肝血，故法当先健脾消食，然后治嗽；若继续补阴降火，则脾胃转伤，恐生腹胀泻泄之变。", ["滑", "大", "软", "弱"]], "6012": ["预后", "脉数而见吐血碗余、潮热咳嗽、冷汗淋漓、大便溏、肌肉消削，为阴虚火旺、气不归元之象。数脉主热，然此热乃虚火上炎，加之脾虚不运，故据症脉法在不治。后以泻白散清肺降火、佐以健脾收涩，汗止便实，脉数渐平，说明数脉在此主阴虚火动，非实热可攻。", ["数"]], "6013": ["病机", "右关尺滑大有力，关主脾胃，尺主下焦，滑为痰涎，大为火盛，有力为实。痰火壅滞中下二焦，故大便秘结、面赤、不思饮食、头时眩晕。此痰火实证，非虚秘可比，故用栝蒌为君、滑石枳实半夏为臣佐，清痰降火，两帖而愈。", ["滑", "大"]], "6014": ["病机", "右关洪滑主痰浊壅盛于中，左寸洪数主心火亢盛，两尺洪大主血海浊痰流滞。误服安胎之剂，益加其滞，致经水大行、血去过多，神魂无依，痰鸣心窍，故昏冒、咬牙乱语、口噤。洪滑数大皆实痰火之象，故急予调气开痰、安神养血，痰去则神清。", ["洪", "滑", "数", "大"]], "6015": ["病机", "尺寸俱弱主元气大虚，两关滑大主中焦有痰食壅滞。年高痢后过食，脾气不运，清浊相干，故大便滑泄不固、胸膈痞闷、语言无力、舌干生疮。弱为虚象，滑大为实滞，虚中夹实，故法当提清降浊、补助元气，不可纯补亦不可纯攻。", ["弱", "滑", "大"]], "6016": ["病机", "脉六部皆滑大有力，滑主痰，大主热盛，有力为实。患者头痛如破、晕倒不省、吐蛔、胸膈满闷、便秘，显系痰厥头痛，痰热内壅，上扰清窍，故脉滑大有力。此脉象与痰盛实证相应，非虚证可比。", ["滑", "大"]], "6017": ["病机", "两手脉滑数，滑主痰积，数主火热。胃脘痛、手心热、呕吐不食、昼夜叫痛，乃痰火内郁，阻滞中焦，不通则痛。脉滑数正是痰热搏结之征，故先清热止痛，继下痰积，脉症相符。", ["滑", "数"]], "6018": ["病机", "两寸关洪滑，六部皆数。洪为火盛，滑为痰聚，数主热。患者左胁痰饮上逆咽间，胀闷不知人事，遍身胀，小水赤，显系痰火生风，上蒙清窍。脉洪滑数正是痰火内盛之象，故断为痰火症。", ["洪", "滑", "数"]], "6019": ["预后", "产后脉不宜大，今脉大而左手散乱，散为元气离散，大则邪气盛而正气衰。更兼大热、气促、汗多、昏愦，法在不治。然医者以人参、白术、炮姜等温补固脱，脉转收敛，喘缓泻减，说明散大之脉主元气欲脱，非绝对死候。", ["大", "散"]], "6020": ["病机", "两手脉濡软无力，濡软主虚，为脾胃气弱、气血不足之象。患者产后欠补，精神疲困，腹中作痛作泻，正是脾胃虚弱，运化失职。脉症相合，故以六君子汤健脾益气，佐以理气化湿而安。", ["濡", "软"]], "6021": ["病机", "六脉洪滑，洪为热盛，滑主痰湿。患者发热、谵语、口渴、发斑、吐泻，乃少阳阳明合病，热邪炽盛，痰湿内蕴。脉洪滑与实热证相应，故用升麻葛根汤清解，后左脉已和，右脉收敛，示邪退正复。", ["洪", "滑"]], "6022": ["病机", "左脉浮弦，右脉洪滑。浮弦为风热上扰，洪滑为痰火内盛。患者耳焮痒、唇燥舌干、咳吐浓痰，乃胃中痰火流入肺经，郁久生热生风。脉象与痰火风热之病机相合，故先导痰、祛风热，继以清热化痰而安。", ["浮", "弦", "洪", "滑"]], "6023": ["病机", "右关洪滑，左手涩。洪滑主胃中痰热，涩主瘀血阻滞。患者咳喘吐痰、胸胀、便血紫黑，显系胃中瘀血痰积，肺气亦虚。脉症合参，先补肺气，后下瘀血痰积，去黑血屑而愈，说明涩脉主瘀血内停。", ["洪", "滑", "涩"]], "6024": ["病机", "脉虽五至而不甚充指，为血虚有热、气亦滞之象。小产后阴血亏虚，虚热内生，故夜分发热、口渴；气滞则脐下作疼、小便频数滴滴不断。湿热在气分故口渴，血虚故脐下痛。脉数主热，不充指主虚，合之则知血虚为本、湿热为标，法当峻补其阴而淡渗其阳。", ["数", "虚"]], "6025": ["主病", "两手寸关洪滑，两尺沉伏，为肠胃中有食积痰饮之征。洪滑主痰饮食积壅盛于中上二焦，故每五更倒饱、必泻一次、腹常作胀而间痛；两尺沉伏，示下焦气机不畅，积滞内阻。洪滑与沉伏并见，说明积滞偏聚肠胃，故用总管丸下之，继以香连丸等调理而安。", ["洪", "滑", "沉", "伏"]], "6026": ["病机", "左弦数，右关洪滑，为热入血室、痰火交作之候。弦数主肝胆热盛，洪滑主痰火壅盛。经行后热邪乘虚入血室，误服治疟刚燥之剂，动其痰火，故胸胁大腹作痛、谵语如狂、午后及夜痛甚；两手浸冷水中、鼻有微衄，皆热盛之象。脉症合参，标本交作，非单纯疟疾可比。", ["弦", "数", "洪", "滑"]], "6027": ["病机", "六部皆沉微，左尤甚，隐隐如蛛丝之细，为脾肾虚寒、湿盛阳衰之象。沉微主阳气不振，细主血少，合之则脾虚不运、积湿而然。症见脾泄不愈、面色黄白带青、两颐浮肿、四肢冷、口不渴，皆虚寒明矣。脉沉微与面色黄肿皆属于湿，诸湿肿满皆属脾土，故由脾虚不运、积湿所致。", ["沉", "微", "细"]], "6028": ["主病", "右滑大，左细弱，为体素弱而痰热壅肺之象。右脉滑大主痰热内蕴，左脉细弱主血虚不足。喘嗽夜分气壅不能仰卧、咳嗽连连数十声、痰不易出，皆痰热壅阻肺气所致；体素弱则正虚不能胜邪。滑大与细弱并见，说明痰热标实而气血本虚，故用人参平肺散加减，扶正与清化痰热并行。", ["滑", "大", "细", "弱"]], "6029": ["病机", "脉沉滑而数，为痰积内蕴、郁而化热之象。沉主里，滑主痰，数主热，故舌上黄苔甚厚、脊骨痛牵引胸腹皆疼。服疏利药后脉转软弱，示痰积下行、邪势已衰而正气亦伤。沉滑数主痰热积滞，软弱主邪退正虚，故先以木香槟榔丸下其痰积，继以人参、当归、白术等调理而安。", ["沉", "滑", "数", "软"]], "6030": ["病机", "六脉皆弦而弱，为胃气受伤、肝木乘脾之象。弦主痛、主肝木，弱主气虚。始以内伤外感，过服发散消导之剂，致胃脘当心而痛，中气亏虚，故脉弱；木来乘土，故脉弦。弦弱并见，说明虚中夹滞，法当补而敛之，故用芍药甘草汤加桂枝、饴糖等，一帖而瘳。", ["弦", "弱"]], "6031": ["病机", "两寸短弱，关弦，尺洪滑，为气虚血热、陷于下部之象。寸短弱主上焦气虚，关弦主肝郁，尺洪滑主下焦血热壅滞。肛上肿毒溃后稍动则出鲜血不止、大便结燥、胸膈饱胀、饮食不思，皆气虚不能升提、血热下陷所致。脉症合参，法宜补而升提，否则痔漏将作。", ["短", "弱", "弦", "洪"]], "6032": ["病机", "左寸涩、右寸滑，按之如黄豆大且鼓指，关尺皆弦小，此积痰郁滞于肺，痰阻气机，肺失肃降，大肠传导失常，故食后即大便、腹皮胀急、胸膈饱闷。脉滑为痰，涩为郁滞，弦小为气机不畅，左尺迢迢有神气示肾气未竭，故可吐痰以实大便。", ["涩", "滑", "弦", "小"]], "6033": ["病机", "左寸滑，余五部皆濡弱，此阳气大虚，虚中有寒。濡弱为阳气不足之象，滑为痰湿内停，阳虚不能温煦，故夜多泄泻、小腹疼、口不渴、小便长。治当温补下元兼升举，药后右脉稍起，阳气渐复。", ["滑", "濡", "弱"]], "6034": ["病机", "右手脉浮滑，左平，此湿痰生热，热生风也。浮为风热在表，滑为痰湿内蕴，痰热流注经络，故右手疼不能上头，误作风痛治则口渴烦躁益加。治宜化痰清热兼流动经络，二陈汤加味而愈。", ["浮", "滑"]], "6035": ["病机", "据脉汗后浮数，热尚不减，乃疫症也。浮为邪在表，数为热盛，汗后脉仍浮数，示疫邪未解，故发热头疼、口渴、腹疼、小便赤、大便泻、日夜不睡。治以清热透邪，病后血虚则脉转虚，以四物汤调补而安。", ["浮", "数"]], "6036": ["病机", "六脉弦而数，身如火烁、头痛如破、口渴鼻干、不得眠、胸膈膨胀，此疫毒热盛，弦为邪郁少阳，数为热炽，热盛伤津故口渴鼻干，热扰心神故不眠。用竹叶石膏汤加味清热透邪，热退后头晕脚软为病后血虚。", ["弦", "数"]], "6037": ["病机", "脉左弦数，右滑数，据弦数为阴虚，滑为有痰。弦数示阴虚内热，滑数示痰热内蕴，故咳嗽、内热、额上多汗、恶风。不亟调治恐成虚怯，以养阴清热化痰之剂诸症皆瘳。后复疟，寒热渴甚，为邪伏少阳。", ["弦", "数", "滑"]], "6038": ["病机", "右寸洪而有力，左寸虚，右尺沉微，此心肾不交之症也。右寸洪为肺热，左寸虚为心血不足，右尺沉微为肾阳衰微，心肾水火不济，膀胱失约，故小水不禁、一日二十余起。治以交通心肾、固涩小便而安。", ["洪", "虚", "沉", "微"]], "6039": ["病机", "两寸关皆滑数，两尺皆沉微，此脾气弱而饮食不消。滑数为痰湿内蕴，沉微为脾肾阳虚，当秋令湿淫之候，不利亦泻，故腹痛有块、腹冷甚。治以健脾化湿，后脉皆软弱不滑，累块亦消，示湿去脾渐复。", ["滑", "数", "沉", "微"]], "6040": ["病机", "两寸皆数，关弦而无力，尺洪滑左甚，数主热，弦为木旺克土，无力示中气不足，洪滑为湿痰壅盛于下。合肠风脏毒、大便燥结，乃胃寒肠热、上热下湿之候，故以肠风药为君、养血裹之，使不伤胃气。", ["数", "弦", "洪", "滑"]], "6041": ["病机", "右寸关皆滑，滑主痰湿，右寸关候肺胃，故知肺胃有痰；左寸短弱，左寸候心，短弱为心血不足。劳倦伤脾，痰湿上泛则膈痞恶心，心血亏则目中出泪。治以六君子汤加味，健脾化痰以复心血。", ["滑", "短", "弱"]], "6042": ["病机", "两寸俱滑数，滑主痰，数主热，寸候上焦胸膈，故为痰热结于胸中。饮食过伤、风寒外袭后，五更发热、唇燥、胸中冲跳、手足皆冷，乃痰热内结、阳气不达四末之奇痰症，故以小陷胸汤加味涤痰清热。", ["滑", "数"]], "6043": ["病机", "右寸软弱、关滑，左脉弦长直上鱼际，两尺皆弱，弦长上鱼际为肝木亢逆不下，软弱滑为肺胃痰火，尺弱为下元不足。合《难经》木行乘金之候，诸风掉眩皆属肝木，兼痰火，故治当养金平木、培土化痰。", ["软", "弱", "滑", "弦"]], "6044": ["病机", "六脉俱濡弱，濡弱主正气亏虚、气血不足，兼汗大出更伤卫阳。大便作泻、身热、耳壅、眩晕、胸膈不宽、口渴痰多咳嗽，皆由克伐太过、正气大虚、脾失健运、清阳不升所致，故当以补养为先，用人参白术等健脾益气。", ["濡", "弱"]], "6045": ["病机", "左手沉而弦数，沉弦为积气内结，数为积热；右手滑为痰饮；关脉濡弱为脾气不充。两胁痛上壅至胸、发热、饮食不进，乃怒触肝气、积热痰气交阻之候，故治先祛积热、消痰气，后用当归龙荟丸刈其根。", ["沉", "弦", "数", "滑"]], "6046": ["病机", "脉大小不一，乍大乍小，为气血逆乱、虫动攻冲之象，非正气虚衰之常脉。心痛唇红、痛则大发热头疼、少顷出汗，痛吐白沫可征，皆虫扰气机、阴阳不相顺接之候，故以槟榔川椒乌梅等安蛔杀虫而痛除。", ["大", "小"]], "6047": ["病机", "右寸极软弱，右寸候肺主气，软弱为气虚不振；左近快（左脉近数），为血分有热。行经如崩、头晕眼花，乃气虚不能摄血、血热妄行之候，即气虚而血不固，故宗仲景血脱益气之法，重用人参黄芪补气摄血。", ["软", "弱"]], "6048": ["病机", "脉六部皆软弱无力，为脾虚不能统血之象。患者痔血、里急后重、便频、五更咳嗽、肌肉脱、口渴，皆因过服凉血药损伤脾阳，脾失统摄，血不循经而下溢；脾虚运化失职，故饮入即便；土不生金，则咳嗽痰响。脉软无力正合脾虚之候。", ["软", "弱"]], "6049": ["病机", "左弦大、右滑大搏指，为肝胆之火为痰所凝之象。弦主肝火，滑主痰，大搏指为邪实有余。患者午后发热夜甚、右胁胀痛、咳嗽吊疼，乃木火郁遏、痰火内结；误补参术后痛增，更显气机闭塞。脉象证实肝胆火郁痰凝，非虚热也。", ["弦", "大", "滑", "搏"]], "6050": ["病机", "六脉皆涩，为汗大出而津伤、气血运行不畅之象。患者恶风发热、遍身疼痛、汗出不止、口中热、小水短，乃表虚汗多，津液耗伤，营卫不和，气血涩滞。涩脉主血少气滞，故用白芍、白术、桂皮等调和营卫、止汗生津。", ["涩"]], "6051": ["妇人", "右关滑主痰，左寸微弱主心气不足，两手皆数主热。妊已四月，夜不能睡、小便淋痛、痰嗽内热，乃痰热内扰、心气不足。滑数之脉示痰火，微弱示胎元需养。故用清热化痰安胎之品，后以四君子汤加味调理而产。", ["滑", "微", "弱", "数"]], "6052": ["病机", "两寸脉短弱，两手皆数而无力，为劳倦内伤、气阴两虚之象。短弱主气不足，数而无力主虚热。患者遍身痛、发热、汗大出、昏昏如醉，乃劳倦耗气，卫外不固，汗多伤阴。故用黄芪、白芍、当归等益气养阴止汗。", ["短", "弱", "数", "无力"]], "6053": ["病机", "两寸脉俱洪滑而数，为湿痰凝滞、痰火内盛之象。洪滑主痰热壅盛，数主火。患者胸胁作痛、夜分发热、左足不能履地，因补塞太重，湿痰凝滞经络。脉象证实痰火实证，故用二陈汤加苍术、黄柏等化痰清热通络。", ["洪", "滑", "数"]], "6054": ["预后", "右手软弱，左手散乱，为汗多而脉不敛，气阴外脱之危候。软弱主气衰，散乱主元气涣散。患者寒热、咳嗽、心痛、腰疼、肌肉大瘦、汗出如雨、白带如注，乃久病正虚，汗多亡阳。脉散乱示病势危重，故用黄芪、白芍、阿胶等敛汗固脱。", ["软", "弱", "散", "乱"]], "6055": ["病机", "左寸洪大，右寸关皆滑，两手尽数，为痰火壅盛、瘀热内结之有余候。洪大主火，滑主痰，数主热。患者咯血色紫、胃中痰火素盛、胸膈痞疼，乃痰与瘀血挟而为热。脉象证实痰火瘀热实证，故用总管丸及桃仁、红花等化痰逐瘀清热。", ["洪", "大", "滑", "数"]], "6056": ["病机", "左寸脉短主心血不足，关弦、右关滑、两尺弦示中焦有痰，流于下部，凝于经络。痰湿下注故腰膝酸疼，背心作胀；痰阻清阳则头多眩晕；心血不足、痰湿内扰则夜睡多汗。前医投风剂更伤正气，故以养血化痰通络取效。", ["短", "弦", "滑"]], "6057": ["预后", "右关滑大为痰热壅盛，余部无神气示胃气已败，粪门瘘疮溃流脓血乃阳病极而下陷。咳嗽多痰、面青潮热肌瘦，为痰火耗伤气阴，性躁多郁更助火势。脉证合参，正虚邪盛，故断为不治。", ["滑", "大"]], "6058": ["病机", "右手豁大近芤为血脱阳浮，左濡弱为气血大虚。小产后血大下、白沫如注、五更泄泻、面虚浮，皆脾虚不能统血，血海瘀血未尽致新血不归。面青黄、食少，脾虚已剧，故急宜温补，温脾摄血兼化瘀。", ["芤", "濡", "弱"]], "6059": ["主病", "两寸皆短示上焦气机不畅，两关滑大、右关尤搏指为痰气搏结。喉中梗梗如炙脔、吞之不下吐之不出，正是梅核气症；痰阻清阳则鼻塞头晕耳鸣，痰扰心神则心惊胆怯，卫外不固则汗出如雨、见风身疼。", ["短", "滑", "大"]], "6060": ["妇人", "妊已七月，两寸脉俱短弱，主上焦元气大虚，不能固摄胎元。惊触后胎动不安、下血、大小便急、腰腹胀疼，皆气虚下陷、冲任不固之象。故当骤补元气，佐以安胎止血，一剂血止，诸症悉除。", ["短", "弱"]], "6061": ["病机", "劳倦色欲后精竭血继，复感风寒，邪传少阳，故六脉俱弦数，胸胁痛耳聋呕逆口苦咳嗽。进小柴胡后呕止热退，然左脉不弦数、两寸脉虚、脉散以止嗽渴，示少阳邪减而气阴已伤，故变证丛生。", ["弦", "数", "虚", "散"]], "6062": ["病机", "两寸短弱为清阳不升，关滑、两尺沉滑有力为湿痰蕴积中焦化热。食积痰饮作痞滞，故大便了而不了、间或作胀。治当清中宫、升清降浊，使气血自旺，此不补之补也。", ["短", "弱", "滑"]], "6063": ["病机", "六脉俱涩主痰饮内阻、气血不畅。痰饮挟木火之势上逆，蒙蔽清阳则头晕且痛、起则倒仆；痰阻胸膈则胀闷如绳束缚、呕吐食不得入。故先涌吐痰涎，继以清火降逆、引火下行而愈。", ["涩"]], "6064": ["主病", "脉洪大为阳明热盛之象，原文述发热头痛、口渴、便秘三日，正合阳明少阳合病。洪为热盛，大为邪实，故用大柴胡汤下之，黑粪出而热退。后因食粥太早、复受寒邪，脉象虽未再言，然洪大主实热，与口渴、便秘相应，说明邪在阳明气分，非虚证可比。", ["洪", "大"]], "6065": ["病机", "原文言脉近虚、脉虚而当补，然此案难产伤力、悲戚晕厥、恶露绝无，瘀血上冲致瘛疭神昏，脉虚非真虚，乃壅塞膈上、气血不达之假象。女医误投人参、独参汤，粥药乱进，反致神昏瘛疭不已，吐后方定。脉虚当补之语在此为误治之由，说明虚脉须辨有无实邪壅塞。", ["虚"]], "6066": ["病机", "左弦数主少阳余邪未清，右寸弱、关大重则滑，示脾虚积滞、痰湿内蕴，右尺微为下元不足。原文疟后复伤饮食，大便泻而变痢，积滞无粪、腹疼后重，午未后发热，正合夏伤于暑、秋为疟痢之病机。弦数应疟邪，滑应积滞，弱微示脾肾已伤，故先解散后补。", ["弦", "数", "弱", "滑"]], "6067": ["病机", "孕三月疟疾发，先寒后热、胸膈胀疼、口渴、汤水入即吐、谵语无汗、胎气上冲成子悬，脉皆弦大。弦主少阳疟邪，大主邪盛气壅，疟邪与胎气交争，气机上逆故胀疼呕吐、谵语。弦大之脉说明邪实而胎气不安，故用柴胡、黄芩和解，佐紫苏、砂仁理气安胎，吐止痛除。", ["弦", "大"]], "6068": ["妇人", "左寸关短弱、尺滑，右寸滑、关濡弱、尺沉微。原文断为心神脾志大不足、肺经有痰，而夫言有孕七十日。左寸短弱主心血不足，关濡弱主脾虚，两寸滑主痰，尺沉微主肾虚。脉象示气血不足兼痰，与屡产畸形之胎相应，说明孕育需气血充盛，短弱之脉难以养胎。", ["短", "弱", "滑", "濡"]], "6069": ["误治", "原文仅言左寸脉甚短，此案眼目红痛，先服寒凉两月无效，又误温补人参枸杞五六斤，目肿如桃不能开，再误大下五六次，饮食日减、恶心畏风。左寸短主心阳不足、气血亏虚，屡经寒凉温补攻下，正气大伤。短脉示气血不能上奉，与目肿不消、恶心畏风之虚象相应，说明误治伤正。", ["短"]], "6070": ["病机", "六部俱弦，重按稍快。原文述两手筋挛、指掉不能屈伸、臂肉瘦削、体瘠面白、寝食大减，先发寒热筋骨疼痛，诸医皆作风治不效。弦脉主筋病、主痛、主肝风，六部俱弦示肝血亏虚、筋脉失养，虚风内动。重按稍快说明非纯实风，乃血虚生风，与筋挛肉削、面白体瘠相应。", ["弦"]], "6071": ["病机", "脉之六部大而无力，原文引脉至而从、按之不鼓，诸阳皆然。下消症小便频数清白而长、味甜如脂，腰膝软弱、载身不起、饮食减半、神色大瘁。大而无力为阳气虚衰、虚阳外浮之象，非实热。脉大示虚阳浮越，无力示下焦真阳不足，故法当温补下焦，与腰膝软弱、尿甜如脂之肾阳虚衰相应。", ["大"]], "6072": ["病机", "原文述每动怒则夜卧不安、如见鬼魅、小水淋沥、大便秘结、腹中疼痛、腰胯胀坠如生产状，因痛而脉多不应指。脉不应指非虚，乃肝经郁火内炽、气机壅滞，气血不得宣通，故脉道不利而应指模糊。郁火扰心则卧不安如见鬼魅，下迫膀胱则淋沥，灼津则便秘，气滞血瘀则痛胀坠。法当通利，以杏仁桃仁等通降，便通痛减，反证脉不应指由郁火壅滞所致。", []], "6073": ["兼症", "原文先述夜分脐腹疼极、次日头痛如箍、遍身疼，断为上盛下虚。经治头痛止后，惟咳嗽胸前略痛，两寸脉浮滑、两尺弱。寸浮滑主上焦痰浊未清，故咳嗽胸痛；尺弱主下元虚衰，故脐腹疼需温熨。浮滑与弱并见，正合上盛下虚之机，故用鹿角霜、补骨脂等温补下元，佐香附、金铃子理气，丸服而瘳。", ["浮", "滑", "弱"]], "6074": ["预后", "原文述产后感风食面，误投参术后大热谵语、汗出如洗、气喘泄泻黄水、小水短少，又误寒凉温补，泻益频热益剧。产后脉洪大，法皆犯逆；六脉乱而无绪，乃正气溃散、邪热鸱张，气血失序。洪大为热盛，乱为胃气将败，故医者引汗出如油、喘而不休为死症，断其无生，属危恶之预后。", ["洪", "大", "乱"]], "6075": ["病机", "原文述疟后腰痛白浊、日夜咳嗽、肌肉大消，诸药乱投而痛剧欲死。脉左弦细、右滑大，俱六至。左弦细主肝经郁滞、阴血不足；右滑大主痰热内蕴。合之口渴眼赤，知昔患杨梅疮余毒伏于经络，因疟后气血不足，旧毒感动而暴发。弦细滑大并见，示正虚邪实、毒热痰瘀交阻，故痛暴而剧。", ["弦", "细", "滑", "大"]], "6076": ["病机", "原文述古稀之年痰火旧疾，因过劳感寒，咳嗽痰中带血、鼻流清水、舌生芒刺、语言强硬、二便不利、喘急不能卧。两手脉浮而洪，两关滑大有力。浮洪为风邪外束、内热炽盛；关滑大有力为积热痰火壅于中焦。故断为内有积热痰火为风邪所閟、怒气所加，血上逆。脉大发热非阴虚，乃有余之症，法当先驱痰火积热。", ["浮", "洪", "滑", "大"]], "6077": ["其他", "原文述中焦湿热生痰，痞闷、五更倒饱、下午股膝筋脉抽掣疼痛、嗳气、面黄、间常梦遗。未载脉象，然症候所示乃湿热痰浊壅阻中焦、脾运失健，下流则梦遗，筋脉失养则抽掣。故以清气大安化痰丸清化痰热，猪肚丸健脾去湿热、固精，二方调治而安，属症候与治法之记。", []], "6078": ["其他", "原文述虚损咳嗽昼轻夜重，由肺火未清、误服参术太过而然；丁氏肥而性躁，患痛风，手不能沐栉、足不能履地，痛处略肿。未载脉象，然症示肺火未清与湿热痰瘀痹阻经络。故治蜃楼以清肺利肺，咳止后补心安神；治丁氏则刈其根，暗示湿热瘀滞可速去，属症候与治法之论。", []], "6079": ["病机", "原文述暑月患痢，小腹窘迫、胸膈膨胀、口舌焦渴。右寸关脉洪滑，左脉弦。右寸关洪滑主气分热盛、痰食壅滞于中上焦；左弦主肝气郁结。合之症候，断为气郁食积痢。洪滑为实热痰食，弦为气郁，故先以木香槟榔丸开下，继以温胆汤加减清化痰热，痢寻止。", ["洪", "滑", "弦"]], "6080": ["病机", "先见六脉俱伏，乃瘀血内阻、气机闭塞之象；继而六部俱见，惟左寸短涩，左寸候心，短涩主血行不畅，故断为瘀血作痛。胸喉有物作梗、汤水难入、心痛始萌，皆瘀阻气滞之征，与脉相应。", ["伏", "短", "涩"]], "6081": ["兼症", "暑月患痢，右手脉弦主气滞，左脉滑主血盛有孕，后六脉已和但软弱，为痢后气血不足。原文以脉之弦减、脉和软弱判断病退，主张补养气血以保胎，脉象变化直接反映痢疾与胎孕的兼症转归。", ["弦", "滑", "弱"]], "6082": ["病机", "左脉细数主阴虚内热，右脉滑主食积，合梦遗后痢下，断为阴虚之候。先补后攻，后六部虚软无力、独右关滑，示脾气已虚而食积未净，脉由滑转虚软，说明攻下伤正、积滞尚存之病机。", ["细", "数", "滑", "虚"]], "6083": ["病机", "左脉浮弦而数，浮为风、弦为疟、数为热，右软弱中部稍滑，示内伤饮食、脾胃不足。原文断为内伤饮食、外感风邪、疟痢并作，脉象外浮内弱，正合外感内伤相兼之机，故宜速治防邪陷下。", ["浮", "弦", "数", "弱"]], "6084": ["病机", "两寸洪大有力、左浮弦而数，为少阳阳明合病之疟，热盛于上；右脉稍软亦弦长，示脾胃稍弱而邪未尽。洪大弦数主阳热亢盛，与头痛口渴、汗大泄、寒热间日发相应，故以柴葛解肌汤清解少阳阳明。", ["洪", "弦", "数", "软"]], "6085": ["病机", "两寸短、左寸尤甚，左寸候心，短为心气不足；余部滑数，为阴虚火动、精关不固。原文断为心气大弱、神弱不能固摄其精，故梦遗不禁，兼见体倦气弱、汗多肌热，法当养心安神而非滋阴降火。", ["短", "滑", "数"]], "6086": ["主病", "六脉皆洪数，洪为热盛、数为热急，合面色苍黑、皮肤燥若老松树皮，示热毒内蕴、气血壅滞，腹痛两月诸治不效，非寒非虚，乃热毒结聚之实证，脉洪数正主此邪热壅盛之病机。", ["洪", "数"]], "6087": ["病机", "六部濡弱，濡弱主气血两虚、脾虚不运；所下紫黑稠黏、色晦如芋苗汁，非痢乃脏毒下血。脉虚与久病形色瘦瘁、匙箸厌举相应，说明正虚为本、下血为标，故用人参樗皮散补虚止血。", ["濡", "弱"]], "6088": ["病机", "原文未明言脉象，然述‘冲暑往来’致发热燥渴，过食生冷成泄泻，小水短少，医以通利致大便结燥，复泻不止，终致‘脐下胀急，立解点滴不出，卧则流之不竭’。此系暑热伤气、过利伤津，气化失司，水液代谢紊乱，病机为气不化水、州都失职，非单纯癃闭，故诸医不识。", []], "6089": ["病机", "左弦数、右滑数，原文自释‘滑为痰，弦为风，数为热’。湿生痰，痰生热，热壅经络，伤营卫而变风，故右胁痛、右手足筋骨痛、艰于举动。脉弦主风、滑主痰、数主热，合为湿痰风热痹阻经络之病机，非偏风也。", ["弦", "数", "滑", "数"]], "6090": ["病机", "两寸滑大，左关弦，右关滑，两尺皆弦皆七至。滑主痰热，弦主少阳，数急为热盛。原文断为‘少阳阳明两经合病’，因表汗泻吐后津伤热炽，痰热内扰，故小水短赤、口渴腹痛、耳聋气塞、懊𢙐不眠，脉象与症相符。", ["滑", "大", "弦", "滑"]], "6091": ["病机", "左沉细，右寸滑，关尺濡弱。沉细濡弱主下焦湿热伤阴、筋脉失养，故腰与环跳常痛；右寸滑主上焦痰火，故行动即热发渴呕恶。原文断为‘上焦有痰火，下焦有湿热’，脉症合参，治当流湿舒筋后施补。", ["沉", "细", "滑", "濡弱"]], "6092": ["病机", "左寸芤、关涩、尺弱，右寸短、关滑。芤主失血，涩主血少，弱主气虚，短主气损，滑主痰火。原文谓‘胃中痰火正旺，气血俱虚’，酒伤咳血、不思饮食、左胁气不调，皆由痰火灼伤肺胃、气血两亏所致，故先清胃保肺后大补。", ["芤", "涩", "弱", "短"]], "6093": ["病机", "六脉皆数，左滑右软弱。数主热，滑主痰，软弱主脾虚气弱。原文谓‘上焦热，下焦寒’，由思虑悒悒、肝脾郁结，痰热阻膈，故食入即痛吐酸、便结经闭。脉数滑为痰热内蕴，软弱为脾虚不运，恐成膈症，急宜拂虑。", ["数", "滑", "弱"]], "6094": ["病机", "脉沉弦而数，沉主里，弦主痛主风，数主热。原文谓‘痰火上壅而变风热，将欲作毒’，故喉痛颊车肿、两太阳胀疼、遍身胀痛、憎寒发热。沉弦数示痰火内郁、风热上攻，毒势欲成，宜急治以疏风清热化痰。", ["沉", "弦", "数"]], "6095": ["病机", "两寸短弱，关尺洪数。短弱主肺气不足，洪数主火热内盛。原文断为‘胃中有痰火，下焦有阴火，由壮年酒色所伤’，故辛苦酒多则咯血。寸短弱为肺虚失摄，关尺洪数为胃火与阴火交炽，迫血上溢，脉症相应。", ["短", "弱", "洪", "数"]], "6096": ["病机", "左脉浮数，右濡弱，两手六至，为湿热发黄之候。浮主表，数主热，濡弱示湿滞而正气不足。患者冒雨劳力汗出，冷水澡浴，致湿热郁蒸，故发热、口渴、身黄如金、小便赤长、舌黄苔、夜不得卧。脉症合参，湿热内蕴，表里俱病，年高而脉数，然有是症当用是药，故以柴胡、酒芩等清透湿热，佐人参扶正。", ["浮", "数", "濡", "弱"]], "6097": ["病机", "左脉弦大，右脉虚大，合参症见大吐痰沫、呕血鲜红、昏晕汗出。弦大主肝火亢盛，因作文劳心、被怒伤肝，气逆血涌；虚大主暑伤元气，经云“脉虚身热得之伤暑”。虽血涌脉大似危，然左弦右虚，非纯实热，乃痰火与暑热交迫，气血俱伤。故断为可生，治当清暑平肝、降火化痰，不可拘泥血证脉大即死之说。", ["弦", "大", "虚"]], "6098": ["病机", "六脉浮而洪滑且数，症见咳吐臭脓血、发热昼轻夜重、肌肉大瘦。浮洪主热盛于上，滑数主痰热壅聚。此非吐血，乃酿酒伤肺、怒气触之，瘀血浊痰滞于肺之气窍，久郁化脓成肺痈。脉洪滑数示热毒痰瘀互结，故治宜开肺窍、活血化痰，使脓尽自愈。若误作虚损吐血，则谬矣。", ["浮", "洪", "滑", "数"]], "6099": ["病机", "脉俱洪数，症见小便血淋疼痛、溺出大血块。洪数为热盛之象，因善饮好内，湿热下注膀胱，灼伤血络，故血淋剧痛。前服补下元药过多，助热增剧。洪数脉主实热，非虚寒，故以五灵脂、蒲黄等活血通淋，热清瘀化则痛减。此脉此症，确为湿热瘀阻下焦之血淋实证。", ["洪", "数"]], "6100": ["病机", "脉洪数，症见吐红发热、经水二十日一行或一月二次、白带且多、胸膈饱胀。洪数主热盛，热迫血妄行则经频吐红，湿热下注则带多，热壅气滞则胸膈饱胀。此属血热妄行、肝脾郁热之候，故以丹参、生地、山栀子、白芍、小蓟凉血止血，鹿角胶固冲，童便降火，使热清血宁。", ["洪", "数"]], "6101": ["病机", "脉弦大而无力，症见眼红肿胀、两太阳痛、遍身胀闷、寝食俱废。前医误用苦寒治时疾，更增石膏，致寒凝气滞。弦大无力非实热，乃肝郁气滞、清阳不升，兼寒凉伤中。故用蔓荆子、柴胡、香附、夏枯草疏肝散郁，桑白皮、芽茶清上，甘草和中，使气机畅达，肿痛自消。此脉示郁滞而非实火。", ["弦", "大"]], "6102": ["病机", "两手脉皆滑数，右尺软弱，症见右背一点痛、夜尤痛、手臂肢节胀痛、筋暴起、肌肉生红点。滑数主湿热，右尺软弱示下元不足而湿滞。湿热伤筋，流注肢节，故成痛痹。脉滑数非虚寒，乃湿热壅遏经络，故以东垣舒筋汤为主，羌活、黄柏、防己等清热利湿、舒筋活络，使湿热去而痹痛止。", ["滑", "数", "软", "弱"]], "6103": ["病机", "两寸脉洪大，症见血痢、里急后重、呕吐不纳谷。洪大主热盛于上焦，寸脉候上焦，热壅胸膈则呕吐不纳，热迫大肠则血痢后重。此属上焦热盛、胃气上逆、湿热下迫之候。故以竹茹温胆汤加姜连、滑石、橘红、酒芩清上焦热、降逆止呕，热清则呕止痢减，后以枳壳、当归等调气和血而安。", ["洪", "大"]], "6104": ["病机", "左脉沉伏，右脉滑大有力。沉伏主气闭于下，滑大主痰格中焦。原文谓“痰格中焦，气闭下焦”，故大小便秘、气逆呕吐。右滑大为痰热壅盛之象，左沉伏为气机郁闭之征。经吐胶痰、通大便后，右脉平而左脉起，说明痰去气通，脉象随之而变。", ["沉", "伏", "滑", "大"]], "6105": ["病机", "原文仅言“脉仅四至”，未及脉形。四至为缓脉之常，但症见四肢冷、胃脘痛极、食西瓜不化、面青声不扬，乃霍乱兼蛔厥，阳气内郁，胃气上逆。前医误作郁火投寒凉，痛更增，说明非真热。脉虽四至而症属阴寒内盛、蛔虫扰动，故以温通安蛔取效。", []], "6106": ["病机", "左手甚弱，汗多故也；右手滑大，痰饮湿热而然。左弱为汗多伤阴、元神不敛；右滑大为痰饮湿热壅于中焦。症见肢节肿痛、痰多呕恶、语言不清、夜梦惊恐、汗多不止，乃虚实夹杂。前医作风治疏散，泄其元神，故以补敛为主，佐以化痰。", ["弱", "滑", "大"]], "6107": ["病机", "六脉俱弦数。弦主肝郁，数主热。原文谓“忧伤肺、思伤脾”，忧思伤及脾肺，肝木乘之，郁而化热，故脉弦数。症见声哑、咳嗽、喉痛、便溏、肌肉大削，乃木火刑金、脾土受损之候。弦数为郁热内炽之象，故治以健脾清肝、润肺利咽。", ["弦", "数"]], "6108": ["病机", "六脉俱数，左寸滑大，右关搏指，左关软弱。数主热，滑大主痰热壅盛，搏指为邪实，软弱为气血不足。孕妇血大下后发战，乃血去阴伤、虚火内动。左寸滑大主心火，右关搏指主胃热，左关软弱主肝血不足。此虚火游行无制，故见白泡、面肿、寒热、汗出。", ["数", "滑", "大", "弱"]], "6109": ["病机", "两寸脉洪大，两尺沉微。洪大主热盛于上，沉微主阳衰于下。症见两胁胀急抵胃作痛、汗出、颧红唇红、饮入即吐，乃上焦热壅、下焦虚寒，阴阳不相顺接。洪大为胃热上逆，沉微为肾阳不足。故用阴阳汤调玄明粉，清上温下，后以安蛔止痛收功。", ["洪", "大", "沉", "微"]], "6110": ["病机", "脉右大于左者三倍且数，后脉大无绪。右大主气分邪实，数主热，无绪为脉乱无伦。产后子死忧闷，小腹块痛，发热便闭，鼻衄口渴，乃瘀血内结、郁而化热。右大于左三倍，说明气分热壅血分不足。脉大无绪为邪热鸱张、气血逆乱之危候，故用破血通瘀、泻热通便。", ["大", "数"]], "6111": ["病机", "左脉弦，右脉滑，两寸稍短。弦主肝郁，滑主痰，短主气损。症见梦魇晕厥、精神恍惚、咳嗽面青、不思食，乃痰浊蒙窍、肝郁神伤。前医作寒痰投附子肉桂而厥尤加，说明非寒。弦滑为痰郁交阻，短为神气不足。结合其眷属瘵症病史，知为传尸瘵症，故先补养神气、化痰治嗽。", ["弦", "滑", "短"]], "6112": ["病机", "脉弦涩有力，弦主痛主饮，涩主凝滞。患者受寒后筋骨红肿痛，卧床三年，大肉尽消而骨节肿大，前医或补或温或祛风利湿皆不效。此脉说明湿热痰火被寒气凝滞固涩经络，气血不通，故见红肿疼痛；弦涩有力非虚非寒，乃邪实阻滞之象，与“腿间大肉尽消，惟各骨节处肿大而疼”相应。", ["弦", "涩"]], "6113": ["病机", "脉六部俱豁大无力，豁大而无力为正气大虚、虚阳外浮之象。患者过服寒凉十一日，口疮日甚，延及于喉，饮食药难下，涎沫迷漫，毒甚可毙鸡。此脉说明寒凉过度损伤中阳，虚火上炎，毒热壅盛而正气已馁，故脉虽大而无力，与“口疮日甚”“药亦难下咽”相应，非实热之洪大有力。", ["大"]], "6114": ["妇人", "脉左滑数，右寸弱，关滑，左尺有力，右尺弱。妊娠六月，伤风咳嗽，腹中吊疼，痰壅喉音不清，头眩。左滑数为痰热内蕴，右寸弱为肺气不足，关滑主痰，左尺有力为胎气壅盛，右尺弱为肾气偏弱。此脉示痰热壅肺兼胎气不宁，与咳嗽痰壅、腹中吊疼相应，故用参术安胎、芩贝清痰而愈。", ["滑", "数", "弱"]], "6115": ["兼症", "两关滑大有力，尺寸俱不足。关候脾胃，滑大有力为湿热积滞壅于中焦，故腹痛下痢、里急后重；尺寸不足为下元与肺气偏虚，且患者有肠风下血旧疾，又因乃翁痢疾发热卒于湖州而心甚恐怖，情志伤中。此脉示湿热痢疾兼肠风，与发热多痰、腹痛下痢相应，故用芍药止痛、连芩清热升提而效。", ["滑", "大"]], "6116": ["病机", "左关脉弦大鼓指，弦主痛主肝，大主邪盛，鼓指为气滞壅盛。患者偏坠脐腹腰俞俱胀痛，服理气药后痛如旧而脉转数，恐作囊痈，急为解毒。此脉说明肝经湿热壅滞，气机不通，弦大鼓指为邪实；转数则示热毒欲酿痈脓，与“脐腹腰俞俱胀而痛”相应。后弦脉尽退，食鸡鱼太早复弦，示食复气滞。", ["弦", "大", "数"]], "6117": ["病机", "两寸洪大，寸候上焦肺卫。患者表虚易感风寒，致鼻渊流清涕不止，头运，两太阳常疼，多喷嚏。洪大为热盛于上之象，风寒郁而化热，壅于肺窍，故脉两寸洪大。此脉说明上焦肺热壅盛，与鼻渊清涕、头痛喷嚏相应，故用秦艽、酒芩、石膏、滑石等清上焦郁热而涕止病愈。", ["洪", "大"]], "6118": ["病机", "脉左涩右滑。左涩主血瘀，右滑主痰积。患者腹胀满呕哕，目珠面皆黄，恶寒发热，鼻衄，腹痛，大便黑如墨，吐黑血如烂猪肺，腹大如斗有块坚如石。此脉说明痰瘀互结、湿热壅盛，血不循经而妄行，与“目珠如金，面若熏橘”“吐出黑血”相应，非中蛊之毒，乃瘀热内结之重证。", ["涩", "滑"]], "6119": ["病机", "原文未识脉名，仅言“左脉绝不应指，虚极故也”。左脉候血，小产后腹痛晕厥、冷汗淋淋、遍身麻木、心怔怔动，左脉绝不应指为血脱气陷、虚极之象。此脉说明小产后失血过多，气血暴虚，不能充脉，与冷汗、晕厥、麻木、怔忡相应，故用当归、川芎、人参、荆芥穗等益气养血固脱而安。", []], "6120": ["病机", "脉左弦长、右洪大俱七至，乃阳明少阳热盛之象。弦长为少阳火郁，洪大为阳明热炽，数至七至则热邪亢盛。热邪内迫，故头疼发热、口渴水泻、躁闷不宁；热盛神昏气促，舌苔焦黄，体若火燎。此非梦遗虚证，乃伤寒热症，邪在阳明少阳二经，误补则转剧。", ["弦", "长", "洪", "大"]], "6121": ["主病", "脉濡而数，濡主湿，数主热，乃湿热内蕴之象。酒疸遍身皆黄、尿如柏汁，为湿热郁蒸；胸膈痞满、口不知味、四肢酸软，皆湿困中焦、热灼津液所致。脉濡数正合湿热交蒸之病机，故以四苓散加清热利湿之品取效。", ["濡", "数"]], "6122": ["病机", "六部数而无力，形气殊不胜息，乃气血大虚、虚热内扰之候。数脉虽主热，然无力则非实火，乃阴血不足、阳气浮越所致。跨马痈肿痛日加而饮食日减、肌肉日削，正虚不能托毒外出。前医投败毒、解毒诸剂更伤气血，故脉数无力，当大补托之。", ["数", "虚"]], "6123": ["病机", "两寸关滑数，两尺沉细，乃上焦痰热、下元虚寒之候。滑数主痰饮实热，沉细主肾虚不足。咳嗽痰红、便泻频数、肌肉消瘦、午后发热，为虚中夹实、痰饮内停。脉虽数而尺沉细，故不敢轻用寒凉，温补下元以固关门，泻止而战摇亦愈。", ["滑", "数", "沉", "细"]], "6124": ["病机", "六脉伏而不见，乃热极汗不得透、阳气郁遏之象。春温后鼻衄寒战、舌焦黄、目珠红，为阳明余热迫血上行。脉伏非虚寒，乃热邪壅遏、气血不能外达，故曰作汗之兆。服清热透邪之剂后汗出如雨，脉乃渐出，证实热极使然。", ["伏"]], "6125": ["病机", "两关洪滑鼓指，按之不下，乃有余之候。洪滑主实热积滞，鼓指有力为邪气壅盛。腹大如斗、坚如石、小水不通，由食冷积滞酿成鼓胀。前医误作气虚中满温补，致胀急欲裂。脉候洪滑证实为积块有余，故用积块丸下之。", ["洪", "滑"]], "6126": ["病机", "左脉弦大、右洪大俱七至，乃春温阳症、热邪炽盛之候。弦大为少阳热盛，洪大为阳明热炽，七至则热邪亢极。虽房事后腹痛水泻，似阴症，然面赤唇燥、舌苔黄厚、烦躁口渴，脉洪数有力，实为阳症。误投理中则呕逆烦躁，当从脉症辨为春温阳症。", ["弦", "大", "洪", "数"]], "6127": ["病机", "六部洪数，身热而烦，乃痰火炽盛、热迫血溢之候。洪主热盛，数主火亢，素痰火又误用收涩、滋阴、发散，致火势愈炽，血从口鼻喷出如泉涌。时当三伏，内外火夹攻，非釜底抽薪难夺上涌之势，故用大黄、石膏、黄连急下泄热。", ["洪", "数"]], "6128": ["预后", "脉弦数不减，弦主少阳、数主热，说明子午潮热虽汗出热退十之七，而邪热仍郁于少阳未解。原文以\"据脉弦数不减，恐防作疟\"为断，正因弦数为疟疾将作之兆，后半月果疟作、咳转加、出黄黏老痰，与\"无痰不作疟\"相应，故本段脉象主邪伏少阳、痰热内郁之病机与疟变之预后。", ["弦", "数"]], "6129": ["病机", "左数右沉涩，数主热、沉主里、涩主血滞。经水久不止而夹紫黑血块，胸腹胃脘皆痛、玉户肿、脐下块坚如铁、手足冷，正是瘀血内结、血瘕成形，气血不得温通之候。沉涩为瘀阻之征，左数则瘀久化热，故断为血瘕症，与消瘀行气后痛减、手足渐温相应。", ["数", "沉", "涩"]], "6130": ["病机", "六脉浮数，浮主表、数主热，孕四月而头疼遍身痛、腰痛、恶寒发热、咳嗽口渴，为外感风邪束表、内热相搏之候。浮数应表热，故以小柴胡加防风、羌活、葛根解表；后寒战发热汗出，是作汗之兆。脉象所主在表邪未解，与子悬、汗出不止等兼症演变相承。", ["浮", "数"]], "6131": ["病机", "两手脉短弱而两关弦大，左尺弱、右尺滑大。短弱为心血不足、正气虚；关弦大主中焦痰积；右尺滑大为阴分淫火。原文断\"心血不足，中焦有痰积，膈间有瘀血，阴分有淫火\"，与咳嗽吐红、腹痛、梦遗、背胀诸症相应，脉象正示虚中夹痰瘀火之杂病机。", ["短", "弱", "弦", "大"]], "6132": ["病机", "六脉浮大而数，浮主风邪在表，大数主内热壅盛。崩后百日洗浴受风，外寒束内热，故前后心胀、四肢肿痛、面浮、恶寒发热、大小便欲行不行、口甜。浮大数正合外寒束内热之机，故用柴胡、紫苏、麻黄解表，酒芩清里，得微汗而胸腹稍安。", ["浮", "大", "数"]], "6133": ["病机", "右关洪滑、两尺尤有力，洪滑主痰热实积；左脉略弦，弦主少阳、主痛。丁年寒热、右胁块起疼痛拒按、额颅手心热、日夜不睡，为痰热结于胁下、少阳枢机不利。洪滑有力示实热内结，故仿推气散攻之，便行得睡；再诊左弦、苔厚、便结，仍主少阳痰热未清。", ["洪", "滑", "弦"]], "6134": ["病机", "两寸洪滑、两尺弱，寸洪滑主痰热壅于上焦，尺弱示下元不足、胎气上逼。孕八月受惊后胸膈胀闷、呕逆不食，原文断为\"亢上不下之候\"\"子悬而然\"。上盛下虚，故用温胆汤加黄连、大腹皮清降痰热，一剂呕止膈宽，脉象与子悬病机相合。", ["洪", "滑", "弱"]], "6135": ["病机", "原文未识别脉名，然诊得两寸洪大、两尺弱。寸洪大主上焦热盛，尺弱示下虚，然结合吐血碗余、下午潮热、便秘、背心胀痛，断为瘀血凝滞、新血不得归经而满溢。洪大为瘀热上壅之象，尺弱为下元不足，故法当消瘀为主，与龙荟丸通便后吐止食进相应。", ["洪", "大", "弱"]], "6136": ["病机", "脉浮紧而数，浮主表，紧主痛，数主热。原文谓“湿热所致”，肿属湿，痛属火，火性速故痛暴猛。湿热搏结筋骨肢节，气血壅滞，故遍身筋骨疼痛、肢节肿痛、痛处热如火燎。脉浮紧数正合湿热痹阻、火性急迫之机，非单纯外风，故疏风及活血止痛皆不应。", ["浮", "紧", "数"]], "6137": ["预后", "六部俱微弱不充指，右关稍滑，微弱为气血大虚，不充指为神气衰惫；右关稍滑虽存胃气，然整体脉势已弱。症见精神昏惫、一息奄奄、四肢冷厥，脉症合参，断为“邪已尽退，惟虚惫而神气弱”，预后取决于大补，故属预后判断。", ["微", "弱", "滑"]], "6138": ["病机", "两寸关脉俱滑大有力，两尺沉微。滑大有力主痰火壅盛于中上二焦，沉微主下元不足。原文断为“中焦有痰，肝胆有火”，因怒气所触，火性急速，痰随气升，故眼眦突生白泡、呕吐眩晕、伏枕不敢动。脉象直接反映痰火冲逆、本虚标实之病机。", ["滑", "大", "沉", "微"]], "6139": ["误治", "脉仅四至，重按则伏而有力。四至为缓，伏而有力非虚寒，乃因攻克太过、寒凉伤脾，中气不运，积反凝滞，气机郁伏于内。故大便虽泻而痛尤甚，手足清冷、形神俱倦。此脉示误下后脾虚气陷、积滞内伏之候，非纯虚亦非实积，治当建立中气。", ["伏", "有", "力"]], "6140": ["病机", "六脉洪大，洪大为阳热亢盛之象。产后未弥月，醉犯房事，血来如崩，发热头晕，大小便俱热，此因酒热与房劳相合，扰动冲任，迫血妄行，热势充斥内外，故脉洪大。洪大脉与崩热血热之症相应，示热迫血溢、气血俱热之病机。", ["洪", "大"]], "6141": ["病机", "六脉洪大，主热盛于内。症见颊腮红肿、呕恶、发热、口苦、烦躁不眠，原文断为“少阳阳明二经之症”，洪大脉正合阳明热盛、少阳火郁之机。热邪壅于经络则腮肿，犯于胃腑则呕恶不食，扰于心神则烦躁不眠，故法当清解。", ["洪", "大"]], "6142": ["病机", "左脉沉弦而数，右关结实大如碧豆。沉弦主气郁，数主热，结实大主积滞内结。原文谓胸胁胀闷、腹中疼痛、大便秘结，乃酒湿化热、气机壅滞、积结于内所致。前医误作脾虚理脾，反致邪愈结。脉象示肝郁热结、腑气不通之实滞病机。", ["沉", "弦", "数", "结"]], "6143": ["病机", "脉之左涩右寸关滑大，两尺又弱。左涩主血少或血瘀，右寸关滑大主痰火壅于中上焦，两尺弱主下元虚惫。原文述吐血后咳喘、泄泻、发热烦躁，前医滋阴则泻甚，保脾则火炽。脉象示上焦痰火未清、中焦脾弱、下元不足，虚实错杂之病机。", ["涩", "滑", "大", "弱"]], "6144": ["病机", "脉浮大无力，重按三五不调，六七至一止，右关近滑。浮大无力为劳倦表虚、气不敛固之象；重按不调而止，乃气虚血弱、脉道不续；右关滑为脾虚痰食内滞。高年劳倦感邪，误汗更伤元气，故汗漏、神疲、昏愦、发呃，皆由中气衰败、虚风上逆所致。", ["浮", "大", "虚", "滑"]], "6145": ["病机", "左脉弦大，右滑大。弦为肝木偏旺，大为邪实气壅，滑为痰湿内蕴。病从忧思而起，肝郁克脾，气滞痰凝，中焦失运，遂成胀满。左弦大主肝郁气逆，右滑大主痰食壅滞，故用木香化滞汤行气化痰、疏肝运脾，服后腹宽其半。", ["弦", "大", "滑"]], "6146": ["病机", "六脉浮而洪数，左寸尤甚。浮为邪在表，洪为热盛，数为热急，左寸候心与上部，尤甚则热毒壅聚于上。痛处红肿光浮如瓠、抚之烙手，显系热毒蕴结、气血壅滞之便痈。洪数之脉与局部红肿灼热相应，非湿痰风气，亦非疝气。", ["浮", "洪", "数"]], "6147": ["病机", "脉俱洪数，症见发热昼夜不止、口渴、齿燥、鼻干、舌苔黄厚、不得眠，呕恶胸痞、小水短赤。洪数为阳明热盛、气分燔灼之象；热灼津伤则渴燥，热壅胸膈则呕恶痞懑，热迫大肠则下清水。故用石膏、知母、柴胡、葛根清解阳明气分热邪。", ["洪", "数"]], "6148": ["病机", "左脉弦细，右关滑。弦细为肝郁血少、情志怫郁之象，右关滑主痰湿内滞。病者丧子哀恸，绝粒断浆，肝气郁结，脾运不健，痰湿内生，故寒热交作、呕哕、懊𢙐、遍身疼。弦细应其郁损，滑应其痰滞，乃情志所伤、肝脾失调之候。", ["弦", "细", "滑"]], "6149": ["病机", "原文未识脉名，然述蛊胀大如覆箕，青筋缕缕如蚯蚓大，上自胸脯至上脘而止，脐平，四肢瘦削。此由纵口腹、伤脾胃，水湿痰瘀互结，气机壅塞，血络瘀阻而成蛊胀。青筋显露、脐平为水气太过、血瘀络阻之危候，故非一般胀满可比。", []], "6150": ["病机", "左弦大，右关滑大，两尺俱无。弦大为肝郁气逆、痰饮内壅，右关滑大为痰湿困脾，两尺俱无则肾气衰微、下元虚惫。昔肥今瘦、肠鸣如雷、腹中块跳、肤目黄、足膝冷，皆痰饮瘀结、脾肾阳虚、水湿泛滥之机。形瘦目炯有神，痰去则正犹可支。", ["弦", "大", "滑"]], "6151": ["病机", "左脉大而有力，右寸亦大。大为气壅邪实，有力为热郁不畅。素多疮疥，湿热内蕴；沐浴后鼻红、面足浮肿、汗多，乃湿热上蒸、肺气失宣、水湿泛溢。左脉大主肝气偏亢，右寸大主肺气壅滞。据脉多思气不畅，故用升麻、葛根、滑石等宣透清利。", ["大"]], "6152": ["病机", "左手数、右手弱，数主热，弱主虚。患者忧思郁结，食积痰饮瘀血流于下部，郁而化火，故脉数；脾虚不运，故右弱。症见左胯疼痛及膝、小水频数、大便频、脐腹胀痛、口干，皆郁火挟瘀之象，恐成肠痈。", ["数", "弱"]], "6153": ["病机", "独右寸洪大，右寸候肺，洪大为热盛之象。症见头痛、胸背胀、饮食下膈便吐、咳嗽痰浊如脓、大便结燥，乃痰热壅肺，肺气上逆。洪大之脉主肺经实热，热灼津液成痰，故痰浊如脓，将作肺痈。", ["洪", "大"]], "6154": ["病机", "六脉滑数，滑主痰湿、血热，数主热。三孕三小产，因气虚血热，热迫血妄行，故血频下；血滑已久，如水行旧路，滑脉示血行滑利难止。数脉为血海热甚，肝风内动，故需涩血凉肝。", ["滑", "数"]], "6155": ["病机", "右寸关脉濡弱，左手和。濡弱主脾虚湿停，右寸关候脾肺，年过六十脾阳不足，运化失职，湿邪下注，故小水频迫、出不禁、足有浮气；湿聚生痰，上逆犯肺则咳嗽。此脾虚停湿之症。", ["濡", "弱"]], "6156": ["病机", "原文未识脉名，但据症候分析：经不行三月，大便泻、腹胀嘈杂、吐酸水、时下白带、恶心，乃脾经湿热内蕴；心经有瘀血，故经闭。湿热下注则泻、带下，胃气上逆则恶心吐酸。非孕脉，实为湿热瘀血互结。", []], "6157": ["病机", "左脉弦大，右寸关滑大有力。弦主肝郁，大主热盛；滑主痰，右寸关候肺脾，滑大有力为痰热壅盛。症见喉痛、痰多晕厥、头痛面赤，乃肝火上炎，痰热内扰，上蒙清窍，故晕厥频发。", ["弦", "大", "滑"]], "6158": ["病机", "独两关洪大，两关候脾胃，洪大为阳明热盛之象。时疫热病发汗过度，热留胸中，烦躁呕恶、汗不敛、口渴，皆阳明热炽、津气两伤。洪大脉主阳明实热，故以白虎生脉汤清泄阳明、益气生津。", ["洪", "大"]], "6159": ["病机", "左脉弦大，右洪大，后六部俱浮洪。弦大主肝热，洪大主阳明热盛；浮洪为热邪弥漫三焦。春温头痛发热，食复发斑色紫、神昏、面赤、舌苔黄黑芒刺，乃热毒内陷，气血两燔，故脉浮洪，主病机为热毒炽盛。", ["弦", "大", "洪", "浮"]], "6160": ["病机", "脉左弦数、右洪数但不克指，为误下后邪陷化热、表里皆热之象。弦主邪郁少阳，数主热盛，洪为阳明热炽，不克指示正气已伤。症见昏闷谵语、头痛身疼、舌沉香色、口干燥渴，皆热邪内陷、壅滞三焦所致，故断为误下坏症。", ["弦", "数", "洪"]], "6161": ["病机", "六脉浮弦而数鼓指，浮主表邪未解，弦主春温木气之郁，数主热盛，鼓指为邪正相争之象。症见头项痛、腰脊强、遍身如被杖、口渴不寐，皆春温外感、内伤复加，邪郁肌表、热壅经络之候，故滋阴反剧、疏通热尤不退。", ["浮", "弦", "数"]], "6162": ["病机", "脉之近数，数主热盛，为乳肿欲成痈毒、热毒壅聚之征。症见寒热虽退而肿不消，痛减而肿仍不消，脉近数知热毒未散、肉腐成脓，故用内托十宣散加金银花、蒲公英以托毒排脓，服后脓溃而安。", ["数"]], "6163": ["病机", "独右寸脉洪大有力，右寸候肺，洪大为暑热燔灼、酒面积热壅肺之象。症见吐、胸膈痞闷、口渴嘈杂、目珠如金、一身尽黄，为暑湿内蕴、脾火燥动、湿热郁蒸发为疸症，故先解暑清热，使湿热散而黄自瘳。", ["洪", "大"]], "6164": ["病机", "两寸脉滑而数，两关弦。滑主痰，数主火，弦主郁，寸候肺、关候肝胆，故断为肺有宿痰、胆有郁火。症见喘嗽连声、浓痰滚滚、行动喘促、夜分口渴、胸膈胀闷，皆痰火郁于上焦、肺失肃降之候，故用火郁发之之法。", ["滑", "数", "弦"]], "6165": ["病机", "左关弦大，右寸关滑大。弦大为肝郁化火、气逆于上，滑大为痰壅上焦。症见胸膈背心胀疼、头眩晕、脚软弱、手指痛、咳吐红痰，为食饱后感怒、老痰瘀血积于上焦、热壅不通之候，故当清化上焦，忌滋阴滞腻。", ["弦", "大", "滑"]], "6166": ["病机", "左寸关脉洪滑，右关亦然。洪主火盛，滑主痰聚，左关候肝胆、右关候脾胃，故断为肝胆有郁火、胃中有胶痰。症见胸胁胀痛、五更嘈杂、嘈杂则痛甚，为木火郁而犯胃、痰火互结之有余疾，故用龙荟丸条达疏通。", ["洪", "滑"]], "6167": ["病机", "左脉弦数，右寸短弱。弦数主肝火太炽，短弱主肺气不足。症见暑月小便不利而痛、玉户肿、便血、发热，为肝经壅塞、血热妄行、肺失通调之候，故治当疏决肝经壅塞，使气畅热解，则小水通而肿痛消。", ["弦", "数", "短", "弱"]], "6168": ["病机", "两寸关俱滑数、尺也数，滑主痰湿食积，数主热，说明湿热积滞蕴结肠胃，气血壅滞，故见脐腹疼痛、白带如注、赤白痢里急后重；四肢酸疼为湿阻经络。脉滑数与此湿热积滞之痢症相应，故用芩连清热、木香槟榔行气导滞。", ["滑", "数"]], "6169": ["病机", "左脉浮大、六部俱数，浮主表、大主热盛、数主热，说明三阳合病、暑热充斥表里，故额痛遍身痛、口干苔黄、小水赤痛、烦躁不睡；脉浮大数正合暑热鸱张、邪在三阳之机，故用白虎合柴胡清解。", ["浮", "大", "数"]], "6170": ["病机", "两寸关脉滑大、两尺沉弱，滑大为气滞痰食壅于中上，沉弱为下元血虚不足，故断为血虚气滞症；胃脘疼痛拒按、饥不能食，正是气滞于中、血虚失养之候。脉象上盛下虚，与年高血虚气滞之病机相应。", ["滑", "大", "沉", "弱"]], "6171": ["病机", "左脉微弦、右关滑大，弦主疟邪少阳，滑大为痰湿食滞壅于脾胃，故三阴疟久发、热多寒少；饮食不进、四肢懒倦为脾虚痰滞之象。脉弦滑大说明疟邪未解而脾运受困，故先以二陈加柴胡和解，继以白术首乌补截。", ["弦", "滑", "大"]], "6172": ["病机", "左脉浮弦而数、中按有力、右关滑大，浮弦数主春温邪在少阳阳明，滑大为里热痰滞，故两太阳痛、胸胁疼、口渴、水泻；脉浮弦数有力正合春温表里俱热之机，故用柴胡葛根石膏清透而愈。", ["浮", "弦", "数", "滑"]], "6173": ["病机", "右脉洪大如豌豆，洪大为阳明热盛、气血壅滞，故腹中微疼、经行不利、喉痛、四肢麻木作战、不知饥饿，为热壅气滞、经血不畅之候；脉洪大与实热内壅相应，故用芩连荆防清散、芎附调经而安。", ["洪", "大"]], "6174": ["病机", "左脉软弱、右关尽弦数有力，软弱为气血不足，弦数有力为疟邪痰热壅于脾胃，故三阴疟久发、寒多热少、盗汗；脉左弱右弦数，示正虚邪恋、脾困痰滞，故用白术首乌扶正、柴胡黄芩青皮截疟。", ["软", "弱", "弦", "数"]], "6175": ["病机", "左脉弦数、右关尺沉数有力，弦数主热，沉数有力主里实热结，说明妄下妄补后疫热内陷、壅结阳明，故神昏、舌尖沉香色、舌根焦黑芒刺、语言不清；脉沉数有力与疫毒内结之坏症相应，故用石膏知母枳实清下。", ["弦", "数", "沉"]], "6176": ["病机", "脉左弦数，右滑大而数。春温后经水适止，余热不退，热入少阳阳明。左弦数主少阳胆热，右滑大数主阳明热盛痰滞。胸胁痛、耳重为少阳经气不利；口渴为阳明热耗津液。脉症合参，病机为少阳阳明合病，余热未清，痰热内蕴。", ["弦", "数", "滑", "大"]], "6177": ["病机", "六脉俱洪数，为少阳阳明合病之疫。洪脉主热盛，数主热急。症见头疼身燔、口渴气促、舌心焦黑、遍体紫斑、发呃耳聋，皆热毒炽盛、充斥三焦之象。误进藿香正气散致呕逆水泻，柴苓汤热转增剧，更伤津液。洪数脉与壮热、斑疹相应，主疫毒内陷阳明少阳。", ["洪", "数"]], "6178": ["病机", "左脉弦数坚劲搏指，主瘀血痰积胶结。弦为痛为积，数为热，坚劲搏指示实邪壅盛。患者壮年原有湿热痰积，跌伤背胁，旧瘀未净，新血不循。左胁痛手不可近、小腹痛，皆瘀阻络脉之征。脉症相符，故以攻下瘀痰为治，瘀去则脉自和。", ["弦", "数", "坚"]], "6179": ["病机", "两寸脉累累如贯珠，两尺俱软弱，为上盛下虚之候。上盛者，痰与瘀血壅于肺；下虚者，肾阴弱也。咳嗽吐红、发热头眩，为瘀痰化热上扰；脚膝乏力、精神渐羸，为肾阴亏虚。脉象虽未明言，然「累累如贯珠」示寸部滑实，尺弱示根本不足，病机为痰瘀阻上、肾阴亏下。", []], "6180": ["病机", "左浮而弦数，右洪长而数。浮弦数主少阳热邪外达，洪长数主阳明热盛。症见头痛口渴、舌苔黄燥紫黑、身热昏愦、谵语耳聋、胸胁痛，为热厉之邪充斥阳明少阳二经。脉症相对，故断为可生。洪长示热势虽盛而胃气未绝，弦数示少阳枢机不利。", ["浮", "弦", "数", "洪"]], "6181": ["病机", "六脉沉弦而数，主疫后阴阳易类证。沉为病在里，弦为痛为郁，数为热。新寡七日疫及，大热头疼口渴胸胁痛，为疫毒未清；梦交汗出、四肢如解、神昏谵语、面如土色、舌焦强硬，为阴精骤泄、邪陷少阴。沉弦数脉示邪热内郁而正气已伤，危候已极。", ["沉", "弦", "数"]], "6182": ["病机", "脉左沉弦，右滑数。沉弦主气滞血瘀，滑数主湿热积滞。滞下复食，里急后重，下稠黏紫黑血无粪，口渴胸膈焦辣，肛门辣痛，为湿热积滞壅遏肠腑，气血凝滞。左沉弦示肝气郁滞，右滑数示阳明湿热。脉症合参，病机为积滞胶固、湿热伤络。", ["沉", "弦", "滑", "数"]], "6183": ["病机", "脉浮大无力，主虚阳外浮。患者久服五虎汤，麻黄石膏耗散胃中冲和，致腹大如箕、两腿光肿、臁疮流水，为脾肾阳虚、水湿泛滥。浮大无力非实热，乃阳气浮越、根本已虚之象。脉症相应，病机为过服峻剂损伤中阳，水气太过，本虚标实。", ["浮", "大"]], "6184": ["病机", "左脉浮数、中按弦，右滑数，浮数主湿热在表，弦主风，滑主痰，合之乃湿热风痰壅遏经络。肢节红肿热痛、游走不定，为行痹；喘咳气涌不能睡，为痰热壅肺。脉症相合，故以祛风清热、化痰通络取效。", ["浮", "数", "弦", "滑"]], "6185": ["主病", "脉洪数，洪为热盛，数为热急，热壅肺络，血肉腐败，故咳吐桃花脓、腥秽恶气，胸背隐痛、右胁乳胀，身热便燥、肌瘦骨立，此肺痈已成之候。洪数之脉正合热毒炽盛、脓痰瘀血壅滞之病机。", ["洪", "数"]], "6186": ["病机", "右寸关脉滑大有力，滑主痰饮，大主实热，寸关候肺脾，故知气郁食积痰饮内结。忧思伤脾，脾气结则津液凝聚为痰，痰气上逆则喘急背胀，食积内停则腹胀便结。脉象有力，证实非虚，故先定喘，继以消痰化积而愈。", ["滑", "大"]], "6187": ["病机", "左涩右滑，涩主瘀血内阻，滑主痰积，据脉知有瘀血痰积。休息痢下紫血、腹痛日久、体倦肌瘦，乃痰瘀胶结肠道，气血不畅。涩滑并见，正合瘀痰互结之病机，故下瘀血痰积后痛除痢止。", ["涩", "滑"]], "6188": ["病机", "右脉濡数，左脉洪数，濡主湿，数主热，洪为火盛。忧思伤脾肺，饮食不化，积而生痰，郁而化火，故肠鸣腹痛、溏泻、潮热汗出。脉象虽似虚怯，实为郁火痰积，故理中焦、消痰积而瘳。", ["濡", "数", "洪"]], "6189": ["病机", "左浮而弦大，右滑大俱数，浮弦为风，滑大为痰火，数主热。胃中痰火上壅，热极生风，上扰清窍，故耳鸣闭塞、鼻塞、口不知味、痰多膈热。脉象反映痰火风热上攻之病机，故清上化痰熄风而诸症平。", ["浮", "弦", "大", "滑"]], "6190": ["病机", "两寸洪滑，两尺沉微，寸候上焦，洪滑为痰火壅盛；尺候下焦，沉微为肾阳不足。上盛下虚，痰火扰于上则吐痰身热、吼喘乱语、面赤头痛，下虚则根本不固。脉象明确揭示上盛下虚之候，故清上补下而瘳。", ["洪", "滑", "沉", "微"]], "6191": ["病机", "两寸脉短涩，短主气损，涩主血滞，寸候心肺。孀居二十年，忧伤肺脏，肺气郁结，心气不足，故神情恍惚、口乳语、常悲泣。脉短涩正合忧伤肺、脏寒多泣之病机，故用大枣小麦汤养心润肺而愈。", ["短", "涩"]], "6192": ["兼症", "两寸脉洪大，右关滑大，洪大为热盛，滑主痰湿。热与痰湿相搏，故五六月间必吐紫黑血块，足跟焮肿痒痛流黄水，此湿热下注、血热妄行之兼症。脉象与症候相应，热清湿化则愈。", ["洪", "大", "滑"]], "6193": ["病机", "脉才四至，大而不敛，此真气虚中满之候。脉大而不敛为正气涣散，四至为迟，主虚寒。症见腹大如箕、足膝肿大、气壅不能卧，皆脾肾阳虚、水湿不化所致。若攻下则更伤正气，故法当温补下元兼理脾。", ["大"]], "6194": ["病机", "六脉俱洪大而数，洪大为热盛，数为热急。杨梅疮毒内陷，在上则喘咳胸胀，在下则肛脱疮满，阴囊红肿，皆热毒炽盛、气血壅滞之象。脉症相符，幸壮年可治，待瘀血毒物出后乃可敷药。", ["洪", "大", "数"]], "6195": ["病机", "六脉弦数，弦主痛、主肝郁，数主热。骨梗后硬物压伤胃脘，瘀血停留膈间，食管被逼向后，故胸膈胀痛、饮食从背后而下，恶寒发热。弦数为瘀热内结之象，消瘀则脉症自平。", ["弦", "数"]], "6196": ["预后", "六脉滑大无力，滑主湿浊，大而无力为气虚。痢下屋漏水、血子，哕恶不食，神昏发热，乃脾肾衰败、湿热未清而正气已竭。脉洪大者死，大而无力仍作虚看，屋漏脉现则预后不良。", ["滑", "大"]], "6197": ["病机", "六脉滑大无力，滑为湿浊内蕴，大而无力为气虚不敛。产后下痢红白，胃脘痛不止，汗多，乃气郁化热、湿浊内阻而中气已虚。法当收敛，以小建中汤为主，温中补虚、缓急止痛，痛减汗未全敛，加御米壳以固涩。", ["滑", "大"]], "6198": ["病机", "脉得沉弦而数，沉主里，弦主肝郁、主痛，数主热。疟久不愈，胸膈痞闷、口渴、小便混浊腥臊，面黄肌瘦，乃湿热内蕴、肝脾不和、正气已伤。沉弦数为里热郁结之象，非单纯表症或虚寒。", ["沉", "弦", "数"]], "6199": ["病机", "六部皆弦，弦脉乃肝木所主，搀前而至是肝有余而脾土受敌。症见肌肉瘦削、尻膝肘肩皆肿痛发热、色青白、饮食少，此筋痿症也。诸痿不可作风治，前医皆用风剂伤血，血枯则筋失养，弦脉正示肝旺脾伤之机。", ["弦"]], "6200": ["病机", "脉细涩为气血两伤、寒湿秽瘀凝滞经络之象。痢后风由治痢不善，寒湿瘀滞日久，气血为痛所伤，故脉细涩。细主虚，涩主瘀，正合虚虚实实之机，症见筋骨肿痛、肌肉消、烦躁，乃虚中夹瘀。", ["细", "涩"]], "6201": ["其他", "原文仅述症候与嗜肉之癖，未及脉象，故脉象要素为空。其病机为脾虚肉积，嘈杂与痛交替，属虚实夹杂之候，非脉诊可断。", []], "6202": ["妇人", "两关脉滑数，滑主痰湿食积，数主热。孕逾七月食冷患痢，湿热积滞下焦，故腹痛后重、小水不利。滑数见于关部，示中焦湿热壅滞，胎前痢疾之候。", ["滑", "数"]], "6203": ["病机", "六脉滑大而数、浮而不敛，滑大为痰，数为热，浮为风。体肥善饮则湿生痰，痰生热，热生风；荒于色则真阴竭而脉浮。手指掉硬、口角牵扯，中风之兆已见。", ["滑", "大", "数", "浮"]], "6204": ["预后", "脉细如蛛丝，为疫毒内陷、正气衰微之危候。经治后六脉渐见，即“脉绝微续者生”，示胃气渐复，故断可保无事。此段以脉象判断预后顺逆。", ["细"]], "6205": ["病机", "脉皆缓大无力，缓大为脾虚湿盛之象。痢下红脓、腹大痛日夜百余次，由饥饱后纵欲，脾经为寒湿所伤，脾不裹血，故脉缓大无力，主虚寒湿滞。", ["缓", "大"]], "6206": ["病机", "两寸滑数，左关尺涩。滑数主痰热，涩主瘀血。瘀血痰饮积于胸膈，故吐烂猪肺状物、胸背胀。酒伤脾、怒伤肝，血随气上，脉象正合瘀血痰饮之机。", ["滑", "数", "涩"]], "6207": ["病机", "左关弦大，右寸下半指累累如薏苡子状。弦大为肝火亢盛，右寸痰壅之象。多酒多怒，湿热助火生痰，火炎迫肺，痰壅肺窍，故吐血、溲血、声哑，此有余症非瘵。", ["弦", "大"]], "6208": ["病机", "六脉滑数，滑主痰湿，数主热，合为湿热痰火内蕴。痢赤白俱下、呕吐痰涎、粒米不进，皆湿热痰火壅滞胃肠、胃气上逆之象。虽形气不足，然脉滑数示邪实未去、神存可治，故以二陈汤加益元散、姜汁炒黄连黄芩清化湿热痰火而呕止痢瘳。", ["滑", "数"]], "6209": ["病机", "两寸脉洪滑，寸候肺，洪为火盛，滑为痰壅。咳吐红痰如桃花脓色、前后心胀痛，正是瘀血痰火郁滞肺之气道、欲成肺痈之征。洪滑之脉应痰火壅盛于上焦，故治当调气化痰、兼消瘀血、清理肺金，方用山栀丹皮贝母桑皮等而瘳。", ["洪", "滑"]], "6210": ["病机", "左弦数、右洪大而数，弦数主肝胆热盛，洪大数主阳明气分热炽。春温食复，人事昏沉、内热口渴、舌如焦煤、胁痛耳聋、身热如火，正合少阳阳明合病、热邪充斥三焦之机。故用柴胡石膏黄芩知母葛根双解两经，后脉右寸稍软加人参扶正而热退。", ["弦", "数", "洪", "大"]], "6211": ["病机", "原文未识脉名，仅言脉之早晚、大小、缓急不一。脉象乍大乍小、时缓时急而无定体，正是虫积扰动、气机逆乱之征，故知其为虫。腹痛呕吐不止而诸药不效，亦合虫扰胃肠之候。以干姜槟榔苍术五灵脂乌梅川椒温中安蛔杀虫，痛吐立止，脉无定体实为辨证眼目。", []], "6212": ["病机", "两手俱缓弱，缓弱主脾胃气虚、运化无力。遍身痱痤红痒，前医屡用蒺藜荆芥升麻葛根等疏散风热，反伤脾胃，致饮食顿减、发疮痛痒。脉缓弱说明病本在脾虚湿蕴而非风热实邪，故以六君子汤减半夏加扁豆砂仁苡仁山药等健脾渗湿，饮食进而疮疥如蜕。", ["缓", "弱"]], "6213": ["病机", "右脉滑、左脉弱，右滑主脾有痰湿积滞，左弱主血虚不荣。心脾痛因劳倦而致、得食压之立止，是中虚夹痰之候；两腿生疮亦湿浊下注。故以芍药甘草汤缓急止痛，佐蒺藜胡麻当归养血，黄柏清下焦湿热，菖蒲茯苓化痰，后以小建中汤加减调补而疮愈。", ["滑", "弱"]], "6214": ["病机", "右关脉滑大有力，右关候脾胃，滑主痰，大主热盛。八岁女腹高于胸、发热面红、咳嗽呕吐甚至连血喷出，正是风热羁绊脾肺之间、痰热壅盛上逆之象。滑大有力示邪实非虚，故用滑石枇杷叶麦芽天麻半夏曲枳实枳壳防风青皮清疏风热、化痰降逆，热退嗽定而吐瘳。", ["滑", "大"]], "6215": ["病机", "两手脉俱软弱，软弱主气血亏虚、筋脉失养。年近五十，左胁痛、手足抽搐、不能步履，是肝血不足、筋脉失濡之候，非实邪所致。故用当归白芍木瓜石斛枸杞人参牛膝等养血柔肝、益气舒筋，药后下黑血而痛搐俱缓，改方调补而精神和好，脉软弱正合虚证之机。", ["软", "弱"]], "6216": ["病机", "六脉洪大，面赤唇红似涂朱，喊叫之声四舍悚骇，此热盛于内、气血沸涌之象。然前医以香连丸、黄芩芍药汤苦寒不愈反增痛，知非实火，乃血痢日久、阴伤及阳，虚阳外浮，故脉虽洪大而伏床泪不能言，是假热真寒、格阳之候，故用芍药甘草汤加姜桂温中，热退痢减。", ["洪", "大"]], "6217": ["病机", "脉甚数，因怒复热吐血、口渴汗多，乃肝火犯肺、血热妄行之候；数脉主热，热迫血溢故吐血。药后数脉渐退而左脉尚弦，弦为肝旺未平，寒热虽止而肝气未和。后因将息失宜，两胁痛、痰多难嗽，脉较前不甚数，是热减而痰气郁滞，故以栝蒌、贝母、青皮、香附化痰理气而安。", ["数", "弦"]], "6218": ["病机", "两寸脉滑大，滑主痰、大主实，痰积胸膈上焦；两尺沉微，沉微为下焦阳虚。心痛彻背、背痛彻心、必探吐其食乃已，是痰食壅塞胸中、上实下虚之证。积气丸消积行气，故不终剂而十七年痼疾断根，脉症相合，病在痰积气滞而非虚寒。", ["滑", "大", "沉", "微"]], "6219": ["病机", "脉浮而数，浮主风邪在表，数主热，合咳嗽胸胁背心胀痛如刀刃所痌、发热口渴，是风寒外束、鼓激痰火上涌，肺气壅逆之候。故以麻黄、前胡、紫苏散风邪，栝蒌仁治痰火为君，佐旋覆、杏仁降气，表解火降则两剂而平，非单纯内伤咳嗽。", ["浮", "数"]], "6220": ["病机", "六脉缓大有力，缓主湿、大主实，力则为有余。经闭八年而肌肉丰肥、饮食倍加、精采艳美、腹柔不坚，是脾湿生痰、脂满子宫，非血枯经闭。前医四物、三棱、莪术破血千余帖罔效，正因痰脂壅塞而非瘀血，故法宜调气消痰、燥湿熔脂，使清瘦则经自行。", ["缓", "大"]], "6221": ["病机", "脉沉弦有力，沉主里、弦主痛主气结，有力为实。腹膨懑成胀满、青筋缕缕如贯索、中有一块坚若铁石，是气滞血瘀、实邪内结之鼓胀，非气虚中满。前医见形神俱弱误投参苓白术散，补之太骤反助其壅，故胀堵如鼓，审脉验症当以实治，不可作虚损。", ["沉", "弦"]], "6222": ["病机", "右脉缓弱无力，右主脾胃，缓弱无力为脾胃气虚、清阳不升之象。饮茶逆流从鼻出、食粥饭亦多从鼻出，是胃气上逆、升降失司，非胃火冲逆。诸医投黄连解毒、三黄石膏苦寒，愈服愈病，反加恶心头晕、肌肉削、四肢无力，正伤其中气，故脉见缓弱无力，当补中升清。", ["缓", "弱"]], "6223": ["病机", "六脉濡大无力，濡主湿、大而无力为气血不足兼湿滞。产后半月右腿疼且热，是败血凝滞血海、流于经络，久则化脓成毒。前医认虚投八珍、十全大补，痛转剧而发寒热，小腹近胯红肿出脓，正合败血化热成痈之征；濡大无力示正虚而邪滞，不可纯补，当消瘀排脓。", ["濡", "大"]], "6224": ["病机", "脉大数，大主邪盛，数主热。结合右胁痛、面青、汗出如雨，乃肝胆郁热，木火亢盛，上冲耳后，迫津外泄。夜属肝气用事，故痛甚。中焦湿痰内蕴，故右关沉滑。脉症合参，病机为肝经郁热，痰湿内阻，法当调肝清热。", ["大", "数"]], "6225": ["病机", "右寸关洪滑，洪为热盛，滑为痰聚。右寸关候肺胃，症见鼻塞、衄血、咽喉痰核、口渴，显系肺经痰火壅盛，上灼清窍。火性炎上，迫血妄行则衄；痰火胶结则生痰核。脉象与症候相应，故断为肺经痰火症。", ["洪", "滑"]], "6226": ["预后", "左脉散乱如解索，为正气涣散、神气将绝之兆；右脉如豆大弹指，乃胃气衰败、痰食内阻之象。两尺绝无神气，根本已竭。脉症不符，久病虚弱而见散乱，预后不良。故断为不治，示人以脉决死生。", ["散", "乱", "虚", "弱"]], "6227": ["病机", "两手脉浮洪数滑，浮为风邪在表，洪数为热，滑为痰。症见恶风、潮热、吐红、咳嗽痰多，乃外感风邪，引动内热，痰热壅肺，灼伤血络。虽年高脾泄，然脉症属实，法当清解，不可拘泥于温补。", ["浮", "洪", "数", "滑"]], "6228": ["其他", "原文仅述“予以脉知其伤风伤食所致”，未载具体脉象，故脉象要素为空。据文意，脉诊所得支持伤风伤食之诊断，然无脉形描述，难以深析病机。", []], "6229": ["病机", "左脉弦大，右脉滑大。弦主肝主痛，大主邪盛，滑主痰食。右胁痛、体肥面青、咳嗽夜甚，乃外伤风邪，内伤食滞，痰食互结，肝络不和。脉症合参，病机为风邪外袭，食痰内阻，肝胆气机不利。", ["弦", "大", "滑", "大"]], "6230": ["病机", "左脉数，右脉滑数。数主热，滑主痰食。症见上焦浮热、头面疮疖、腹痛泄泻、便后带红，乃胃中食积痰饮郁而化热，劳心引动相火，上炎则生疮，下迫则便红。脉象揭示痰热内蕴，肝胃火旺。", ["数", "滑", "数"]], "6231": ["病机", "右脉滑数，左脉弦数。滑数主痰热，弦数主肝火。症见咳嗽口干、腹中如火、右胁痛、不思饮食，乃中焦痰积化热，肝火犯肺，木火刑金。脉症相应，病机为痰热中阻，肝肺火郁。", ["滑", "数", "弦", "数"]], "6232": ["预后", "脉三四至一止、七八至一止，为结脉，非死候。患者年高痰火，大便频、肠鸣腹胀，脉歇止由痰湿凝滞、气血不畅所致，非元气败绝。两尺迢迢有神，示肾气未竭，故预后尚可，非凶兆。", ["结"]], "6233": ["病机", "脉缓而止曰结，数而止曰促。此案脉三四至一止、七八至一止，为结脉，由寒湿之痰凝滞、气血不畅所致，非凶脉。误用苦寒克伐，更伤中阳，致腹疼。法当温补下元，使火生土，则痰湿化而脉复。", ["结", "数"]], "6234": ["主病", "左关尺脉甚弦，弦主肝经气结、寒湿凝滞。疝气半年，两胯结核硬痛，乃肝脉循少腹环阴器，寒湿痰浊结聚所致。弦为痛、为积，故以平疝丸消痰软坚、疏肝散结，服一月而消。", ["弦"]], "6235": ["兼症", "左弦大主肝胆热盛，右寸短弱为肺气不足，关尺滑大为痰热内蕴。疟热多寒少、口渴、小水不利，乃痰热壅遏、少阳不和。脉症合参，热多伤津，故用石膏、知母清热，柴苓和解，后以益气养阴收功。", ["弦", "大", "短", "滑"]], "6236": ["病机", "左脉弦大而数，右滑大而数，弦主肝胆，滑主痰热，数主火。患者嗜爆炙，致肝胆二经热毒蕴结，发为胁下红块硬痛。脉象示热毒炽盛、痰瘀互结，故治以活血清热、解毒散结，使硬块潜消。", ["弦", "大", "数", "滑"]], "6237": ["病机", "六部皆弱，唯右关滑，弱主气血不足，滑主胃中有痰。心血不足、下元阳虚，故脉弱；痰滞中焦，故右关独滑。此虚中夹痰之候，法当补益心肾、温阳固精，兼化痰湿，丸剂缓图。", ["弱", "滑"]], "6238": ["病机", "两寸短，关滑，两手皆数。短主气郁，滑主痰，数主火。患者酒积郁火，痰热壅阻胸膈，故胸膈胀痛、痰中紫血。脉象示痰火郁结、气机不畅，治以清火化痰、行气解郁，使胸宽而愈。", ["短", "滑", "数"]], "6239": ["病机", "两尺脉洪大，两关滑，两尺沉微，洪大滑为痰火壅盛于上，沉微为肾阴不足于下，此阳亢阴微、上盛下虚之候。上盛则头目不清、耳鸣眩晕，下虚则腰膝酸软。法当清上补下，使火降痰消、阴复筋强。", ["洪", "大", "滑", "微"]], "6240": ["病机", "左寸短弱，关弦大，右寸下半指与关滑大，两尺洪大。左寸短弱示心气不足，关弦大主肝经瘀血；右寸关滑大主中焦痰浊；两尺洪大因血去阴伤、虚火下迫。原文断为“中焦有痰，肝经有瘀血”，与血淋、面热牙疼、燥渴便结相应，故治当去瘀生新、提清降浊。", ["短", "弱", "弦", "大"]], "6241": ["病机", "两手脉皆沉数，左弦。沉主里，数主热，弦主饮。原文谓“此上焦有痰饮故也”，痰饮停膈则饮白汤亦停、作酸呕逆；郁热上扰则面赤手心热、耳鸣眩晕。脉沉数弦正合痰饮郁热之机，故以二陈汤加味化痰清热而愈。", ["沉", "数", "弦"]], "6242": ["病机", "脉涩，原文断为“此气虚而痛也”。涩主气血涩滞，气虚推动无力则脉道不充，故痛而喜按、冷汗如雨。胃脘痛彻背、重按少止，皆虚痛之征。涩脉在此非独主瘀，结合症候当从气虚血涩解，故用小建中汤加御米壳补虚缓痛而愈。", ["涩"]], "6243": ["病机", "左寸沉弱，关尺弦细，右寸略滑。左寸沉弱示心气不足，关尺弦细主肝经瘀血内结；右寸略滑为肺经浊痰。原文谓“肺经有浊痰，肝经有瘀血”，总由酒后纵欲、淫火交煽，精离故道，凝滞溺道而成血淋。脉症相合，故先以丹参等化瘀澄心。", ["沉", "弱", "弦", "细"]], "6244": ["病机", "左寸短，右关滑，两尺弦大。左寸短示心火不充，右关滑主中焦湿滞，两尺弦大为下焦风热壅盛。肠风下血、腹中微痛，乃风热湿浊下迫大肠，血络受损。脉弦大滑与便血相应，故用地榆、槐花、荆芥穗等清肠凉血疏风而愈。", ["短", "滑", "弦", "大"]], "6245": ["病机", "左寸短弱，关弦大，右寸关滑，两尺洪大，六部皆数。左寸短弱示心气不足，关弦大主肝经郁热，右寸关滑主上中二焦痰火，两尺洪大数示湿热下注膀胱。原文谓“脾肺二经有痰火，中焦有湿热，流于膀胱为淋浊”，脉症相应，故先清上中痰火，后提清降浊。", ["短", "弱", "弦", "大"]], "6246": ["病机", "右寸关滑数，左弦。右寸关滑数主酒积化热、痰火壅于中上二焦；左弦主肝经郁火。原文谓酒积频伤于怒，致右胁之火冲上作疼、耳鸣眩晕、便艰，正合痰火肝郁之机。滑数示痰热，弦示气郁火升，故用当归龙荟丸加胆星泻火化痰而愈。", ["滑", "数", "弦"]], "6247": ["预后", "脉七八至，乱而无序。数而乱示热邪充斥三阳、正气散乱，原文断为“三阳合病，春温症也”。虽症见发热口渴、胸膈饱闷，脉数乱为邪盛正扰之象，非漏底伤寒。后服三阳药汗出脉伏，乃阴极阳生欲作汗之兆，故曰非死候，此段重在凭脉判预后。", ["数", "乱"]], "6248": ["病机", "左脉中按数而有力，为阳明少阳热邪内盛；右脉软弱，示正气已伤。症见发热、口渴、舌干、耳聋、胁热，正是阳明少阳并病之象。数而有力主热，软弱主虚，故以柴葛汤清解，兼顾气阴。次诊数脉稍缓，热退而舌干、小水不利，仍属余热未清、气化不利。", ["数", "虚", "缓"]], "6249": ["病机", "左脉弦数，右脉滑数。弦为肝郁，数为热，滑为痰。症见右胁下疼、咳嗽喉干、吐红，乃肝火犯肺、痰热内蕴；肠鸣泄泻为木旺克土。年六十外，性急躁，头风坏目，皆肝火亢盛之征。故以清肝化痰、凉血止血为治，郁金磨服而红止痛瘳。", ["弦", "数", "滑"]], "6250": ["病机", "两寸短弱，据脉为肺气虚；左关大而有力，为肝木实；右关滑，为胃中有痰。触怒即晕厥、手足冷、汗出如雨、气息微，乃肝气上逆、肺虚不摄；指甲无血色、经紫有块，为血虚夹瘀。总属肺虚肝实、痰阻之证，故以六君补脾肺、化痰为治。", ["短", "弱", "大", "滑"]], "6251": ["病机", "两寸短弱，关弦，右关滑，两尺平。两寸短弱主心肺之神不足，志愿不遂，郁结生痰；关弦为肝郁，右关滑为痰。面白而青，癫狂悲歌骂詈，皆心神失养、痰浊蒙蔽所致。故引《内经》主不明则十二官危，治宜补养收敛心神兼清痰，不可一味攻伐。", ["短", "弱", "弦", "滑"]], "6252": ["病机", "脉两寸软弱，主心肺气虚。患者疝疾久治，囊烂子开，气满汗出如流，终夜不寐，饮食大减，面青肌瘦，皆由外治溃烂、气随液泄，心肺之气受损。寸脉软弱正合上焦气虚之机，故予佐陈补于内，内外兼治，以固护正气为要。", ["软", "弱"]], "6253": ["误治", "本段未识脉名，述高年过劳过饮伤食，市医概用消导，反加内热；张氏误投人参致右胁胀痛，又加木香、砂仁辛热，益呕吐胀痛、大便燥结。此属误治致变，消导伤脾、温补助热，病机由食滞转为气逆热结，故原文详录误治经过以戒后学。", []], "6254": ["病机", "左洪大，右缓大。洪大为阳热亢盛，缓大为气虚湿滞。体丰嗜炙、纵欲躁急，年六十七，跌后左手足不能动、口眼歪斜、神昏鼾呼、呼长吸短，乃中风危候。左洪大主肝阳暴亢，右缓大主脾虚痰湿，色苍黑、口气不能回，示阴阳将脱，故症候甚恶，非特半身不遂。", ["洪", "大", "缓"]], "6255": ["病机", "脉皆濡弱，主气血两虚、湿邪内蕴。患者臀肛生毒，反复针溃插药凡八遍，脓血屡溃，正气大伤。濡弱之脉示气血不足、托毒无力，故疮口难敛、硬处再肿、寒热交作。此非单纯外毒，乃正虚不能胜邪，治当补托兼清，不可一味攻溃。", ["濡", "弱"]], "6256": ["主病", "原文谓“脉大为痢所忌”，今两手俱大而无力，右关略滑。痢久二十日，唇红面瘁、声微气不接、潮热呕吐，形神俱弱，是虚多实少。脉大无力为正气虚而邪未净，右关滑主积滞未消，故断为“虚虚实实，不足中之有余”，治当补养兼清兼消，缓以图之。", ["大", "滑"]], "6257": ["病机", "左弦大、右滑大，症见喉管梗梗难下、便燥内热、肌肉渐瘦。弦为气郁，大为火盛，滑主痰涎。原文断为“谋而不决，气郁成火，脾志不舒，致成痰涎，因而血少便燥，内热肌消”，引张鸡峰“膈乃神思间病”，明言病机在神思气郁，非单纯膈症。", ["弦", "大", "滑"]], "6258": ["其他", "此段论医为代天生生之职，举炎帝本草、轩岐《灵》《素》、伊尹汤液，言医道本于阴阳动静、变化顺逆、燥湿虚实之机，并引孙思邈“不知易者不足以言太医”。全段未及具体脉象与病症，属医道源流之论，故脉象要素为空。", []], "6259": ["其他", "此段以“三不朽”立论，谓立功立言本为一事，能起疲癃、泽苍生即功，阐理觉来兹即言。末及孙文垣因尊人病痹而弃儒业医。通篇论医者立德立功立言之旨，未涉脉症，故无脉象可录，归入其他。", []], "6260": ["其他", "此段述孙东宿著《医旨绪余》《赤水玄珠》行世，感慨古今运气异、南北风土殊，病不必雠脉、药不必雠病。原文“脉可按而覆，其方可悉而数”系泛论诊脉与方药相应之理，非具体脉象，故脉象要素为空，主旨属医论其他。", []], "6261": ["其他", "此段记族叔生生周游江左、临症殚思，以己之精神通患者之精神，对病投剂，积三十余年医案欲梓行济世。全段论医者仁心与临证态度，未载具体脉象症候，故脉象要素为空，归入其他。", []], "6262": ["其他", "此段为生生子自序医案之作，谓医案当如老吏断狱、爰书一定，须著症、详脉、备述治法与君臣佐使。原文虽言“详其脉”，乃泛论医案体例，非具体脉象，故脉象要素为空，主旨属医案凡例之其他。", []], "6263": ["其他", "此段论士君子济世之心，得位则施于政，不遇则隐于医，以救死扶生为功；又言医道宗旨自《内经》本草以来一百七十九家，非博通超悟不能探讨阴阳。通篇言医道与士志，未及具体脉症，故脉象要素为空。", []], "6264": ["其他", "原文为游历与论医之叙，未及脉象，亦未言病机。所述吴小峰兄弟病目，红肿、太阳痛、白星翳叠出，属目疾专科误治致重，然无脉可凭，故不能以脉析病机。此段主旨在于说明医当通变、随俗为变，非论脉主病之文。", []], "6265": ["主病", "妊妇腹痛昏厥，两手脉皆洪大，洪大为邪实壅盛之象，虽妊九月亦当下，故用承气下之而安。又叙瘄子盛行，脉浮弦而数，浮弦数主风热外袭、斑毒不透，故喘嗽发热、斑紫不敛。此段以脉洪大、浮弦数辨实热与风热，主病在邪实，非虚损。", ["洪", "大", "浮", "弦"]], "6266": ["病机", "痛风三年，脉皆弦细而数，面青肌瘦，大小腿肉削。弦主筋急拘挛，细为阴血虚少，数为虚热内扰。原文谓“禀气弱，下虚多内，以伤其阴”，阴血虚则筋失养，气为寒束则卫不卫外，营卫不行故肢节肿痛而热，病名周痹。脉弦细数正合血虚寒束、郁而化热之机。", ["弦", "细", "数"]], "6267": ["病机", "左寸短弱，右关略弦，余皆洪大。左寸候心，短弱为心气不足，故病心痹；右关略弦，木郁克土；余脉洪大，虚阳外浮之象。症见咳嗽、下午足心热上至头面、色青形羸气促、多梦遗，皆阴亏火动、心肾不交。诸医谓火，然脉非实火，乃虚损夹郁，故可治。", ["短", "弱", "弦", "洪"]], "6268": ["主病", "年六十七，过啖瓜果而胸膈胀痛，脉寸关弦紧。弦紧主寒饮内停、气机壅遏，瓜果生冷伤中，寒饮结于胸膈，故胀痛。然原文观其“神藏气固”，虽症脉似实，而胃气未败，故断为易瘳。弦紧在此主寒饮实邪，非虚寒，亦非死候。", ["弦", "紧"]], "6269": ["病机", "便血三年，左脉沉涩，右脉漏出关外。沉涩主瘀血内积、血行不畅，原文谓“必有瘀血积于经隧”。右脉漏关难凭，故先以升提兼补兼涩探其虚实，后得病情，法当下而除根。沉涩在此主瘀血久积，非单纯气虚下陷，故补中益气仅暂止而复作。", ["沉", "涩"]], "6270": ["预后", "马厨病痢，日夜八十余行，腹痛恶心，汗多神倦，脉洪大。原文引“下痢脉洪大者死，细微者生”，以痢伤阴血，脉宜细微，洪大为邪热鸱张、正气反浮之逆象，故曰“洪大逆也”。然予又谓寒热非细微所宜，其中必有故，示洪大虽逆，尚须参合寒热辨治，非一概断死。", ["洪", "大"]], "6271": ["病机", "咳嗽体倦多汗腹痛，左手三五不调，右手沉弦，面青息微，腹中漉漉有声。沉弦主饮邪内结、木郁克土，腹中漉漉为水饮流动；左手不调为营血涩滞。前医误表误下，致脉急缩，原文谓“脉急缩也”“脉弦不退”，示饮邪未化、气机挛急，病机在饮停气滞、误治伤正。", ["弦", "急"]], "6272": ["病机", "右脉滑大，左浮弦而数。滑主痰，大主热，浮弦为风邪外袭，数则为热。患者头痛恶寒、胸膈懑痛、时发寒热，乃痰热内蕴、风邪外束之象。前医误作血虚经滞，投四物汤养血调经，然太夫人年七十余，经水早绝，药证不符，故不瘥。脉象揭示病机在痰热风邪，非血虚也。", ["滑", "大", "浮", "弦"]], "6273": ["病机", "脉左弦右滑数。滑为痰，弦为饮，数主火。患者虽因跌仆胁痛，前医屡用行血散血活血之剂无效，且脉不沉伏、不芤涩，反见弦滑数，故知非瘀血，实为痰火留滞经络。痰火阻络，气血不通，故胁痛昼夜不宁。公言生平无痰，然脉书云滑为痰、弦为饮，当据脉断病，不可徇言。", ["弦", "滑", "数"]], "6274": ["病机", "脉左弦大，右滑大而数。弦大为肝阳上亢、气逆火升，滑数为痰热内盛。患者心痹晕厥、胸膈痛不可忍、烦躁干哕、恶内蒸热、气喷喷上腾，皆痰火壅盛、肝风内动之候。诸逆吐酸皆属于火，诸风掉眩皆属于肝，脉证相合，故断为可生，治当清火化痰、平肝降逆。", ["弦", "大", "滑", "数"]], "6275": ["误治", "本段未识脉名，述马二尹过食鳗肉卷饼，心腹胀痛，市医不知用吐，遽用硝黄下之，继以木香槟榔丸、小承气、大承气、白饼子、备急丸、甘遂芫花大戟牵牛等峻下攻逐，愈下愈胀，大便不行，小便点滴亦无。此食积中焦，本宜吐法，反屡用下剂，诛伐无过，致气机壅塞，胀痛益甚，乃误治之典型。", []], "6276": ["病机", "脉沉而濡弱。沉主里，濡弱为气虚阳衰之象。患者多怒多欲，胸膈否胀，饮食少，医屡用平胃、枳术、香砂、槟榔、三棱、莪术等消伐，致大便溏泻、手足浮肿、面色黄黑、身重不能动止。此气虚中满，清阳不升则便溏，浊阴不降则胸胀，脾虚水湿泛溢则浮肿。脉沉濡弱正合气虚，法当温补升提。", ["沉", "濡", "弱"]], "6277": ["主病", "脉六部皆洪长而数。洪为热盛，长为邪气有余，数为热急。患者连看戏文、多食鱼腥虾蟹，发寒热，耳前后颊车红肿，渐及满头红大如斗，昏愦谵语，粒米不进。此大头疫也，乃热毒壅盛、上攻头面之证。洪长数脉正合热毒炽盛之病机，故以贯众、石膏、柴胡、葛根等清热解毒、疏风散邪而愈。", ["洪", "长", "数"]], "6278": ["预后", "脉上盛下虚，左弦大。上盛为痰与火，下虚为精元弱。弦大为肝阳偏亢、痰火内蕴之象。患者年甫逾疆，微觉阳萎，下虚可知；痰火在上，故脉上盛。予断三年内恐中风不免，盖由痰生热、热生风也。公未暇制服，次年中秋连宵酒色，果中风。此脉示上实下虚、痰火生风之机，预后凶险。", ["弦", "大"]], "6279": ["病机", "脉两寸短弱，两关滑，两尺洪滑。寸短弱为心肺气虚，关滑为痰湿中阻，尺洪滑为湿痰下流、相火妄动。患者白浊精淫淫下，乃湿痰下注、精关不固之证。经云治痰必先理气，脉书谓洪为痰火。两尺洪滑尤显下焦湿痰蕴热，故断为湿痰下流症，治当理气化痰、清利下焦。", ["短", "弱", "滑", "洪"]], "6280": ["妇人", "左寸洪滑，两尺皆滑数，左尺尤有神气。滑为孕脉，数主血热，洪为气分有热。脉滑非经闭之象，左尺神气为胎元之征，故断为孕。发热腹痛乃气虚血热所致，非经闭实邪，故以安胎饮加减补气清热而安。", ["洪", "滑", "数"]], "6281": ["预后", "产后两日脉皆软弱，为气血亏虚之常。后因食滞、怒气，吐泻交作，元气脱而脉散乱如解索状，神气惫而恍惚，循衣摸床。解索脉乃元气败绝之死候，散乱无根，胃气已竭，故病势危急。", ["弱", "软", "散", "乱"]], "6282": ["病机", "六脉皆数，数脉所主，其邪为热，其症为虚。产后误下，大泻伤正，发热恶心，粒米不进，昏愦耳聋，虚浮。数而无力为虚热，非实火。后六脉散乱无伦，脉又数，散乱为元气离散，数而无力为虚阳外浮，故以十全大补加炮姜温补。", ["数", "散", "乱"]], "6283": ["病机", "右寸滑，左寸短弱，两关濡，两尺皆软弱。右寸滑主上焦有痰湿，左寸短弱为心气不足，关濡为脾湿不运，尺软弱为肾气亏虚。心肾俱不足，中焦不湿，白物下多，气血日败，故法当燥脾兼补心肾。", ["滑", "短", "濡", "弱"]], "6284": ["病机", "两手脉皆驶，驶即数急之意，主热。经行前四肢发块红紫胀痛，胃脘痛，经水不及期，乃肝脾郁火，多思多怒，郁滞于中，热迫血行，故脉数。以症脉参之，肝脾二经有郁火也。", ["驶"]], "6285": ["病机", "右寸关皆数，右寸主肺，右关主脾。酒后不检，中宫多湿多痰，积而为热，流于下部，故白浊淫淫而下。数脉主热，见于寸关，为痰湿郁热在中上二焦，下流为浊，久不愈则肌瘦膝软。", ["数"]], "6286": ["病机", "六脉皆洪大，汗出如雨，喘息不相续。洪大为气分热盛，热迫津泄则汗出，热壅气逆则喘。妊娠五月，失足坠楼，瘀热内扰，心胃热盛，故脉洪大。脉宜沉细而反洪大，为热盛之象，非虚寒也。", ["洪", "大"]], "6287": ["病机", "两寸短涩，两尺洪滑，关弦。寸短涩为心肺气郁，尺洪滑为下焦湿热，关弦为肝郁。经行仅一日点滴，脉在良家为梦遗，妓者亦遗，乃金木相胜，心神无主，湿热下注，肝郁不舒，故脉象怪异。", ["短", "涩", "洪", "滑"]], "6288": ["主病", "六脉洪大，为疫毒内炽、热盛于阳明气分之象。洪大主热盛，热邪上攻则头痛身热，耗津则口渴唇燥，舌心黑苔；热扰神明则昏沉耳聋、梦多乱语。水泻不止乃热迫大肠，非虚寒泄泻，故前医补中益气、附子理中皆误，当以清解为法。", ["洪", "大"]], "6289": ["预后", "两寸洪滑搏指，两关微弦，两尺微弱，乃《难经》溢脉，上盛下虚之候。洪滑搏指为阳火上浮，关弦为木气偏亢，尺微弱则真阴亏于下。深秋木凋之时脉不宜弦大，大则阳无阴济，有升无降。至二月木旺生火，升而不降，阴阳离决，故断不治。", ["洪", "滑", "弦", "微"]], "6290": ["主病", "六脉大而无力，大则为虚，无力为气血不足，主行痹。气血亏虚，湿热痰瘀流注肢节，故手足肢节肿痛、胯痛不能起止；肌肉消半、日进粥二碗，皆脾胃虚弱、气血生化不足之征；月汛两月一行且少，亦血虚之候。", ["大", "无", "力"]], "6291": ["病机", "左弦数、右洪大，左弦数主少阳郁热，右洪大主阳明热盛。头痛骨节痛、发热口渴、胸膈膨胀、七日不食，乃外寒引动内热，邪壅阳明少阳，热盛于里。故以藿香、苍术等解表化湿，继以麻黄、葛根、石膏等清解透邪，汗出热痛皆除。", ["弦", "数", "洪", "大"]], "6292": ["病机", "右寸绝不应指，关沉滑有力，左手弦数。右寸不应指非气绝，乃邪热壅于上焦，肺气被遏；关沉滑为痰热内结中焦；左弦数为少阳热盛。故断为阳明少阳合病，邪热壅上，非膈食。药后右寸脉起，粥进，证明脉随邪解而复。", ["沉", "滑", "弦", "数"]], "6293": ["病机", "尺寸脉隐伏不见，惟两关沉滑，非六脉将绝，乃中焦食积痰泄，积胶于中，阻遏气血，故尺寸脉伏而不见。腹膨脝、粪色青、晨泄，皆积滞内阻之象。关脉沉滑正是积痰固结之征，故当下去其积，补之则谬。下后六脉齐见，证明脉伏因积阻。", ["沉", "滑"]], "6294": ["病机", "脉弦紧，弦主痛、主湿，紧主寒主痛。左膝肿痛年半、大便日三次，乃脾虚湿热凝于经络，流注下部。肿属湿，痛属火，弦紧为湿热壅遏、气血不通之象。故以苍术、黄柏、薏苡仁清利湿热为主，佐以通络，痛减肿消而泄止。", ["弦", "紧"]], "6295": ["病机", "右关滑大搏指，滑主积滞痰食，大搏指为邪实壅盛。下痢十二日，腹痛后重脱肛，嗳气不知饥，乃积滞固结肠胃，气机壅遏，故后重脱肛。前医补中益气反增腹痛后重，证实为实积非虚陷。右关独滑大，正积滞在脾胃之征，故当推荡消导。", ["滑", "大"]], "6296": ["病机", "右关滑大有力，左脉和缓，右关候脾胃，滑主痰饮、主食积，大而有力为邪实。原文谓「中焦食积痰饮胶固已久」，故滑大之脉主中焦痰食内结；眩晕呕吐、冷汗津津乃「无痰不作晕」，痰火上扰所致。次日右关仍滑，正合积久难动之说。", ["滑", "大"]], "6297": ["病机", "左寸候心，洪滑为火盛痰聚之象。原文断为「脾虚，肝心二经火盛」，左寸洪滑正应心火挟痰上扰，故后半夜不睡、两太阳及眉棱骨痛；面黄肌瘦、便溏、四肢无力则脾虚之征。脉自春至秋皆然，见火痰久羁不去。", ["洪", "滑"]], "6298": ["误治", "两关俱洪滑有力，关候肝脾，洪滑有力为实为有余，非阴虚之脉。原文力辨「此肝脾二经有余症也，作阴虚治左矣」，怒伤肝则哕血下泄，犬肉伤脾则不能统血；误用地黄、麦冬、知母、黄柏滋阴，致胸背愈胀、血来更多，故本段主旨在于纠误治之偏。", ["洪", "滑"]], "6299": ["预后", "原文未识脉名，仅言「喜左脉皆有神气」，以脉有神气断其可治，故列预后。痰火过服降火，气下行滞于大肠，脐边硬块按痛、痢下红白点滴、里急后重，皆滞下之候；左脉有神则正气未败，故敢从刘守真行血调气之法而获效。", []], "6300": ["兼症", "脉仅四至、两寸软弱、尚不数，寸候心肺，软弱为气血不足之象，四至未数为热未炽。患者孀居茹素、屡怒吐血，又见里急后重、二便交替疼痛、经停带下、虚浮痰梗，症情错杂；脉不数不实，说明非纯实热，故本段以兼症记述为主。", ["软", "弱", "数"]], "6301": ["病机", "两寸濡弱，两关滑大。寸弱为心肺气虚，关滑大为中焦痰积之实。原文断「此中焦痰积所致」，故晕厥吐痰、五更倒饱、肠鸣腹痛泄泻、小水短涩，皆痰湿内积、脾运失职使然；濡弱与滑大并见，正是虚中挟实之机。", ["濡", "弱", "滑", "大"]], "6302": ["预后", "六脉俱数，肝脉甚弦。数主热，弦主木旺。原文谓「弦则木气太旺，脾土受亏，不能统血」，又言「脾胃一虚，肺气先绝」，故咳血潮热、左胁胀疼不能侧卧、声哑肌削。脉数而弦、症见危候，段末叹「病势危矣」，主旨归于预后判断。", ["数", "弦"]], "6303": ["病机", "右关滑，左弦数。右关候脾胃，滑主食积痰滞；左关候肝，弦数为肝火内郁。原文究其因「大怒后即伤于食」，故腹中硬块如石、肠鸣、饮食俱废为食积，头疼夜热、洒淅恶寒、汗出淋漓为肝火郁蒸；前医误用滋阴苦寒，致脾气大虚，热愈甚。", ["滑", "弦", "数"]], "6304": ["病机", "原文载下痢“脉沉细者生，脉洪大者死”，而此案“两手皆滑大，尺部尤搏指”，滑主痰积，大主邪盛，尺部搏指说明积滞在下焦。前医误作瘟疫、疟疾，致噤口滞下；脉象证实非逆症，乃积滞内阻，故用当归龙荟丸“引而竭之”从下而解。", ["滑", "大"]], "6305": ["病机", "右关滑大为饮食所伤、脾胃壅滞之象，左手软弱为血虚咳嗽之本。专科误作阴虚治，反伤脾胃，致胸膈愈胀。脉象示标实（食积）重于本虚（血虚），故先健脾消食，以二陈汤加消导之品，待食积去后再治嗽，体现“脾胃喜温而恶寒”之旨。", ["滑", "大", "软", "弱"]], "6306": ["预后", "冬月病目发散太过，至春吐血，夏潮热咳嗽、冷汗、便溏、肌肉消削，脉数。数脉主热，阴血亏耗而虚火内炽，症见潮热、冷汗、便溏，正虚邪盛，故“据症脉，法在不治”。然用泻白散加味清肺养阴，竟获渐愈，说明脉数虽主热，尚需结合症候动态判断。", ["数"]], "6307": ["病机", "右关尺滑大有力，关候脾胃，尺候下焦，滑主痰，大主火，有力为实。症见大便秘结、面赤、不思饮食、头时眩晕，皆痰火壅滞之象。故断为“痰火症”，用栝蒌为君，佐滑石、枳实、半夏等清化痰火，两帖而愈，脉症相合。", ["滑", "大"]], "6308": ["病机", "右关洪滑主痰热壅盛，左寸洪数主心火，两尺洪大主下焦热盛。症见经水暴下血块、昏冒、咬牙乱语、口噤、手心热，乃浊痰流滞血海，误服安胎之剂益增其滞，痰迷心窍，血去神魂无依。脉象证实痰热内扰，故以调气开痰、安神养血取效。", ["洪", "滑", "数", "大"]], "6309": ["病机", "年高痢后过食，致滑泄不固、胸膈痞闷、语言无力、口燥生疮，元气大虚而虚火所致。尺寸俱弱示下焦元气亏虚，两关滑大示中焦浊气壅滞。正合“清气在下则飧泄，浊气在上则䐜胀”之机，故用四君子汤补气，佐葛根、桔梗升清，陈皮、麦芽降浊。", ["弱", "滑", "大"]], "6310": ["病机", "六部皆滑大有力，滑主痰，大主邪盛，有力为实。症见头痛如破、晕倒不省、胸膈饱闷、饮停不下、吐蛔，显系痰厥头痛。痰浊上蒙清窍，故昏不知人；痰阻中焦，故饮停呕逆。脉象证实痰盛属实，故先吐后下，以半夏、巴霜峻下痰积。", ["滑", "大"]], "6311": ["病机", "两手皆滑数，滑主痰积，数主火热。症见胃脘痛、手心热、呕吐不食、昼夜叫痛，乃痰火互结、壅滞中焦所致。故先以清热止痛暂息其火，继用总管丸峻下痰积，便下痰积甚多而痛止，印证滑数脉主痰火内实之病机。", ["滑", "数"]], "6312": ["病机", "两寸关洪滑、六部皆数，洪滑主痰热壅盛，数主热，痰火互结，随气上逆则胀闷不知人事、遍身皆胀；热灼津液则小水赤。原文断为“痰火症”，谓“痰生热，热生风”，故发则神识昏冒，脉象与痰火生风之机相应。", ["洪", "滑", "数"]], "6313": ["预后", "产后脉不宜大，今脉大而左手散乱，兼大热、气促、汗多，为元气欲脱、阴阳不相维系之危候，故众医谓“法在不治”。然散乱非绝脉，补后脉稍收敛、喘缓能睡，说明散乱属虚而可挽，原文以脉之敛散判预后吉凶。", ["大", "散", "乱"]], "6314": ["病机", "两手脉皆濡软无力，濡软主气血不足、脾胃虚弱，产后欠补养则精神疲困、脾胃亦弱，运化失职故腹中作痛、作泻。脉无力正合虚象，故以六君子汤加味健脾调中而安，脉症相参皆属虚损。", ["濡", "软"]], "6315": ["病机", "六脉洪滑，洪主热盛，滑主痰湿壅实，症见发热、谵语、口渴、发斑、呕吐泄泻，为少阳阳明合病、热邪充斥表里之象。服药后左脉已和、右脉稍收敛，说明邪热渐退，脉之收敛即病势向愈之征。", ["洪", "滑"]], "6316": ["病机", "左稍浮弦，右洪滑，浮弦主风热上扰，洪滑主痰火壅盛。症见耳掀痒、唇燥舌干、咳吐浓痰，原文断为“胃中痰火流入肺经，郁积久而生热生风”，右洪滑正应胃中痰火，左浮弦应风热上攻之机。", ["浮", "弦", "洪", "滑"]], "6317": ["病机", "右关洪滑主胃中痰积，左手涩主血行不畅、瘀血内停，故症见咳逆倚息、胸胀、便下紫黑血。原文谓“胃中有瘀血痰积，而肺气亦虚”，涩脉与瘀血相应，洪滑与痰积相应，先补后泻即据此脉症而定。", ["洪", "滑", "涩"]], "6318": ["病机", "脉虽五至而不甚充指，五至近数，不充指为虚，主血虚有热而气亦滞。小产后阴血亏虚，湿热留于气分，故口渴、脐下痛、小便频数滴滴不断、精神甚惫。原文断为“血虚有热，而气亦滞”，脉虚数正合此机。", ["数"]], "6319": ["病机", "两手寸关洪滑，两尺沉伏，洪滑主痰饮食积壅于中焦，沉伏主积滞内结、阳气不达。症见五更倒饱、必泻一次、腹胀间痛，原文断为“肠胃中有食积痰饮”，寸关洪滑应积滞在中，尺沉伏应下焦气机不畅。", ["洪", "滑", "沉", "伏"]], "6320": ["病机", "左脉弦数，右关洪滑。弦主肝胆，数主热，洪滑主痰火。患者经行后热入血室，误服刚燥之剂，动痰火，致胸胁大腹疼、谵语如狂、鼻衄、自悲自哭等症。脉象反映热入血室、痰火内扰之病机，与原文“热入血室症”相应。", ["弦", "数", "洪", "滑"]], "6321": ["病机", "六部沉微，左尤甚，隐隐如珠丝之细。沉主里，微主阳虚，细主虚。患者肠风去血过服寒凉，伤脾胃，脾泄不愈，面黄浮肿，四肢冷，口不渴。脉沉微与面色黄肿皆属湿，由脾虚不运积湿而然，虚寒明矣。脉症合参，主脾肾阳虚、湿浊内停之病机。", ["沉", "微", "细"]], "6322": ["主病", "右脉滑大，左细弱。滑大主痰热壅肺，细弱主体虚。患者体素弱，患喘嗽，夜分气壅不能仰卧，咳嗽连连，痰不易出。脉象示痰热壅肺兼气阴不足，故以人参平肺散加减，补气清肺化痰而愈。", ["滑", "大", "细", "弱"]], "6323": ["病机", "脉沉滑而数，沉主里，滑主痰，数主热，示痰热内积。患者脊骨痛牵引胸腹，舌苔黄厚，为痰积下行欲去不能。下后脉转软弱，示邪去正虚。脉象反映痰热积滞之病机，与腹痛、苔黄等症相应。", ["沉", "滑", "数", "软"]], "6324": ["病机", "六脉皆弦而弱。弦主痛、主肝，弱主虚。患者因内伤外感过服发散消导，致胃脘当心而痛。脉弦弱示中气虚弱、肝木乘脾，故法当补而敛之，用芍药甘草汤加桂枝、饴糖等，一帖而瘳。脉象主虚寒腹痛之病机。", ["弦", "弱"]], "6325": ["病机", "两寸短弱，关弦，尺洪滑。寸短弱主气虚，关弦主肝郁，尺洪滑主下焦湿热。患者肛上肿毒溃后出血不止，便结胸胀，脉示气虚血热陷于下部。法宜补而升提，否则痔漏将作。脉象反映气虚下陷、湿热下注之病机。", ["短", "弱", "弦", "洪"]], "6326": ["病机", "左寸涩，右寸滑，按之如黄豆大且鼓指，关尺皆弦小。涩主痰滞，滑主痰，弦小主郁。患者食后即大便，腹皮胀急，胸膈饱闷，脉示积痰郁滞于肺，致大便之气不固。法当吐去上焦痰积，则大便自实。脉象主痰积郁滞之病机。", ["涩", "滑", "弦", "小"]], "6327": ["病机", "左寸滑，余五部皆濡弱。滑主痰，濡弱主气虚阳衰。患者夜多泄泻，小腹痛，口不渴，小便长，半年不愈。脉示阳气大虚，虚中有寒。治当温补下元兼升举，服后右脉稍起。脉象反映脾肾阳虚、虚寒内盛之病机。", ["滑", "濡", "弱"]], "6328": ["病机", "右手脉浮滑，左平，浮主表分肌腠，滑主痰湿内盛。年近七十，右手疼不能上头，医作痛风不效而反口渴烦躁，知非外风，乃湿痰久郁化热，热极生风，风痰流窜经络所致。故以二陈汤化痰为主，倍威灵仙、僵蚕、秦艽流动经络，酒芩清热，痰热去则风自息而痛止。", ["浮", "滑"]], "6329": ["病机", "原文据脉言「汗后浮数，热尚不减」，浮为邪在表分未尽，数为热盛，汗后而脉仍浮数，是疫邪郁于肌表、热势未衰之象。故见发热头疼、口渴、小便赤、大便泻、日夜不睡，皆疫热充斥三焦之候。以滑石、青蒿、葛根、片芩等清透疫热，一帖即睡而热减，后以四物加味养血收功。", ["浮", "数"]], "6330": ["病机", "六脉弦而数，弦主邪郁少阳、气机不畅，数主热盛。身如火烁、头痛如破、口渴鼻干、不得眠、胸膈膨胀，皆疫热炽盛、郁于少阳阳明之候；腹饥不能食，是热伤胃气。故用竹叶石膏汤加知母、青蒿等清解疫热，热退后现头晕脚软，为病后血虚，转以四物汤调养。", ["弦", "数"]], "6331": ["病机", "左脉弦数，右脉滑数。弦数为阴虚内热，滑为痰湿内蕴。咳嗽、内热、额上多汗、恶风，乃阴虚火旺兼痰之候，故断为「据弦数为阴虚，滑为有痰」，不亟调治恐成虚怯。用归、芍、麦冬、知母滋阴，贝母、花粉、桑皮化痰，标本兼顾。七月复疟寒热渴甚，是转属疟邪，另以石膏、柴胡、桂枝等和解清热。", ["弦", "数", "滑"]], "6332": ["病机", "右寸洪而有力，为肺经有热；左寸虚，为心血不足；右尺沉微，为命门火衰。心火不能下交于肾，肾水不能上济于心，故小水不禁、一日二十余起，是心肾不交、膀胱失约之症。方以当归、远志、丹参养心安神，桑螵蛸、益智仁固脬，黄柏、知母清下焦，人参、山茱萸补虚，使水火既济。", ["洪", "虚", "沉", "微"]], "6333": ["病机", "两寸关滑数，滑主痰湿食积，数主郁热；两尺沉微，为脾肾阳气不足。腹有藟块、腹冷甚，是脾气虚弱、饮食不消，又逢秋令湿淫，故断「不利亦泻」而预为防范。服健脾渗湿药后泻果作，脉转软弱不滑，藟块亦消，说明湿滞渐化，遂改以参、芪、术、芍补中兼消兼利收功。", ["滑", "数", "沉", "微"]], "6334": ["病机", "两寸皆数，为心肺有热；两关弦而无力，弦主肝郁、无力为脾胃虚弱；两尺洪滑，左尤甚，为下焦湿热壅盛。合观大便燥结、数日不行而痛苦殊甚，是胃寒肠热、肠胃相兼之症。故用药专以肠风脏毒之药为君，外裹养血之剂使不伤胃气，取「寒非凄凄，热非灼灼」之缓调法。", ["数", "弦", "洪", "滑"]], "6335": ["病机", "右寸关皆滑，滑主痰湿，知肺胃有痰；左寸短弱，短弱为心血不足之象。劳倦伤脾，脾运失健则生痰，痰阻膈上故早晨痞闷恶心；心血不足故食热物则目中出泪。此心血不足而肺胃有痰之候，故以六君子汤健脾化痰为主，加麦芽、白豆仁、旋覆花消痞降逆，标本兼治而愈。", ["滑", "短", "弱"]], "6336": ["病机", "两寸俱滑数，滑主痰，数主热，寸部候上焦胸膈。原文见唇燥、胸中冲跳不已，乃痰热结于胸膈，气机壅滞而冲逆；手足皆冷是痰热内闭、阳气不达四末。故断为奇痰症，以小陷胸汤加味清热涤痰，下蛔虫后寸脉减半，正合痰热渐去之机。", ["滑", "数"]], "6337": ["病机", "右寸软弱、关滑，左脉弦长直上鱼际，两尺皆弱，原文断为亢而不下之脉，即木行乘金。弦长主肝木亢盛，滑主痰火，右寸软弱为肺金受乘，尺弱示下元不足。诸风掉眩皆属肝木，故眩晕、肢节作胀，治当养金平木、培土化痰。", ["弦", "长", "滑", "弱"]], "6338": ["病机", "六脉俱濡弱而汗大出，濡弱主正气亏虚，汗大出更耗气阴。原文断为正虚，或由克伐太过所致，故见大便作泻、身热、耳壅、眩晕、胸膈不宽、口渴痰多咳嗽，皆脾肺气虚、清阳不升、痰湿内停之候，治以补养为先，用参术芍草健脾益气。", ["濡", "弱"]], "6339": ["病机", "左手沉而弦数，沉弦主积气，数主积热；右手滑主痰饮；关脉濡弱示脾气不充。两胁痛上壅至胸、发热、饮食不进，乃怒气触发的积热痰气壅阻肝络。原文先去积热、消痰气，后用当归龙荟丸刈根，正合脉症。", ["沉", "弦", "数", "濡"]], "6340": ["病机", "脉大小不一，乍大乍小，是虫扰气机、脉道忽张忽敛之象。原文以心痛、唇红、痛则大发热、头疼、少顷出汗，断为虫痛，并以痛吐白沫为征。虫动则气逆攻冲故痛剧发热，虫静则暂缓，脉无定体，故大小不一，用槟榔乌梅椒姜杀虫安蛔而痛除。", ["大", "小"]], "6341": ["病机", "右寸极软弱，左近驶，右寸候肺主气，软弱为气虚；左近驶乃血热妄行之象。原文断为气虚血热之候，由气虚而血不固，故行经如崩、势不可遏，兼头晕眼花。仲景云血脱益气，故重用人参黄芪白术补气摄血，佐荆芥蒲黄侧柏姜炭止血。", ["软", "弱"]], "6342": ["病机", "六部皆软弱无力，为脾气大虚之脉。原文因服痔科凉血药过多，致脾虚不能统血，故痔血、里急后重、食入即行、五更咳嗽痰响、肌肉脱、口渴，皆脾虚失运、气血不摄之候。治以四君子汤加荆芥秦艽陈皮炮姜，健脾统血而血止嗽定。", ["软", "弱"]], "6343": ["病机", "左弦大、右滑大搏指，弦大主肝胆火郁，滑大搏指主痰凝气壅。原文据脉断为肝胆之火为痰所凝，因过思不决、木火不得通达，郁而为痛，夜甚者肝邪实也。误作疟治燥动其火，误补参术闭塞其气，致舌苔沉香色、热极，故急以小陷胸汤通降痰火。", ["弦", "大", "滑"]], "6344": ["病机", "六脉皆涩，涩主气血滞涩、营卫不和。症见恶风发热、遍身疼痛、汗大出不止，乃外邪束表、营卫壅滞，汗出过多则津伤血涩，故脉道不利而涩；口中热、腹中不知饿、小水短，又示里有郁热、气化不畅。涩脉在此非单纯虚候，而是邪滞兼津伤之象，故用白芍、白术、桂皮、黄芩调和营卫、清热和中而效。", ["涩"]], "6345": ["妇人", "妊已四月，右关滑为痰湿内盛之象，左寸微弱示心血不足，两手皆数则内有热。夜不能睡、小便淋痛、痰嗽内热，正合痰热扰心、下迫膀胱、上犯肺金。滑脉主痰，数脉主热，弱脉示胎元需养而心气不足。故以橘红、贝母、芩、连清化痰热，茯苓、泽泻利湿，苏梗、前胡宣肺，热清痰化则安寝。", ["滑", "弱", "数"]], "6346": ["病机", "两寸脉短弱，短主气损，弱主气虚，两手皆数而无力则为虚热。原文明言“此劳倦之余，故汗大走也”，劳倦伤气，气虚不能固表，故汗大出、发热、昏昏如醉、卧不能起；遍身痛亦因气虚营卫不充。数而无力非实火，乃虚阳外浮。故用黄芪、白芍、甘草、桂枝益气固表、调和营卫，一帖而热除汗止痛止。", ["短", "弱", "数"]], "6347": ["病机", "两寸俱洪滑而数，洪为有余，滑主痰，数主热，寸脉候上焦胸膈。症见胸胁作痛、夜分发热、素多痰火，正合湿痰凝滞、痰火壅于胸膈。前医以四物、天麦冬、独参补塞太重，致痰湿愈滞，故迁延不脱。洪滑数乃实痰实火之候，非虚损，故用二陈加苍术、黄柏、威灵仙等化痰除湿、清火通络而足能举步。", ["洪", "滑", "数"]], "6348": ["预后", "右手软弱，左手散乱，散为脉不敛、元气外泄之象。症见汗出如雨、肌肉大瘦、饮食减少，汗多则津气两脱，脉道不能收摄，故左脉散乱。原文叹“此汗多而脉不敛，病势至此，危之甚矣”，属火热似疟而气阴将竭之危候。用黄芪、白芍、阿胶、鳖甲、乌梅益气敛阴固脱，汗止而左脉已敛，神气乃回，示脉敛则生机复。", ["软", "散", "数"]], "6349": ["病机", "左寸洪大，右寸关皆滑，两手尽数，洪大为阳盛有余，滑主痰，数主热。症见咯血色紫、胃中痰火素盛、壅于胸膈作痞作疼，痰与瘀血挟而为热，正合洪滑数之实候。原文断为“此有余之候”，非虚损出血，故用总管丸及滑石、桃仁、红花、丹皮、茅根等清化痰火、凉血化瘀，便行痰积瘀血而安。", ["洪", "大", "滑", "数"]], "6350": ["病机", "左寸脉短，短主心血不足；关弦、右关滑、两尺亦弦，弦主气滞痰凝，滑主痰。原文谓“心血不足，中焦有痰，流于下部，凝于经络”，故见腰膝酸疼、背心作胀、头多眩晕、夜睡多汗。前医误投风剂，反伤正气。弦滑非外风，乃痰滞经络之象，故以陈皮、白芍、木瓜、牛膝、苡仁、黄柏等化痰通络、养血清热而诸症悉愈。", ["短", "弦", "滑"]], "6351": ["预后", "右关滑大，滑主痰，大主邪盛，右关候脾胃。症见咳嗽多痰、面青、潮热、肌瘦、性躁，又新婚饮食不节，粪门发瘘疮溃流脓血。原文断为“阳病极而下也，法在不治”，谓痰火壅盛于中焦脾胃，下注肛门成瘘，余部无神气则胃气已败，滑大而失和缓乃邪盛正衰之候，故预后凶险，果不逾月而亡。", ["滑", "大"]], "6352": ["病机", "右脉豁大近芤，为血脱而虚阳外浮之象；左濡弱，示血海空虚。小产后血大下、白沫如注，脾虚不能统血，故面浮食少、五更泄泻；虚中夹瘀，新血不归源，稍动气即崩。脉证合参，属大虚之候，急宜温补脾阳以摄血。", ["芤", "濡", "弱"]], "6353": ["主病", "两寸皆短，上焦气机不畅；两关滑大、右关搏指，为痰气交阻中焦之象。喉中梗梗如炙脔、吞之不下吐之不出，正是梅核气症。痰阻气逆则鼻塞头晕、耳不安，气不达表则汗出如雨、见风身疼。脉滑大搏指，主痰盛气滞，故用半夏厚朴汤化痰降气。", ["短", "滑", "大"]], "6354": ["病机", "两寸俱短弱，寸主上焦，短弱为元气大虚之征。妊已七月，因惊胎动不安、血下、二便急、腰腹胀疼，皆上焦元气虚不能固摄胎元所致。脉证相应，故当骤补元气，参芪术以固胎，阿胶归芍以养血，佐条芩杜仲安胎止痛。", ["短", "弱"]], "6355": ["病机", "六脉俱弦数，弦为少阳主脉，数为热，合胸胁痛、耳聋、哕逆口苦、咳嗽，显系少阳症。劳倦后勉强色欲，精竭血继，复感风寒，邪从太阳传入少阳。弦数并见，主邪郁少阳、胆热内蒸，故用小柴胡汤和解，加枳桔竹茹以清降。", ["弦", "数"]], "6356": ["病机", "两寸短弱，上焦气不足；关滑、两尺沉滑有力，为湿痰蕴积中焦、流注下焦之象。食积痰饮作痞，大便了而不了、间或作胀，皆湿痰蕴热、清浊升降失司所致。脉滑主痰，沉滑有力主积滞，故治以清中宫、升清降浊，不补而补。", ["短", "弱", "滑"]], "6357": ["病机", "六脉俱涩，涩主气滞血少、痰饮内阻。头晕且痛、起则倒仆、胸膈胀闷如绳束缚、呕吐食不得入，乃痰饮挟木火之势上逆作晕。脉涩与痰饮阻滞、气血不畅相应，故先涌吐痰涎，继以清火降逆、引火下行，使痰火去而晕吐止。", ["涩"]], "6358": ["病机", "脉洪大，为阳明热盛之象。发热头痛、口渴、大便秘结三日未行，正是阳明少阳二经热结。洪大主热盛于经，故用大柴胡汤通下黑粪，继以白虎汤清阳明余热。后因食复、受寒，热退而神思大瘁、四肢皆冷，乃热病后气阴两伤，脉转虚而当补。", ["洪", "大"]], "6359": ["病机", "脉近虚，虚而当补，然此案难产伤力、悲戚晕厥后，恶露绝无，神昏瘛疭、目上视，乃瘀血上冲、痰粥壅塞膈上所致。女医误投人参、独参汤并粥，壅塞不通，脉虚非纯虚，实为瘀痰内闭、正气受困。探吐痰饮粥药盈盆而瘛疭定，证明脉虚不可骤补，当先通降。", ["虚"]], "6360": ["病机", "左脉弦数为疟后余邪未清、肝木乘脾，右寸弱关大重则滑为食积痰滞内阻、脾运失职，右尺微示下焦元气不足。弦数主热主痛，滑主积滞，故见大便泻而变痢、积滞无粪、腹疼后重、午未后发热，皆夏伤于暑秋为疟痢、余邪与食积交争之象。", ["弦", "数", "弱", "滑"]], "6361": ["病机", "孕三月而疟发，先寒后热、胸膈胀疼、口渴、汤水入即吐、谵语无汗、胎气上冲成子悬，脉皆弦大。弦为肝木亢盛、疟邪郁于少阳，大为邪热壅盛、气机上逆，故胎气随冲脉上逼而胀疼呕逆，弦大之脉正合邪实气逆、胎气上冲之病机。", ["弦", "大"]], "6362": ["妇人", "左寸关短弱、右关濡弱示心脾气血大虚，两尺滑、右寸滑为痰湿内蕴，尺沉微为肾气不足。原文以左寸短弱断其难孕，而夫人已孕七十日，且前二胎九个月产下无水火、无舌，正合心脾不足、胎元不充之机，短弱濡微皆主气血虚衰、胎失所养。", ["短", "弱", "滑", "濡"]], "6363": ["误治", "本段叙眼目红痛屡经寒凉温补误治，致目肿如桃、绝不能开，又议大下。左寸脉甚短，短主气血不足、心阳不振，目为心使，过用寒凉冰血、温补助热、峻下伤正，脉短正示正气已伤而邪热未解，故诸治不效、饮食日减、恶心畏风。", ["短"]], "6364": ["病机", "六部俱弦、重按稍𫘝，弦主筋脉拘急、肝风内动，𫘝为热象，合之乃寒热退后筋骨疼不减、指掉不能屈伸、臂肉瘦削，属热邪久羁、耗伤阴血、筋脉失养而动风。诸医皆作风治不效，正因脉弦非外风，乃内伤筋脉之候。", ["弦", "𫘝"]], "6365": ["病机", "六部大而无力，即“脉至而从，按之不鼓”，大而无力为阳气浮越于外、下焦真阳衰微，不能蒸化水液，故下消小便清白而长、味甜凝结如脂、腰膝软弱、神色大瘁。此非实热消症，乃肾阳虚衰、气不固摄之候，法当温补下焦。", ["大"]], "6366": ["病机", "原文未识脉名，仅言“因痛而脉多不应指”，痛甚气机郁滞、脉气不畅故不应指。每动怒则夜卧不安如见鬼魅、小水淋沥、大便秘结、腹中疼痛、腰胯胀坠如生产状，皆肝经郁火、气滞不通所致，法当通利，便通则痛胀随减。", []], "6367": ["病机", "两寸浮滑为痰热上壅、清阳不升，故次日头痛如箍、遍身亦疼；两尺弱为下元虚衰，脐腹疼极需炒盐熨之乃下焦虚寒。原文断为“上盛下虚症”，浮滑应上盛之痰，弱应下虚之本，先清上痰后温补下元，正合此病机。", ["浮", "滑", "弱"]], "6368": ["预后", "产后脉洪大，且六脉乱而无绪，为脉证相反之逆。新产气血大虚，脉宜缓弱，今反洪大，是邪热亢盛、正气溃散之象；六脉乱而无绪，乃胃气衰败、阴阳离决之兆。原文谓“汗出如油，喘而不休，死症也”，又“汗出而热不退，泻而热不止，且谵语神昏”，脉洪大与危候并见，故断为逆证难治。", ["洪", "大", "乱"]], "6369": ["病机", "左弦细、右滑大，俱六至。弦细为疟后气血不足、经络余毒伏留；滑大为痰火湿热内蕴。原文谓“昔患杨梅疮，余毒尚伏经络，适因疟后气血不足，旧毒感动，故痛而暴也”，脉象与腰痛白浊、咳嗽肌消相应，示正虚邪伏、毒热攻冲之病机。", ["弦", "细", "滑", "大"]], "6370": ["病机", "两手脉浮而洪，两关滑大有力。浮洪为风邪外闭、热盛于内；关部滑大有力，主中焦痰火积热壅实。原文谓“内有积热痰火，为风邪所闭，且为怒气所加，故血上逆”，脉与咳血、鼻流清水、舌生芒刺、喘急不能卧相应，属有余实症，非阴虚火旺。", ["浮", "洪", "滑", "大"]], "6371": ["其他", "本段未载脉象，述中焦湿热生痰之证治。痞闷、五更倒饱、膝下筋脉抽掣疼痛、嗳气、面黄、梦遗，皆湿热痰浊中阻、流注下焦所致。清气大安化痰丸清化痰热，猪肚丸健脾去湿热、固精，方证相合，故调治而安。", []], "6372": ["其他", "本段未录脉象，论虚损咳嗽与痛风之治。蜃楼咳嗽昼轻夜重，由肺火未清、误服参术太过，故以清肺利肺取效；丁氏肥而性躁，痛风肿痛呻吟，属湿热痰火流注经络。原文强调“令弟之症，虽易见功，然非百日不能断根”，示虚实夹杂、治需分途。", []], "6373": ["病机", "右寸关脉洪滑，左脉弦。洪滑主痰热食积壅于中焦，弦为气郁。原文断为“气郁食积痢也”，症见小腹窘迫、胸膈膨胀、口舌焦渴，脉症相合。先以木香槟榔丸开下，继因吐痰涎用温胆汤加减，脉象示气郁食积化热、痰阻胸膈之病机。", ["洪", "滑", "弦"]], "6374": ["病机", "昨日六脉俱伏，今早六部俱见，惟左寸短涩。六脉俱伏为气机闭阻、痛极气逆；左寸短涩，寸主胸中，短涩为血行不畅，故“知其痛为瘀血也”。原文述胸喉有物作梗而痛、汤水难入、晕厥，脉象由伏转见而左寸短涩，示瘀血内阻、气机不通之病机。", ["伏", "短", "涩"]], "6375": ["妇人", "右手脉弦，左脉滑，孕妇暑月患痢。弦为气滞，滑为湿热壅盛，亦主孕脉。原文谓“孕已二月，幸而腰不痛”，示胎元未伤。药后右弦减半，六脉已和但软弱，软弱为气血不足，故“宜从补养”，以八珍汤加味保胎，体现孕妇痢疾以补养气血、调气安胎为要。", ["弦", "滑", "软"]], "6376": ["病机", "左脉细数，细为阴亏，数为虚热，合下午发热、梦遗后痢，显系阴虚之候；右脉滑主食积，故先补后攻。后六部虚软无力独右关滑，虚软为脾虚，右关滑为食积未化，故补后攻积。", ["细", "数", "滑"]], "6377": ["病机", "左脉浮弦而数，浮为风邪外感，弦为疟痢之象，数为热；右软弱而中部稍滑，软弱为内伤饮食，滑为积滞。合之乃内伤饮食、外感风邪，疟痢并作，故先柴苓汤解表利湿，后以败毒散、补中益气汤调之。", ["浮", "弦", "数", "滑"]], "6378": ["病机", "两寸洪大有力，左浮弦而数，右稍软亦弦长，洪大为阳明热盛，浮弦数为少阳风热，右软弦长为木克土。此少阳与阳明合并为疟，故用柴葛解肌汤双解两经，后以鳖血何首乌丸截疟。", ["洪", "大", "弦", "数"]], "6379": ["病机", "两寸短，左寸尤甚，余部滑数。寸短为心气大弱，心藏神，神弱不能固摄其精，故梦遗不禁；滑数为兼注夏之湿热。诸症丛集，法当养心安神，若滋阴降火则损脾减食，故以人参、黄芪、石莲子等补心固精。", ["短", "滑", "数"]], "6380": ["病机", "六脉皆洪数，洪为热盛，数为火炽，合腹痛两月、面色苍黑、皮肤燥若老松树皮，显系热毒壅滞、气血瘀阻之实证。前医误作寒热虚实杂治，反致痛剧，洪数脉示邪热内蕴，非虚寒可比。", ["洪", "数"]], "6381": ["病机", "六部濡弱，濡为湿滞，弱为气虚，合下紫黑稠黏、色晦如芋苗汁，非痢乃脏毒下血。濡弱示脾虚湿盛、血失统摄，故以人参樗皮散补气涩血，终剂全愈。", ["濡", "弱"]], "6382": ["病机", "原文未识脉名，然述冲暑发热燥渴，过食水浸瓜梨新藕成泄泻，小水短少，医利之泻止而便结，润之复泻，再利之小水竟不得流通，脐下胀急，立解点滴不出，卧则流之不竭。此系过利伤津、气化失司，水湿内停之癃闭，非纯实可下。", []], "6383": ["病机", "左弦数，右滑数。滑为痰，弦为风，数为热，合右胁痛、手足筋骨痛艰于举动，乃湿痰风热为痹。湿生痰，痰生热，热壅经络，伤营卫变为风，故以二陈汤加钩藤、苍耳子等化痰通络。", ["弦", "数", "滑"]], "6384": ["病机", "两寸滑大、左关弦、右关滑、两尺皆弦且七至，滑主痰，弦主少阳，数主热，大示邪盛。脉象反映少阳阳明合病，痰热内扰，故见寒热、烦躁、耳聋、懊𢙐、谵语等症。", ["滑", "大", "弦", "数"]], "6385": ["病机", "左脉沉细，右寸滑，关尺濡弱。沉细主下焦阴伤，滑主上焦痰火，濡弱示湿热伤络。脉象说明上焦痰火、下焦湿热，故行动即热、发渴呕恶、腰与环跳常痛。", ["沉", "细", "滑", "濡弱"]], "6386": ["病机", "左寸芤、关涩、尺弱，右寸短、关滑。芤主失血，涩主血少，弱主气虚，短主气损，滑主痰火。脉象示胃中痰火旺而气血俱虚，故咳嗽咯血、不思饮食、左胁气不调。", ["芤", "涩", "弱", "短"]], "6387": ["病机", "六脉皆数，左滑，右软弱。数主热，滑主痰，软弱主脾虚。脉象示上焦热、下焦寒，痰热中阻，脾胃虚弱，故食入即痛吐、吐酸、便结，久则恐成膈症。", ["数", "滑", "软弱"]], "6388": ["病机", "脉沉弦而数。沉主里，弦主痛主风，数主热。脉象说明痰火上壅，变生风热，将欲作毒，故喉痛颊车肿、两太阳胀疼、遍身胀痛、憎寒发热。", ["沉", "弦", "数"]], "6389": ["病机", "二寸皆短弱，关尺洪数。短弱主肺气不足，洪数主火盛。脉象示胃中痰火与下焦阴火并炽，因壮年酒色所伤，故辛苦酒多则咯血。", ["短", "弱", "洪", "数"]], "6390": ["病机", "左脉浮数，右濡弱，两手七至。浮数主表热，濡弱主湿，数主热。脉象示湿热交蒸发黄，故发热口渴、目黄肤黄、小便赤、舌黄苔、夜不得卧。", ["浮", "数", "濡弱"]], "6391": ["病机", "左脉弦大，右脉虚大。弦大主肝火亢盛，虚大主暑伤气阴。脉象示作文劳心、怒伤肝、暑伤气，痰火上逆迫血妄行，故大吐痰沫、哕血、昏晕汗出。", ["大", "虚", "弦"]], "6392": ["病机", "脉浮洪滑数，浮为热邪在表，洪为热盛，滑为痰瘀，数为热象。患者咳嗽吐臭脓血，发热夜重，肌肉大瘦，此热毒瘀痰壅滞肺窍，化腐成痈。脉大非呕血之虚证，乃肺痈实热之征，故主开肺窍、活血化痰。", ["浮", "洪", "滑", "数"]], "6393": ["病机", "脉俱洪数，洪为热盛，数为热急，此湿热下注膀胱，灼伤血络，故小便血淋疼痛，尿出大血块。前用通利清热不应，因瘀热胶结，故以五灵脂、蒲黄活血散瘀，佐以清热通淋，二帖痛减。", ["洪", "数"]], "6394": ["病机", "脉洪数，洪为阳热亢盛，数为热迫血行。吐红发热，经水频行，白带多，胸膈饱胀，此血热妄行兼湿热下注。洪数之脉主内热炽盛，故以清热凉血、固经止带为治，二十剂而瘳。", ["洪", "数"]], "6395": ["病机", "脉弦大而无力，弦为肝郁，大为虚象，无力为气弱。眼红肿痛，误用苦寒更增太阳痛、遍身胀闷，此肝郁脾虚、清阳不升。弦大无力非实热，乃郁而兼虚，故用疏肝理气、升清降浊而愈。", ["弦", "大"]], "6396": ["病机", "脉两手滑数，右尺软弱。滑主湿，数主热，软弱为湿伤筋脉。右背一点痛，手臂肢节胀痛，筋暴起，生红点，此湿热伤筋而成痛痹。滑数示湿热内蕴，右尺弱示下焦不足，故以舒经汤清热除湿、活血通络。", ["滑", "数", "弱"]], "6397": ["病机", "两寸脉洪大，洪大为热盛于上焦。患血痢里急后重，呕吐不纳谷，此湿热蕴结大肠，热邪上逆犯胃。寸脉洪大主膈上有热，故用竹茹温胆汤加姜连、滑石等清上焦热、降逆止呕，使热清痢止。", ["洪", "大"]], "6398": ["病机", "左脉沉伏，右滑大有力。沉伏为气闭于内，滑大为痰热壅盛。脐腹右痛，二便不通，呕吐不食，面青手冷，此痰格中焦、气闭下焦。右滑大主痰热实邪，左沉伏主气机郁滞，故急以豁痰通闭，后脉起而愈。", ["沉", "伏", "滑", "大"]], "6399": ["病机", "脉仅四至，迟而无力，面青声不扬，四肢冷，胃脘痛极，吐不化西瓜，此寒湿内盛、蛔虫内扰之霍乱蛔厥。脉迟主寒，四至为阳气不振，误用寒凉更伤中阳，故以温中安蛔止痛为急。", []], "6400": ["病机", "左手甚弱因汗多不止，汗为心液，过汗则心气营阴俱伤，故脉弱；右手滑大乃痰饮湿热内蕴之象，滑主痰，大主热。肢节肿痛、痰多呕恶、胸中气不畅达、语言不清，皆痰湿阻滞、气机不利所致；梦亡人野鬼、精神惨恶惊恐，为心神失养、痰浊扰心。前医作风治疏散，更泄元神，故脉弱汗多，将成柔痓。", ["弱", "滑", "大"]], "6401": ["病机", "六脉俱弦数，弦为肝木之象，数主热。忧伤肺则气结，思伤脾则运化失职，木郁化火，火刑肺金，故咳嗽声哑、喉痛；脾失健运则大便溏泻、饮食减少、肌肉大削。弦数并见，示肝郁化火、脾肺两伤，本虚标实，故原文叹为危急甚矣。", ["弦", "数"]], "6402": ["病机", "六脉俱数主热，左寸滑大示心火偏旺、血热妄行，故孕五月而血大下；右关搏指为胃火搏结，左关软弱乃肝血不足。午后发战、寒热、头痛恶心、腹中块硬，皆血虚夹热、冲任不固之候。数而软弱并见，虚火无疑，故以补中益气加阿胶、炮姜补敛止血。", ["数", "滑", "大", "弱"]], "6403": ["病机", "两寸洪大，寸候上焦，洪大为热盛气壅，故两胁胀急抵胃作痛、颧唇俱红、饮入立吐；两尺沉微，尺候下焦，沉微为下元虚寒。上热下寒，热壅于上而阳衰于下，故以阴阳汤调玄明粉泻热，继以温中杀虫之品，唇脸红、吐甚示虫扰之象。", ["洪", "大", "沉", "微"]], "6404": ["病机", "脉右大于左者三倍且数，右主气分，大数为邪热壅盛于气分；产后子死忧闷，气滞血瘀，小腹块痛、午后发热。继而脉大无绪，是无胃气之象，邪实正虚，气血紊乱，故鼻衄、极热口渴、腹大如斗坚如石、气促不安，势甚危急，示瘀热内结、正气将溃。", ["大", "数"]], "6405": ["病机", "左脉弦为肝木偏旺，右脉滑主痰，两寸稍短示上焦气机不畅。梦魇惊厥、精神恍惚、咳嗽面青、不思谷食，乃痰浊蒙蔽心神、肝风内动之候。前医作寒痰用附子肉桂，厥反加，知非纯寒。弦滑并见，痰火夹惊，且先眷皆卒于瘵，虑为传尸瘵症，故权以补养化痰消息。", ["弦", "滑", "短"]], "6406": ["病机", "脉弦涩有力，弦主痛主饮，涩主血滞，有力为实。受寒后筋骨疼痛、骨节红肿，乃湿热痰火为寒气凝滞、固涩经络，气血壅遏不通，故脉弦涩有力。前医或补或温或祛风利湿，皆未中病，致大肉尽消而骨节肿大。此实邪闭阻，非虚非纯寒，故取精神尚在、胃气未损为可治之机。", ["弦", "涩", "有", "力"]], "6407": ["病机", "六部俱豁大无力，大而无根、按之无力，是正气大虚、脾胃元气耗败之象。连日过劳伤气，又误进寒凉十一日，口疮日甚、延及于喉、饮食药饵难下，皆寒凉戕伐中阳、虚火上浮所致。脉豁大无力正示虚阳外浮而非实热，故稠涎毒甚，鸡啄立毙，乃毒火夹虚，攻补皆难。", ["大", "无", "力"]], "6408": ["兼症", "脉左滑数，右寸弱，关滑，左尺有力，右尺弱。左滑数为痰热内蕴，右寸弱为肺气不足，关滑为痰湿中阻，左尺有力为热在下焦，右尺弱为肾气不足。妊妇伤风咳嗽，痰壅喉音不清，头眩运，腹中吊疼，乃痰热上扰，肺失宣降，兼脾肾不足。故以人参、白术补气，黄芩、贝母清热化痰，茯苓、陈皮健脾化痰，桑白皮、紫苏、前胡宣肺止咳。", ["滑", "数"]], "6409": ["病机", "六脉俱浮大，按之豁然空虚，此中气大虚，元神俱脱之候。浮大而空为虚阳外越，脾胃败坏，故膝跟踝皆浮肿，遍身发热口渴，小水短赤，舌上黄胎焦煤，误服寒凉致大便连泻，目不能开，手足无力，倦于言语。脉证合参，乃脾胃虚极，元气欲脱，故以人参、白术、茯苓、甘草补中，木香、葛根、白芍调理而愈。", ["浮", "大", "虚"]], "6410": ["病机", "两关滑大有力，尽寸俱不足。关脉滑大为湿热积滞中焦，气血壅阻，故腹痛下痢，里急后重；寸脉不足为肺气不足，表虚易感风邪。原有肠风下血，又感风邪发热，湿热夹瘀，故以白芍止痛，当归活血，酒连、酒芩、柴胡、桔梗清热升提，枳壳、槐花治肠风，益元散、木香实大肠，山楂消瘀。", ["滑", "大"]], "6411": ["病机", "左关脉弦大鼓指，弦为肝郁气滞，大为邪盛，鼓指为气机壅塞。脐腹腰俞俱胀痛，偏坠，乃肝经气滞，寒湿下注。服温散药后痛如旧，脉转数，恐作囊痈，急为解毒。弦脉尽退后因食鸡鱼太早，脐腹又胀痛发热，弦脉复现，示肝郁气滞复作，故以山楂、栝蒌、金银花、连翘等解毒消滞而愈。", ["弦", "大", "数"]], "6412": ["病机", "两寸洪大，洪大为热盛，寸脉主上焦，肺热上壅，故鼻渊流清涕不止，头晕，两太阳常作痛，多喷嚏。表虚易感风寒，入里化热，肺热上蒸，故以秦艽、酒芩、桑白皮、马兜铃清肺热，滑石、石膏清热，枳壳、蔓荆子疏风止痛，白芍和营，甘草调和。", ["洪", "大"]], "6413": ["病机", "脉左涩右滑。左涩为肝血瘀滞，右滑为痰湿内盛。腹中胀满，呕哕不宁，眼珠面色皆黄，恶寒发热，五心加热，下午潮热烦躁，鼻衄腹痛，大便黑如墨，吐出黑血如烂猪肺，乃瘀血内阻，湿热熏蒸，肝脾失调。涩主瘀，滑主痰湿，瘀血与湿热互结，故见黄疸、出血、腹胀等症。", ["涩", "滑"]], "6414": ["病机", "左脉绝不应指，虚极故也。小产后腹痛晕厥，冷汗淋淋，遍身麻木，心怔怔动，乃血脱气陷，元气虚极，脉道不充，故左脉绝不应指。以当归、川芎、人参、荆芥穗炭、益母草、泽兰叶、甘草养血益气，化瘀止血。腹痛减后怔怔不宁，以四君子汤倍黄耆补气，当归、香附、益母草调血，川芎为佐，炮姜为使，两剂而安。", []], "6415": ["病机", "左弦长，右洪大，俱七至。弦长为少阳邪盛，洪大为阳明热盛，七至为热盛脉数。舌苔焦黄，体若火燎，神昏气促，咳嗽胸痞，躁闷不宁，乃伤寒热症，邪在阳明少阳二经。前医误以梦遗为虚，投补剂致热愈炽，汗泻愈剧。脉证合参，邪热内传，气分热盛，故当清热泻火，和解少阳。", ["弦", "长", "洪", "大"]], "6416": ["病机", "脉濡而数，濡主湿、数主热，合为湿热内蕴之象。原文见遍身皆黄、尿如柏汁、汗出沾衣如染，乃酒湿化热、熏蒸肌肤所致；胸膈痞满、口不知味、四肢酸软，皆湿热困阻中焦、脾运失健之候。故以四苓散加厚朴、陈皮、麦芽等渗湿清热、运脾消导，正合濡数之脉所主湿热酒疸病机。", ["濡", "数"]], "6417": ["病机", "六部数而无力，形气殊不胜息，数虽主热，然无力则非实火，乃气血大亏、虚热内扰之象。原文痛盛而脉数，专科误以痛为实、脉数为热，仍进活命饮加大黄；然饮食日减、肌肉日消、精神大惫，显系痈疡日久耗伤气血。此脉数无力正是正虚不能托毒之病机，故当大补托出，不可再攻。", ["数"]], "6418": ["病机", "两寸关脉滑数，两尺沉细，滑数主痰热食积壅于中上，沉细主下元虚寒。原文咳嗽痰红、恶心难食、食下即欲泻、肌肉消瘦、午后发热、四肢先麻、足膝战摇，正是虚中有食积痰饮之候。脉虽数而不敢轻用寒凉，因尺部沉细示下元不足、关门不守，故温补下元以止泻，滑数之痰积自可渐化。", ["滑", "数", "沉", "细"]], "6419": ["病机", "六脉浮而不见，非无脉也，乃热极汗未透彻、阳明余热在经，迫血上行而越出鼻窍，气机一时郁闭于表，故脉浮而不显。原文舌焦黄、目珠极红、鼻衄寒战、小水不利，皆热郁阳明之征。此浮而不见为作汗之兆，由热极使然，故用石膏、滑石、升麻等透热散邪，汗出如雨后脉乃渐出。", ["浮"]], "6420": ["病机", "两关洪滑鼓指，按之不下，洪滑为有余之候，主实积内壅。原文经不行半载、腹大如斗、坚如石、小水涓滴不通，乃魆食冷物积久成鼓胀，前任不审脉候，误作气虚中满温补，致胀急欲裂。洪滑鼓指正示积块实邪壅塞中焦，非虚满可比，故用积块丸下之，脉候实为辨证关键。", ["洪", "滑"]], "6421": ["病机", "左脉弦大、右洪大俱七至，弦大洪数主阳热亢盛。原文醉后房事、脐下痛、水泻肠鸣、发热头痛、面赤唇燥、黄苔深厚、呕逆烦躁口渴，里医误作阴症进理中而反剧。此脉洪大搏指、七至，正是春温阳症热邪充斥三焦之象，虽有房事、漏底，不得遽认为阴寒，当从脉症合参辨为阳热。", ["弦", "大", "洪", "数"]], "6422": ["病机", "六部洪数，洪主火盛、数主热炽，合为痰火壅盛之象。原文素有多躁痰火、旧曾吐红，误用收涩致痰瘀留滞，又误作风邪投散，火盛得风其势愈炽，血从口鼻喷出如泉涌，身热而烦，时当三伏内外火夹攻。洪数之脉正示火盛销铄、迫血上涌之病机，故用釜底抽薪、泻火凉血夺其上涌之势。", ["洪", "数"]], "6423": ["病机", "脉弦数不减，弦主少阳、数主热，合为少阳邪热未清之象。原文子午潮热、咳嗽痰多、汗流不止、胸膈不畅、大便燥结、动作喘乏、口渴，服清热化痰后热退十之七，而脉弦数不减，故断其恐防作疟。弦数持续示邪伏少阳、痰热未净，后果然疟作、咳转加、出黄黏老痰，正应无痰不作疟之说。", ["弦", "数"]], "6424": ["主病", "左脉数主血中有热，右脉沉涩主气滞血瘀。经水久不止而夹紫黑血块，脐下块坚如铁，胸腹胃脘皆痛，玉户肿，手足冷，皆瘀血内结、血瘕成形之征。沉涩为瘀阻脉络，数因瘀久化热，故断为血瘕症，非单纯虚寒崩漏。", ["数", "沉", "涩"]], "6425": ["妇人", "孕四月而六脉浮数，浮为风邪在表，数为热，与头疼、遍身痛、恶寒发热、咳嗽口渴相应，属外感风热乘胎。战汗后表减而胸膈胀闷，为胎气上逼之子悬。浮数在此非里虚，乃表邪未解、胎热内扰之象。", ["浮", "数"]], "6426": ["病机", "两手脉短弱示气血不足，两关弦大、右尺滑大示中焦痰积、膈间瘀血、阴分淫火。咳红、腹痛、梦遗、背胀并见，正合心血不足而痰瘀火交结。短弱为本虚，弦大滑为标实，故先清肃上焦，再攻痰瘀。", ["短", "弱", "弦", "大"]], "6427": ["病机", "崩后百日洗浴受风，外寒束内热，故六脉浮大而数。浮为风邪在表，大为热盛，数与发热、口甜、前后心胀、四肢肿痛相应。此表邪夹内热、气机壅滞之候，非崩后纯虚，故用柴胡、紫苏、麻黄以解表散邪。", ["浮", "大", "数"]], "6428": ["病机", "右关洪滑、两尺有力，主中焦痰热积滞；左脉略弦，示肝胆气郁。右胁块起疼痛拒按、额颅手心热、便结，皆痰热瘀结于胁。洪滑为实热痰壅，弦为痛为郁，故仿推气散合当归龙荟丸，泻热通滞。", ["洪", "滑", "弦"]], "6429": ["妇人", "孕八月受惊，两寸洪滑、两尺弱，为亢上不下之候。洪滑主痰热上壅胸膈，尺弱示下元不足、胎气上逼，故胸膈胀闷、呕逆不食。病起于惊，气逆痰随，胆胃不和，故用温胆汤加黄连、大腹皮以清降痰热。", ["洪", "滑"]], "6430": ["病机", "两寸洪大、两尺弱，寸大示上焦热壅，尺弱示下元不足。吐血碗余、潮热、便秘、呕吐不食，前医作阴虚火动滋阴反增饱闷，说明非纯虚。瘀血凝滞致新血不得归经，满而溢，故洪大为瘀热上逆之象，法当消瘀。", ["洪", "大"]], "6431": ["主病", "六脉浮紧而数，浮紧主风邪夹湿闭阻经络，数主火热。遍身筋骨疼痛、肢节肿痛、痛处热如火燎，正合湿热痹阻、火性速暴之周痹，俗名白虎厉节风。紧为痛为闭，数为热，故断为湿热所致，非单纯风邪。", ["浮", "紧", "数"]], "6432": ["病机", "六部俱微弱不充指，右关稍滑，为邪尽退而虚惫神弱之象。微弱不充指示气血大虚，右关稍滑主脾虚有痰湿内滞。症见精神昏惫、一息奄奄、四肢冷厥、口渴，皆虚惫神气弱之候，故非大补不能起。", ["微", "弱", "滑"]], "6433": ["病机", "两寸关脉俱滑大有力，两尺沉微，滑大主中焦有痰、肝胆有火，沉微示下元不足。症见眼赤肿、太阳痛、便闭、呕吐眩运，皆痰火冲逆之候，故断为中焦有痰、肝胆有火，怒气所触而然。", ["滑", "大", "沉", "微"]], "6434": ["病机", "脉仅四至，重按则伏而有力，四至为迟，伏而有力主积滞内凝。因攻克太过、寒凉伤脾，脾虚中气不运，积反凝滞，故大便虽泻而积不行，痛终不减。手足清冷、形神俱倦，皆中气受损之候。", ["伏", "数"]], "6435": ["病机", "六脉洪大，主热盛于内。产后未弥月醉犯房事，血来如崩，发热头晕，大小便俱热，洪大为阳热亢盛、迫血妄行之象。热扰冲任则血崩，热上攻则头晕，热下迫则二便热，故脉证相合。", ["洪", "大"]], "6436": ["病机", "六脉洪大，主少阳阳明二经热盛。颊腮红肿、呕恶发热、不能进食、下午烦躁、口苦、夜不能睡，皆热邪壅于少阳阳明之候。洪大之脉应阳热亢盛，故法当清解，以柴胡、贯众等清透二经之热。", ["洪", "大"]], "6437": ["病机", "左脉沉弦而数，右关结实大如碧豆，沉弦主肝郁，数主热，结实主积滞内结。症见胸胁胀闷、腹中疼痛、大便秘结、饮食大减，皆肝郁化热、积滞内结之候。前医误作脾虚理脾，故久治不愈。", ["沉", "弦", "数", "实"]], "6438": ["病机", "脉之左涩、脉滑大、两尺脉又弱，左涩主血少，滑大主痰火，两尺弱主肾元虚。症见吐血后咳嗽、喘促泄泻、发热烦躁，乃火刑肺金而脾胃已惫，上喘下泄，元气下脱，故脉象虚实夹杂。", ["涩", "滑", "大", "弱"]], "6439": ["病机", "六部浮大无力，重按三五不调，六七至一止，右关近滑。浮大无力为劳倦表虚感邪，三五不调、六七至一止为气虚血弱、脉行不畅，右关近滑主脾虚有痰。症见汗出不止、呃逆、昏愦，皆表虚邪陷、中气大亏之候。", ["浮", "大", "滑"]], "6440": ["主病", "左脉弦大，右滑大。弦为肝郁，大为邪盛，滑主痰湿。患者因忧思而起胀满，忧思伤脾，肝木乘之，气机壅滞，痰湿内停，故脉见弦滑而大。此木香化滞汤症，主气滞湿阻之胀满，与忧思病因相应。", ["弦", "大", "滑"]], "6441": ["主病", "六脉浮而洪数，左寸尤甚。浮主表，洪数为热盛，左寸候心与上部。患者左胯肿痛，红肿光浮如匏，抚之烙手，显系热毒壅聚成痈。脉浮洪数，为热毒外发之象，故主便痈，与局部红肿热痛相应。", ["浮", "洪", "数"]], "6442": ["病机", "脉俱洪数，症见发热昼夜不止、口渴齿燥、舌苔黄厚、呕恶胸痞、小水短赤。洪数为阳明热盛，热灼津伤，故口渴齿燥；热壅气机，故胸膈痞懑；热迫大肠，故下清水。此脉主里热炽盛，与诸热症相应。", ["洪", "数"]], "6443": ["病机", "脉左弱细。弱为气血不足，细为阴血亏虚。患者因丧子哀哭弥月，绝粒断浆，肌容日瘁，复感初秋寒热，呕哕懊𢙐，遍身疼。此忧思伤脾，气血生化乏源，脉道不充，故见弱细。主气血两虚，与形瘁、不食相应。", ["弱", "细"]], "6444": ["其他", "原文未识别脉名，仅述患蛊胀，腹大如覆箕，青筋缕缕如蚯蚓，脐平，四肢面目浮肿。此水湿壅盛，气滞血瘀之蛊胀重症。脉象缺如，故无从论脉，然症情危重，非一般胀满可比。", []], "6445": ["病机", "左弦大，右关滑大，两尺俱无。弦大主肝郁邪盛，滑大为痰湿壅盛，两尺无脉主肾气衰微。患者昔肥今瘦，肠鸣如雷，腹中块跳，肌肤黄金，足膝冷，饮食不入。此痰饮内停，脾肾阳虚，本虚标实之候。", ["弦", "大", "滑"]], "6446": ["病机", "左脉大而有力，右寸亦大。大为邪气盛，有力为实。患者素多疮疥，沐浴后鼻红，面足浮肿汗多。此湿热内蕴，肺气不宣，水湿泛溢。脉大主热盛邪实，与浮肿、鼻红、汗多之湿热症相应。", ["大"]], "6447": ["病机", "左手数，右手弱。数为有热，弱为气血不足。患者忧思郁结，左胯痛连膝，小水频数，便频，脐腹胀疼，口干，发热恶寒，汗出痛甚。此郁火挟痰瘀流注下部，脉数主郁火，弱主正虚，恐成肠痈。", ["数", "弱"]], "6448": ["病机", "右寸独洪大，右寸候肺，洪大为热盛之象。患者头痛胸背胀、咳痰浊如脓、便结，显系肺热壅盛，灼津为痰。脉象独右寸洪大，正合肺中实热，故以二陈汤加竹茹、滑石、石膏、酒连、麦冬清肺化痰。后痰腥臭，为热壅血腐，将作肺痈，改用清热凉血排脓之品而安。", ["洪", "大"]], "6449": ["病机", "六脉滑数，滑主痰湿，数主热，此气虚血热之征。患者三孕三小产，血下频多，热迫血妄行，故脉滑数。滑下如水行旧路，血滑不止，治以清热凉血、涩血安胎，用防风子芩丸及白芍、侧柏叶等，血止胎安。脉滑数正是血热妄行之病机反映。", ["滑", "数"]], "6450": ["病机", "右寸关脉濡弱，右寸关候脾肺，濡弱为脾虚湿盛之象。患者右手痛风、小水频迫不禁、足有浮气，年过六十，脾虚不能运化水湿，湿浊下注，故见小便失禁、足肿。近加咳嗽，为脾虚生痰犯肺。治以六君子汤加苍术、石菖蒲、附子等健脾化湿，缓治而平。", ["濡", "弱"]], "6451": ["病机", "原文未识脉名，但述经不行三月、便泻腹胀、吐酸水、带下恶心，似孕而非孕。脉候非孕，乃脾经湿热与心经瘀血相合。湿热困脾则泻、腹胀、恶心；瘀血阻心则经闭。治先清利湿热，泻止经行，继以活血化瘀，吐黑血水，终以四物汤加味调理而痊。", []], "6452": ["病机", "左脉弦大，右寸关滑大有力。弦主肝风，滑主痰，大主热。患者下午喉痛、痰多晕厥、头痛面赤，显系肝风挟痰热上扰清窍。左脉弦大应肝风，右寸关滑大有力应痰热壅肺胃。治以疏风清热、化痰开窍，用荆芥、薄荷、僵蚕、竹茹、贝母等，痰热渐清而平。", ["弦", "大", "滑"]], "6453": ["病机", "时疫热病发汗过度，热留胸中，烦躁呕恶，汗出不敛，口渴。独两关洪大，两关候阳明，洪大为阳明热盛之象。汗后津伤而热未解，阳明热邪尚炽，故以白虎生脉汤清热生津，石膏、知母清阳明，人参、麦冬、五味子益气敛汗生津，热退而安。", ["洪", "大"]], "6454": ["病机", "春温头痛发热，左脉弦大，右洪大，弦大主肝胆热盛，洪大主阳明热炽。初以小柴胡合白虎汤而愈，后食复发斑，神昏鼾睡，舌苔黄黑芒刺，六部俱浮洪，为热毒炽盛、气血两燔。浮洪示热邪充斥表里，故以三黄石膏汤清热解毒，加枳实、鳖甲通下，热退神清而愈。", ["弦", "大", "洪"]], "6455": ["误治", "饥劳感疫，面内伤，表里皆热，医误以遇仙丹下之，泻三四十行，邪陷成挟热下利。脉左弦数，右洪数，但不克指，为误下坏症。弦数主肝胆热，洪数主阳明热，不克指示正气已伤。治以柴胡、石膏、黄芩等清解表里，后吐蛔、便泻、呕吐酸水，改小柴胡加滑石、竹茹，随证调治。", ["弦", "数", "滑", "洪"]], "6456": ["病机", "六脉浮数，浮为邪在表，数为热盛；继而浮弦而数，弦主痛、主少阳，鼓指为邪势亢盛。头项痛、腰脊强、遍身如被杖，显系春温外感，邪郁肌表，故脉浮数鼓指。前医误作阴虚，滋阴壅滞，引邪入阴，故热加躁闷。此脉证实为外感春温，非内伤虚损。", ["浮", "数", "弦"]], "6457": ["病机", "脉之近数，数主热盛，亦主脓成。乳肿寒热，经治疗后寒热退而肿不消，脉近数，知热毒酝酿，血肉腐化，已成脓。数脉在此非单纯表热，而是痈毒内腐、正邪交争之象，故用内托十宣散托毒排脓，脓溃而愈。", ["数"]], "6458": ["病机", "右寸脉洪大有力，右寸候肺，洪大为热盛气壅。途次受暑，又为酒面所伤，暑热与酒食湿热搏结，燥动脾火，致吐、痞闷、目珠如金、一身尽黄，已成疸症。右寸洪大有力，正是暑热壅肺、湿热熏蒸之象，故治以解暑清热、利湿退黄。", ["洪", "大"]], "6459": ["病机", "两寸脉滑而数，两关弦。滑主痰，数主热，弦主郁。寸候肺，关候肝胆。暑月喘嗽、浓痰滚滚、夜分口渴、胸膈胀闷，显系肺有宿痰，胆有郁火。痰火交阻，肺失肃降，故喘咳；胆火郁蒸，故关脉弦。此痰火内郁之实证，非单纯外感。", ["滑", "数", "弦"]], "6460": ["病机", "左关弦大，右寸关滑大。左关候肝，弦大为肝气郁结、郁而化火；右寸关候肺脾，滑大为痰热壅盛。食饱后感怒，气郁痰凝，老痰瘀血积于上焦，故胸背胀疼、眩晕、咳吐红痰。脉象证实为痰瘀互结、肝郁化火之实证，滋阴反滞其邪。", ["弦", "大", "滑"]], "6461": ["病机", "左寸关脉洪滑，右关亦然。洪为火盛，滑为痰凝。左寸关候心肝，右关候脾胃。胸胁胀痛、五更嘈杂，嘈杂则痛甚，显系肝胆郁火横逆，胃中胶痰内蕴。木火之性贵乎疏通，郁火与胶痰搏结，故脉洪滑。此有余之疾，宜龙荟丸条达肝火。", ["洪", "滑"]], "6462": ["病机", "左脉弦数，右寸短弱。弦主肝郁，数主热，短弱主肺气不足。暑月小便不利而痛、玉户肿、便血发热，显系肝火太炽，下迫膀胱与血海；右寸短弱，示肺气不足，不能通调水道。肝经壅塞，热伤血络，故便血发热。治当疏决肝经壅塞，兼补肺气。", ["弦", "数", "短", "弱"]], "6463": ["病机", "两寸关俱滑数，尺亦数。滑主湿浊痰积，数主热。寸关候中上焦，尺候下焦。脐腹疼痛、白带如注、里急后重、赤白痢，显系湿热蕴结肠道，气血壅滞，故脉滑数。湿热下注，伤及血络，故便脓血。此湿热痢之实证，治当清热利湿、调气和血。", ["滑", "数"]], "6464": ["病机", "左脉浮大、六部俱数，浮为邪在表，大为热盛，数为热象，结合额痛遍身疼、口干、舌苔黄厚，显系三阳合病而暑热内炽。浮大之脉主表热壅盛，数脉主热邪亢盛，故用柴胡、白虎、羌活等解表清里，后以石膏为君大清气分，汗出热退，脉象当随之而平。", ["浮", "大", "数"]], "6465": ["病机", "两寸关脉滑大，滑主痰食积滞，大主邪气盛，见于寸关提示中上焦气机壅滞；两尺沉弱，沉弱主下焦气血不足。合而观之，乃血虚气滞、胃脘疼痛之候，故用积气丸行气止痛，继以养血和血、理气消食之品而安。", ["滑", "大", "沉", "弱"]], "6466": ["病机", "左脉微弦，弦为少阳之象，主疟邪伏于半表半里；右关滑大，滑主痰湿，大主邪盛，关部候脾，提示痰湿困脾、脾气大虚。三阴疟久发，热多寒少，脉弦滑大，故以二陈汤加柴胡、黄连等和解截疟，后以白术、何首乌、鳖甲扶正截疟而愈。", ["弦", "滑", "大"]], "6467": ["病机", "左脉浮弦而数，浮主表邪，弦主少阳，数主热盛；中按有力，右关滑大，滑主痰热内蕴。结合两太阳痛、胸胁疼、口渴、水泻，显系春温之邪客于少阳阳明，表里俱热。故用柴胡、葛根解表，石膏、知母清里，使汗出热解而诸症悉平。", ["浮", "弦", "数", "滑"]], "6468": ["病机", "右脉洪大如豌豆，洪主热盛，大主邪气实，右脉候气分，提示气分热炽、血分有滞。症见腹中微疼、经行不利、喉痛、四肢麻木作战，乃热壅气滞、经血不畅之候。故用川芎、香附、酒芩等行气清热调经，四剂而安；后经水大行不止，改用黄芪、阿胶补气摄血而止。", ["洪", "大"]], "6469": ["病机", "左脉软弱，软主气血不足，弱主虚损，左脉候血，提示阴血亏虚；右关尺弦数有力，弦主疟邪，数主热，关尺候脾肾，提示疟邪内蕴、脾肾有热。三阴疟久发，寒多热少，盗汗，脉见软弱与弦数并见，乃正虚邪恋之象，故用白芍、当归、白术扶正，柴胡、黄芩、首乌截疟。", ["软", "弱", "弦", "数"]], "6470": ["误治", "左脉弦数，弦主少阳，数主热；右关尺沉数有力，沉主里，数主热，有力主实，提示热邪内陷阳明。患者先感风邪后伤饮食，医者妄下妄补，致神气昏沉、舌焦芒刺，已成坏症。脉弦数沉实有力，说明邪热仍盛，故以柴胡、石膏、知母等清解，少佐人参扶正。", ["弦", "数", "沉", "有力"]], "6471": ["病机", "脉左弦数，弦主少阳，数主热；右滑大而数，滑主痰热，大主邪盛，数主热炽。春温后经水适止，余热不退，口渴、胸胁痛、耳重，显系少阳阳明热邪未清，痰热内蕴。故以小柴胡加石膏、知母清解，后以柴胡、当归、白芍、红花等调理而瘳。", ["弦", "数", "滑", "大"]], "6472": ["病机", "六脉俱洪数，洪为阳明热盛，数为热邪亢盛，脉症合参，头痛身热口渴气促、舌焦紫斑、谵语耳聋，皆少阳阳明合病之疫毒内炽。前医误用藿香正气散温燥，致呕逆水泻；柴苓汤升散，反增热剧。洪数脉确示热盛于内，故以石膏、知母清阳明，柴胡、黄芩和解少阳，热退斑消。", ["洪", "数"]], "6473": ["病机", "左脉弦数，坚劲博指，弦主痛、主瘀，数主热，坚劲为实邪内结。患者左胁痛手不可近，小腹亦痛，乃旧瘀与湿热痰积作祟，瘀血阻络，不通则痛。脉坚劲博指，正示瘀滞坚实，故用青皮、桃仁、大黄、玄明粉逐瘀泻下，下沉香色稠黏瘀物而安。", ["弦", "数", "坚"]], "6474": ["病机", "两寸脉累累如贯珠，两尺俱软弱。寸盛主上焦痰瘀壅实，累累如珠为痰瘀结聚之象；尺弱主肾阴亏虚，下元不足。症见咳红发热、脚膝乏力，乃上盛下虚、本虚标实之候。先清上焦痰瘀，后养阴收功，脉象示痰瘀在上、肾虚在下，故不可纯补纯攻。", ["软弱"]], "6475": ["病机", "左浮而弦数，右洪长而数。浮弦数为少阳邪热，洪长数为阳明热盛，脉症合参，头疼口渴、舌苔黄燥紫黑、身热昏愦谵语、胸胁痛，显系少阳阳明二经热疠。脉症相对，故断可生。洪长示热势鸱张，弦数示邪郁少阳，治当两解阳明少阳。", ["浮", "弦", "数", "洪"]], "6476": ["病机", "六脉沉弦而数，沉主里，弦主痛、主郁，数主热。疫后大热头疼胸胁痛，复因梦交泄精，冷汗肢解神昏谵语，舌焦强硬，二便俱秘，此阴阳易类，热毒内陷厥阴少阴，脉沉弦数正示邪热深伏于里、郁结不伸。危候已极，故以生脉汤加柴胡黄芩桂枝，扶正透邪。", ["沉", "弦", "数"]], "6477": ["病机", "左脉沉弦，右滑数。沉弦主里、主痛、主气滞，滑数主湿热积滞。滞下里急后重，下稠黏紫黑血无粪，口渴胸膈焦辣，乃湿热瘀积胶固肠道，气血壅滞。脉沉弦滑数，示积滞在里、湿热壅盛，故不敢轻补，先以芩芍汤清肠，终用下法逐积。", ["沉", "弦", "滑", "数"]], "6478": ["病机", "本段未明言脉象，然述哮喘夙疾，屡服五虎汤（麻黄、石膏等）大剂，致胃中冲和耗损，腹大如覆箕、腿肿如柱、臁疮清水涓涓，显系过服峻药伤中，脾肾阳虚，水气泛滥。病机为药误致虚，水湿不化，与脉象无直接关联，故脉象要素从缺。", []], "6479": ["病机", "左脉浮数，中按弦，右滑数。浮数主风热在表，弦主痛、主饮，滑数主痰热。肢节红肿热痛、游走不定，喘咳气涌，乃湿热风痰壅遏经络，行痹之候。脉浮数弦滑，正合风、湿、热、痰交阻之机，故以苍术、黄柏、苡仁清利湿热，麻黄、威灵仙通络，痰化则咳止。", ["浮", "数", "弦", "滑"]], "6480": ["主病", "脉洪数，洪为阳盛，数为热炽，此肺痈热毒壅盛之征。原文见咳吐桃花脓、腥秽恶气、右胁乳胀痛、大便燥、肌瘦骨立，皆热毒腐肺、瘀痰成痈之候。洪数应热，热盛则肉腐为脓，故脉洪数主肺痈实热。", ["洪", "数"]], "6481": ["病机", "右寸关脉滑大有力，滑主痰饮，大主实热，有力为积滞。原文谓气郁食积痰饮症，忧思伤脾，气结不行，津液凝聚为痰，故喘急作胀、面浮、胁不能卧。滑大有力正应痰食壅实之病机。", ["滑", "大"]], "6482": ["病机", "左涩右滑，涩主瘀血，滑主痰积。原文据脉有瘀血痰积，休息痢下紫血、腹痛、体倦肌瘦，乃痰瘀互结、痢久不愈之候。左涩应血瘀，右滑应痰积，脉症相合，故主瘀血痰积。", ["涩", "滑"]], "6483": ["病机", "右脉濡数，左脉洪数。濡主湿，数主热，洪为火盛。原文谓郁火痰积症，忧伤肺、思伤脾，饮食不化，积而生痰，故腹痛溏泻、潮热汗出。濡数应湿郁化火，洪数应火痰壅盛，脉示郁火痰积之机。", ["濡", "数", "洪"]], "6484": ["病机", "左浮而弦大，右滑大，俱数。浮弦大主风热上壅，滑大主痰火。原文引《内经》九窍不利肠胃所生，谓胃中痰火上壅，热极生风，故耳鸣鼻塞、痰多膈热。脉象正合痰火生风、上壅清窍之病机。", ["浮", "弦", "大", "滑"]], "6485": ["病机", "两寸洪滑，两尺沉微。寸洪滑为痰火上盛于上，尺沉微为下元虚衰于下。原文谓上盛下虚之候，体肥痰火十年，吐痰吼喘、面赤头痛而尺脉沉微，正合上实下虚、清上补下之病机。", ["洪", "滑", "沉", "微"]], "6486": ["病机", "两寸脉短涩，短主气损，涩主血滞。原文孀居二十年，忧思伤肺，脏寒故多悲泣，神情恍惚乱语。寸脉短涩应心肺气虚、血涩不畅，故主忧伤肺脏、脏寒多泣之病机。", ["短", "涩"]], "6487": ["病机", "两寸脉洪大，右关滑大。洪大为火盛，滑大为痰热。原文五六月吐紫黑血块、足跟焮肿痒痛流黄水，乃痰火湿热壅盛、迫血妄行之候。寸洪大应上焦火炎，关滑大应中焦痰热，脉示痰火湿热之病机。", ["洪", "大", "滑"]], "6488": ["病机", "脉才四至，大而不敛，为真气虚中满之象。四至虽平，然大而不敛，是元气耗散，虚阳外浮，脾肾阳虚，水湿不化，故腹大如箕、足膝肿大、气壅不能卧。此非实邪，乃虚中夹满，攻下则更伤正气，故曰‘攻下是杀之也’。", ["大"]], "6489": ["病机", "六脉俱洪大而数，为毒热炽盛、邪正交争之象。杨梅疮毒内陷，肺受热灼则喘咳气涌，阴囊红肿、肛脱疮满，皆热毒壅滞。洪大数脉主阳热实邪，壮年正气尚能抗邪，故虽重犹可治。", ["洪", "大", "数"]], "6490": ["病机", "六脉弦数，弦主痛、主肝郁，数主热。骨梗后硬物压伤胃脘，瘀血停留膈间，气机壅滞，故胸膈胀痛、恶寒发热。弦数为瘀热内结之征，消瘀则食管复常，痛可瘳。", ["弦", "数"]], "6491": ["预后", "六脉滑大无力，滑主湿浊，大而无力为气虚。痢下屋漏水、血子，呕恶不食，神昏卧不起，脉证相悖，正虚邪盛。前医更投苦寒攻伐，脉转‘屋漏’，乃胃气衰败之死脉，故预后凶险。", ["滑", "大"]], "6492": ["病机", "六脉滑大无力，滑为湿滞，大为气虚，无力为脾虚不运。产后下痢红白，胃脘痛不止，汗多，乃气郁化火、脾虚湿盛、卫外不固。法当收敛，以小建中汤温中补虚，加御米壳敛汗止痢。", ["滑", "大"]], "6493": ["病机", "脉得沉弦而数，沉主里，弦主肝郁、主疟，数主热。疟久不愈，邪伏少阳，肝脾不和，痰湿内蕴，故寒热往来、胸膈痞闷、小便溷浊。沉弦数为疟邪内郁化热之象，非单纯表里虚实可概。", ["沉", "弦", "数"]], "6494": ["病机", "六部皆弦，弦为肝木所主，搀前而至，是肝有余而脾土受敌。脾伤则饮食少，血枯则筋失养，故肌肉瘦削、关节肿大而痛。诸痿不可作风治，前医误作风剂，伤血耗气，病势几危。", ["弦"]], "6495": ["病机", "脉皆细涩，细为血虚，涩为血瘀。痢后寒湿秽瘀凝滞经络，气血为痛所伤，故筋骨肿痛、肌肉消、烦躁。细涩脉示虚实夹杂，补则肿剧，通则痛甚，惟大防风汤补虚疏通兼施。", ["细", "涩"]], "6496": ["病机", "原文仅言“六脉大小不等”，未列具体脉名，故脉象要素为空。此案心膈嘈杂、嗜肉、痛则吐酸涎，脉大小不等提示脾胃虚实错杂、气机紊乱：脾虚不运则嘈杂思肉，肉入难化则气逆痛吐。脉象不匀正是脾虚夹滞、升降失司之象，非单纯虫祟。", []], "6497": ["病机", "孕七月食冷患痢，两关脉滑数。滑主痰湿食滞，数主热，关候脾胃。冷食伤中，湿滞化热，故下白脓、腹痛后重、小水不利。脉滑数示湿热壅滞肠胃兼胎孕之象，故用艾叶、砂仁安胎，芩连清湿热，滑石泽泻利水。", ["滑", "数"]], "6498": ["病机", "六脉滑大而数、浮而不敛。原文自释“滑大为痰，数为热，浮为风”，又谓湿生痰、痰生热、热生风。体肥善饮多湿，荒于色则真阴竭而脉浮。手指掉硬、口角牵扯，正是痰热生风、中风先兆之候，脉象与症相应。", ["滑", "大", "数", "浮"]], "6499": ["预后", "脉细如珠丝，为疫症日久、气血衰微、阳气欲绝之危候。原文引“脉绝微续者生”，服药后六脉渐见，故断可保无事。细如丝示正气将竭，微续渐见则胃气来复，脉象由绝转续，主生机尚存，属预后判断。", ["细"]], "6500": ["病机", "脉皆缓大无力。缓大为脾虚湿盛之象，无力则中气不足。痢下红脓如腐烂鱼肠、日夜百余次，由饥饱后纵欲所得，脾为寒湿所伤、脾不裹血，故脉缓大无力。此脉主脾虚寒湿、统血失职，非实热痢之滑数。", ["缓", "大"]], "6501": ["病机", "两寸滑数，左关尺涩。滑数主痰热，涩主瘀血。吐物如烂猪肺、胸背胀，由酒后怒发，肝脾伤而血不藏不统，血随气上积于胸膈。寸滑数示痰热壅上，关尺涩示瘀血内停，故断为瘀血痰饮症而非肺坏。", ["滑", "数", "涩"]], "6502": ["病机", "左关弦大，右寸下半指累累如薏苡子状。左关候肝，弦大为肝气有余、郁火亢盛；右寸候肺，累累如薏苡子示痰壅肺窍。多酒多怒，湿热助火生痰，火炎迫肺，金壅不鸣故声哑；怒伤肝，血随气妄动，故上吐下溲。此有余症，非瘵。", ["弦", "大"]], "6503": ["病机", "六脉滑数，滑主痰湿，数主热。孀居年六旬患痢赤白、呕吐痰涎、粒米不入，肌肉尽削，脉滑数知湿热痰火所致。虽形气不足，而脉见滑数、神存，故可治。以二陈加益元散、姜连芩清化痰火，服四十帖而愈，示脉症相参、神存可恃。", ["滑", "数"]], "6504": ["病机", "两寸脉洪滑，洪为火盛，滑为痰聚。寸部候肺，痰火郁滞肺之气道，灼伤血络，故咳吐红痰如桃花脓色；气血壅滞，前后心稍胀疼。此瘀血痰火互结，肺痈将成之候，治当调气化痰、消瘀清肺。", ["洪", "滑"]], "6505": ["病机", "左弦数、右洪大而数，弦主少阳，数为热盛，洪大为阳明热炽。春温食复，热邪内燔，故人事昏沉、内热口渴、舌如焦煤、胁痛耳聋、身热如火。脉证合参，乃少阳阳明合病，热壅气机，僵硬不能转动。", ["弦", "数", "洪", "大"]], "6506": ["病机", "脉象早晚大小缓急不一，非外感六淫之常脉，乃虫动气乱、脉气不宁之象。虫扰于中，气机逆乱，故腹痛呕吐不止。脉无定体，与虫痛之发止无常相应，故知为虫痛，治以温中安蛔。", []], "6507": ["病机", "两手俱缓弱，缓为脾虚，弱为气馁。前医误作风热，过用升散寒凉，戕伐中气，故饮食顿减、遍身发疮、痛痒不可言。脉缓弱示脾虚湿蕴、气血不足，疮痱乃中虚湿郁化热所致，治当健脾益气。", ["缓", "弱"]], "6508": ["病机", "右脉滑、左脉弱，右滑主痰湿内蕴，左弱主血虚不荣。劳倦伤脾，脾虚气弱，痰湿中阻，故心脾痛、得食压之立止；两腿生疮亦湿郁下注。脉证合参，乃中虚痰湿、气血失和之候。", ["滑", "弱"]], "6509": ["病机", "右关脉滑大有力，关候脾胃，滑主痰，大主热。风热羁绊脾肺之间，痰热壅盛，故腹高于胸、发热面红、咳嗽呕吐，甚则连血喷出。脉滑大有力，正邪俱实，风热痰浊交阻之病机昭然。", ["滑", "大"]], "6510": ["病机", "两手脉俱软弱，软为气虚，弱为血少。年近五十，气血渐衰，左胁痛、手足抽搐、不能步履，乃肝血不足、筋脉失养，兼脾虚气弱。脉软弱与虚风内动相应，故治以养血柔肝、益气通络。", ["软", "弱"]], "6511": ["病机", "六脉洪大，洪为热盛，大为邪实。血痢腹痛、里急后重，面赤唇红似涂朱，喊叫之声骇人，皆热毒壅滞肠道、气血搏结之象。脉洪大与热毒炽盛相应，然伏于床间、泪不能言，示邪实正伤，急当温通导滞。", ["洪", "大"]], "6512": ["病机", "脉甚数主热盛，因怒后发热吐血、口渴汗多，显系肝火犯肺、热迫血行；数脉渐退而左脉尚弦，弦为肝旺未平，故寒热止而胁疼痰多，终以清肝化痰获安。", ["数", "弦"]], "6513": ["病机", "两寸滑大主上焦痰积，两尺沉微为下元不足，痰气交阻胸膈，故心痛彻背、食入即吐；积气丸消痰下气，气顺痰消则十七年痼疾得断根。", ["滑", "大", "沉", "微"]], "6514": ["病机", "脉浮而数，浮为风邪在表，数为痰火内郁；风寒外束鼓激痰火上涌，故咳嗽胸胁胀痛如刀刃所剚，发热口渴。治以散风清痰，表解火降则痛平。", ["浮", "数"]], "6515": ["病机", "六脉缓大有力，缓主脾湿，大而有力为痰脂壅盛；脾湿生痰，脂满子宫，故经闭八年而肌肉丰肥、饮食倍加。法当调气消痰、燥湿溶脂，非破血所能通。", ["缓", "大"]], "6516": ["病机", "脉沉弦有力，沉主里、弦主气结，非气虚中满之候；惊骇气乱，肝郁乘脾，水气太过，故腹胀如鼓、青筋缕缕、足跗浮气。前用参苓白术补之太骤，反助其壅。", ["沉", "弦"]], "6517": ["病机", "右脉缓弱无力，右关主脾胃，缓弱为脾胃气虚；中气不足则清阳不升、浊阴不降，故饮茶饭食逆从鼻出，渐加恶心头晕、肌肉削、四肢无力，非胃火实症。", ["缓", "弱"]], "6518": ["病机", "六脉濡大无力，濡主湿、大而无力为气虚湿滞；产后败血凝滞血海，流于经络，郁而化热，故右腿疼处发热。误认虚风峻补，致脓成毒发，非虚症也。", ["濡", "大"]], "6519": ["病机", "脉太数近七至，左关弦而搏指为肝火亢盛，右关沉滑为中焦湿痰，两寸短弱则上焦气不足；木火循少阳上冲耳后，故右胁极痛、夜甚汗出，法当调肝清热化痰。", ["数", "弦", "滑", "短"]], "6520": ["病机", "右寸关洪滑，洪为阳盛火炎，滑为痰湿内蕴，右寸关候肺胃，故断为肺经痰火。痰火壅肺，鼻窍不利则塞，火迫血溢则衄，火灼津液则口渴，痰结咽喉则生痰核。寒月更甚者，外寒引动内火，痰火胶结愈甚。此脉症相合，故以清肺化痰降火取效。", ["洪", "滑"]], "6521": ["预后", "右寸关洪滑弹指如黄豆大，为痰食壅盛、胃气上逆之象；左三部散乱如解索，两尺绝无神气，乃久病脏气衰败、根本已亏之候。左脉散乱无绪主虚弱久病，右脉弹指主饮食所伤，反复发作，正虚邪实，故断其势危、不治。此以脉判预后，非主病机。", ["洪", "滑", "散", "弱"]], "6522": ["病机", "两手脉皆浮而洪数带滑，浮为风邪在表，洪数为热，滑为痰。风热外袭，痰热内壅，故恶风、潮热、咳嗽痰多难出、胸膈壅塞。虽脾泄多年，然脉不虚而反浮洪数滑，说明新感风邪、痰热壅肺为当前主病机，非单纯气虚老蓐，故法当清解，不可温补。", ["浮", "洪", "数", "滑"]], "6523": ["病机", "左弦大、右滑大，左候肝胆，弦大为肝气偏亢、胁络不和；右候脾胃，滑大为食痰内壅。外伤风邪，内伤饮食，风痰食积交阻，肝络失和，故右胁痛、咳嗽夜甚。体肥面青亦痰湿肝郁之征。脉症合参，主风邪外袭、食痰内伤之病机。", ["弦", "大", "滑"]], "6524": ["病机", "左数右滑数，数为热，滑为痰。左数主心肝火旺，右滑数主胃中痰热食积。平素好食热物，积热生痰，劳心动火，故上焦浮热、头面疮疖；稍凉即腹痛泄泻、便后间红，乃脾胃蕴热、升降失司。脉象揭示痰热食积内蕴、火动上炎之病机。", ["数", "滑"]], "6525": ["病机", "右滑数、左弦数，滑主痰，数主热，弦主气郁。右候脾胃，滑数乃中焦痰积化热；左候肝胆，弦数为肝气偏旺。痰积中焦，气机壅滞，故腹中如火滚动、不知饱饿、不思饮食、右胁痛；痰热上逆则咳嗽口干。脉象紧扣中焦痰积之病机。", ["滑", "数", "弦"]], "6526": ["预后", "脉三四至一止、七八至一止，缓而止，脉书谓之结脉。结脉非凶脉，乃寒湿痰凝滞、阳气不伸所致，非死候。两尺迢迢有神，说明肾气未绝，故断为可治、寿算未艾。诸医误以苦寒克伐，反致腹疼，更证其虚寒本质。此段以脉辨结脉之预后，非主病。", ["缓", "结"]], "6527": ["病机", "左关尺脉甚弦，左关候肝，尺候下焦，弦为肝气郁结、寒凝气滞之象。肝脉绕阴器、抵少腹，肝经寒凝气滞，则疝气、两胯结核硬痛。脉弦与疝痛结核相应，主肝经寒凝气滞、痰湿结聚之病机，故以平疝丸疏肝散结、温通消滞取效。", ["弦"]], "6528": ["病机", "左脉弦大为肝胆气机偏亢，右寸短弱示肺气不足，关尺滑大为中焦痰湿内蕴。疟热多寒少、口渴、小水不利，正是痰热内郁、肺失通调之象；倦怠头疼亦由气虚痰阻、清阳不升所致。脉象与症候相合，故以石膏、知母清痰热，柴苓和解渗利，黄耆补肺气。", ["弦", "大", "短", "滑"]], "6529": ["病机", "左脉弦大而数，弦为肝胆之脉，大数主热，右滑大而数亦属痰热壅盛。患者嗜煿炙，热毒蕴结肝胆二经，故左胁下红块作疼。脉象弦大数正合肝胆热毒炽盛之机，滑大数则示痰热互结。治以栝蒌、白芍、当归等活血清热，使硬块潜消而大毒不成。", ["弦", "大", "数", "滑"]], "6530": ["病机", "六部皆弱为气血阴阳俱不足之象，惟右关滑则示胃中有痰。心血不足、下元阳气不充，故脉弱；胃中痰浊内停，故右关独滑。弱脉主虚，滑脉主痰，合而观之，乃虚中夹痰之候。治以远志、枸杞、巴戟等补心肾、固阳气，佐以茯苓化痰，正合脉证。", ["弱", "滑"]], "6531": ["病机", "两寸短为胸膈气机不畅，关滑主痰，两手皆数则示郁火内炽。患者胸膈胀痛、痰中紫色瘀血，乃酒积郁火灼伤血络、痰瘀互结所致。脉短滑数正合痰火郁结胸膈之机，短脉应胸膈病位，滑数应痰火。故先以红六神丸，继以山栀、酒连、郁金等清火化痰行瘀。", ["短", "滑", "数"]], "6532": ["病机", "两尺脉洪大而两关滑，示痰火壅盛于上；两尺沉微，则肾经真阴不足于下。原文明言「阳亢阴微之候，上盛而下虚」，上盛为痰火，下虚为肾阴亏。洪大滑主痰火亢盛，沉微主下元虚衰。故法当清上补下，清中用清中丸化痰降火，补下用既济丹滋肾填阴，使头目清利、腰膝强健。", ["洪", "大", "滑", "沉"]], "6533": ["病机", "左寸短弱示心血不足，关弦大主肝经瘀血，右寸下半指与关滑大、两尺洪大，皆中焦痰湿与下焦热象之征。原文断为「中焦有痰，肝经有瘀血」。血淋日久、面热牙疼、燥渴喜冷，乃瘀血内阻、痰热下迫之候。脉弦大滑大与痰瘀互结相应，故治当去瘀生新、提清降浊。", ["短", "弦", "大", "滑"]], "6534": ["病机", "两手脉皆沉数，左兼弦，沉主里、数主热、弦主饮。原文断为「上焦有痰饮」，痰饮内停、郁而化热，故脉沉数而弦。前后心痛、面赤手心热、耳鸣眩晕、吐酸水，皆痰饮上逆、郁热内扰之象。沉数弦正合痰饮郁热之机，故以二陈汤加瓦楞子、滑石、姜连等化痰清热降逆。", ["沉", "数", "弦"]], "6535": ["病机", "脉涩主气血运行不畅，涩而无力则为气虚血少之征。胃脘痛彻背、重按少止、痛时冷汗如雨，皆中气虚弱、络脉失养所致。原文明言「此气虚而痛也」，涩脉正应气虚血滞之机。故以小建中汤温中补虚，加御米壳缓急止痛，使中气复而痛止。", ["涩"]], "6536": ["病机", "左寸沉弱主肺气虚，关尺弦细主肝经瘀血；右寸略滑为肺经浊痰。酒后纵欲，淫火交煽，精离故道，凝滞经络，流于溺道，新血被阻而成血淋。脉弦细为瘀血阻滞，沉弱为气虚推动无力，滑为痰浊。", ["沉", "弱", "弦", "细"]], "6537": ["主病", "左寸短主心气不足，右关滑主胃有痰湿，两尺弦大主下焦风热。肠风下血，腹中微痛，脉弦大为风热迫血，滑为湿浊，短为气弱。风热湿浊蕴结肠道，血络受损而下血。", ["短", "滑", "弦", "大"]], "6538": ["病机", "左寸短弱为心肺气虚，关弦大为肝经有热，右寸关滑为脾肺痰火，两尺洪大、六部皆数主湿热下注膀胱。痰火湿热流于膀胱，溲前作痛，小便了而不了，脉数洪大为湿热壅盛之象。", ["短", "弱", "弦", "大"]], "6539": ["病机", "右寸关滑数主酒积化热、痰火内蕴，左弦数主肝火偏亢。频伤于怒，肝火冲上，右胁作疼，耳鸣眩晕，大便艰涩。滑数为痰热，弦为肝火，火盛灼津故便艰。", ["滑", "数", "弦"]], "6540": ["预后", "脉七八至，乱而无序，为热盛神乱、邪正交争之危候。痢后感寒，月水适至，三阳合病春温，热邪弥漫三焦，故脉数乱无序。后六脉俱无，乃战汗前阴极阳生之象，非死候也。", ["数", "乱"]], "6541": ["病机", "左脉中按数而有力主少阳阳明热盛，右脉软弱主脾虚气弱。发热口渴，舌干如沉香，额胁热，耳聋，便下二次热不除，为阳明少阳并病。数而有力为实热，软弱为正气不足。", ["数", "有力", "软", "弱"]], "6542": ["病机", "左脉弦数主肝火偏旺，右滑数主痰热内蕴。性急躁，右胁下疼，咳嗽喉干吐红，肠鸣泄泻。弦数为肝火犯肺，滑数为痰热灼伤血络，故咳红；肝木乘脾则肠鸣泄泻。", ["弦", "数", "滑"]], "6543": ["病机", "两寸短弱主肺气虚，左关大而有力主肝木实，右关滑主胃中有痰，左尺滑、右尺沉微主肾气不足。触怒晕厥，手足冷，汗出如雨，气息微，为肝气上逆、肺虚痰阻。脉短弱为肺虚，关大有力为肝实。", ["短", "弱", "大", "有力"]], "6544": ["病机", "两寸短弱，心肺之神不足，志愿高而不遂，郁结不舒，津液生痰不生血；关弦右关滑，木郁克土、痰浊内蕴。攻痰太过更伤心神，故昏乱无所摄持，癫狂悲歌骂詈。脉短弱正合神不足，弦滑示郁与痰，故治宜补养收敛心神兼清痰。", ["短", "弱", "弦", "滑"]], "6545": ["病机", "两寸软弱，心肺气虚。翁患𤻊疝，外治烂囊开子，胸中气满、汗出如流、终夜不寐、饮食大减、面青肌瘦，皆气耗神伤之候。寸脉软弱正应心肺不足，气虚不能摄汗安神，故见气满汗泄不寐，治当佐补于内以扶正气。", ["软", "弱"]], "6546": ["误治", "原文未识脉名，然述高年过劳伤食，市医概用消导，反加内热；张氏投人参致右胁胀痛，加木香、砂仁辛热止痛，益呕吐胀痛、大便燥结。此段主旨为误治致变：消导峻则伤脾，补早则壅气，辛热更助燥结，故列误治，警示高年虚实夹杂不可偏攻偏补。", []], "6547": ["病机", "左洪大右缓大，体丰嗜炙纵欲，年高躁急，跌后猝发左手足不动、口眼歪邪、神昏鼾呼、呼长吸短。洪大为气血上逆、肝阳暴亢，缓大示中气弛缓，故非寻常半身不遂，乃中风危候，症候甚恶，脉证相合示痰火壅塞、神机失用。", ["洪", "大", "缓"]], "6548": ["病机", "脉皆濡弱，气血俱虚。臀肛生毒，反复针溃插药凡八遍，脓血久耗，故脉濡弱不任。濡弱示正气不足、托毒无力，与反复红肿寒热、疮口难敛相应，说明久病正虚、脓毒未尽，治当扶正托毒而非徒事刀针。", ["濡", "弱"]], "6549": ["预后", "脉大为痢所忌，今两手俱大而无力，右关略滑，乃虚虚实实、不足中之有余。痢久里急后重、食减、潮热呕吐、声微气不续，形神俱弱而脉大无力，正合痢忌大脉之戒，示正虚邪恋、预后宜缓治补养兼清兼消，不可峻攻。", ["大"]], "6550": ["病机", "左弦大右滑大，饮食胸膈梗梗难下、便燥内热肌瘦。弦大为谋而不决、气郁成火，滑大为痰涎内壅，脾志不舒，痰火耗血故血少便燥、肌肉渐瘦。脉证合参，膈乃神思间病，气郁痰火为患，故当减想虑、断色欲、薄滋味，药乃有功。", ["弦", "大", "滑"]], "6551": ["病机", "脉来虚软，右半身不遂，元气不足也。虚软为气衰不振、血脉失充之象，气虚不能运血荣筋，故半身不遂。此案以脉定因，明示非风火痰瘀实邪，乃元气亏虚，法宜温补，使气充则血行、筋脉得养，与温补治法相应。", ["虚", "软"]], "6552": ["病机", "偏枯而见脉数，数主热，说明内热偏盛。原文直言\"症属偏枯，内热脉数\"，偏枯本属气血不荣肢体，今脉数则示内有郁热，热灼津血，筋脉失养，故内热与偏枯并见，脉数为内热之征。", ["数"]], "6553": ["病机", "原文\"六脉模糊\"为脉象描述而非具体脉名，故脉象要素从缺。右肢偏废而六脉模糊，模糊示阳气不振、湿痰内滞，气血运行不畅，脉道不充，故脉象模糊不清，主阳气虚而湿痰阻络，与偏废相应。", []], "6554": ["病机", "肢麻言蹇而\"脉来无力\"，无力即虚，主阳气亏虚。阳气亏则推动无力，痰滞脉络，气血不能充养肢体与舌本，故肢麻、言语蹇涩。原文断为\"阳气亏而痰滞脉络\"，脉无力正合虚象，非小恙。", ["虚"]], "6555": ["病机", "原文\"脉和，两尺濡细\"，脉和示整体尚平，两尺濡细则肾阳不足、阴无从生。阳衰则心脾失养，舌胖少液、艰于语言、灵机时窒，皆由真阳衰微、脾阳失根、心营失养所致，故拟方专主温补。", ["濡", "细"]], "6556": ["病机", "病后液亏，心脾失于滋养，舌大而蹇，脉见浮弦略数。浮弦示虚风内动、气机不敛，略数示液亏生内热，热扰心脾，舌本失养而肿大蹇涩，故脉浮弦略数，主心脾液亏兼内热之病机。", ["浮", "弦", "数"]], "6557": ["病机", "心脾气液两亏，舌根蹇涩，脉形濡涩。濡主气液不足、脉道不充，涩主血行不畅、津亏络滞，二者并见，正合气液两亏、痰阻机窍之机，故舌根蹇涩，治专培补兼豁痰利窍。", ["濡", "涩"]], "6558": ["病机", "舌本蹇涩、语音不清、目不能转，症本于虚，脉濡而涩，并不弦急。濡涩示气液两亏、血行不畅，非弦急则无实邪亢盛之象，阻之者疫气，然脉不弦急，说明虚为本而邪为标，故专主培补。", ["濡", "涩"]], "6559": ["病机", "肝肾阴亏，筋脉失养，寒从下袭，足指及两踝痛，发战连次，脉弦而长。弦主筋脉拘急、肝失柔养，长主邪气有余、病势深入，弦长并见示精血不足而寒袭筋脉，故当温养，拟方常服。", ["弦", "长"]], "6560": ["病机", "脉濡为营液内亏、脾虚湿滞之象，左略弦则肝木失养而筋脉不柔。原文谓“营液内亏，风寒乘虚袭入”，右偏肢节酸楚，正合濡主虚、弦主筋急。以胃气为主，谷食少则生血无多，故脉濡亦反映中焦化源不足，治当甘平柔润养胃和肝。", ["濡", "弦"]], "6561": ["病机", "右脉尚和示脾胃未大伤，左寸关略见弦动，乃心肝失养、浮火上炎之征。原文谓“营液内亏，心肝失养”，又兼脾虚痰酒中积，血虚失养则脉络牵掣、艰于举动。弦动见于左寸关，正合心肝阴亏而阳不潜藏，面赤唇红亦浮火之象。", ["弦", "动"]], "6562": ["病机", "左数右弦缓有年，形盛气衰，冬春之交真气不相继续，内风日炽。左数主肝阴不足、虚阳偏亢，右弦缓主脾土受克、运化不健。脉见弦数而缓，正合“内风日炽”之机，故见左肢麻木不仁、舌歪言蹇，属中络之候。", ["数", "弦", "缓"]], "6563": ["病机", "脉来濡细，濡主湿滞、细主阴亏，合而观之乃心脾液亏、内失滋养之象。原文谓“舌为心之苗，又脾开窍于舌”，心脾液亏则舌强语涩。濡细之脉不任峻补，故治以滋补脾阴、兼舒心系，从缓图之。", ["濡", "细"]], "6564": ["病机", "脉来濡细，与上证同属心脾液亏。濡为湿滞不运，细为营阴不足，心脾液亏则舌强音不清。原文直言“专主滋补”，正因濡细非实邪之脉，乃虚损之候，故以滋补为专法，不从痰火论治。", ["濡", "细"]], "6565": ["病机", "脉右濡而调，左大不弦。右濡示胃气本虚、中焦运化不足，左大不弦则肝木虽亢而未至劲急。原文谓“木不滋则邪亢，亢必侮土”，脘痛连胁乃肝络不和。左大不弦说明木郁尚可培养，故拟方温煦，从春令升发之意。", ["濡", "大", "弦"]], "6566": ["病机", "左弦大而虚，右濡涩不调。弦大为肝木亢而不柔，虚则营气不足；右濡涩为脾虚血少、脉道不利。原文谓“营气并亏，中无实火”，故时觉虚烦、近乎痫厥。弦大而虚正合木亢土弱、君火被扰之机，治以甘温补气调营。", ["弦", "大", "虚", "濡"]], "6567": ["病机", "右脉紧细而弦，右关浮大，寸略濡。紧细弦为木郁不达、营液内耗，浮大主虚阳上扰，寸濡则心营不足。原文谓“木火引动君火，营液内耗”，故烦扰不安、夜不得眠、胆虚而怯。脉紧细弦而关浮大，正虚而兼郁火之象，症纯属虚。", ["紧", "细", "弦", "大"]], "6568": ["病机", "原文谓脉左大而时见虚弦、右浮大而濡，且无数象亦劲急，说明非实热劲急之候。左大虚弦为肝血不足、气不帅血，右浮大而濡为脾阳中虚、血失滋养。故病机在脾阳中虚、气血失序，神魂不安、心无主而事不能决，与痫症、怔忡均异，治当补而参温疏。", ["大", "虚", "弦", "濡"]], "6569": ["病机", "原文述肝脾不调、正弱本邪时亢，又感外风兼挟积酒，留滞太阳少阳二经，蒸郁不达而日晡发热、脘次不舒。右脉见涩，涩主气机郁滞、血行不畅，正合外邪与积酒留滞、疏泄失职之机，故未宜进补，姑拟疏泄以宣通郁滞。", ["涩"]], "6570": ["病机", "原文言肝风挟痰上冲包络，气滞则厥，先笑而后肢节牵动，脉来弦细。弦为肝风内动之象，细为痰阻络脉、气血不充之征。包络与肝同属厥阴，故厥；近心故笑。脉弦细正合风痰上扰、气滞厥阴之病机，故拟用开法以宣窍涤痰。", ["弦", "细"]], "6571": ["病机", "原文谓太阳感风兼挟寒湿，颈项不便流入左臂，酸楚，又因敷治引动头风，肝阳未旺而外风引动内风，留滞于络。脉涩主营卫不畅、气虚痰滞，与素体气虚多痰相应。风为阳邪无定处，故症尚轻，宜宣理以通络祛风。", ["涩"]], "6572": ["病机", "原文述头风频发，太阳少阳兼症，营液素亏，脉来弦细。弦为风阳上扰、肝胆气逆之象，细为营液亏虚、脉道不充之征。营血不足则风易动而难息，故虽属太阳少阳兼症，实以营亏风动为本，难许脱根，治风先治血、肝脾兼理。", ["弦", "细"]], "6573": ["预后", "原文言营虚风动，跷脉为病，足挛难于行走，脉来促数。促数为阳热亢急、营阴亏虚而风动不息之象，跷脉失养故足挛难行。脉促数而症见挛急，正邪交争而阴血难复，故原文断为急切难愈，示其病程缠绵、预后较缓。", ["促", "数"]], "6574": ["病机", "原文述肝脾不调，脘次作胀，气阻于络，络血外溢，头风时发，脉来细涩。细为气血不足，涩为气阻络瘀、血行不畅。肝脾失和则气阻络伤而血外溢，头风时发亦由络脉不畅所致，脉细涩正合虚中夹滞之机，故当用宣理。", ["细", "涩"]], "6575": ["病机", "原文谓土不培木，虚风上升，脉来弦大。弦为肝风之象，大为虚阳浮越、脉道弛张之征。脾土不培则肝木失养，虚风因而上升，脉见弦大而非劲急，正属虚风内动之候，故当用调补以培土宁风，而非清泄。", ["弦", "大"]], "6576": ["病机", "脉象弦大为肝风内动、胃气受扰之征。弦主肝病，大示邪盛，肝风患胃则膈胀呕恶、饮食顿减。风阳上扰，胃失和降，故脉弦大而症见呕恶纳减，暂拟苦泄以折其势。", ["弦", "大"]], "6577": ["病机", "六脉不静，即脉象躁动不宁，为虚风内动之象。头晕心悸乃风阳上扰、心神不宁所致。脉不静反映阴不制阳、内风萌动，须安养调摄以复其常，非实邪为患。", []], "6578": ["病机", "脉来滑大，滑主痰，大主邪盛，由肝风内扇所致。风动痰升，上扰清窍则头晕多痰。滑大之脉示风痰壅盛，故治以柔肝熄风，使风平痰化而脉自和。", ["滑", "大"]], "6579": ["病机", "失血后脉来细数，细为阴血亏少，数为虚火内动。水亏火动，灼肺则气喘咳逆。细数之脉示阴亏火旺，久延恐成虚怯，故曰恐久延成怯。", ["细", "数"]], "6580": ["预后", "积劳内伤，咳血延至气喘，脉来软弱，为阴损及阳之候。软弱示气血俱衰、阳气不振，正虚已甚，故防其虚脱。脉症合参，预后堪忧。", ["软", "弱"]], "6581": ["治法", "咳血便溏，六脉无力，为脾肺两虚、土不生金之象。脉无力示正气亏虚，咳血伤肺，便溏属脾虚，故为怯之渐。当用补土生金法，培脾以益肺。", []], "6582": ["病机", "失血后咳呛便溏，六脉少力，不惟阴络有伤，阳气亦不足。脉少力示气血两亏，咳呛为阴伤，便溏为阳弱，故宜扶阳以生阴，阳生则阴长。", []], "6583": ["病机", "遗精咳血，络脉空虚，脉空虚，腰背作痛，神色㿠白，为怯症之根。空虚无脉气之充，精血亏耗，络脉失养，故见诸症。当以甘温补剂培其根本。", ["空", "虚"]], "6584": ["病机", "脉数无力，数因阳浮，无力为虚。失血后阴液内亏，阳气失所依附而浮越，故脉数无力。咳逆自汗乃阴不敛阳、阳不摄阴之象，病机在阴虚阳浮，治以潜阳摄阴。", ["数", "虚"]], "6585": ["预后", "六脉数虚，数主虚热，虚为不足。失血后咳逆不休、间有寒热，阴损及阳，气血俱亏，故脉数而虚。症延入怯门，草木难振，预后不佳，属虚劳重候。", ["数", "虚"]], "6586": ["病机", "脉浮数，时觉虚弦，重切无力。水亏不制相火，火升烁金则咳，伤阴络则动血。浮数为火旺，虚弦无力为真阴亦弱，故不特阴亏，真阴亦弱，治当潜阳育阴。", ["浮", "数", "虚", "弦"]], "6587": ["病机", "脉大而不和，虽无促数之象，而不能敛摄。大而无力为虚阳外浮，肾之下虚可见。虚则火升，烁金则咳，病机在肾虚火升、真元不摄，治以填补真元、体阴用阴。", ["大"]], "6588": ["病机", "脉虚无力，虚为阳气不足。气虚不任补，热之不热是无火，当责其阳。补火乃能生土，脉虚无力正是火衰土弱之征，后恐见喘急，急宜温补。", ["虚"]], "6589": ["病机", "左脉见涩，右濡弱无力，尺为甚。命火下衰，气不生阴，脾肾并虚，精液亦耗。涩为精血少，濡弱为气虚，尺甚则肾虚尤著，虚则两无所附，值肃令阳气渐藏，恐难资化育。", ["涩", "濡", "弱"]], "6590": ["病机", "尺脉总小，或大或濡，右大于左，有虚无实。尺小为肾命亦虚，气与阴未能骤复，脉随气升降为衰旺。此属肾脱非风，治以滋纳下焦，肾脾为关键。", ["小", "濡", "大"]], "6591": ["病机", "脉数，左略弦。数主木火，弦为厥阴之脉。风寒袭络，散入厥阴，两胁连背，咳呛痰红，此属木火。脉数弦示肝火偏旺，治拟轻剂宣泄，养血恐腻，温燥助火。", ["数", "弦"]], "6592": ["病机", "脉形见芤，为阴血亏虚、络脉瘀积之象。劳乏伤阴，烦火内动，火烁肺金，金令不肃，故咳呛狂溢、吐痰渐腥。芤脉主血虚失血，此处血由阳明火动，阴亏无以制火，夏令火旺，恐加剧，故脉芤提示阴血耗伤而火热内炽。", ["芤"]], "6593": ["病机", "脉来浮大，为劳倦内伤、气陷阴中之象。气陷则虚阳外浮，故脉浮大而无力。腰膝酸楚、便浊，皆气陷阴中、肾失固摄所致。浮大非实热，乃正气不足、虚阳上浮，故当用滋补以固本。", ["浮", "大"]], "6594": ["病机", "脉濡涩不调，为脾不统血、失血后气血两亏之象。濡主气虚，涩主血少，不调则营卫失和。神倦色黄、肌削，皆脾虚失运、气血不荣。夏令炎暑郁蒸，更耗气阴，故恐加剧。益气为主，补气生阴，脉象示正气亏虚。", ["濡", "涩"]], "6595": ["病机", "脉濡不数，为心虚肝脾液亏、正气亦亏之象。濡主虚，不数则内无实火。咳呛有痰、络伤失血，虽见症在肺胃，实因心肝受病，生血之源不旺，木火烁金。神倦色悴，脉濡不数，提示虚损而无实火，故拟柔剂滋养。", ["濡", "数"]], "6596": ["病机", "脉濡细，为火衰气陷、脾肾阳虚之象。濡细主气血不足，阳虚不能化气，则水道不行而肿；火衰不能生土，则便溏、神倦；肾不纳气则喘。脉濡细与气升、泻下焦相应，总皆火衰，故拟温补。", ["濡", "细"]], "6597": ["病机", "脉大而濡，为金不生水、津液二亏之象。大而濡软，非实热，乃气阴耗散、虚阳外浮。三消之症已具，津亏液涸，故脉形大而无力。专拟滋补，以复肺肾津液，脉象示虚多实少。", ["大", "濡"]], "6598": ["病机", "脉来右寸浮大，为风温伤肺化热、气逆咳呛之象。右寸候肺，浮大主风热在表，肺气不降，痰多色黄。风温化热，热壅肺络，故脉浮大而右寸独显。暂用泻白散清泻肺热，脉象示邪在肺卫气分。", ["浮", "大"]], "6599": ["病机", "六脉弦数，为肝络伤而津不上承之象。弦主肝病，数主热，血溢后阴亏火旺，肝络受伤，津液不能上承，故咳呛不止、咽痛失音。弦数并见，提示肝火内炽、阴津耗损，殊非浅恙。", ["弦", "数"]], "6600": ["病机", "久咳不已而脉数，非实热之数，乃腠理疏而精液亏，虚热内生之象。腠理不固则畏风，精液亏耗则脉数无力。此数脉主虚损，与畏风、久咳相应，故治以固养育阴兼治，非清散所能。", ["数"]], "6601": ["病机", "脉右濡，右候脾胃，濡为气虚湿滞之象。脾胃气虚则痰湿素蕴，中虚表阳亦弱，故畏风多汗；土不生金则肺虚咳呛，金不生水则肾阴亦弱，气不下摄。此濡脉主脾肺气虚、湿痰内蕴，与心跳目眩、纳减嘈杂、夜不安寐相应。", ["濡"]], "6602": ["病机", "左脉略弦，右浮濡。弦主气分不舒、胁肋掣痛；浮濡为卫表不和、风寒外袭之象。肺感风寒，营卫失和，故渐寒忽热、咳呛有痰；兼挟食滞则纳减便结、舌腻黄边红碎。此脉示表邪未解而气机郁滞，恐其喘急，故不宜过散。", ["弦", "浮", "濡"]], "6603": ["病机", "脉虚弦，虚为肺气不足，弦主气机不降、湿郁为患。肺虚不降则咳呛无痰，舌胖渐白乃湿蒸之征，非火旺烁津。此虚弦脉主肺虚湿郁、气逆不降，与咳呛无痰、舌胖白相应，故当用宣泄以化湿降气，不可作火旺论治。", ["虚", "弦"]], "6604": ["病机", "脉左弦而右濡。左弦为肝风大虚、气逆不降；右濡为肺虚不能通调水道。高原之水不降，肾阳亦衰，下不能摄，故咳呛喘急而二足作肿。此脉主肝肺肾三脏虚损、水气不化，与喘急、足肿相应，故专主温养。", ["弦", "濡"]], "6605": ["病机", "右脉濡涩，左虚弦。濡涩为脾阳已亏、暑湿未清，运化失司；虚弦为肝脾不和、气机郁滞。先咳后痢，痢止咳剧，畏寒热、纳减无味、神倦色悴，皆脾肺两虚之候。此脉主脾阳亏虚兼湿滞，与咳呛、纳减、神倦相应，故脾肺兼治。", ["濡", "涩", "虚", "弦"]], "6606": ["病机", "脉来弦大，弦为气逆，大为邪盛。咳频震络，络伤血溢，痰带血出，此肝肺气火上逆、络脉损伤之象。弦大之脉主气逆火动、络伤出血，与咳频、痰中带血相应。只宜薄味清上焦，不可温补壅滞。", ["弦", "大"]], "6607": ["病机", "脉来洪大，洪大为阳盛火旺之象。咳血见红而脉洪大，明示肺胃之火炽盛，迫血妄行，血不循经而外溢。此洪大脉主肺胃实火、血热妄行，与咳血见红相应，故治以甘寒清降，折其火势而血自宁。", ["洪", "大"]], "6608": ["病机", "脉涩为血虚不能充盈脉道，阴血亏虚则阳气失于依附，故言“阴不变阳”。血虚不能载气，气逆而喘；血虚阳浮，下午身热；下损及中，脾胃渐衰则饮食渐减。此脉涩主内伤失血后阴血亏虚、阳气浮越之病机，症见气喘、午后身热、纳减，属难愈之候。", ["涩"]], "6609": ["病机", "左脉浮数见芤，浮为气升，数为阴火潜动，芤主络血狂溢、营络大空。阴血暴失则阴不维阳，气随火升；向患痰喘，肺金清肃不降，金不生水，肾气亦亏，下不能纳气。此脉主阴血亏虚、阴火动而气逆上升之病机，治以纳气为主，参用养胃以生血。", ["浮", "数", "芤"]], "6610": ["病机", "左脉虚弦而数，虚为营络内伤、生源不旺，弦为肝失所养、脏燥动火，数为少阴火升、真阴被铄；右数而濡，为脾统失职、气阻于络。失血连发，心跳火升，皆由肝脾统藏失职、阴血亏虚而火动。此脉主营络内伤、脏燥动火、真阴被灼之病机，当燥令拟滋补参以味络。", ["虚", "弦", "数", "濡"]], "6611": ["病机", "脉退凉后浮濡，右涩不数，热时数而略弦。浮濡为风温湿邪留滞于络，涩为郁热不泄、络脉不畅，数弦为热时郁热内动。咳呛失血、寒热往来、胸闷纳减便泄，皆风湿湿邪郁于络、郁热不泄之象。此脉主风温湿邪留络、郁热不泄之病机，故拟轻剂清泄。", ["浮", "濡", "涩", "弦"]], "6612": ["病机", "脉来细涩，细为阴血不足、脉道不充，涩为阳明络伤、血行不畅。咳呛动肺，肺叶张动则动络，胃为多血之府，血随痰咯出，此属阳明络伤失血，与阴虚火旺者有别。细涩主络伤血少、肺胃气逆之病机，故未宜腻补，恐滋腻碍络。", ["细", "涩"]], "6613": ["病机", "脉大而弦，大为脾胃中虚、气不能摄，弦为冲脉应亏、肝木失和，少冲和之象。阳明多血之府，冲脉主一身之血，中虚气不摄血，血从外溢，连吐不止，左胁牵动即至。此脉主中虚气逆、血失统摄之病机，恐气逆狂吐而骤见虚脱，故血脱补气，不可过服纯阴及通络之剂。", ["大", "弦"]], "6614": ["病机", "脉细涩，细为肝肾阴亏、脉道不充，涩为络伤血少、血行不畅；火动则数，数为木火用事、火旺烁金。素嗜饮则肺胃郁热，咳呛失血连发，痰稠火旺。此脉主肝肾阴亏、木火刑金、络伤失血之病机，故专主清降，从肝、肺、胃三经调治。", ["细", "涩", "数"]], "6615": ["病机", "左脉弦数，弦为君火引动相火、肝阳不潜，数为虚阳不潜、阴精易泄；右滑大，滑为阴精易泄、相火妄动，大为虚阳浮越。操烦过度，心火引动相火，阴精不固。此脉主君相火动、虚阳不潜、阴精易泄之病机，故方专主滋摄，以滋水摄阳为要。", ["弦", "数", "滑", "大"]], "6616": ["病机", "脉数主热，湿热下注，故便浊。数脉为热邪内蕴之象，湿热蕴结下焦，分清泌浊失职，故见便浊。原文直言'湿热下注也'，脉数与湿热相合，法当分利，使湿热从小便而去，则浊自清。", ["数"]], "6617": ["病机", "脉涩少神，涩主血瘀气滞，少神示正气已伤。湿热下注兼努力伤络，络伤血溢，故尿血茎痛、腰膂酸痛。涩脉为瘀血阻络之征，破瘀分利则络通血止，与原文'努力伤络'相应。", ["涩"]], "6618": ["病机", "左脉虚弦，虚为营阴不足，弦属厥阴肝脉。努力滞气下归厥阴，兼涉太阳，营络受伤，故尿血、阴茎结痛。虚弦示肝营亏而气滞，拟用滋摄，正合虚弦之脉，当节劳调养以复营络。", ["虚", "弦"]], "6619": ["病机", "脉浮大而数，浮大示阴虚阳浮，数主热。肝脾阴络内伤，血渗下焦，故尿血。浮大而数非实热，乃阴伤络损、虚阳外浮之象，故养营为主，参用清络，不可纯用苦寒直折。", ["浮", "大", "数"]], "6620": ["病机", "脉来弦大，弦属厥阴，大为气旺而血失所摄。气不摄血，血无所归，归于厥阴则为尿血，随时发作。弦大示肝气偏旺而统摄无权，故培补为主，参以温宣，使气能摄血而归经。", ["弦", "大"]], "6621": ["病机", "脉形濡涩，濡主湿、主气虚，涩主血滞络伤。劳力伤络，左偏少腹结痛，小便见血，乃肝脾两伤、气血俱损之候。濡涩并见，示虚中夹滞，故原文断为'肝脾两伤，急切难效'。", ["濡", "涩"]], "6622": ["病机", "脉来弦濡，弦属厥阴少阳，濡主气陷湿滞。劳乏伤气，气陷下焦，少腹作痛，便浊囊胀。弦濡示厥阴少阳之气不舒而兼湿，故厥阴少阳兼治，疏达与渗利并行。", ["弦", "濡"]], "6623": ["病机", "脉弦右涩，弦属厥阴，右涩示右部血少气滞。肾水不足，水中火动，相火寄于厥阴，下不能摄，尿道召阻。弦为相火内动之象，涩为阴亏血滞之征，故滋补为主，滋水以制相火。", ["弦", "涩"]], "6624": ["病机", "左脉略弦，右数而紧，弦主厥阴气滞，数紧主湿热内蕴。湿热下注厥阴，气陷而少腹滞痛、水道有阻，发为膏淋；茎中不畅、左囊作胀，皆肝经湿热气滞之征。脉弦数紧与湿热滞络、气机不畅相应，故宜疏理。", ["弦", "数", "紧"]], "6625": ["病机", "脉大数，大主邪盛，数主热，为湿热滞于下焦之象。湿热蕴结，尿道通而艰出口，是热郁气阻、水道不利。脉大数说明邪热壅盛于下，故拟清理，并须节劳以防火动助湿。", ["大", "数"]], "6626": ["病机", "脉弦而涩，弦主气滞，涩主血少精亏。素体劳乏，气滞下焦，肾虚不摄，气化无权，故小便淋沥、少腹胀痛、神倦色悴。弦涩并见，示气滞与肾虚并存，恐其腹满，急宜滋补以固根本。", ["弦", "涩"]], "6627": ["病机", "脉不应指，即脉来沉微难寻，为阳气衰微、不能鼓动血脉之象。腹胀气喘而脉不应指，说明脾肾阳衰，水气不化，上逆迫肺。此脉与脾肾阳衰之腹胀气喘相应，故仿金匮肾气法温阳化气。", []], "6628": ["病机", "脉来弦软，弦主气机不畅，软主阳气不足。腹鸣作胀而脉弦软，是脾阳衰微、运化失职、气滞于中所致。软而不实，说明非实邪壅滞，乃虚寒之气作胀，故法当温补以复脾阳。", ["弦", "软"]], "6629": ["病机", "左脉濡涩，右尺亦弱，濡主湿滞，涩主阳衰血少，弱主虚。命阳下衰，火不生土，脾阳亦弱，痰湿阻滞，故胱节作肿连及肾囊，肺虚咳呛喘急。濡涩弱并见，示下焦阳衰、湿阻气弱，拟从下焦温补。", ["濡", "涩", "弱"]], "6630": ["病机", "脉虚弦而数，虚主营液亏虚，弦主肝木失养、气机郁滞，数主郁蒸络热。素体阴虚，肝木侮土，脾阳已弱，土不胜湿，故腹胀足肿、饥削；肿减而胃纳艰化，脉虚弦数示虚中夹郁热，恐虚不能复，扶胃为主。", ["虚", "弦", "数"]], "6631": ["病机", "脉涩，左略见虚弦，涩主阳衰血滞，虚弦主土虚木郁。火弱无以生土，阴水不行，腹胀作肿、两足连囊、举动喘急，皆脾肾阳虚、水湿不化之征。涩而虚弦，说明虚寒水停兼气滞，故从中下二焦温理。", ["涩", "虚", "弦"]], "6632": ["病机", "右脉滑浮，滑主湿浊内蕴，浮为气机外浮不敛；左虚数略弦，虚数示肝阴不足而虚热内扰，弦为肝气郁滞。重切皆濡，濡主湿困脾阳。合观腹胀纳减、便溏溲短涩，正是肝脾失调、气阻经腠、水道不畅之象，脉与症合，故断为脾虚湿滞、肝郁气阻之病机。", ["滑", "浮", "虚", "数"]], "6633": ["病机", "脉来左虚弦，右数动，直来直往。虚弦为肝阴亏而木亢，数动直来直往则营阴内亏、中无涵蓄，脉失柔和之象。原文谓'营气二亏，中无涵蓄，似于此症不符'，正恐胀满之症与虚脉相悖，故拟培土柔肝、温疏下焦，攻补皆须斟酌，示脾虚木亢、气滞水阻而正气已伤之病机。", ["虚", "弦", "数", "动"]], "6634": ["病机", "脉濡不弦，濡为脾阳衰而湿不化，不弦则肝木之亢已不显于脉。原文谓'木亢乘土，脾阳大衰'，肌削色黄乃虚极现中央正色，非因湿；舌光脱液、渴不多饮，又见液耗。脉濡不弦正合脾阳大衰、运化无权之机，故补则胀、攻则虚、寒温皆碍，处方殊难，属虚鼓重候。", ["濡"]], "6635": ["病机", "脉形濡细，濡主脾阳不振、湿浊内停，细主阴血亏少、脉道不充。原文以肌削色黄属脾主肌肉，舌干属肾主五液，肝木独亢则腹胀而坚、食入即胀，症属虚鼓。濡细之脉正示脾肾两亏、气血不足而木亢乘土，虚多实少，故云极难理治，姑拟疏补并进。", ["濡", "细"]], "6636": ["病机", "脉形濡细，濡为脾土中虚、湿滞不运，细为气血两亏、脉道不充。原文引《内经》'诸气𪱥郁，皆属于肺'，而言气由腹中上升直从下焦丹田出，是脾土中虚、肝木不达，鼓动之气失于制约；腹胀便泄亦脾虚木郁之征。濡细之脉正合中州虚馁、肝木不达之病机，故先振定中州、佐以温疏。", ["濡", "细"]], "6637": ["病机", "右濡涩，左虚弦亦见涩象。原文谓'血少则涩，营不行于脉中也；土弱则濡'，濡为脾土弱而木亢侮土，涩为心血亏少、营血不充脉道，虚弦为肝阴不足而木气偏亢。胀而兼痛随时发作，正合操烦过度、心血先亏、肝脾不滋、木亢侮土之病机，故发时温疏、平时甘润滋养。", ["濡", "涩", "虚", "弦"]], "6638": ["病机", "脉濡细而涩，濡主脾阳不足、水湿不化，细主阴血亏少，涩主血少气滞、脉道不利。原文谓肾阳下虚、火不生土，气陷于下则少腹不坚、手足俱肿；舌干红少液又见真阴亦亏。濡细涩之脉正示脾肾阳衰、阴阳两亏而水湿内停，滋阴则滞气、补火则烁阴，恐成虚鼓，故以善遣为要。", ["濡", "细", "涩"]], "6639": ["病机", "脉形弦细，弦为肝木偏亢、气机郁滞，细为气血两亏、脉道不充。原文谓脾肾阳衰，腹胀足肿随退随发、肌削色黄，症属虚鼓；屡经克伐元气大伤，故脉见弦细而非实大。弦细正合正虚邪恋、脾肾阳衰而木气乘之之病机，正气旺乃能胜邪，故惟温补一法，参金匮肾气丸。", ["弦", "细"]], "6640": ["病机", "脉涩为脾肾阳虚、水湿内停之象，左略见虚弦则肝木失于温养。原文“火弱则无以生土，阴水不行”致腹胀作肿、足连囊、举动气喘，皆由火弱水泛、气机壅滞。涩主血少气滞，虚弦主土虚木乘，故治从中下二焦温理，以复火土之运。", ["涩", "虚", "弦"]], "6641": ["病机", "脉虚弦而数，虚为脾阴已弱、营液亏耗，弦为肝木失养、时或侮土，数为郁蒸终热之征。原文“土不胜湿，腹胀足肿，渐致肌削”正是脾阴弱而湿滞、肝木乘土之候。肿势略减而胃纳艰化，脉仍虚数，说明虚热未清、化机未复，故扶胃为主。", ["虚", "弦", "数"]], "6642": ["病机", "脉形浮濡，浮主湿郁肌表，濡主土虚湿胜。原文“土不胜湿，归于肌腠之间，蒸郁成黄”，湿郁肌腠不得外达，故脉浮；脾土虚弱不能运湿，故脉濡。此脉象直接说明湿郁发黄之病机在脾土不运、湿泛肌表，故治以温健为主，参用淡渗。", ["浮", "濡"]], "6643": ["病机", "右脉虚弦，右关候脾，虚为脾土不足，弦为湿郁气滞。原文“服温剂，色黄更甚，黄为土之正色，因湿外现”，说明温剂未能化湿，反使湿郁外显。脉虚弦正合脾虚湿滞、土不运化之机，故仍以培土为主，兼温利以化肌腠之湿。", ["虚", "弦"]], "6644": ["病机", "脉大略滑，大为脾胃中虚、气机外浮，滑为湿阻气壅。原文“脾胃中虚，土不胜湿，气阻作胀，左胀不舒”，左胀不舒乃肝木乘土之象。脉大非实热，乃中虚气不能敛；滑非痰食，乃湿滞未化。故治以培土为主，参用泄木，使土运而木平。", ["大", "滑"]], "6645": ["病机", "脉形浮濡，浮为阳虚水泛、气不归元，濡为肾阳下虚、阴翳日积。原文“肾为水脏，真阳下虚，阴翳日积，囊、足肿”，真阳不能化水，水湿泛滥于下，故脉浮濡。此脉象说明病本在肾阳不足、水气不化，故参肾气法以温阳化水。", ["浮", "濡"]], "6646": ["病机", "脉细见涩，细为营血不足、木郁乘土，涩为湿滞气阻、暑湿困遏。原文“木郁乘土，腹胀色黄，近感暑湿，寒热类疟，胀势加剧，舌白而少液”，脉细涩正合土虚木郁、暑湿内阻之机。细涩示正气已伤而邪未透达，故先疏其气，然后达邪，否则恐其中满。", ["细", "涩"]], "6647": ["病机", "本段未出脉名，专论下痢后诸症归属脾病之机。原文“脾主四末，虚则湿滞于络，而肢节酸楚，气不行也”，又言“脾阴即血”“土燥岂能生物”，强调脾土须得血润气煦方能养筋平木。此段主旨在于阐发脾阴血润泽、气机和煦之病机，故治总以治脾为主，拟方温健。", []], "6648": ["病机", "脉软无力，是脾土阳气衰微之象。痞结日久延及腹痛、食减、便溏，皆脾阳不振、运化失司所致。脉软主虚，无力主阳气不足，故断为脾土阳衰，殊非轻候，提示病机在阳虚而非实邪。", ["软"]], "6649": ["病机", "脉形濡细，濡主湿滞、细主营血亏少。阴疟淹久，余邪未清而营液素亏，肝脾失养，营血益耗，故见舌中脱液、肌削色黄、宿痞作胀、呕逆。濡细合示气弱血耗、湿滞中焦，恐其中满，故培中为主兼疏达。", ["濡", "细"]], "6650": ["病机", "右脉略涩，涩主营络阻滞、血行不畅；左见虚弦，弦主肝木亢盛，虚则肝脾亏虚。木亢乘土，虚邪结痞，营络阻滞致八月愆期，阴疟后肝脾益亏。涩弦并见，示肝郁络阻而脾土已虚，故不必急于通经，健脾养肝渐复。", ["涩", "虚", "弦"]], "6651": ["病机", "右脉大而见濡，左部亦弱，并无弦急之象。大而濡为气虚湿滞、脾土不足，弱主营气二亏。肝邪结痞侮土作痛呕逆，木托根于土，土弱则木病。脉无弦急，说明非肝木亢急实邪，乃积劳内伤、木失所养，故温养扶脾柔肝。", ["大", "濡", "弱"]], "6652": ["病机", "左脉弦主肝木亢盛，右沉实主胃气素旺、中脘结痞、气陷下趋。过食伤中，暑湿内结，土弱木亢，故胁腹掣痛、便泄成利。弦与沉实并见，示木亢乘土而中焦实滞，故消补参用，佐辛温升降之品。", ["弦", "沉", "实"]], "6653": ["病机", "脉弦促不伦，弦主肝木为病，促主气机急促不匀。营液内亏，血不营筋，因风牵掣，木邪结痞作胀，表虚多汗、心跳时眩，皆肝阴不足、筋脉失养之候。弦促不伦示肝脾阴亏而风动，故拟滋补专理肝脾之阴。", ["弦", "促"]], "6654": ["病机", "脉弦紧实，弦主厥阴气滞，紧主寒凝收引，实主邪结有形。寒热之后厥阴气滞，小腹痞痛归于右偏，脉见弦紧实，说明寒凝气滞、结聚不散，属实证可疏，故宜疏达以行气散结。", ["弦", "紧", "实"]], "6655": ["病机", "脉形浮濡，浮主复感外邪、病位偏表，濡主湿滞、气阴不足。病后肝脾已乏，痞胀腹膨，近兼复感寒热，色黄而泛，阴亏内热。浮濡示正虚兼感、湿滞未化，恐其肌削，故当加意调摄。", ["浮", "濡"]], "6656": ["病机", "脉弦为肝邪偏旺，促为气机郁结而数中一止，合见则肝邪结痞、侮土作痛。原文点明「气弱而营液亦亏」，故弦促非实热壅盛，乃肝郁乘土、气血营液不足之象，痛由气结不通而作，治当酌进滋养以柔肝扶土。", ["弦", "促"]], "6657": ["病机", "脉来细软，细为营血不足，软为气弱不振，合之则中土衰馁。原文谓「土衰木乘」，纳食呕吐正因脾胃无力受纳，肝木乘虚而犯，胃气上逆。细软非实邪之脉，故宗仲景法以温健中土、平木降逆为主。", ["细", "软"]], "6658": ["病机", "右脉浮濡，右候脾胃，浮而濡为胃阳中虚、湿浊不化；左促数略弦，则肝邪偏亢、郁而化热。原文谓「土不培木，肝邪必亢」，故时胀、呕逆、味酸苦，皆土虚木乘、胃失和降之候，治以培中为主，参用温疏。", ["浮", "濡", "促", "数"]], "6659": ["病机", "脉形濡弱，濡为湿滞、弱为气衰，合见则中气郁滞而不足。原文谓「气郁伤中，食入作呕，阻于胃口之下」，正因中焦气机不畅、升降失司，食入不能下行而反逆。所阻者气而非火，故脉不数不滑，体弱境难，恐其难以速健。", ["濡", "弱"]], "6660": ["病机", "脉形见涩，涩主气滞血少、脉道不利。原文谓「胃气大虚，纳食减少」，久患痰喘更耗中气，胃虚不能纳运，气机壅滞故脉涩；呕逆乃胃气上逆之兼症。涩非实邪壅塞，乃虚中夹滞，故暂拟和降以调其胃。", ["涩"]], "6661": ["病机", "脉来濡弱，弱为胃气中虚，濡为气不充脉。原文谓「土不生金，兼患咳呛」，纳减呕逆是胃虚失纳，咳呛则母病及子、肺失所养；神倦色悴亦气虚不能外荣之征。脉证相合，故酌培补中气，冀其渐复。", ["濡", "弱"]], "6662": ["病机", "脉形濡细，细为阴血不足，濡为气弱湿滞。原文谓疟后未复，木邪克土，中气受伤而胃阴亦耗，故痞胀作呕、舌中脱液。濡细正合气阴两伤、中焦失运之机，虚而兼滞，恐其中满加重，治当顾护胃阴、扶土抑木。", ["濡", "细"]], "6663": ["病机", "原文未识脉名，仅言「六脉模糊」，属纯描述，故脉象要素从缺。模糊者脉体不清、界限难辨，多因湿痰壅阻、清阳不运，气血运行不畅而脉道不利。原文明言「乃由湿痰所阻，清阳不运」，胸次作痛即痰湿痹阻胸阳之候，故仿平胃法化湿运中。", []], "6664": ["病机", "脉沉主里，胸闷作痛、短气而脉沉，说明病不在表而属清阳失展、气机不利。清阳不升则胸中阳气痹阻，故闷痛短气；沉脉应之于里，正合气机内郁、阳不布展之机，故宗《金匮》法以通阳宣痹为治。", ["沉"]], "6665": ["病机", "脉数无力，数则为热、无力为虚，合喘逆自汗，是阴液涸竭而阳气浮越于外，气衰不能纳摄。阴涸则阳无所附，故脉数而无力；气衰失纳则喘逆自汗并见，法当收摄固元以纳浮阳。", ["数", "虚"]], "6666": ["病机", "脉沉气喘，背冷腰痛，沉脉主里主虚，说明病在肺肾而属虚寒。肾阳不足则不能纳气，故气喘；阳气不充于背则背冷，腰为肾府，肾虚寒则腰痛。脉沉与肺肾虚寒之症相应，法当温补。", ["沉"]], "6667": ["病机", "脉来细软，细为阴血不足、软为气衰无力，合举动喘促，是元海无根、气逆上泛。下元虚衰不能摄纳，气不归元而反上逆，故喘促；细软之脉正示根本空虚、气失固摄，理宜补纳。", ["细", "软"]], "6668": ["病机", "右脉弦滑，弦主饮主痛、滑主痰，右脉候中焦脾胃，合喘急多痰，说明中气虚而停饮上逆。脾虚不能运化水湿，饮邪停聚上逆犯肺，故喘急多痰；弦滑之脉与停饮痰浊相应，法当燥土祛邪。", ["弦", "滑"]], "6669": ["病机", "脉来细涩不弦，细为虚、涩为滞，不弦则非实邪，合咳痰喘急、两足渐肿，是脾阳中虚、土不生金、肃令不降。脾虚不能制水，水湿下溢则足肿；肺失肃降则咳喘。细涩之脉示虚滞，故先从气分调治。", ["细", "涩"]], "6670": ["病机", "脉见虚弦，虚为素体不足、弦主饮主痛，合咳呛多痰、感邪发作近乎哮喘，说明肺肾两虚而痰饮内伏。肺虚易感外邪，肾虚不能纳气，痰有窠穴故难于脱根；虚弦之脉正示正虚邪伏，故肺肾兼治。", ["虚", "弦"]], "6671": ["病机", "脉数右更浮，数为热、浮为邪在表，右脉候肺，合喘急痰热上蒸，说明真阴本亏、虚火上炎烁肺，兼外邪引动。肺受火烁兼感外邪，痰热有升无降，故喘急愈发愈密；数而右浮正合肺热兼表之机，益气为主佐以凉泄。", ["数", "浮"]], "6672": ["病机", "脉形濡弱，濡为湿象、弱为气虚，合之见肺俞感寒而痰喘频发。原文谓“表虚则外感易入，气弱则顽痰日蒸”，正说明濡弱之脉反映表气不固、中气虚弱，痰湿内蒸上逆。脉不任按，故现当平复，治以益气滋阴，冀得希发，属本虚标实之候。", ["濡", "弱"]], "6673": ["主病", "右脉弦数，弦主肝风，数主热，合见肝风挟痰。原文“肢麻头晕”为风痰上扰清窍、旁走四肢之症，右脉候气，弦数示风火内动、痰随气升。故惟恐仆跌，乃风阳上冒、痰蒙清空之危候，脉症相合，主肝风痰热之病。", ["弦", "数"]], "6674": ["病机", "本段未识脉名，专论脾胃气虚、湿痰中积之病机。原文谓湿痰“附于皮膜之间，流注脉络”，又值湿令，说明气虚不能运化水湿，痰湿流注经络。以益气为主、参用疏涤，正是针对脾虚湿痰之本虚标实而设，脉象虽缺，病机可明。", []], "6675": ["病机", "脉形浮大，浮为气虚外浮、大为虚火不敛。原文“脾胃气虚，土不生金，湿痰作呛”示土虚金弱、痰湿上逆；又“胃中虚火烁津，所吐之痰皆胃汁”说明虚火灼津。浮大之脉正合气虚火浮之机，故拟温润之剂，益气生阴，使虚火降而痰呛平。", ["浮", "大"]], "6676": ["病机", "左脉弦数，弦主木火、数主热；右涩示湿滞血少。原文“肾阴下虚，水不滋木，木火偏亢”致虚痰结核溃脓、耳中出水，乃阴虚火旺、痰火凝结之候。素体有湿，火必兼风，蒸热上升，故脉左弦数右涩，拟方滋摄以滋水制火、摄纳浮阳。", ["弦", "数", "涩"]], "6677": ["病机", "脉濡数，濡主湿、数主热，然原文明言“中无实火”，故数非实热，乃脾虚痰湿壅滞、肝木不达引动内风所致。风与痰凝，清阳内陷，发为癫疾。濡数之脉反映湿痰内盛、虚风扰动之机，治以益气为主，培土以熄风化痰，非清泻实火之法。", ["濡", "数"]], "6678": ["病机", "脉形浮濡，浮示肺气不敛、虚阳上浮，濡为湿滞气弱。原文“肺气本虚，金不制木，肝邪偏亢”致左胁掣痛连及腰脊，乃肺虚不能平木、肝络失和之候。浮濡之脉正合肺虚湿滞、肝邪偏亢之机，故拟培补参以宣络，补肺以制木、通络以止痛。", ["浮", "濡"]], "6679": ["病机", "脉象沉弱不扬，沉主里、弱主阳虚，合见中下焦阳微。原文“痰饮上泛，纳食艰运”正是阳微不能化饮、脾运失健之症。沉弱不扬说明阳气衰微、饮邪内停，故治以通阳涤饮法，温通中下之阳以化上泛之饮，脉症相应，病机昭然。", ["沉", "弱"]], "6680": ["病机", "脉细涩而濡，右部略弦，乃肝木失荣、脾土先虚之象。细涩为血少，濡为土弱，弦为木旺。原文谓“藏血少则槁，虚火妄动，筋燥则牵掣，气升为眩”，正合细涩濡之阴血亏虚、虚火内动；右部略弦则木克土，中阳必亏。故主培土养阴、佐以辛温。", ["细", "涩", "濡", "弦"]], "6681": ["病机", "脉左虚弦、右濡，乃胃虚气弱、湿积不化之悬饮证。左虚弦为肝木乘胃，右濡为脾湿不运。原文谓“清晨吐水，乃觉酸”“按之作水喜，其中有窠”，水饮停聚，胃气上逆。虚弦濡并见，说明正虚饮停，故拟培补涤饮。", ["虚", "弦", "濡"]], "6682": ["病机", "脉涩略弦，右部未和，乃脾阳中虚、营气不足兼少阳疟邪未净之象。涩为血少气滞，弦为疟邪归少阳。原文谓“元虚未复，余邪归于三阴，从少阳发，起患阴疟”，正虚邪恋，故脉涩而略弦。治以补气和营、参以辛温。", ["涩", "弦"]], "6683": ["病机", "脉形濡弱，乃阴疟日久、营气并亏之候。濡弱为气血两虚、脾土不运。原文谓“寒热已不准期，营气并亏”“面黄体软，舌干少液，纳减时呕”，皆脾虚营亏之症。脉证相合，故当用培补，不可再散。", ["濡", "弱"]], "6684": ["病机", "脉随寒热为紧数，总之虚弦而促，乃暑湿郁蒸、疟久脾虚、气弱营耗之象。紧数应寒热发作，虚弦促为真元已亏、有虚无实。原文谓“肢节酸麻，汗出不禁，嘈杂能食”，皆虚象。故急宜培补，不可攻伐。", ["紧", "数", "虚", "弦"]], "6685": ["病机", "脉形濡细，左部略数，乃久疟伤阴、金水不生、肝阴亦弱之候。濡细为气阴两虚，略数为虚热内扰。原文谓“金不生水，肾阴先亏，水不生木，肝阴亦弱”“并无虚急之象”，说明正虚邪恋，宜补不宜攻，和理营卫、滋养金水。", ["濡", "细", "数"]], "6686": ["病机", "脉左关尺微弦，右关见弱，乃少阳疟邪内陷、胃气大虚之象。微弦为伏邪未透，右关弱为谷气太少。原文谓“伏邪渐深，胃中津液被烁”“有胃气则生”，故以养胃为主，补气生阴，待胃气复而后可攻邪。", ["弦", "弱"]], "6687": ["病机", "左脉虚弦，右关较大，乃疟后营气二亏、心肝脾三脏失养、浮阳上升之候。虚弦为肝阴不足、虚风内动，右关大为脾虚不运。原文谓“心烦健忘，头痛耳鸣”“虚则神魂不安”，故拟养心为主，以安神魂。", ["虚", "弦", "大"]], "6688": ["病机", "右脉少冲和之气、左更濡弱，为脾胃正气亏乏、气血津液并耗之象。暑湿久羁，湿伤脾则神倦色黄、胃不思纳，暑伤气则舌光脱液、痰随气涌。脉失冲和柔和，正合「正气先亏，久而津液亦耗」，故高年虚乏难支，属本虚标实之候。", ["濡", "弱"]], "6689": ["病机", "脉弦而数，弦为肝木之象，数为热盛之征。阴疟日久，肝阴内伤，络脉郁热，热迫血动，故见动血。弦数并见，说明病不在表而在肝络，热由阴伤而生，非实火可比，故用参一柴胡法和解泄热、养阴和络。", ["弦", "数"]], "6690": ["病机", "久疟伤脾，脉见虚弦。虚为正气不足、脾阳衰弱，弦为木气乘土、疟邪未净。色黄乃脾虚湿郁之征。原文谓「阳弱则阴无所附」，说明阳虚不能温煦，阴血失于依附，故治宜温补，而不专治少阳，重在扶阳健脾。", ["虚", "弦"]], "6691": ["病机", "阴疟淹久，脉形濡弱。濡弱为阳气衰微、中气不足之象，故原文谓「阳衰不能卫外，中气亦弱」。阳虚则卫外不固，中弱则运化无力，疟邪久恋而正虚难复，故拟温理之法，温阳建中以复其本，非单纯截疟。", ["濡", "弱"]], "6692": ["病机", "左脉略弦，右濡。左弦为肝阴内亏、木火偏亢，右濡为脾土不足、气血生化乏力。疟久不止，肝阴亏而火升，血随火升，举动鼻衄，正是弦脉所主之肝火动血。故拟填补肝肾，不专治疟，重在培本潜阳。", ["弦", "濡"]], "6693": ["病机", "脉形濡细，濡为气虚湿滞，细为营液亏少。阴疟淹久，余邪未清，营液素亏，肝脾失养，故舌中脱液、肌削色黄；宿痞作痛、甚则呕逆，乃中虚气滞、脾运不健。脉症合参，虚多实少，恐其中满，故培中为主，参用疏达。", ["濡", "细"]], "6694": ["病机", "脉来弦细，弦主肝木、细主阴血不足。阴疟淹久，肝阴内亏，木失柔养则弦，营血亏少则细。寒重热轻为阳虚阴盛，心跳头痛乃肝阴亏虚、虚阳上扰。脉症相应，故治以和营兼泄少阳，养肝阴而清透疟邪。", ["弦", "细"]], "6695": ["预后", "原文未识出具体脉名，仅言「色脉少神」。久疟不已，咳逆盗汗，已见肺脾两伤、气阴耗散之象；色脉俱少神气，说明正气衰败、胃气不复。故断为「殊非轻候」，属预后不良之征，提示正虚邪恋、生机不振。", []], "6696": ["病机", "原文仅言「脉不条达」，未出具体脉名，指脉气郁滞不畅、失其柔和条畅之象。暑湿伤气，气机壅遏，故脉不条达；寒热、腹痛兼胀，为太阴疟邪踞中焦、气机不利之候。脉不条达正反映湿阻气滞、太阴脾土受困，与寒热腹痛腹胀相应。", []], "6697": ["预后", "原文「色脉少神」，指脉象与面色皆乏神气，非具体脉名。久泻不止，脾肾阳衰，清阳不升，故色脉失神。脉少神为阳气衰败之征，提示病情深重，故断为「殊非轻恙」，属预后不良之论，与久泻、脾肾阳衰相应。", []], "6698": ["病机", "六脉细软，细为阴血不足，软为阳气衰弱，久痢延及腹胀，脾肾阴阳俱伤，脉道不充、鼓动无力，故见细软。原文断为「阴阳两伤」，正合细软之象，与久痢腹胀相应，故主张温补以复阴阳。", ["细", "软"]], "6699": ["预后", "脉微为阳气衰微、鼓动无力之象。久痢伤及命门真阳，阳气衰败，故脉微。原文断为「命阳衰也」，并警示不急进补恐延成肿胀，说明脉微主阳气将竭、预后堪忧，与久痢、命阳衰相应。", ["微"]], "6700": ["病机", "脉数为热象。湿热内侵，蕴结肠胃，热邪鼓动血脉，故脉数；湿热下迫，气机壅滞，故痛泻。脉数与湿热内侵、痛泻相应，数而有力为实热之征，说明本段以湿热病机为主。", ["数"]], "6701": ["兼症", "脉弦右甚，弦主肝胆气郁、饮邪内停，右甚则病偏于脾肺气分。痢疟寒热往来、胸闷呕逆、舌糙白不渴，为少阳枢机不利、湿浊内阻；向患头风痛归左偏，营液素亏。脉弦右甚与诸症并见，故云「似非所宜」，属兼症辨析。", ["弦"]], "6702": ["病机", "脉形濡弱，濡主湿、弱主气虚。脾虚挟湿，营液亦耗，脾土肌肉既弱，不能达邪，暑湿积冷陷于下焦，故见下痢。濡弱之脉正反映脾虚湿困、正气不足，与脾虚挟湿、外感下痢相应，故先以培中为主。", ["濡", "弱"]], "6703": ["病机", "脉右濡左不弦而涩，右濡为脾虚湿滞，左涩为营血不足、气机不畅。暑湿伤脾，气弱不化，冷物阻滞中焦，气陷而痢，日数十行、里急后重、舌黄腻。脉右濡左涩正合脾阳既虚、不能达邪之机，故先培补以清升浊降。", ["濡", "涩"]], "6704": ["病机", "右脉虚弱，为脾胃两虚之征。原文谓下痢大势已减而胃渐开，然时觉嘈杂，乃中虚气馁、冲和之气虽在而力不足；左部略大，示暑湿余邪未净。脉虚主正气不足，弱主中州失运，故不可徒事疏化，当培补本原，使清阳自升，略参疏品以清余邪。", ["虚", "弱"]], "6705": ["病机", "脉促数而弦，数主热，促示郁滞不畅，弦为木旺克土。原文谓暑湿伤脾、疟后兼利经年，大便仍泄、肌削色黄、食不甘味，显系脾土中虚、清阳下陷，而郁火未清。促数应郁火内扰，弦应土虚木乘，故治以培土为主，参用疏达以解郁火。", ["促", "数", "弦"]], "6706": ["病机", "右脉略数，右候肺脾，数主热。原文谓暑湿蒸热、因疟转痢，气滞于下而里急后重，舌白渐黄，是暑湿化热、郁于气分，脾土受困而清浊不分。脉数不甚，示热未炽盛而湿滞偏重，故以升清为主，使清阳上升、湿浊下行，则气滞可解。", ["数"]], "6707": ["病机", "脉来见濡，濡主湿、主气虚，为脾虚湿滞之象；左略弦，弦应木旺，示土虚而肝木乘之。原文谓脾虚下痢久必传肾，肾气素亏、关门不固，故濡脉既应脾虚湿盛，又应肾气不固。治拟培补，使脾肾气复则关门自固，多服见效。", ["濡", "弦"]], "6708": ["病机", "脉见虚弦，虚主正气不足，弦主痛、主木旺。原文谓久痢脾虚、气陷于下，少腹增痛，是脾肾气虚而肝木乘虚作痛。肾为胃关、主二便，久痢及肾则关门失摄。虚弦之脉正合气虚而痛之机，故拟温摄，温补脾肾以摄下陷之气。", ["虚", "弦"]], "6709": ["病机", "脉形濡弱，濡主湿、弱主气虚，为脾肺气虚之象。原文谓便泄淹久、时或带血、肛门作痛，属脏毒，由脾肺气虚下陷所致。气虚则湿滞不化，下陷则血随气泄，故脉见濡弱。治参真人养胃法，补脾肺之气以升举下陷，气复则湿化血止。", ["濡", "弱"]], "6710": ["病机", "左脉弦涩，弦主寒、主痛、主木旺，涩主气滞血少。原文谓暑湿郁久入冬感寒，归于小肠发为阴疟，疟止患痢带红，脾虚气陷，余邪下趋。弦应寒邪郁滞，涩应气血不畅，故不可纯补，当参败毒及清暑益气，升清以透余邪。", ["弦", "涩"]], "6711": ["病机", "右脉浮濡，浮主表阳虚浮，濡主湿、主气虚。原文谓脾命阳衰、火不化土，表阳亦虚于下焦，便泄淹久兼畏风。命火衰则土不生，表阳弱则卫外不固而畏风，湿滞于中故濡。浮濡并见，示阳虚不能内守而外浮，治拟培补作丸缓图。", ["浮", "濡"]], "6712": ["病机", "疟后营虚，脉形弦细。弦为肝象，细为营血不足，疟邪久羁耗伤营阴，筋脉失养故遍体作酸、两足为甚；体弱纳减亦营虚及脾之征。脉细主虚，弦则示筋脉拘急，合而观之属营虚络脉不充之病机，故拟培养。", ["弦", "细"]], "6713": ["病机", "心腹结痛而脉弦细而紧。紧主寒主痛，寒邪阻滞气机，不通则痛，故心腹结痛；弦为气滞痛征，细示寒凝脉道收引。三象合见，说明寒邪内阻、阳气不伸之病机，非虚寒即实寒凝滞，故拟温通以散寒行滞。", ["弦", "细", "紧"]], "6714": ["病机", "疝气少腹结痛，脉来弦细。弦为肝脉，少腹乃肝经所过，寒滞下焦则肝气不疏、络脉拘急，故结痛；细主寒凝脉道收引、气血不畅。脉弦细反映寒邪滞于下焦、肝络失和之病机，故拟温疏以温散寒邪、疏达肝气。", ["弦", "细"]], "6715": ["病机", "肺虚不降，咳呛有痰，体软纳减，脉来细涩。细为气血不足，涩为血少气滞、脉道不利；肺虚则宣降失职，痰随气逆而咳呛，脾运不健故体软纳减。细涩并见，示肺脾两虚、气血涩滞之病机，故拟疏理以调畅气机。", ["细", "涩"]], "6716": ["病机", "血症淹久，时发咳呛，两胁掣痛，脉数而弦。数主热，弦为肝脉、主痛主气逆；肝火内郁、木火刑金则咳呛胁痛，热迫血妄行故血症时发。脉数而弦正示肝经郁热、气火上逆之病机，故当用清降以清肝降火。", ["数", "弦"]], "6717": ["病机", "腹满渐致，两足微肿，体软肌削，舌红脱液，脉濡右略弦。濡主湿主虚，右略弦示肝脾不和、土虚木乘；脾虚失运则湿停腹满足肿，肌削脱液为久病阴伤。脉濡而右弦，说明肝脾内伤、湿阻兼阴液不足之病机，故拟温理。", ["濡", "弦"]], "6718": ["病机", "积湿下注，小便短塞作痛，舌白纳减，脉来濡细。濡主湿，细主虚，湿浊下注膀胱则气化不利、小便短塞作痛；舌白纳减示脾运不健、湿从内生。濡细并见，说明脾虚湿盛、湿浊下注之病机，故当用疏理以化湿通利。", ["濡", "细"]], "6719": ["病机", "肺感外风，咳呛有痰，脉濡。濡为湿象，亦主气虚；外风袭肺，肺失宣降则咳呛有痰，风邪夹湿留连故脉见濡。此脉说明外感风邪兼有湿滞、肺气不宣之病机，非单纯表实，故暂拟疏降以疏风宣肺、降气化痰。", ["濡"]], "6720": ["病机", "脉来浮濡，浮为气浮于外，濡为营阴不足、脉络失养。原文谓咳呛失血、劳乏伤气，气不生阴而营液内耗，久则火动木旺克金，故见胁痛失血、宿痞时动。浮濡正合气虚阴亏、虚火上浮之机，非实邪在表，故拟培补以复气阴。", ["浮", "濡"]], "6721": ["病机", "右脉略促，少冲和之象，是脾土衰而胃气不相接续；左浮濡、沉部不摄，为营阴亏虚、根本失守。原文述脾阴先亏、土不培木、肝邪侮土，致肿而胀、便泄完谷，君火衰则相火弱，火不化土。促而失冲和，正示中气败而化源竭，故拟培补参以酸辛。", ["促", "浮", "濡"]], "6722": ["病机", "右脉濡弱，主胃气虚弱、中土不运；左关见革，革脉中空外急，为肝血枯竭、木邪失养而横逆。原文谓脘痛偏左、午后至亥方止，木邪侮胃，更言肝脏必有一叶枯者。濡弱见土衰，革见肝枯，二者合参，正合木侮胃、肝叶枯槁之病机。", ["濡", "弱", "革"]], "6723": ["病机", "脉沉涩，沉主气机内郁，涩主血行不畅、气为厥阴所阻。原文述惊后默坐不应、便闭，手足先痉，谓目惊动魄，肺藏魄下通大肠，魄门为幽门，气为厥阴所阻故便结。沉涩正示厥阴气阻、魄门不通之机，故拟通幽门以疏其阻。", ["沉", "涩"]], "6724": ["病机", "脉来沉数，沉为气陷不升、水道有阻，数为郁热内蒸。原文谓肺为阴金属兑，太阳坎之阳水，下焦为厥阴之部，气陷不升致肿满。沉数示水气内停、郁而化热，气机陷而不升，故当降高原以通沟渎，兼泄巽风，使水道通而肿满消。", ["沉", "数"]], "6725": ["病机", "左寸紧、关弦，紧为郁结不畅，弦为肝木失达。原文谓肝藏血，血虚则卫脉失调，躁烦多郁，郁则木不达而营液耗，火动络、热迫血妄行，故偶然咯吐而不咳呛，肢酸心跳多寐。寸紧关弦正合心肝郁结、木火内动之机，故养心滋肝兼调奇脉。", ["紧", "弦"]], "6726": ["病机", "脉弦细紧，弦为肝木亢逆，细为营血不足，紧为气滞内结。原文述产后月余，肝血骤虚，肝脾失养，木亢克土，气滞下陷，致大腹胀满下及两足，水道有阻，兼涉任脉。弦细紧正示肝亢脾弱、气滞水停之机，故以疏肝升清阳为主。", ["弦", "细", "紧"]], "6727": ["病机", "脉形涩滞，涩主气机不畅、痰湿内阻。原文谓脾虚挟湿，微感外风，蒸痰壅塞，症近乎痫。涩滞正示痰湿壅遏、气机不利、脉络不畅之机，非血虚一端，故暂拟开泄以疏痰湿、畅气机。", ["涩"]], "6728": ["病机", "脉来濡细，濡主湿、细主虚，合之则见脾肾两衰、阴翳不化。原文谓鼓胀肿胀不减，脾肾阳气不足，水湿阴翳内停，脉道不充故细，湿性濡软故濡。此脉示正虚湿盛之机，非单纯实证，故曰大势不浅，拟温疏以化阴翳。", ["濡", "细"]], "6729": ["病机", "脉见虚弦，虚为正气不足，弦为肝气郁滞。原文绕脐腹痛，乃肝脾气滞、下焦气机不畅所致。虚弦并见，说明痛由气滞而本于正虚，非实邪壅塞，故从下焦温疏，温以助虚，疏以行滞，脉症相合。", ["虚", "弦"]], "6730": ["病机", "左脉弦大，弦主肝郁气滞，大主邪气有余。原文左腹结痞、大便带红，乃肝脾气滞、络脉不和，郁滞日久化热伤络。左脉候肝，弦大为肝经气滞邪盛之象，故拟疏理以调肝脾、行气滞，使痞结得散。", ["弦", "大"]], "6731": ["病机", "脉形浮濡，浮主气虚外浮，濡主湿邪内蕴。原文潮热畏寒、体软无力，乃气虚挟湿之候。气虚则卫外不固而畏寒，湿郁则潮热体软，脉浮濡正合气虚湿滞、营卫不和之机，故拟培补以固本化湿。", ["浮", "濡"]], "6732": ["病机", "脉弦主肝郁气滞，亦主营血失养、筋脉拘急。原文肢节酸楚、时觉心跳、腹中不舒，乃营虚失养、肝气不舒所致。弦脉虽常见于气滞，此案营虚筋脉失濡亦能致弦，故仍拟宣理，宣通营络、疏理气机。", ["弦"]], "6733": ["病机", "脉形濡涩，濡主湿滞，涩主血行不畅。原文少腹作痛、经阻带下、面浮肌削，乃宿痞气滞、肝脾不和，湿阻血瘀。濡涩并见，示湿滞与血涩交阻，经阻带下由是而生，面浮肌削为久病正伤，故拟温疏以化湿行滞。", ["濡", "涩"]], "6734": ["病机", "脉来濡细，濡为湿滞，细为营血亏虚。原文失血后体软色黄，乃肝脾营络内伤、气血不复。失血则脉道不充而细，脾虚湿滞则脉濡，此脉示营络虚损、湿滞未化，骤不能复，故当培补以复营络。", ["濡", "细"]], "6735": ["预后", "脉形濡细，左兼弦象。濡细主肝脾两亏、气血不足，左弦为木气偏旺。原文痞痛腹胀、潮热肌削、咳呛，乃久病元虚，现当木令，肝木乘脾侮肺，故恐其加剧。濡细示正虚难复，弦为木令当权，脉症合参，预后堪虑。", ["濡", "细", "弦"]], "6736": ["病机", "脉形濡细，濡主湿、细主虚，合之示肝脾内亏、湿邪内蕴。原文“鼓胀肝脾内亏，木邪侮土，腹胀作痛，色黄而浮”，木邪侮土则腹胀痛，脾虚湿泛则色黄而浮，脉濡细正合虚湿内阻之机，故当温疏以运脾化湿。", ["濡", "细"]], "6737": ["病机", "脉大而濡，大非实热，乃脾阳本亏、湿痰内蒸之象；濡为湿盛。原文“痫脾阳本亏，湿痰内蒸，心火不静，入夜少寐”，湿痰内蒸则脉大而濡，心火不静则少寐，脉症合参，主脾虚湿痰、心火不静之病机。", ["大", "濡"]], "6738": ["病机", "脉形濡细，濡主湿、细主虚，示肝脾已伤、湿滞气阻。原文“疟后结痞，肝脾已伤，积湿滞气，先肿后胀，土不培木，木来乘土，气阻则水亦不行”，脉濡细正合脾虚湿阻、气水不行之机，故暂用温通。", ["濡", "细"]], "6739": ["病机", "脉濡不弦，濡为虚湿，不弦则肝木不亢，示肝脾已亏、虚不能摄。原文“便血疟后未复，肝脾已亏，气泄便泄，络伤带血，此由虚不能摄”，脉濡不弦正合气虚不摄、络伤血溢之机，故拟培补。", ["濡"]], "6740": ["病机", "左脉弦细，右濡略浮，弦细为肝血不足、木亢侮土，濡浮为胃气本亏、营液亦耗。原文“厥阴之脉贯胃循喉，中气本亏，营液亦耗，血不足以养肝，木亢侮土，不纳不饥，少纳即嗳，咽间时哽”，脉症相应，故暂拟疏泄以动其机。", ["弦", "细", "濡", "浮"]], "6741": ["病机", "左脉弦细，右濡，弦细为肝无血养、木亢克中，濡为胃气弱而胃汁亦亏。原文“胃气弱而胃汁亦亏，肝无血养，兼其克中焦，阻滞，纳减，时嗳上冲，咽哽”，脉弦细右濡正合肝胃同病、中焦阻滞之机，故培中为主，参用和阴。", ["弦", "细", "濡"]], "6742": ["病机", "脉弦紧，弦主肝郁、紧主郁热内结。原文“肤痒阴亏火旺，木失所养，下焦郁热，肤中作痒，时觉虚烦，火盛则泄”，阴亏火旺、木失所养则脉弦紧，郁热下迫则泄，脉症合参，主阴亏火旺、下焦郁热之病机，故拟苦降。", ["弦", "紧"]], "6743": ["病机", "脉濡不弦，濡为气虚湿滞，不弦则肝木不亢，示肾阳素亏、中气弱而表阳亦共。原文“阴疟肾阳素亏，气不生精，营阴亦耗，肝木失养，外感风寒，入于少阳，淹久不止，卫不能与营和”，脉濡不弦正合营卫不和、气弱湿滞之机，故和解参以益气。", ["濡"]], "6744": ["病机", "脉濡为湿、为虚，此案素体不足、真阳先亏，又患阴疟未止，色悴而脉濡，是正气虚馁、湿邪留恋之象。濡脉主气血不足兼湿，正不胜邪，故专主温补，以扶真阳、化湿浊，使正复邪却。", ["濡"]], "6745": ["病机", "脉涩主血少、气滞、精亏。案中头眩经停，营液内亏，肝脾失养，疟后未复，冲脉不调，肝邪时亢，癸水不至，皆阴血亏虚、脉道不充之征。涩脉应之，故拟滋补参温养，以充营液、调冲任。", ["涩"]], "6746": ["病机", "脉浮大而濡，浮大似有余，濡则示不足，此肝肾阴亏、精不能摄，虚风上升，发则眩仆。阴不恋阳，虚阳上浮，故脉浮大；精亏血少，脉道不充，故兼濡。填补肝肾，使阴精复而虚风息。", ["浮", "大", "濡"]], "6747": ["病机", "脉形濡细，濡为气虚湿滞，细为阳衰血少。表阳根于中阳，中阳虚则外感易入，畏寒不热，气弱使然，非纯外感。濡细正合气弱阳微之机，故拟温补，以固中阳而实表。", ["濡", "细"]], "6748": ["病机", "下血而脉弦，弦为肝脉，主气机劲急。阴络内伤，血不循经而下溢，肝失柔和，木气偏亢，故脉见弦。培土和肝，略参苦坚，使肝脾调和、阴络得固，则血自止。", ["弦"]], "6749": ["病机", "脉见虚弦，虚为正气不足，弦为肝邪偏旺。命肠下衰，真气运迟，肝邪侮土，兼挟肾气，腹胀时痛偏左，皆土虚木乘之象。虚弦正示正虚邪实，故培补参温疏，扶土抑木。", ["虚", "弦"]], "6750": ["病机", "脉来濡弱，濡弱皆主虚，为气血不足、阳气衰微之征。操烦过多，心血本亏，阴疟后肝脾亦弱，神疲气弱、夜不安寐，是阳弱不能入阴。心火衰则血生化无源，故当补心火以助生原，濡弱正合火衰之机。", ["濡", "弱"]], "6751": ["病机", "脉来弦大，弦主肝风劲急，大主邪盛或虚阳外浮。劳乏伤营，筋失所养，外感风寒引动内风，络脉牵掣而痛，曾患便血，营阴已亏。弦大为风动络急、营虚不柔之象，故拟滋养以柔肝息风、养营通络。", ["弦", "大"]], "6752": ["兼症", "本案腹胀时痛为肝脾不和，近兼感风、咳呛有痰，属肺气不宣。右脉略浮，浮主表、主风邪在肺卫，与咳呛有痰相应；因兼感外风，故脉略浮而非沉弦，说明当前以肺气不宣、表邪未解为标，肝脾不和为本，故暂拟疏降，先解外兼调中。", ["浮"]], "6753": ["病机", "脘痛作胀、连胁及背、时或呕酸，为肝邪偏亢、气不条鬯之象。脉弦属实，弦为肝脉，实主邪气盛，说明肝气横逆、疏泄失职，气机郁滞而作胀痛，木旺犯胃则呕酸。脉弦而实，正合疏泄之法，故拟用疏泄以条达肝气。", ["弦"]], "6754": ["病机", "咽痛失音、咳呛失血，肺阴大亏，虚火上炎，恐成喉痹。脉浮不甚数，浮为肺金受病、气逆于上，不甚数说明热势未炽，阴亏而虚阳浮动，非实热壅盛。此脉与肺阴亏虚、金不生水相应，故拟甘平清金，使金水相生。", ["浮", "数"]], "6755": ["病机", "头风时发、胸闷不舒、偏体肢节酸楚，为营虚失养、络脉不荣。脉来濡弱，濡主湿滞、弱主气血不足，说明营血亏虚、阳气不振，外风乘虚而入，络脉失养而酸楚。濡弱之脉与营虚失养相应，故拟疏散，寓补于散。", ["濡", "弱"]], "6756": ["病机", "冬温身热无汗、咳呛多痰、两胁时痛、舌干少液、胸闷便闭，为太阳阳明兼涉肝肺之络。脉浮而数，浮主表邪未解，数主化热伤津，说明温邪在表而里热已萌，热灼津液故舌干。脉浮数示邪热鸱张，防其气急，故不可过散劫津，拟疏降参以宣络。", ["浮", "数"]], "6757": ["病机", "咳呛痰腻并黏、时或呕逆，为肝胃不和，近兼外感。脉浮而弦，浮主外感风邪在肺，弦主肝气偏亢、木犯胃土，说明外邪引动肝气，肺失宣降、胃失和降，故咳呛与呕逆并见。浮弦并见，外内合邪，故拟疏降以宣肺平肝和胃。", ["浮", "弦"]], "6758": ["病机", "咳呛喘急、色黄，为肾命下虚、气不摄阴，虚阳上浮。脉弦，弦为肝脉，亦见于肾虚不能涵木、虚气上逆之候，此弦非实邪，乃下虚上实、气不归元之象。脉弦与喘急色黄相应，说明虚阳浮越，故仍拟纳气归肾，引火归原。", ["弦"]], "6759": ["病机", "大便溏泄、纳减少味，脾阳本虚、传化失宜，兼受木克，营卫禀于脾而胃不和。脉左略弦、右涩，左弦为肝木偏旺、木克脾土，右涩为脾虚营血不足、脉道不利。弦涩并见，正合脾虚受克、营卫不和之机，故拟培补于气，胃开酌之。", ["弦", "涩"]], "6760": ["病机", "脉涩不数，涩主血行不畅、气机郁滞，不数则非热邪亢盛。原文舌强不语、脾窍不灵，属内闭，乃重剂久服后气机壅塞、脾运失司，浊邪内阻而脉道不利，故涩而不数。涩示闭阻在里，非表非热，故宜开泄以通其闭。", ["涩"]], "6761": ["病机", "脉来弦滑，弦主气机郁滞、肝木偏旺，滑主痰湿内盛。原文咳呛多痰、肃令不降，肺肾本虚而微感外风，痰阻气逆故脉见弦滑。弦滑为痰气交阻之象，非纯虚亦非纯实，故不可过散，暂拟滋摄以顾其本。", ["弦", "滑"]], "6762": ["病机", "脉右涩，右候肺脾，涩主气滞血少、宣降不利。原文喘咳肺虚易感、咳呛喘急、肃令不降，肺气虚弱则脉道不畅而涩。此症难许脱根，正因肺虚日久、气机涩滞难复，故暂拟疏理以调其气，非峻补可速效。", ["涩"]], "6763": ["病机", "脉涩不数，涩主营血亏少、脉道不充，不数则无火盛之象。原文劳乏伤营、失血之后骤不能复、体软纳减、微有咳呛，营血耗伤而脉失濡养，故涩而不数。此属虚损之候，宜酌进调补以复其营。", ["涩"]], "6764": ["病机", "脉大而滑，大主邪盛气张，滑主痰湿食滞内蕴。原文腹痛便血、近感寒邪、痛势加剧、寒热咳呛胁痛、舌白而腻，肝脾失调、气滞不达，复感寒邪与痰湿相搏，故脉见大滑。大滑示邪实壅盛，暂拟温疏以散寒调气。", ["大", "滑"]], "6765": ["病机", "脉浮濡无力，浮为气虚外浮，濡为湿困、力弱为正气不足。原文肺虚痰喘略平而肺气大虚、素力劳乏，肺气亏虚不能充脉，故浮而濡软无力。此非外感表实，乃虚象显露，当用培补以固肺气。", ["浮", "濡", "无", "力"]], "6766": ["病机", "脉右涩，右候中焦脾胃，涩主气机郁滞不畅。原文气阻作呕、脘次不舒、时或作呕、畏风微热，肝胃不和、肺亦不达，中焦气阻则脉道涩滞。涩示气郁而非热实，故拟用和解以调肝胃、疏达气机。", ["涩"]], "6767": ["病机", "脉数而弦，数主火升热动，弦主肝木偏亢、阴不敛阳。原文血症后复发、火升发热、肺虚咳呛，真阴本亏则虚火内动，火升故脉数，阴亏木旺故弦。数弦并见示阴虚火旺、络伤血溢，拟用宣络以疏其壅。", ["数", "弦"]], "6768": ["病机", "脉左弦为木旺克脾之象，右濡涩主脾虚湿滞血少。原文“结痞劳乏伤脾，兼受木克”，脾虚劳乏则右脉濡涩，木气偏亢则左脉弦，故少腹作痛、纳多时胀。弦为肝旺，濡涩为脾弱，合示肝脾不和、本虚标实，久则气滞水停恐成臌。", ["弦", "濡", "涩"]], "6769": ["病机", "右脉濡细主脾虚湿滞、气血不足，左不弦则厥阴气滞未至亢盛。原文“疝气为患，右肾作胀，厥阴气滞，陷于下焦”，气滞下焦则肾胀，脾虚湿阻则纳减，脉濡细正合虚中夹滞之机，故拟温疏以行气化湿。", ["濡", "细"]], "6770": ["病机", "脉来浮濡主气虚湿浮、津液不充。原文“土不生金，津液内耗”，脾土虚弱不能生金，肺津亏耗则音闪咳呛、体软纳减；浮为气浮于外，濡为湿滞而弱，示气阴两伤、虚多实少，故拟滋养参以益气。", ["浮", "濡"]], "6771": ["病机", "左脉略弦主厥阴肝气郁滞。原文“努力伤络，厥阴气滞，腹痛连胁，曾经见红”，努力伤络则血溢，肝气郁滞则腹痛连胁，弦为肝脉，略弦示气滞初起未甚，故以疏肝和络为治。", ["弦"]], "6772": ["病机", "脉涩主气滞血涩、表气不畅。原文“咳痰胁痛，身热无汗，舌白不渴”，身热无汗为表郁，咳痰胁痛为肺气不宣、络脉不和，涩脉示气血运行不畅，表邪未透，故当泄表疏中以宣通气血。", ["涩"]], "6773": ["预后", "原文“幸脉不弦大”，以脉不弦大为吉，示肝肾虽虚而木气未亢。盗汗咳呛多痰、舌干少液为肝肾两虚、气阴耗伤，若脉弦大则木火偏旺、虚中夹实，病势更进；今脉不弦大，故可补摄兼疏降。", []], "6774": ["病机", "左脉见弦主肝气偏旺、疏泄失常。原文“肝肾本虚，湿热下注，小便带浊”，本虚而湿热下注，肝脉弦示木气不柔、气机郁滞，助湿下流，故酌进滋养肝肾，参以疏肝化湿之剂。", ["弦"]], "6775": ["病机", "脉滑而弦主气滞痰阻、肝木犯胃。原文“肝肾内伤，中焦气阻，脘次时痛，纳食坚化，畏寒微热”，弦为肝旺，滑为痰湿内蕴，肝气横逆则中焦气阻，故脘痛、纳食难化，温疏以行气化痰。", ["滑", "弦"]], "6776": ["病机", "脉数而动，数主热，动主阳浮不宁。原文点明“浮阳上越肝膨阴亏，水不济火”，阴亏不能涵木，水火失济，虚阳上浮，故脉数而躁动不安。此非实热，乃阴不敛阳之象，治以“体阴用阳之品”，正合滋阴潜阳、柔肝敛浮阳之法。", ["数", "动"]], "6777": ["病机", "原文未出脉名，仅言“经迟腹胀痛，经迟”，以症测机。经迟而腹胀痛，属奇经失调、肝肾不足，冲任失养，气血运行不畅。故曰“当补肝肾”，以肝肾同源，精血充则冲任调、经自按期。本条重在由症推机，非凭脉断病。", []], "6778": ["病机", "右脉略数，右主肺卫，数则为热。原文谓“营液内亏，感受风寒”，营阴亏于内，风邪袭于表，表虚营不和，故微寒忽热、咳呛有痰。数而略，非大实大热，乃营液不足兼表邪之象，故拟疏降，疏表降肺而不峻补。", ["数"]], "6779": ["病机", "脉弦而促，弦主肝木偏旺，促主气机郁迫不舒。原文言“脾胃气虚，肝邪不平，腹中作痛，宿痞时发”，土虚则木乘，肝邪横逆，气结于中，故痞痛时作而脉弦促。此肝脾不和、虚实夹杂之候，故“酌进调养”，不宜峻攻。", ["弦", "促"]], "6780": ["预后", "脉数而左略弦，数主虚热，弦主肝逆。原文述咳呛寒热已久、胁痛气逆、宿痞时升、肌削多汗，久病阴伤，虚热内扰，肝气上逆。既言“病久必虚，恐其喘急，骤见脱象”，是虑正虚邪恋、气阴耗竭而有暴脱之危，故以预后为要。", ["数", "弦"]], "6781": ["病机", "脉滑而弦，滑主湿痰内蕴，弦主气机郁滞。原文谓“湿热积湿蒸热，中焦不舒，面色微黄，咳呛有痰”，湿郁化热，困阻中焦，痰热上逆于肺，故面黄咳痰。滑弦并见，正合湿热痰浊壅滞、肝胃气郁之机，故拟疏泄以化湿清热、调畅气机。", ["滑", "弦"]], "6782": ["病机", "脉濡主虚主湿，为气血不足、中焦失运之象。原文言“脾胃气虚，中焦阻滞，脘次作痛，纳减少味，肌削痛剧”，脾虚不运则湿滞中焦，纳减肌削示气血日亏。濡脉正应脾虚湿阻，故拟温补，温运中阳以复健运。", ["濡"]], "6783": ["病机", "脉形濡弱，濡主湿滞，弱主气虚。原文述咳呛有痰、身热多汗、大便仍溏、肌削神倦，久病脾肺两虚，气不化湿，湿浊内停，故脉濡弱。既言“久病必虚，当用培补”，是虚象已著，当培补脾肺以固其本，不可再事疏泄。", ["濡", "弱"]], "6784": ["病机", "脉见虚弦，虚为脾虚劳乏，弦为木克。原文言'脾虚木克，素体劳乏'，虚弦并见，正合土虚木乘之机。脾虚则纳减少味、痞胀腹痛，木克则气机壅滞。恐其中满，故拟温疏，温以扶脾，疏以达木，脉症相参，病机在虚实夹杂。", ["虚", "弦"]], "6785": ["病机", "脉弦而涩，弦主气滞，涩主血少或气机不利。原文谓'脘痛气陷中寒气滞'，中寒则阳气不运，气陷下焦则滞涩不畅，故脉弦中带涩。脘次作痛即气滞中寒之征。治以益气为主，参以疏达，益气以升陷，疏达以行滞，脉涩非纯血瘀，乃气虚不运所致。", ["弦", "涩"]], "6786": ["病机", "脉濡主虚主湿，原文言'中虚木郁'，中虚则脉气软弱无力而见濡，木郁则气机不畅。脘次时呃、畏寒不热，皆中阳不足、木气犯胃之象。濡脉不主实邪，正合虚寒之机，故当用温理，温中以复阳，理气以解郁，脉症相应。", ["濡"]], "6787": ["病机", "脉涩不甚弦，涩主气血不畅，不甚弦则少阳之象不显。原文谓阴疟'兼涉太阴'，脾胃气虚则体寒，痰湿内蕴，气血运行滞涩故脉涩；疟属少阳本当弦，今弦不甚，说明病偏太阴脾虚而非纯少阳。通阳为主，正针对湿遏阳微之机。", ["涩", "弦"]], "6788": ["治法", "本段未识别出脉名，原文仅言'肝脾失养'及'滋养肝脾，兼理奇脉'，属治法立论。肝脾失养则气血生化不足、奇脉失充，故以滋养肝脾为主，兼理奇脉。无脉象可据，病机从症候与治法反推，属虚损调补之例，不涉具体脉形。", []], "6789": ["病机", "脉浮略滑，浮主邪在肺卫，滑主痰热。原文谓'肺胃郁热'，失血微咳有痰、胁痛，皆郁热灼络、痰阻气机之象。浮为热郁于上，滑为痰湿内蕴，故以凉泄为主，参用宣络，清肺胃之热以止失血，宣络以解胁痛，脉症合参。", ["浮", "滑"]], "6790": ["病机", "脉浮不弦，浮主表主气升，不弦则非少阳。原文谓冬温身热无汗、咳呛痰多、左胁掣痛、痰中带血，症属冬温而不传经。脉浮说明邪郁肺卫、气机上升，不弦排除少阳传变。恐其气升，故暂拟宣理，宣肺降气以平升逆之势。", ["浮"]], "6791": ["病机", "脉形濡弱，濡弱皆主虚，原文谓'中虚多寒'，中阳不足则脉气软弱无力。脘次作痛、肌削加剧，乃中虚寒凝、气血不充之征。濡弱非实邪之脉，正合虚寒之机，故当用培中，温补中焦以复运化，中气充则痛减肌复，脉症相应。", ["濡", "弱"]], "6792": ["病机", "脉来濡弱，濡为湿象、弱为气虚，合而见肺肾两亏。原文咳呛气升、咯痰难出，是肺失肃降；舌光少液、纳减色黄，为肾阴不足、脾运不健。濡弱之脉不任重按，正合虚损之候，故主滋补肺肾，非实邪可比。", ["濡", "弱"]], "6793": ["病机", "脉芤为中空之象，主失血络伤。原文失血因劳乏所致，血去脉道不充，故按之中央空而两边实。芤脉示血脱未止，故言势未定，当从肺胃宣理，使气机调畅而血自归经，不可骤补。", ["芤"]], "6794": ["病机", "脉濡细主中气大亏、津液耗伤。原文便闭因邪解后肠胃津液亦耗，下不通则返乎上，故胸闷时呕。濡为气虚不运，细为阴血不足，脉证相合，故培中为主、参以润下，不可峻攻。", ["濡", "细"]], "6795": ["病机", "脉浮数主风邪郁热在表。原文游风上面归于左边、色红而肿，是风热上攻；小便不利、营液内亏，为热郁伤阴。浮为风邪在表，数为郁热，故当凉泄以清透风热，不可温散。", ["浮", "数"]], "6796": ["病机", "脉来虚弦，虚为气血不足，弦为肝木偏旺。原文肝阴内亏、脾肾之阳已弱，纳食不旺、夜不安寐，是阴亏阳弱而肝失柔养。虚弦不任按，正合虚损，故拟培补，不可伐肝。", ["虚", "弦"]], "6797": ["病机", "脉数而浮，浮为风邪在表，数为上焦郁热。原文咳呛淹久不止、肺阴已亏，风邪外袭而郁热内扰，故脉浮数并见。此非纯虚，暂拟清理以疏风清热，兼顾肺阴。", ["数", "浮"]], "6798": ["病机", "脉来弦细，弦主肝郁，细主阴血不足。原文疟后未复、宿痞时胀、体软纳减、盗汗，是肝脾内亏、气血两伤。弦细示木旺土虚，骤不能补，故拟和理以调肝脾，缓图恢复。", ["弦", "细"]], "6799": ["病机", "脉弦不和，弦主气机郁滞、木旺克土。原文湿阻中焦、脾虚化迟，纳减无味、脘次不舒，是湿浊困阻而肝脾不调。弦而不和示气机不畅，故拟通阳为主，使湿化阳通而脉自和。", ["弦"]], "6800": ["病机", "脉见虚弦，虚为不足，弦主肝木。失血咳痰，阳明络伤，血去阴亏则脉虚；肝脾不足，木失柔养则脉弦。此非独肺病，乃肝脾两虚、络伤未复之象，故曰“不专在肺也”。", ["虚", "弦"]], "6801": ["病机", "脉濡涩不数，濡主湿滞，涩主血少，不数则热未炽。咳呛淹久，肝阴内亏，上焦郁热，痰带秽浊，恐成肺痈。濡涩示阴亏湿郁，热郁未深，故当燥令以清金为主。", ["濡", "涩", "数"]], "6802": ["预后", "脉形细数，细为阴亏，数为虚热。肺肾两亏，兼感风寒，身热痰多，气升体软，纳减，正虚邪扰。细数之脉见于虚体感邪，阴液已耗而阳不潜藏，故“恐见脱象”，示预后可虑。", ["细", "数"]], "6803": ["病机", "右脉见涩，左略弦。涩主中寒血滞，弦主气机不畅。纳食化迟，脘次时胀，中寒气弱，运化无力，故右涩；肝木乘土，左略弦。此中虚寒滞、肝脾不调之机，当疏消兼辛温。", ["涩", "弦"]], "6804": ["病机", "脉濡，濡主气虚湿滞。素体气虚，表阳根于中阳，中阳不足则卫分不固，畏风发热，色黄。脉濡正合气虚卫弱、湿郁肌表之机，故益气为主，太阳阳维兼治。", ["濡"]], "6805": ["病机", "左脉弦细，右濡。弦细为肝阴不足、木失柔养，濡为脾虚湿滞。向患便血，肝脾两亏，近兼畏寒，表阳亦弱。弦细右濡并见，示肝脾两虚、气血不足而兼外感风寒，故暂疏理。", ["弦", "细", "濡"]], "6806": ["病机", "脉数右浮，浮主表，数主热。胃阳本虚，肺感外风，肺气不达，微有寒热，咳呛有痰，甚则呕逆。右浮数示风热袭肺、肺失宣降，胃虚为本，外感为标，故拟疏降。", ["数", "浮"]], "6807": ["病机", "脉濡细而数，濡细为阴亏，数为虚热。咳痰淹久，曾经带红，甚则呕急，肺阴内亏，肃令不降，虚热灼津。濡细数并见，示肺阴亏虚、虚热内扰之机，故拟清养。", ["濡", "细", "数"]], "6808": ["病机", "脉浮数为外感风邪、肺金被烁之象，浮主表邪未解，数主燥火内燔；左弦则木火偏亢、肝邪犯肺。原文谓“外感风邪，兼挟木火，肺金被烁，现当燥令”，故脉浮数而左弦，正合风燥束表、木火刑金之咳呛淹久，先宜清金，后养营阴。", ["浮", "数", "弦"]], "6809": ["病机", "脉来弦大为肝邪偏亢之征。弦为肝脉，大为邪盛，原文谓“胁胀痛肝邪偏亢，胀而兼痛”，胁为肝之分野，肝气横逆则胀痛并作，脉象弦大正应肝木太过、气机壅实，故当用温疏以达肝郁、散结滞。", ["弦", "大"]], "6810": ["病机", "右脉浮濡，右候脾肺，浮为气虚外浮，濡为湿滞阳弱。原文谓“血痢淹久，天寒加剧”“火不生土，肾为胃关”，脾肾两虚、阴络受伤，火不生土则运化无权，故脉浮濡无力，主温健脾肾以复中阳。", ["浮", "濡"]], "6811": ["病机", "脉形濡涩，濡主胃气中虚、湿滞不化，涩主阴液亏少、络脉不畅。原文谓“先患失血，现在血止，胃气中虚”“舌干少液，气不生阴，久恐成格”，失血后胃络受伤、气不生阴，故脉濡涩，主温补以复胃气、生阴液。", ["濡", "涩"]], "6812": ["病机", "脉来浮濡，浮为阳气外浮不敛，濡为脾土虚弱、湿困中焦。原文谓“脾阳中虚，土不培木”“肝邪偏亢，侮土作胀”“金弱则不能克木，木反乘金，肌削色黄”，脾虚木乘、气血不充，故脉浮濡，主滋培脾土以御肝邪。", ["浮", "濡"]], "6813": ["病机", "脉形濡弱，濡主湿滞，弱主气虚。原文谓“脾虚积湿，郁热伤营，偏体发瘰，便溏带血”，脾虚则湿积化热，郁热伤营则发瘰、便溏带血，气血两亏故脉濡弱，主滋补脾营、参以宣络化湿。", ["濡", "弱"]], "6814": ["病机", "右脉浮数，左略紧。浮数主外感风寒、肺气不降，紧主寒邪束表。原文谓“气虚痰喘，风寒易感，咳呛气促”，气虚卫外不固则风寒易袭，痰阻气逆故咳喘并作，脉浮数而紧，主疏降肺气、解表化痰，后当进补。", ["浮", "数", "紧"]], "6815": ["病机", "右脉见弦，右候脾土，弦为肝木之脉。原文谓“肝郁侮土，中阳不达，营络不和”“畏风潮热，卫外之阳不固，营液亦亏”，肝郁乘脾、营卫失调，故右脉弦，主益气和营、兼理奇脉以调阳维。", ["弦"]], "6816": ["病机", "脉形濡数，濡主湿、数主热，合为湿热内蕴之象。原文齿龈根痛、宿痞时痛，外感风寒归于阳明，兼挟风燥，说明阳明经气不降、湿热与风燥相搏，上攻齿龈则痛，内阻中焦则宿痞时痛。脉濡数正应湿热未清、风燥未净之机，故参用疏泄以透邪化湿。", ["濡", "数"]], "6817": ["病机", "左脉弦主肝气郁滞，右涩主气滞血少、冲带不利。原文腰酸腹痛、腰节酸楚、气滞腹痛，冲带为病，说明肝郁气滞、血行不畅，带脉失约。弦为气郁之征，涩为血滞之象，左右分候，正合肝郁血滞、冲带失调之病机，故拟疏理以调气行血。", ["弦", "涩"]], "6818": ["病机", "右脉浮主肺气虚浮不降，左涩主肾阴不足、血少。原文音哑略清、咳呛不减，断为肺肾两虚、金不生水。肺虚则气浮而咳呛，肾虚则水亏而音哑，浮涩并见，正示肺不降、肾不纳之机，故当用滋养以补肺肾。", ["浮", "涩"]], "6819": ["病机", "脉来弦细，弦主肝木亢旺，细主脾虚血少。原文肝胀脾虚、木旺邪亢作胀、肌削色黄，说明肝气横逆、脾土受克，气血生化不足。弦为木旺之征，细为脾虚之象，弦细并见正合木亢侮土、脾虚失运之病机，故仍拟疏理以平肝扶脾。", ["弦", "细"]], "6820": ["病机", "脉来弦细，弦属肝木，细为阴血不足。原文血痢下痢带红、阴络内伤，说明肝脾失调、阴络受损，血不循经而下痢带红。弦示肝气不调，细示阴血亏耗，弦细并见正应肝脾两伤、阴络内损之病机，故当用肝脾调养以和血止痢。", ["弦", "细"]], "6821": ["病机", "脉弦而紧，弦主肝木亢盛，紧主气机壅滞、寒凝作痛。原文脘胀、木亢侮土、脘次时胀，说明肝气横逆犯胃，中焦气滞不行。弦为木旺之征，紧为气结之象，弦紧并见正合木亢侮土、脘腹气滞之病机，现当平复，酌进调补以缓肝扶脾。", ["弦", "紧"]], "6822": ["病机", "脉来浮数，浮主肺气上浮不降，数主热象。原文咳呛有痰、气升呕逆、两胁掣痛，断为肺虚不降。肺虚则气浮而咳呛，热郁则脉数，浮数并见正示肺失肃降、气逆化热之机。原文防其喘急、更不可散，说明忌用辛散耗气，酌进调补参以疏降。", ["浮", "数"]], "6823": ["病机", "脉见虚弦，虚主脾胃气虚，弦主肝木偏旺；右略数示虚热内扰。原文中多痰湿、气升咳呛、曾经失血、表虚畏寒、气不摄血、时或便血、脘次嘈杂，说明脾虚气弱、肝脾失调、气不摄血。虚弦正合肝脾两虚、气不统血之病机，故归脾、六君主之。", ["虚", "弦", "数"]], "6824": ["病机", "脉数而弦，数主热，弦主肝木。原文谓“胀营液内亏，肝失所养”，营阴亏虚则肝木失柔，木火上升，故脉弦而数；火升则咽痛、膈次不舒，木火刑金则咳呛。此脉示阴亏火旺、肝阳上扰之病机，非外感实热。", ["数", "弦"]], "6825": ["病机", "脉来濡细，濡主湿、细主虚。原文谓“胀血不养肝，木亢乘土”，血虚不能养肝，肝木亢盛而乘脾土，故时或作胀；奇脉不调亦由血虚。濡细之脉示血虚湿滞、肝脾不调，故拟滋养以柔肝健脾。", ["濡", "细"]], "6826": ["病机", "脉形濡细，濡为湿象，细为虚候。原文谓“腹胀不减，中寒木郁，兼挟湿邪，恐其成鼓”，中阳不足则寒生，木郁不达则胀，湿邪内蕴故脉濡细。此脉示中寒湿困、木郁乘土，久则恐成鼓胀，故用温疏以散寒化湿。", ["濡", "细"]], "6827": ["病机", "脉数略浮，浮主表、数主热。原文谓“痰喘有根，感风发作，气升不降”，风邪外袭则脉浮，痰热内蕴则脉数；风引痰升，肺失肃降，故喘作。此脉示外风引动内痰、肺气上逆之病机，当燥令暂宜降肺，未可进补。", ["数", "浮"]], "6828": ["病机", "脉形濡浮，濡主湿、浮主虚浮。原文谓“土不生金，积湿蒸热”，脾土虚弱不能生金，湿积化热，故身热虽止而咳痰带红、体软色黄；濡浮之脉示脾虚湿蕴、肺金受损。恐其成肺痿，乃虚热灼津、肺叶焦枯之渐。", ["濡", "浮"]], "6829": ["病机", "右脉浮滑，右寸主肺，浮主风邪，滑主痰湿。原文谓“寒湿侵脾，腹痛下痢”，又“风邪入肺，咳痰音哑，甚则呕逆”，风邪犯肺则脉浮，痰湿内盛则脉滑。此脉示外风挟痰、肺脾同病，故当疏化以解表化湿。", ["浮", "滑"]], "6830": ["病机", "脉形浮数，浮主外感，数主邪热。原文谓“风邪外感，咳痰，胁痛”，风邪袭表则脉浮，邪郁化热则脉数；肺气失宣，络脉不和，故咳痰而胁痛。此脉示风热犯肺、表邪未解之病机，故暂拟疏降以宣肺达邪。", ["浮", "数"]], "6831": ["病机", "脉形浮濡，浮主虚浮，濡主湿滞。原文谓“宿痞作胀，脘腹不舒，脾阳中虚，木郁不达”，脾阳虚弱则运化失职，湿浊内停，木郁不达则气机壅滞，故脉浮濡。此脉示脾阳中虚、湿郁气滞之病机，当用温疏以振阳化湿。", ["浮", "濡"]], "6832": ["病机", "右脉见弦，弦为肝木之象，右关候脾胃，今弦见于右，是肝木侮土、中气未和之征。原文谓“痞胀宿痞时胀，肝木侮土”，纳减少味、畏寒不热，皆土受木克、运化失职所致。脉弦主肝旺，故治以疏补并进，疏肝以抑木，补中以扶土。", ["弦"]], "6833": ["病机", "脉右涩，涩为血行不畅、瘀滞之象。产后失调，瘀阻未清，时觉腹痛，右脉涩正是瘀血内阻、气血不得流畅之征。原文谓“瘀阻未清”，涩脉主瘀，故调养肝脾兼理奇脉，以化其瘀滞。", ["涩"]], "6834": ["病机", "脉形濡涩，濡主湿、涩主滞。湿从下受，两足先肿，渐及大腹连囊，面浮色晦，近兼咳呛，是土不能胜、高原不行，水湿泛滥之候。濡涩之脉正合湿邪困阻、气机涩滞之机，故拟用温理以化湿浊。", ["濡", "涩"]], "6835": ["病机", "脉形濡涩，濡为阴液不足、脉道不充，涩为血少行滞。原文谓“营液内亏，肝脾失养，木邪时亢，舌光脱液”，濡涩之脉正是营阴亏虚、脉络失濡之象。阴亏则木失柔养而亢，故拟用柔剂以养阴柔肝。", ["濡", "涩"]], "6836": ["病机", "脉数而弦，数为有热，弦主肝木、主痰饮。咳痰喘急，有感即发，是痰热内蕴、肝木上逆犯肺之候。数脉示热，弦脉示肝旺痰阻，故暂拟疏降，以疏肝降气、清化痰热为治。", ["数", "弦"]], "6837": ["病机", "脉濡数，濡主营虚湿滞，数主虚热。潮热疟止，时觉畏风，肢节酸楚，舌干少液，是营虚失养、肝脾不调，虚热内扰之征。濡数为营阴不足而兼虚热之象，故从肝脾调养，以复营液。", ["濡", "数"]], "6838": ["病机", "脉弦而数，弦为木火亢盛，数为热象。木火作呛，络伤失血，当气燥肃令不降之时，弦数之脉正示肝火偏旺、灼伤血络。火性急迫故数，木气劲急故弦，故从肝脾清养，清肝降火以宁络。", ["弦", "数"]], "6839": ["病机", "脉形弦数，弦主肝木不和，数主浮阳有余。肝脾不和，浮阳上越，气不调畅，时或呕逆，腰节酸楚，弦数之脉正是肝阳偏亢、气逆不降之征。木旺则克土，气逆则呕，故拟用调补以和肝脾、潜浮阳。", ["弦", "数"]], "6840": ["病机", "下痢久不止，气血两伤，脾运不健，故脉来濡涩。濡为气虚湿滞，涩为血少行艰，与腹痛连胁、纳减少味相应，示脾虚肝乘、虚实夹杂，故疏补并进。", ["濡", "涩"]], "6841": ["病机", "外感已解而气虚未复，脾肺俱弱，故脉形濡弱。濡主气虚湿滞，弱主元气不足，与体软无力、纳减少味、便溏咳呛相应，示中气亏虚、肺脾同病，故酌进调补。", ["濡", "弱"]], "6842": ["病机", "肝肾两亏，水不济火，阴火上升射肺，故左脉弦大不静、右数亦弦。弦为肝旺，大为虚火鼓动，数为火象，与虚火作呛相应，示阴虚火旺、木火刑金，故拟滋补。", ["弦", "大", "数"]], "6843": ["病机", "疟后肝脾内亏、气不调畅，近因外感咳呛有痰，脉形濡涩。濡为气虚湿滞，涩为营血不充、气机不畅，与咳呛有痰相应，示肝脾两虚兼外感，故平调益气、参以和营。", ["濡", "涩"]], "6844": ["病机", "潮热咳呛、痰中带红、体软，脉濡。濡主气虚湿滞、营阴不足，与畏寒潮热、咳呛带红相应，示气阴两虚、虚热内扰，故酌进培补。", ["濡"]], "6845": ["病机", "肝脾营虚，木亢乘土，内失滋养，故脉来濡弱。濡弱为气血不足之象，与心跳时眩、咯血上行相应，示营虚失摄、肝脾同病，故拟用培补。", ["濡", "弱"]], "6846": ["病机", "便血不止，肝脾阴络内伤，下焦不摄，故脉来沉细。沉主病在里，细主阴血亏少，与便血不止相应，示络伤血溢、下焦失摄，故拟用温健。", ["沉", "细"]], "6847": ["病机", "咳呛略减而肺阴内亏，肃令不降，脉数右浮。数为阴虚内热，右浮应肺，与天寒气燥、咳呛相应，示肺阴不足、虚热上浮，故以清金为主。", ["数", "浮"]], "6848": ["病机", "右脉浮数，右寸候肺，浮为肺气上浮不敛，数为燥热内扰。原文谓痰喘本肺气虚，操烦耗心液而失血，天寒气燥又克肺金，故浮数示肺虚夹燥热、气不肃降，主痰喘失血之咳逆上气，治以清养宣络。", ["浮", "数"]], "6849": ["病机", "脉数而浮，数为阴分有火，浮为虚阳不潜。原文言金水两亏、痰喘时发，肺肾阴亏则虚火浮越于上，故脉浮数。此脉主阴虚火动、气不归元之痰喘，与滋养金水之法相应，非实火可清。", ["数", "浮"]], "6850": ["病机", "脉弦略数，弦属厥阴木旺，数为木火内郁。原文谓时邪愈后未清归于太阳，厥阴木火潜潮致音哑，厥阴之脉循喉，故弦数主木火上炎、循经灼喉之音哑，与滋养厥阴、潜降木火相应。", ["弦", "数"]], "6851": ["病机", "脉虚弦略数，虚为营液内亏，弦属肝脾不滋、虚邪时亢，数为营虚生热。原文谓营虚不能与卫和故热胜无汗，纳减便溏示脾营亦弱。此脉主营亏生热、肝脾失滋之虚热，故不宜温燥，主以滋养。", ["虚", "弦", "数"]], "6852": ["病机", "左脉弦细，弦为肝郁、细为肝肾素亏；右浮濡，浮示微有外感，濡为气虚湿滞。原文见咳呛气逆、左胁掣痛、腹胀足肿，皆肝失疏泄、气逆水停之象，故脉主肝肾亏虚、气升水泛，急宜温通以防气升多汗。", ["弦", "细", "浮", "濡"]], "6853": ["病机", "原文未识脉名，仅言脉亦如常。素体气虚而内风妄动、顽痰上壅，致目瞪舌蹇、艰于言语，然呼吸尚调、脉如常，说明病在痰风壅阻清窍经络，未至脏气败绝，故脉不显败象，暂拟开泄以豁痰熄风。", []], "6854": ["病机", "脉涩为血少气滞、脉道不利。原文产后感寒，腹痛便泄虽愈，而气升咳呛、面浮，产后营血本亏，气机壅滞不降，故脉涩。此脉主产后气血两虚兼气逆水浮，治以益气为主，参以疏降，使气降则咳浮自平。", ["涩"]], "6855": ["病机", "脉见虚弦，虚为肾气不摄，弦为下焦不摄、气逆上冲。原文谓气根在肾，下焦不摄则喘急咳呛，阴阳相为维系，虚则防脱。此脉主肾虚不纳、气逆欲脱之喘咳，故拟补纳以固根本，非疏泄可投。", ["虚", "弦"]], "6856": ["病机", "下痢已减而身热不退，脉来见弦。弦为木旺之象，此处不主肝实，而示表阳不充、正气未复。下利伤中，营卫不和，外邪乘虚而感，故身热不退、纳食不旺。脉弦与表阳不充并见，说明正虚邪恋、脾胃未复，治当酌进调补以扶正达邪。", ["弦"]], "6857": ["病机", "原文未识脉名，仅言“脉络不舒”。便溏由劳乏伤营、脾运不健所致，畏寒时热乃营卫失调之象。脉络不舒与便溏并见，说明营血亏虚、气机不畅，脾失健运而络脉失养。故以益气为主，参以疏泄，使气旺则营复、络通而便实。", []], "6858": ["病机", "脉弦而促，原文自释“弦为木旺，旺则克土；促为气不舒”。木旺克土，土不生金，肃降失令，故咳痰喘急、甚则呕逆；肺虚表疏则易感、畏寒微热。弦促并见，示肝木偏亢、气机郁滞而肺金受病，病机重在木旺侮金、气逆不降。", ["弦", "促"]], "6859": ["病机", "脉形弦而右数。弦为肝木之象，右数主肺热。肺热蒸痰，咳呛时发、痰中带红，两胁掣痛，乃木火刑金、热伤肺络之征。弦数并见，说明肝火偏旺、肺热内蒸，气逆络伤，故宜清降以泻肺平木。", ["弦", "数"]], "6860": ["病机", "脉濡，神倦，素体劳乏。濡为虚软之象，主气血不足、湿滞。肺胃两虚，土不生金，咳呛淹久，痰带腻秽，肺虚成痈。脉濡与神倦并见，说明正气已虚、湿浊内蕴，正虚而痈成，恐其不支，故当扶正为要。", ["濡"]], "6861": ["病机", "脉数不静。数主热，不静示阳亢躁动。肝肾阴亏，水不制火，心阳时亢，木火内炽，故脉数不静。素日操烦，阴亏内热，神火有亏。此脉说明阴虚火旺、心肝阳亢，热扰心神，故暂拟滋养，后当进补。", ["数"]], "6862": ["病机", "脉形濡滑。濡主湿，滑主痰火。头为诸阳之首，湿火上升，气蒸多汗，归巅顶。阳明多汗、太阳卫疏亦多汗。濡滑并见，说明湿蒸火炎、痰湿内蕴而上扰，故头汗多。现当燥令，拟用静剂以清化。", ["濡", "滑"]], "6863": ["病机", "脉形见涩。涩主血少、气滞。心脾液亏，内失滋养，郁火时炽，喉间作痒，舌根红点，心跳时眩。脉络不舒与涩脉相应，说明营阴亏虚、血行不畅、郁火内扰。故以养营为主，更须静养。", ["涩"]], "6864": ["病机", "脉濡而涩，濡主脾虚湿困，涩主气滞血瘀。肝胀土不培木，气郁肝邪时亢，胀痛并作，大便时溏，心跳腰楚，皆脾虚湿盛、肝郁气滞之象。脉濡为土虚不运，涩为气郁血滞，故拟温疏以运脾疏肝。", ["濡", "涩"]], "6865": ["病机", "脉濡不弦，濡主脾虚湿盛，不弦则肝木未至过亢。痞胀脾虚木亢，纳食不安，体软肌削，肢节酸楚，皆脾虚失运、湿阻肌络之候。脉濡不弦，说明木亢不甚而土虚为著，久恐腹满，故当温疏以健脾化湿。", ["濡"]], "6866": ["病机", "脉虚弦而细，虚为劳乏气弱，弦为肝脾内伤、气机郁滞，细为阴血不足。下痢失血痞胀腹痛，服疏化之剂遂起失血，乃积瘀从络外溢。素体劳乏，肝脾内伤，虚弦细脉正合气血两亏、瘀滞络伤之机，故酌用培补。", ["虚", "弦", "细"]], "6867": ["病机", "脉濡，主气虚湿弱。下痢不止，咳呛多痰，失血，肝肺络伤，神倦，素日劳乏，气不摄营。脉濡为气弱不能摄血运湿，故下痢、失血、咳痰并见。此非实邪，乃劳乏气馁、营血不摄之候，仍拟培补以固本。", ["濡"]], "6868": ["病机", "脉来濡浮，浮主肺气上逆，濡主胃气弱而湿滞。肺痿咳呛淹久，渐致音哑，咳甚呕逆，胃不开纳，乃肺胃津气两伤、虚火上炎之候。濡浮之脉说明病位偏上而正气已弱，故恐加剧，拟和胃为主以培土生金。", ["濡", "浮"]], "6869": ["病机", "左脉见弦，左关候肝，弦为肝郁气滞之象。营卫不和，肝郁侮土，中阳不达，营络不和，畏风潮热，卫外之阳不固，营液不能充周，虚邪时亢。左脉弦正是肝郁不疏、营卫失调之反映，故益气和营兼理奇脉。", ["弦"]], "6870": ["病机", "原文未识脉名，从症候论病机。阴疟中虚作恶，少阳之脉贯胃，发则必呕，舌黄而干，外邪未清。此乃少阳邪郁、胃气上逆、中虚夹邪之候。虽无脉象可凭，然症见呕恶舌黄，知邪在少阳阳明之间，故调营卫兼泄少阳。", []], "6871": ["病机", "脉形濡涩，濡主胃气中虚、湿滞不运，涩主气滞血少、络脉不畅。失血阳明络伤，血从外溢已止，纳食不减，时时作嗳，胸膈气滞，舌干少液。脉濡涩说明胃虚气不生阴、血络滞涩，久恐成格，故拟温补以复胃气。", ["濡", "涩"]], "6872": ["病机", "右脉弦数而紧，弦主郁、数主火、紧主邪聚，合见肺阴内亏而郁火挟痰；左部虚弦为阴血不足之征。咳呛不减正是肺阴亏耗、郁火刑金之象，故曰兼挟郁火，酌进滋养并须节劳，以劳则耗阴助火。", ["弦", "数", "紧", "虚"]], "6873": ["病机", "脉濡为湿滞、右数为热，合之则血热伤营而兼脾湿。肤燥发痒是营热外扰，便溏带红乃湿热下注、脾失健运。拟用苦燥者，以苦能燥湿清热，湿去则濡减，热清则数平，正合脉证。", ["濡", "数"]], "6874": ["病机", "左脉弦数，弦为肝旺、数为火动，肝升太过而肺降不及；右濡为肺气不足。咳痰喘急、气不下摄，正是肺肾两虚、肝火上逆之候。脉弦数而不沉细，说明虚中挟火，故拟滋补以摄纳。", ["弦", "数", "濡"]], "6875": ["病机", "脉形濡细，濡为气虚不运、细为营液亏少，合之气阴两亏。素体气虚则肝脾失养，营液亦亏则奇脉失充，故虽痰喘平复而脉仍濡细。拟用滋养不专治肺，正因病本在肝脾营液，非独肺也。", ["濡", "细"]], "6876": ["病机", "脉形濡弱，濡主气虚湿滞、弱主中气不足，合之脾胃中虚、气不生阴。营液亦耗则内失滋养，故体软色悴、食不甘味、大便时溏。脉弱而不数，说明虚多热少，故益气为主兼和营络。", ["濡", "弱"]], "6877": ["病机", "左脉濡弱，濡为湿滞、弱为气虚，左关候肝，故知肝脾不调。风寒挟湿，时发阴疟，正因营卫不和、少阳枢机不利。脉濡弱而不弦紧，说明正虚邪恋，故和营卫兼泻少阳，扶正祛邪并行。", ["濡", "弱"]], "6878": ["病机", "脉来濡弱，濡为阳气不充、弱为卫外无力，故曰表阳先亏、卫外不固。风寒乘虚入肺，痰喘时发，脉不浮紧而濡弱，正见虚人感邪之象。当用温补者，补表阳以固卫，非徒散邪也。", ["濡", "弱"]], "6879": ["病机", "脉濡细，濡为湿盛、细为阴虚，合之命阳下亏、积湿不化。肿胀连囊是水湿泛溢，兼咳呛则水气上逆犯肺。脉不沉实而濡细，说明正虚湿滞，故曰急切难效，参肾阴法以化气行水。", ["濡", "细"]], "6880": ["病机", "脉形濡而不数，濡为阴湿之象，不数则非实火。原文谓“阴火上越，不能归根”，阴火本虚，上浮而不归肾宅，故脉濡软不数，反映阴中之阳失守。此脉主虚阳上浮、下元不固，与阴火升越之证相应，治当消息阴中之阳，引火归原。", ["濡", "数"]], "6881": ["病机", "脉浮濡而不甚数，浮为虚阳外浮，濡为脾胃气弱、阴不摄阳。原文谓“脾胃中虚，气不摄阴，阴火上升，离不交坎”，起患梦泄，正是中虚阴火不归、心肾不交之象。脉浮濡不数，说明非实热，乃气不摄阴之虚火，故拟培补而不宜纯阴。", ["浮", "濡", "数"]], "6882": ["病机", "原文谓“幸脉不弦”，弦为木旺克土之象，今脉不弦，说明脾肾虽亏而肝木未至横逆。便溏脱肛、色黄浮肿，皆火不生土、脾肾二亏之候。脉不弦则中土尚可受温补，无木贼之害，故拟用温补，以复火土相生之机。", ["不弦"]], "6883": ["病机", "脉形濡细，濡为脾虚湿困，细为阴血不足。原文谓“木火烁金，咳呛有痰，络伤失血”，又“脾受木克”而便溏，畏风时热、肌削，皆肝木乘肺、脾肺两虚之象。濡细之脉正合虚损，主气阴两伤、木火刑金，故酌进调补。", ["濡", "细"]], "6884": ["病机", "脉滑大而数，滑主湿浊，大数主热与气壅。原文谓“素日劳乏，兼挟积湿，气陷下焦”，先便浊后癃闭，少腹作胀，乃太阳气化无权、湿热壅阻下焦。滑大数之脉说明湿浊化热、气机壅滞，故益气化湿参滋肾，以复气化。", ["滑", "大", "数"]], "6885": ["病机", "脉濡，左略弦，濡为营卫二虚、中气亦弱，左弦为肝阴内亏、木亢侮土。原文谓“阴疟淹久，肝阴内亏，木亢侮土，脘次结痞”，疟止而寒热间作，咳呛失血，肝肺络伤。濡而左弦，正合营虚肝亢、中气不足之机，故拟调养。", ["濡", "弦"]], "6886": ["病机", "脉濡细，濡主气虚湿滞，细主营血不足。原文谓“产后营虚，肝脾失养，气滞不达”，故腹痛便泄、腰节酸楚、心跳头眩。产后营血亏虚，肝脾不调，气滞而湿不化，濡细之脉正合虚中夹滞之象，故当用温疏以调养肝脾。", ["濡", "细"]], "6887": ["病机", "脉数而弦，数为木火内炽，弦为肝气郁逆。原文谓“肝阴内亏，气不得达，木火乘金”，故咳呛胁痛、脘次不舒。肝阴亏则木火亢，上乘肺金，脉数弦正是木火刑金之象，久恐成怯，说明病机在肝肺阴伤、火逆。", ["数", "弦"]], "6888": ["预后", "本案汗多表虚，又兼便血，肌削而脉弦。弦为肝木之象，阴血亏耗不能柔肝，木失所养而劲急，故脉弦。肌削示形肉已脱，汗多便血示气血两伤，弦脉见于虚损之体，是阴不敛阳、肝木偏旺，正虚难复，故断为急切难效。", ["弦"]], "6889": ["病机", "疟久伤营，营血耗损则木火内动，肝失柔养而脾亦受克，故大便带红。脉弦而大，弦为肝旺，大为虚象，是阴血不足而肝木亢盛之征。木火内动、肝脾失养为本段病机核心，故治以和营为主，参小柴胡法以疏肝和脾。", ["弦", "大"]], "6890": ["病机", "产后十朝，气血未复，外感寒邪，腹痛便泄而色黄。脉略浮涩，浮为邪在表，涩为血少气滞、营卫不利。产后本虚，寒邪外束，脾运失司，故泄泻。浮涩并见，示表邪未解而里虚血滞，拟温理下焦，温散寒邪以复脾肾之阳。", ["浮", "涩"]], "6891": ["病机", "长夏暑湿起患便溏，淹久至冬，脾阳先虚，土不培木而肝阴亦弱，木反侮土，故时胀、泄仍未止。脉濡涩不数，濡主湿、主气虚，涩主血少气滞，不数则无热象，正合脾阳虚弱、湿滞营卫不和之机。故培中为主，兼和营卫，待胃气旺而春阳助之可复。", ["濡", "涩", "数"]], "6892": ["病机", "脾胃气虚，湿痰内聚，上逆作呛，甚则喘急，有感即发。脉大而濡，大为气虚阳浮，濡为湿盛、为气弱，并不弦急，说明非肝木亢盛之实证，而是中气不足、湿痰内停。脉证相合，故拟益气健脾化湿，气旺则痰湿自消。", ["大", "濡"]], "6893": ["病机", "失血之后，络伤未复，连次作呛、胁痛。左脉见弦，弦为肝木之象，失血阴亏则肝失柔养而劲；右濡不数，濡示气分不足、湿滞，不数则无实热。左弦右濡，示肝胃同病、阴血亏而气分弱，故从肝胃滋养，参以理肺，以柔肝和胃、润肺止咳。", ["弦", "濡", "数"]], "6894": ["病机", "风寒外感，咳呛身热胁痛，咳止而热不退，神昏谵语、循衣摸床，舌苔腻白带灰。左脉弦大，右较细数，弦大为肝风内动之兆，细数为阴伤邪郁。中焦阻滞、表邪未解，邪归阳明尚未化热，素体劳乏正不胜邪，故恐风动发厥，拟散而兼疏。", ["弦", "大", "细", "数"]], "6895": ["病机", "得汗后热仍不解，神昏谵语，舌干唇燥，脉弦而数。弦为少阳木火之象，数为热盛，汗后热不退而津液被烁，示阳明里症渐入少阳，邪热内逼而阴津受灼。舌干唇燥、神昏谵语皆津伤热扰之征，恐其内陷，故仍拟疏散，参用化热以透邪保津。", ["弦", "数"]], "6896": ["病机", "脉来弦滑，弦主气机郁滞、木邪犯土，滑主痰湿内蕴。脾胃中虚则运化失职，气阻于中，痰湿随气上逆，故呕逆而吐酸苦。弦滑并见，说明中虚为本、气阻痰凝为标，久延有格拒之虞，故原文谓\"旧恐成格\"，治当温理中焦以复升降。", ["弦", "滑"]], "6897": ["病机", "脉弦而数，弦为肝郁气滞之象，数主邪热内扰。肝郁日久，木邪乘金，肺虚失肃，兼感外风，故咳呛入夜多汗；肝气横逆，时觉腹痛。弦数并见，示肝肺同病、气郁化热，故原文以\"肝肺兼理\"为治，既疏肝解郁，又清肺肃降。", ["弦", "数"]], "6898": ["病机", "脉形濡弱，濡主湿滞、弱主气虚，二者并见，说明肺气本虚而肃降无力。痰喘虽略平，然肺虚未复，肃令不降，痰湿内留，故脉见濡弱。此脉不任攻伐，只宜调补，原文\"酌进调补\"正合虚多实少之机，补肺气以复肃降，兼化留痰。", ["濡", "弱"]], "6899": ["病机", "脉弦而涩，弦为肝木偏亢，涩主气滞血少、津液不充。郁怒伤肝，木邪侮土，脾运受困，故脘胀纳减、味不甘；舌干少液，亦津亏之征。弦涩并见，示气郁而兼阴血不足，不可峻攻，原文\"拟用调养\"，即柔肝健脾、养液疏滞并行。", ["弦", "涩"]], "6900": ["病机", "脉来濡涩，濡主脾虚湿困，涩主血行不畅、下焦亏虚。产后失调，脾虚木亢，肝气横逆则腹痛，脾不健运则便泄。濡涩并见，说明虚而兼滞，病位偏下，故原文\"拟从下焦温理，兼理奇脉\"，温养下元以复脾运，兼调冲任奇经。", ["濡", "涩"]], "6901": ["病机", "脉濡，主气虚而兼湿滞。腹痛中痞，痛自腰连脊而偏于左，乃脉络不舒、气血痹阻之象；肌削则气血日亏。濡脉示正气不足、湿阻络脉，故痛而缠绵。原文\"拟用温宣\"，以温通阳气、宣畅脉络为法，使气血得行而痛痞可解。", ["濡"]], "6902": ["病机", "脉来濡弱，濡主湿、弱主虚，示气血两亏而脾运不健。潮热淹久、畏寒微汗，为营卫不和、虚热内扰；咳痰带红，则肺络受损。濡弱之脉说明正虚为主，肝脾同病，故原文\"从肝脾兼理\"，健脾以生化气血，柔肝以调营卫，不可纯用寒凉。", ["濡", "弱"]], "6903": ["病机", "脉左弦右数，左候肝、右候肺。真阴下亏，水不涵木，肝火偏旺故左弦；火旺烁金，肺失清肃故右数，咳呛淹久由此而致。弦数并见，示阴虚火旺、肝肺同病，非外邪实热，故原文\"拟用滋养\"，滋水涵木、清金降火，使阴复火平而咳自缓。", ["弦", "数"]], "6904": ["病机", "脉数略弦，数主火升，弦主肝木失柔。原文谓“营液内亏，肝脾失养，木火上升”，故脉数应火，弦应木旺，与心跳时眩、筋脉不舒相应。此脉说明营亏火升、肝脾失养之病机，非外感实火，故拟柔剂养营柔肝。", ["数", "弦"]], "6905": ["病机", "脉弦而数，弦为肝络不和，数为火动。原文“阳明络伤，血从外溢，微有咳呛”，血溢则阴亏，阴亏则火动，火动则脉数；络伤气逆则脉弦。此脉主失血后阴亏火动、络伤气逆之病机，与咳呛相应，故宜宣理。", ["弦", "数"]], "6906": ["病机", "脉濡而数，濡主湿，数主热。原文“肺感风寒，咳痰喘急，有感即发”，风寒外束，肺失宣降，痰湿内蕴，郁而化热，故脉濡而数。此脉说明外寒内饮、痰热郁肺之病机，与咳痰喘急相应，故当疏降。", ["濡", "数"]], "6907": ["预后", "原文“脉不弦大，可无汗脱之虞”，脉不弦大则无肝阳上亢、气火升腾之象，故断无汗脱之危。此段以脉不弦大判断预后，说明津亏咳喘虽肺肾二亏、金不生水，但脉象平和，未至阴阳离决，故从下焦滋补缓图。", []], "6908": ["病机", "脉大而弦，大主虚，弦主肝脾不和。原文“粪后下血，肛门作痛”，脾阴不足则脉大，肝木乘脾则脉弦，下血伤阴，络脉不和故肛门作痛。此脉说明脾阴亏虚、肝木偏旺、阳明络伤之病机，故养脾阴兼理阳明。", ["大", "弦"]], "6909": ["病机", "原文“六脉不静”，未识具体脉名，然“不静”即脉失柔和、躁动不宁之象。经下颇多则阴血亏耗，心烦口渴为阳亢，阴亏阳亢则脉不静。此脉说明阴虚阳亢、血去阴伤之病机，与经多、烦渴相应，故议滋养。", []], "6910": ["病机", "脉来细软，细主阴血不足，软主气虚。原文“肝强脾弱，胸腹作胀，癸水不行”，脾弱则气血生化不足，脉道不充故细软；肝强则气机郁滞，冲任失养故经闭。此脉说明肝强脾弱、气血两虚之病机，与胀、闭经相应，故调气和血。", ["细", "软"]], "6911": ["病机", "原文未识脉名，然“阴虚内热，经漏淋漓”已明病机。阴虚则阳亢，虚热内生，扰于冲任，血海不宁，故经漏淋漓。此段以阴虚内热为纲，脉象虽未明言，当见细数之象。仿仲景复脉法，即养阴复脉、清热止血之意。", []], "6912": ["病机", "原文谓“六脉无力”，虽未列具体脉名，然六脉无力即虚象，主产后结瘕属“肝肾络虚，非有形所阻”。少腹胀痛因络脉空虚、气血不充而作，非实积攻伐可解；自汗屡泄更耗气阴，故脉无力。虚证当以疏通为要，忌投攻剂，此脉象与症候相应，示人勿犯虚虚之戒。", []], "6913": ["病机", "原文仅言“色脉少神”，未出具体脉象，然色脉少神即脉来无力、缺乏神气之象，主中虚肝郁。中气不足则腹胀食减，肝郁不达则气机不畅，故仿逍遥法疏肝健脾。脉少神反映正气已虚，非实邪壅滞，治当调补兼疏，不可峻攻。", []], "6914": ["病机", "脉濡涩不弦，濡主脾胃中虚、气血不足，涩主血少气滞、络脉不畅；不弦则肝邪郁滞而未成亢盛之象。土不培木，肝邪郁滞，结瘕少腹，发则上升胀痛，犯胃则呕酸。脉濡涩正合中虚血少、气机郁滞之机，故当温疏，兼涉奇脉则平时调补。", ["濡", "涩"]], "6915": ["病机", "左脉促而弦，促主气机急促或虚中挟实，弦主木亢侮土；右大而濡，大主虚阳外浮，濡主中气已虚。血不养肝，木亢克脾，产后下痢不止，中虚受克，腹胀时痛，津不上承而口干唇燥。脉促弦与右大濡并见，正是虚中挟实、攻补两难之象，故拟温剂。", ["促", "弦", "大", "濡"]], "6916": ["病机", "左脉数动，数主有火，动主中虚火浮、津液受灼；右大略弦，大主中气不足而虚阳外张，弦主肝木偏亢。中虚有火，舌光脱液，津不上承，微觉腰楚，皆由脾虚不能摄营、奇脉失养所致。脉数动而右大弦，示虚火内扰、肝脾不调，故专主培补。", ["数", "动", "大", "弦"]], "6917": ["病机", "脉形濡数，濡主湿滞中焦、脾气不达，数主郁热内蒸；左略弦，弦主肝郁不疏。肝脏脾胃不和，积湿蒸热，中气不达，郁火时升，故脉见濡数而左略弦。此湿郁化热、肝脾不调之候，仍拟疏泄，未宜腻补，以免助湿碍气。", ["濡", "数", "弦"]], "6918": ["病机", "右部濡弱，濡主脾胃素虚、湿气不化，弱主中气不足；左亦濡而不弦，不弦知肝无藏血，血少失养。水不滋木，邪亢侮土，脾胃益弱，脘腹作痛微觉坚实，筋脉酸楚，舌光脱液。脉濡弱不弦，正合气液并耗、虚邪内结之机，故拟柔剂调摄。", ["濡", "弱"]], "6919": ["病机", "原文未出具体脉象，然述肝脾内亏、冲脉失调之病机。心悸属营虚，腹胀属肝气，头眩耳鸣属厥阴、少阴风火上升，经到则络空故见诸症。此皆因肝脾亏虚、冲脉失养、血络不充所致，虽未言脉，其病机与脉当见虚细不静之象相应，故拟滋摄。", []], "6920": ["病机", "产后失调淹久，肝脾之阴皆亏，血少不能充肌肤，故色悴而燥。脉虚为血不足，弦为肝木失养而气不柔，虚弦并见正是阴血亏虚、肝脾失润之象，非实邪为患。土得润泽则木能发荣，故治以滋补，脉象与色悴燥、肌肤不充相应。", ["虚", "弦"]], "6921": ["病机", "产后肿胀，根于命阳不足，肾阳弱则阴翳不消、水湿不化。今胃纳已开、肿退未净，而右脉尚见浮大，右候脾肺，浮大为阳气外浮、脾土未复之征，非实热。故仍当扶肾阳以生脾土、壮脾气以统营血，脉象示温健未竟、调营可续。", ["浮", "大"]], "6922": ["病机", "产后营虚，血不荣筋，气滞不能充布，故手指麻木、筋牵掣痛。脉弦略数，弦主肝主筋，数示营虚而有郁热，非纯虚之候，与“气滞不能为之充布”相应。神色未痿顿、胃气尚支，故以温宣避实击虚，阳明旺则肝木和。", ["弦", "数"]], "6923": ["病机", "产后失调，土不生金，虚则肿、咳痰气升，宿痞时胀，荣虚本亢。脉来见涩，涩主血少气滞、营卫行涩，正合荣虚而气机不畅之机。土虚不能生金，肺失清肃则咳痰气升；营虚不荣则涩。故清高原兼培中州，脉涩与肿咳痞胀并见。", ["涩"]], "6924": ["病机", "产后作肿退而复发，举动喘急，脉来濡涩。濡主气虚湿滞，涩主血少行艰，合示肺脾肾三脏虚而水湿泛滥。肺虚高原不行、脾虚堤防不固、肾真阳下衰则水无制，故肿复喘急。濡涩并见为虚中夹湿、气化不利，恐水气上升，急宜温纳。", ["濡", "涩"]], "6925": ["病机", "产后失调，营虚气陷，少腹时胀、小便淋沥，症属太阳而部归厥阴，色黄而浮系营分湿热。脉濡而涩，濡为湿滞、涩为营虚血行不畅，正合营虚夹湿热、气化不利之机。故养营为主，仍拟通利以佐气化，脉象与淋沥、色黄浮相应。", ["濡", "涩"]], "6926": ["主病", "恶寒发热、头痛身疼、脘闷无汗，脉来弦紧。紧主寒主痛，弦主风主痛，弦紧并见为风寒外束、卫阳被遏、营卫不通之象。卫阳疏而风邪外袭，邪正交争则寒热头痛身疼，表闭则无汗脘闷。脉证合参，例用辛温解表以汗解。", ["弦", "紧"]], "6927": ["主病", "邪伤阳经，形寒身热、头疼脘闷、舌白脉紧。紧脉主寒，为寒邪外束、阳气被郁之征，与形寒身热、舌白相应，示表寒未解。邪在阳经当从汗解，故先宜汗解为要，脉紧正是表实可汗之凭。", ["紧"]], "6928": ["病机", "脉来弦劲，弦主气机郁滞，劲示邪势鸱张。素体发热、头胀胸闷、舌布白苔，为邪郁气分、不得汗化之象。脉弦劲与邪郁气分相应，气机不畅则胸闷头胀，邪未外达故发热无汗，治宜疏解透达，使邪从汗解。", ["弦", "劲"]], "6929": ["病机", "得汗后邪势不解，脉数舌干，数主热盛，舌干示津伤。伏邪未清，热邪内扰则烦渴少寐；汗后津液养伤，故舌干。脉数与伏邪化热相应，热不清则津难复，法当先宜清解，清其伏热以保津液。", ["数"]], "6930": ["病机", "湿热伤阴，舌红脉数。数脉主热，舌红为阴伤有热之征。湿热久蕴化热，耗伤阴液，故舌红而脉数。此脉数非单纯实热，乃湿热伤阴、虚中有热之象，故仿玉女煎法，清熱养阴并施，以救阴液。", ["数"]], "6931": ["病机", "六脉沉数，沉主里，数主热。湿邪内陷，四肢厥逆，热深厥亦深；谵语神昏、大便三候不解，乃邪归胃腑、病久元虚。沉数脉与邪热内结胃腑相应，热郁于里故脉沉，热盛故数，勉拟黄龙汤攻下以图幸。", ["沉", "数"]], "6932": ["病机", "冬温乘阳虚而发，身热不得汗解，脘闷咳逆，舌白脉弦。弦主邪郁气机、表分不畅。阳虚感邪，邪郁表分尚未施张，故身热无汗、脘闷咳逆；脉弦正示邪郁未达，法当辛散，透邪外解。", ["弦"]], "6933": ["病机", "暑湿伤气分，脘闷腹痛，上吐下泻，四肢厥冷，舌腻脉微。微脉主阳气衰微，暑湿伤气、清浊相干，故吐泻交作；阳气不达四末则厥冷。脉微与霍乱吐泻伤阳相应，理用正气法以化湿和中、回护阳气。", ["微"]], "6934": ["病机", "暑风伤肺，发热汗少，头胀咳呛，舌布白苔，脉左弦数。弦主邪郁，数主热，左脉候肺肝。暑风袭肺，邪郁不宣，故发热汗少、咳呛头胀；脉弦数示暑热郁于气分，此闭暑之候，姑拟辛解以开郁透邪。", ["弦", "数"]], "6935": ["病机", "脉弦数，暮热朝凉，汗解渴饮。弦主少阳枢机不利，数主热。邪踞少阳，正邪分争，故暮热朝凉；汗出热解而渴饮，示热伤津液。脉弦数与少阳证相应，治从少阳，和解枢机以透邪外出。", ["弦", "数"]], "6936": ["病机", "脉左濡浮，右涩，不甚数。濡浮为湿温初起，湿郁肌表，阳气不达；涩为湿阻气机，血行不畅。斑已见而热不退，神昏谵语，痉象呃逆，舌腻白渴，便闭，皆湿热蒸郁，表未达而腑气不通之象。脉不甚数，说明热势未至亢盛，但湿浊内闭，气机壅滞，故见逆境。", ["濡", "浮", "涩"]], "6937": ["病机", "脉左略弦，右大而不摄。弦为邪郁少阳，大而不摄为心营亏虚，气不收敛。解后身热未净，谵语，舌苔薄白，素日劳乏，心营本亏，故脉见弦大不摄。此邪轻而正不能复，当用滋养，以复心营，敛其浮越之气。", ["弦", "大"]], "6938": ["病机", "脉形浮濡。浮为风邪在表，濡为湿郁，风邪化热郁于太阳阳明，身热咳呛，唇燥而肿，皆风热上攻，湿郁不化之象。浮濡之脉，说明邪在肌表，湿未化燥，故拟清泄，以透风热，化湿浊。", ["浮", "濡"]], "6939": ["病机", "左脉见弦。弦为气机郁滞，中焦阻滞，暑湿内郁，三阳俱见，邪郁尚未透达。素体中虚，寒热经旬不退，呕逆，舌光而干，饮不解渴，肢节酸楚，时谵语，胸闷不舒，食冷不安。此非实热，舌光亦非阴亏，由中阻气不上乘，故脉弦。拟疏中泄表，加人参助气机。", ["弦"]], "6940": ["病机", "右脉浮大而濡，左大而不弦，热甚见数。浮大为暑湿蒸郁，气不达邪；濡为湿伤脾气；数为热甚。暑湿侵脾，中阳不运，体软色黄，四肢不能运动，身热淹久，汗出发疹不退，舌薄白而大。此中焦内闭，湿伤脾，暑伤气，故脉浮大而濡，拟益气为主，参以疏化。", ["浮", "大", "濡", "数"]], "6941": ["病机", "右脉浮大少力，左部亦滞。浮大为暑湿外蒸之象，少力为气伤，左滞为湿阻气机。暑伤气，湿伤脾，蒸郁日久，中阳被遏，身热见疹，色黄体软。外蒸之象皆浮而实，实则中寒不运，故脉浮大少力。急宜益气，佐以辛温，以运中阳。", ["浮", "大"]], "6942": ["病机", "脉数见弦。数为热，弦为郁，暑湿蒸热，红白疹俱郁，邪未清，归于阳明少阳，热在肌表，中阻而外亦不解。脉数见弦，说明热郁少阳，气机不畅，不可更散，当解肌，参用清泄，以透邪热，疏气机。", ["数", "弦"]], "6943": ["病机", "脉弦细，右数。弦为少阳郁热，细为津液渐亏，数为热盛。暑湿之邪由阳明渐入少阳，身热不退，疹见未透，脘次痞结，时谵语，舌光脱，津液渐亏。脉弦细而数，恐入厥阴，见昏厥等象。拟养阴，参以疏化，以透邪保津。", ["弦", "细", "数"]], "6944": ["病机", "右脉数而有力，主郁火蒸热，邪从阳明归少阳，逼入厥阴血分，故神昏谵语、舌绛根黄、疹点已见；左大略濡为津液已亏。数而有力示热盛，濡示津伤，热深厥阴恐风动见厥，故拟清泄。", ["数", "大", "濡"]], "6945": ["病机", "风温上受，肺气不宣，咳呛音哑、喉痛头晕，脉弦为风邪郁于上焦、气机不畅之象；舌白尖红示邪在肺卫。弦脉主风主郁，故法当化邪清金，宣肺透邪。", ["弦"]], "6946": ["病机", "暑温挟湿，误投辛散，邪未除净，蕴久阴分受损，寒起背肢、热从心炽、久咳痰腻，命门火衰、肺失升降，脉数示余热未清而阴已伤；舌白尖红为湿遏热伏。故和阴潜阳兼清化。", ["数"]], "6947": ["病机", "肝胆郁热，扰乱神明，时发多言妄笑，脉来弦劲为肝郁化火、气火亢逆之征。弦主肝病，劲示热盛而急，故苦泄柔镇以折其亢，接服养肝清心以善后。", ["弦", "劲"]], "6948": ["病机", "肌肤燥裂，六脉弦数，为血热外游之象。弦主肝郁血燥，数主热盛，血分热炽则肌肤失润而燥裂。治以滋补，寓清血热、养阴血之意。", ["弦", "数"]], "6949": ["病机", "久患溺血，气不摄阴，禀体本虚，近感暑邪，身热多汗、舌红作渴。右脉浮濡、左较细且无数象，浮濡示暑伤气分、气虚湿滞，细示阴血不足，无数象则热不炽，故参清暑益气。", ["浮", "濡", "细"]], "6950": ["病机", "肝主筋、肾主骨，其阴内亏，失于滋养，脉络不调，时或酸楚。现当夏令，脉细不甚数，细为阴血不足，不甚数示虚热不亢，故拟滋补肝肾以养筋脉。", ["细", "数"]], "6951": ["病机", "肝阴内亏，少阳火郁，潮热淹久，时吐涎痰。脉形浮数、左略弦，浮数示郁火外浮，弦主少阳郁滞，火郁灼津则生涎痰。参逍遥法以疏肝解郁、养阴清火。", ["浮", "数", "弦"]], "6952": ["病机", "原文未出脉名，以“血虚生热，热生风”立论，长夏湿蒸，风湿归营，发为㾦瘰。脾主肌肉、肺主皮毛，病仅在外形筋脉，故症尚浅。其病机核心为营血亏虚、内热生风、外湿引动，属虚实夹杂之浅层营分病变，治以养营为主。", []], "6953": ["病机", "“真阴内亏，水不制火，郁热内蒸”是本案根本，阴亏则火旺，故脉数；郁热内蒸、筋脉失养，故脉略弦。肛漏溃脓为热毒下注，肢节酸楚为阴亏筋脉不荣。数弦并见，示虚火内郁而非实热，故拟滋养以壮水制火。", ["数", "弦"]], "6954": ["病机", "营阴素亏、少阳真气亦弱，虚痰结瘿聚于颔下，舌干为少阴虚火不潜。脉形濡细，濡主气虚湿滞，细主阴血不足，正合营阴亏而真气弱之候。虚痰凝结非实邪，故拟柔剂滋补，濡细二字点出虚多实少之病机。", ["濡", "细"]], "6955": ["病机", "“气与血斗，血虚者多寒”，此症血多于气，有时作颤、但寒不热。脉形细主血虚气弱、脉道不充，与血虚作寒、气血相争致颤相应。细而无力，说明病在气血亏虚而非实邪，故以益气为主，气旺则血生。", ["细"]], "6956": ["病机", "气泛少腹上冲至心，名奔豚，属肾邪。真阴素亏、舌红脱液，则水不涵木，肝失摄纳，故左关尺脉弦大不摄。弦为肝象，大为虚阳不敛，关尺候肝肾，弦大不摄正示肾虚肝逆、冲气上泛之机，故用温纳之法引气归元。", ["弦", "大"]], "6957": ["病机", "奇脉统于肝肾，肾虚水不生木，肝木不荣，诸脉皆病。脉平时渐见冲和气，动则弦，总带涩象：弦为肝木失荣，涩为精血不充、脉道不利。此示肝肾精血亏虚、木失滋培之病机，故治肾补阴中之阳，治肝补血中之气。", ["弦", "涩"]], "6958": ["病机", "肝肾阴亏，少阳虚火蒸痰结疬于项，前曾失血、渐有咳呛，显系虚火灼津。脉浮濡而不甚数，浮为虚阳外浮，濡为阴血不足、脉道软弱，不甚数说明火势未炽。总属虚损，故酌进培补，濡而不数正合虚证本质。", ["浮", "濡"]], "6959": ["病机", "脾虚挟湿，真色外现为阴黄，中无热象。脉左弦右濡涩：左弦应肝，木旺克土；右濡涩应脾，濡为湿滞、涩为血少气滞。弦濡涩并见，示肝脾不和、湿阻血滞而无热，久恐中满，故拟温泄以运脾化湿。", ["弦", "濡", "涩"]], "6960": ["病机", "脉形见数，示血不胜湿，湿流脉络，郁而化热，故多发湿疮。数脉主热，此热由湿郁血分而来，非外感实热。凉血为主、参用苦燥，正合清血分湿热之旨。脉数与湿疮并见，说明病机在血分湿热，非单纯表证。", ["数"]], "6961": ["病机", "脉弦略数，弦主湿郁络脉、气机不畅，数主郁而化热。积湿入络归于营分，肢节发瘰，故脉见弦数。疏理之法，旨在疏泄络中湿热。弦数并见，说明湿阻营分已有化热之势，非纯寒纯虚之候。", ["弦", "数"]], "6962": ["病机", "脉来略弦，弦主湿邪下注、络脉不畅。积湿下注足胫发瘰，湿性重浊趋下，故脉弦见于下焦病变。参用益气使之下达，是借气机推动以化湿滞。略弦而非紧数，说明湿滞未至化热伤阴之候。", ["弦"]], "6963": ["病机", "原文未识脉名，以湿邪未清、脾虚不胜立论。湿滞脉络者半已结痂，说明湿邪有外解之势，而脾虚未复，气旺则复。此段重在脾虚湿滞之病机，脉象缺如，故从症候推断病本在脾，酌进培补以助气化。", []], "6964": ["病机", "脉来弦数近七至，弦主伏暑挟湿挟滞、气机郁阻，数主邪滞化火。身热咽痛、口腻作恶、目黄溲热、便黑衄多、舌干苔糙，皆邪滞化火扰荣之象。脉数近七至为热盛，症势非轻，慎防变幻，说明病机在暑湿化火、迫血妄行。", ["弦", "数"]], "6965": ["预后", "脉来沉细，沉主里、细主虚，示脾肾阳衰，纳谷不运。阳气衰微不能鼓动脉道，故脉沉细。原文谓近乎格矣，是言脾肾阳衰日久，升降将废，有渐成关格之虞。沉细为阳衰之脉，与纳运失职相应，预后堪忧。", ["沉", "细"]], "6966": ["预后", "脉来软弱无力，软弱主气血虚衰、积劳内伤。纳食梗塞、大便艰难，是阳结于上、阴凝于下，升降不通。脉弱无力说明正气已亏，非实邪壅塞，故为关格之渐。姑拟温疏以图幸功，可见病机在虚中夹滞，预后未可乐观。", ["软", "弱"]], "6967": ["病机", "脉涩而濡，涩主血少气滞、脉络不畅，濡主胃阳虚而湿滞。胃中阳虚纳食难化，阻于下口则上返攻冲，肌削色悴，是气弱而汁亦槁。脉涩濡并见，说明胃阳不足、气汁两亏，恐成络病，故拟温润以养胃阳、润胃汁。", ["涩", "濡"]], "6968": ["病机", "阴虚内热而见脉数，数主热，此热由阴亏而生，非实火。阴液不足则虚火内扰，肠络受伤故见肠红。脉数与阴虚内热之病机相应，提示热象虽显而本在阴亏，故当以滋阴清热为治，不可纯用苦寒直折。", ["数"]], "6969": ["病机", "原文谓痔由肝肾阴亏、下不能摄，又逢燥令火旺烁金，水不能制。脉来浮大，浮为虚阳外越、阴不敛阳，大为热盛而阴不足，正合其脱属虚、其胀属热之论。浮大之脉反映虚热上浮、金水失制之机，故主以滋补。", ["浮", "大"]], "6970": ["病机", "肾阴先虚，气陷下焦，命火不能化膀胱之气，故肛痔不收、小便时闭、神倦色黄。脉来浮濡，濡为阴血不足、脉道不充，浮则气陷虚阳外浮。浮濡并见，正合肾阴亏虚、气陷不摄之病机，故以补纳为主。", ["浮", "濡"]], "6971": ["病机", "肾命二虚，气不摄阴，阴络伤则血下行，故肛痔时发、腰节酸楚。脉虚弦不静，虚为精气不足，弦为肝阴亏而筋脉失柔，不静则虚阳扰动、阴不守位。此脉示肾命亏虚、肝脾阴伤而气不摄血之机，故拟填补。", ["虚", "弦"]], "6972": ["病机", "两足酸软属骨痿，由阴虚内热所致。六脉浮数无力，浮为虚阳外浮，数为热，无力则示虚，三者合观正是阴虚不能制阳、虚热内蒸之象。脉浮数无力与骨痿之阴虚内热病机相合，故宗虎潜法滋阴降火。", ["浮", "数", "虚"]], "6973": ["病机", "筋痿由厥阴郁热所致，肝主筋，郁热灼筋则筋失所养。左脉候肝，弦为肝郁筋急，数为郁热内盛。左脉弦数正反映厥阴郁热、营热灼筋之病机，故宜清营热以疏筋，使热清而筋得舒养。", ["弦", "数"]], "6974": ["病机", "四肢不用而脉沉少力，沉主里、主阴，少力为阳气不足。脾主四肢，肾阳为一身阳气之根，脾肾虚寒则阳气不能温煦四肢，故见不用。脉沉少力正合脾肾虚寒、阳气衰微之病机，故急宜温补以复其阳。", ["沉"]], "6975": ["病机", "肝肾阴亏，精血不足则筋脉失养，故右足酸楚，恐其成痿。脉形濡弱，濡为阴血虚而脉道软，弱为精气不足、脉力衰微。濡弱并见，正示肝肾精血亏虚、筋脉失濡之病机，故以填精之味补之。", ["濡", "弱"]], "6976": ["病机", "六脉弦数，弦为阴亏木旺、筋脉失养，数为阴虚内热之象。原文谓\"阴虚挟湿，两足肿痛\"，阴虚则生内热故脉数，湿邪下注、肝木失柔故脉弦，两足肿痛正是湿着筋骨、阴不濡络之候。脉见六脉俱弦数，说明阴亏与湿热并扰，非单纯虚证，故断\"病势非轻\"。", ["弦", "数"]], "6977": ["病机", "脉来细软，细为阴血不足、脉道不充，软为阳气无力鼓动。原文断为\"水中无火\"，即肾阳亏虚、命门火衰，不能温煦下焦，故下体痹痛。细软之脉正合阳微阴弱、气血不能充达之机，故治法\"当温补\"，以温肾助阳、补火生土为要，非祛邪通痹所能治。", ["细", "软"]], "6978": ["病机", "右脉濡细，濡为湿滞、细为气虚，主中阳不足、湿阻气机；左略滑，滑主痰气。原文谓\"膻中无阳，气阻上焦\"，胸膈作痛属气痹，正因中阳不振、痰湿上阻，胸中宗气不得宣通。濡细应其中虚，滑应其痰阻，故治法\"培中为主，佐以辛温\"，温运中阳以宣上焦。", ["濡", "细", "滑"]], "6979": ["病机", "脉形濡细，濡主湿、细主虚，合示中阳不振、气血不充。原文言\"膻中无阳，上焦不运\"，脘痛连背，属气痹胸痹。又以\"静为阴，气聚而痛；动为阳，散而痛止\"说明气机聚散之机，濡细正应阳虚气弱、阴寒凝聚，故拟\"培中阳，参用宣络\"，温补中阳以复气机升降。", ["濡", "细"]], "6980": ["病机", "右脉弦而略数，左部濡。弦为肝旺阴亏，数为阴火内动，濡为阴分不足。原文谓\"肝肾阴亏\"，感风兼寒，咳呛潮热、咯痰带血、咽痛，因\"厥、少二阴之脉循喉\"，咳则气升，阴火随动。弦数应阴亏火旺，濡应阴血不充，故\"不宜过于清润\"，恐滋腻碍邪，酌进养阴、静摄，防延成喉痹。", ["弦", "数", "濡"]], "6981": ["病机", "左脉略弦，右较大，重按见涩。弦主肝郁湿阻，大为邪盛，涩为湿滞血行不畅。原文谓脾胃气虚、痰湿素积，暑湿郁蒸而发热、咽痛、足酸、肤目俱黄，属湿热为患。弦大涩合示湿阻气机、血行不畅，故\"恐其成痹\"，治以轻剂宣理，化湿而不峻补。", ["弦", "大", "涩"]], "6982": ["病机", "脉大而濡，大为阴不敛阳、虚阳外浮，濡为津液亏耗、脉道不充。原文谓\"金不生水，津液两亏，三消之症也已具\"，肺金不能生肾水，津液两伤，虚热内扰故脉大，津亏失濡故脉濡。大而濡正合津亏气浮之象，故\"专主滋补\"，滋水清金以复津液。", ["大", "濡"]], "6983": ["病机", "脉形弦紧，弦为气机郁滞、筋脉失柔，紧为阴寒内结、阳气不运。原文谓\"劳乏内伤，气不生阴\"，体软色黄、消渴引饮，乃气虚不能化生阴津，津亏而燥。弦紧示气郁阴凝、虚中夹滞，非纯虚之脉，故治\"益气为主\"，补气以生阴，气旺则津自复。", ["弦", "紧"]], "6984": ["病机", "脉来弦数，弦为肝木偏旺、气机郁滞，数为内有郁热之征。本案阳不下交于阴，寤不成寐，饮食日减，正合弦数之脉：木郁化火则数，木不疏土则纳减，阴阳失交则失眠。故以半夏泻心法暂调中焦寒热、交通阴阳，脉象揭示肝胃郁热、升降失司之病机。", ["弦", "数"]], "6985": ["病机", "左脉弦大，左候心肝，弦为肝郁化火，大为火势炽盛、气血涌盛。原文谓'五火内炽'，心烦头晕、寤不成寐皆火扰神明、上干清窍之症。弦大之脉正应肝火亢盛、内炽无制，故治以苦泄，折其火势。脉象说明病机在肝火有余，而非虚损。", ["弦", "大"]], "6986": ["病机", "脉濡不甚数，濡为阴血亏虚、脉道不充，不甚数示虚火内扰而未至亢盛。原文'营液内亏，血不养肝，木火烁金'，故咳呛音哑、潮热少寐、神惝恍、色黄肌削。血少不能与卫和则潮热，魂不安则少寐。濡脉主营液内亏，不甚数说明火势尚缓，故拟静滋摄，非苦寒直折。", ["濡", "数"]], "6987": ["病机", "脉形濡弱，濡为阴血不足、脉道失充，弱为阳气衰微、鼓动无力。原文'阳弱而阴无所丽'，离坎不交，故不寐、心跳不安；向患梦泻去精，精亏及阳。濡弱并见，示阴阳两虚而以阳弱为主，神魂失藏。法当以阳引阴，正合脉象所示阳弱阴亏、心肾不交之病机。", ["濡", "弱"]], "6988": ["病机", "脉数主热，痫频发而心悸脉数，原文断为'肝郁气乱使然'。肝郁化火则脉数，气乱扰心则心悸，痰火随气上逆则痫发。数脉在此示内热扰动、气机逆乱，非单纯外感之数。先清后补，即先清肝郁之火、后补其虚，脉数为热盛之凭据。", ["数"]], "6989": ["预后", "六脉弦紧，弦为肝胆气郁，紧为邪正相搏、气机拘急。原文'肝胆郁热，膈张神昏'，郁热内闭、气逆上扰则神昏膈张。弦紧并见示邪势鸱张、内闭未解，故'惟恐痫厥'，属预后警示。脉象说明病机为肝胆郁热、气机紧束，有痉厥之虞，非平和之候。", ["弦", "紧"]], "6990": ["病机", "脉虚弱，虚为阳气不足、脉道不充，弱为鼓动无力。原文'素体气虚，脾胃不足'，阳亏阴盛，脾窍不灵，中枢不能健运，故心悸、心胆虚怯、近乎痫症。虚弱之脉正应中阳亏虚、运化失职，神失所养。拟用通阳，即温运中阳以复健运，脉象揭示虚寒内盛之病机。", ["虚", "弱"]], "6991": ["病机", "脉来濡涩，濡为阳气不足、脉道失充，涩为营血亏少、血行不畅。原文'脾阳虚而心营亦耗'，时或神昏，近痫症之象。脾阳不运则濡，心营耗损则涩，气血两伤、神失所养故神昏。濡涩并见示虚实夹杂，故培补为主、参用开泄，脉象说明脾阳心营俱损之病机。", ["濡", "涩"]], "6992": ["病机", "脾阳中虚，木克乘之，故脉弦。弦为肝脉，见于中虚之体，是土衰木亢、肝气犯脾之象。脘次作胀、寒热、色黄皆脾虚湿郁、营卫不和之症，脉弦示木克未已，恐其中满加重，故以脉测病机之进。", ["弦"]], "6993": ["病机", "暑邪挟湿，湿性黏滞，阻遏气机，右脉见紧。紧主寒主痛，亦主湿邪搏结，右脉候脾胃，紧则湿浊壅滞中焦，脘次作胀由此而致。暑湿相合，非纯寒之紧，乃湿阻气机之象，故当用疏化以宣畅中焦。", ["紧"]], "6994": ["病机", "脉来弦紧，右涩，弦紧为肝郁气滞、寒湿内搏之象，涩则湿阻血行不畅。脘次结痛连及腰脊，是肝郁侮土兼入奇脉，素体多湿，湿与寒结，气血凝滞，故脉弦紧而右涩。拟温宣者，正以脉示寒湿郁滞、非温不通。", ["弦", "紧", "涩"]], "6995": ["病机", "脉右尚和，左部略见弦象。左脉候肝，弦为厥阴气滞之征。素患脱肛属气阴两亏、下不能摄，近脘痛服药后中焦通而渐及下焦，脉左弦示厥阴气滞未解，右和则中焦渐复。拟从下焦滋纳，是据左弦知病在厥阴下焦。", ["弦"]], "6996": ["病机", "右脉濡涩，左虚弦，少冲和之象。濡涩为胃阳虚而阴亦耗，虚弦为土受木克、肝气未平。脘满作痛、食入即呕、呕多痰稠，是胃汁耗伤；大便坚结，阴亏阳弱并见。脉失冲和，故急宜培补温润，佐辛甘以复中焦之虚。", ["濡", "涩", "虚", "弦"]], "6997": ["病机", "脉来见弦，弦为肝脉，主木郁气滞。脘腹作痛连及胁背，痛无定处，正是肝气郁滞、循经攻冲之象。弦脉应肝，气滞则脉道拘急，故见弦。宣络为主，即据弦脉知肝郁络滞，治在疏宣肝络以解气滞。", ["弦"]], "6998": ["病机", "右脉濡弱无力，濡弱为胃阳中虚、寒湿所伤之象。胃阳虚则多寒，脘痛呕酸积年，曾吐瘀二次，是土衰木亢、邪必侮中。中年不应火衰，脉濡弱无力正示寒湿伤阳而非真火衰，故拟温补以复胃阳、化寒湿。", ["濡", "弱"]], "6999": ["病机", "脉来细软，细为阳虚阴弱，软为气衰不充。胃痛食减，中阳失运，纳化无权，故脉见细软无力。细软非实邪之脉，乃中阳不足、运化失职之征，治以温通，正合脉示之阳虚失运病机。", ["细", "软"]], "7000": ["病机", "原文直言“腹痛脉微，阳气衰也”，脉微为阳气虚衰、鼓动无力之象，故腹痛不由实邪，而由阳衰不能温煦。法当温理，正针对阳气衰微、寒凝腹痛之机，与虚寒性腹痛症候相应。", ["微"]], "7001": ["病机", "原文谓“肝肾阴亏，下焦不摄”，又言“肝木失养，厥阴气滞”，脉来弦细正是阴血不足、肝木失濡而气滞之象。弦主肝郁，细主阴亏，故脉弦细当用温纳，与肛痔、腹痛等厥阴气滞症候相应。", ["弦", "细"]], "7002": ["病机", "原文指出“寒湿滞气，木郁不达”，绕脐腹痛、便泄属厥阴任脉之部。脉左弦细主肝郁阴伤，右涩主寒湿滞气、血行不畅，故脉象反映木郁不达、寒湿内滞之病机，拟用温疏以解。", ["弦", "细", "涩"]], "7003": ["病机", "原文言“脾阳先亏，气从下陷”，又兼暑、腹痛便溏、脱肛、色黄而浮。脉形濡弱不振，濡主湿、弱主阳虚，正合脾阳亏虚、湿浊内困、中气下陷之机，故拟补火生土，使清升浊降。", ["濡", "弱"]], "7004": ["病机", "原文谓“厥阴气滞，专归下焦”，绕脐腹痛而“木邪归于本部而不侮土”。脉数略弦，弦主肝郁气滞，数示气郁化热之象，说明邪在厥阴本部而未传脾土，故拟宣达以疏肝理气。", ["数", "弦"]], "7005": ["病机", "原文直断“腰痛脉虚，肾阳不足也”。脉虚为阳气亏虚、鼓动无力之征，腰为肾之府，肾阳不足则温煦失职而腰痛。故脉虚主肾阳亏虚之病机，当用温补以复肾阳。", ["虚"]], "7006": ["病机", "原文谓“暑风蒸热，归于阳明少阳之部”，症见头痛右偏、目亦而小。脉形浮濡，浮主邪在表分、病位偏上，濡主暑湿蒸热、热邪轻扬，故脉象反映暑风客于阳明少阳之病机，拟轻剂凉泄。", ["浮", "濡"]], "7007": ["病机", "原文言“脾虚则土弱，营液少则失养”，外风引动内风。脉来濡涩，濡主脾虚湿困、营液不足，涩主血少滞涩、风动不畅，故脉象反映脾虚营亏、内外风动之病机，拟培补常服取效。", ["濡", "涩"]], "7008": ["病机", "左脉弦细，为肝血不足、木失濡养之象；尺脉右浮大而濡，示肾水虚而虚阳上浮。原文谓“坎水滋木，虚则木失养而风火妄动”，水不涵木则内风妄动，外风引之而头风时发，脉络失养则肢节酸麻。脉弦细主肝虚风动，浮大而濡主肾虚不藏，故以宣泄为治。", ["弦", "细", "浮", "濡"]], "7009": ["病机", "脉来弦细而紧，弦细为肝血不足、血不养肝，紧主邪亢侮中、冲脉失调。原文谓“血不养肝，邪亢侮中”，故脘次时发胀；营血不贯则冲脉衍期，风动而头痛。弦细紧并见，示血虚而邪气内紧，非单纯虚证，故拟滋养以柔肝养血。", ["弦", "细", "紧"]], "7010": ["病机", "脉滑主痰，头晕而脉滑，原文断为“内风挟痰也”。肝风内动，挟痰上扰清窍，故头晕；滑脉为痰湿内盛之征。病机在肝胃同病，风痰相搏，故以肝胃同治，化痰息风并举。", ["滑"]], "7011": ["病机", "六脉弦滑，弦主肝火，滑主湿痰。原文谓“乃肝火挟湿兼痰为患”，肝火上炎则头晕耳鸣，湿痰内蕴则脉滑。弦滑并见，示火与痰湿交结，实多虚少，故先清后补，先清肝火痰湿，再议培补。", ["弦", "滑"]], "7012": ["病机", "六脉弦软，弦为肝象，软为无力，示阳气不足、不能恋阴。原文谓“此阳不恋阴也”，阳虚失于固摄则自汗，清阳不升则头晕。弦而软，非实弦，乃虚阳浮动之象，故法当培补，温阳以恋阴。", ["弦", "软"]], "7013": ["病机", "六脉软细，软为气虚无力，细为阴血不足。原文谓“水不涵木，厥阴化风”，烦劳伤阴，肾水亏虚不能涵养肝木，厥阴风动而上扰，故头晕。软细并见，示肝肾精血两亏，故当从肝肾图治，滋水涵木。", ["软", "细"]], "7014": ["病机", "左脉虚弦，虚为血少，弦为肝脉。原文谓“血少则肝失养而胆亦怯”，心生血而血少，肝失所养，胆气亦怯，营血不贯于中。虚弦并见，示肝血亏虚而气机不畅，非实邪之弦，故仍参养营法以养血柔肝。", ["虚", "弦"]], "7015": ["病机", "脉见虚弦，虚主肝阴内亏，弦主虚风内动。原文谓“肝阴内亏，虚风上扰”，虚风上扰则胸膈不舒；又谓“内风之动必因外风”，外风引动内风，故症难脱根。虚弦示阴亏而风动，非实弦，平日当以养营为主，养血以息风。", ["虚", "弦"]], "7016": ["病机", "脉濡主气虚湿滞，涩主血少气滞，合见则肝脾二虚、气弱不能运化顽痰，虚风内动而眩晕发厥。原文明言「中无实火」，故濡涩非热象，乃正虚痰滞之征，治以培土为主、参用开泄，正合虚中夹痰之机。", ["濡", "涩"]], "7017": ["病机", "濡细为气阴两虚之象，左部见弦则肝风易动。土不培木，肝失濡养，气滞而厥、时作眩晕。脉来濡细说明正气不足为主，弦为风动之标，故治当滋补肝肾之阴以培其本，而非单纯熄风。", ["濡", "细", "弦"]], "7018": ["病机", "脉来浮大，非实热之浮大，乃脾胃气虚、痰湿中积，虚阳浮越之象；左寸略弦，为土薄木不营、虚风易动之征。故见入春耳鸣，治拟培补，正合虚风内动、痰湿内蕴之病机。", ["浮", "大", "弦"]], "7019": ["病机", "脉和说明正气尚调、无大虚大实之象。然气虚多痰，近兼湿火上升，左耳时鸣，湿属脾、火属少阳，病在湿火为患而脉未显乖戾，故拟方专主清降，清少阳之火、降上逆之湿，脉和正示病势尚浅。", ["和"]], "7020": ["病机", "脉涩主脾虚湿滞、血行不畅，左略弦为木旺动风之象。脾虚多湿，木旺动风，风扰湿邪上升，故左耳时鸣、耳后牵掣，属少阳之络。涩而兼弦，示虚风夹湿、本虚标实，故从肝脾补摄。", ["涩", "弦"]], "7021": ["病机", "左脉弦数为肝肾阴亏、木火上升之征，络热蒸痰故结核溃脓、右耳出水；右略浮现，示夏令积湿蒸热于外。弦数主火旺，浮示湿蒸，总属阴亏火旺、痰热互结，故仍拟滋补以育阴潜阳。", ["弦", "数", "浮"]], "7022": ["病机", "脉来弦数，弦为肝旺，数为火盛，合之乃水亏火旺、阴不制阳，虚火上炎迫血妄行，故头晕鼻衄。原文直断「水亏火旺也」，治宜育阴潜阳，使水足火降、血自归经，脉象正是阴虚阳亢之据。", ["弦", "数"]], "7023": ["病机", "六脉弦数，弦主肝阳偏亢，数主火热内盛，阴亏不能涵阳，阳亢化火迫血上溢，故鼻衄大发。原文点明「由阴亏阳亢所致」，弦数为阳亢火动之象，非外感实热，治当滋阴潜阳以平其亢。", ["弦", "数"]], "7024": ["病机", "脉弦主肝胆，数主热，弦数并见为胆热内盛之象。原文称「胆热积脑，鼻流秽涕」，胆火循经上蒸于脑，故鼻流秽浊之涕；脉弦数正应胆腑热盛，治以辛凉，即清泄胆热。此脉此症，病机在胆热上攻，非外感表热。", ["弦", "数"]], "7025": ["病机", "脉涩主津伤血少，不甚数则热势未炽。原文「风燥化热，从肺入脑」，燥热伤肺，咳呛痰中带血，肺津受灼则脉涩；素体劳乏，阴血本亏，故数而不甚。涩而少数为燥热伤津、肺络受损之征，非实火亢盛，故姑拟清泄而非苦寒直折。", ["涩", "数"]], "7026": ["病机", "脉数而弦，数主火，弦主肝，为肝肾阴亏、阴火上升之象。原文「肝肾阴亏，阴火上升，脑热则流秽涕」，阴不制阳，虚火上炎循经入脑，故鼻流秽涕；脉数而弦正是阴亏火旺之应。治「专从下焦滋摄」，即滋肝肾之阴以摄浮火，非清泄实热。", ["数", "弦"]], "7027": ["病机", "脉浮数而动，浮主虚阳上浮，数主火，动主阴阳相搏。原文「阴亏火升，时患鼻渊，脑热也」，阴亏于下，虚火升腾，故脉浮数而动；火升脑热则鼻渊时作。此浮非表邪，乃阴亏阳浮之象，故治「当从肝肾滋摄」，滋下以潜上。", ["浮", "数", "动"]], "7028": ["病机", "左脉弦，左候肝，弦主肝木有余。原文「火旺则烁金，肺热鼻塞」，肝火偏旺上刑肺金，肺窍不利则鼻塞；阴分本亏，木失水涵而弦。左弦独见，说明病机侧重肝火烁金、阴亏于下，故拟培补阴分以柔肝，非单纯清肺。", ["弦"]], "7029": ["病机", "脉数而弦，数主火，弦主肝脾不和。原文「脾阴内亏，湿火上升于头，鼻渊痰热郁于上膈」，脾阴亏则湿火内生，循经上蒸，痰热郁膈而鼻渊。脉数弦为湿火内郁、阴亏之应，故治「养营为主，兼清脾肺」，养阴清化并行。", ["数", "弦"]], "7030": ["病机", "脉形濡细，濡主湿亦主虚，细主阴血不足。原文「肝阴内亏，鼻衄时发」，肝阴亏虚，虚火内扰，血不循经而时发鼻衄；阴血亏少，脉道不充，故见濡细。此脉示阴亏而非实热，故「当用培补」，滋养肝阴以摄血。", ["濡", "细"]], "7031": ["病机", "左脉弦紧，左候肝，弦主肝郁，紧主邪实拘急。原文「咽痛失音，咳痰不爽」，木火刑金，肝火循经上灼咽喉，肺金受刑则咳痰不爽、失音；弦紧为肝木亢盛、气机拘急之象。故断为「木火刑金」，仿仲景法以疏肝清金。", ["弦", "紧"]], "7032": ["病机", "右脉濡数，濡主湿、数主热，正合暑湿蒸热之候。暑湿郁蒸，咽喉微痛，久而津液被劫，进而兼腐难咽，近乎喉痹。脉数示热邪内扰，濡示湿浊未化，湿热久羁则气阴并亏，故言急切难效。脉象与气阴两伤、湿热未清之病机相应。", ["濡", "数"]], "7033": ["病机", "脉来弦数，弦属肝木，数则为火。牙痛口干而脉弦数，是水亏于下、火动于上，肝木之火上炎所致。原文直断“水亏火动也”，故以滋养为拟。弦数为阴虚火旺之象，与牙痛口干症候相应，主水亏火动之病机。", ["弦", "数"]], "7034": ["病机", "右脉数大，数主热盛，大主邪实。齿龈及下唇均属阳明，热则动血，故见齿龈出血。脉数大示阳明热盛动血，然原文以养阴为主，水足制火则营络自清，可知热由阴虚而炽，脉大数正是水亏火旺、营络受灼之征。", ["数", "大"]], "7035": ["病机", "本段未识脉名，纯论病机。木火上升必在寅卯二时，又值寅卯之月，春令渐旺，营液素亏，内失滋养。少阳之脉贯胃，阳明发热或受外风，遂致齿龈出血。全段以时令、脏腑经络推阐木火升动、营液亏虚之机，故方专主清泄。", []], "7036": ["病机", "脉大而略弦，大示气虚不摄，弦示兼挟微湿。血不归经，在阳明则为牙宣、肠红，入太阳则为尿血，由气弱不能通摄所致。二足酸软亦气虚挟湿之征。脉大而略弦正合气弱不摄、湿邪内挟之病机，故以补气为主。", ["大", "弦"]], "7037": ["病机", "脉形濡细，濡主湿滞，细主阴血不足。木郁侮土则脾胀时痛，浮阳上升则齿痛咽塞，奇脉为痛。脉濡细示阴血亏虚而湿郁不化，木郁土困、浮阳上逆之机由此可窥，故拟柔剂滋补，以柔肝滋肾、调畅奇脉。", ["濡", "细"]], "7038": ["病机", "脉来沉迟，沉主里、迟主寒，下焦阳气失于运化，故大便闭结。非热结之便闭，乃阳虚寒凝、肠道失运所致，故治以温润。沉迟之脉与下焦阳虚、传导无力之病机相应，温润之法正针对阳运失职。", ["沉", "迟"]], "7039": ["病机", "脉弦右涩，弦属肝木，涩主血滞。肾为水脏，膀胱为阳水，少腹以下为厥阴之部，水中火动，下不能摄，相火寄专，尿道有阻。脉弦涩示相火妄动、阴血滞涩之机，与尿道有阻症候相应，故以滋补为主。", ["弦", "涩"]], "7040": ["病机", "脉濡右略细，濡为湿象，细为阴血不足。原文谓“肾气本虚，阴无由化”，下焦管摄无权，太阳气化失司，故小便癃闭；夏令暑伤，肺肾并理。此脉示肾虚湿滞、气化不利之病机，主癃闭，与暑伤、气虚相应。", ["濡", "细"]], "7041": ["病机", "脉形濡细，濡主湿滞，细主气虚。原文言“素体劳乏，气陷下焦，水道召阻”，劳乏伤气，气陷则水湿不化，阻于下焦，故脉见濡细。此脉说明气虚湿阻之病机，主水道不利，与劳乏、气陷症候相应。", ["濡", "细"]], "7042": ["病机", "脉濡细，濡为湿，细为虚。原文谓“下焦虚寒，厥阴气滞”，肾之外候睪丸渐致胀大而无痛楚，乃虚寒湿滞、气机不畅所致。脉濡细正合虚寒湿滞之病机，主狐疝胀大，与下焦虚寒、厥阴气滞相应。", ["濡", "细"]], "7043": ["病机", "脉来濡细，濡主湿滞，细主虚寒。原文言“肝肾本虚，寒滞下焦”，童年患狐疝时上时下，时或作痛，乃虚寒湿滞、气机升降失常。脉濡细示肝肾虚寒、湿滞下焦之病机，主狐疝，与虚寒、气滞症候相应。", ["濡", "细"]], "7044": ["病机", "右脉尚和，左脉大而见浮。浮主表，大主热盛。原文谓风邪郁久化热，由阳明传少阳，但热不寒，自汗谵语耳鸣，邪已去表。左脉大浮，知为风热内传之病机，主阳明少阳里热，与但热、自汗、谵语、耳鸣相应。", ["大", "浮"]], "7045": ["病机", "脉浮迟而濡，浮为表虚，迟为阳弱，濡为湿滞。原文谓热退邪余，脾胃本虚，多痰多湿，表虚汗多，正气未复。此脉示脾虚湿滞、表气不固之病机，主汗多神倦，与脾胃虚、痰湿、表虚症候相应，故拟六君益气。", ["浮", "迟", "濡"]], "7046": ["病机", "脉濡，濡主气虚湿滞。原文谓“脾阳中虚，表气亦弱，盗汗过多，外不能固”，神倦脉濡，乃脾阳虚弱、卫表不固之象。脉濡说明中虚湿滞、表气不固之病机，主盗汗神倦，与脾阳不足、表弱症候相应。", ["濡"]], "7047": ["病机", "脉涩而弦，涩主气血滞涩，弦主气机紧张。原文谓脾胃气虚，阳弱不能运，症见嘈杂善饥、腹坚、气随火升、肤胀多汗、四末不举，皆阴盛阳衰。脉涩弦示气虚阳弱、气机郁滞之病机，主中虚气滞，与嘈杂、腹坚、多汗相应。", ["涩", "弦"]], "7048": ["病机", "脉形浮数，浮为郁火外浮、数主热，然本案营液内亏，郁火时升，潮热召汗、色赤发瘰、咳呛，皆肝肺胃三经郁热之象。浮数非表邪，乃内亏液少、火不潜藏而浮越于外，故从肝肺胃清理，清其郁火、滋其营液，使浮数得敛。", ["浮", "数"]], "7049": ["其他", "此段述龙光幼习举业算学未成，二十七岁患阳虚弱症，咳嗽痰多、神疲食少、肌肤瘦削、举步维艰，历芩连清热、参术补虚杂投而病剧，后忿而矢志习医。原文未出脉名，仅叙病状与学医缘起，故脉象要素为空，主旨属其他，非论脉理。", []], "7050": ["其他", "此段论中国医学精深而习医者不得其法，主张由浅入深、先明躯壳血脉经络而后推及脏腑，批评方书所载躯壳脏腑模糊、选本按症略载数语、删去虚实寒热辨别之理，故绝少入门考据之书。原文未及脉象，主旨属其他，非脉学病机之论。", []], "7051": ["其他", "此段分病为客感、杂症两种，谓客感可参伤寒六经豚证辨表里寒热虚实，杂症最难，种类纷繁变动莫测，金匮未全备，诸家如中风一症刘李朱张认症各别，学者根柢未深易胶于成见而误人。原文未出脉名，主旨属其他，论学医门径而非具体脉象病机。", []], "7052": ["预后", "此段言古者名手能预断吉凶，无病戒以死期、重病告以愈期，非通术数，乃由脉症中参详而得，其理平淡妇孺能解。今人无此学问，遇重病推托张皇，遇脏气已离未见于外者茫然不觉，故所言危者安、所言安者死。主旨论凭脉症断预后，原文未出具体脉名。", []], "7053": ["病机", "此段举伤寒论浮数脉见于汗前为实、见于汗后为虚，说明切脉须与问诊所见合参，素有痞结不得发汗、素有动气不得用下，皆须问而知之。浮数一脉，汗前汗后虚实迥异，故非目见耳闻口问手诊四事合参不能辨认，主旨论脉症合参之要。", ["浮", "数"]], "7054": ["病机", "脉皆洪大而数，右寸尤甚。洪大为热盛气分、数主热，右寸候肺，尤甚则热壅肺胃。症见热极袭人、神昏躁扰、满面红光油积、小便六日不解、大便日夜百数十次、左腿水泡根盘皆红，皆洪大数脉所主之实热壅盛、热毒外发，故诊为热极之候。", ["洪", "大", "数"]], "7055": ["病机", "六部沉微，沉为阴脉、微主阳微。症见酉刻发寒、四肢冷至肘膝、渴不欲饮、舌嫩红苔黏滑、面有红光、便闭溺赤，乃阴盛于内逼阳于外、水饮内结、输机失职。前医误作阴虚火结，用青蒿鳖甲重剂反致危笃，正因沉微之脉示阴寒内盛而非阴虚，故断为水饮。", ["沉", "微"]], "7056": ["病机", "右三部浮数无力，左三部弦数无力，浮数示虚阳外浮，无力为气血大虚；弦为肝郁，数主虚热。产后情志不遂，肝郁化火，胃气已伤，故饮食不进、终日啼哭。脉证合参，虽非死候，然胃气衰败，正虚邪恋，故前辈断为胃气已绝。", ["浮", "数", "虚", "弦"]], "7057": ["预后", "脉弦数而疾，弦为肝旺，数为火炽，疾则阴液枯竭、胃气将绝。体弱性傲，肝木本旺，产后乳多乃肝火逼血化乳，非血气有余。断乳后肝火上冲如故，干咳潮热、汗多不敛，脉见疾数，法在不治，果殁于春分前，脉症相符。", ["弦", "数", "疾"]], "7058": ["病机", "两寸关俱虚软无力，两尺俱滑大。虚软无力为正气大伤，滑大为暑邪深伏、痰湿内蕴。病寒热如疟，误服藿香正气散数十剂，更伤正气，阴阳两虚，邪不能托。故脉见寸关虚软、尺部滑大，主正虚邪伏，治当扶正以托邪。", ["虚", "软", "滑", "大"]], "7059": ["病机", "右脉弦数无力，左脉弦数有力。弦为肝旺，数为热盛，右无力为气分不足，左有力为血分热炽。阴虚之体受温邪，深入血分，心肝两脏受灼，故烦躁抽掣、寒热往来。脉象弦数，主温邪入营，阴虚火旺。", ["弦", "数", "虚"]], "7060": ["病机", "两寸关脉俱滑，两尺脉沉弱。滑为痰湿，沉弱为肾虚。初诊疑孕，然尺部沉弱非胎脉，乃脾胃痰湿气滞。后尺脉数大鼓指，舌紫苔黏垢，为痰湿久郁化热，下焦热盛，迫血妄行，故崩下血块。脉症合参，主痰湿阻滞、下焦积热。", ["滑", "沉", "弱", "数"]], "7061": ["病机", "两寸洪滑，两关尺弦数。洪滑主水气壅盛于上焦，弦数主热郁于内。温病水结胸，水气因热上升填塞胸膈，故寸脉洪滑；上窍闭则下窍亦闭，故二便不通。脉症合参，主水热互结、气机闭塞。", ["洪", "滑", "弦", "数"]], "7062": ["病机", "脉沉弱而迟，沉为里，弱为虚，迟为寒。面黑黄、体瘦削、腹大坚硬、便溏尿清，纯是脾阳大虚之候。前服五皮五苓渗利，更伤脾阳，致脾虚气散，腹日坚硬。脉沉弱迟，主脾阳衰微、阴寒内盛。", ["沉", "弱", "迟"]], "7063": ["病机", "六部俱无脉，面色黑滞，舌苔秽浊厚，神识昏迷如尸寝。此伏邪深藏，蓄势暴发，上犯心肺，邪气弥满，故脉伏不见。脉症合参，主秽浊伏邪闭阻清窍，非真无脉，乃邪闭气机，脉道不通。", []], "7064": ["病机", "两关滑大而迟、重按无力，余部不应指，是胃气虚弱、运化失职之象。滑大为痰涎壅盛于胃，迟而无力为阳气不足、推动无权。痰水涎沫填满胃中，饮食为痰所裹，宿食酸腐而吐，大肠传导失润故便如马粪，小便赤涩。此非真关格，乃虚中夹痰之候，脉症相参，病机在胃虚痰阻。", ["滑", "大", "迟"]], "7065": ["病机", "脉似有似无，阳微实甚，是阳气衰微而水气内盛之象。水气凌心则动悸，浸渍肢体则身𥆧动、手足搐搦，阳虚不能温煦则面色白而微黄、体瘦如柴。寒热发于阴日、逢阳日稍安，正见阴阳交争、阳微欲绝。此极重水气病，脉微与水肿、悸、搐并见，主阳虚水泛。", ["微"]], "7066": ["病机", "两寸浮数无力，两关滑大而缓，两尺沉滑，是寒湿困阻中焦、阳气郁而不伸之象。浮数无力非真热，乃虚阳上浮；关脉滑大而缓为湿浊壅滞；尺沉滑主湿着下焦。故见面红气急、烦躁呃逆而口苦不渴、苔油黄滑腻、胸闷腹满、身重神迷，种种属太阴寒湿，前医误作燥热，反伤中阳。", ["浮", "数", "滑", "缓"]], "7067": ["病机", "脉数大有力，与神昏谵语、狂躁、面赤气急、便闭、大渴引饮、苔厚黄焦燥相应，是温邪入胃、浊邪化热之实症。数主热盛，大而有力主邪实壅盛，热灼胃津则大渴便闭，热扰神明则狂躁登高。症实脉实，故宜早下，重用硝黄以泻热存阴，非如伤寒之可迟下。", ["数", "大"]], "7068": ["病机", "脉濡弱无力，畏寒恶食，舌苔白滑，是脾虚多湿、寒痰闭阻肺窍之喉痛。濡弱为气虚湿盛之脉，非实热之象；脾虚运化失职则湿痰内生，上闭肺窍而喉痛，故畏寒恶食、苔白滑。市医误作肺胃实热，用石膏黄芩苦寒，更伤脾阳，致喉痛加剧、胸鬲板塞、滴水不入。", ["濡", "弱"]], "7069": ["病机", "两寸弦紧搏指，两足俱微弱，是上实下虚之候。弦紧为痰湿壅于上焦，寸部应之；微弱为真阳虚于下焦，尺部应之。下焦真阳不足，不能蒸水上潮，脾湿又塞窍隧，故舌干、白沫时吐、经闭倦怠。上实者痰湿拥肺，下虚者阳虚不化，脉症相符，故用清上补下分治。", ["弦", "紧", "弱", "微"]], "7070": ["病机", "两寸俱微，关尺小紧，是胸阳不振、阴寒痹阻之胸痹脉。寸微为胸中阳气衰微，关尺小紧为阴寒内结、气机痹阻。阳微不布则四肢冷厥、手足无力，阴寒上逆则汤水入喉即吐、哕恶、喉中破烂，胸中胀闷。脉症相符，故用薤白桂枝通阳散结，一剂而和。", ["微", "小", "紧"]], "7071": ["病机", "脉滑大有力而缓，面黄隐青、口鼻两颊滞气重、苔秽滑白，是痰湿内盛、肝风挟痰上扰之象。滑大为痰浊壅盛，缓主湿，有力非虚。体丰多湿，误服养阴降火十八日，抑遏阳气，痰湿愈壅，风痰上逆则头痛转剧、搐搦晕厥，昏睡不省。脉症合参，咎在药误，非真阴虚火盛。", ["滑", "大", "缓"]], "7072": ["病机", "脉微细如丝、不受重按，为气血衰微、阴血枯竭之象。原文谓温邪陷入血分，血热盛极发狂，灌雪水后邪正俱衰，仰卧如尸、呼吸甚微，阴血为热邪灼伤，血枯阴绝，经脉无血，故脉道空虚而微细欲绝，非温病常见之脉，乃热病后期阴竭正衰之危候。", ["微", "细"]], "7073": ["病机", "左脉弦弱、右脉滑大而空、三五停，为脾胃大伤、气机虚滞之象。原文谓前医多投疟门例药，脾胃受损，故脉来弦弱无力、滑大中空而歇止；虽脉不佳，然气尚未绝，故以六君子汤和胃补脾而热退能食，说明此脉主虚损而非实邪，不可用黄连枳实戕生。", ["弦", "弱", "滑", "大"]], "7074": ["病机", "脉两手浮大滑急、重按坚数，为温邪内闭、壅塞隧道之象。原文谓本温病而误用四物等阴滞之药，致内闭外脱，喘急气促、汗大如雨、舌青紫苔剥，脉浮大滑急者邪热壅盛于外，重按坚数者热结于内，故主开闭固脱，非滋阴滞腻所宜。", ["浮", "大", "滑", "数"]], "7075": ["病机", "脉滑数无力、尺部洪盛，为气分不足、湿热凝滞经络之象。原文谓烦躁面赤、亢热无汗、干呕气粗、胸胀便闭，湿热重症日轻夜重；滑数主湿热，无力为气分不足，尺洪盛示湿热下凝，故以清热化湿通经络而汗出热退，非阴虚危候。", ["滑", "数", "洪"]], "7076": ["病机", "左脉浮洪而数、按之弦，右脉浮数而弱，为阴虚之体受暑热、热陷血分之象。原文谓寒热后纯热无寒、鼻衄如泉色鲜紫，浮洪数主暑热炽盛，弦为肝热，右弱示阴分不足，热迫血妄行，故用鲜生地、青蒿等凉血透暑而愈。", ["浮", "洪", "数", "弦"]], "7077": ["病机", "左脉弦数、右脉滑数，为阴虚肝旺、痰火妄行之象。原文谓左腿疼痛筋脉牵掣、畏风寒，非寒湿乃热痰妄走周身，肝主筋，肝木既旺，痰火循肝经下行至足，经络壅遏，筋失所养，故脉弦数主肝旺，滑数主痰火，治以清肝化痰通络，忌针灸热药。", ["弦", "数", "滑"]], "7078": ["预后", "左脉浮大数疾、重按则无，右脉沉小而疾，为肾虚于下、痰壅于上、根本将脱之象。原文谓形容枯槁、神气脱离，前医误用甘寒收涩滞肺助痰，致脉败神离，浮大数疾而按之无根，乃肾将无根而上脱，故断其行期不远，属危候预后。", ["浮", "大", "数", "疾"]], "7079": ["误治", "脉浮大而弱、重按则小，为误治伤正、正虚邪恋之象。原文谓先因风邪咳嗽，医者屡用滋阴降火，致干咳、肢体倦怠、夜热肌瘦、喘急腹大、便溏溺涩，脉浮大而弱示正气已虚，重按小为根本不足，尚未绝者一线生机，全因误治至此极。", ["浮", "大", "弱"]], "7080": ["病机", "初诊两脉俱弦数、两尺洪实，弦数主温邪内伏、热郁气分，尺洪实示伏邪深踞下焦、里热壅盛，故见头痛身痛发热无汗、口渴不欲饮、小便黄少。后两脉沉小而疾，乃暑邪壅闭经气隧道，阳气郁而成火，煎熬津血，热邪内陷，故面色大变、肢冷烦躁、人事不知，脉由弦数转为沉小疾，示邪陷正伤之危局。", ["弦", "数", "洪", "实"]], "7081": ["病机", "初诊脉濡弱，濡主湿、弱主气虚，合体倦食少、面黄腹胀便溏，为脾虚湿重、血不归经之吐血。复诊寸关濡弱、两尺弦小而疾、重按始得，濡弱为外显气虚之象，尺弦小而疾乃真火内动、阴液暗伤、真阳脱出之征，故形容憔悴、神气虚羸，脉症不妙。", ["濡", "弱", "弦", "疾"]], "7082": ["病机", "两脉沉小而疾，沉主里、小主正气不足、疾主热盛，合神昏躁扰、口闭无言、二便俱无、身凉肢厥，为温邪内陷、窍闭津枯、心肝火炽。内热盛极则阳气陷于内不能外达，故身冷肢厥，脉沉小而疾正是热邪深伏、正不胜邪之象，势急危重。", ["沉", "小", "疾"]], "7083": ["病机", "左手关尺脉弦数搏指，弦主肝旺、数主热，为肝火旺极；右手虚数，虚为阴血亏、数为热，合潮热、烦躁、头左大痛如裂、五心干热、舌鲜红起刺，乃肝火炽盛、阴血耗伤之候。前服辛燥重剂更助火伤阴，若不急养阴血清肝热，恐成亡阴之象。", ["弦", "数", "虚"]], "7084": ["病机", "诊得沉滑有力之尺脉，沉主里、滑主水湿痰积，尺部有力示水气积伏下焦。合腹胀微痛、气时下坠、食后酸水上犯、舌淡紫兼黑苔厚而潮，为水气积伏、肝肾被郁、阴邪内盛之证，非虚也，故补之不效，当从水气论治。", ["沉", "滑"]], "7085": ["病机", "左寸关注小而沉，小为阴血亏少、沉为病在里，合久痢后夜不成寐近三月、抽搐惊恐二十余次、面色通赤、心烦多汗、经水久闭、舌深紫光亮如镜，乃痢后阴血耗竭、虚风内动、心神失养之候，脉小沉示正气亏虚、邪热内伏，病情危笃。", ["小", "沉"]], "7086": ["病机", "两寸脉滑如豆转、关濡、尺沉滑而小重按搏指，滑主痰、濡主湿、沉小主里，合咳嗽痰多胸闷、食少神疲肢软、小便不禁下体冷，为痰结上焦、中气不足、下焦湿浊内蕴。前医误作血虚肾虚温补两月反剧，脉症皆非虚象，乃痰湿为患。", ["滑", "濡", "沉", "小"]], "7087": ["死脉", "寸关俱绝、尺部重按至骨微小而疾、指稍起则不应指，此为败脉。寸关绝示心肺之气已竭，尺微小而疾乃肾阴耗竭、虚阳妄动，合形容枯槁、耳轮焦黑、目有绿膜、舌青紫无苔，形存神亡。前医尚用桂附，不知毒气深藏、血耗津伤，误治致目盲喘逆，终成死候。", ["微", "小", "疾"]], "7088": ["病机", "左脉弦数，右脉滑数，弦主肝热，数主热盛，滑主食积痰热。温病热入血室，兼食积，热邪炽盛，血分大伤，故见身热无汗、腹痛胁胀、吐血谵妄、手足搐搦。脉象反映热邪内迫血分，食积壅滞，与症相符。", ["弦", "数", "滑"]], "7089": ["病机", "左三部弦数有力，右三部滑数有力，尺部尤盛。弦数主肝热，滑数主痰热，尺盛示热在下焦。痰湿之体，伏热内蕴，误服辛温燥烈，致热势暴炽，鼓动痰火上犯神明，下逼肝经筋络，故见躁妄、囊坠筋牵痛甚。", ["弦", "数", "滑"]], "7090": ["病机", "左弦数，右滑数，尺脉圆大如筋到指有力，三五至一止，类促脉而非促脉。弦数主肝热，滑数主痰火，尺大示热结下焦。思虑伤脾，气滞郁而痰火甚重，枢机无权，气机皆塞，故大便久闭、胸闷腹胀、烦热多汗。脉象示痰火壅盛，气机不畅。", ["弦", "数", "滑", "促"]], "7091": ["病机", "两脉弦数无力，弦主肝郁，数主热，无力示正气已困。木火久郁，木来克土，故腹痛及胸胁；申刻发热腹痛，乃金气得令之时，木气受制而抗争。脉象反映肝郁化火，脾土受克，正气不足，与少阳厥阴经症相应。", ["弦", "数"]], "7092": ["预后", "六部俱微，惟两尺略滑。微主气血虚衰，滑主湿浊下注。病久神伤，误治致此，肌消气弱，白带如注，小便难，小腹坠痛。脉症相符，虽重非死候，微脉示正气虚，尺滑示下焦湿浊未清，预后尚可图治。", ["微", "滑"]], "7093": ["病机", "右微滑不能应指，左弦紧，俱属阴象。滑主痰，弦紧主寒饮。痰清稀带青色，口不渴，苔薄白潮滑，溺清长，面黄白，皆非肺痈之热实。脉象示阴寒痰饮内停，与肺痈之滑数实脉相反，故非痈也。", ["滑", "弦", "紧"]], "7094": ["病机", "两脉俱无，非无脉，乃伏邪内发，秽浊实邪上犯心胸，堵塞清窍，宗气不行，神明无主，故脉伏不见。症见面黄、身软、手撒口开眼合肢厥，皆宗气闭塞、百骸俱废之候。脉象模糊难辨，反映邪闭气机之险恶。", []], "7095": ["病机", "脉仍大有数意，久按无力。大数示邪热未净，无力示正气已衰。冬温十四日，身似凉，面红目赤，口舌燥，舌灰黄，乃肝肺余热未清，津液受损。脉象反映邪退而正伤，余热留恋，故以葳蕤汤存津液、凉肝肺。", ["大", "数"]], "7096": ["病机", "左脉细软为阴液亏耗、脉道不充，右关大去而尚数，是余热未清、胃津受灼。原文谓“沸阴之热，精液得滋润”，说明热邪已伤阴，故脉由大转细软，数象未尽则热未全除；舌苔黑燥、喉舌尚燥，皆阴伤燥热之征，故主养肺阴清燥，不可苦寒再燥。", ["细", "软", "数"]], "7097": ["病机", "左关候肝，脉左关反大，是肝经气火偏亢之象；然症见两太阳痛、腰痛、咳嗽喉哑痛而舌苔燥，显系燥热外袭、肝火上炎。原文提出“从症不从脉法”，说明此大脉非纯实可攻，须合症辨治，脉大在此提示肝经热盛而阴分已伤。", ["大"]], "7098": ["病机", "脉涩为血少脉道不利，营血亏虚不能濡养筋骨，故诸筋骨痛；血虚生风、肺失濡润则咳嗽无味。原文以“滋血息风”为治，正合涩脉主血虚风动之机，涩而不滑亦示无痰湿实邪，病本在血分不足。", ["涩"]], "7099": ["病机", "左关候肝，脉左手关尚弦，是肝木偏旺、疏泄失常；痛瘥而作泻、胃不开、舌尚黄，为肝旺乘脾、木郁克土之候。原文再以“肝法建中汤法”，说明弦脉在此主肝郁脾虚，故治当柔肝建中，使木土相和。", ["弦"]], "7100": ["病机", "弦为肝脉，细为阴血不足，弦细并见是肝虚不能藏血、阴分亏耗之象。寒热往来、出汗四月，久病耗伤肝阴，虚热内扰，故原文断为“此属肝虚”，用清骨散以清虚热，脉弦细正是肝虚内热之凭。", ["弦", "细"]], "7101": ["病机", "左手大、右手弱，左候肝心、右候肺脾，左大是肝火偏亢，右弱为肺气不足。气急老病又伤风，咳嗽无痰、身热头痛，乃风热犯肺、肝木反侮肺金。原文拟“清金平木法”，正合左大右弱所示肝旺肺虚之机。", ["大", "弱"]], "7102": ["病机", "浮为邪在表，弦主少阳，大为邪盛，浮弦大并见是风邪客于少阳经之象。背冷气急、腰痛、舌黄口燥有汗，皆少阳感风、经气不利所致。原文断“当属少阳经感风”，脉浮弦大正是表邪未解、少阳枢机不利之凭。", ["浮", "弦", "大"]], "7103": ["病机", "脉平为脉象和缓、无太过不及，示邪气已衰而正气渐复。少阳症身已凉、舌黄口渴咳嗽痰厚、诸筋尚痛，是余风热未尽、筋脉失养。原文谓“当祛余风热”，脉平说明正不虚而邪已微，故可专事清解余邪，不必扶正。", ["平"]], "7104": ["病机", "脉弦细，弦为少阳主脉，细为厥阴血少。胸中痛及腰、呕黄水苦，是少阳胆火犯胃、厥阴肝气横逆；咳嗽寒热为少阳枢机不利。弦细并见，示少阳厥阴合病，木火内郁而阴血不足，故主此病机。", ["弦", "细"]], "7105": ["病机", "脉已大起而全涩，大起为邪退正复之象，涩属血虚，血少不能充盈脉道。舌稍黄、有肝气，是肝阴不足兼气郁化热。涩脉主血虚，故拟滋补肝阴气分复入舒肝，紧扣“涩属血虚”之旨。", ["大", "涩"]], "7106": ["预后", "产后温邪后，左手脉小且调，小为虚象，调为和缓，故属吉象。惟数意未除，伴寐回冷汗、耳响，皆阴血亏虚、虚热内扰之征。脉小调而数，示正虚未复，然胃气尚和，预后可期。", ["小", "数"]], "7107": ["病机", "产后外感愈后五月，经未至，饮食起居均好，右手脉好，左手沉小。沉小为肝血不足、脉道不充之象。左关候肝，沉小示肝血虚滞，故曰“虚是属肝血之虚，当调其肝”，紧扣脉象与病机。", ["沉", "小"]], "7108": ["病机", "左手数大，右亦数大而脾尤觉大。数主热，大主邪盛，面红头痛、口渴、舌黄滑、小便赤短，皆冬温热盛之征。大便如水随出，乃肺移热于大肠，由湿体所致，非挟热下利。脉数大示三焦热炽，故用三焦法。", ["数", "大"]], "7109": ["病机", "暑湿误下，舌苔雪花、呃逆，泻瘥呃减而脉仍弦。弦为肝木乘脾、湿郁气滞之象。暑湿久羁，误下伤阴，木火未平，故脉弦不退。再拟复脉加减，是养阴柔肝以复脉气，紧扣“脉仍弦”之病机。", ["弦"]], "7110": ["病机", "暑湿误下，舌雪花、口燥甚、出冷汗，脉左手已小，右手尚大。小为阴血亏虚，大为邪热未清。左小右大，示误下后阴伤而热势偏盛于右，故再以前法益阴固脾，紧扣“左手已小，右手尚大”之象。", ["小", "大"]], "7111": ["病机", "脉皆滞缓，滞为湿阻气机，缓为湿性黏滞。疟久两月，汗出嗜卧、身重、舌白苔滑、呕黄水、腹痛口淡，皆太阴湿困之征。热时之数不作凭，示湿郁为本。脉滞缓主太阴湿疟，故拟温劫湿邪。", ["滞", "缓"]], "7112": ["病机", "肚痈后致弱，脉虚小之至，是气血耗伤、肝肾阴分至虚之象。虚小为不足之脉，逢吃力即咳嗽失血、腰足骨酸，正合肝肾阴亏、虚火上逆、筋骨失养之机，故脉虚小主虚损而非实邪。", ["虚", "小"]], "7113": ["病机", "肝病胀与如崩均减而带甚，脉仍弦数，弦为肝旺，数为热，示肝经郁热未清、血热未宁。虽症减而脉未和，故再以调肝，说明弦数脉主肝热内扰、疏泄失职之病机。", ["弦", "数"]], "7114": ["病机", "久咳痰臭气急、口味甜、小溲红，脉弦大，弦主风，大主热盛，合为肺分风热之象。风热壅肺则咳急痰臭，热伤津液则溲红，甘味上泛亦属热蒸，故脉弦大主肺经风热壅盛。", ["弦", "大"]], "7115": ["病机", "久嗽用药后臭痰已瘥，口味尚甜，脉尚弦而已小，弦为余热未清，小为邪减正亦不足。脉由大转小，示肺热渐退而阴分受伤，故再以甘寒清养，说明弦小主热减而津伤之病机。", ["弦", "小"]], "7116": ["病机", "肺胀一年，咳嗽痰少、口渴舌黄、便痛泻、溲少，脉弦细。弦为气逆，细为阴伤，示上焦肺胀日久、气壅津亏、热郁于上，故当治上焦，脉弦细主肺气壅逆兼津伤之病机。", ["弦", "细"]], "7117": ["病机", "动则气喘属肾虚，烟气咳喘属肺气冲，脉弦细是肝冲。弦细为肝阴不足、肝气上逆之象，肝肾之气冲肺而肺气亦虚，故脉弦细主肝冲犯肺、下虚上逆之病机。", ["弦", "细"]], "7118": ["病机", "肝痛已瘥而左脉尚弦数，经期如崩、腹中痛胀、口渴，弦为肝旺，数为血热，示血热妄行而不摄。脉弦数不去，故知血热未清、肝不藏血，主崩漏之因于热扰血海。", ["弦", "数"]], "7119": ["病机", "咳嗽背冷、身上觉胀、舌净，脉弦浮。浮主表主上，弦主气逆，合为肺胀之象，风寒束肺、气壅不得宣降，故背冷而胀。脉弦浮主肺胀属上焦气壅之病机，故用上焦法。", ["弦", "浮"]], "7120": ["病机", "脉弦数，弦主肝气，数主热。久嗽舌黄为热象，气急发热为风热壅肺。原文谓“伤风带起肝气，又有重感”，说明外风引动肝气，肝热犯肺，故脉见弦数。此脉主肝热犯肺之病机，与久嗽、舌黄、气急发热相应。", ["弦", "数"]], "7121": ["病机", "脉弦细，弦为肝脉，细为阴血不足。大流鼻衄后血止而面色痿白、耳响、太阳痛、腰酸，乃失血后肝阴亏虚，虚阳上扰。舌黄为余热未清。原文“当用甘寒肺金”，说明病机为肝阴不足、肺金失养，脉弦细主阴血亏虚兼肝郁。", ["弦", "细"]], "7122": ["病机", "脉弦细，弦主少阳，细为邪入半表半里。原文“仍属少阳症，已有三日”，说明外感邪传少阳，枢机不利。弦细为少阳本脉，主邪郁少阳、胆热内蕴，与寒热往来、口苦等少阳症相应。", ["弦", "细"]], "7123": ["病机", "脉尚弦，弦主肝胆风木。耳痛聋响、流脓、腹痛水泻，经肝胆法治疗后耳痛腹痛去而脉仍弦，原文“再以风木法”，说明肝胆风木之邪未净，木旺克土致水泻。脉弦主肝风未息，与口渴作响、水泻相应。", ["弦"]], "7124": ["病机", "脉浮弦小数，浮为表，弦主肝，小为阴不足，数为热。咳嗽失红两年、寒热十月，初由暑风湿热，久传厥阴。原文“清金平木法”，说明病机为暑风湿热久郁，传入厥阴，肝风犯肺，脉浮弦小数主表热未清、肝阴受损。", ["浮", "弦", "小", "数"]], "7125": ["病机", "脉沉涩，沉主里，涩主气滞血瘀。胃痛流涎、呕清水味酸、嗳气、舌白燥、胃不开，乃肝气郁滞，胃失和降。原文“法当滋肝舒气”，说明病机为肝郁气滞、胃气不和，脉沉涩主气机郁滞、血行不畅。", ["沉", "涩"]], "7126": ["平脉", "脉平，即脉象平和，无太过不及。作泻四月，舌黄口微渴腹响，而脉平、小溲如常，说明脾胃虽病而未至脉象失常。原文“是当调其脾胃”，脉平提示病在脾胃气机失调，非大虚大实，故以调和为法。", ["平"]], "7127": ["病机", "脉沉大而滞，沉主里，大为阳脉，滞为湿象，数属化热。原文“是湿体之象，数属化热，而大属阳脉”，说明湿体蕴热，肺阴受伤，肝风内动。脉沉大而滞主湿阻热蕴、气机不畅，与舌灰白滑、便泻、手牵足痛、易怒相应。", ["沉", "大", "滞", "数"]], "7128": ["病机", "风温失红，脉弦细。弦为风木之象，细为阴血不足。风温化热伤及肺络则咳痰带红，热灼津伤则口渴、舌白气急。脉弦细示风热未解而阴分已伤，属风温失血后正虚邪恋之候。", ["弦", "细"]], "7129": ["病机", "风温十天，脉弦数，舌黄口渴，是邪已化火。弦主风木，数主热盛，弦数并见为风火相煽。咳嗽作泻、腹痛乃木火犯肺侮脾，冷作热为热郁阳不外达。脉示邪从热化，表里俱有郁热，故当表里均解。", ["弦", "数"]], "7130": ["病机", "喉痛寒热十日，欲呕胸肋痛，脉弦细，舌黄，是少阳经感风热。弦为少阳主脉，细为邪郁阴分、营血不畅。胸肋痛、欲呕为少阳枢机不利，寒热无汗为邪郁表分。脉弦细正合少阳风热郁而不达之机，故用逍遥散疏解。", ["弦", "细"]], "7131": ["病机", "风温后又感风邪，作冷出汗，舌白，脉弦。弦为风邪未净、肝木偏旺之象。风邪外袭则作冷，营卫不和则汗出，舌白示邪未全化热。脉弦说明风邪留恋、木气不舒，故再当甘寒以清余热、柔肝息风。", ["弦"]], "7132": ["病机", "风温后邪已净，惟胃不开，稍有咳痰，两脉甚虚。虚脉主正气不足，邪去而脾胃气弱，运化无力故胃不开；肺气亦虚，故稍有咳痰。两脉甚虚是风温耗伤气阴之后，正虚未复之象，非邪恋之候。", ["虚"]], "7133": ["病机", "腹腰作痛，期早而多如崩状，脉弦大，当调其肝。弦为肝脉，大为气火亢盛。肝失疏泄、藏血失职则经期早而量多如崩；肝气横逆则腹腰作痛。脉弦大示肝旺气盛、血失所藏，故治当调肝以复其藏血疏泄之职。", ["弦", "大"]], "7134": ["病机", "六脉弦小数，舌苔黄厚，口燥不渴，咳痰气急肋痛，多梦话。弦为肝风，数为热，小为阴分不足。热邪未清、肝风内动则梦话、咳引肋痛；苔黄厚口燥示余热夹痰。脉弦小数说明肝经风热未净而阴分渐伤，故再当凉肝息风。", ["弦", "小", "数"]], "7135": ["病机", "身热三日，出冷汗，咳嗽有痰，胃不开，口燥头眩，脉弦。弦为风木之象，风热外袭则身热，风阳上扰则头眩，木旺克土则胃不开，风热灼津则口燥。冷汗出为卫表不固。脉弦示风热未解、肝木偏亢，故用甘寒清解。", ["弦"]], "7136": ["病机", "久经失红，阴血耗伤，脉道不充故细；肝血不足，木失柔养则弦。弦细并见，示血虚而肝气不舒，故咳嗽右肋痛、少寐。原文谓'少寐即血分之虚'，正合阴血亏虚、心神失养之机，治当清金润肺以复其阴。", ["弦", "细"]], "7137": ["病机", "六脉弦数，弦主肝木气盛，数主热。咳嗽失红本属肺热，今逢食即吐、胃不开，是风温之邪夹胃热上逆。原文断'出于肺脏'又虑'夹有风温'，弦数正示热盛于内、木火刑金，故仍从风温失红例治。", ["弦", "数"]], "7138": ["主病", "疟发间日转两发，小溲赤、足酸、腹中痛、肋痛，皆厥阴肝经之候。脉弦为肝病主脉，细为阴血不足，邪伏少阳厥阴。原文断'当属厥阴大疟'，弦细正合疟邪深伏、肝络不和之机。", ["弦", "细"]], "7139": ["病机", "盗汗伤阴，舌黄滑、便溏、胃不开，是阴亏而脾土亦弱。脉弦小数，弦为肝旺，小为阴血不足，数为虚热内扰。原文'当益阴调土'，正合阴虚火动、脾运不健之机，弦小数即虚热夹肝脾不和之象。", ["弦", "小", "数"]], "7140": ["主病", "寒热十三日，胸胃塞痛，是邪郁少阳、肝脾不和。脉弦主肝胆气郁，细示阴血渐伤。原文'当用逍遥散'，正取疏肝解郁、健脾和营之意，弦细即肝郁血虚、木不疏土之脉证。", ["弦", "细"]], "7141": ["病机", "身热虽凉而咳嗽多痰、冷汗、舌黄口燥、便溏气急，脉弦数。弦为风木之象，数为热盛，原文断'当属风温，久则化火'，是风温余邪化火、木火刑金，故咳痰气急；热迫津泄则冷汗，热灼则口燥。", ["弦", "数"]], "7142": ["病机", "喉痒燥则呕、头筋胀痛、腹胀、舌黄，脉右手调而左手有数意。左脉候肝，数主热，是湿热郁于肝经、上扰清窍则头筋胀，犯胃则呕。原文'大抵湿热为病'，数意正示热郁于内，右脉调和则脾未大伤。", ["数"]], "7143": ["病机", "风邪解后余热未清，脉稍弦滞。弦为余邪郁于肝络，滞示气机不畅、热与痰湿相结。故舌黄、干咳作空呕、出汗，皆余热内扰、肺胃不和之候。原文'拟用甘寒以解余邪'，弦滞正合邪郁未彻之机。", ["弦", "滞"]], "7144": ["病机", "原文以「脉未滑利」为据，说明湿疟虽口渴、舌黄而滑，但脉象尚未见滑利之象，提示湿邪仍困阻中焦、气机未畅，热象不著。故不可因口渴、舌黄而径用寒凉，据理仍当温燥中焦、兼以通阳，使湿化阳通，脉转滑利则病退。此段以脉象未变判断病机仍属湿阻，指导治法。", []], "7145": ["病机", "舌白体肥、胃不甚开、大便易溏或时作嘈，皆脾运不健、湿痰内蕴之象。诊得「脉短涩」，短主气机不畅、涩主血行滞涩，合而示痰湿阻遏、气血运行不利，故断为「脾胃多湿痰」，拟祛痰益脾，使痰化脾健则脉自畅。", ["短", "涩"]], "7146": ["病机", "伤风日久，痰黏喉中有声，是风邪入里、痰热内蕴之候。脉「弦」主肝木偏旺、气机郁滞，痰热阻于肺系则喉中痰鸣。弦脉示木火刑金、痰热胶结，故不用辛散而用甘寒法，以清润化痰、柔肝保肺，使弦脉得缓。", ["弦"]], "7147": ["预后", "暑邪二十二日，舌上已有雪花，是阴液大伤、胃阴将竭之危候。「六脉弦大」者，弦为肝气偏亢，大为阴不敛阳、虚阳外浮，病久阴亏而脉反弦大，正合「断无下攻之理」。误以制军伤脾，今见呃逆，是肝气亦起，病属棘手，故须速救阴，预后堪忧。", ["弦", "大"]], "7148": ["治法", "此段为复脉加减方，未载脉象。方中生地炭、炒白芍、炒麦冬、地骨皮、炒怀药滋阴救液，清炙甘草、生苡仁、陈皮、阳春砂理脾和胃，旋覆花降逆。合观乃针对前段阴亏呃逆而设，属「救法」，以滋阴柔肝、和胃降逆为治，非凭脉断病。", []], "7149": ["预后", "诊得「右关已起」，余脉「欠有精长之象」，是病后胃气渐复而整体未复元。冬令脉「宜静小」，今脉虽静小却由「血不应脉」所致，非平脉之静小，故断为病后不复元、血虚不能充脉，再拟两益肝脾，以养血复脉，属病后调摄之预后判断。", ["小"]], "7150": ["病机", "怕冷去、咳嗽瘥、痰有、舌净，是外邪渐解而余痰未清；惟胃不开，诊得「脉弦小」。弦主肝木乘脾、气机郁滞，小主正气不足，合示肝胃不和、余痰阻中，胃气未醒。故用甘寒法，柔肝清养、和胃化痰，使弦小之脉渐和。", ["弦", "小"]], "7151": ["病机", "头胀、背间怕冷、腰肋咳时作痛、胸膈塞闷作呕，皆肺邪郁遏、气机不宣之症。诊得「脉浮微」，浮主邪在表、微主正气不足；「右手中部稍数而涩」，数示郁热，涩示气滞痰阻。合而断「当属肺邪」，以浮微涩数示肺气郁滞、痰热内阻而正虚。", ["浮", "微", "数", "涩"]], "7152": ["病机", "脉由虚小渐去而尚数，示白虎汤后大热已减，然余热未清，故数象独存；中沉之滞大已除，说明里滞已化，但大便溏、小溲长、口渴去而燥，是热退津伤、肺失清肃之象，脉虚小为正气未复，数则余邪未净，故再拟凉肺通溲。", ["虚", "小", "数"]], "7153": ["病机", "风温身热退、昏语去、泻止，而脉尚弦，咳嗽有痰、胃口不开，是外热虽解，肺胃痰热未清，肝木偏旺，弦为气机郁滞、痰热内阻之象，故当用甘寒清养肺胃，使痰化气降而弦脉自和。", ["弦"]], "7154": ["病机", "身热七八日，咳嗽有痰、水泻腹痛、昏语、口大渴、舌鲜红，脉弦小数，是邪在心肺之间，弦主邪郁，小为热灼阴伤，数则热盛；肺与大肠相表里，故泻在肺，昏语为邪入心包之重症，当用上焦法清透心肺。", ["弦", "小", "数"]], "7155": ["病机", "病久属虚，逢劳则发为劳复，脉虽数而沉虚作冷，数非实热，乃阳虚气浮之象；坐久伤气，责之阳虚，筋骨作酸总属血事，是气血双亏、脾肾不足，故用归脾汤加减补益心脾、温养气血。", ["数", "虚"]], "7156": ["病机", "十三龄室女去冬患下焦肝痛，六脉弦数，弦为肝气郁结、木失条达，数为郁热内扰；室女情志易郁，肝经郁热下注下焦，故痛在肝部，当用张石顽先生法疏肝清热、调畅气机。", ["弦", "数"]], "7157": ["病机", "肝痛在胃已月余，舌苔、脉弦数、怕冷，弦主肝郁，数主郁热，肝木犯胃，气机不畅故痛；怕冷非真寒，乃阳郁不达，热郁于内而外失温煦，当用河间法清肝泄热、和胃调气。", ["弦", "数"]], "7158": ["病机", "休息痢四年，用药痛尚在而少解，脉尚弦，舌尚黄，弦为肝木偏旺、气机郁滞，黄为湿热未清；久痢脾虚而肝木乘之，湿热积滞未净，故痛减而未已，再当前法疏肝清湿热、调气和血。", ["弦"]], "7159": ["病机", "咳嗽已去，右乳曾作突，嗣成小疮，延走乳上近腋下，脉弦小，弦主肝风，小为郁热伤阴；乳头属肝，肝经郁热化风，循经外发，故疮疡延走，此属肝风郁热，当清肝散风、凉血解毒。", ["弦", "小"]], "7160": ["主病", "六脉弦小细数，弦主肝郁，细为阴血不足，数为有热。寒势往来半年，乃少阳枢机不利、肝郁化热之象；头痛冷汗、咳嗽、腹痛泻，皆肝木乘脾犯肺所致。无汗者逍遥散疏肝解郁，有汗者清骨散清虚热，正合弦细数所主之郁热伤阴病机。", ["弦", "细", "数"]], "7161": ["病机", "先肝气作痛，后咳嗽失红、腹痛作泻，舌黄脉弦。弦为肝脉，主气郁化火；舌黄为热象。肝火犯肺则咳血，乘脾则痛泻，或如痢或水泻，皆木旺克土之变。少有寒热，是郁热未深。脉弦一症贯穿始终，故以清肝为法，紧扣肝气横逆之病机。", ["弦"]], "7162": ["病机", "休息痢四年，腹痛、胸腹足皆肿、解出如墨水，脉弦细。弦主肝，细主阴伤，痢久伤阴而厥阴肝木不调，疏泄失职，水湿泛滥故肿，络伤血溢故色黑如墨。断为痢在厥阴，正是弦细脉所主之肝络不和、阴血亏耗病机，故两剂已效。", ["弦", "细"]], "7163": ["病机", "因跌胸痛，呕出瘀血多，继而泛呕痰饮，诊脉弦细。弦为肝脉，细为血少阴伤；跌仆瘀阻，肝失疏泄，木不疏土，胃气上逆，故呕痰呕饮。脉弦细正示肝胃不和、瘀去而阴血未复之机，故治法当调其肝胃，使木土相和。", ["弦", "细"]], "7164": ["病机", "病经月余，舌白、腹痛作溏、气急咳嗽痰多、夜汗，脉弦小。弦主肝郁，小主正气不足；冬温失治，外寒束表、内热郁肺，肝木乘脾则痛溏，肺失宣降则咳喘。脉弦小示邪郁正伤、寒热错杂，故用外寒内热之法，解表清里并行。", ["弦", "小"]], "7165": ["病机", "原文未识脉名，仅言「诊脉左关当起」。左关候肝，泻止而痛未去、舌净，是风木乘脾之泻虽止，肝气郁滞未净，左关脉当起而未平，正示肝气未疏之病机。故以风木法续调肝气，使左关脉复其常，则痛自除。", []], "7166": ["主病", "久嗽声哑、痰臭，脉大。久嗽肺阴亏耗，金破不鸣则声哑；痰臭为热毒壅肺、腐肉成脓之征。脉大者，热盛于内、邪气亢盛，然久病见大脉亦当防正虚邪实。甘寒之法清肺润燥、解毒排脓，正合脉大所主之肺热壅盛病机。", ["大"]], "7167": ["病机", "风温六日，咳嗽气急、口渴舌黄、背冷自汗，脉弦大。弦主风木，大主热盛；风温之邪郁于肺卫，化热伤津故口渴舌黄，热迫津泄故自汗，卫表不和故背冷。脉弦大示风热壅盛、邪在气分，故用辛凉透解，清宣肺卫之热。", ["弦", "大"]], "7168": ["病机", "脉弦细，弦为肝脉，细主血少。患者失经年余，血海空虚，肝失濡养，疏泄失常，故寒热往来、口苦、胸胀欲呕；肝气犯肺则咳嗽。舌净示无实热痰浊。此脉象反映肝血不足、肝气郁滞之病机，属肝病，故用清骨散法养血清肝。", ["弦", "细"]], "7169": ["病机", "脉弦细，弦主肝风，细主阴血亏虚。肝风内动，上射于肺，灼伤肺络则嗽血；肝木乘脾，脾失健运则痛泻。此脉象说明肝血不足、风动于内，木叩金鸣、土受木克之病机，故用土中拔木法培土宁风。", ["弦", "细"]], "7170": ["病机", "脉弦数，弦主肝郁气滞，数主热。胸中痛、胃下开，为肝气横逆犯胃，气机不畅，郁而化热。此脉象反映肝胃不和、气郁化火之病机，故用河间法清肝泻热、和胃降逆。", ["弦", "数"]], "7171": ["病机", "左手脉弦大，右手弦，弦为疟邪伏于少阳厥阴，大为久疟正虚、邪气未净。间日疟反复，盗汗多，汗多则阴血更耗，故曰久疟必虚。此脉象示正虚邪恋、营卫不和之病机，当遵柯氏法扶正截疟。", ["弦", "大"]], "7172": ["病机", "脉弦细，弦主肝风，细主阴血不足。高年素咳血，阴血本亏，肝风内动，上射于肺，损伤肺络，故咳血复发、痰中带血；肋背抽痛为肝风窜络，寒热为营卫失和。舌白示无热象。此脉象说明血虚肝风射肺之病机。", ["弦", "细"]], "7173": ["病机", "产后左手脉应细虚，右手弦大。细虚为血虚之常，弦大为肝风偏亢之象。喉燥、肌热、动则有汗，为血虚阳浮；肌肤作肿，为风木乘土。恶露未净而经多且旺，有黑块，恐血虚风动，冲任不固，日久成崩漏。此脉象示血虚肝风为病。", ["细", "虚", "弦", "大"]], "7174": ["病机", "脉弦细，弦主肝，细主血少。目视不清，为肾轮之事，肾精肝血不足，不能上奉于目。方书用石决明、五味子同用，可使目视得力，然脉弦细示阴血亏虚，药不宜过重，以免伤正。此脉象反映肝肾阴血不足、目失濡养之病机。", ["弦", "细"]], "7175": ["病机", "大疟后脉弦大，弦为厥阴肝脉，大为邪气未净、正气已伤。疟后咳嗽、舌黄、盗汗，为余邪未清、阴分受损；腹痛响泻，为肝木乘脾、脾虚湿盛。此脉象说明疟邪出于厥阴，肝脾不和、正虚邪恋之病机。", ["弦", "大"]], "7176": ["病机", "右手脉弦大，左关独数，为肺疟邪热未净之象。弦主疟邪未解，大示热势尚盛，数则热郁于内。虽汗已透而头汗未至，邪未尽达，故脉仍弦大；左关数，木火偏旺。胃口两便均好，说明病位偏肺，未传中焦，故断为肺疟。", ["弦", "大", "数"]], "7177": ["病机", "六脉滞大，滞为湿阻气机，大为热盛，合之便溏、掌心热、嗜卧，显系肺分湿热内蕴。湿热滞于肺，气机不畅则脉滞；热郁于内则脉大、掌心热；湿困脾肺则便溏嗜卧。脉症相参，主肺经湿热，非虚寒之候。", ["滞", "大"]], "7178": ["病机", "脉弦数去而右手滞大，左手滑利，示疟邪寒热已退，而湿热未净。弦数去为暑邪渐解，右手滞大乃肺分湿热壅滞未除；左手滑利为邪退之象。舌苔尚黄、大便响泻，皆湿热下迫。故曰暑净而湿热未除，再从肺治。", ["弦", "数", "滞", "大"]], "7179": ["病机", "脉细数，右关少带滞象，为冬温后肺阴亏虚、余热未清之候。细主阴伤，数主余热，右关滞示肺胃气机不畅。病中经至，血分更虚，故无汗出；阴虚无以濡养，则喉燥喜饮、面红、目牵耳痛。总属肺阴不足，兼肝风火内动。", ["细", "数", "滞"]], "7180": ["病机", "六脉弦数，舌黄燥，为感风在肝、肺分热邪未净之象。弦主肝风，数主热，风热相搏则脉弦数；舌黄燥示肺热伤津。虽已出汗，然冷汗出而脉仍弦数，说明风邪未彻，热邪内郁。小溲时黄、大便时溏，兼夹湿邪，故当清肺肝风热，兼化湿滞。", ["弦", "数"]], "7181": ["病机", "出瘄三日，身热大汗，背上已见，脉弦滞，为风热郁于肌表、欲透未彻之象。弦主风，滞主气机不畅、邪有郁遏。舌黄无嗽泻，说明热在肺卫，未入中焦。脉弦滞而身热汗出，风热有外透之势，故当托风热，助其透达。", ["弦", "滞"]], "7182": ["病机", "瘄后寒热、无物不呕，脉弦数较前已大，为肝阳犯胃、风木乘脾之候。弦主肝木，数主热，脉大示邪盛。肝阳上逆则呕，木邪乘脾则泻，喉梗胸痛亦肝气上冲所致。脾胃两受木邪，故先除呕，兼治喉梗胸痛，法当平肝和胃。", ["弦", "数"]], "7183": ["病机", "瘄后身凉、便溏、咳痰少、知苔少、胃不开，脉已缓，为邪退而肺胃未和之象。缓为病势已缓，非邪盛之急脉。身凉示表热已解，便溏、胃不开示脾胃气弱未复，咳痰少为肺余邪未清。脉缓而症见虚象，故再从肺治，用甘寒法养肺胃之阴。", ["缓"]], "7184": ["病机", "身热四日，有汗，瘄毒已得泄而轻，然诊脉尚数，数主热盛，说明肺经风热未尽，余邪仍稽留于气分。面色红、喉痛、舌上无苔，皆风热上攻、肺津受灼之象，故脉数未净，当续用肺风热法清透余邪。", ["数"]], "7185": ["病机", "久泻舌净，腹中响而间痛，泻如水，是脾虚甚；诊脉弦数，弦主肝旺，数主有热，说明肝木乘脾、脾虚夹热。响多痛少、泻如水，偏于脾虚，故脉弦数反映肝脾同病，治当舒肝扶土，标本兼顾。", ["弦", "数"]], "7186": ["病机", "出瘄满月又受风，身热有汗、头胀舌燥、夜间口渴、小溲热，诊脉弦数已四日，舌微黄而燥，腹中时痛。弦数为风热内郁、肝胃热盛之象，热灼津伤故燥渴，风热未清故身热头胀，拟辛凉合甘寒以透风热、生津液。", ["弦", "数"]], "7187": ["病机", "瘄后脉虚，是正气已伤；舌尚黄、大便素有泻病，属肾虚不固。脉虚主气血不足，外感风热余邪下移，正虚而邪未净，故当先祛外感风热之下移者，再议补虚，体现先祛邪后扶正之意。", ["虚"]], "7188": ["病机", "经停三月，暑邪已净而胃开，然六脉弦大稍有数意，是素体阴虚有热之征。若为孕脉，当静小柔和，今脉欠静缓、过于有力，故未敢确认为孕。弦大为肝阳偏亢、阴不敛阳，数主内热，宜凉滋肝分以养阴清热。", ["弦", "大", "数"]], "7189": ["病机", "舌黄、胃不开、脉滞，因食面而作泻。面食善助湿热、动肝气，湿热内蕴则舌黄胃呆，肝气犯脾则作泻，脉滞正是湿阻气机、运行不畅之象。故拟除面积兼调胃，以化湿消滞、疏调肝胃。", []], "7190": ["病机", "右手颇有收敛之象，关脉颇滑利有神，左关较前收小，是震象渐复、胃气有神之征。滑利有神主胃气尚存、生机未绝；惟腹中时痛、胃胀，是肝气未调，故再拟调肝保元，既顺肝木又保元气。", ["滑"]], "7191": ["病机", "出瘄六日，身热五日后出瘄，背上有为齐，大便泻、舌燥白，诊脉弦数。弦主风动，数主热盛，说明风热之邪郁于肺胃未净，故当按时令用辛凉合甘寒法，透风热、清里热，使瘄毒尽解。", ["弦", "数"]], "7192": ["病机", "原文谓「诊脉涩且大，左手尤涩，涩属血虚，当益血分」。涩为血少脉道不充，大为阴血亏而气浮，左脉候血，左手尤涩更印证血分不足。故本段以涩大之脉断为血虚，主血亏之证，治法当益血分，与补血养阴相应。", ["涩", "大"]], "7193": ["病机", "原文述产后去血过多属虚，肠上下有块按之不痛，为「肝气之不舒」，并明言「脉弦是肝病之象，蛔虫属肝，虫由于湿热」。弦为肝脉，主气机郁滞，故脉弦反映肝气不舒、湿热生虫之病机，与气闷、腹块等症相应。", ["弦"]], "7194": ["病机", "原文因饭时淘气致胃口稍减、左肋下作胀、转矢气不畅，诊「脉稍数」，舌苔右黄。数脉主热，稍数示郁热不甚，气郁化热，木郁犯胃，故见纳减、胁胀、矢气不畅，治以香砂法加减理气和中。", ["数"]], "7195": ["病机", "暑邪五天，舌黄、晚间作热有汗、热甚则言，为暑热内盛；「脉左手尚数，右手已缓」，数主热，左数示血分热盛，右缓示气分热势稍退。适逢经期，故用热从血泄法，使暑热随血外泄，脉象正示热偏于血分。", ["数", "缓"]], "7196": ["病机", "原文见气急咳嗽无痰、汗多、诸筋抽痛、饭不得下、口渴、小便热，诊「脉浮弦」，断为「肝喘」。浮为邪在表、气逆于上，弦为肝病，肝气上逆犯肺则喘咳，筋失养则抽痛，故浮弦之脉主肝气逆而作喘。", ["浮", "弦"]], "7197": ["病机", "咳嗽舌黄已十日，下午作热，两肋痛，诊「脉弦细」。弦主肝，细主阴血不足，肝阴亏而风动，木火刑金，故原文断为「肝风之妨肺」，脉弦细正示肝阴不足、风热内扰之病机，与胁痛、午后热相应。", ["弦", "细"]], "7198": ["病机", "痛泻已去、寒热亦减、舌净，而「脉仍弦」，说明邪减而肝气未和。原文述腹中有块梗痛、胃不开，再当调肝。弦为肝脉，主气郁不舒，故脉仍弦示肝木未调、气机郁滞，与腹块梗痛、纳呆之症相应。", ["弦"]], "7199": ["病机", "寒热往来、头痛胸肋痛、咳嗽气急、舌黄已五日，口苦欲呕，诊「脉弦细」，断为「少阳受风之症」。弦为少阳主脉，细示邪郁而正气不足，风邪客于少阳，枢机不利，故见寒热、口苦、胁痛，脉弦细正合少阳受风之机。", ["弦", "细"]], "7200": ["病机", "六脉全芤，芤主血虚，妇人崩漏、小产后血分大虚，脉道失充故见中空之象。原文又言冷气上冲，引丹溪“非真冷也，此属肝气之逆”，说明血虚而肝气上逆，冷感为气逆所致，非真寒，脉芤与崩漏、小产失血及肝逆症候相应。", ["芤"]], "7201": ["预后", "原文未及具体脉名，仅言“六脉已起，胃口亦开”，是脉气渐复、胃气来复之象，故断“病已净尽”。脉起与纳开并见，说明邪退正复，预后向愈；后路惟凉滋肺胃，是热病瘥后调养之法，非主病脉象。", []], "7202": ["兼症", "肺气感冒大汗后，头眩足滞痛皆瘥，而脉数已流利，数示余热未清，流利示气机尚畅、非涩滞之象。原文据“脉数已流利”断热未净，故拟再清肺；有汗者不应再汗，兼症已减而脉仍数，说明余邪未尽，当清不宜再汗。", ["数"]], "7203": ["病机", "右脉已滑、有力有神，左寸亦然，滑而有力为气血尚充、胃气有神；惟左关尚涩，左关候肝，涩主血少络滞，故原文断“总由肝血之虚”，当补肝血兼养络。滑涩并见，说明他部脉气已复而肝血独虚，涩脉与肝血虚、络脉不畅相应。", ["滑", "涩"]], "7204": ["平脉", "原文诊脉“甚流利而缓”，缓为脾脉本象，流利而缓即脉贵有神，属和平之脉，非病脉。故不可进热药，只用益阴健骨法调养。此段以缓脉辨胃气有神，说明脉得缓象则脾土安和，与虚寒需温之脉不同。", ["缓"]], "7205": ["病机", "发时纯热、口大渴有汗，总属瘅疟；脉数不滞，数主热，不滞示邪未与湿浊胶结，故断“非伏暑”。原文以脉数不滞排除伏暑，认定瘅疟由暑热在肺，兼有湿热痰，故用白虎汤复入祛湿消痰生津，脉数与纯热大汗渴饮相应。", ["数"]], "7206": ["病机", "白虎汤后大热大汗已止，脉左手已小，右手稍有滞象，惟皆数。小为热退正伤之象，滞示余邪未畅，数则“属邪未净”。原文据数脉断瘅疟暑邪尚在肺，兼素湿邪，故再拟肺入法祛湿，数脉与舌根黄、口苦腻、溲赤等余热症相应。", ["数", "小"]], "7207": ["病机", "因劳复作寒热，舌黄口渴脉数，数主热。原文辨寒热可出肺、少阳胆、肝、募原及营卫，今逢劳则发，责营卫不和；汗出便溏属卫病，干呕清水属肝病。脉数与舌黄口渴并见，说明劳伤后营卫失和、内有郁热，故先调和营卫。", ["数"]], "7208": ["病机", "原文“舌净脉平，惟鼻间尚有红色”，脉平示邪已大退，阴阳趋于和平，然鼻红为余热未清之征，故病机为热病后期阴分受损、虚热上浮，当益其阴以清余热。脉平非无病，乃正虚邪微之象。", ["平"]], "7209": ["病机", "原文“诊脉已缓，舌白燥，小溲赤短”，脉缓为汗后邪解、胃气未和之象，然舌燥溲赤、口味淡而口气存，说明胃火未净、肺分受风化火，脉虽滞而腰酸，总非伏邪，故以清凉肺胃为治。", ["缓"]], "7210": ["病机", "原文“脉小数，口渴少寐，头眩痛瘥，指木腰痛，呼吸腰间痛”，脉小数主阴虚内热，热灼津伤故口渴少寐；筋中病而腰痛、指木，为热伤筋脉、兼夹劳乏，大便四日不解亦津亏肠燥之征。", ["小", "数"]], "7211": ["病机", "原文“诊脉两手皆滞，书以木属湿痰，合脉怕作伏邪”，脉滞主湿痰内阻、气机不畅，故头身觉木、腰背穿痛；冷时作战为疟象属肝分，然脉滞非伏邪之象，故拟肺分法而勿用小柴胡引贼。", ["滞"]], "7212": ["病机", "原文“诊脉尚弦，总由血虚生风”，脉弦为肝风内动之象，肝风上扰故齿痛月余、左右肿替、头额痛；血虚不能濡养筋脉，虚风内生，脉弦劲不柔，故以养血熄风为治。", ["弦"]], "7213": ["病机", "原文“诊脉稍有滑象，是湿热未罢之候”，脉滑主湿热内蕴，虽舌黄已减而根未除、目筋尚红、鼻柱色膏、卧不安口燥，皆湿热余邪未清之征，故祛疾务尽，再用前法清化湿热。", ["滑"]], "7214": ["病机", "原文“诊脉右手弦，左关独起，是必由于热伤肝络”，右脉弦而左关独起，为肝经热盛、络脉受伤之象，故失红、右肋下痛、舌黄、大小溲均热，皆热伤肝络、血不循经之候。", ["弦"]], "7215": ["病机", "原文“诊脉浮弦数，已有三日，尚渴，身上不怕冷而热，舌上无苔微白”，浮弦数主风热在肺、湿痰内蕴，故身热有汗、头痛且眩、两足滞、两手木；无苔邪在肺，有汗属风，头眩足滞属湿痰，拟祛肺分风热湿痰。", ["浮", "弦", "数"]], "7216": ["病机", "原文谓脉「皆起，惟欠长，且有数意，总属血分之虚」。数意示血虚生内热，欠长即脉体短绌，为血不足以充脉。张氏以脉洪大者能载重用地黄，脉小者不能载重药，正说明脉之大小关乎阴血盈亏与受药之力，故本条主旨落在血分虚损之病机，而非单纯主病。", ["数", "长"]], "7217": ["病机", "原文「诊两手脉皆滞，舌苔根黄厚」，滞为气机不畅、湿浊内阻之象。头胀虽瘥未除、胃开气冲、喉痒干呕，皆肝胃不和、阳气不达颠顶所致；据脉滞与苔黄厚，断「恐有湿病之起」，故以越鞠丸加减行气解郁化湿。脉滞在此主湿阻气滞之病机。", ["滞"]], "7218": ["病机", "间日疟后「胃开脉弦数，舌黄」，弦为肝木偏旺、疟邪入肝之象，数示余热未清。故云「仍当温肝」；又夹外风在肺，打嚏咳嗽有痰、喉中觉热，乃风热犯肺，故复入清肺。脉弦数在此既主肝经余邪，又兼肺中外风之病机。", ["弦", "数"]], "7219": ["病机", "右肋间穿痛、痛时作嘈欲食，诊脉弦细，舌中黄。弦主肝、主痛，细为络脉不畅、阴血不足；胁肋为肝络所布，故断「络中肝痛」；舌中黄、作嘈欲食，又夹胃热与痰。脉弦细正合肝络痛而兼胃热痰滞之病机。", ["弦", "细"]], "7220": ["病机", "齿痛月余、大痛三四日，两太阳痛，诊脉数，舌白燥。数脉主热，齿与太阳皆属阳明、肝经所络，热郁于经则痛。原文断「当用肝分法」，是脉数示内热偏盛、肝经郁热上攻之病机，故从肝分论治，非徒清阳明。", ["数"]], "7221": ["病机", "感风出瘄已五日，有汗、舌黄、口渴，脉数。数脉主热，合舌黄口渴，知外邪已化热；原文谓「素属火体，是气有余，血不足」，故脉数亦反映火体气余血少之内因。先祛外邪、当用凉剂，是脉数主热盛之病机，而非虚寒。", ["数"]], "7222": ["病机", "伏邪十日，冷颤虽去、汗虽有，而小溲未长、口中尚腻，脉弦滞。弦主邪郁少阳、气机不舒，滞主湿浊内停；小溲不长、口腻正是湿郁不化之征。原文断「当清其肺湿」，是脉弦滞主伏邪夹湿、肺气不宣之病机。", ["弦", "滞"]], "7223": ["病机", "寒热三四日，头胀咳嗽、小溲赤，脉右寸弦浮数。右寸候肺，浮为邪在表，数为热，弦主风；原文断「上焦暑风，因新感风寒引起」，是浮数示新感外邪化热，弦示风动，右寸独见说明病位在上焦肺卫。", ["弦", "浮", "数"]], "7224": ["病机", "先泻十余日，止后反腹痛且寒热，脉滞大。滞为湿浊壅遏、气机不畅，大为邪势方盛。泻后湿邪未尽，反致腹痛寒热，正是湿热郁滞、不得开廓之象，脉滞大与湿热内蕴、气机壅塞相应。", ["滞", "大"]], "7225": ["病机", "受寒后先冷作颤、热转神昏，今晨始凉，脉弦细，舌白口苦胃不开。弦主少阳枢机不利，细为邪未化热、正气尚弱。原文断为邪尚未化火，怕成疟疾，脉弦细正合寒邪郁于少阳、未从热化之机。", ["弦", "细"]], "7226": ["病机", "下午发热不作冷，汗不透澈，脉数弦，舌黄口不渴，小溲赤。数主热，弦主邪郁少阳。原文谓伏邪之轻者，热郁上中焦而汗出不彻，脉数弦与舌黄、溲赤共示伏邪化热、郁而未透之病机。", ["数", "弦"]], "7227": ["病机", "胃中梗塞，或酸或苦，无物不呕已三月，舌黄厚，脉弦细。弦为肝气偏旺，细为胃阴不足、胃气上逆。原文断为肝阳犯胃，脉弦细正合肝阳亢逆、胃失和降而呕酸苦之候。", ["弦", "细"]], "7228": ["病机", "伤风后脉弦滞去而稍数，舌仍黄，耳响聋，咳嗽与痰尚有。弦滞渐去示风邪外束之势已减，稍数则余热未清。舌黄、耳聋、咳痰与脉数相应，说明风邪渐解而痰热尚恋，故仍当前法续治。", ["弦", "滞", "数"]], "7229": ["病机", "感风肌热已久，今已有汗，舌黄口燥，咳嗽痰如水，喉痒，脉弦数。弦主风邪未解，数主热盛。原文引书谓风温日久表里均热，脉弦数与舌黄口燥、咳痰喉痒共示风温化热、表里俱热之机，故用甘寒。", ["弦", "数"]], "7230": ["病机", "少腹痛，气升作呕，脉两关尺独大，咳嗽多痰，患经四载。关尺独大示下焦冲气上逆、肝胃不和。原文断为奔豚，气从少腹上冲致呕，脉两关尺独大正合冲脉气逆、病根在下焦之候。", ["大"]], "7231": ["病机", "外感去后，带起肝痛作呕，口渴，脉弦数。外感虽去而弦数未平，弦主肝气横逆，数主郁热内扰。肝痛作呕、口渴与脉弦数相应，说明外感引动肝经郁热、肝胃不和之病机。", ["弦", "数"]], "7232": ["主病", "脉沉弦，沉主里主水，弦主痛主肝木乘脾。五更腹痛作溏，乃脾肾阳虚，肝木克土，水湿内停。沉弦之脉反映里虚寒湿、肝脾不和，故用建中汤温中补虚、缓肝理脾，以治腹痛便溏。", ["沉", "弦"]], "7233": ["病机", "右关弦数，弦主肝郁疟邪，数主热。疟母日久，痰瘀互结，郁而化热，故块形日增痛，咳嗽痰少，久则失红。右手已调而右关独弦数，示疟邪未净、肝脾郁热，薛氏法未效，仍须进药消疟母。", ["弦", "数"]], "7234": ["其他", "此段述张聿青学术源流及霍乱论治，脉伏不起、脉沉弦为霍乱寒热辨证之脉。伏主邪闭，沉弦主里寒饮。热多寒少者脉伏，寒多者脉沉弦，示霍乱吐泻致阳气内遏、寒热错杂之病机。", ["伏", "沉", "弦"]], "7235": ["病机", "脉弦而滑，弦主肝风，滑主痰浊。气虚多湿之体，劳顿引动阳气，肝气挟痰上升，蒙蔽清窍，故神情呆顿、迷沉多睡；痰阻经络，则右手足不利、口眼㖞斜。此类中之症，痰浊弥漫心脾之络，恐阳气复上而神昏。", ["弦", "滑"]], "7236": ["兼症", "脉象柔和为起色，但右关沉滑有力，沉主里，滑主痰，右关候脾胃。浊痰弥漫心窍稍开，而火风鼓旋之势尚炽，故手足不遂、口眼㖞斜、舌强言蹇、不饥不纳、嗳噫似呃。沉滑有力示痰火内结脾胃，风火未平。", ["沉", "滑"]], "7237": ["预后", "七诊脉症相安，病势逐日减退，为向愈之兆。然类中之后，气血未复，饮食起居急宜谨慎，若稍有感触而复中，则病深难治。此段强调脉症平和时仍需防复中，属预后调摄之论。", []], "7238": ["病机", "脉弦大而数，弦主肝风，大主火盛，数主热。肝风挟痰中于府络，痰火风内扰，神灵之府被撼，故心中烦懊烙热、迷睡神昧、呃忒频频。弦大数示风火痰热炽盛，若再中心络必神昏不语，极险可虞。", ["弦", "大", "数"]], "7239": ["病机", "脉形弦滑，弦主肝风，滑主痰浊。神迷转清、烦懊较定、痰得咯出为松动之象，然心胸之热犹团聚不化，时带呃忒，眩晕不能转侧。弦滑示火风挟痰上旋未平，犹恐发痉发厥，故再泄木火以清痰热。", ["弦", "滑"]], "7240": ["病机", "脉形弦大，弦主肝风，大主火盛，此肝火风鸱张不熄之象。虽症见转机，但头昏眩晕、转侧辄厥，乃风火挟痰上旋，恐阴分劫烁，舌起糜腐，示病机由实转虚之危。", ["弦", "大"]], "7241": ["预后", "脉弦大渐转细弱，弦大为痰火风之实，细弱为真水欲竭之虚。舌胎白腐、糜点布散，多言妄笑，五志之火上亢，实症转虚，预后堪忧，故勉拟救阴泄热以护神明。", ["弦", "大", "细", "弱"]], "7242": ["病机", "脉细弦转大，细弦为阴分稍复，转大乃火风鸱张之征。食入中脘作痛，是风木干土，木旺克土。脉象由细转大，示阴复而风火未熄，故再育阴化痰兼平肝木。", ["细", "弦", "大"]], "7243": ["病机", "脉弦滑，弦主风木，滑主痰热，此火风挟痰上旋，乘阳明脉络之虚而中络。经降火消痰，脉弦滑渐柔，示痰热渐平，然虚火挟湿上腾，口糜腐，危险未脱。", ["弦", "滑", "柔"]], "7244": ["病机", "脉左弦右滑，左弦为肝风内煽，右滑为脾湿酿痰。体丰气弱，痰阻心脾之络，风阳挟痰乘势内煽，致舌强难言、右手足不利，类中之渐，恐复中变生不测。", ["弦", "滑"]], "7245": ["病机", "脉象虚弦，虚为气血亏损，弦为虚风暗动。年近古稀，舌光无苔，心胸咽喉热辣、环口作麻、四肢不便，皆阴血亏虚、风阳上扰之类中根源，故惟培养气血为保守之计。", ["虚", "弦"]], "7246": ["病机", "脉象虚弦，虚为胃液耗残，弦为肝风内动。呕吐太过，阳明脉络空虚，肝风乘虚中络，致神昏发厥、左肢弛纵、目开手撒遗溺，类中虚多实少，故勉用救阴熄风。", ["虚", "弦"]], "7247": ["病机", "脉象弦滑少力，弦为风动，滑为痰盛，少力为气虚。气虚挟痰化风，中于经络，故偏右不遂、舌强言謇，此正虚痰风阻络之候。", ["弦", "滑"]], "7248": ["病机", "脉濡为气虚湿困，滑主痰浊内蕴。原文谓“气虚而湿痰入络”，濡示正气不足、脾运失健，滑示湿痰流注经络，阻滞气血，故见四肢不遂、言语謇涩。此属类中，本虚标实，痰湿深伏络隧，故“难望近功”。", ["濡", "滑"]], "7249": ["其他", "原文未出脉名，仅言“脉症相安”，指前诊中湿之后，经温通和络泄湿治疗，脉象与症候趋于平稳。络隧未和，湿邪未尽，故守效方出入再进，属治疗过程中的动态观察，非主病脉象。", []], "7250": ["病机", "左关候肝胆，弦主肝风内动；右关候脾胃，滑主痰湿内盛。原文谓“痰湿阻于阳明之络”，弦滑并见，示肝风挟痰湿上扰，阻滞阳明经络，故口眼㖞斜、手指屈伸不利，为类中之先声。", ["弦", "滑"]], "7251": ["兼症", "原文未出脉名，仅言“脉症相安”，而手仍带肿。经谓“湿胜则肿”，说明湿邪未尽，络脉未和。又谓诸病皆风火所为，提示湿肿虽存，风火内动仍是病本，属兼症观察。", []], "7252": ["病机", "左脉弦主肝风，右关滑主痰浊。原文谓“惊痰入络，机窍被阻”，弦滑并见，示惊痰挟肝风上阻清窍，故语言謇涩，为中厥之先声。脉象反映痰风内扰、机窍闭塞之病机。", ["弦", "滑"]], "7253": ["病机", "脉细主精血亏虚，弦主肝风内动，尺涩为肾精不足、血行不畅。原文谓“高年精血亏损，肝风鸱张”，细弦尺涩正合精血亏于下、肝风亢于上之机，故头晕、心中震痉，为类中之渐。", ["细", "弦", "涩"]], "7254": ["病机", "脉弦滑主痰湿内盛、肝风暗动。原文谓“湿痰过盛，营卫之气为之阻蔽”，弦滑示痰湿壅阻络隧，营卫不通，故左臂作麻，有痱中之虞。脉象反映痰湿阻络、气血不达之病机。", ["弦", "滑"]], "7255": ["病机", "脉弦滑主痰湿内蕴、胆木不降。原文谓“胃有湿痰，胆木不降”，弦为肝胆气逆，滑为痰湿内盛，痰湿中阻则清阳不升，故眩晕耳鸣、四肢麻木，有类中之虞。脉象示痰湿挟胆逆上扰之机。", ["弦", "滑"]], "7256": ["病机", "脉形弦滑，弦主气机郁滞，滑主痰湿内蕴。左臂作麻，乃血中无气推动，血行不畅，痰湿阻遏经络，荣卫不宣所致。脉症合参，病机为痰湿阻络、气血不宣，故仿石顽法以化痰通络。", ["弦", "滑"]], "7257": ["兼症", "三诊后脉症相安，然四肢酸软、筋惕少寐，乃痰湿阻络，甲木之气不降。脉象虽未明言，但症见筋惕少寐，属痰湿未净、肝胆气逆，故前法出入再进，以化痰降逆为要。", []], "7258": ["病机", "右脉濡滑，左关微弦。濡主中气不足，滑主湿土生痰，弦主气机郁滞。面色浮黄、四肢酸软、心悸少寐，皆中气不足、痰湿郁阻络隧之象，为痱中之根。病机重在脾虚痰阻。", ["濡", "滑", "弦"]], "7259": ["病机", "脉数浮弦，数主热，浮弦主风邪化热。风温八日，身热咳嗽、神昏迷昧、气升痰嘶、痰黄渴饮，皆风邪化热、灼烁肺胃，津液化为痰热，肺叶煽动，有喘厥之虞。病机为风热痰火壅肺。", ["数", "浮", "弦"]], "7260": ["病机", "脉数弦滑，数主热，弦主气逆，滑主痰盛。神迷较清而痰仍黄厚、痰声如潮，乃肺胃热灼，津液尽化为痰，痰随气升，气随痰逆。病机仍属痰热壅肺、气逆不降，故参上病下取法。", ["数", "弦", "滑"]], "7261": ["病机", "脉象滑数而软，滑数主痰热，软主阴伤。上升之气大定，讝语烦懊减，但舌苔浮糙、上腭糜腐，乃痰热化火灼阴，虚象渐露。病机为痰热未清而阴液已伤，故再化痰热兼甘凉养阴。", ["滑", "数", "软"]], "7262": ["病机", "脉形软滑，软主阴分亏损，滑主浊痰未净。痰喘渐平、热减而白腐渐多、不甚作渴，乃阴分亏损，浊随气火上浮，虚多实少。病机为阴伤浊泛，故急和其阴，参清化气热。", ["软", "滑"]], "7263": ["预后", "脉形软滑，软主阴伤，滑主浊蒸。痰喘全平而腐糜忽少忽多，舌呆紫苔淡黄干毛却不燥渴，胸次如哽如阻，乃阴分伤损，浊蒸不化。病机深重，治多棘手，勉以清化并行，预后难料。", ["软", "滑"]], "7264": ["病机", "脉象郁数，数主热，郁示邪湿相合、三焦气机壅滞。饮食内伤，时邪外感，邪湿交蒸，故发热甚炽、无汗、懊烦、频渴不多饮。脉数应热势，郁应湿阻，舌红苔黄罩灰亦为湿热内蕴之征。此脉说明邪湿相合，有化火化燥之势。", ["数"]], "7265": ["病机", "原文言风脉必浮，今脉不以浮应，非风象。风在表则浮，今风入肠胃，病既入里，则脉不以浮应。此段辨脉以明邪之出入：便泄减、咳增多、热渐减，苔灰大化，为转轻之象，然无汗邪无出路，热仍不解，耳窍闭塞，乃风邪上阻清窍、下趋大肠，脉不浮正示邪已入里。", ["浮"]], "7266": ["病机", "脉象糊滑，重按少力，滑主痰，糊示神机被蒙，少力为正气虚微不能托送。便泄黏腻色白带赤，热轻而迷沉欲寐、谵语，苔黄根灰润，乃中气不足，风、湿、热炼液成痰，弥漫神机，里虚内陷之象，恐神昏发痉。", ["滑"]], "7267": ["病机", "脉象稍起而软数微弦，数主热，弦主风，软示正气不足。热势发扬于外，迷蒙较退，懊烦、谵语、口渴欲饮，舌红后半灰霉，乃风燥上阻清窍，风与湿合，熏蒸神机。脉稍起为邪有外达之机，软数微弦说明风热未清而正虚，恐邪复内窜。", ["数", "弦", "软"]], "7268": ["病机", "脉数微弦，数主热，弦主风。风为阳邪，不从外越，从中化热，灼肺胃则咳嗽不爽，扰神明则言语妄乱，劫津液则神机不运。目赤颧红、口渴欲饮、舌红苔深黄根霉黑，皆风邪化火劫烁阴津之象。脉数弦正应风火鸱张，恐阴干神昏发痉。", ["数", "弦"]], "7269": ["病机", "脉象沉细软弱，较昨稍起。沉细软弱主正气虚衰、阴津亏耗。神志较清，懊烦略定，迷睡略退，咳嗽增多痰黏，舌红稍淡灰霉略化，为阴津渐回。喉有痰声，乃津液为热邪所炼成痰，即有形之火。脉沉细软弱说明正虚未复，故拟凉肝泄热兼保阴液。", ["沉", "细", "软", "弱"]], "7270": ["病机", "原文未识脉名，仅言脉渐起。脉渐起示正气渐复、邪有外达之机。内陷之邪还于肺胃，故神志渐清、热势递减、口渴稍定、苔灰霉较化。惟眠多醒少，乃神机欠运、胸中热弥漫。此段以脉渐起为邪退正复之兆，仍须泄热和阴、宣肺引邪外出。", []], "7271": ["病机", "原文未识脉名，仅言右脉稍起。右脉稍起为热化津回之象，口渴渐定、热势渐轻、舌红渐淡、苔黄转白、灰霉渐退皆应之。然眠多醒少、耳聋不爽、大便不解，乃余热与湿弥漫胸中如雾氤氲。病初风温夹湿，邪化热劫津，今津回热化而燥仍为湿，故脉虽起而症未全清。", []], "7272": ["病机", "脉数右大，数主热盛，右大主肺胃热壅。原文痰中带红、左颊红赤、舌心黄带霉黑、大便不行，皆肺胃热胜、痰热内蕴之象。痰既得出而咳稍甚，热未清而津已伤，故仍守清胃养津，脉象示热势未衰、病位在肺胃气分。", ["数", "大"]], "7273": ["病机", "脉象右大，右主肺胃，大主热盛邪实。原文胸中弥漫之热略得扩清，而大便欲解不出，迷睡稍退，是热邪仍壅于肺胃、津液受灼而肠燥。右大之脉正应肺胃热结、津亏便难之机，故参增液以望便行，脉示邪热未净而阴液待复。", ["大"]], "7274": ["病机", "脉数重按微弦，数主热，弦主木火升动。原文大便畅行后津液为热所耗，木火升动致懊烦口渴、左颊红赤、耳鸣窍闭、咳嗽咽痒，皆风温化火劫津、肝胃之火上炎之候。舌未焦燥、神未昏糊，示津伤未至危重，故泄热存阴之法不可更动。", ["数", "弦"]], "7275": ["病机", "脉数主热，舌质淡红、苔淡黄灰霉未尽，示肺胃余热未清。原文多眠渐退、两次得汗、咳嗽渐轻痰少，是内陷之邪还归于表，为正色。热未解而耳聋不聪，乃余热未尽、清窍不利。液复化汗，故不表汗而汗自出，宜乘势疏风泄热使邪有出路。", ["数"]], "7276": ["病机", "脉数右大，数主热，右大主肺胃热盛。原文内陷之邪还于肺胃，咳嗽身热、耳聋、音声雌腻，舌淡红、淡黄灰霉苔逐步化轻，是邪由深出浅、肺胃余热尚存之象。脉数右大正应肺胃热壅，故宜辛凉散风、微苦泄热，因势利导以清余邪。", ["数", "大"]], "7277": ["预后", "原文未识脉名，仅言脉静苔化。脉静者，热退邪衰、脉不复数大躁动之谓；苔化则痰热渐消。耳窍闭塞已开、身热亦退，内陷之邪从汗而出，故断大局已定。脉静苔化与症候相应，示邪去正安，故宜和中醒胃以善其后，属预后佳象。", []], "7278": ["预后", "原文未识脉名，仅言脉静苔化。脉静示邪热已退、脉象平和，苔化示胃浊渐清，故胃开思食。久热之下阴津不能遽复，是热病后期津亏未复之常。脉静与胃开思食相应，说明邪去而正待复，故宜和阴益肾以滋化源，属病后调摄、预后向安之论。", []], "7279": ["病机", "脉数右大，数主热盛，右大主肺胃邪壅。原文咳嗽不爽、发热汗出不解、气从上逆、便溏、苔厚心黄，症方七日，风温袭于肺胃，热势炽盛。右大之脉正应肺胃热壅、气逆不降，便溏为热迫大肠，苔厚心黄为湿热内蕴，故断为势甚炽。", ["数", "大"]], "7280": ["病机", "脉滑数，滑主痰湿食积，数主热，合之示有形之积阻于中焦，兼湿热内蕴。原文“腹膨脘痞欲呕，频转矢气”为积滞内阻、气机不畅之症；“日晡似疟”乃湿热郁蒸。脉症合参，病机为有形积滞阻而不化，湿热蕴结，故拟导滞兼清湿热。", ["滑", "数"]], "7281": ["病机", "脉数主热，右部沉郁为湿阻气机，左部弦大为热盛阴伤。原文“无形之邪，有形之湿，熏蒸不化”致“清津不能上供，阴液由此渐亏”，故见“烦渴而不欲饮”“舌红苔黄，根带灰霉”。脉症示湿热熏蒸、阴液渐亏，恐化燥而神机不运，渐成昏蔽。", ["数", "沉", "弦", "大"]], "7282": ["病机", "脉滑数，滑主实滞，数主热，示阳明腑实兼湿热内结。原文“大便不行，大腹满痛，频转矢气”正合阳明病频转矢气之条，为燥屎内阻、气机壅滞之征。脉症相应，故以丸药缓下，通腑泄热。", ["滑", "数"]], "7283": ["病机", "脉数左弦，数主热，弦主气滞，示阴伤热恋、宿滞不达。原文“大腹满痛，频转矢气，大便不行”为宿滞内阻；“舌尖红绛”为阴伤有热。热势虽减而起伏，脉症合参，病机为阴液耗伤、热邪留恋、宿滞未化，故再泄热利湿，参以磨滞。", ["数", "弦"]], "7284": ["病机", "脉数右大，数主热，右大主肺胃热盛，示风温袭于肺胃，不能外达。原文“汗未畅达，热仍不解，头胀耳鸣”为风热上扰、邪郁肺胃之症。三日正炽，脉症相应，病机为风温客于肺胃，表气不宣，热势鸱张。", ["数", "大"]], "7285": ["预后", "脉略缓，缓为胃气渐和之象，示邪从汗解、热势大减。原文“得汗甚畅”“胀痛渐松”“苔黄较化”皆邪退之征。然“炉烟虽熄，余烬未消，身热尚未尽退”，脉缓而余热未清，故还宜疏泄余邪，为病势向愈之预后。", ["缓"]], "7286": ["病机", "脉左大重按无力，大为热盛，重按无力为阴津亏虚，示邪热内灼、阴津损伤。原文“舌光无苔，干燥无津”为津伤之象；“发热便泄”“懊烦不寐”“耳窍失听”为热移大肠、上扰清窍。脉症合参，病机为邪热不从外达，灼烁阴津，恐液劫神昏。", ["大"]], "7287": ["病机", "脉数左大，数主热，左大主热盛于内，示风温夹湿化热，由大肠还于肺胃，气燥津伤。原文“舌燥无津，既干且腻”“右目红赤作痛”为燥热伤津、风热上攻之症；便泄已止而神烦少寐，热未全清。脉症相应，故拟流湿润燥，开泄风热。", ["数", "大"]], "7288": ["病机", "脉象细数，细为阴津亏耗，数为邪热内盛。原文述病八日，发热便泄后表热入里，里热神烦、频渴欲饮、舌苔焦黑无津，皆邪热内陷、劫烁阴津之象。气火上冲致呃逆频频，吸气不得入，脉细数正合阴伤热炽之机，故断将有神昏发痉之变。", ["细", "数"]], "7289": ["病机", "脉数大重按带弦，数为热盛，大为气分热炽，弦主风火内旋。原文谓风化为火，火风内旋，虽经泄热和阴，沸腾之风火虽熄，而气分之热未遽化，故脉仍数大带弦。风痰为热所灼，色变黄稠，气燥则清窍不利，咽痛鼻红、耳窍闭塞，皆肺胃风热渊薮之征。", ["数", "大", "弦"]], "7290": ["病机", "脉数而弦，数为热，弦为肝火。原文述咳嗽头胀发热、寤难成寐、知饥欲食，乃风温袭于外，肝火炽于内。外风引动内火，故脉见数弦。风温在表则咳嗽头胀发热，肝火内炽则寤难成寐，知饥欲食为胃热。脉数弦正合外风内火相搏之病机。", ["数", "弦"]], "7291": ["病机", "脉数糊滑，数为热，滑为湿痰。原文述发热烦渴、胸闷气逆、频咳痰多、神烦少寐，此风温挟湿，郁蒸肺胃。湿与热合，蒸酿痰浊，故脉数而糊滑。症逾两候，邪势未解，恐致昏喘，脉象示湿热痰浊壅遏肺胃，有内陷生变之虞。", ["数", "滑"]], "7292": ["病机", "二诊气逆稍定，热亦渐减，而脉仍滑数。滑主湿痰，数主热，脉仍滑数，说明肺胃之湿未楚，余热未清。原文直言“还是肺胃之湿未楚也”，故虽症减而脉象未平，仍当再为降化，以清化肺胃湿浊为治。", ["滑", "数"]], "7293": ["病机", "脉数而滑，数为热，滑为痰湿。原文述发热咳嗽多痰、喉间霍霍有声、胸闷神烦，此温邪挟湿，蒸于肺胃。湿热蒸酿，痰浊上壅，故脉见数滑。七日正炽，邪势方盛，脉象与症相符，主肺胃湿热痰浊壅盛之病机。", ["数", "滑"]], "7294": ["病机", "脉数滑大，数为热，滑为湿痰，大为邪势炽张。原文述口碎作痛、热起势甚炽张、胸闷懊烦、鼻衄便泄、咽中作痛，舌红苔白，此风邪袭上，时令之邪与湿相合，一阴一阳之火俱结于上。病属风温，方在五日，邪势炽甚，脉数滑大正合其机。", ["数", "滑", "大"]], "7295": ["病机", "二诊汗出邪从外泄，而肺胃之热蕴结，痧疹并发不少衰，痛不少减。脉数滑大，舌红边绛，喉关白腐满布，喉肿关小。原文谓炉烟甫熄，余烬复燃，肺胃之热冲斥于中，脉数滑大示热毒痰浊壅盛，恐火烁肺金而致气喘，属喉疳重症。", ["数", "滑", "大"]], "7296": ["病机", "原文谓\"脉洪大略收火风之灼铄肺胃者，已退三舍\"，洪大为热盛之象，前因火风灼铄肺胃而致喉肿、涎涌，今脉势略收，说明邪热渐退而病机向缓，故当乘胜再进泄热，属热势衰减之机。", ["洪", "大"]], "7297": ["病机", "脉数至六至以外，为阳邪化火之征。原文言\"风为阳邪，阳邪易于化火\"，痰浊尽从阳化，华盖受炎，清肃不行，右降失权，故痰鸣气喘、讝如梦语。数脉主热盛，预示耗气伤阴之变，病机在痰火壅肺。", ["数"]], "7298": ["病机", "右寸脉独大，右寸候肺，独大为邪热灼肺之象。原文谓\"邪热灼肺，手太阴清肃无权\"，致热蒸炼液成痰，痰火内炽，故咳恋痰稠黄厚、火升少寐。鼻准清冷乃气机闭郁，非元阳衰脱，病机重在痰热壅肺。", ["大"]], "7299": ["病机", "脉数右部浮大，数主热，浮大主邪在肌表。原文谓\"热之尚在肌表，显然可见\"，风邪在表，阳气屈曲不伸，故壮热无汗、头疼烦疼。湿痰素盛内壅，表邪难达，病机为表邪夹湿痰闭郁，当疏解兼化痰。", ["数", "浮", "大"]], "7300": ["病机", "脉仍带数，示热退未楚；脉数微滑，滑主湿痰。原文谓\"邪势渐去，湿热未清\"，偏左瘕积阻滞，气道失宣，故气短腋痛。数滑并见，说明余热与湿热痰浊留恋，病机为邪去而湿热未净、兼有积滞。", ["数", "滑"]], "7301": ["病机", "脉左大、右部软滑，左大主肝气偏亢，软滑主痰湿。原文谓恣食甜腻\"酿湿生痰，肺降痹阻\"，故热退不清、痰鸣气急、不能安眠。气弱生寒、阳不旋转，病机为痰湿痹阻肺降，兼阳气不运，恐喘甚汗脱。", ["大", "软", "滑"]], "7302": ["病机", "脉数而滑，数主热，滑主痰。原文谓\"天燥太过，肺胃风热内烁，更兼肝火凌金\"，故咳痰带血、沉迷多睡。阴虚火炽，热蕴胸中如烟雾弥漫，病机为风热痰火内烁肺胃、肝火凌金，恐昏痉等变。", ["数", "滑"]], "7303": ["病机", "脉数小软，数主热，小软示营气日亏而邪恋。原文谓\"肺热脾湿相蒸，痰黄而稠\"，热恋不解、咳不止、形色瘦削，说明邪湿留恋而元气渐伤。病机为湿热未化、营气亏耗，故治法惟泄化邪湿以保全元气。", ["数", "小", "软"]], "7304": ["病机", "脉数弦滑，数主热盛，弦主肝郁气逆，滑主痰浊内壅。风温袭肺，化热内灼，故咳剧痰稠、身热神烦；胁痛不寐乃热灼肝络、痰热扰心。适值经来，血室空虚，热邪易陷，故有暴喘之虞，脉象正示热盛痰壅、内灼之势。", ["数", "弦", "滑"]], "7305": ["病机", "脉数带滑，数主邪热未清，滑主痰湿内蕴。咳减而仍凛寒身热、痰黄厚，苔白心黄，是邪热郁于肺胃、痰热交蒸之象。夹经未净，血室未闭，热邪易乘虚内陷，故脉数滑不去，还恐神昏气喘之变，示病机仍在进展。", ["数", "滑"]], "7306": ["病机", "脉象沉弦，沉主病在里，弦主气机郁滞、痛证。身热已退而脐上作痛、大便不行，是寒滞内阻、腑气不通，气机壅塞于中焦，故脉沉而弦。沉弦相应于内实寒滞，宜小承气汤顺其气，脉象正合里实可下之机。", ["沉", "弦"]], "7307": ["病机", "脉象数滑，数主热，滑主湿痰。风热之邪与湿相合，蒸腾于肺胃之间，故身热不解、汗出不透、胸闷神烦少寐；舌红苔白质腻，正湿遏热伏之征。数滑并见，示湿热痰浊交蒸，症属风湿，恐其化热内传，脉象已露端倪。", ["数", "滑"]], "7308": ["病机", "脉数而滑，数主热盛，滑主痰壅。风温挟痰，与热相合，熏蒸肺胃，故热不外扬、咳嗽痰稠、口渴舌干少津、小溲作痛。痰气遏阻上中两焦，清津不升，脉数滑正示痰热内盛、化热伤阴之势，恐转候痰热内闭而致神昏发痉。", ["数", "滑"]], "7309": ["预后", "脉亦稍缓，缓为胃气渐和、邪热渐退之象。前诊清化痰热后，舌苔燥转润、霉黑亦化、溲痛退、气逆平，诸症向愈，脉由数滑转缓，示痰热渐化、气机渐畅。然内热未楚，脉缓而未尽和，故还宜清化，不可遽补，脉象反映邪退而未净之预后。", ["缓"]], "7310": ["病机", "右脉滑大，滑主痰，大主热盛，右脉候肺胃。咳嗽气逆虽定，而肺胃之间痰热未化，气不流布，津液不行，故口燥舌干欲饮。滑大之脉示虚火挟痰熏蒸胃口，恐起口糜，故需引津上升、导热下行，脉象正指痰热未清、虚火上炎之机。", ["滑", "大"]], "7311": ["病机", "脉形细数，细主阴伤、正虚，数主邪热内盛。冬温九日，发热懊烦无汗，赤斑不透，神识迷糊，指节引动，是邪郁不达、挟温蒸腾，神机为之弥漫。细数示热盛伤阴、邪陷心包之势，苔白心黄质腻，故有内窜昏痉之虞，脉象正合邪郁化热、内陷之机。", ["细", "数"]], "7312": ["病机", "脉数弦大，数主热盛，弦主木旺，大主邪实。冬温化热，炼液为痰，郁阻肺胃，甲木不降，乙木独升，故脉弦；热盛于内，故脉数大。症见烦热火升颧红、恶心欲吐、胸次窒闷、惊惕耳聋、四肢震动，皆风火内旋、痰热郁阻之象，恐致神昏痉厥。", ["数", "弦", "大"]], "7313": ["病机", "脉数竟在六至以外，为热盛之征；气口带浮，按之少情，示风火壅肺，热循肺系内犯膻中。风化为火，尽壅于肺，火郁于内发现于外，故两颧红赤、唇口朱红、谵语。脉数主热，浮主邪在表分，然按之少情，说明热郁于内，非单纯表证。", ["数", "浮"]], "7314": ["病机", "脉数滑带弦，数主邪热，滑主痰湿，弦主木火。疹㾦后营液暗虚，方寸愁虑，木火升动，邪热转炽，炼液成痰，神机不运。症见烦热复盛、耳鸣耳闭、喉有痰声、俨如梦语、手指引动、少腹气坠，皆痰火交炽、肝风内动之候，有神昏发痉之虞。", ["数", "滑", "弦"]], "7315": ["病机", "脉弦稍柔，较前之弦劲为缓，示肝胆之火与邪热交炽之势稍减。透热凉肝、化痰宣窍后，烦懊大减，寐略安，四肢引动较定，少腹作胀亦松，红疹化淡，舌红黄苔化薄，皆邪热渐退之征。然痰火相煽，神昏发痉仍岌岌可虞，故脉虽稍柔，病机未全离险。", ["弦", "柔"]], "7316": ["预后", "脉见歇止，为热炽于内、痰湿抑郁、热不得泄、转从内窜之象。温邪七日，热炽神迷，肢节引动，舌黑质红，颧颊红赤，喉间霍霍痰鸣，气粗短促，皆痰热壅盛、内闭心包之危候。歇止脉示正气不续，痰涌昏喘之虞迫在眉睫，预后堪忧。", []], "7317": ["病机", "脉数滑大，左部小濡，右部搏指。数主热，滑主痰，大主邪实，右部搏指示肺胃热炽；左部小濡为津亏之象。蕴结之气分渐开，而痰鸣气逆，肺胃邪热尚炽，火与痰激，故霍然有声；热灼津亏，故频渴欲饮。痰即有形之火，火即无形之痰，邪势不泄，液即为痰。", ["数", "滑", "大", "濡"]], "7318": ["病机", "脉数糊滑，数主邪热，滑主湿痰。天气乍冷，阳气阻郁，邪湿羁留，未能遽解，上焦之气不展，故胸中窒闷不舒、口腻苔白舌红。面色浮赤较淡，赤色瘀滞不匀，为邪湿熏蒸、热势尚在鸱张之象。脉数糊滑正合湿遏热伏、痰湿交蒸之病机。", ["数", "滑"]], "7319": ["病机", "脉数舌红，苔白淡黄，数主热，舌红示热入营分。叠得自汗，胸中窒闷稍开，尚未安寐，口燥而腻，为胃中浊与湿交蒸，不能遽化。症经旬日，邪湿羁留，热甚不退，脉数示邪热未衰，惟宜泄之化之，俾免湿浊内蒙心包为幸。", ["数"]], "7320": ["病机", "脉数主热，糊滑主湿痰内蕴。原文谓热势下午为甚、口渴黏腻、舌边绛赤中心白腻，正是湿热相持、邪欲深陷之象。脉数而带糊滑，说明热为湿裹，清之不解、汗之不透，故曰邪势由浅而深，当以泄化为主，使邪湿分消。", ["数", "滑"]], "7321": ["病机", "脉沉细涩，右略大而混数不扬，一派正不胜邪之象。花甲命火衰、湿痰盛，又伤于甘寒，脾阳受遏，湿痰弥漫三焦，故热势不扬、便注下迫、淋淋汗出。沉细涩示阳气被湿所困，混数不扬示伏邪欲动而力不能透，故治以分理三焦、化湿痰为要。", ["沉", "细", "涩", "数"]], "7322": ["病机", "脉糊滑并不甚数，苔白腻不焦黑，身热不炽甚，说明非火热扰乱神明，而是湿盛之极、中阳不运，湿蕴成痰、痰蒙清窍，故见神昏、手暖足厥。糊滑为痰湿之征，数不甚则热不亢，正与火热致昏相鉴别，故拟芳香通神、辛开苦降。", ["滑"]], "7323": ["病机", "脉数糊滑，苔白心黄近根厚掯，赤疹不透、胸窒咳不爽、谵语频渴不欲饮，皆无形之邪与有形之湿相持不化之象。数主热，糊滑主湿痰，湿郁则表气不通，故疏之汗之而疹汗不畅；湿热交蒸，神机弥漫，深恐湿蒸为痰内蒙昏痉。", ["数", "滑"]], "7324": ["病机", "神识转清、谵语指搐已定，是郁蒸稍解；但气冲咳逆、脉仍数糊滑，说明邪湿之势尚在极甚之时，退机不足济事。数滑示湿热痰浊仍盛，肺胃被蒸气难下降，故气冲欲咳未减，前法再参疏肺下气，正合脉症。", ["数", "滑"]], "7325": ["病机", "原文未识脉名，仅言脉仍不扬。胸闷懊烦、气冲咳逆虽次第减轻，舌苔大化，但脉不扬说明肺胃之间尚是熏蒸之地，表不得越、邪无出路。脉不扬即邪湿郁遏、气机不能外达之征，故虽症减而难恃为稳当，仍须望其透泄外越。", []], "7326": ["病机", "咳嗽气逆、痰爽、谵语热烦渐减，而小溲清而不爽、大便不行、频转矢气，脉数糊滑、苔化而中独厚，说明湿痰仍阻于内，邪难泄越。数滑为湿热痰浊未清之象，中苔独厚尤证里湿郁结，故再导其滞，使邪从下泄。", ["数", "滑"]], "7327": ["病机", "原文未识脉名，仅言脉象较爽。大便畅行、燠烦大定、热轻渴减，是邪湿熏蒸渐松；但赤疹寥寥、汗不外达、舌根苔白尚掯，说明邪湿虽减而未能透泄。脉较爽示郁遏稍开，然外越之路未畅，故须望其外越方为稳妥。", []], "7328": ["病机", "脉数滑苔白，数主热，滑主湿痰，湿性黏腻不克遽行泄化，邪湿互相犄角，里气不宣表气难达，故见咳嗽气逆小溲不爽，汗㾦不得发越，说明湿温邪势虽松而黏滞难解，尚难稳当。", ["数", "滑"]], "7329": ["病机", "脉糊数苔白腻，糊为湿浊蒙蔽，数主热，滑主痰湿，湿温胸闷，神沉迷，讝语风动，邪火内窜心胞，湿浊蒙蔽清窍，故脉糊数而苔白腻，说明湿浊内闭，有痉厥内风之险。", ["数", "滑"]], "7330": ["预后", "脉较缓和，舌红转淡，边尖转润，热势大减，烦懊亦定，神识爽慧，邪退三舍，湿痰有欲化不化之意，气机遏伏，津液犹难流布，脉缓和为邪退正复之象，预后向安，治当兼顾经行。", ["缓", "和"]], "7331": ["病机", "脉数糊滑，数主热，滑主湿痰，湿被热蒸，胸中弥漫，神情不如昨日爽慧，清空之地悉皆秽浊所占，说明湿浊痰热蒙蔽清阳，气机不利，故脉见数糊滑，治当泄化之中参以芳化。", ["数", "滑"]], "7332": ["病机", "脉象沉细不爽，沉主里，细主湿，湿蕴肺胃，胃气不降，饮汤噎塞恶心，湿胜则泄，大便稀水，湿郁之极阴阳不通，振寒而战，汗泄白疹，耳窍不聪，鼻起烟霉，神情呆钝错语，皆湿浊熏蒸蒙蔽之机。", ["沉", "细"]], "7333": ["病机", "脉象较爽，苔亦略化，中心黄掯，脐下作痛拒按，频转矢气，口渴欲饮，午后烦热，湿积交蒸不能泄化，虽神情灵爽耳窍略聪便泄亦减，然蕴蓄之热勃发，还恐昏燥等变，说明湿积未净，气机渐通而郁热未清。", []], "7334": ["病机", "脉细沉数，细主津亏，沉主里，数主热，以燥治燥津液果回，郁蒸渐解气机渐得施化，腹胀已松少腹痛退，舌心干毛边道已润，余滞积湿犹未尽达，元气支离未便峻攻，说明湿郁渐解而津伤未复，余滞未净。", ["细", "沉", "数"]], "7335": ["病机", "脉数糊滑，数主热，滑主痰湿，神识已清热亦大减，内闭之热已开，然频频呃忒胸脘不舒，舌苔炱黑，痰湿滞交阻不化，虽略转机尚不足恃，说明痰湿滞交阻，气机未畅，余邪未清。", ["数", "滑"]], "7336": ["病机", "原文述外感风寒，卫阳被郁，先微寒后壮热，汗出邪泄则脉静身凉，说明邪从表解、阴阳洽和。但热气蒸动里湿，湿蕴未清，故胃纳不复、舌苔未化，治宜理湿和中。头痛昏眩、腹满心悸系平素肝阳偏亢、血虚不能养肝所致，当缓议。", []], "7337": ["病机", "脉糊数不扬，糊为湿浊蒙蔽、脉道不清，数为邪热内蒸。呕吐虽止而气湿不化，烦热不退、耳聋不聪、时带讝语，皆湿邪弥漫、清窍被阻之象。脉象与症相符，主湿浊内蕴、蒙蔽清阳，非单纯表证。", ["数", "糊"]], "7338": ["病机", "脉形滑数，滑主湿痰壅盛，数主邪热内炽。湿痰素盛复感时邪，邪湿相持，表气不通，又误食面包壅实胃口，湿痰弥漫，清津被抑，故神识迷糊、舌干无津、苔黑淡白、斑点不透、大便不行。邪湿化燥，弥漫神机，有内窜昏厥之虞。", ["滑", "数"]], "7339": ["病机", "脉象糊滑，糊为浊邪闭郁、脉气不宣，滑为痰湿内盛。开通蕴遏后舌干转润、迷糊稍清、斑点略透，但大便不行、迷蒙如睡、苔灰滞垢腻，说明胃中浊邪闭郁尚盛。胃脉通心，浊邪上蒙心包，还恐昏痉，故以苦辛泄化、劫痰为治。", ["滑", "糊"]], "7340": ["病机", "脉弦滑而数，弦主郁遏，滑主痰湿，数主化火。痰湿积蕴遏久渐化为火，火劫阴津，故舌苔焦黑、舌质深红，神识迷蒙而时揭衣被、颇有懊烦。胃脉通心，深恐热入胞络，症极郑重，故议急下存阴以泄热救津。", ["弦", "滑", "数"]], "7341": ["病机", "下后大便畅行、神情清爽，但日晡后复渐迷蒙，脉形转细。细为阴津被劫、脉道不充。舌干质红苔黑、齿垢唇焦、斑点未畅，系邪浊化火，阳明热炽，劫烁阴津。脉细与热炽并见，示正伤邪盛，仍恐热从内窜而神昏痉厥，故拟泻南补北、泄热透斑。", ["细"]], "7342": ["病机", "原文未识脉名，述泻南补北后斑点渐畅、神识较清、脉亦稍起、舌津稍回，但稍稍饮汤舌质即腻。说明清津虽回而痰浊昏蒙，气不能化，津不上升。脉稍起为津液渐复之兆，然痰浊未化，故仍以流化气分、通津化痰宣窍为治。", []], "7343": ["病机", "脉象弦数，弦主郁热内郁，数主火盛。神识较清而烦热复盛、欲揭衣被、不时讝语，舌苔黑质红少津，斑点未畅已化淡，系邪热内郁与浊交蒸，化火劫津，火必为烦。脉弦数示热势未衰，还恐内窜，故以透热救阴、参化痰为治。", ["弦", "数"]], "7344": ["病机", "脉沉实，沉主里，实主邪盛，为邪热挟积聚于阳明之象。原文谓“邪热挟积，复聚阳明，劫烁津液”，故大便未行、小溲作痛、气粗颧红、懊烦不宁，舌干苔黑有断纹，皆燥火劫津之征。脉沉实正应阳明腑实，热积内结，有昏厥之虞，故拟调胃承气以抽釜薪。", ["沉", "实"]], "7345": ["病机", "脉沉重按有力，为积热仍聚阳明之候。原文谓“积热仍聚阳明，不能曲折而下”，故大便未行、腹满拒按作痛、频转矢气；舌干苔黑，乃燥火劫液烁津。肠胃为积所阻，阳土之气尽化燥火，热气上冲，故为烦燥迷蒙。脉沉有力，说明里实未去，前法再展一筹。", ["沉"]], "7346": ["病机", "脉数糊软，数主热，软主湿，糊为湿浊黏滞之象。原文谓“湿温逗留日久，湿蒸阳明，微寒里热”，邪湿日恋，原气日伤，故脉见数而糊软。苔白亦湿郁之征。此脉说明湿温久羁，正气渐伤，将延入损途，非单纯实热可比。", ["数", "软"]], "7347": ["预后", "脉仍带数，为余烬尚恋之征。原文谓“肌表之风，太阴之湿，因之外解”，表气已通，汗出㾦透，然脉数未除，说明内热未尽。虽得转机，犹不足恃，故以“余烬尚恋”喻之。脉数在此提示邪热未清，预后尚需观察，不可遽以为安。", ["数"]], "7348": ["病机", "左脉弦大，右脉濡滑，俱重按少力。弦大为肝胃阴伤、风动之象，濡滑为湿邪未化之征。原文谓“久热之下，肝胃阴伤，胃失通降，所有湿邪，不能旋运”，故热恋不解、大便经月不行、酸涎上涌、胸脘不舒。脉重按少力，说明虚多实少，恐虚中生变。", ["弦", "大", "濡", "滑"]], "7349": ["病机", "左脉弦大稍收，为肝胃阴伤未复之象。原文谓“肝胃阴伤，肺津并损，致虚火挟膀胱湿热，熏蒸胃口”，故苔白花糙退而复起，糜腐情形，不饥不纳，小溲结滞不爽，大便不行。脉弦大虽稍收，而虚火湿热仍熏蒸，说明阴伤未复，浊蒸胃口，病深入重地。", ["弦", "大"]], "7350": ["预后", "脉亦较缓，为热邪减轻之征。原文谓“糜腐稍化，热邪减轻，小溲略爽”，脉缓说明邪势渐退。然仍不饥，稍进糜饮仍觉气冲，乃气阴并亏，浊蒸胃口未化。脉缓在此提示病情有转机，但气阴难遽复，浊蒸难遽化，惟有循理按法以觇其后。", ["缓"]], "7351": ["病机", "右脉糊滑，糊为湿浊黏滞，滑为痰涎内蕴。原文谓“胃中之痰湿郁结不化”，故中州郁郁不舒，时有痰涎随气上冲，饮喜暖热。阴液虽虚，而痰湿郁结，遂令清津难升，气火无从下降。脉糊滑正应痰湿郁结，非辛不开，非苦不降，故拟泻心法。", ["滑", "糊"]], "7352": ["病机", "左脉弦细急促，弦主木火，细促为阴亏火旺；右脉濡滑，濡滑主湿浊内蕴。阴液亏虚则不化气，气火内烁，湿浊蒸腾，故见胃糜舌腐。脉不耐重按，示正气已虚，邪热内陷，病势深重。", ["弦", "细", "急", "濡"]], "7353": ["病机", "脉数糊滑，数主热，滑主湿，糊为湿浊黏滞之象。湿温旬日，汗不解，胸闷气逆，便泄溲闭，舌苔薄白底腻，皆湿郁三焦、气机痹阻之征。湿遏热伏，恐转痢疾，脉象正示湿浊壅盛、热邪内郁之病机。", ["数", "滑"]], "7354": ["病机", "脉沉细涩，沉主里，细主阴伤，涩主湿滞血行不畅。湿温七日，烦热胸闷恶心，汗出至颈而还，苔黄罩灰，乃湿遏热伏，邪郁于里，气机不畅。脉沉细涩正合湿浊内阻、热邪不能外达之机，故有内闭神昏之虞。", ["沉", "细", "涩"]], "7355": ["病机", "脉糊不爽，糊为湿浊黏滞、气机不畅之象。斑痧已发而烦热不减，暮则神昏谵语，苔霉化而底白掯，乃邪湿郁蒸，欲泄不能即泄。脉糊示湿浊蒙蔽清窍，热邪内陷心包，故恐内闭昏痉。", []], "7356": ["病机", "脉形不爽，即脉象模糊不畅，为湿浊未清、气机未畅之征。汗出热解而脉仍不爽，说明蕴湿未尽，余邪留恋，气化未复。故当继续泄化湿浊，以畅气机，不可因热退而遽补。", []], "7357": ["病机", "右脉糊数，糊主湿浊，数主热；左脉弦大，弦主木火，大主热盛。水痘后余热与谷气交蒸，湿邪遏伏，津不上布，故舌干白不渴。湿热熏蒸，湿多热少，阳明少降，少阳木火挟浊上腾，蒙阻清窍，故耳聋、神烦、暮热。脉象正示湿热内蒸、木火上升之机。", ["糊", "数", "弦", "大"]], "7358": ["病机", "右脉糊数，糊为湿浊黏滞，数主热。白㾦已发，肺气虽得宣泄，然阳明之热、太阴之湿未遽化，熏蒸之势难解，故热仍起伏，迷蒙多寐。舌淡红苔白腻，脉糊数，皆邪湿溷处、秽浊蒙蔽清阳之象，故需芳香破秽。", ["糊", "数"]], "7359": ["病机", "脉象糊数，糊主湿浊黏滞，数主热。症交八日，热重汗不畅，红疹未透，恶心脘痞，汤饮停聚，苔白不渴，皆湿阻气机、表气不达之征。湿蒸热动，邪难外泄，脉糊数正示湿浊内蕴、热邪郁蒸之病机，故恐内蒙昏痉。", ["糊", "数"]], "7360": ["病机", "原文谓\"脉仍糊数，热犹未解\"，糊为脉象模糊不清，数则主热。二诊后汗出热减、烦懊大定、胸痞转舒，症虽减而脉仍糊数，说明气分之邪依然留恋未清，热未全解。脉数应热，糊则示湿浊未化、邪未透达，故断为气分余邪留恋，需再宣化。", ["数"]], "7361": ["病机", "原文\"脉象糊滑而数\"，滑主痰，数主热，糊示痰热胶结不化。症见不悲而泣、不恐而惊、痰稠灰黑、腹中攻撑、便溏，乃邪从外达而痰被热蒸，蕴而不化，胆胃之气失降，胆木漂拔。滑数之脉正应痰热内蕴、胆胃不和之机。", ["滑", "数"]], "7362": ["预后", "原文\"脉静身凉，稠痰渐少，思谷知味，胃气渐开，悲泣惊恐亦定\"，脉静指脉象由数转和缓，为邪退正复之象。身凉、痰少、思纳、神定，皆示热清痰化、胃气渐开，故属预后转佳之候，宜和中以清余蕴，防余邪复聚。", []], "7363": ["病机", "原文\"惟脉形左大\"，左脉候肝，大为阳亢有余之象。症见头重眩晕，乃肝阳挟痰上逆，扰于清窍。苔白已化、胃开思纳示湿浊渐退，而左脉独大提示肝阳未平、痰随阳升，故主肝阳挟痰上逆之病机，治再熄肝化痰。", ["大"]], "7364": ["病机", "原文\"左脉弦滑，右部糊滞\"，弦主肝、主饮，滑主痰，糊滞示饮浊窒塞。症见烦闷、脘痞、哕恶呕吐、头目晕眩、渴喜沸饮，乃肝阳上逆挟停饮窒塞气机。左弦滑应肝阳挟饮上逆，右糊滞应中焦饮浊不化，故恐发痉发呃。", ["弦", "滑"]], "7365": ["预后", "原文\"久病湿热，化燥化火，而藏气虚微，脉至少神，症属难治\"，脉至少神指脉象虚微少神，为脏气虚微、胃气将败之征。湿热久羁化燥化火而正气已虚，脉失神气，故断为难治，循例告辞，属预后不良之论。", []], "7366": ["病机", "原文\"脉闷数不扬\"，数为热，闷而不扬示湿邪遏伏、阳气不宣。症见暮重、懊烦闷乱、神识模糊、目赤颧红、喜沸饮、气逆似喘，乃暑热内蒸、湿热外遏，湿为阴邪旺于阴分故暮重，湿蒙清窍故神糊，热蒸湿腾犯肺故似喘。数而不扬正应湿热遏伏之机。", ["数"]], "7367": ["预后", "原文\"脉较数，苔略化，似有松动之机\"，数脉较前略减，苔渐化，示痰湿蕴结、上焦气郁痹阻之势稍有松动。然极盛之时虽略转机尚难足恃，痰湿蕴结未解，故当预防神昏发痉，属预后判断兼防变之论。", ["数"]], "7368": ["病机", "脉数糊滞，数主热，糊滞为湿热郁遏、痰气阻府之象。原文谓“湿热郁遏，津液不能布散于上”，故见烦闷频渴、渴不多饮；脐下板满按痛，乃痰气阻府、里气郁遏。脉糊滞反映湿浊痰积内阻，气机不畅，与斑疹隐约、热势起伏相应，恐内闭神昏发痉厥。", ["数", "糊", "滞"]], "7369": ["病机", "脉形糊滑，糊为湿浊蒙蔽，滑主痰湿内蕴。原文述湿温“邪与湿蒸，熏蒸之气，弥漫胸中”，故见迷蒙多睡、耳窍不聪；痱疹密布、舌质滑白，皆湿浊占清位、清窍不宣之征。脉糊滑正合湿蒙清阳、浊邪弥漫之病机，恐由湿而蒙、由蒙而闭。", ["糊", "滑"]], "7370": ["病机", "脉虽数却沉细，继转糊滑，数主热，沉细为阳郁不伸，糊滑乃痰湿郁遏。原文谓“中阳不足，而痰湿郁遏”，故热盛而脉不浮大；湿蒸成痰、热郁成火，则颧红目赤、惊跳。脉象由沉细转糊滑，反映痰湿渐化热而内壅，有痉厥之虞。", ["数", "沉", "细", "滑"]], "7371": ["病机", "脉数较爽，数主热，爽示脉来较前流畅，为邪热渐透、郁滞稍减之象。原文谓“肌表之风，三焦之暑，太阴之湿，悉经化火，充斥三焦”，故热仍起伏、烦扰面赤、赤疹密布。脉较爽说明前法已使部分郁热得泄，但火势仍盛，故需大苦大寒泄热。", ["数", "爽"]], "7372": ["病机", "脉数浮弦，数主热，浮主风邪在表，弦主饮邪与痛。原文谓“风热感受于上，伏暑窃发于内”，两邪相并化火，上迫肺金，故咳嗽气逆、痰稠带红、左胁作痛。浮弦应风热挟饮上逆，数应伏暑化热，脉症合参，邪势正炽，有昏喘之虞。", ["数", "浮", "弦"]], "7373": ["病机", "脉数糊滑，数主热，糊滑主湿浊痰邪内蕴。原文谓“伏暑内发，夹湿熏蒸，蕴于肺胃”，故发热得汗不解、胸闷恶心、苔白黏腻。脉糊滑正反映湿浊蒙蔽、气机不畅，与暑湿熏蒸肺胃之病机相应，症方两日而势炽张，故以泄化为法。", ["数", "糊", "滑"]], "7374": ["病机", "脉忽大忽小忽歇，大小交替为邪正交争、气机紊乱，歇止为湿浊阻遏、脉气不续。原文谓“伏暑之邪，为湿所抑，不能泄越”，故微寒热甚、烦懊恶心、苔白掯。脉象不定反映湿抑暑邪、中宫气机壅塞，津气不克上承，故恶燥喜润。", ["大", "小", "歇"]], "7375": ["病机", "原文未识脉名，但言“脉仍歇止”，歇止为湿浊内阻、气机不续之象。原文谓“气湿未能流化，清津安能上供”，故频渴欲饮、饮则呕吐。脉歇止与湿阻中焦、清津不升相应，说明前法虽稍得寐，湿浊仍未化，故从苦辛合化再进。", []], "7376": ["病机", "脉闷细如昨，右部仿佛沉伏，乃郁遏虽开而气机未畅，卫阳已亏。汗出肤冷、汗收烦懊复盛，显系内闭外脱之兆。细为阳衰，沉伏主邪闭，脉气不畅故闷细，右部沉伏尤见肺卫郁滞。此非单纯邪实，正虚邪陷，故可虞。", ["细", "沉", "伏"]], "7377": ["预后", "六脉皆起但仍歇止，乃正虚邪郁、营卫不相续之象。烦懊大定、渴退、汗出肤温为转机，然歇止脉示气血断续，虽邪退而正未复，还怕里陷。歇止主脏气衰微，此际脉起而止，正虚未复，预后须慎。", ["歇止"]], "7378": ["病机", "脉由细涩转为弦滑，舌剥痕被浊苔满布，为退象。细涩主阴血不足、脉道不利；弦滑主痰湿内蕴、气机渐畅。此转脉示邪有外达之机，湿浊渐化，故为退候，然弦滑未静，痰湿犹存。", ["细", "涩", "弦", "滑"]], "7379": ["病机", "脉又转细，时见歇止甚至隐伏，神情少爽、胸闷烦懊，乃正虚邪郁、气不足鼓动之象。前用连附泻心脉即起，今补中扶阳而脉转异，细为气衰，歇止伏主阳微邪陷，痰少倦甚，湿浊弥漫中焦，气机不运。", ["细", "歇止", "伏"]], "7380": ["预后", "脉歇及数象皆退，大便畅行，为气湿开通、胃气将起之佳兆。歇止主气机断续，数主邪热，二者皆退，示邪去正复，故曰谨慎。此脉转平和，预后向安，然仍须调护防复。", ["歇", "数"]], "7381": ["病机", "脉象弦滑，舌红苔白浮，脐上脘下梗痛跳动，乃脾胃为浊痰所遏，胃不降、脾不运，肝气郁而疏泄失职。弦主肝郁，滑主痰湿，浊气阻冲脉故突起一条，木郁土中，作酸阻食，皆痰浊肝郁之征。", ["弦", "滑"]], "7382": ["病机", "左寸细弱、关弦滑、尺小涩，右寸濡软、关尺虚弦，重取空豁无根，此中气虚微之兆。弦滑为肝木摇撼中州，细弱濡软主气衰，空豁无根即木无胃气，故嘈杂呕恶吐青绿，肝浊上泛，病伤根本，大为可虑。", ["细", "弱", "弦", "滑"]], "7383": ["病机", "脉稍觉黏指，仍涩数，乃胃气空乏、胃阴耗伤之象。涩主阴血不足、脉道不利，数主虚热，黏指示痰湿未净。吐水嘈杂减而痰涌痞满，胃阴亏而浊未清，虽见转机，正虚难恃，故仿戊己汤益阴。", ["涩", "数", "黏"]], "7384": ["病机", "脉濡细而涩，舌光无苔，乃气阴并亏之象。濡细主气阴不足，涩示血行不畅，肝木之气与饮气互结，聚形攻撑虽定而气分窒滞。大便两旬未行，脾土不能鼓舞运旋，衰羸之症未稳。", ["濡", "细", "涩"]], "7385": ["病机", "脉尚细涩，舌苔薄白而掯，小溲作酸，时犹嘈杂。细涩为中气未复、肝虚撼扰、肾阴亦亏之征，气化不及州都，故小溲作酸。虽转机已现，然大节恰临，还有意外之虞。", ["细", "涩"]], "7386": ["病机", "脉濡而滑，左部细弱，舌淡少华频渴。濡滑主血液衰脱，细弱示气少，正合《内经》谷入多而气少之例。血液衰脱不及告复，故仍未能起坐，偏左头颊作痛，仿复脉法。", ["濡", "滑", "细", "弱"]], "7387": ["病机", "脉象滑大而数，沉取濡软，舌淡红苔白掯。滑大数主邪湿痰气交会中宫，濡软示正气渐虚。中州阻痹，坎离不接，彻夜不睫，所虑神昏发呃，拟泻心为法。", ["滑", "大", "数", "濡"]], "7388": ["病机", "脉象糊数不扬，舌红苔白干毛，齿垢唇焦，无汗哕恶。糊数不扬乃邪湿滞交蒸，伏邪欲从外达而气湿相持于内，故叠经疏解未能作汗。暑必归心，懊烦闷乱，深恐内闭神昏发痉发厥。", ["数"]], "7389": ["病机", "脉数糊滑，苔白糙腻异常，汗不畅达。数滑主暑邪与湿痰相合，三焦气窒，里气不能外通于表，故不能作汗。湿阻中州则哕恶，暑必为烦，若不从外达即从内闭，将至神昏发痉发厥。", ["数", "滑"]], "7390": ["病机", "脉数犹带糊细，舌苔大化，白色转黄，近根微霉。数细示湿痰郁遏稍开而暑湿相蒸未遽化，上中二焦邪湿交炽。虽烦闷减、厥未作，然将及两旬，还恐化燥昏厥之类。", ["数", "细"]], "7391": ["病机", "脉数糊大，头痛退轻而热蒸辄甚，咽中牵腻，频作恶心，窒闷尤甚。数大主暑湿内蒸，火风随之上旋，肺胃之气不能开降。病起即发白㾦，气分素虚，恐湿热交蒸致内窜昏厥。", ["数", "大"]], "7392": ["病机", "原文未直接描述脉象，但通过“肺脉通心”说明暑湿蒸腾于胃，湿蕴为热，上扰心神，故时作懊烦。病机为暑湿蕴阻气分，热势虽轻但未清，舌苔中心黄掯，示湿浊未化。治疗以轻清泄化，使热势微轻，大便通行，为正色。", []], "7393": ["病机", "脉数沉郁不扬，数主热，沉主里，郁而不扬示暑湿夹湿郁阻气分，热不得外达。症见凛寒而热、热势不扬于外而甚于里、胸闷脘痞、恶心呕吐、渴不多饮、少腹作痛、咳嗽痰多、苔黄质腻，皆暑湿郁阻肺胃，气机不降，开合失度所致。", ["数", "沉"]], "7394": ["病机", "脉象稍扬而带糊滑，稍扬示气机略通，糊滑主湿蕴成痰。症见中脘痞阻已舒、恶心减、凛热退轻、咳松，但下午微寒、痰多胶腻、舌红苔白不匀，说明上焦微通而湿痰仍弥漫肺胃，故再参清化。", ["滑"]], "7395": ["病机", "脉细弦数，细主阴伤，弦主木郁，数主热。木郁已久，暑湿内伏，风邪外束，脾胃受困，骤然吐泻。伏暑风邪郁于肺胃，致咽赤痛、肌痒发痧、烦热不解、热迫下注便频、胃热上冲干恶，又经行不爽，舌红无苔，示热郁阴伤，势多变局。", ["细", "弦", "数"]], "7396": ["病机", "左脉弦紧，弦主肝胆，紧主邪实。邪热化火，熏灼肺胃，阴津暗伤，故咽中赤碎痛甚、环口热泡、两腮碎痛、烦渴欲饮、经色紫黑、舌红边尖绛刺。弦紧示火郁不散，恐热入血室而致昏喘。", ["弦", "紧"]], "7397": ["病机", "左脉细弦而数，右脉细数微弱，细数主阴伤热炽，弦主郁，弱主气衰。火热劫烁肺胃，阴津大伤，故咽痛略定而白腐不退、烦热、口渴喜凉饮、肌肤痒、舌白质红尖红点。咽通胃喉通肺，金因火旺而腐白，恐火刑金烁致肺喘。", ["细", "弦", "数", "弱"]], "7398": ["病机", "脉象弦数，弦主肝胆，数主热。肝胆之火风交炽于上，故咽痛白腐布满、项侧耳后肿胀作痛、热势不衰；欲行未行之血凝滞于下，故经紫色不净、脐下按之板滞。营郁则热，舌红起刺，治从清泄兼和营滞。", ["弦", "数"]], "7399": ["病机", "脉小数弦，小主阴虚，数主热，弦主郁。郁伏之邪火由脏出腑、由腑出经，故喉腐定、痛势缓而遗毒胀痛更甚，口干渴、唇吻燥痛。症虽转顺，但本质阴虚，邪火燔灼余气伤液耗，火化风劫液，急宜存阴清热、导腑解毒。", ["小", "数", "弦"]], "7400": ["病机", "脉细数而滞，细为阴伤，数为热，滞为湿阻气机。伏暑新凉外束，暑湿内郁，气机不畅，故胸闷恶心、经来少腹不舒。脉滞反映湿浊阻滞，热不得透，深恐邪内闭昏痉。", ["细", "数", "滞"]], "7401": ["病机", "脉滞数不扬，滞主湿郁，数主热，不扬为邪遏不达。暑湿交蒸，无形之暑与有形之湿混合，气机氤氲，故热起伏、胸闷恶心、头昏晕冒、汗不畅。经来涩少，血因热滞，虑内窜昏厥。", ["滞", "数"]], "7402": ["预后", "脉仍糊数，糊为湿浊未清，数主热邪尚盛。虽热减恶心定，但脉象未和，说明伏气与湿交蒸之势未解，邪势尚甚，还恐起伏生波，预后须防反复。", ["数"]], "7403": ["病机", "脉左关弦大，左关候肝，弦主气机郁滞，大主邪势未衰。暑湿交蒸于气分，肝胃之气失和，故脐上作痛、胸闷恶心、经事涩少。脉象反映肝胃不和，需调气化湿。", ["弦", "大"]], "7404": ["病机", "脉濡主湿，暑为热气，暑湿内蕴，故热起伏、烦扰不宁、语言错杂、胸闷频渴、汗多不解。经水适来，热与血结，深恐热入血室而致昏厥。脉濡说明湿邪偏盛，暑热被湿遏。", ["濡"]], "7405": ["主病", "脉弦滑，弦主少阳，滑主痰湿。时感之邪与湿混合，阻遏少阳阳明，发为湿疟，故先寒后热、寒战烦渴、恶心胸闷、汗出秽浊。病起失精，邪易内陷，恐少阳并入阳明而变但热不寒。", ["弦", "滑"]], "7406": ["病机", "脉弦滑带微数，弦主气郁，滑主痰，数主热。久咳见红，痰阻营卫，阴阳不交，寒热交作，营卫郁勃之气欲借阳经泄越，气血凝滞而偏左有形。脉数示阴气渐伤，当通营卫之痹。", ["弦", "滑", "数"]], "7407": ["病机", "右脉濡软，左部细弦。濡软主痰湿不运，细弦主营卫阴阳受阻。痰湿熏蒸阳明，营卫失和，故大疟转寒热叠来、汗多气酸带秽。脉象反映湿痰内蕴、营卫不通，宜和中化痰通营卫。", ["濡", "软", "细", "弦"]], "7408": ["病机", "脉弦滑转甚，弦主痰饮、滑主痰湿，说明痰热未净而益加壅盛。前诊畅汗热达，然苔根黄腻、夜寐不安，皆痰热内扰之征。脉象转甚，正合痰热胶结难化之势，故以加味温胆法清化痰热、和胃安神，候其脉转则痰热渐化。", ["弦", "滑"]], "7409": ["主病", "脉糊不爽，即脉象模糊不清、来去不分明，为湿邪黏滞、阻遏气机之象。寒热间作而脉糊，湿邪弥漫三焦，疟邪与湿相合，故断为湿疟。湿性黏腻，脉道不清，正合湿疟之机，治以和以化之，化湿截疟。", []], "7410": ["病机", "脉濡主湿、主气虚，苔白质腻亦湿象。久疟屡止屡发，脾胃气弱，运化无力，湿浊内蕴；食入不舒、胃钝少纳为脾运不健，左胁下按之板滞乃余邪结聚肝络。脉濡正应脾胃气弱、湿邪留恋之机，故拟和中运脾疏络，标本兼顾。", ["濡"]], "7411": ["病机", "脉濡滑，濡主湿、滑主痰湿内蕴，苔白质腻相应。胃钝少纳、形体恶寒，是湿有余而阳不足，命火不能蒸变水谷，胃气呆钝。脉濡滑正示湿浊内盛、阳气不振之机，故拟化湿和中、温助阳气，使脾胃转旋则络邪默化。", ["濡", "滑"]], "7412": ["病机", "脉细数，细为阴虚，数为内热；左部微弦，弦属木火。寒热稍减而五心烦躁、喜得凉饮，皆阴虚木火内炽之候。营卫阴阳不和，根源在阴虚火旺，脉细数弦正合此机，故再和阴而参酸苦涌泄，以泄木火、和营卫。", ["细", "数", "弦"]], "7413": ["病机", "脉弦主痰饮，故曰疟脉自弦。疟症黄涎聚于胸中，无痰不成疟，湿痰未清而西药止截，致腹满肤肿面浮，成疟胀重症。脉弦正应痰饮内聚、气机不畅之机，痰湿壅阻则胀满浮肿，故不可轻视，当化痰逐湿为要。", ["弦"]], "7414": ["病机", "脉象溷数，数为热，溷示湿热混杂不清。大便虽通、有形之积已下，而热仍起伏、汗出即解，苔腻心黄，是湿热氤氲、极难泄化。脉数正应湿热内蒸之机，故于泄化之中参辛温寒以通营卫，使湿热分消而营卫调和。", ["数"]], "7415": ["病机", "本段未明言脉象，以寒热分明、阳明之邪并归少阳为辨。阳明胃脉上通于心，少阳胆经无出无入，邪居其间不能蔓延脏腑，故断不虑病变。此从经络脏腑传变论病机转归，寒热分明即邪有出路之兆，与脉象无直接对应。", []], "7416": ["病机", "原文谓「脉形左大」，左脉候表，大为邪盛之象，寒热五日一来，邪正交争于表里之间，故脉形偏大。大而未见虚象，说明邪实而未深陷，病位在半表半里，故治法宜「和化」而非峻攻峻补，以调和表里为要。", ["大"]], "7417": ["病机", "原文「脉不甚数」，身热而脉不数，说明热非实火，乃痰湿郁遏阳气所致。痰湿内阻，阳气不得宣通，故自觉身热而脉象不数，此为郁热而非实热，痰湿为本、身热为标，故当化痰祛湿以通阳。", []], "7418": ["病机", "脉濡滑，濡主湿、滑主痰，正合「痰多」之症。日晡漫热、汗出稍松，乃痰湿阻遏、阴阳开合失其常度所致，非纯虚之热。年近花甲见此濡滑之脉，痰湿壅盛，故原文谓「不宜见此」，拟苦辛寒开阴泄热以化痰湿。", ["濡", "滑"]], "7419": ["病机", "三诊脉象仍濡滑，濡为湿、滑为痰，与「便溏不实」「舌苔中心黑润」相合，皆痰湿内停之征。运化迟钝乃脾阳不克鼓舞，痰湿不运，故脉见濡滑。治拟温中蠲饮，温运脾阳以化湿痰，脉症相应。", ["濡", "滑"]], "7420": ["预后", "脉软而数，软为虚、数为热，久嗽痰稠带青绿、寒热往来，乃肝肾素亏而脾胃痰热熏蒸于肺，阴阳开合为痰所阻。虚中夹实热，脉软示正虚，故原文谓「将入劳损之门，不易图治」，属预后不良之判。", ["软", "数"]], "7421": ["病机", "原文「脉象左寸微浮」，左寸候心肺，微浮示痰气阻遏、营卫不利。气虚多痰之质，食黏腻窒滞，气不行、湿不运、痰不化，营卫阴阳由此而阻，遂先寒后热。痰湿熏蒸欲化燥，舌苔焦黑，皆痰气窒滞阳明之病机。", ["微", "浮"]], "7422": ["病机", "「脉数稍退」，数脉主热，数退则郁蒸之热已退三舍，与舌焦黑顿化相应。然热仍未退、右胁仍痛、痰鸣欲咳，是痰湿交蒸未遽化，中脘略软、频转矢气为府气欲通之象，故再拟疏化并顾中阳，防内陷神昏。", ["数"]], "7423": ["预后", "六诊「脉象和缓」，缓为胃气调和之象，较前数脉已趋平和，示邪热渐退、正气渐复。但小溲有时仍痛，是余热未尽，故脉虽和缓而症未全除，再清泄以澈余热，属向愈之预后判断。", ["缓"]], "7424": ["病机", "痛泻呕吐后中州不舒，脉沉细。沉主里、细主虚，寒湿内阻中焦，阳气不伸，故脉道沉细。寒湿困脾，升降失司，则痛泻呕吐相继；脉沉细正合寒湿内阻、中阳不振之病机，非单纯虚象。", ["沉", "细"]], "7425": ["病机", "寒食交阻，胸中阳气逆乱，泄泻稀水继而复吐，肢厥脉伏，汗出不温，目陷音低。脉伏乃阳气闭郁、不能外达所致，与肢厥、中脘不通、胸中大痛相应，示中阳毫无旋转之权，有内闭外脱之虞，故用黄连汤通胃中阴阳。", ["伏"]], "7426": ["预后", "二诊后六脉俱起、肢厥转温、胸痛止、泄泻减，病有转机；然湿热未楚，湿化为热劫烁阴津，舌苔干黄无津、频渴欲饮、时带呃忒、小溲全无、神识迷沉。脉由伏而起，反映闭郁渐开而阴津受劫，神识迷沉、无溲为危险之候。", []], "7427": ["病机", "饮食内停，寒热杂感，清浊相干，三焦闭塞，吐泻后腹笥板滞、按之满痛、噫出卵臭，脉伏肢厥，螺瘪目陷。脉伏由浊积闭塞、气道不宣、阳不敷布所致，与肢厥、目陷相应，示湿食停阻、阳气不能外达，危险已极，故议苦辛开通、降泄浊积。", ["伏"]], "7428": ["病机", "春温疫疠之邪从内发，发热咽痛、遍身丹赤、痧点连片、咽痛连颈肿，右脉滑数左脉弦紧。滑数主温疫化火、充斥内外；弦紧主邪势鸱张、郁于少阳。脉症合参，知火邪蔓延三焦，恐火从内窜而致神昏发痉，故拟咸寒泄热、甘凉保津。", ["滑", "数", "弦", "紧"]], "7429": ["兼症", "头胀恶风发热，头面四肢已透痧点，咽中微痛，脉数苔白，风温之邪袭于肺胃。数脉主热，与发热、痧点相应。适值经来，血室正虚，恐热邪乘虚入于血室，故特揭不可与寻常并论，示人须兼顾经水适来之兼症。", ["数"]], "7430": ["病机", "痧虽畅透而不肯化，经事淋沥未已，舌燥咽干痛，脉象细数。细为阴血不足，数为热邪内迫；经水适来血室空虚，血分暗为热迫，故脉细数。此脉示热入血分、阴津受灼，与舌燥咽干、经淋相应，故再泄热凉营。", ["细", "数"]], "7431": ["预后", "八诊脉静身凉，履夷出险。脉静指脉象平和、不躁不数，与身凉并见，示邪热已退、正气渐复，故曰幸甚。既出险境，余炎未澈，故拟清养肺胃以澈余炎，属病后调治、预后向安之候。", []], "7432": ["病机", "脉紧数而弦，紧主邪郁，数主热盛，弦主气机不畅。时疫之邪郁于肺胃，化火熏蒸，故见咽肿作痛、丹痧未畅、胸闷神烦。脉象反映邪热内郁、肺胃气壅之病机，恐邪化为火而生枝节。", ["紧", "数", "弦"]], "7433": ["预后", "脉象紧数，紧为邪束，数为热炽，乃春温疫疠之邪由募原入胃腑，化火熏蒸肺胃，充斥内外。热炽丹痧密布、咽赤肿痛、协热下利，今渐增气喘，脉紧数示邪热鸱张，正不胜邪，危象已著。", ["紧", "数"]], "7434": ["病机", "脉数弦滑，数主热，弦主风动，滑主痰壅。外风引动温邪，邪从内发化火，喉风发痧，舌心焦黑，黏痰缠扰咽中。脉象反映风火痰热交炽，邪势鸱张，时行急病，变端不测。", ["数", "弦", "滑"]], "7435": ["病机", "脉象滑数，滑主痰热内壅，数主火盛。丹痧虽透足而热势不减，咽痛赤肿，舌红无苔，足见邪势太重，半化火热郁于肺胃。况经水适行，血分空虚，热易乘虚袭入营中，有热入血室之虞。", ["滑", "数"]], "7436": ["病机", "脉仍滑数，滑主痰热未清，数主火邪尚炽。痧点畅发、喉肿退、热略减，然脉未和，舌红无苔，不时恶心，乃胃火逆冲、胃气不降。邪势太重，泄者虽泄，留者仍留，故脉象仍示痰热内蕴。", ["滑", "数"]], "7437": ["病机", "脉数细弦，数主热，细主血虚，弦主肝郁。热甚之时经水适行，血海空虚，邪热乘虚入血室，热扰血中，神魂不安，故寤难成寐、多言错语。脉象示热入血室、阴血耗伤之病机，恐致神昏痉厥。", ["数", "细", "弦"]], "7438": ["病机", "脉数，重按滑大，数主热，滑主痰湿，大主邪盛。风温发痧，邪热半从外出，半从里陷，直趋大肠，致泄痢无度、痧点欲回未回、咳嗽不爽、遍身作痛。脉象示邪热内陷、肺胃大肠同病，上下交困。", ["数", "滑", "大"]], "7439": ["预后", "脉滑大稍平，滑主痰湿内蕴，大主邪势尚盛，然较前稍平，示陷里之邪略得升散，脾之清气稍得升举。泄泻大减，白冻亦退，神情振作，舌红绛较淡，脉象转和，种属转机之象，守前法可望应手。", ["滑", "大"]], "7440": ["病机", "脉数竟在七至以外，为热邪内陷，与湿相合，悉化为火，故下痢黑黄、肛门烙热、舌红起刺。数脉主热，七至以上示热盛，此协热下痢之病机。", ["数"]], "7441": ["病机", "脉象弦数，弦主肝旺，数主热盛。丹痧回没太早，火热内灼，口疳咽痛，热胜则肿，面目肢体虚浮，此热毒内蕴、肝风欲动之机，恐变肿胀。", ["弦", "数"]], "7442": ["预后", "脉细数而促，细为阴亏，数为内热，促为气急。久咳失血，金水亏虚，肉脱形瘦，舌淡少华，中气薄弱，症入劳损之途，故曰不能许治。", ["细", "数", "促"]], "7443": ["病机", "脉细弦数，细主阴伤，弦主木旺，数主热。清晨咳甚，寅卯属木，金病遇木旺之时，病势胜矣。药既应手，未便更章。", ["细", "弦", "数"]], "7444": ["病机", "脉细数，舌红苔黄，细为阴虚，数为内热。咳嗽哕恶，上午为甚，辰巳之交寒热，此肝肾阴虚，气难摄纳，阴阳不能和协，虽略转机，不足为恃。", ["细", "数"]], "7445": ["病机", "脉象虚弦，虚为肺气不足，弦为肝邪有余。伤风激动伏饮，邪去饮复阻肺，肺虚肝旺，气撑不和，得矢气则松，将成虚损之症。", ["虚", "弦"]], "7446": ["病机", "脉细而数，右寸关微浮，细数主阴伤内热，浮为邪在肺卫。肺感风邪，咳嗽身热，络损血溢，此伤风成劳，邪未泄而正已伤。", ["细", "数", "浮"]], "7447": ["病机", "脉形沉细而数，颇有促意，沉细为阴伤，数为阴火，促为气逆。失血久嗽，面红易怒，恶寒足厥，此血去阴伤，龙雷之火不能藏蛰，阴火逆犯，肺降无权。", ["沉", "细", "数", "促"]], "7448": ["病机", "脉数稍缓，较前数急已减，示壮水益肾、辛温为导后火势略平，故足厥转温；然交节仍复见红，说明龙相之火尚未安静，数脉未尽，虚火仍动，病机在肾水不足、相火不潜，主虚损火升之证。", ["数", "缓"]], "7449": ["病机", "脉细濡而苔白无华，细为气弱，濡为湿滞，合痰饮多年、病损未复，脾虚不运，水谷尽化为痰，痰阻肺肾相通之道，故气喘肿发、吸气少腹触痛、神情痿顿，主脾肺肾虚而痰饮内阻，诚恐损而不复。", ["细", "濡"]], "7450": ["病机", "脉象虚弦，虚为阴亏，弦为木旺，合吐血盈碗、呛咳气逆，乃肝肾阴虚，虚火载血上行，阴不收摄，血从脘下上升；弦为肝火，虚为阴损，主阴虚火逆之吐血，恐咳不止而致入损。", ["虚", "弦"]], "7451": ["病机", "脉仍虚弦，吐血未定、色鲜赤，食入胀满、气冲作呛，是阴虚木火上凌，激损肺胃之络，络损血溢；虚弦示阴亏而肝火未平，故主阴虚火逆、肺胃络伤之吐血，治当降胃凉营、降气即降火。", ["虚", "弦"]], "7452": ["预后", "脉细弦而数，舌红心剥，细为阴亏，弦为木旺，数为内热，合咳嗽见红、内热连绵、肛痈、月事停阻、心烦咽痛，乃肺肾并损、金水不能相生，虚火内炽；脉数而细，损象已深，故曰不能许治，仅以金水双调缓兵。", ["细", "弦", "数"]], "7453": ["预后", "脉稍柔缓，较前细弦而数已见柔和，内热略减、咽痛亦轻、胃气稍振，是金水双调后虚火稍平之象；然咳嗽时轻时重，金水并损未复，缓仅示胃气渐回，故姑踵效方以观其后，仍属损证未复。", ["缓"]], "7454": ["预后", "脉数细急，数为虚火，细为阴亏，急为脏气不安，合脾肺肾三脏并亏：脾不运则生痰，肺不降则呛咳，肾不收则气逆，痛泄咽疼时轻时重，虚损不复；数细而急，正损象未缓，故只聊望缓兵。", ["数", "细", "急"]], "7455": ["预后", "脉细，关弦，细为气阴并亏，关弦为肝木偏旺，合形寒已退而咳嗽痰多、左胁肋气上逆，乃气阴两亏、肝气上逆之虚损情形；细弦并见，正气难复，故曰一派虚损，不敢许治。", ["细", "弦"]], "7456": ["预后", "二诊呛咳稍减，脉亦稍缓。前诊脉当偏数或弦，药后脉转缓和，说明邪热渐退、肺气渐和，药既应手，故可再为扩充。脉缓在此非平人从容之缓，而是病脉转和之象，提示病情向愈，与呛咳减轻相应。", ["缓"]], "7457": ["病机", "脉细为阴血亏少，数为虚火内动。原文谓阴分素亏、嗜饮激动阳气，肝肾之血随火上逆，吐紫黑厚血而消瘦；秋燥引动呛咳，金水双调后咳定，证明虚火凌上烁金。脉细数正合真阴亏虚、虚火内扰之机，舌苔黄糙亦为阴伤有热之征。", ["细", "数"]], "7458": ["病机", "脉数主内热。伤风夹湿损肺，咳嗽痰稠黄、不时见红，痰血日甚，兼肛门漏管，为阴虚挟湿、湿热熏蒸，肺胃之络受损。脉数内热正是湿热化火、阴液受灼之象，故断为痿损情形，仅作缓兵之计。", ["数"]], "7459": ["病机", "本段未识脉名，重在辨咽痛病机。原文谓少阴之脉系舌本循喉咙，咽痛其标在肺、其本在肾。痰红虽减而咽中隐隐作痛，说明肺胃之热渐轻而肾阴亏虚未复，根本已伤，故叹非草木之功所能挽狂澜于既倒，属病机深重之论。", []], "7460": ["病机", "脉细数有急促之意，为阴伤火旺；右关弦滑，主胃中湿热痰浊。原文述足肿属湿热，咳而损络吐血，血去阴伤，金水不能相生，风邪悉化为火，肾水日亏、肺金日损，胃中湿热熏蒸于上，故声音雌喑、咽痛内热、痰黄稠。脉症合参，病机为阴虚火旺兼湿热熏蒸。", ["细", "数", "弦", "滑"]], "7461": ["预后", "本段未识脉名，原文仅言脉症尚属相安。二诊承前风湿热相合、熏蒸损肺之病机，前方引导湿热下行以缓熏蒸、救阴液耗损，药后脉症相安，故姑踵前意再进。此段主旨在于据脉症相安判断可守前法，属预后与治法之间的过渡。", []], "7462": ["预后", "脉数微促，数为有热，促为脉来急迫而时一止，主火盛气逆、阴液亏耗。原文谓嗜饮伤肺、屡次见红、久咳不止，金水并亏，症入损门。数促之脉反映虚火内炽而脏气不相接续，故虽可苟安目前，难免颓败日后，属损证预后不良之象。", ["数", "促"]], "7463": ["预后", "脉虚为正气亏衰，苔腐示胃气败浊。原文谓肝肾阴水亏损已极，肝风上翔冲侮胃土，呕吐复作，营液气分俱耗，腋下发白㾦。脉虚苔腐而见呕吐、白㾦，为正虚邪陷、气阴欲竭之征，故断为欲脱之兆，勉拟补气育阴，仅尽人事而已。", ["虚"]], "7464": ["病机", "脉象细数，细为阴血亏少，数为内热亢盛。症见咳嗽不减、内热口渴便赤，乃肺金肾水交亏，阴虚不能制阳，虚热内扰。饮食少思，示脾胃亦弱。脉症合参，病机为肺肾阴亏、虚热内炽，久延恐成劳损，故云“将恐不支”。", ["细", "数"]], "7465": ["预后", "脉细如丝，为肾阴枯竭、脉道不充之象。久咳气逆难卧，舌苔腐烂，乃肾虚之极，肾火挟浊上浮。阴精耗竭，虚火上炎，本元已败，故断为“危在旦夕”。脉细如丝与舌苔腐烂并见，提示阴阳离决之势，预后极恶。", ["细"]], "7466": ["病机", "脉形虚弦，关部独大，虚为气阴不足，弦主饮邪与肝旺，关大乃中焦痰火壅盛。原文谓“饮化为痰，痰化为燥，燥化为火”，阴津尽被劫夺。虽气喘略定，痰稍爽，然脉象未和，糜腐时退时来，示痰火燥热交织，阴伤未复，故“尚不足恃”。", ["虚", "弦"]], "7467": ["病机", "脉细沉，细主阴血亏少，沉主病在里、阳气不振。吐血后剧咳多痰，痰皆稀白，苔白无华，显系三焦气虚，脾肺肾俱损。劳损根深，虚不摄血，故吐血；气虚不能化津，故痰稀白。脉症皆示虚损深重，故谓“鞭长莫及”。", ["细", "沉"]], "7468": ["病机", "脉数内热，数为热象，然此热由本虚而来。先天肾亏，湿热下注发为漏疡，又肺感风邪，邪恋不澈，咳久不止，咽痒痰多音闪。本虚表实，虚热内蒸，故脉数。原文断为“劳损情形”，示正虚邪恋，阴液耗伤，非单纯外感可治。", ["数"]], "7469": ["预后", "脉象带数，仍未敛静，数为阴液耗伤、虚热内扰之征。虽肺气稍得下行，咳嗽略减，音声较爽，但时犹燥热，脉数未静，说明阴液已耗，虚热未清。脉症合参，正虚未复，余热留恋，故恐“缠绵不复”，预后堪忧。", ["数"]], "7470": ["病机", "脉象数，左关细弦，尺部缓急不齐。数主虚热，细弦为阴亏木旺，尺部缓急不齐示肾气不摄。吐血后阴虚阳旺，木郁生火，火激血逆，耗成损虚。金水不能相生，肾不纳气，故咳嗽气逆、内热连绵、痰多盈碗。脉症皆示肺脾肾三脏交损，虚火内炽。", ["数", "细", "弦", "缓"]], "7471": ["病机", "脉细弦数，细为阴血不足，弦主肝旺，数为虚热。产后久咳，复产更甚，吐血时止时来，不能左卧，音声雌喑，左胁漉漉有声，咽痒呕吐，舌红少苔。此阴虚木旺，木叩金鸣，肝火犯肺，灼伤肺络。证入损门，正虚邪盛，故“不敢言治”。", ["细", "弦", "数"]], "7472": ["病机", "脉细弦而数，细为阴血亏虚，弦为木火亢盛，数为内热炽张。原文谓\"阴虚木火凌金，金被火铄\"，屡次吐血已耗营阴，木火无制上刑肺金，故久咳不止、内热火升、右颊红赤；音闪不扬乃金被火铄、生化不及之征，水源日涸则损而难复。", ["细", "弦", "数"]], "7473": ["病机", "二诊音闪渐扬而咳不减，舌红苔糙白，脉仍细弦数。细弦数示阴虚未复、冲阳挟龙相上炎，火升灼金故咳不止、内热不除。吐血之后阴分已甚亏，龙雷之火不潜，上冲为患，故须金水并调，滋水制火以平冲逆。", ["细", "弦", "数"]], "7474": ["病机", "脉象细弦，细主营血亏损，弦主筋脉失养、营卫不和。原文谓\"营血不能濡养经络\"，故心悸、肢节作痛；营卫失和则皮寒骨热。此非外邪，乃内伤营血不足、络脉空虚之候，故治宜养血和营以复其濡养之职。", ["细", "弦"]], "7475": ["病机", "脉象细弦，舌红少苔，皆阴虚不复之象。抑郁则阳升不寐，木火刑金致吐血复发；血止后营阴亏损，营卫循环失度，故倏寒倏热、头晕火升、口渴。细为阴亏，弦为木火内动，总属阴虚阳扰、营卫失调之病机。", ["细", "弦"]], "7476": ["病机", "脉形左大，左候肝，大为阳亢不敛。吐血之后阴分未复，操劳则阳气升腾，肝阳上扰故头目昏晕；寐中轰然而热、有汗出之意，乃阳升失潜、阴不敛阳之象。此阴虚阳浮之机，治宜育阴熄肝，使阳得潜藏。", ["大"]], "7477": ["病机", "脉沉弦带涩，沉主里、弦主木郁、涩主血瘀。肝胃不和、木郁土中，久病气滞于络，气多血多之处气留血凝，流行之道壅而不宣，木气横行、土气郁阻，故为痛为黄、溲赤如柏汁。此气血瘀滞之机，与湿热黄疸有别，故拟宣络化瘀。", ["沉", "弦", "涩"]], "7478": ["病机", "二诊中脘较舒、痛亦未甚，然面目色黄不减，脉仍弦涩。弦为木气横逆、涩为血行不畅，示络阻气滞、气血不行之机未除。药既应手，说明宣络化瘀方向不误，故守前意出入，继续疏通气血以消黄止痛。", ["弦", "涩"]], "7479": ["病机", "产后气血亏损，不能制伏肝木，木乘土位。脉象细弦，细为气血不足，弦为肝强；舌苔腻浊示土弱运迟。饮食过节辄便泄、中脘作痛、噫出腐气，皆肝强土弱、运化失职之候，故拟温中运中，降逆以升，使土木相安。", ["细", "弦"]], "7480": ["病机", "原文未明言脉象，仅述“脉症相安”，提示前诊温中运中后脉证趋于平稳。然肝强土弱、脾胃升降失常，故上见噫腐气、下见便溏泄，此乃土虚木乘、清浊相干之机。脉症相安说明中气渐复，但肝强未敛，仍需养脏疏腑以调升降。", []], "7481": ["病机", "脉形濡滑，濡主中虚，滑主痰湿。中虚夹痰，胆胃失降，甲木升浮，故头胀眩晕、火升、身体似觉升浮、四肢作麻。虚里跳动亦为中虚痰动之征。此脉此症，皆由中气不足、痰浊内阻、木气上逆所致，故宜化痰而扶持中气。", ["濡", "滑"]], "7482": ["病机", "六脉细弦均有数意，细为土虚，弦为木乘，数为郁热。原文明言“若以痰浊上泛，则脉象应当滑大”，今细弦而数，故断为土虚木乘无疑。土虚木贼，胃浊不降，故不纳不饥、气冲哕恶、舌红苔黄微灰霉。治宗苦辛酸以平肝降胃。", ["细", "弦", "数"]], "7483": ["病机", "脉象细弦仍有数意，细主中气素虚，弦主木火犯中，数主浊被火蒸。虽哕恶少定、胃纳略增，然中脘微痛，土中有木，胶滞难化。胃浊不降则清气不升，故不纳不饥势所必至。前投扶土熄木尚合机宜，再拟扶持中气、化浊和中、参以熄木。", ["细", "弦", "数"]], "7484": ["病机", "左寸细数，关部弦搏，尺部细涩，右部濡弱重按微滑，尺部细沉。细数主津气耗亏，弦搏主木火未靖，涩主血少，濡弱主气衰，微滑主湿痰留恋。暑温外疡溃后脓水去多，气血阴阳俱损，故便泄无度、痰气上升、口渴不欲饮、舌淡苔糜。", ["细", "数", "弦", "涩"]], "7485": ["病机", "脉弦搏稍收而均带细数，弦搏为木火未平，细数为气血并亏。药后痰涌、汗出、胸次、舌苔均有起色，然湿热逗留，津气遏伏不能上布，故虽不引饮而频觉口渴、舌干少津、懊𢙐里急、小溲涩少。此虚中夹实，培养之剂动多窒碍。", ["弦", "细", "数"]], "7486": ["病机", "脉细而沉，细主阳气不足，沉主里主湿。湿温之后多进甘寒，湿邪有余而阳气不足，纳食后动辄胀满、脘中微觉坚硬，胃府失通降之权。此湿困阳微、脾胃旋运无力之候，故宜温运和中，使脾胃之气鼓舞，则不治满而满自退。", ["细", "沉"]], "7487": ["病机", "脉象带数，数为热为风。感风入肺，肺失清肃，风热郁蒸，故咳嗽痰色黄厚、夜重日轻。数脉主热，与黄厚痰相应，说明风邪化热、肺气不清。治宜肃肺化痰，使肺复清肃之令，则咳痰自减。", ["数"]], "7488": ["病机", "脉数右大，数主热，右大应肺胃。风温袭于肺胃，热邪内蒸故脉数；右脉大者，邪壅肺胃气分，肺失清肃降令，故咳嗽气逆、身热头胀。脉证相合，示病位在太阴肺胃，属风热实邪，非虚损之比，故治宜清肃太阴、疏泄肌表。", ["数", "大"]], "7489": ["病机", "脉象微数，为营液不足之征；脉沉带数，沉主在里，数主热。前诊温疏后咳减而脉仍微数，说明风温渐化而营分已伤，热郁于里未清。原文谓肺恶寒、心恶热，沉数则不宜再投苦温耗伤营分，故出之以和平，兼顾清透与护营。", ["数", "沉"]], "7490": ["病机", "脉象沉弦，沉主里、弦主郁主痛。肺感风温，又熬夜受寒，寒束于外、热郁于内，邪郁太阴，肺金失降，故咽痛呛咳、痰不爽出、头胀恶寒。沉弦正示邪郁在里而气机不畅，非单纯表证，故拟辛温寒合方以彻肺邪，开郁透热并行。", ["沉", "弦"]], "7491": ["病机", "脉弦微数，弦主气郁，数主热。前投辛温寒彻肺邪而咳仍不减，脉转弦微数，说明寒邪已减而热郁于肺未清，气机仍郁，故咳不止。弦为郁、数为热，合示热郁于肺、肃降失司，故再宜清金肃肺，清透郁热以复肺之降令。", ["弦", "数"]], "7492": ["病机", "右脉浮滑，浮主邪在表分，滑主痰湿。咳剧虽止而邪未尽泄，稍感触即喉痒咳剧，说明邪仍内踞肺络；金病不能制木，木火刑金。然右脉浮滑，病仍在肺而未深入他脏，故主疏其新感、宣肺化痰，取三拗汤之意而变其法，疏不碍表、补不滞里。", ["浮", "滑"]], "7493": ["治法", "原文未识脉名，仅言脉证相安。久病投猛剂而脉证相安，说明邪正尚能相持；然邪与正不能并立，不去其邪则正气难保。若一味和平缓治，犹畏疡溃之痛而养毒，故再作背水之计，主张乘脉证相安之时峻药祛邪，属治法取舍之论，非单纯凭脉断病。", []], "7494": ["病机", "脉濡而气口独浮，濡主湿、主虚，浮主邪在表。肺感风邪不为疏解反投补益，邪恋不得泄，咳久不止；气口独浮说明邪仍从外感而来，虽日久仍当疏泄。濡示正气已伤而湿滞，浮示表邪未解，故虽久病不得不为疏泄，不可再补。", ["濡", "浮"]], "7495": ["病机", "脉象弦滑，弦主饮主痛，滑主痰。咳嗽气逆痰多、遍身作痛，正合痰饮阻肺、肺失降令、络隧不宣之候。弦为饮邪内结、气机不利，滑为痰湿壅盛，故脉弦滑主痰饮阻肺之实证，治宜辛温寒以开饮邪，饮去则咳逆身痛自减。", ["弦", "滑"]], "7496": ["病机", "原文仅言「脉象气口不调」，未指具体脉形，故脉素从缺。气口不调提示肺气失于宣肃，寒热互阻于肺，音塞不扬两年、呛咳而无红，是邪郁肺金、气机不利之象。久延则肺为水之上源，金损及水，故虑「变假为真」，示病机由实转虚之虞。", []], "7497": ["病机", "「脉象左大」主邪热偏盛于左，肝肺气分热郁。前用辛温寒合方音塞开、咳减，然天气温燥呛咳复甚，左大之脉示伏匿之邪虽渐解而未尽，肺气阴液已并损，热象偏张。故治法转为清金养肺，以脉大辨邪热未清、正已受伤。", ["大"]], "7498": ["病机", "「脉沉弦重按少力」，沉主里、弦主饮主寒，重按少力则示肾本空虚。肺有伏寒，感寒涉洋则咳甚气逆，是风寒痰饮有余于上；沉弦少力应下焦肾虚。舌红苔薄白不厚腻，佐证寒饮非湿热。故断为上实下虚，用雷氏上下分治法。", ["沉", "弦", "虚"]], "7499": ["病机", "「脉细濡软」为气血不足、脾肺俱虚之象，细主阴血少，濡软主气虚湿滞。汗出略减而咳不定、甚则呕涎、时凛寒，是久咳不已三焦受之，气海空虚、卫外不固。脉证相合，故进黄耆建中法以温建中气、培土生金。", ["细", "濡", "软"]]});